/* DSE Writing Part B: imported from supplied PDFs. */
window.EDMUND_DSE_WRITING_PART_B_2016_SEED = {"dse/writing/part-b/2016/Q2":[{"front":"opening school gates","meaning":"開放校園","examples":[{"en":"The letter supports opening school gates to the community under clear rules.","zh":"這封信支持在清晰規則下向社區開放校園。"},{"en":"Opening school gates means allowing people outside the school to use certain school spaces.","zh":"開放校園指容許校外人士使用某些學校空間。"},{"en":"Opening school gates after lessons can give residents more places to exercise.","zh":"課後開放校園可以給居民更多地方做運動。"},{"en":"Opening school gates must be managed carefully so students’ safety is not affected.","zh":"開放校園必須小心管理，以免影響學生安全。"},{"en":"This phrase is not only about a physical gate; it also means sharing school resources with the community.","zh":"這個說法不只是指實際校門，也指與社區共享學校資源。"}],"source":"2016 Q2.pdf","sourcePage":1},{"front":"without opening the door to chaos","meaning":"不引發混亂","examples":[{"en":"Schools can open their facilities without opening the door to chaos.","zh":"學校可以開放設施，而不引發混亂。"},{"en":"Without opening the door to chaos means doing something without causing disorder or serious problems.","zh":"“Without opening the door to chaos” 指做某事而不造成失序或嚴重問題。"},{"en":"A library can welcome more visitors without opening the door to chaos if it uses a booking system.","zh":"如果圖書館使用預訂系統，就可以接待更多訪客而不引發混亂。"},{"en":"Clear rules help new schemes grow without opening the door to chaos.","zh":"清晰規則可以幫助新計劃發展，而不引發混亂。"},{"en":"This phrase answers the fear that change will automatically create confusion.","zh":"這個說法回應了改變必然造成混亂的擔憂。"}],"source":"2016 Q2.pdf","sourcePage":1},{"front":"to the Editor","meaning":"致編輯","examples":[{"en":"The letter is addressed to the Editor of Hong Kong Daily.","zh":"這封信是寫給《香港日報》編輯的。"},{"en":"To the Editor is a formal way to address a public letter to a newspaper or magazine editor.","zh":"“To the Editor” 是把公開信正式寫給報章或雜誌編輯的稱呼方式。"},{"en":"A reader may write to the Editor to express an opinion about a social issue.","zh":"讀者可以致編輯寫信，表達對社會議題的意見。"},{"en":"Letters to the Editor are usually written for public discussion, not private conversation.","zh":"致編輯的信通常是為了公開討論，而不是私人對話。"},{"en":"This phrase shows that the writer is joining a wider community debate.","zh":"這個說法顯示作者正在參與更廣泛的社區討論。"}],"source":"2016 Q2.pdf","sourcePage":1},{"front":"Dear Editor","meaning":"編輯先生／女士鈞鑒","examples":[{"en":"Dear Editor, I am writing in response to the suggestion.","zh":"編輯先生／女士鈞鑒：本人寫信回應該建議。"},{"en":"Dear Editor is a formal greeting used at the beginning of a letter to a newspaper editor.","zh":"“Dear Editor” 是寫給報章編輯的信件開首正式稱呼。"},{"en":"Dear Editor, I would like to express my views on public sports facilities.","zh":"編輯先生／女士鈞鑒：本人希望表達對公共體育設施的看法。"},{"en":"This greeting is suitable when the writer does not know the editor’s personal name.","zh":"當作者不知道編輯姓名時，這個稱呼很合適。"},{"en":"Using Dear Editor makes the letter sound formal and public.","zh":"使用 “Dear Editor” 令信件語氣正式而公開。"}],"source":"2016 Q2.pdf","sourcePage":1},{"front":"I am writing in response to","meaning":"本人寫信回應……","examples":[{"en":"I am writing in response to the suggestion about school sports facilities.","zh":"本人寫信回應有關學校體育設施的建議。"},{"en":"I am writing in response to means I am writing because I want to reply to an idea, event, or proposal.","zh":"“I am writing in response to” 指本人寫信是為了回應某個想法、事件或建議。"},{"en":"I am writing in response to your article about youth health.","zh":"本人寫信回應貴報有關青少年健康的文章。"},{"en":"This phrase quickly tells the reader why the letter is being written.","zh":"這個說法很快告訴讀者寫信原因。"},{"en":"It is useful in formal letters that discuss public suggestions or complaints.","zh":"它適合用於討論公共建議或投訴的正式信件。"}],"source":"2016 Q2.pdf","sourcePage":1},{"front":"the suggestion that","meaning":"……的建議","examples":[{"en":"I am writing in response to the suggestion that schools should open their sports facilities.","zh":"本人寫信回應學校應開放體育設施的建議。"},{"en":"The suggestion that introduces an idea someone has proposed for others to consider.","zh":"“The suggestion that” 用來引出別人提出、供大家考慮的想法。"},{"en":"The suggestion that libraries should stay open later has received public support.","zh":"圖書館應延長開放時間的建議得到公眾支持。"},{"en":"A writer may agree or disagree with the suggestion that a new policy should be introduced.","zh":"作者可以同意或不同意應推出新政策的建議。"},{"en":"This phrase is useful when clearly naming the proposal being discussed.","zh":"當需要清楚指出正在討論的建議時，這個說法很有用。"}],"source":"2016 Q2.pdf","sourcePage":1},{"front":"in our community","meaning":"在我們社區","examples":[{"en":"Schools in our community may allow residents to use their facilities.","zh":"在我們社區，學校可以容許居民使用其設施。"},{"en":"In our community means in the local area where people live, study, or work together.","zh":"“In our community” 指在人們一起生活、學習或工作的本地區域。"},{"en":"In our community, many elderly residents need safe places to exercise.","zh":"在我們社區，許多年長居民需要安全地方做運動。"},{"en":"A problem in our community should be discussed by schools, families, and local groups.","zh":"我們社區中的問題應由學校、家庭和本地團體一起討論。"},{"en":"This phrase makes the issue feel close to local people’s daily lives.","zh":"這個說法令議題更貼近本地人的日常生活。"}],"source":"2016 Q2.pdf","sourcePage":1},{"front":"allow members of the public to","meaning":"允許公眾人士……","examples":[{"en":"Schools may allow members of the public to use their sports facilities.","zh":"學校可以允許公眾人士使用其體育設施。"},{"en":"To allow members of the public to do something means to permit ordinary citizens to do it.","zh":"“Allow members of the public to” 指准許普通市民做某事。"},{"en":"The museum allows members of the public to visit free on Wednesdays.","zh":"博物館允許公眾人士逢星期三免費參觀。"},{"en":"Schools can allow members of the public to enter only after registration.","zh":"學校可以只允許已登記的公眾人士進入。"},{"en":"This phrase is useful when discussing public access to shared resources.","zh":"當討論公眾使用共享資源時，這個說法很有用。"}],"source":"2016 Q2.pdf","sourcePage":1},{"front":"members of the public","meaning":"公眾人士","examples":[{"en":"Members of the public may use school sports facilities after school hours.","zh":"公眾人士可以在課後時間使用學校體育設施。"},{"en":"Members of the public are ordinary people in society, not staff, students, or officials in a specific organisation.","zh":"公眾人士是社會中的普通人，而不是某機構的職員、學生或官員。"},{"en":"Members of the public can attend the meeting and give their views.","zh":"公眾人士可以出席會議並發表意見。"},{"en":"If members of the public use school facilities, rules must be clear and fair.","zh":"如果公眾人士使用學校設施，規則必須清晰而公平。"},{"en":"This phrase is formal and often used in policies, letters, and announcements.","zh":"這個說法較正式，常用於政策、信件和公告。"}],"source":"2016 Q2.pdf","sourcePage":1},{"front":"sports facilities","meaning":"體育設施","examples":[{"en":"Schools may open their sports facilities after school hours.","zh":"學校可以在課後時間開放體育設施。"},{"en":"Sports facilities are places or equipment used for exercise, games, and physical training.","zh":"體育設施是用來做運動、比賽和體能訓練的地方或設備。"},{"en":"Sports facilities can include playgrounds, courts, halls, tracks, and fitness areas.","zh":"體育設施可以包括操場、球場、禮堂、跑道和健身區。"},{"en":"Good sports facilities help people exercise safely and regularly.","zh":"良好的體育設施幫助人們安全而定期地做運動。"},{"en":"Opening sports facilities can improve health if they are managed properly.","zh":"如果管理得宜，開放體育設施可以改善健康。"}],"source":"2016 Q2.pdf","sourcePage":1},{"front":"after school hours","meaning":"課後時間","examples":[{"en":"Members of the public may use sports facilities after school hours.","zh":"公眾人士可以在課後時間使用體育設施。"},{"en":"After school hours means during the time after normal lessons and school activities have ended.","zh":"課後時間指正常課堂和學校活動結束後的時間。"},{"en":"The library opens to residents after school hours on Fridays.","zh":"圖書館逢星期五在課後時間向居民開放。"},{"en":"Using facilities after school hours can avoid disturbing students during lessons.","zh":"在課後時間使用設施，可以避免打擾學生上課。"},{"en":"This phrase helps separate student use from community use.","zh":"這個說法有助區分學生使用和社區使用。"}],"source":"2016 Q2.pdf","sourcePage":2},{"front":"public courts","meaning":"公共球場","examples":[{"en":"Public courts are often fully booked.","zh":"公共球場經常預訂已滿。"},{"en":"Public courts are sports courts available for ordinary residents to book or use.","zh":"公共球場是普通居民可以預訂或使用的體育場地。"},{"en":"Public courts may include basketball courts, tennis courts, and badminton courts.","zh":"公共球場可以包括籃球場、網球場和羽毛球場。"},{"en":"When public courts are limited, residents may struggle to exercise regularly.","zh":"當公共球場有限時，居民可能難以定期做運動。"},{"en":"The shortage of public courts explains why school facilities could help the community.","zh":"公共球場不足，正好解釋為何學校設施可以幫助社區。"}],"source":"2016 Q2.pdf","sourcePage":2},{"front":"fully booked","meaning":"預訂已滿","examples":[{"en":"Many public courts are fully booked.","zh":"許多公共球場預訂已滿。"},{"en":"Fully booked means all available times or places have already been reserved.","zh":"“Fully booked” 指所有可用時間或名額都已被預留。"},{"en":"The badminton court was fully booked, so we had to choose another day.","zh":"羽毛球場預訂已滿，所以我們要改選另一天。"},{"en":"If public facilities are fully booked, people may give up exercising.","zh":"如果公共設施預訂已滿，人們可能會放棄做運動。"},{"en":"This phrase shows that demand is higher than available space.","zh":"這個說法顯示需求高於可用空間。"}],"source":"2016 Q2.pdf","sourcePage":2},{"front":"private clubs","meaning":"私人會所","examples":[{"en":"Private clubs are often expensive.","zh":"私人會所通常很昂貴。"},{"en":"Private clubs are membership-based places that offer sports or leisure facilities to paying members.","zh":"私人會所是以會員制度運作，向付費會員提供體育或休閒設施的地方。"},{"en":"Some private clubs have swimming pools, tennis courts, and gyms.","zh":"有些私人會所有游泳池、網球場和健身室。"},{"en":"Private clubs may be too expensive for ordinary families to use regularly.","zh":"私人會所可能太昂貴，普通家庭難以定期使用。"},{"en":"Mentioning private clubs highlights why affordable public options are needed.","zh":"提到私人會所，突顯為何社區需要負擔得起的公共選擇。"}],"source":"2016 Q2.pdf","sourcePage":2},{"front":"open spaces","meaning":"休憩空間；開放空間","examples":[{"en":"Open spaces are shrinking in the city.","zh":"城市中的開放空間正在減少。"},{"en":"Open spaces are outdoor areas where people can rest, walk, play, or exercise.","zh":"開放空間是讓人休息、散步、玩耍或運動的戶外地方。"},{"en":"Parks, playgrounds, and waterfront paths are examples of open spaces.","zh":"公園、遊樂場和海濱長廊都是開放空間的例子。"},{"en":"Open spaces are important because they give crowded communities room to breathe.","zh":"開放空間很重要，因為它給擠迫社區一點呼吸空間。"},{"en":"When open spaces disappear, existing public facilities become even more valuable.","zh":"當開放空間消失，現有公共設施就變得更有價值。"}],"source":"2016 Q2.pdf","sourcePage":2},{"front":"open spaces shrinking","meaning":"開放空間減少","examples":[{"en":"With open spaces shrinking, residents need more places to exercise.","zh":"隨着開放空間減少，居民需要更多地方做運動。"},{"en":"Open spaces shrinking means outdoor public areas are becoming fewer or smaller.","zh":"開放空間減少指戶外公共地方變少或變小。"},{"en":"With open spaces shrinking, children may have fewer places to play after school.","zh":"隨着開放空間減少，孩子放學後可玩耍的地方可能更少。"},{"en":"Open spaces shrinking can make school sports facilities more important to the community.","zh":"開放空間減少可能令學校體育設施對社區更重要。"},{"en":"This phrase explains why better use of existing land is necessary.","zh":"這個說法解釋為何有必要更好地使用現有土地。"}],"source":"2016 Q2.pdf","sourcePage":2},{"front":"find it difficult to","meaning":"覺得難以……","examples":[{"en":"Many residents find it difficult to exercise regularly.","zh":"許多居民覺得難以定期做運動。"},{"en":"To find it difficult to do something means to feel that doing it is hard because of obstacles or limits.","zh":"“Find it difficult to” 指因障礙或限制而覺得做某事很困難。"},{"en":"Students may find it difficult to study at home if the flat is noisy.","zh":"如果家中很嘈吵，學生可能覺得難以在家溫習。"},{"en":"Residents find it difficult to exercise when nearby venues are expensive or unavailable.","zh":"當附近場地昂貴或沒有空位時，居民會覺得難以做運動。"},{"en":"This phrase identifies a practical problem rather than blaming people for not acting.","zh":"這個說法指出實際問題，而不是責怪人們沒有行動。"}],"source":"2016 Q2.pdf","sourcePage":2},{"front":"exercise regularly","meaning":"定期做運動","examples":[{"en":"Many residents find it difficult to exercise regularly.","zh":"許多居民覺得難以定期做運動。"},{"en":"To exercise regularly means to do physical activity often and as part of a routine.","zh":"「定期做運動」指經常並以習慣方式進行體能活動。"},{"en":"Walking for thirty minutes three times a week is one way to exercise regularly.","zh":"每星期散步三次、每次三十分鐘，就是定期做運動的一種方式。"},{"en":"People are more likely to exercise regularly when safe venues are nearby.","zh":"當附近有安全場地，人們較容易定期做運動。"},{"en":"Regular exercise can improve health, mood, and energy.","zh":"定期運動可以改善健康、心情和精神。"}],"source":"2016 Q2.pdf","sourcePage":2},{"front":"this has led some people to ask whether","meaning":"這令一些人提出是否……","examples":[{"en":"This has led some people to ask whether school facilities should remain locked.","zh":"這令一些人提出，學校設施是否應繼續上鎖。"},{"en":"This has led some people to ask whether means the situation has caused people to raise a question.","zh":"“This has led some people to ask whether” 指某情況令一些人提出一個問題。"},{"en":"Rising transport costs have led some people to ask whether more cycle paths are needed.","zh":"交通費上升令一些人提出是否需要更多單車徑。"},{"en":"A shortage of sports space has led residents to ask whether schools can share their facilities.","zh":"體育空間短缺令居民提出學校是否可以共享設施。"},{"en":"This phrase connects a social problem with a public question.","zh":"這個說法把社會問題與公共提問連接起來。"}],"source":"2016 Q2.pdf","sourcePage":2},{"front":"school playgrounds","meaning":"學校操場","examples":[{"en":"School playgrounds could be used by the public after school hours.","zh":"學校操場可以在課後時間供公眾使用。"},{"en":"School playgrounds are outdoor areas in schools where students play, exercise, or hold activities.","zh":"學校操場是學校內讓學生玩耍、運動或舉行活動的戶外地方。"},{"en":"A school playground can be used for running, ball games, and group exercises.","zh":"學校操場可以用來跑步、打球和做集體運動。"},{"en":"Opening school playgrounds after lessons can help residents exercise without building new parks.","zh":"課後開放學校操場，可以幫助居民運動，而不用興建新公園。"},{"en":"Clear rules are needed so school playgrounds remain safe and clean.","zh":"需要清晰規則，讓學校操場保持安全和清潔。"}],"source":"2016 Q2.pdf","sourcePage":2},{"front":"halls and courts","meaning":"禮堂和球場","examples":[{"en":"School halls and courts should not remain locked unnecessarily.","zh":"學校禮堂和球場不應不必要地繼續上鎖。"},{"en":"Halls and courts are indoor activity spaces and sports areas used for events, games, or training.","zh":"禮堂和球場是用於活動、比賽或訓練的室內活動空間和體育場地。"},{"en":"A school hall may host fitness classes, while courts can be used for badminton or basketball.","zh":"學校禮堂可以舉辦健體班，球場則可用於羽毛球或籃球。"},{"en":"If halls and courts stand empty after lessons, the community loses useful space.","zh":"如果禮堂和球場課後空置，社區便失去有用空間。"},{"en":"Opening halls and courts can help different groups exercise in bad weather.","zh":"開放禮堂和球場可以幫助不同群體在天氣欠佳時做運動。"}],"source":"2016 Q2.pdf","sourcePage":3},{"front":"remain locked","meaning":"繼續上鎖","examples":[{"en":"Some people ask whether school facilities should remain locked after the final bell.","zh":"有些人提出，放學鐘聲響起後，學校設施是否應繼續上鎖。"},{"en":"Remain locked means continue to be closed and unavailable for use.","zh":"“Remain locked” 指繼續關閉，不能供人使用。"},{"en":"The community room remained locked even though no one used it at night.","zh":"社區活動室晚上沒有人使用，卻仍然繼續上鎖。"},{"en":"If useful spaces remain locked, public resources cannot serve people fully.","zh":"如果有用空間繼續上鎖，公共資源便不能充分服務市民。"},{"en":"This phrase suggests waste when a facility is closed without a strong reason.","zh":"這個說法暗示設施在沒有充分理由下關閉，是一種浪費。"}],"source":"2016 Q2.pdf","sourcePage":3},{"front":"after the final bell","meaning":"放學鐘聲響起後","examples":[{"en":"School facilities often remain locked after the final bell.","zh":"放學鐘聲響起後，學校設施常常繼續上鎖。"},{"en":"After the final bell means after the school day or lessons have officially ended.","zh":"“After the final bell” 指學校一天或課堂正式結束之後。"},{"en":"After the final bell, students packed their bags and left the classroom.","zh":"放學鐘聲響起後，學生收拾書包離開課室。"},{"en":"Facilities that are empty after the final bell may still be useful to the community.","zh":"放學鐘聲響起後空置的設施，仍可能對社區有用。"},{"en":"This phrase clearly separates normal school time from after-school use.","zh":"這個說法清楚區分正常上課時間和課後使用時間。"}],"source":"2016 Q2.pdf","sourcePage":3},{"front":"as far as I am concerned","meaning":"就我而言","examples":[{"en":"As far as I am concerned, the answer should be a qualified but firm yes.","zh":"就我而言，答案應是有條件但堅定的同意。"},{"en":"As far as I am concerned means in my opinion or from my point of view.","zh":"“As far as I am concerned” 指以我的看法或從我的角度而言。"},{"en":"As far as I am concerned, public space should be used more fairly.","zh":"就我而言，公共空間應被更公平地使用。"},{"en":"This phrase is useful when a writer wants to state a personal position clearly.","zh":"當作者想清楚表明個人立場時，這個說法很有用。"},{"en":"It sounds slightly formal and is suitable for opinion letters.","zh":"它語氣略正式，適合用於意見信。"}],"source":"2016 Q2.pdf","sourcePage":3},{"front":"a qualified but firm yes","meaning":"有條件但堅定的同意","examples":[{"en":"The answer should be a qualified but firm yes.","zh":"答案應是有條件但堅定的同意。"},{"en":"A qualified but firm yes means clear agreement, but only under certain conditions.","zh":"“A qualified but firm yes” 指清楚同意，但只在某些條件下同意。"},{"en":"I give a qualified but firm yes to opening the library at night if safety rules are added.","zh":"如果加入安全規則，我會對晚上開放圖書館給予有條件但堅定的同意。"},{"en":"This phrase shows support while still recognising risks and limits.","zh":"這個說法顯示支持，同時承認風險和限制。"},{"en":"It is useful when the writer agrees with a proposal but does not support it blindly.","zh":"當作者同意建議但不是盲目支持時，這個說法很有用。"}],"source":"2016 Q2.pdf","sourcePage":3},{"front":"provided that","meaning":"只要；前提是","examples":[{"en":"Provided that access is properly regulated, school facilities can be opened safely.","zh":"只要使用權受到妥善規管，學校設施便可以安全開放。"},{"en":"Provided that means if, or only on the condition that something happens.","zh":"“Provided that” 指如果，或只在某條件成立的情況下。"},{"en":"Residents may use the hall provided that they register in advance.","zh":"只要居民預先登記，便可以使用禮堂。"},{"en":"A school can share its facilities provided that student safety remains the first priority.","zh":"只要學生安全仍然是首要考慮，學校便可以共享設施。"},{"en":"This phrase introduces a condition that must be satisfied.","zh":"這個說法引出必須滿足的條件。"}],"source":"2016 Q2.pdf","sourcePage":3},{"front":"access is properly regulated","meaning":"使用權受到妥善規管","examples":[{"en":"Opening facilities is acceptable if access is properly regulated.","zh":"如果使用權受到妥善規管，開放設施是可以接受的。"},{"en":"Access is properly regulated means entry and use are controlled by clear rules and supervision.","zh":"“Access is properly regulated” 指進入和使用受到清晰規則及監管控制。"},{"en":"A gym is safer when access is properly regulated through booking and identity checks.","zh":"如果健身室透過預訂和身份核查妥善規管使用權，便會更安全。"},{"en":"If access is properly regulated, schools can reduce risks such as overcrowding and damage.","zh":"如果使用權受到妥善規管，學校可以減少人流過多和財物損毀等風險。"},{"en":"This phrase shows that opening facilities does not mean allowing anyone to enter freely.","zh":"這個說法顯示開放設施不等於容許任何人自由進入。"}],"source":"2016 Q2.pdf","sourcePage":3},{"front":"make wiser use of","meaning":"更明智地運用","examples":[{"en":"Opening school facilities would make wiser use of scarce resources.","zh":"開放學校設施會更明智地運用稀缺資源。"},{"en":"To make wiser use of something means to use it more sensibly and effectively.","zh":"「更明智地運用」指更合理和有效地使用某事物。"},{"en":"A family can make wiser use of money by planning meals before shopping.","zh":"家庭可以在購物前計劃膳食，從而更明智地運用金錢。"},{"en":"A city makes wiser use of land when empty facilities serve more people.","zh":"當空置設施服務更多人時，城市就是更明智地運用土地。"},{"en":"This phrase suggests improvement without necessarily building anything new.","zh":"這個說法暗示改善不一定要興建新東西。"}],"source":"2016 Q2.pdf","sourcePage":3},{"front":"scarce resources","meaning":"稀缺資源","examples":[{"en":"Hong Kong should make wiser use of scarce resources.","zh":"香港應更明智地運用稀缺資源。"},{"en":"Scarce resources are useful things that are limited and not enough for everyone’s needs.","zh":"稀缺資源是有限、未必足夠滿足所有人需要的有用事物。"},{"en":"Land, money, time, and public facilities can all be scarce resources.","zh":"土地、金錢、時間和公共設施都可以是稀缺資源。"},{"en":"When resources are scarce, leaving usable spaces empty becomes wasteful.","zh":"當資源稀缺時，讓可用空間空置便是一種浪費。"},{"en":"This phrase explains why efficient sharing is important in a crowded city.","zh":"這個說法解釋為何在擠迫城市中有效共享很重要。"}],"source":"2016 Q2.pdf","sourcePage":3},{"front":"improve community health","meaning":"改善社區健康","examples":[{"en":"Opening sports facilities would improve community health.","zh":"開放體育設施會改善社區健康。"},{"en":"To improve community health means to make people in a local area healthier as a group.","zh":"「改善社區健康」指令某地區的人整體上更健康。"},{"en":"Free exercise classes can improve community health by helping residents stay active.","zh":"免費運動班可以幫助居民保持活躍，從而改善社區健康。"},{"en":"More sports space may improve community health because people can exercise more often.","zh":"更多體育空間可能改善社區健康，因為人們可以更常做運動。"},{"en":"This phrase connects public facilities with the well-being of the whole neighbourhood.","zh":"這個說法把公共設施與整個社區的福祉連接起來。"}],"source":"2016 Q2.pdf","sourcePage":3},{"front":"strengthen trust between","meaning":"加強……之間的信任","examples":[{"en":"The scheme could strengthen trust between schools and residents.","zh":"這項計劃可以加強學校和居民之間的信任。"},{"en":"To strengthen trust between two groups means to make them believe in and cooperate with each other more.","zh":"「加強兩者之間的信任」指令兩個群體更相信彼此並更願意合作。"},{"en":"Regular meetings can strengthen trust between parents and teachers.","zh":"定期會議可以加強家長和老師之間的信任。"},{"en":"Sharing facilities responsibly can strengthen trust between schools and nearby residents.","zh":"負責任地共享設施可以加強學校和附近居民之間的信任。"},{"en":"This phrase shows that the plan may improve relationships, not only provide space.","zh":"這個說法顯示計劃不只提供空間，也可能改善關係。"}],"source":"2016 Q2.pdf","sourcePage":4},{"front":"schools and residents","meaning":"學校和居民","examples":[{"en":"Opening facilities could strengthen trust between schools and residents.","zh":"開放設施可以加強學校和居民之間的信任。"},{"en":"Schools and residents refers to educational institutions and the people living nearby.","zh":"學校和居民指教育機構及附近居住的人。"},{"en":"Schools and residents both benefit when sports spaces are shared safely.","zh":"當體育空間被安全共享時，學校和居民都可受益。"},{"en":"Clear communication between schools and residents can prevent misunderstandings about noise or security.","zh":"學校和居民之間清楚溝通，可以避免有關噪音或保安的誤會。"},{"en":"This phrase highlights the relationship between institutions and the local community.","zh":"這個說法突顯機構與本地社區之間的關係。"}],"source":"2016 Q2.pdf","sourcePage":4},{"front":"the first reason is that","meaning":"第一個原因是","examples":[{"en":"The first reason is that Hong Kong cannot afford to leave useful facilities idle.","zh":"第一個原因是香港不能讓有用的設施閒置。"},{"en":"The first reason is that introduces the first main explanation supporting an argument.","zh":"“The first reason is that” 用來引出支持論點的第一個主要理由。"},{"en":"The first reason is that the park is too small for the growing population.","zh":"第一個原因是公園對不斷增長的人口來說太小。"},{"en":"This phrase helps organise an essay by giving readers a clear structure.","zh":"這個說法透過清楚結構幫助組織文章。"},{"en":"It is often followed by evidence, examples, or explanation.","zh":"它後面通常接證據、例子或解釋。"}],"source":"2016 Q2.pdf","sourcePage":4},{"front":"cannot afford to","meaning":"承受不起；不能夠","examples":[{"en":"Hong Kong cannot afford to leave useful sports facilities idle.","zh":"香港承受不起讓有用體育設施閒置。"},{"en":"Cannot afford to means cannot accept or risk something because the cost or damage would be too high.","zh":"“Cannot afford to” 指因成本或損害太高而不能接受或冒某種風險。"},{"en":"A small business cannot afford to waste money on unused equipment.","zh":"小企業承受不起把金錢浪費在不用的設備上。"},{"en":"A crowded city cannot afford to leave safe sports spaces unused.","zh":"擠迫城市不能讓安全的體育空間閒置。"},{"en":"This phrase shows that inaction also has a cost.","zh":"這個說法顯示不行動也有代價。"}],"source":"2016 Q2.pdf","sourcePage":4},{"front":"leave facilities idle","meaning":"讓設施閒置","examples":[{"en":"The city should not leave useful sports facilities idle.","zh":"城市不應讓有用的體育設施閒置。"},{"en":"To leave facilities idle means to keep usable spaces or equipment unused.","zh":"「讓設施閒置」指使可用空間或設備處於沒有使用的狀態。"},{"en":"It is wasteful to leave a community hall idle every evening.","zh":"每晚讓社區禮堂閒置是一種浪費。"},{"en":"Facilities left idle cannot help residents even if they are well built.","zh":"即使設施建得很好，如果被閒置，也不能幫助居民。"},{"en":"This phrase criticises poor use of resources.","zh":"這個說法批評資源使用不善。"}],"source":"2016 Q2.pdf","sourcePage":4},{"front":"land is so limited","meaning":"土地非常有限","examples":[{"en":"Hong Kong should use existing facilities because land is so limited.","zh":"香港應使用現有設施，因為土地非常有限。"},{"en":"Land is so limited means there is very little available space for new buildings or public areas.","zh":"“Land is so limited” 指可用於新建築或公共地方的空間很少。"},{"en":"When land is so limited, building every new facility from nothing is difficult.","zh":"當土地非常有限時，每項新設施都從零開始興建很困難。"},{"en":"Limited land makes it sensible to share spaces that already exist.","zh":"土地有限令共享現有空間變得合理。"},{"en":"This phrase explains why efficient use of school facilities matters.","zh":"這個說法解釋為何有效使用學校設施很重要。"}],"source":"2016 Q2.pdf","sourcePage":4},{"front":"building a new sports centre","meaning":"興建新的體育中心","examples":[{"en":"Building a new sports centre may require years of planning.","zh":"興建新的體育中心可能需要多年規劃。"},{"en":"Building a new sports centre means constructing a new public or private place for exercise and games.","zh":"興建新的體育中心指建造一個新的公共或私人運動場地。"},{"en":"Building a new sports centre can be expensive because land, design, and construction all cost money.","zh":"興建新的體育中心可能很昂貴，因為土地、設計和建設都需要金錢。"},{"en":"If a community needs space now, building a new sports centre may be too slow.","zh":"如果社區現在就需要空間，興建新的體育中心可能太慢。"},{"en":"This phrase contrasts a long-term solution with using existing facilities.","zh":"這個說法把長遠方案與使用現有設施作對比。"}],"source":"2016 Q2.pdf","sourcePage":4},{"front":"require years of","meaning":"需要多年……","examples":[{"en":"Building a new sports centre may require years of planning and construction.","zh":"興建新的體育中心可能需要多年規劃和建設。"},{"en":"Require years of means need a very long period of time for a process to finish.","zh":"“Require years of” 指一個過程需要很長時間才能完成。"},{"en":"Restoring an old building may require years of careful work.","zh":"修復舊建築可能需要多年仔細工作。"},{"en":"Projects that require years of planning cannot solve urgent problems immediately.","zh":"需要多年規劃的項目不能即時解決緊急問題。"},{"en":"This phrase emphasises that some solutions are slow.","zh":"這個說法強調有些解決方案需時很長。"}],"source":"2016 Q2.pdf","sourcePage":4},{"front":"planning and construction","meaning":"規劃和建設","examples":[{"en":"New sports centres require planning and construction.","zh":"新體育中心需要規劃和建設。"},{"en":"Planning and construction are the stages of designing, approving, and building something.","zh":"規劃和建設是設計、審批和興建某物的階段。"},{"en":"A new library needs planning and construction before residents can use it.","zh":"新圖書館需要經過規劃和建設，居民才能使用。"},{"en":"Planning and construction can take years if land and funding are difficult to secure.","zh":"如果土地和資金難以取得，規劃和建設可能需要多年。"},{"en":"This phrase explains why using existing facilities may be faster.","zh":"這個說法解釋為何使用現有設施可能更快。"}],"source":"2016 Q2.pdf","sourcePage":4},{"front":"whereas","meaning":"然而","examples":[{"en":"Building new facilities is slow, whereas using existing ones could help immediately.","zh":"興建新設施很慢，然而使用現有設施可以即時幫助社區。"},{"en":"Whereas is used to contrast two different facts or situations.","zh":"“Whereas” 用來對比兩個不同事實或情況。"},{"en":"Private clubs are expensive, whereas school facilities already exist in many neighbourhoods.","zh":"私人會所很昂貴，然而許多社區已有學校設施。"},{"en":"New construction may take years, whereas sharing existing spaces can begin sooner.","zh":"新建設可能需時多年，然而共享現有空間可以更早開始。"},{"en":"This word helps make comparison clear in formal writing.","zh":"這個詞有助在正式寫作中清楚作比較。"}],"source":"2016 Q2.pdf","sourcePage":4},{"front":"existing school facilities","meaning":"現有學校設施","examples":[{"en":"Existing school facilities could increase community capacity quickly.","zh":"現有學校設施可以快速增加社區容量。"},{"en":"Existing school facilities are school spaces and equipment that are already built and available.","zh":"現有學校設施是已建成並可使用的學校空間和設備。"},{"en":"Existing school facilities may include playgrounds, halls, courts, and fitness rooms.","zh":"現有學校設施可以包括操場、禮堂、球場和健身室。"},{"en":"Using existing school facilities can save time because no new land is needed.","zh":"使用現有學校設施可以節省時間，因為不需要新土地。"},{"en":"This phrase supports the idea of making better use of what the community already has.","zh":"這個說法支持更好地利用社區已有資源的想法。"}],"source":"2016 Q2.pdf","sourcePage":5},{"front":"after lessons","meaning":"課後","examples":[{"en":"Existing school facilities could be used after lessons.","zh":"現有學校設施可以在課後使用。"},{"en":"After lessons means after classes have finished for the day.","zh":"“After lessons” 指一天課堂結束之後。"},{"en":"Students often join clubs after lessons before going home.","zh":"學生常在課後參加學會才回家。"},{"en":"Facilities used after lessons can serve residents without interrupting teaching.","zh":"課後使用設施可以服務居民，而不打擾教學。"},{"en":"This phrase helps show when public access might be suitable.","zh":"這個說法有助顯示公眾使用的合適時間。"}],"source":"2016 Q2.pdf","sourcePage":5},{"front":"increase community capacity","meaning":"增加社區容量","examples":[{"en":"Opening school facilities could increase community capacity almost immediately.","zh":"開放學校設施可以幾乎即時增加社區容量。"},{"en":"To increase community capacity means to give the community more usable space, services, or ability to meet people’s needs.","zh":"「增加社區容量」指給社區更多可用空間、服務或能力去滿足居民需要。"},{"en":"Opening a school hall at night can increase community capacity for exercise classes.","zh":"晚上開放學校禮堂可以增加社區舉辦健體班的容量。"},{"en":"Community capacity increases when existing spaces serve more people safely.","zh":"當現有空間安全地服務更多人時，社區容量便會增加。"},{"en":"This phrase shows the practical benefit of sharing facilities.","zh":"這個說法顯示共享設施的實際好處。"}],"source":"2016 Q2.pdf","sourcePage":5},{"front":"almost immediately","meaning":"幾乎即時","examples":[{"en":"The scheme could increase community capacity almost immediately.","zh":"這項計劃可以幾乎即時增加社區容量。"},{"en":"Almost immediately means very soon, with little delay.","zh":"“Almost immediately” 指很快，幾乎沒有延誤。"},{"en":"If the hall is already available, evening classes could begin almost immediately.","zh":"如果禮堂已經可用，晚間課程幾乎可以即時開始。"},{"en":"Using existing facilities helps almost immediately because construction is not needed.","zh":"使用現有設施幾乎可以即時提供幫助，因為不需要建設。"},{"en":"This phrase stresses speed and practical usefulness.","zh":"這個說法強調速度和實際作用。"}],"source":"2016 Q2.pdf","sourcePage":5},{"front":"covered playgrounds","meaning":"有蓋操場","examples":[{"en":"Many schools already have covered playgrounds.","zh":"許多學校已有有蓋操場。"},{"en":"Covered playgrounds are playgrounds with a roof or shelter above them.","zh":"有蓋操場是上方有屋頂或遮蔽的操場。"},{"en":"Covered playgrounds allow students to exercise even when it rains.","zh":"有蓋操場讓學生即使下雨也能做運動。"},{"en":"Covered playgrounds could also serve residents in the evening if managed well.","zh":"如果管理得宜，有蓋操場晚上也可以服務居民。"},{"en":"This phrase highlights a useful school space that already exists.","zh":"這個說法突顯一個已經存在的有用學校空間。"}],"source":"2016 Q2.pdf","sourcePage":5},{"front":"badminton halls","meaning":"羽毛球場館","examples":[{"en":"Some schools have badminton halls and small fitness areas.","zh":"有些學校有羽毛球場館和小型健身區。"},{"en":"Badminton halls are indoor spaces designed or used for playing badminton.","zh":"羽毛球場館是設計或用作打羽毛球的室內空間。"},{"en":"A badminton hall usually has court lines, enough height, and proper lighting.","zh":"羽毛球場館通常有場線、足夠高度和合適照明。"},{"en":"Badminton halls can serve many players because games are organised in short sessions.","zh":"羽毛球場館可以服務許多運動人士，因為比賽可按短時段安排。"},{"en":"Opening badminton halls after school could help residents exercise affordably.","zh":"課後開放羽毛球場館可以幫助居民以可負擔方式運動。"}],"source":"2016 Q2.pdf","sourcePage":5},{"front":"fitness areas","meaning":"健身區","examples":[{"en":"Schools may have small fitness areas.","zh":"學校可能設有小型健身區。"},{"en":"Fitness areas are spaces with equipment or room for exercise and physical training.","zh":"健身區是有器材或空間供人運動和體能訓練的地方。"},{"en":"A fitness area may include mats, simple machines, or space for stretching.","zh":"健身區可能包括墊子、簡單器械或伸展空間。"},{"en":"Fitness areas can help residents build strength and stay active.","zh":"健身區可以幫助居民鍛鍊力量和保持活躍。"},{"en":"Small fitness areas are useful even when a school does not have a full gym.","zh":"即使學校沒有完整健身室，小型健身區也很有用。"}],"source":"2016 Q2.pdf","sourcePage":5},{"front":"once students have gone home","meaning":"學生回家後","examples":[{"en":"Once students have gone home, some sports facilities serve no one.","zh":"學生回家後，有些體育設施沒有服務任何人。"},{"en":"Once students have gone home means after students have left school for the day.","zh":"“Once students have gone home” 指學生一天放學離校之後。"},{"en":"Once students have gone home, the playground may be empty for several hours.","zh":"學生回家後，操場可能會空置數小時。"},{"en":"Facilities can be shared more easily once students have gone home because lessons are over.","zh":"學生回家後，設施較容易被共享，因為課堂已結束。"},{"en":"This phrase identifies a time when community use may be possible.","zh":"這個說法指出社區使用可能合適的時間。"}],"source":"2016 Q2.pdf","sourcePage":5},{"front":"serve no one","meaning":"沒有服務任何人","examples":[{"en":"These spaces often serve no one after school activities end.","zh":"這些空間在學校活動結束後常常沒有服務任何人。"},{"en":"Serve no one means help or benefit nobody.","zh":"“Serve no one” 指沒有幫助或惠及任何人。"},{"en":"A locked community room serves no one if it stays empty every night.","zh":"如果社區活動室每晚空置又上鎖，它就沒有服務任何人。"},{"en":"A useful facility serves no one when it is closed at the time people need it most.","zh":"當有用設施在人們最需要時關閉，它便沒有服務任何人。"},{"en":"This phrase stresses the waste of unused resources.","zh":"這個說法強調未被使用資源的浪費。"}],"source":"2016 Q2.pdf","sourcePage":5},{"front":"stand empty","meaning":"空置","examples":[{"en":"A school basketball court may stand empty from 6 p.m. to 9 p.m.","zh":"學校籃球場可能由晚上六時至九時空置。"},{"en":"To stand empty means to remain unused and without people in it.","zh":"“Stand empty” 指保持無人使用和沒有人的狀態。"},{"en":"The hall stood empty after the meeting ended.","zh":"會議結束後，禮堂空置着。"},{"en":"A sports court that stands empty every evening could serve residents instead.","zh":"每晚空置的球場其實可以服務居民。"},{"en":"This phrase makes wasted space easy to imagine.","zh":"這個說法令被浪費的空間容易想像。"}],"source":"2016 Q2.pdf","sourcePage":5},{"front":"accommodate","meaning":"容納","examples":[{"en":"An empty basketball court could accommodate several one-hour sessions.","zh":"一個空置籃球場可以容納幾個一小時時段。"},{"en":"To accommodate means to provide enough space, time, or support for people or activities.","zh":"“Accommodate” 指提供足夠空間、時間或支援給人或活動。"},{"en":"The classroom can accommodate thirty students comfortably.","zh":"這間課室可以舒適地容納三十名學生。"},{"en":"One hall can accommodate several exercise groups if the timetable is organised well.","zh":"如果時間表安排得好，一個禮堂可以容納幾個運動小組。"},{"en":"This word shows how a space can be used to meet demand.","zh":"這個詞顯示空間如何用來滿足需求。"}],"source":"2016 Q2.pdf","sourcePage":6},{"front":"one-hour sessions","meaning":"一小時時段","examples":[{"en":"The court could accommodate several one-hour sessions.","zh":"球場可以容納幾個一小時時段。"},{"en":"One-hour sessions are periods of activity that each last for one hour.","zh":"一小時時段是每段持續一小時的活動時間。"},{"en":"The gym offers one-hour sessions for basketball practice every evening.","zh":"健身室每晚提供一小時籃球練習時段。"},{"en":"Dividing time into one-hour sessions helps different groups share the same facility fairly.","zh":"把時間分成一小時時段，有助不同群體公平共享同一設施。"},{"en":"This phrase is useful when planning bookings and timetables.","zh":"當規劃預訂和時間表時，這個說法很有用。"}],"source":"2016 Q2.pdf","sourcePage":6},{"front":"elderly residents","meaning":"年長居民","examples":[{"en":"The facilities could serve teenagers, office workers, and elderly residents.","zh":"這些設施可以服務青少年、上班族和年長居民。"},{"en":"Elderly residents are older people who live in a particular community or neighbourhood.","zh":"年長居民是住在某個社區或鄰里的年紀較大人士。"},{"en":"Elderly residents may need safe and nearby places for gentle exercise.","zh":"年長居民可能需要安全而鄰近的地方做溫和運動。"},{"en":"Opening school facilities can help elderly residents stay active without travelling far.","zh":"開放學校設施可以幫助年長居民不用遠行也能保持活躍。"},{"en":"This phrase reminds readers that sports space is useful for older people, not only young athletes.","zh":"這個說法提醒讀者，體育空間不只對年輕運動員有用，也對長者有用。"}],"source":"2016 Q2.pdf","sourcePage":6},{"front":"not a matter of","meaning":"並不是……的問題","examples":[{"en":"This is not a matter of taking something away from students.","zh":"這並不是從學生手中拿走某物的問題。"},{"en":"Not a matter of means the issue should not be understood in that way.","zh":"“Not a matter of” 指這個問題不應以那種方式理解。"},{"en":"Opening the library at night is not a matter of disturbing classes if it happens after lessons.","zh":"如果圖書館在課後開放，晚上開放圖書館並不是打擾課堂的問題。"},{"en":"This phrase rejects a mistaken way of framing the problem.","zh":"這個說法否定對問題的錯誤理解方式。"},{"en":"It helps the writer explain what the issue is really about.","zh":"它幫助作者解釋真正問題所在。"}],"source":"2016 Q2.pdf","sourcePage":6},{"front":"take something away from","meaning":"從……手中拿走某物","examples":[{"en":"Opening facilities is not taking something away from students.","zh":"開放設施並不是從學生手中拿走東西。"},{"en":"To take something away from someone means to remove something they have or reduce their access to it.","zh":"“Take something away from someone” 指取走某人擁有的東西，或減少他們使用它的機會。"},{"en":"Sharing the hall at night does not take it away from students during school hours.","zh":"晚上共享禮堂，並不會在上課時間從學生手中拿走它。"},{"en":"People may oppose sharing if they think it takes something away from the original users.","zh":"如果人們認為共享會從原有使用者手中拿走東西，便可能反對共享。"},{"en":"This phrase is useful when explaining that shared use need not create loss.","zh":"當解釋共享使用不一定造成損失時，這個說法很有用。"}],"source":"2016 Q2.pdf","sourcePage":6},{"front":"a matter of","meaning":"是……的問題","examples":[{"en":"It is a matter of allowing public resources to serve the public.","zh":"這是讓公共資源服務公眾的問題。"},{"en":"A matter of means an issue or question concerning a particular thing.","zh":"“A matter of” 指關於某件事的問題或議題。"},{"en":"Recycling is a matter of using resources responsibly.","zh":"回收是負責任地使用資源的問題。"},{"en":"Opening empty facilities is a matter of fairness when many residents need sports space.","zh":"當許多居民需要體育空間時，開放空置設施就是公平的問題。"},{"en":"This phrase helps define what the real issue is.","zh":"這個說法幫助界定真正議題。"}],"source":"2016 Q2.pdf","sourcePage":6},{"front":"public resources","meaning":"公共資源","examples":[{"en":"School facilities are public resources that should be used wisely.","zh":"學校設施是應被明智使用的公共資源。"},{"en":"Public resources are things funded, owned, or supported for the benefit of society.","zh":"公共資源是由社會資助、擁有或支持，並用來惠及公眾的事物。"},{"en":"Parks, libraries, roads, and public sports centres are public resources.","zh":"公園、圖書館、道路和公共體育中心都是公共資源。"},{"en":"Public resources should not be wasted when people have genuine needs.","zh":"當人們有真正需要時，公共資源不應被浪費。"},{"en":"This phrase supports the argument that school facilities can serve more than one group.","zh":"這個說法支持學校設施可以服務多於一個群體的論點。"}],"source":"2016 Q2.pdf","sourcePage":6},{"front":"serve the public more fully","meaning":"更充分地服務公眾","examples":[{"en":"Public resources should serve the public more fully.","zh":"公共資源應更充分地服務公眾。"},{"en":"To serve the public more fully means to benefit more people and meet public needs better.","zh":"「更充分地服務公眾」指惠及更多人，並更好地滿足公眾需要。"},{"en":"A community hall serves the public more fully when it is open for both students and residents.","zh":"當社區禮堂同時向學生和居民開放時，它便更充分地服務公眾。"},{"en":"Facilities serve the public more fully when empty hours are used responsibly.","zh":"當空置時段被負責任地使用，設施便能更充分地服務公眾。"},{"en":"This phrase argues for better use, not careless use.","zh":"這個說法主張更好地使用，而不是草率地使用。"}],"source":"2016 Q2.pdf","sourcePage":6},{"front":"in a crowded city","meaning":"在擠迫的城市中","examples":[{"en":"In a crowded city, such efficiency is common sense.","zh":"在擠迫的城市中，這種效率是常識。"},{"en":"In a crowded city means in a place where many people live in limited space.","zh":"“In a crowded city” 指在許多人住於有限空間的地方。"},{"en":"In a crowded city, parks, schools, and community halls must be used carefully.","zh":"在擠迫的城市中，公園、學校和社區禮堂都必須被小心使用。"},{"en":"Space is valuable in a crowded city because many needs compete for the same land.","zh":"在擠迫的城市中，空間很珍貴，因為許多需要都爭用同一片土地。"},{"en":"This phrase explains why sharing facilities is especially reasonable in Hong Kong.","zh":"這個說法解釋為何在香港共享設施尤其合理。"}],"source":"2016 Q2.pdf","sourcePage":6},{"front":"such efficiency","meaning":"這種效率","examples":[{"en":"Such efficiency is not optional in Hong Kong.","zh":"這種效率在香港不是可有可無。"},{"en":"Such efficiency means this kind of careful and productive use of resources.","zh":"“Such efficiency” 指這種小心而有效地使用資源的方式。"},{"en":"Using empty classrooms for evening courses is one example of such efficiency.","zh":"用空置課室舉辦晚間課程，就是這種效率的一個例子。"},{"en":"Such efficiency matters when land is scarce and demand is high.","zh":"當土地稀缺而需求很高時，這種效率很重要。"},{"en":"This phrase refers back to a practical way of using space wisely.","zh":"這個說法回指一種明智使用空間的實際方法。"}],"source":"2016 Q2.pdf","sourcePage":6},{"front":"not optional","meaning":"不是可有可無","examples":[{"en":"Efficient use of land is not optional.","zh":"有效使用土地不是可有可無。"},{"en":"Not optional means necessary, not something that can simply be ignored or chosen freely.","zh":"“Not optional” 指有必要，不是可以隨便忽略或自由選擇的事。"},{"en":"Wearing a helmet is not optional during cycling lessons.","zh":"上單車課時，戴頭盔不是可有可無。"},{"en":"In a crowded city, careful use of public space is not optional.","zh":"在擠迫城市中，小心使用公共空間不是可有可無。"},{"en":"This phrase shows that the issue is urgent and necessary.","zh":"這個說法顯示議題緊急而必要。"}],"source":"2016 Q2.pdf","sourcePage":7},{"front":"common sense","meaning":"常識","examples":[{"en":"Using empty facilities wisely is common sense.","zh":"明智使用空置設施是常識。"},{"en":"Common sense is practical judgement that most reasonable people can understand.","zh":"常識是大多數合理的人都能理解的實際判斷。"},{"en":"Locking unused sports courts while residents need exercise space does not seem like common sense.","zh":"居民需要運動空間時仍鎖上不用的球場，並不像常識。"},{"en":"Common sense suggests that useful resources should not be wasted.","zh":"常識告訴我們，有用資源不應被浪費。"},{"en":"This phrase makes an argument sound practical and reasonable.","zh":"這個說法令論點聽起來實際而合理。"}],"source":"2016 Q2.pdf","sourcePage":7},{"front":"wider access to","meaning":"更廣泛使用……的機會","examples":[{"en":"Wider access to sports facilities would promote healthier communities.","zh":"更廣泛使用體育設施的機會會促進更健康的社區。"},{"en":"Wider access to something means more people have the chance to use or benefit from it.","zh":"“Wider access to” 指更多人有機會使用或受惠於某事物。"},{"en":"Wider access to libraries can help children from different backgrounds read more.","zh":"更廣泛使用圖書館的機會，可以幫助不同背景的孩子閱讀更多。"},{"en":"Wider access to sports facilities can reduce unfairness between rich and poor residents.","zh":"更廣泛使用體育設施的機會，可以減少富裕與基層居民之間的不公平。"},{"en":"This phrase supports equality by focusing on opportunity.","zh":"這個說法透過關注機會來支持平等。"}],"source":"2016 Q2.pdf","sourcePage":7},{"front":"promote healthier communities","meaning":"促進更健康的社區","examples":[{"en":"Wider access to sports facilities would promote healthier communities.","zh":"更廣泛使用體育設施的機會會促進更健康的社區。"},{"en":"To promote healthier communities means to encourage habits and conditions that improve people’s health in a local area.","zh":"「促進更健康的社區」指鼓勵能改善本地居民健康的習慣和條件。"},{"en":"Safe parks and affordable classes can promote healthier communities.","zh":"安全公園和可負擔課程可以促進更健康的社區。"},{"en":"Regular exercise spaces promote healthier communities because residents can build better routines.","zh":"固定運動空間能促進更健康的社區，因為居民可以建立更好習慣。"},{"en":"This phrase connects policy with real improvement in daily life.","zh":"這個說法把政策與日常生活中的實際改善連接起來。"}],"source":"2016 Q2.pdf","sourcePage":7},{"front":"more connected communities","meaning":"聯繫更緊密的社區","examples":[{"en":"Sports facilities can help build more connected communities.","zh":"體育設施可以幫助建立聯繫更緊密的社區。"},{"en":"More connected communities are neighbourhoods where people meet, know, and support one another more.","zh":"聯繫更緊密的社區，是居民更常見面、認識和支持彼此的社區。"},{"en":"Community sports classes can build more connected communities by bringing neighbours together.","zh":"社區運動班可以把鄰居聚在一起，建立聯繫更緊密的社區。"},{"en":"When people share local facilities, they may become more familiar with one another.","zh":"當人們共享本地設施，他們可能會更熟悉彼此。"},{"en":"This phrase shows that sports can improve relationships, not only bodies.","zh":"這個說法顯示運動不只改善身體，也改善關係。"}],"source":"2016 Q2.pdf","sourcePage":7},{"front":"winning matches","meaning":"贏得比賽","examples":[{"en":"Exercise is not just about winning matches.","zh":"運動不只是關於贏得比賽。"},{"en":"Winning matches means defeating opponents in sports games or competitions.","zh":"“Winning matches” 指在體育比賽或競賽中擊敗對手。"},{"en":"A basketball team may enjoy practice even when it is not winning matches.","zh":"籃球隊即使沒有贏得比賽，也可能享受練習。"},{"en":"If exercise focuses only on winning matches, beginners may feel discouraged.","zh":"如果運動只專注贏得比賽，初學者可能會感到灰心。"},{"en":"This phrase helps show that sport also builds health, habits, and friendship.","zh":"這個說法有助顯示運動也能建立健康、習慣和友誼。"}],"source":"2016 Q2.pdf","sourcePage":7},{"front":"building habits","meaning":"建立習慣","examples":[{"en":"Exercise is about building habits and relieving stress.","zh":"運動是關於建立習慣和紓緩壓力。"},{"en":"Building habits means forming repeated actions that become part of daily life.","zh":"「建立習慣」指形成重複行動，使它成為日常生活的一部分。"},{"en":"Walking after dinner every day is a way of building healthy habits.","zh":"每晚飯後散步是一種建立健康習慣的方法。"},{"en":"Sports facilities nearby help residents build habits because exercise becomes easier to repeat.","zh":"附近有體育設施能幫助居民建立習慣，因為運動更容易重複進行。"},{"en":"This phrase shows that long-term health depends on repeated practice.","zh":"這個說法顯示長遠健康取決於重複實踐。"}],"source":"2016 Q2.pdf","sourcePage":7},{"front":"relieving stress","meaning":"紓緩壓力","examples":[{"en":"Exercise can help people relieve stress.","zh":"運動可以幫助人紓緩壓力。"},{"en":"Relieving stress means reducing worry, pressure, or tension.","zh":"「紓緩壓力」指減少憂慮、壓迫感或緊張。"},{"en":"Playing badminton after work can help office workers relieve stress.","zh":"下班後打羽毛球可以幫助上班族紓緩壓力。"},{"en":"If residents have nowhere to exercise, they may lose a healthy way of relieving stress.","zh":"如果居民沒有地方做運動，便可能失去一種健康的紓緩壓力方式。"},{"en":"This phrase shows the mental-health value of sports facilities.","zh":"這個說法顯示體育設施對心理健康的價值。"}],"source":"2016 Q2.pdf","sourcePage":7},{"front":"a constructive way to","meaning":"一種有建設性的方式去……","examples":[{"en":"Sports give people a constructive way to spend their evenings.","zh":"運動給人一種有建設性的方式去度過晚上。"},{"en":"A constructive way to do something is a positive and useful method of doing it.","zh":"“A constructive way to” 指以正面而有用的方法去做某事。"},{"en":"Volunteering gives teenagers a constructive way to use their free time.","zh":"做義工給青少年一種有建設性的方式去運用空閒時間。"},{"en":"Sports offer a constructive way to release energy instead of wandering aimlessly.","zh":"運動提供一種有建設性的方式去釋放精力，而不是漫無目的地閒逛。"},{"en":"This phrase highlights a healthy alternative to less useful behaviour.","zh":"這個說法突顯比無益行為更健康的選擇。"}],"source":"2016 Q2.pdf","sourcePage":7},{"front":"spend their evenings","meaning":"度過晚上","examples":[{"en":"Sports give residents a healthy way to spend their evenings.","zh":"運動給居民一種健康方式去度過晚上。"},{"en":"To spend their evenings means to use the time after daytime work or school in a particular way.","zh":"“Spend their evenings” 指以某種方式使用日間工作或上學後的晚上時間。"},{"en":"Some residents spend their evenings walking in the park.","zh":"有些居民晚上會在公園散步。"},{"en":"People with safe sports venues can spend their evenings exercising instead of sitting at home.","zh":"有安全體育場地的人可以晚上做運動，而不是坐在家中。"},{"en":"This phrase focuses on how daily free time is used.","zh":"這個說法關注日常空閒時間如何被使用。"}],"source":"2016 Q2.pdf","sourcePage":7},{"front":"affordable venues nearby","meaning":"附近負擔得起的場地","examples":[{"en":"Without affordable venues nearby, many residents simply give up.","zh":"如果附近沒有負擔得起的場地，許多居民便會乾脆放棄。"},{"en":"Affordable venues nearby are places close to home that people can use without paying too much.","zh":"附近負擔得起的場地，是住家附近而收費不高的可用地方。"},{"en":"Affordable venues nearby make it easier for families to exercise regularly.","zh":"附近有負擔得起的場地，家庭便較容易定期做運動。"},{"en":"If venues are far away or expensive, residents may stop trying to book them.","zh":"如果場地太遠或太貴，居民可能會停止嘗試預訂。"},{"en":"This phrase explains why location and cost both affect exercise habits.","zh":"這個說法解釋地點和費用如何影響運動習慣。"}],"source":"2016 Q2.pdf","sourcePage":8},{"front":"give up","meaning":"放棄","examples":[{"en":"Some residents give up exercising when venues are too expensive.","zh":"當場地太昂貴時，有些居民會放棄做運動。"},{"en":"To give up means to stop trying to do something.","zh":"“Give up” 指停止嘗試做某事。"},{"en":"He gave up looking for a badminton court after every booking was full.","zh":"每個預訂都滿額後，他放棄尋找羽毛球場。"},{"en":"People may give up healthy habits when the practical barriers are too high.","zh":"當實際障礙太高時，人們可能會放棄健康習慣。"},{"en":"This phrase shows the result of repeated frustration.","zh":"這個說法顯示反覆受挫的結果。"}],"source":"2016 Q2.pdf","sourcePage":8},{"front":"end up wandering around","meaning":"最後四處閒逛","examples":[{"en":"Teenagers may end up wandering around shopping centres.","zh":"青少年可能最後在商場四處閒逛。"},{"en":"To end up wandering around means finally spend time walking about without a clear purpose.","zh":"“End up wandering around” 指最後漫無目的地到處走動。"},{"en":"Without activities after school, some students end up wandering around the streets.","zh":"如果放學後沒有活動，有些學生最後會在街上四處閒逛。"},{"en":"Teenagers may end up wandering around because there are no affordable places to play sport.","zh":"青少年可能因為沒有負擔得起的運動地方，而最後四處閒逛。"},{"en":"This phrase shows an unwanted result when better options are missing.","zh":"這個說法顯示缺少更好選擇時出現的不理想結果。"}],"source":"2016 Q2.pdf","sourcePage":8},{"front":"shopping centres","meaning":"商場","examples":[{"en":"Teenagers may wander around shopping centres after school.","zh":"青少年放學後可能在商場四處閒逛。"},{"en":"Shopping centres are large buildings with many shops, restaurants, and services.","zh":"商場是有許多店舖、餐廳和服務的大型建築物。"},{"en":"Students often meet friends in shopping centres because they are bright and convenient.","zh":"學生常在商場與朋友見面，因為那裏明亮又方便。"},{"en":"If teenagers only wander around shopping centres, they may lose chances to exercise.","zh":"如果青少年只在商場閒逛，可能會失去做運動的機會。"},{"en":"This phrase gives a familiar example of where young people may spend free time.","zh":"這個說法提供一個年輕人使用空閒時間的熟悉例子。"}],"source":"2016 Q2.pdf","sourcePage":8},{"front":"remain glued to their screens","meaning":"一直黏着螢幕","examples":[{"en":"Adults may remain glued to their screens after work.","zh":"成人下班後可能一直黏着螢幕。"},{"en":"To remain glued to their screens means to keep staring at phones, computers, or televisions for a long time.","zh":"“Remain glued to their screens” 指長時間一直盯着電話、電腦或電視。"},{"en":"After dinner, many people remain glued to their screens instead of going outside.","zh":"晚飯後，許多人一直黏着螢幕，而不是外出活動。"},{"en":"Lack of nearby exercise space can make adults more likely to remain glued to their screens.","zh":"如果附近缺少運動空間，成人可能更容易一直黏着螢幕。"},{"en":"This phrase criticises unhealthy screen habits in a vivid way.","zh":"這個說法以生動方式批評不健康的螢幕習慣。"}],"source":"2016 Q2.pdf","sourcePage":8},{"front":"lose chances to","meaning":"失去……的機會","examples":[{"en":"Elderly people may lose chances to stay active safely.","zh":"長者可能失去安全地保持活躍的機會。"},{"en":"To lose chances to do something means to have fewer opportunities to do it.","zh":"“Lose chances to” 指做某事的機會變少。"},{"en":"Children lose chances to play outdoors when playgrounds are closed.","zh":"遊樂場關閉時，孩子會失去到戶外玩耍的機會。"},{"en":"Older residents lose chances to exercise if safe venues are too far away.","zh":"如果安全場地太遠，年長居民會失去運動的機會。"},{"en":"This phrase shows how poor access can reduce people’s real choices.","zh":"這個說法顯示使用機會不足如何減少人們真正的選擇。"}],"source":"2016 Q2.pdf","sourcePage":8},{"front":"stay active safely","meaning":"安全地保持活躍","examples":[{"en":"Elderly residents need chances to stay active safely.","zh":"年長居民需要機會安全地保持活躍。"},{"en":"To stay active safely means to keep moving and exercising without unnecessary danger.","zh":"「安全地保持活躍」指在沒有不必要危險的情況下持續活動和運動。"},{"en":"Gentle stretching classes help older people stay active safely.","zh":"溫和伸展班幫助長者安全地保持活躍。"},{"en":"Safe floors, lighting, and supervision help residents stay active safely.","zh":"安全地板、照明和監督可以幫助居民安全地保持活躍。"},{"en":"This phrase is important because health activities should not create new risks.","zh":"這個說法很重要，因為健康活動不應製造新風險。"}],"source":"2016 Q2.pdf","sourcePage":8},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"By contrast, a well-run booking scheme could give residents a regular place to exercise.","zh":"相比之下，一個管理良好的預訂計劃可以給居民一個固定運動地方。"},{"en":"By contrast introduces a different situation that is compared with the previous one.","zh":"“By contrast” 用來引出與前面情況作比較的另一種情況。"},{"en":"Private gyms are expensive; by contrast, school facilities already exist nearby.","zh":"私人健身室很昂貴；相比之下，學校設施已在附近存在。"},{"en":"Without planning, access may be messy; by contrast, a booking scheme can be orderly.","zh":"沒有規劃時，使用可能混亂；相比之下，預訂計劃可以有秩序。"},{"en":"This phrase helps show the difference between a problem and a better alternative.","zh":"這個說法有助顯示問題與更好選擇之間的差異。"}],"source":"2016 Q2.pdf","sourcePage":8},{"front":"a well-run booking scheme","meaning":"管理良好的預訂計劃","examples":[{"en":"A well-run booking scheme could serve different groups fairly.","zh":"管理良好的預訂計劃可以公平地服務不同群體。"},{"en":"A well-run booking scheme is an organised system that lets people reserve facilities clearly and fairly.","zh":"管理良好的預訂計劃是讓人清楚而公平地預留設施的有組織系統。"},{"en":"A well-run booking scheme should show available times, rules, fees, and responsibilities.","zh":"管理良好的預訂計劃應顯示可用時間、規則、費用和責任。"},{"en":"Such a scheme can prevent overcrowding because every group has a fixed time.","zh":"這種計劃可以防止過度擁擠，因為每個團體都有固定時間。"},{"en":"This phrase suggests that public access should be managed, not random.","zh":"這個說法暗示公眾使用應受到管理，而不是隨意進行。"}],"source":"2016 Q2.pdf","sourcePage":8},{"front":"different groups","meaning":"不同群體","examples":[{"en":"The scheme could give different groups a regular place to exercise.","zh":"這項計劃可以給不同群體一個固定運動地方。"},{"en":"Different groups means separate types of people with different ages, needs, or purposes.","zh":"不同群體指有不同年齡、需要或目的的不同類別人士。"},{"en":"Different groups may include teenagers, elderly residents, parents, and office workers.","zh":"不同群體可以包括青少年、年長居民、家長和上班族。"},{"en":"A fair timetable helps different groups use the same facility without conflict.","zh":"公平時間表幫助不同群體使用同一設施而不產生衝突。"},{"en":"This phrase reminds readers that community needs are varied.","zh":"這個說法提醒讀者，社區需要是多樣的。"}],"source":"2016 Q2.pdf","sourcePage":8},{"front":"a regular place to","meaning":"一個固定地方去……","examples":[{"en":"Residents need a regular place to play sport.","zh":"居民需要一個固定地方去做運動。"},{"en":"A regular place to do something is a fixed and reliable place where people can do it repeatedly.","zh":"“A regular place to” 指一個固定而可靠、可讓人重複做某事的地方。"},{"en":"A community hall can become a regular place to practise dance.","zh":"社區禮堂可以成為一個固定地方去練習舞蹈。"},{"en":"Having a regular place to exercise helps people build habits.","zh":"有一個固定地方去運動，可以幫助人建立習慣。"},{"en":"This phrase shows that consistency matters, not only one-time access.","zh":"這個說法顯示穩定性很重要，而不只是一次性使用。"}],"source":"2016 Q2.pdf","sourcePage":9},{"front":"practise table tennis","meaning":"練習乒乓球","examples":[{"en":"Residents could practise table tennis after school hours.","zh":"居民可以在課後時間練習乒乓球。"},{"en":"To practise table tennis means to train or play repeatedly to improve table tennis skills.","zh":"「練習乒乓球」指透過重複訓練或打球來提升乒乓球技術。"},{"en":"Students practise table tennis by serving, returning, and controlling the ball.","zh":"學生透過發球、接球和控制球來練習乒乓球。"},{"en":"Residents need safe indoor space to practise table tennis when outdoor weather is poor.","zh":"天氣欠佳時，居民需要安全室內空間練習乒乓球。"},{"en":"This phrase gives a concrete example of how school facilities could be used.","zh":"這個說法提供學校設施可如何使用的具體例子。"}],"source":"2016 Q2.pdf","sourcePage":9},{"front":"stretching exercises","meaning":"伸展運動","examples":[{"en":"Some residents could do stretching exercises in school facilities.","zh":"有些居民可以在學校設施內做伸展運動。"},{"en":"Stretching exercises are gentle movements that lengthen muscles and improve flexibility.","zh":"伸展運動是拉長肌肉並改善柔韌度的溫和動作。"},{"en":"Elderly residents may do stretching exercises before walking or light sports.","zh":"年長居民可能在散步或輕量運動前做伸展運動。"},{"en":"Stretching exercises can reduce stiffness when people sit for long hours.","zh":"伸展運動可以減少長時間坐着造成的僵硬。"},{"en":"This phrase shows that sports facilities can support gentle activity, not only competitive games.","zh":"這個說法顯示體育設施不只支援競賽，也支援溫和活動。"}],"source":"2016 Q2.pdf","sourcePage":9},{"front":"parent-child sports activities","meaning":"親子體育活動","examples":[{"en":"Schools could host parent-child sports activities at weekends.","zh":"學校可以在週末舉辦親子體育活動。"},{"en":"Parent-child sports activities are exercise or games that parents and children join together.","zh":"親子體育活動是家長和孩子一起參與的運動或遊戲。"},{"en":"A parent-child sports activity may include relay races, ball games, or simple fitness games.","zh":"親子體育活動可以包括接力賽、球類遊戲或簡單健體遊戲。"},{"en":"These activities can improve health while strengthening family relationships.","zh":"這些活動可以改善健康，同時加強家庭關係。"},{"en":"This phrase shows how school facilities can serve families, not only individual users.","zh":"這個說法顯示學校設施可以服務家庭，而不只是個別使用者。"}],"source":"2016 Q2.pdf","sourcePage":9},{"front":"early evening slots","meaning":"傍晚早段時段","examples":[{"en":"Early evening slots could be reserved for youth teams.","zh":"傍晚早段時段可以預留給青少年隊伍。"},{"en":"Early evening slots are booking periods in the earlier part of the evening, usually after school or work.","zh":"傍晚早段時段是晚上較早部分的預訂時間，通常在放學或下班後。"},{"en":"A court may offer early evening slots from 6 p.m. to 8 p.m.","zh":"球場可以提供晚上六時至八時的傍晚早段時段。"},{"en":"Early evening slots suit teenagers because they can exercise before going home too late.","zh":"傍晚早段時段適合青少年，因為他們可以運動後不用太晚回家。"},{"en":"This phrase is useful when planning fair use of shared facilities.","zh":"當規劃共享設施的公平使用時，這個說法很有用。"}],"source":"2016 Q2.pdf","sourcePage":9},{"front":"be reserved for","meaning":"預留給……","examples":[{"en":"Early evening slots could be reserved for youth teams.","zh":"傍晚早段時段可以預留給青少年隊伍。"},{"en":"To be reserved for someone means to be kept specially for that person or group.","zh":"“Be reserved for” 指特別保留給某人或某群體使用。"},{"en":"The front seats are reserved for elderly passengers.","zh":"前排座位預留給長者乘客。"},{"en":"Some time slots can be reserved for students so public use does not replace school needs.","zh":"有些時段可以預留給學生，讓公眾使用不會取代學校需要。"},{"en":"This phrase shows planned and fair allocation.","zh":"這個說法顯示有計劃而公平的分配。"}],"source":"2016 Q2.pdf","sourcePage":9},{"front":"youth teams","meaning":"青少年隊伍","examples":[{"en":"Early evening slots could be reserved for youth teams.","zh":"傍晚早段時段可以預留給青少年隊伍。"},{"en":"Youth teams are organised groups of young people who train or play sports together.","zh":"青少年隊伍是由年輕人組成、一起訓練或比賽的有組織團體。"},{"en":"A youth team may use a school court for basketball practice.","zh":"青少年隊伍可以使用學校球場進行籃球練習。"},{"en":"Youth teams need regular practice spaces to build discipline and teamwork.","zh":"青少年隊伍需要固定練習空間來建立紀律和團隊合作。"},{"en":"This phrase shows how shared facilities can support young people positively.","zh":"這個說法顯示共享設施如何正面支援年輕人。"}],"source":"2016 Q2.pdf","sourcePage":9},{"front":"adult groups","meaning":"成人組別","examples":[{"en":"Later slots could be reserved for adult groups.","zh":"較後時段可以預留給成人組別。"},{"en":"Adult groups are organised groups of grown-up residents who join activities together.","zh":"成人組別是由成年居民組成、一起參與活動的有組織團體。"},{"en":"Adult groups may book a hall for badminton after work.","zh":"成人組別可以在下班後預訂禮堂打羽毛球。"},{"en":"Adult groups often prefer later time slots because many members finish work in the evening.","zh":"成人組別通常較適合較後時段，因為許多成員晚上才下班。"},{"en":"This phrase helps show how booking times can match different users’ needs.","zh":"這個說法有助顯示預訂時間如何配合不同使用者需要。"}],"source":"2016 Q2.pdf","sourcePage":9},{"front":"weekend mornings","meaning":"週末早上","examples":[{"en":"Weekend mornings could be used for elderly fitness classes.","zh":"週末早上可以用作長者健體班。"},{"en":"Weekend mornings are the morning periods on Saturdays and Sundays.","zh":"週末早上是星期六和星期日的上午時段。"},{"en":"Weekend mornings are often suitable for family or community sports activities.","zh":"週末早上通常適合家庭或社區體育活動。"},{"en":"Elderly residents may prefer weekend mornings because the weather is cooler and travel is easier.","zh":"年長居民可能較喜歡週末早上，因為天氣較涼，出行較方便。"},{"en":"This phrase gives a specific time for community use.","zh":"這個說法為社區使用提供具體時間。"}],"source":"2016 Q2.pdf","sourcePage":9},{"front":"elderly fitness classes","meaning":"長者健體班","examples":[{"en":"Weekend mornings could be reserved for elderly fitness classes.","zh":"週末早上可以預留給長者健體班。"},{"en":"Elderly fitness classes are exercise classes designed for older people’s strength, balance, and safety.","zh":"長者健體班是為長者的力量、平衡和安全而設計的運動課程。"},{"en":"Elderly fitness classes may include stretching, light movement, and balance training.","zh":"長者健體班可能包括伸展、輕量活動和平衡訓練。"},{"en":"Such classes help older residents stay active while reducing injury risks.","zh":"這些課程幫助年長居民保持活躍，同時減低受傷風險。"},{"en":"This phrase shows that school facilities can support public health for all ages.","zh":"這個說法顯示學校設施可以支援不同年齡層的公共健康。"}],"source":"2016 Q2.pdf","sourcePage":9},{"front":"such arrangements","meaning":"這些安排","examples":[{"en":"Such arrangements would improve physical health and community connection.","zh":"這些安排會改善身體健康和社區連繫。"},{"en":"Such arrangements means the planned measures or schedules just described.","zh":"“Such arrangements” 指剛才描述的計劃措施或時間安排。"},{"en":"Such arrangements can help different groups use the same court without argument.","zh":"這些安排可以幫助不同群體使用同一球場而不爭執。"},{"en":"When such arrangements are clear, residents know when and how they may use facilities.","zh":"當這些安排清楚時，居民便知道何時及如何使用設施。"},{"en":"This phrase refers back to practical plans and explains their benefits.","zh":"這個說法回指實際計劃，並解釋其好處。"}],"source":"2016 Q2.pdf","sourcePage":10},{"front":"physical health","meaning":"身體健康","examples":[{"en":"Sports facilities can improve physical health.","zh":"體育設施可以改善身體健康。"},{"en":"Physical health is the condition of the body, including strength, movement, fitness, and freedom from illness.","zh":"身體健康是身體的狀況，包括力量、活動能力、體能和沒有疾病。"},{"en":"Regular walking and stretching can improve physical health.","zh":"定期散步和伸展可以改善身體健康。"},{"en":"Access to sports facilities supports physical health because people can exercise more safely.","zh":"使用體育設施的機會能支援身體健康，因為人們可以更安全地運動。"},{"en":"This phrase focuses on bodily well-being rather than only enjoyment.","zh":"這個說法集中於身體福祉，而不只是娛樂。"}],"source":"2016 Q2.pdf","sourcePage":10},{"front":"neighbours","meaning":"鄰居","examples":[{"en":"Sports activities allow neighbours to meet one another.","zh":"體育活動讓鄰居互相認識。"},{"en":"Neighbours are people who live near one another in the same building, street, or community.","zh":"鄰居是住在同一大廈、街道或社區附近的人。"},{"en":"Neighbours may become friends when they join the same evening exercise class.","zh":"鄰居參加同一個晚間運動班後，可能會成為朋友。"},{"en":"Community sports can help neighbours know one another beyond a quick lift greeting.","zh":"社區運動可以幫助鄰居不只是升降機裏打個招呼，而是真正認識彼此。"},{"en":"This word shows the social value of shared local activities.","zh":"這個詞顯示共享本地活動的社交價值。"}],"source":"2016 Q2.pdf","sourcePage":10},{"front":"more than examination factories","meaning":"不只是考試工廠","examples":[{"en":"Schools would become more than examination factories.","zh":"學校會變得不只是考試工廠。"},{"en":"More than examination factories means schools would be seen as places for community growth, not only exam results.","zh":"“More than examination factories” 指學校會被視為促進社區成長的地方，而不只是追求考試成績。"},{"en":"A school is more than an examination factory when it supports health, friendship, and civic responsibility.","zh":"當學校支援健康、友誼和公民責任時，它就不只是考試工廠。"},{"en":"If schools only focus on marks, they may look like examination factories.","zh":"如果學校只專注分數，它們可能看起來像考試工廠。"},{"en":"This phrase criticises a narrow view of education.","zh":"這個說法批評對教育的狹窄理解。"}],"source":"2016 Q2.pdf","sourcePage":10},{"front":"living parts of the community","meaning":"社區中有生命力的一部分","examples":[{"en":"Schools would become living parts of the community.","zh":"學校會成為社區中有生命力的一部分。"},{"en":"Living parts of the community are active places that connect with local people’s daily lives.","zh":"社區中有生命力的一部分，是與本地人日常生活有連繫的活躍地方。"},{"en":"A school becomes a living part of the community when residents join events there after hours.","zh":"當居民在課後參加學校活動時，學校便成為社區中有生命力的一部分。"},{"en":"Shared facilities can make schools feel more open, useful, and connected.","zh":"共享設施可以令學校感覺更開放、更有用和更有連繫。"},{"en":"This phrase presents schools as active community spaces, not closed buildings.","zh":"這個說法把學校呈現為活躍社區空間，而不是封閉建築物。"}],"source":"2016 Q2.pdf","sourcePage":10},{"front":"the risks, while real","meaning":"風險雖然真實存在","examples":[{"en":"The risks, while real, can be managed through clear rules.","zh":"風險雖然真實存在，但可以透過清晰規則管理。"},{"en":"The risks, while real means the dangers truly exist, but they are not necessarily impossible to handle.","zh":"“The risks, while real” 指危險確實存在，但不一定無法處理。"},{"en":"The costs, while real, may be justified if the programme benefits many residents.","zh":"成本雖然真實存在，但如果計劃惠及許多居民，可能仍然值得。"},{"en":"This phrase admits a concern before explaining why it should not stop action completely.","zh":"這個說法先承認憂慮，再解釋為何不應完全停止行動。"},{"en":"It makes an argument more balanced and realistic.","zh":"它令論證更平衡和現實。"}],"source":"2016 Q2.pdf","sourcePage":10},{"front":"be managed through","meaning":"透過……管理","examples":[{"en":"The risks can be managed through clear rules.","zh":"風險可以透過清晰規則管理。"},{"en":"To be managed through something means to be controlled or reduced by using that method.","zh":"“Be managed through” 指使用某種方法控制或減少問題。"},{"en":"Crowds can be managed through advance booking and time limits.","zh":"人流可以透過預先登記和時間限制來管理。"},{"en":"Security risks can be managed through registration, guards, and restricted areas.","zh":"保安風險可以透過登記、保安員和限制區域來管理。"},{"en":"This phrase shows how a problem can be handled practically.","zh":"這個說法顯示問題可以如何實際處理。"}],"source":"2016 Q2.pdf","sourcePage":10},{"front":"clear rules","meaning":"清晰規則","examples":[{"en":"Clear rules can reduce the risks of opening school facilities.","zh":"清晰規則可以減低開放學校設施的風險。"},{"en":"Clear rules are instructions that are easy to understand and follow.","zh":"清晰規則是容易理解和遵守的指示。"},{"en":"Clear rules should state who may enter, which areas may be used, and when users must leave.","zh":"清晰規則應列明誰可以進入、哪些區域可使用，以及使用者何時必須離開。"},{"en":"Without clear rules, even a good idea can become confusing.","zh":"如果沒有清晰規則，即使好主意也可能變得混亂。"},{"en":"This phrase is central to making public access safe and fair.","zh":"這個說法是令公眾使用安全和公平的核心。"}],"source":"2016 Q2.pdf","sourcePage":10},{"front":"rather than used as an excuse","meaning":"而不是被用作藉口","examples":[{"en":"Risks should be managed rather than used as an excuse for doing nothing.","zh":"風險應被管理，而不是被用作不作為的藉口。"},{"en":"Rather than used as an excuse means instead of being treated as a reason to avoid action.","zh":"“Rather than used as an excuse” 指不應把某事當成避免行動的理由。"},{"en":"Safety concerns should be solved rather than used as an excuse to close every activity.","zh":"安全憂慮應被解決，而不是被用作取消所有活動的藉口。"},{"en":"This phrase criticises people who point to problems but refuse to seek solutions.","zh":"這個說法批評只指出問題卻拒絕尋找解決方法的人。"},{"en":"It argues that risk management is better than passive refusal.","zh":"它主張管理風險比被動拒絕更好。"}],"source":"2016 Q2.pdf","sourcePage":10},{"front":"an excuse for doing nothing","meaning":"不作為的藉口","examples":[{"en":"Security concerns should not become an excuse for doing nothing.","zh":"保安憂慮不應成為不作為的藉口。"},{"en":"An excuse for doing nothing is a reason used to avoid action, even when action is possible.","zh":"不作為的藉口，是用來避免行動的理由，即使行動其實可行。"},{"en":"The possibility of rain should not be an excuse for doing nothing if an indoor plan exists.","zh":"如果已有室內方案，下雨的可能不應成為不作為的藉口。"},{"en":"Concerns become an excuse for doing nothing when people refuse to consider safeguards.","zh":"當人們拒絕考慮保障措施時，憂慮就會變成不作為的藉口。"},{"en":"This phrase warns against using problems to justify inaction.","zh":"這個說法提醒我們，不要用問題來合理化不行動。"}],"source":"2016 Q2.pdf","sourcePage":10},{"front":"granted","meaning":"誠然","examples":[{"en":"Granted, schools have every reason to worry about security.","zh":"誠然，學校完全有理由擔心保安。"},{"en":"Granted means the writer accepts that a point is true before giving a further argument.","zh":"“Granted” 指作者先承認某一點是真的，然後再提出進一步論點。"},{"en":"Granted, the plan will cost money, but it may save resources later.","zh":"誠然，這個計劃會花錢，但長遠可能節省資源。"},{"en":"This word helps acknowledge the other side fairly.","zh":"這個詞有助公平承認另一方觀點。"},{"en":"It is often used before explaining why the concern does not defeat the proposal.","zh":"它常用於解釋為何該憂慮不足以推翻建議之前。"}],"source":"2016 Q2.pdf","sourcePage":11},{"front":"have every reason to","meaning":"完全有理由去……","examples":[{"en":"Schools have every reason to worry about security and damage.","zh":"學校完全有理由擔心保安和財物損毀。"},{"en":"To have every reason to do something means to have strong and understandable reasons for doing it.","zh":"“Have every reason to” 指有充分而可以理解的理由去做某事。"},{"en":"Parents have every reason to ask about safety before a school trip.","zh":"家長完全有理由在學校旅行前詢問安全安排。"},{"en":"Schools have every reason to protect students and property carefully.","zh":"學校完全有理由仔細保護學生和財物。"},{"en":"This phrase shows respect for concerns instead of dismissing them.","zh":"這個說法顯示尊重憂慮，而不是輕視它們。"}],"source":"2016 Q2.pdf","sourcePage":11},{"front":"security","meaning":"保安","examples":[{"en":"Schools have to worry about security.","zh":"學校必須擔心保安。"},{"en":"Security means protection against danger, damage, theft, or unauthorised entry.","zh":"保安指防止危險、損毀、盜竊或未經批准進入的保護措施。"},{"en":"A school needs good security when visitors enter after normal hours.","zh":"當訪客在正常時間後進入，學校需要良好保安。"},{"en":"Security can be improved through registration, guards, cameras, and clear boundaries.","zh":"保安可以透過登記、保安員、攝影機和清晰界線來改善。"},{"en":"This word is important because schools must protect students and property.","zh":"這個詞很重要，因為學校必須保護學生和財物。"}],"source":"2016 Q2.pdf","sourcePage":11},{"front":"damage to property","meaning":"財物損毀","examples":[{"en":"Schools may worry about damage to property.","zh":"學校可能擔心財物損毀。"},{"en":"Damage to property means harm caused to buildings, equipment, furniture, or other belongings.","zh":"財物損毀指建築物、設備、家具或其他物品受到破壞。"},{"en":"Broken windows and damaged sports equipment are examples of damage to property.","zh":"窗戶破裂和體育器材受損都是財物損毀的例子。"},{"en":"Schools can reduce damage to property by requiring deposits and responsibility agreements.","zh":"學校可以透過要求按金和責任協議來減少財物損毀。"},{"en":"This phrase names one practical risk of opening facilities.","zh":"這個說法指出開放設施的一項實際風險。"}],"source":"2016 Q2.pdf","sourcePage":11},{"front":"disruption to students","meaning":"對學生造成滋擾","examples":[{"en":"Schools may worry about disruption to students.","zh":"學校可能擔心對學生造成滋擾。"},{"en":"Disruption to students means disturbance that affects students’ learning, safety, rest, or activities.","zh":"對學生造成滋擾指影響學生學習、安全、休息或活動的打擾。"},{"en":"Loud evening events could cause disruption to students if they continue during exams.","zh":"如果晚上活動聲浪很大並持續到考試期間，可能會對學生造成滋擾。"},{"en":"Public access should be planned so there is no disruption to students during lessons or school activities.","zh":"公眾使用應妥善規劃，以免在課堂或學校活動期間對學生造成滋擾。"},{"en":"This phrase explains why student needs must remain a priority.","zh":"這個說法解釋為何學生需要必須保持優先。"}],"source":"2016 Q2.pdf","sourcePage":11},{"front":"these concerns do not prove that","meaning":"這些憂慮並不證明……","examples":[{"en":"These concerns do not prove that the proposal is impractical.","zh":"這些憂慮並不證明該建議不切實際。"},{"en":"These concerns do not prove that means the worries are real but not enough to show the conclusion is true.","zh":"“These concerns do not prove that” 指憂慮雖然存在，但不足以證明某結論是真的。"},{"en":"Safety concerns do not prove that the trip should be cancelled if good precautions exist.","zh":"如果已有良好預防措施，安全憂慮並不證明旅行應被取消。"},{"en":"This phrase separates reasonable worries from final judgement.","zh":"這個說法把合理憂慮與最終判斷分開。"},{"en":"It helps the writer argue that problems can be solved.","zh":"它幫助作者主張問題可以被解決。"}],"source":"2016 Q2.pdf","sourcePage":11},{"front":"impractical","meaning":"不切實際","examples":[{"en":"The proposal is not necessarily impractical.","zh":"該建議不一定不切實際。"},{"en":"Impractical means not realistic or too difficult to carry out successfully.","zh":"“Impractical” 指不現實，或太難成功執行。"},{"en":"Building a huge new stadium in a tiny district may be impractical.","zh":"在細小地區興建大型新運動場可能不切實際。"},{"en":"A plan is not impractical simply because it needs careful rules.","zh":"一個計劃不會只因需要仔細規則就變得不切實際。"},{"en":"This word is often used when judging whether an idea can work in real life.","zh":"當判斷一個想法能否在現實中運作時，常會使用這個詞。"}],"source":"2016 Q2.pdf","sourcePage":11},{"front":"designed carefully","meaning":"經過仔細設計","examples":[{"en":"The scheme must be designed carefully.","zh":"這項計劃必須經過仔細設計。"},{"en":"Designed carefully means planned with attention to details, risks, users, and results.","zh":"“Designed carefully” 指在規劃時仔細考慮細節、風險、使用者和結果。"},{"en":"A booking system must be designed carefully so different groups are treated fairly.","zh":"預訂系統必須經過仔細設計，讓不同群體得到公平對待。"},{"en":"If a scheme is not designed carefully, small problems can quickly become serious.","zh":"如果計劃沒有仔細設計，小問題可能很快變嚴重。"},{"en":"This phrase stresses preparation before action.","zh":"這個說法強調行動前的準備。"}],"source":"2016 Q2.pdf","sourcePage":11},{"front":"be required to","meaning":"被要求","examples":[{"en":"Public users could be required to register in advance.","zh":"公眾使用者可以被要求預先登記。"},{"en":"Be required to means be officially told or expected to do something.","zh":"“Be required to” 指被正式要求或期望做某事。"},{"en":"Visitors may be required to show identification before entering the building.","zh":"訪客進入大樓前可能被要求出示身份證明。"},{"en":"Users can be required to follow rules before they use public facilities.","zh":"使用者可以被要求先遵守規則，才可使用公共設施。"},{"en":"This phrase is useful for explaining formal conditions.","zh":"這個說法適合用來解釋正式條件。"}],"source":"2016 Q2.pdf","sourcePage":11},{"front":"register in advance","meaning":"預先登記","examples":[{"en":"Public users should register in advance.","zh":"公眾使用者應預先登記。"},{"en":"To register in advance means to provide personal or group information before using a service or attending an activity.","zh":"「預先登記」指在使用服務或參加活動前提供個人或團體資料。"},{"en":"Residents must register in advance before booking the school hall.","zh":"居民預訂學校禮堂前必須預先登記。"},{"en":"Registration in advance helps organisers control numbers and check who is responsible.","zh":"預先登記幫助組織者控制人數，並查明誰負責。"},{"en":"This phrase shows one way to make public access safer.","zh":"這個說法顯示令公眾使用更安全的一種方法。"}],"source":"2016 Q2.pdf","sourcePage":11},{"front":"pay a small maintenance fee","meaning":"支付小額保養費","examples":[{"en":"Users could pay a small maintenance fee.","zh":"使用者可以支付小額保養費。"},{"en":"To pay a small maintenance fee means to give a modest amount of money to help cover repair and cleaning costs.","zh":"「支付小額保養費」指付出少量金錢，以幫助支付維修和清潔成本。"},{"en":"Sports groups could pay a small maintenance fee when booking the school court.","zh":"體育團體預訂學校球場時，可以支付小額保養費。"},{"en":"A maintenance fee can make the scheme fairer because users help cover basic costs.","zh":"保養費可以令計劃更公平，因為使用者協助支付基本成本。"},{"en":"This phrase shows that community use does not have to be completely free.","zh":"這個說法顯示社區使用不一定完全免費。"}],"source":"2016 Q2.pdf","sourcePage":12},{"front":"maintenance fee","meaning":"保養費","examples":[{"en":"A maintenance fee could help cover basic costs.","zh":"保養費可以幫助支付基本成本。"},{"en":"A maintenance fee is money paid to keep a place, building, or equipment clean, safe, and usable.","zh":"保養費是用來保持地方、建築物或設備清潔、安全和可用的費用。"},{"en":"The maintenance fee may pay for cleaning, lighting, and minor repairs.","zh":"保養費可能用於清潔、照明和小型維修。"},{"en":"Charging a small maintenance fee can prevent schools from bearing all extra costs.","zh":"收取小額保養費可以避免學校承擔所有額外成本。"},{"en":"This phrase explains how a shared facility can remain in good condition.","zh":"這個說法解釋共享設施如何保持良好狀態。"}],"source":"2016 Q2.pdf","sourcePage":12},{"front":"leave a deposit","meaning":"繳付按金","examples":[{"en":"Users could be required to leave a deposit.","zh":"使用者可以被要求繳付按金。"},{"en":"To leave a deposit means to pay money temporarily as a guarantee against damage or rule-breaking.","zh":"「繳付按金」指暫時支付一筆金錢，作為防止損毀或違規的保證。"},{"en":"The sports club had to leave a deposit before using the hall.","zh":"體育會使用禮堂前必須繳付按金。"},{"en":"A deposit encourages users to take care of shared facilities.","zh":"按金鼓勵使用者好好愛護共享設施。"},{"en":"This phrase shows one practical way to protect school property.","zh":"這個說法顯示保護學校財物的一種實際方法。"}],"source":"2016 Q2.pdf","sourcePage":12},{"front":"staff rooms","meaning":"教員室","examples":[{"en":"Staff rooms should remain strictly out of bounds.","zh":"教員室應嚴格禁止進入。"},{"en":"Staff rooms are rooms used by teachers and school staff for work, rest, meetings, or storage.","zh":"教員室是老師和學校職員用作工作、休息、會議或儲物的房間。"},{"en":"Visitors should not enter staff rooms because private documents may be kept there.","zh":"訪客不應進入教員室，因為那裏可能存放私人文件。"},{"en":"Keeping staff rooms closed protects privacy and school security.","zh":"關閉教員室可以保護私隱和學校保安。"},{"en":"This phrase shows that opening schools does not mean opening every area.","zh":"這個說法顯示開放學校不等於開放每個區域。"}],"source":"2016 Q2.pdf","sourcePage":12},{"front":"laboratories","meaning":"實驗室","examples":[{"en":"Laboratories should remain strictly out of bounds.","zh":"實驗室應嚴格禁止進入。"},{"en":"Laboratories are rooms where scientific experiments, tests, or practical lessons take place.","zh":"實驗室是進行科學實驗、測試或實習課的房間。"},{"en":"School laboratories may contain chemicals, glass equipment, and electrical devices.","zh":"學校實驗室可能有化學品、玻璃器材和電器設備。"},{"en":"Laboratories should be closed to public users because accidents could happen easily.","zh":"實驗室應向公眾使用者關閉，因為容易發生意外。"},{"en":"This phrase identifies an area that should not be included in community access.","zh":"這個說法指出不應納入社區使用的區域。"}],"source":"2016 Q2.pdf","sourcePage":12},{"front":"remain strictly out of bounds","meaning":"嚴格禁止進入","examples":[{"en":"Classrooms, staff rooms, and laboratories should remain strictly out of bounds.","zh":"課室、教員室和實驗室應嚴格禁止進入。"},{"en":"Remain strictly out of bounds means continue to be completely closed to people who are not allowed to enter.","zh":"“Remain strictly out of bounds” 指繼續完全禁止未獲准人士進入。"},{"en":"The school roof must remain strictly out of bounds for safety reasons.","zh":"基於安全原因，學校天台必須嚴格禁止進入。"},{"en":"Clear signs can show which areas remain strictly out of bounds.","zh":"清楚指示牌可以顯示哪些區域嚴格禁止進入。"},{"en":"This phrase protects sensitive or dangerous spaces while allowing limited access elsewhere.","zh":"這個說法在容許部分開放時，保護敏感或危險空間。"}],"source":"2016 Q2.pdf","sourcePage":12},{"front":"designated sports areas","meaning":"指定體育範圍","examples":[{"en":"Only designated sports areas should be opened.","zh":"只有指定體育範圍應被開放。"},{"en":"Designated sports areas are specific places officially chosen for sports use.","zh":"指定體育範圍是官方選定作體育用途的特定地方。"},{"en":"The basketball court and covered playground may be designated sports areas.","zh":"籃球場和有蓋操場可以是指定體育範圍。"},{"en":"Opening only designated sports areas keeps visitors away from classrooms and offices.","zh":"只開放指定體育範圍，可以讓訪客遠離課室和辦公室。"},{"en":"This phrase shows that access should be limited and controlled.","zh":"這個說法顯示使用權應受到限制和控制。"}],"source":"2016 Q2.pdf","sourcePage":12},{"front":"employ security guards","meaning":"聘請保安員","examples":[{"en":"Schools could employ security guards for after-hours access.","zh":"學校可以為課後使用聘請保安員。"},{"en":"To employ security guards means to hire trained people to protect a place and control entry.","zh":"「聘請保安員」指僱用受訓人員保護地方和控制出入。"},{"en":"The community centre employed security guards during evening events.","zh":"社區中心在晚間活動期間聘請保安員。"},{"en":"Security guards can check bookings, guide visitors, and respond to problems.","zh":"保安員可以核對預訂、指引訪客和處理問題。"},{"en":"This phrase gives a practical safeguard for opening facilities safely.","zh":"這個說法提供安全開放設施的一項實際保障措施。"}],"source":"2016 Q2.pdf","sourcePage":12},{"front":"install access-control gates","meaning":"安裝出入控制閘","examples":[{"en":"Schools could install access-control gates.","zh":"學校可以安裝出入控制閘。"},{"en":"To install access-control gates means to put in gates that control who can enter or leave.","zh":"「安裝出入控制閘」指設置控制誰可以進出的閘門。"},{"en":"The sports centre installed access-control gates to check booking passes.","zh":"體育中心安裝出入控制閘，以核對預訂通行證。"},{"en":"Access-control gates can stop visitors from entering private school areas.","zh":"出入控制閘可以阻止訪客進入學校私人區域。"},{"en":"This phrase shows how equipment can help manage public entry.","zh":"這個說法顯示設備如何幫助管理公眾出入。"}],"source":"2016 Q2.pdf","sourcePage":12},{"front":"access-control gates","meaning":"出入控制閘","examples":[{"en":"Access-control gates could help manage public users.","zh":"出入控制閘可以幫助管理公眾使用者。"},{"en":"Access-control gates are gates or barriers that allow entry only to authorised users.","zh":"出入控制閘是只容許獲授權使用者進入的閘門或屏障。"},{"en":"Access-control gates may open with cards, codes, or staff approval.","zh":"出入控制閘可能以卡、密碼或職員批准開啟。"},{"en":"Schools can use access-control gates to separate sports areas from classrooms.","zh":"學校可以用出入控制閘把體育範圍與課室分隔。"},{"en":"This phrase explains a physical tool for keeping the scheme orderly.","zh":"這個說法解釋一種維持計劃有秩序的實體工具。"}],"source":"2016 Q2.pdf","sourcePage":12},{"front":"keep CCTV in public zones","meaning":"在公共區域設置閉路電視","examples":[{"en":"Schools could keep CCTV in public zones.","zh":"學校可以在公共區域設置閉路電視。"},{"en":"To keep CCTV in public zones means to use security cameras in areas open to approved visitors.","zh":"「在公共區域設置閉路電視」指在向獲准訪客開放的地方使用保安攝影機。"},{"en":"A sports hall may keep CCTV in public zones to discourage damage.","zh":"體育館可以在公共區域設置閉路電視，以減少損毀行為。"},{"en":"CCTV should be used carefully so safety is protected without invading private areas.","zh":"閉路電視應小心使用，既保障安全，也不侵犯私人區域。"},{"en":"This phrase offers a security measure for shared spaces.","zh":"這個說法為共享空間提供一項保安措施。"}],"source":"2016 Q2.pdf","sourcePage":13},{"front":"public zones","meaning":"公共區域","examples":[{"en":"CCTV could be used in public zones.","zh":"閉路電視可以用於公共區域。"},{"en":"Public zones are areas where approved visitors or members of the public are allowed to go.","zh":"公共區域是獲准訪客或公眾人士可以進入的地方。"},{"en":"The entrance, playground, and sports hall may be public zones during opening hours.","zh":"入口、操場和體育館在開放時間可以是公共區域。"},{"en":"Public zones should be clearly marked so visitors do not enter private areas.","zh":"公共區域應清楚標示，讓訪客不會進入私人區域。"},{"en":"This phrase helps separate open areas from restricted areas.","zh":"這個說法有助區分開放區域和限制區域。"}],"source":"2016 Q2.pdf","sourcePage":13},{"front":"responsibility agreements","meaning":"責任協議","examples":[{"en":"Community groups could sign responsibility agreements.","zh":"社區團體可以簽署責任協議。"},{"en":"Responsibility agreements are written promises that state what users must do and what happens if rules are broken.","zh":"責任協議是列明使用者必須做甚麼，以及違規後果的書面承諾。"},{"en":"A football club may sign a responsibility agreement before using a school pitch.","zh":"足球會使用學校球場前，可能要簽署責任協議。"},{"en":"Responsibility agreements help schools know who is accountable for damage or misuse.","zh":"責任協議幫助學校知道誰要為損毀或誤用負責。"},{"en":"This phrase shows how shared use can be formal and controlled.","zh":"這個說法顯示共享使用可以是正式而受控制的。"}],"source":"2016 Q2.pdf","sourcePage":13},{"front":"in case of damage","meaning":"如有損毀","examples":[{"en":"In case of damage, the responsible group should pay for repairs.","zh":"如有損毀，負責團體應支付維修費。"},{"en":"In case of damage means if damage happens.","zh":"“In case of damage” 指如果出現損毀。"},{"en":"In case of damage to the hall, the user group must report it immediately.","zh":"如禮堂有損毀，使用團體必須立即報告。"},{"en":"Rules should explain what happens in case of damage before facilities are opened.","zh":"設施開放前，規則應說明如有損毀會如何處理。"},{"en":"This phrase prepares for a possible problem and its solution.","zh":"這個說法為可能出現的問題及其解決方法作準備。"}],"source":"2016 Q2.pdf","sourcePage":13},{"front":"responsible group","meaning":"負責團體","examples":[{"en":"The responsible group should pay for repairs.","zh":"負責團體應支付維修費。"},{"en":"The responsible group is the organisation or team that is accountable for what happens during its booking.","zh":"負責團體是對其預訂期間發生的事情負責的組織或隊伍。"},{"en":"If a basketball team books the court, that team may be the responsible group.","zh":"如果一支籃球隊預訂球場，該隊便可能是負責團體。"},{"en":"Naming a responsible group prevents confusion when damage or rule-breaking occurs.","zh":"指明負責團體可以避免在出現損毀或違規時產生混亂。"},{"en":"This phrase helps make public use accountable.","zh":"這個說法幫助令公眾使用更有問責性。"}],"source":"2016 Q2.pdf","sourcePage":13},{"front":"pay for repairs","meaning":"支付維修費","examples":[{"en":"The responsible group should pay for repairs.","zh":"負責團體應支付維修費。"},{"en":"To pay for repairs means to cover the cost of fixing something that has been damaged.","zh":"「支付維修費」指承擔修理受損物件的費用。"},{"en":"If users break a window, they should pay for repairs.","zh":"如果使用者打破窗戶，他們應支付維修費。"},{"en":"Requiring groups to pay for repairs encourages careful use of facilities.","zh":"要求團體支付維修費，可以鼓勵他們小心使用設施。"},{"en":"This phrase explains one financial responsibility in the scheme.","zh":"這個說法解釋計劃中的一項財務責任。"}],"source":"2016 Q2.pdf","sourcePage":13},{"front":"in case of school activities","meaning":"如遇學校活動","examples":[{"en":"In case of school activities, student use must take priority.","zh":"如遇學校活動，學生使用必須優先。"},{"en":"In case of school activities means if school events, lessons, training, or programmes are taking place.","zh":"“In case of school activities” 指如果學校活動、課堂、訓練或項目正在進行。"},{"en":"In case of school activities, public bookings should be changed or cancelled with notice.","zh":"如遇學校活動，公眾預訂應在通知下更改或取消。"},{"en":"This rule protects students because the school’s main purpose comes first.","zh":"這條規則保障學生，因為學校的主要目的應放在第一位。"},{"en":"The phrase shows that community access should not interfere with education.","zh":"這個說法顯示社區使用不應干擾教育。"}],"source":"2016 Q2.pdf","sourcePage":13},{"front":"take priority","meaning":"優先","examples":[{"en":"Student use must take priority.","zh":"學生使用必須優先。"},{"en":"To take priority means to be treated as more important than other things.","zh":"“Take priority” 指被視為比其他事情更重要。"},{"en":"Emergency cases take priority in a hospital.","zh":"在醫院，緊急個案會優先處理。"},{"en":"In a school, student safety and learning should take priority over public convenience.","zh":"在學校，學生安全和學習應優先於公眾方便。"},{"en":"This phrase makes the order of importance clear.","zh":"這個說法清楚顯示重要性的次序。"}],"source":"2016 Q2.pdf","sourcePage":13},{"front":"with these safeguards","meaning":"有了這些保障措施","examples":[{"en":"With these safeguards, the scheme would not be a free-for-all.","zh":"有了這些保障措施，計劃就不會變成任意混亂的情況。"},{"en":"With these safeguards means if these protective measures are used.","zh":"“With these safeguards” 指如果使用這些保護措施。"},{"en":"With these safeguards, visitors can use the hall without entering private school areas.","zh":"有了這些保障措施，訪客可以使用禮堂，而不進入學校私人區域。"},{"en":"This phrase connects rules and protections with a safer result.","zh":"這個說法把規則和保護措施與更安全的結果連接起來。"},{"en":"It reassures readers that the proposal is controlled.","zh":"它讓讀者放心，建議是受控制的。"}],"source":"2016 Q2.pdf","sourcePage":13},{"front":"safeguards","meaning":"保障措施","examples":[{"en":"Safeguards can make the scheme safe and orderly.","zh":"保障措施可以令計劃安全而有秩序。"},{"en":"Safeguards are measures that protect people, property, or systems from risk.","zh":"保障措施是保護人、財物或系統免受風險影響的方法。"},{"en":"Registration, deposits, and security guards are possible safeguards.","zh":"登記、按金和保安員都可以是保障措施。"},{"en":"Safeguards are necessary when public access may create safety or management concerns.","zh":"當公眾使用可能帶來安全或管理憂慮時，保障措施是必要的。"},{"en":"This word shows that risk can be reduced through preparation.","zh":"這個詞顯示風險可以透過準備來減低。"}],"source":"2016 Q2.pdf","sourcePage":13},{"front":"a free-for-all","meaning":"任意混亂的情況","examples":[{"en":"The scheme would not be a free-for-all.","zh":"這項計劃不會成為任意混亂的情況。"},{"en":"A free-for-all is a situation where anyone does what they want without control or order.","zh":"“A free-for-all” 指任何人都不受控制地隨意行事的混亂情況。"},{"en":"Without bookings, the sports hall could become a free-for-all.","zh":"如果沒有預訂，體育館可能變成任意混亂的情況。"},{"en":"Clear rules prevent public access from becoming a free-for-all.","zh":"清晰規則可以防止公眾使用變成混亂失控。"},{"en":"This phrase warns against disorder, not against sharing itself.","zh":"這個說法警告的是失序，而不是共享本身。"}],"source":"2016 Q2.pdf","sourcePage":14},{"front":"a controlled partnership","meaning":"受規管的合作關係","examples":[{"en":"The scheme would be a controlled partnership.","zh":"這項計劃會是一種受規管的合作關係。"},{"en":"A controlled partnership is cooperation between groups under clear rules and supervision.","zh":"受規管的合作關係是不同群體在清晰規則和監督下合作。"},{"en":"A school and community centre can form a controlled partnership to run evening sports classes.","zh":"學校和社區中心可以建立受規管的合作關係，舉辦晚間運動班。"},{"en":"Controlled partnerships allow sharing while protecting safety and responsibility.","zh":"受規管的合作關係容許共享，同時保障安全和責任。"},{"en":"This phrase presents the scheme as organised cooperation, not uncontrolled access.","zh":"這個說法把計劃呈現為有組織合作，而不是失控使用。"}],"source":"2016 Q2.pdf","sourcePage":14},{"front":"rights come with responsibilities","meaning":"權利伴隨責任","examples":[{"en":"The scheme should show that rights come with responsibilities.","zh":"這項計劃應顯示權利伴隨責任。"},{"en":"Rights come with responsibilities means people who receive benefits or freedoms must also accept duties.","zh":"「權利伴隨責任」指享有好處或自由的人也必須承擔義務。"},{"en":"Residents may have the right to use public space, but they must keep it clean.","zh":"居民可以有使用公共空間的權利，但必須保持地方清潔。"},{"en":"If users enjoy school facilities, they should also protect them and follow the rules.","zh":"如果使用者享用學校設施，他們也應保護設施並遵守規則。"},{"en":"This phrase explains the moral balance behind shared access.","zh":"這個說法解釋共享使用背後的道德平衡。"}],"source":"2016 Q2.pdf","sourcePage":14},{"front":"all things considered","meaning":"總括而言","examples":[{"en":"All things considered, I support allowing the public to use school sports facilities.","zh":"總括而言，我支持容許公眾使用學校體育設施。"},{"en":"All things considered means after thinking about the different facts, benefits, and risks.","zh":"“All things considered” 指在考慮不同事實、好處和風險之後。"},{"en":"All things considered, sharing the hall after school is a sensible idea.","zh":"總括而言，課後共享禮堂是一個合理想法。"},{"en":"This phrase is often used before a final conclusion.","zh":"這個說法常用於最終結論之前。"},{"en":"It shows that the writer has weighed more than one side of the issue.","zh":"它顯示作者已衡量議題不只一面。"}],"source":"2016 Q2.pdf","sourcePage":14},{"front":"agree on sensible conditions","meaning":"就合理條件達成共識","examples":[{"en":"Schools, parents, and residents should agree on sensible conditions.","zh":"學校、家長和居民應就合理條件達成共識。"},{"en":"To agree on sensible conditions means to reach shared approval of reasonable rules or requirements.","zh":"「就合理條件達成共識」指大家共同同意合理規則或要求。"},{"en":"The club and school agreed on sensible conditions before using the sports hall.","zh":"體育會和學校在使用體育館前就合理條件達成共識。"},{"en":"Sensible conditions reduce conflict because everyone understands what is allowed.","zh":"合理條件可以減少衝突，因為每個人都明白甚麼是允許的。"},{"en":"This phrase shows that cooperation needs clear and reasonable agreement.","zh":"這個說法顯示合作需要清晰而合理的協議。"}],"source":"2016 Q2.pdf","sourcePage":14},{"front":"sensible conditions","meaning":"合理條件","examples":[{"en":"The scheme should operate under sensible conditions.","zh":"這項計劃應在合理條件下運作。"},{"en":"Sensible conditions are reasonable rules that protect safety, fairness, and order.","zh":"合理條件是保障安全、公平和秩序的合理規則。"},{"en":"Sensible conditions may include registration, time limits, fees, and restricted areas.","zh":"合理條件可能包括登記、時間限制、收費和限制區域。"},{"en":"A proposal is more acceptable when sensible conditions answer the main concerns.","zh":"當合理條件回應主要憂慮時，建議會更容易被接受。"},{"en":"This phrase suggests balance between openness and control.","zh":"這個說法暗示開放與管制之間的平衡。"}],"source":"2016 Q2.pdf","sourcePage":14},{"front":"Education Bureau","meaning":"教育局","examples":[{"en":"The Education Bureau should help launch pilot schemes.","zh":"教育局應協助推出試驗計劃。"},{"en":"The Education Bureau is the government body responsible for education policy and school matters.","zh":"教育局是負責教育政策和學校事務的政府部門。"},{"en":"The Education Bureau can provide guidelines for schools joining the scheme.","zh":"教育局可以為參與計劃的學校提供指引。"},{"en":"If the Education Bureau supports pilot schemes, schools may feel more confident about safety and responsibility.","zh":"如果教育局支持試驗計劃，學校可能對安全和責任安排更有信心。"},{"en":"This phrase identifies the official body that could guide the proposal.","zh":"這個說法指出可以指導建議的官方機構。"}],"source":"2016 Q2.pdf","sourcePage":14},{"front":"district councils","meaning":"區議會","examples":[{"en":"District councils should work with schools on pilot schemes.","zh":"區議會應與學校合作推行試驗計劃。"},{"en":"District councils are local bodies that deal with community issues and district-level concerns.","zh":"區議會是處理社區議題和地區層面關注的本地機構。"},{"en":"District councils can help identify which neighbourhoods most need sports facilities.","zh":"區議會可以協助找出哪些社區最需要體育設施。"},{"en":"Working with district councils helps connect school resources with local residents’ needs.","zh":"與區議會合作，有助把學校資源與本地居民需要連接起來。"},{"en":"This phrase shows that community planning should involve local representatives.","zh":"這個說法顯示社區規劃應包括本地代表。"}],"source":"2016 Q2.pdf","sourcePage":14},{"front":"school management committees","meaning":"學校管理委員會","examples":[{"en":"School management committees should help review the scheme.","zh":"學校管理委員會應協助檢討計劃。"},{"en":"School management committees are groups that help oversee school policy, administration, and development.","zh":"學校管理委員會是協助監督學校政策、行政和發展的組織。"},{"en":"A school management committee may discuss whether facilities can be opened safely.","zh":"學校管理委員會可以討論設施能否安全開放。"},{"en":"These committees can review the scheme because they understand school needs and responsibilities.","zh":"這些委員會可以檢討計劃，因為它們了解學校需要和責任。"},{"en":"This phrase identifies a school-level decision-making body.","zh":"這個說法指出學校層面的決策組織。"}],"source":"2016 Q2.pdf","sourcePage":14},{"front":"work together to","meaning":"合作去……","examples":[{"en":"The Education Bureau, district councils, and schools should work together to launch pilot schemes.","zh":"教育局、區議會和學校應合作去推出試驗計劃。"},{"en":"To work together to do something means different groups cooperate to achieve the same goal.","zh":"“Work together to” 指不同群體合作以達成同一目標。"},{"en":"Parents and teachers work together to support students during exams.","zh":"家長和老師合作去支援學生應付考試。"},{"en":"Public schemes are stronger when government bodies and local schools work together.","zh":"當政府部門和本地學校合作時，公共計劃會更穩固。"},{"en":"This phrase emphasises cooperation instead of leaving the task to one side.","zh":"這個說法強調合作，而不是把任務留給單方面。"}],"source":"2016 Q2.pdf","sourcePage":14},{"front":"launch pilot schemes","meaning":"推出試驗計劃","examples":[{"en":"The authorities should launch pilot schemes in selected schools.","zh":"當局應在選定學校推出試驗計劃。"},{"en":"To launch pilot schemes means to start small trial programmes before deciding whether to expand them.","zh":"「推出試驗計劃」指先開始小規模試行項目，再決定是否擴展。"},{"en":"The city launched pilot schemes for weekend library opening hours.","zh":"政府推出週末圖書館開放時間的試驗計劃。"},{"en":"Pilot schemes help identify problems before a policy is used everywhere.","zh":"試驗計劃有助在政策全面推行前找出問題。"},{"en":"This phrase suggests a careful way to test a new idea.","zh":"這個說法提出一種小心測試新想法的方法。"}],"source":"2016 Q2.pdf","sourcePage":15},{"front":"selected schools","meaning":"選定學校","examples":[{"en":"Pilot schemes could begin in selected schools.","zh":"試驗計劃可以在選定學校開始。"},{"en":"Selected schools are schools chosen for a particular programme or purpose.","zh":"選定學校是為某個計劃或目的而被挑選的學校。"},{"en":"Selected schools may be chosen because they have suitable facilities and supportive communities.","zh":"選定學校可能因具備合適設施和支持計劃的社區而被選中。"},{"en":"Starting with selected schools reduces risk because the scheme can be tested in manageable places.","zh":"先在選定學校開始可以減少風險，因為計劃可在較易管理的地方測試。"},{"en":"This phrase shows that the plan can begin gradually.","zh":"這個說法顯示計劃可以逐步開始。"}],"source":"2016 Q2.pdf","sourcePage":15},{"front":"consult parent-teacher associations","meaning":"諮詢家長教師會","examples":[{"en":"Schools should consult parent-teacher associations before opening facilities.","zh":"學校開放設施前應諮詢家長教師會。"},{"en":"To consult parent-teacher associations means to ask groups of parents and teachers for views before making a decision.","zh":"「諮詢家長教師會」指在作決定前向家長和老師組成的團體徵詢意見。"},{"en":"The school consulted the parent-teacher association about weekend hall use.","zh":"學校就週末使用禮堂諮詢家長教師會。"},{"en":"Consulting parents and teachers can reveal safety concerns that planners may miss.","zh":"諮詢家長和老師可以發現規劃者可能忽略的安全憂慮。"},{"en":"This phrase shows that school decisions should include stakeholders’ opinions.","zh":"這個說法顯示學校決定應包括持份者意見。"}],"source":"2016 Q2.pdf","sourcePage":15},{"front":"parent-teacher associations","meaning":"家長教師會","examples":[{"en":"Parent-teacher associations should be consulted.","zh":"家長教師會應被諮詢。"},{"en":"Parent-teacher associations are groups that bring parents and teachers together to discuss school matters.","zh":"家長教師會是把家長和老師聚在一起討論學校事務的組織。"},{"en":"Parent-teacher associations may give advice on safety, student needs, and communication with families.","zh":"家長教師會可以就安全、學生需要和與家庭溝通提供意見。"},{"en":"Consulting parent-teacher associations can build trust before a new policy begins.","zh":"在新政策開始前諮詢家長教師會，可以建立信任。"},{"en":"This phrase identifies an important school-community group.","zh":"這個說法指出一個重要的學校與社區團體。"}],"source":"2016 Q2.pdf","sourcePage":15},{"front":"review the results","meaning":"檢討成效","examples":[{"en":"The authorities should review the results after several months.","zh":"當局應在數個月後檢討成效。"},{"en":"To review the results means to examine what happened and judge whether the scheme worked well.","zh":"「檢討成效」指檢視發生了甚麼，並判斷計劃是否運作良好。"},{"en":"After the trial, the school reviewed the results and changed the booking rules.","zh":"試行後，學校檢討成效並修改預訂規則。"},{"en":"Reviewing the results helps people improve a plan instead of guessing whether it succeeded.","zh":"檢討成效幫助人們改善計劃，而不是憑猜測判斷是否成功。"},{"en":"This phrase is important for testing and improving public policies.","zh":"這個說法對測試和改善公共政策很重要。"}],"source":"2016 Q2.pdf","sourcePage":15},{"front":"after several months","meaning":"數個月後","examples":[{"en":"The pilot scheme should be reviewed after several months.","zh":"試驗計劃應在數個月後檢討。"},{"en":"After several months means when a few months have passed.","zh":"“After several months” 指幾個月過去之後。"},{"en":"After several months, the school had enough information to judge the booking system.","zh":"數個月後，學校已有足夠資料判斷預訂系統。"},{"en":"A pilot scheme should not be judged after only one week; reviewing it after several months is fairer.","zh":"試驗計劃不應只在一星期後評估；數個月後檢討會更公平。"},{"en":"This phrase gives time for real patterns and problems to appear.","zh":"這個說法給予時間讓真實模式和問題出現。"}],"source":"2016 Q2.pdf","sourcePage":15},{"front":"shortage of sports facilities","meaning":"體育設施短缺","examples":[{"en":"The shortage of sports facilities will not disappear overnight.","zh":"體育設施短缺不會一夜之間消失。"},{"en":"A shortage of sports facilities means there are not enough places or equipment for people to exercise or play sport.","zh":"體育設施短缺指沒有足夠地方或設備讓人運動或比賽。"},{"en":"A district may face a shortage of sports facilities if every public court is fully booked.","zh":"如果每個公共球場都預訂已滿，該區可能面對體育設施短缺。"},{"en":"The shortage of sports facilities can stop residents from exercising regularly.","zh":"體育設施短缺可能阻止居民定期做運動。"},{"en":"This phrase identifies the main community problem behind the proposal.","zh":"這個說法指出建議背後的主要社區問題。"}],"source":"2016 Q2.pdf","sourcePage":15},{"front":"disappear overnight","meaning":"一夜之間消失","examples":[{"en":"The shortage will not disappear overnight.","zh":"短缺不會一夜之間消失。"},{"en":"Disappear overnight means go away suddenly or very quickly.","zh":"“Disappear overnight” 指突然或非常快速地消失。"},{"en":"Traffic problems will not disappear overnight simply because one road is widened.","zh":"交通問題不會只因一條道路擴闊便一夜之間消失。"},{"en":"Since the shortage will not disappear overnight, temporary and practical solutions are needed.","zh":"既然短缺不會一夜之間消失，便需要暫時而實際的解決方法。"},{"en":"This phrase reminds readers that long-term problems need realistic action.","zh":"這個說法提醒讀者，長期問題需要現實行動。"}],"source":"2016 Q2.pdf","sourcePage":15},{"front":"need not wait passively for","meaning":"不必被動等待……","examples":[{"en":"We need not wait passively for a perfect solution.","zh":"我們不必被動等待完美解決方案。"},{"en":"Need not wait passively for means do not have to do nothing while hoping someone else solves the problem.","zh":"“Need not wait passively for” 指不需要甚麼都不做，只是希望別人解決問題。"},{"en":"Residents need not wait passively for a new park; they can suggest using existing halls.","zh":"居民不必被動等待新公園；他們可以建議使用現有禮堂。"},{"en":"This phrase encourages practical action instead of helpless waiting.","zh":"這個說法鼓勵實際行動，而不是無助等待。"},{"en":"It shows that an imperfect but useful solution may still be worth trying.","zh":"它顯示即使方案不完美，只要有用仍值得嘗試。"}],"source":"2016 Q2.pdf","sourcePage":15},{"front":"a perfect solution","meaning":"完美解決方案","examples":[{"en":"We should not wait passively for a perfect solution.","zh":"我們不應被動等待完美解決方案。"},{"en":"A perfect solution is an answer that solves every problem without any weakness or cost.","zh":"完美解決方案是能解決所有問題，而且沒有弱點或成本的答案。"},{"en":"A perfect solution may be impossible when money, land, and time are limited.","zh":"當金錢、土地和時間有限時，完美解決方案可能不可能出現。"},{"en":"Waiting for a perfect solution can delay smaller improvements that are already possible.","zh":"等待完美解決方案，可能會拖延已經可行的小改善。"},{"en":"This phrase warns against refusing action because no plan is flawless.","zh":"這個說法提醒我們，不應因沒有零缺點方案而拒絕行動。"}],"source":"2016 Q2.pdf","sourcePage":15},{"front":"the time has come to","meaning":"是時候……","examples":[{"en":"The time has come to open our school gates wisely.","zh":"是時候明智地開放我們的校門。"},{"en":"The time has come to means now is the right moment to do something.","zh":"“The time has come to” 指現在正是做某事的合適時候。"},{"en":"The time has come to make better use of empty public spaces.","zh":"是時候更好地運用空置公共空間。"},{"en":"This phrase gives a strong sense of urgency and conclusion.","zh":"這個說法帶有強烈的迫切感和結論感。"},{"en":"It is useful near the end of a persuasive letter when calling for action.","zh":"它適合在說服性信件結尾附近呼籲行動時使用。"}],"source":"2016 Q2.pdf","sourcePage":16},{"front":"wisely, safely and generously","meaning":"明智、安全而慷慨地","examples":[{"en":"Schools should open their gates wisely, safely, and generously.","zh":"學校應明智、安全而慷慨地開放校門。"},{"en":"Wisely, safely and generously means with good judgement, proper protection, and willingness to share.","zh":"“Wisely, safely and generously” 指帶着良好判斷、適當保護和願意分享的態度。"},{"en":"A community centre should serve residents wisely, safely and generously.","zh":"社區中心應明智、安全而慷慨地服務居民。"},{"en":"Opening facilities wisely means planning rules; safely means reducing risks; generously means remembering public need.","zh":"明智地開放代表規劃規則；安全地開放代表減低風險；慷慨地開放代表記得公眾需要。"},{"en":"This phrase balances caution with community spirit.","zh":"這個說法平衡謹慎和社區精神。"}],"source":"2016 Q2.pdf","sourcePage":16},{"front":"Yours faithfully","meaning":"謹啟","examples":[{"en":"Yours faithfully, Chris Wong.","zh":"Chris Wong 謹啟。"},{"en":"Yours faithfully is a formal closing used at the end of a letter, especially when the writer does not know the recipient’s name.","zh":"“Yours faithfully” 是正式信件結尾用語，尤其在作者不知道收件人姓名時使用。"},{"en":"A letter to the editor may end with Yours faithfully before the writer’s name.","zh":"致編輯的信可以在作者姓名前以 “Yours faithfully” 作結。"},{"en":"This closing keeps the tone respectful and formal.","zh":"這個結尾語保持尊重和正式語氣。"},{"en":"In formal letter writing, the closing should match the greeting and purpose.","zh":"在正式書信寫作中，結尾語應配合稱呼和寫信目的。"}],"source":"2016 Q2.pdf","sourcePage":16},{"front":"a concerned resident","meaning":"一名關心社區的居民","examples":[{"en":"Chris Wong signs the letter as a concerned resident.","zh":"Chris Wong 以一名關心社區的居民身份署名。"},{"en":"A concerned resident is a local person who cares about problems affecting the community.","zh":"一名關心社區的居民，是關心影響社區問題的本地人士。"},{"en":"A concerned resident may write to the newspaper about traffic, noise, or public facilities.","zh":"一名關心社區的居民可能會就交通、噪音或公共設施寫信給報章。"},{"en":"Calling oneself a concerned resident shows civic care rather than personal complaint only.","zh":"稱自己為關心社區的居民，顯示這不只是個人投訴，而是公民關懷。"},{"en":"This phrase gives the writer a public and community-minded identity.","zh":"這個說法給作者一個公共而關心社區的身份。"}],"source":"2016 Q2.pdf","sourcePage":16}],"dse/writing/part-b/2016/Q3":[{"front":"beyond Hong Kong","meaning":"香港以外","examples":[{"en":"Graduates should look beyond Hong Kong for career opportunities.","zh":"畢業生應該在香港以外尋找事業機會。"},{"en":"Beyond Hong Kong means outside Hong Kong or wider than the local job market.","zh":"香港以外意思是本地就業市場之外，或比香港更廣闊的地方。"},{"en":"A graduate may look beyond Hong Kong when local jobs are limited.","zh":"當本地工作有限時，畢業生可能會放眼香港以外。"},{"en":"Looking beyond Hong Kong can help young people discover industries they did not expect.","zh":"放眼香港以外可以幫助年輕人發現意想不到的行業。"},{"en":"Beyond Hong Kong does not mean forgetting Hong Kong; it means widening the search.","zh":"香港以外不代表忘記香港，而是擴闊尋找範圍。"}],"source":"2016 Q3.pdf","sourcePage":1},{"front":"look across Asia","meaning":"放眼亞洲","examples":[{"en":"Hong Kong graduates should look across Asia for meaningful first jobs.","zh":"香港畢業生應放眼亞洲，尋找有意義的第一份工作。"},{"en":"To look across Asia means to search different Asian cities or countries for opportunities.","zh":"放眼亞洲意思是在不同亞洲城市或國家尋找機會。"},{"en":"A graduate may look across Asia when Hong Kong’s job market feels too crowded.","zh":"當香港就業市場太擠迫時，畢業生可能會放眼亞洲。"},{"en":"Looking across Asia can reveal openings in technology, finance, tourism, and design.","zh":"放眼亞洲可以發現科技、金融、旅遊和設計方面的空缺。"},{"en":"Students who look across Asia may find that their skills fit another city’s needs.","zh":"放眼亞洲的學生可能會發現自己的技能配合另一個城市的需要。"}],"source":"2016 Q3.pdf","sourcePage":1},{"front":"graduation season","meaning":"畢業季節","examples":[{"en":"Every graduation season, the same uneasy question returns.","zh":"每到畢業季節，同一個令人不安的問題又會回來。"},{"en":"Graduation season is the time of year when students finish school or university.","zh":"畢業季節是一年中學生完成中學或大學課程的時候。"},{"en":"During graduation season, many young people begin sending job applications.","zh":"在畢業季節，許多年輕人開始寄出求職申請。"},{"en":"Graduation season can feel exciting, but it can also bring pressure about the future.","zh":"畢業季節可以令人興奮，但也會帶來對未來的壓力。"},{"en":"Career planning becomes especially important during graduation season.","zh":"在畢業季節，事業規劃變得特別重要。"}],"source":"2016 Q3.pdf","sourcePage":1},{"front":"uneasy question","meaning":"令人不安的問題","examples":[{"en":"The same uneasy question returns to our city every year.","zh":"同一個令人不安的問題每年都回到我們的城市。"},{"en":"An uneasy question is a question that makes people worried or uncomfortable.","zh":"令人不安的問題是令人擔心或不舒服的問題。"},{"en":"“Will I find a good job?” is an uneasy question for many graduates.","zh":"「我會找到好工作嗎？」對許多畢業生來說是令人不安的問題。"},{"en":"Uneasy questions often appear when the future is uncertain.","zh":"當未來不確定時，令人不安的問題常會出現。"},{"en":"A society should answer uneasy questions with support, not silence.","zh":"社會應以支援回應令人不安的問題，而不是沉默。"}],"source":"2016 Q3.pdf","sourcePage":1},{"front":"after years of study","meaning":"經過多年學習後","examples":[{"en":"After years of study, graduates hope to find meaningful work.","zh":"經過多年學習後，畢業生希望找到有意義的工作。"},{"en":"After years of study means after spending many years learning in school or university.","zh":"經過多年學習後，意思是在學校或大學花了多年學習之後。"},{"en":"After years of study, a student may feel eager to use their knowledge in real work.","zh":"經過多年學習後，學生可能渴望把知識用於真實工作。"},{"en":"Graduates may feel disappointed if years of study do not lead to fair opportunities.","zh":"如果多年學習沒有帶來公平機會，畢業生可能會失望。"},{"en":"The phrase shows that graduates have already invested time and effort.","zh":"這個短語顯示畢業生已投入時間和努力。"}],"source":"2016 Q3.pdf","sourcePage":1},{"front":"meaningful first job","meaning":"有意義的第一份工作","examples":[{"en":"Young people want to find a meaningful first job.","zh":"年輕人想找到有意義的第一份工作。"},{"en":"A meaningful first job is a first full-time role that gives purpose, learning, or useful experience.","zh":"有意義的第一份工作，是指能帶來目標、學習或有用經驗的第一份全職工作。"},{"en":"A graduate may find a meaningful first job in a company that trains young workers well.","zh":"畢業生可能在願意良好培訓年輕人的公司找到有意義的第一份工作。"},{"en":"A meaningful first job does not have to be perfect, but it should help a person grow.","zh":"有意義的第一份工作不必完美，但應幫助人成長。"},{"en":"Finding such a job can give graduates confidence at the start of their careers.","zh":"找到這樣的工作可以給畢業生事業初期的信心。"}],"source":"2016 Q3.pdf","sourcePage":1},{"front":"face fierce competition","meaning":"面對激烈競爭","examples":[{"en":"Many Hong Kong graduates face fierce competition.","zh":"許多香港畢業生面對激烈競爭。"},{"en":"To face fierce competition means to compete with many strong candidates for limited opportunities.","zh":"面對激烈競爭意思是與許多強勁候選人爭取有限機會。"},{"en":"Fresh graduates face fierce competition when hundreds apply for the same trainee post.","zh":"當數百人申請同一個見習職位時，應屆畢業生便面對激烈競爭。"},{"en":"Fierce competition can make even capable young people feel anxious.","zh":"激烈競爭可以令有能力的年輕人也感到焦慮。"},{"en":"Looking beyond Hong Kong can reduce pressure when local competition is too intense.","zh":"當本地競爭太激烈時，放眼香港以外可以減輕壓力。"}],"source":"2016 Q3.pdf","sourcePage":1},{"front":"career advisers","meaning":"就業輔導人員","examples":[{"en":"Schools and career advisers have begun to consider overseas options.","zh":"學校和就業輔導人員已開始考慮海外選項。"},{"en":"Career advisers are people who help students or workers plan jobs and careers.","zh":"就業輔導人員是幫助學生或工作者規劃工作和事業的人。"},{"en":"A career adviser may help a graduate improve a CV and prepare for interviews.","zh":"就業輔導人員可能幫助畢業生改善履歷和準備面試。"},{"en":"Career advisers can introduce students to opportunities in other Asian cities.","zh":"就業輔導人員可以向學生介紹其他亞洲城市的機會。"},{"en":"Good career advisers help students see more than one possible path.","zh":"好的就業輔導人員幫助學生看見不止一條可能道路。"}],"source":"2016 Q3.pdf","sourcePage":1},{"front":"consider encouraging","meaning":"考慮鼓勵","examples":[{"en":"Schools have begun to consider encouraging graduates to explore other cities.","zh":"學校已開始考慮鼓勵畢業生探索其他城市。"},{"en":"To consider encouraging someone means to think seriously about advising them to do something.","zh":"考慮鼓勵某人，意思是認真思考是否建議他們做某事。"},{"en":"Teachers may consider encouraging students to apply for regional internships.","zh":"老師可能會考慮鼓勵學生申請區域實習。"},{"en":"Schools consider this option because the local job market may not absorb everyone.","zh":"學校考慮這個選項，因為本地就業市場未必能吸收所有人。"},{"en":"Before encouraging graduates, schools should provide information and support.","zh":"在鼓勵畢業生前，學校應提供資訊和支援。"}],"source":"2016 Q3.pdf","sourcePage":1},{"front":"cannot secure local employment","meaning":"未能找到本地工作","examples":[{"en":"Some graduates cannot secure local employment immediately.","zh":"有些畢業生未能立即找到本地工作。"},{"en":"Cannot secure local employment means cannot successfully get a job in the local market.","zh":"未能找到本地工作意思是未能成功在本地市場獲得工作。"},{"en":"A graduate may not secure local employment if too many people apply for the same posts.","zh":"如果太多人申請同類職位，畢業生可能未能找到本地工作。"},{"en":"Failing to secure local work immediately does not mean the graduate has no ability.","zh":"未能立即找到本地工作，不代表畢業生沒有能力。"},{"en":"Other Asian cities may offer options when local employment is difficult to secure.","zh":"當本地工作難以取得時，其他亞洲城市可能提供選項。"}],"source":"2016 Q3.pdf","sourcePage":1},{"front":"explore other Asian cities","meaning":"探索其他亞洲城市","examples":[{"en":"Graduates should explore other Asian cities for job opportunities.","zh":"畢業生應探索其他亞洲城市的工作機會。"},{"en":"To explore other Asian cities means to research and consider work in different cities across Asia.","zh":"探索其他亞洲城市意思是研究和考慮亞洲不同城市的工作。"},{"en":"A design graduate may explore Seoul, Taipei, or Bangkok for creative roles.","zh":"設計畢業生可能探索首爾、台北或曼谷的創意職位。"},{"en":"Exploring other cities helps graduates understand wider markets and cultures.","zh":"探索其他城市幫助畢業生了解更廣闊市場和文化。"},{"en":"Graduates should explore carefully before deciding where to work.","zh":"畢業生應仔細探索，再決定到哪裏工作。"}],"source":"2016 Q3.pdf","sourcePage":2},{"front":"widen their choices","meaning":"擴闊選擇","examples":[{"en":"Working elsewhere can help graduates widen their choices.","zh":"到其他地方工作可以幫助畢業生擴闊選擇。"},{"en":"To widen their choices means to increase the number of options available to them.","zh":"擴闊選擇意思是增加可供選擇的選項數量。"},{"en":"Applying to jobs in Singapore and Shenzhen can widen a graduate’s choices.","zh":"申請新加坡和深圳的工作可以擴闊畢業生的選擇。"},{"en":"Wider choices reduce the fear of being trapped in one crowded market.","zh":"更廣闊的選擇能減少被困於一個擠迫市場的恐懼。"},{"en":"Graduates widen their choices when they look beyond one city.","zh":"畢業生放眼一個城市以外時，就是在擴闊選擇。"}],"source":"2016 Q3.pdf","sourcePage":2},{"front":"build stronger careers","meaning":"建立更穩固的事業","examples":[{"en":"Graduates can widen their choices and build stronger careers.","zh":"畢業生可以擴闊選擇，並建立更穩固的事業。"},{"en":"To build stronger careers means to develop more stable, skilled, and successful working lives.","zh":"建立更穩固的事業意思是發展更穩定、更有技能和更成功的工作人生。"},{"en":"Regional experience can help graduates build stronger careers by giving them wider skills.","zh":"區域經驗可以透過提供更廣泛技能，幫助畢業生建立更穩固的事業。"},{"en":"A stronger career grows through learning, risk-taking, and useful experience.","zh":"更穩固的事業透過學習、冒險和有用經驗而成長。"},{"en":"Graduates build stronger careers when they choose opportunities that help them grow.","zh":"畢業生選擇能幫助自己成長的機會時，就是在建立更穩固的事業。"}],"source":"2016 Q3.pdf","sourcePage":2},{"front":"as far as I am concerned","meaning":"就我而言","examples":[{"en":"As far as I am concerned, this suggestion deserves our firm support.","zh":"就我而言，這項建議值得我們堅定支持。"},{"en":"As far as I am concerned means in my opinion or from my point of view.","zh":"就我而言意思是以我的看法或角度來說。"},{"en":"As far as I am concerned, students should not fear exploring other cities.","zh":"就我而言，學生不應害怕探索其他城市。"},{"en":"This phrase is useful when introducing a personal but reasoned view.","zh":"這個短語適合用來引出個人但有理由支持的看法。"},{"en":"In an essay, it helps the writer state a clear position.","zh":"在文章中，它幫助作者清楚表明立場。"}],"source":"2016 Q3.pdf","sourcePage":2},{"front":"deserves our firm support","meaning":"值得我們堅定支持","examples":[{"en":"The suggestion deserves our firm support.","zh":"這項建議值得我們堅定支持。"},{"en":"Deserves our firm support means it is worthy of strong approval and encouragement.","zh":"值得我們堅定支持意思是它值得強烈認同和鼓勵。"},{"en":"A policy that helps graduates find real opportunities deserves firm support.","zh":"一項幫助畢業生找到真正機會的政策值得堅定支持。"},{"en":"The suggestion deserves support because it responds to a crowded job market.","zh":"這項建議值得支持，因為它回應了擠迫的就業市場。"},{"en":"Firm support should include practical guidance, not only words.","zh":"堅定支持應包括實際指導，而不只是說話。"}],"source":"2016 Q3.pdf","sourcePage":2},{"front":"looking beyond Hong Kong","meaning":"放眼香港以外","examples":[{"en":"Looking beyond Hong Kong is not a confession of failure.","zh":"放眼香港以外並不是承認失敗。"},{"en":"Looking beyond Hong Kong means considering opportunities outside the city.","zh":"放眼香港以外意思是考慮城市以外的機會。"},{"en":"A graduate looks beyond Hong Kong when they apply for jobs in Singapore or Tokyo.","zh":"當畢業生申請新加坡或東京的工作時，就是放眼香港以外。"},{"en":"Looking beyond Hong Kong can be a sign of courage and planning.","zh":"放眼香港以外可以是勇氣和規劃的表現。"},{"en":"It is not rejection of home, but a wider search for growth.","zh":"這不是拒絕家園，而是更廣闊地尋找成長。"}],"source":"2016 Q3.pdf","sourcePage":2},{"front":"a confession of failure","meaning":"承認失敗","examples":[{"en":"Looking beyond Hong Kong is not a confession of failure.","zh":"放眼香港以外並不是承認失敗。"},{"en":"A confession of failure means an admission that one has failed.","zh":"承認失敗意思是承認自己已經失敗。"},{"en":"Applying overseas is not a confession of failure; it may be a smart career move.","zh":"申請海外工作不是承認失敗；它可能是明智的事業選擇。"},{"en":"Graduates should not treat unemployment as a confession of failure.","zh":"畢業生不應把失業視為承認失敗。"},{"en":"Sometimes a new direction is a strategy, not a confession of failure.","zh":"有時新方向是一種策略，而不是承認失敗。"}],"source":"2016 Q3.pdf","sourcePage":2},{"front":"rather","meaning":"反而；更準確地說","examples":[{"en":"Rather, it is a practical response to a crowded market.","zh":"更準確地說，這是對擠迫市場的實際回應。"},{"en":"Rather introduces a better or more accurate way to understand something.","zh":"Rather 用來引出更好或更準確的理解方式。"},{"en":"Leaving for work is not giving up; rather, it can be a way to grow.","zh":"到外地工作不是放棄；反而，它可以是成長的方法。"},{"en":"Writers use rather to correct a possible misunderstanding.","zh":"作者使用 rather 來糾正可能的誤解。"},{"en":"This word helps shift an argument from a negative view to a fairer one.","zh":"這個詞幫助把論點由負面看法轉向更公平的看法。"}],"source":"2016 Q3.pdf","sourcePage":2},{"front":"practical response to","meaning":"對……的實際回應","examples":[{"en":"Looking beyond Hong Kong is a practical response to a crowded market.","zh":"放眼香港以外是對擠迫市場的實際回應。"},{"en":"A practical response to something is a realistic action that deals with a problem.","zh":"對某事的實際回應，是指處理問題的現實行動。"},{"en":"Applying to regional jobs is a practical response to limited local openings.","zh":"申請區域工作是對本地空缺有限的實際回應。"},{"en":"A practical response focuses on what can be done, not only what is ideal.","zh":"實際回應重視可以做甚麼，而不只是理想上應怎樣。"},{"en":"Graduates need practical responses when the job market becomes difficult.","zh":"當就業市場變得困難時，畢業生需要實際回應。"}],"source":"2016 Q3.pdf","sourcePage":2},{"front":"crowded market","meaning":"擠迫的市場","examples":[{"en":"Hong Kong graduates are facing a crowded job market.","zh":"香港畢業生正面對擠迫的就業市場。"},{"en":"A crowded market is a market with too many people competing for limited opportunities.","zh":"擠迫的市場是有太多人競爭有限機會的市場。"},{"en":"A crowded job market may have hundreds of applicants for one entry-level role.","zh":"擠迫的就業市場可能有數百人申請一個入門職位。"},{"en":"In a crowded market, even strong candidates may wait longer for work.","zh":"在擠迫的市場中，即使強勁候選人也可能要等更久才有工作。"},{"en":"Looking across Asia can help graduates move beyond a crowded market.","zh":"放眼亞洲可以幫助畢業生走出擠迫的市場。"}],"source":"2016 Q3.pdf","sourcePage":2},{"front":"I would argue that","meaning":"我會主張","examples":[{"en":"I would argue that graduates should consider other Asian cities.","zh":"我會主張畢業生應考慮其他亞洲城市。"},{"en":"I would argue that means I will give reasons to support this view.","zh":"我會主張意思是我會提出理由支持這個看法。"},{"en":"I would argue that students need wider choices, not only local options.","zh":"我會主張學生需要更廣闊選擇，而不只是本地選項。"},{"en":"This phrase is useful when presenting a reasoned opinion in an essay.","zh":"這個短語適合在文章中提出有理由支持的意見。"},{"en":"It sounds confident but still thoughtful.","zh":"它聽起來有信心，同時仍然有思考。"}],"source":"2016 Q3.pdf","sourcePage":3},{"front":"expands their opportunities","meaning":"擴大他們的機會","examples":[{"en":"Working in other Asian cities expands graduates’ opportunities.","zh":"在其他亞洲城市工作會擴大畢業生的機會。"},{"en":"To expand opportunities means to increase the number or range of possible choices.","zh":"擴大機會意思是增加可能選擇的數量或範圍。"},{"en":"Applying to jobs in different cities expands a graduate’s opportunities beyond Hong Kong.","zh":"申請不同城市的工作會把畢業生的機會擴大到香港以外。"},{"en":"Opportunities expand when students search in larger and more varied markets.","zh":"當學生在更大和更多元的市場尋找時，機會會擴大。"},{"en":"Regional work can expand opportunities for learning, income, and growth.","zh":"區域工作可以擴大學習、收入和成長的機會。"}],"source":"2016 Q3.pdf","sourcePage":3},{"front":"sharpens their professional abilities","meaning":"提升他們的專業能力","examples":[{"en":"Working elsewhere sharpens graduates’ professional abilities.","zh":"到其他地方工作會提升畢業生的專業能力。"},{"en":"To sharpen professional abilities means to improve work-related skills through real experience.","zh":"提升專業能力意思是透過真實經驗改善與工作相關的技能。"},{"en":"Handling clients abroad can sharpen a graduate’s communication skills.","zh":"在海外接待客戶可以提升畢業生的溝通能力。"},{"en":"Difficult tasks sharpen professional abilities because workers must adapt and solve problems.","zh":"困難任務會提升專業能力，因為工作者必須適應和解決問題。"},{"en":"Regional experience sharpens abilities that classrooms cannot fully train.","zh":"區域經驗能提升課室未能完全訓練的能力。"}],"source":"2016 Q3.pdf","sourcePage":3},{"front":"in the long run","meaning":"長遠而言","examples":[{"en":"In the long run, regional experience can benefit Hong Kong itself.","zh":"長遠而言，區域經驗可以對香港本身有利。"},{"en":"In the long run means over a long period of time, not immediately.","zh":"長遠而言意思是在較長時間之後，而不是立即。"},{"en":"Learning another language may be difficult now, but it helps in the long run.","zh":"學習另一種語言現在可能困難，但長遠而言有幫助。"},{"en":"Working abroad can benefit Hong Kong in the long run when graduates return with skills.","zh":"當畢業生帶著技能回來時，海外工作長遠而言可以有利香港。"},{"en":"This phrase helps writers discuss future results.","zh":"這個短語幫助作者討論未來結果。"}],"source":"2016 Q3.pdf","sourcePage":3},{"front":"benefits Hong Kong itself","meaning":"對香港本身有利","examples":[{"en":"Graduates’ regional experience can benefit Hong Kong itself.","zh":"畢業生的區域經驗可以對香港本身有利。"},{"en":"To benefit Hong Kong itself means to help the city directly or indirectly.","zh":"對香港本身有利意思是直接或間接幫助這個城市。"},{"en":"A graduate who brings back market knowledge can benefit Hong Kong’s companies.","zh":"帶回市場知識的畢業生可以令香港公司受益。"},{"en":"Overseas experience benefits Hong Kong when it creates bridges with other cities.","zh":"當海外經驗建立與其他城市的橋樑時，它就對香港有利。"},{"en":"The city gains when its people grow beyond local borders.","zh":"當香港人超越本地界限成長，城市也會得益。"}],"source":"2016 Q3.pdf","sourcePage":3},{"front":"first and foremost","meaning":"首先；最重要的是","examples":[{"en":"First and foremost, Asia offers a wider employment market.","zh":"首先，亞洲提供更廣闊的就業市場。"},{"en":"First and foremost means most importantly before anything else.","zh":"首先或最重要的是，意思是在其他事情之前最重要的一點。"},{"en":"First and foremost, graduates need real opportunities to start their careers.","zh":"首先，畢業生需要真正機會開始事業。"},{"en":"Writers use this phrase to introduce their strongest first reason.","zh":"作者使用這個短語來引出最有力的第一個理由。"},{"en":"It helps readers know which point matters most.","zh":"它幫助讀者知道哪一點最重要。"}],"source":"2016 Q3.pdf","sourcePage":3},{"front":"a wider and more varied employment market","meaning":"更廣闊和更多元的就業市場","examples":[{"en":"Asia offers a wider and more varied employment market.","zh":"亞洲提供更廣闊和更多元的就業市場。"},{"en":"A wider and more varied employment market has more jobs, industries, and types of roles.","zh":"更廣闊和更多元的就業市場有更多工作、行業和職位類型。"},{"en":"Graduates may find finance in Singapore, design in Seoul, and technology in Shenzhen.","zh":"畢業生可能在新加坡找到金融工作，在首爾找到設計工作，在深圳找到科技工作。"},{"en":"A varied market helps different talents find suitable places.","zh":"多元市場幫助不同人才找到合適位置。"},{"en":"Asia’s wider market can reduce pressure from Hong Kong’s limited openings.","zh":"亞洲更廣闊的市場可以減輕香港有限空缺帶來的壓力。"}],"source":"2016 Q3.pdf","sourcePage":3},{"front":"Hong Kong alone","meaning":"單靠香港","examples":[{"en":"Asia offers more opportunities than Hong Kong alone can provide.","zh":"亞洲提供的機會比單靠香港能提供的更多。"},{"en":"Hong Kong alone means only Hong Kong, without considering other places.","zh":"單靠香港意思是只考慮香港，而不考慮其他地方。"},{"en":"Hong Kong alone may not have enough entry-level posts for every graduate.","zh":"單靠香港未必有足夠入門職位給每位畢業生。"},{"en":"Students limit themselves if they consider Hong Kong alone.","zh":"如果學生只考慮香港，他們會限制自己。"},{"en":"Looking beyond Hong Kong alone can reveal a much larger career map.","zh":"放眼單靠香港以外，可以看見大得多的事業地圖。"}],"source":"2016 Q3.pdf","sourcePage":3},{"front":"dynamic","meaning":"充滿活力的","examples":[{"en":"Hong Kong is dynamic, but it is also small.","zh":"香港充滿活力，但同時也很小。"},{"en":"Dynamic means active, energetic, and full of change.","zh":"充滿活力的意思是活躍、有能量，並充滿變化。"},{"en":"A dynamic city offers new ideas, businesses, and cultural activities.","zh":"充滿活力的城市提供新想法、商業和文化活動。"},{"en":"Hong Kong is dynamic because finance, tourism, education, and technology keep changing.","zh":"香港充滿活力，因為金融、旅遊、教育和科技不斷改變。"},{"en":"A dynamic place can still be too small to offer enough jobs for everyone.","zh":"充滿活力的地方仍可能太小，無法為所有人提供足夠工作。"}],"source":"2016 Q3.pdf","sourcePage":3},{"front":"fresh graduates","meaning":"應屆畢業生","examples":[{"en":"Thousands of fresh graduates compete for similar entry-level posts.","zh":"數以千計應屆畢業生競爭相似的入門職位。"},{"en":"Fresh graduates are people who have recently finished school or university.","zh":"應屆畢業生是剛完成中學或大學學業的人。"},{"en":"Fresh graduates often look for their first full-time job.","zh":"應屆畢業生通常尋找第一份全職工作。"},{"en":"They may lack experience, but they can bring energy and updated knowledge.","zh":"他們可能缺乏經驗，但可以帶來活力和最新知識。"},{"en":"Fresh graduates need guidance when the job market becomes crowded.","zh":"當就業市場變得擠迫時，應屆畢業生需要指導。"}],"source":"2016 Q3.pdf","sourcePage":3},{"front":"compete for","meaning":"競爭爭取","examples":[{"en":"Fresh graduates compete for similar entry-level posts.","zh":"應屆畢業生競爭爭取相似的入門職位。"},{"en":"To compete for something means to try to win it against other people.","zh":"競爭爭取某物，意思是與其他人競爭，希望得到它。"},{"en":"Many students compete for scholarships every year.","zh":"許多學生每年競爭爭取獎學金。"},{"en":"Graduates compete for jobs by submitting CVs and attending interviews.","zh":"畢業生透過提交履歷和參加面試競爭爭取工作。"},{"en":"Competition becomes fierce when too many people compete for the same role.","zh":"當太多人競爭爭取同一職位時，競爭會變得激烈。"}],"source":"2016 Q3.pdf","sourcePage":4},{"front":"similar entry-level posts","meaning":"相似的入門職位","examples":[{"en":"Many graduates compete for similar entry-level posts.","zh":"許多畢業生競爭相似的入門職位。"},{"en":"Similar entry-level posts are beginner jobs that require limited work experience.","zh":"相似的入門職位是要求較少工作經驗的初級工作。"},{"en":"Marketing assistant and trainee analyst roles may be similar entry-level posts.","zh":"市場助理和見習分析員職位可能是相似的入門職位。"},{"en":"When many graduates apply for similar posts, some capable people are left waiting.","zh":"當許多畢業生申請相似職位時，一些有能力的人會被留在外面等候。"},{"en":"Looking across Asia can help graduates find more varied entry-level options.","zh":"放眼亞洲可以幫助畢業生找到更多元的入門選項。"}],"source":"2016 Q3.pdf","sourcePage":4},{"front":"finance","meaning":"金融","examples":[{"en":"Many entry-level posts are in finance, marketing, education, design and technology.","zh":"許多入門職位屬於金融、市場推廣、教育、設計及科技。"},{"en":"Finance is the field of managing money, investment, banking, and financial risk.","zh":"金融是管理金錢、投資、銀行業務和財務風險的領域。"},{"en":"A graduate in finance may work in a bank, insurance company, or investment firm.","zh":"金融畢業生可能在銀行、保險公司或投資公司工作。"},{"en":"Finance jobs often require careful calculation and judgement.","zh":"金融工作通常需要仔細計算和判斷力。"},{"en":"Asian financial centres may offer graduates more finance opportunities.","zh":"亞洲金融中心可能為畢業生提供更多金融機會。"}],"source":"2016 Q3.pdf","sourcePage":4},{"front":"marketing","meaning":"市場推廣","examples":[{"en":"Marketing is one field where graduates seek entry-level posts.","zh":"市場推廣是畢業生尋找入門職位的其中一個領域。"},{"en":"Marketing means promoting products, services, or ideas to customers.","zh":"市場推廣意思是向顧客推廣產品、服務或想法。"},{"en":"A marketing graduate may write advertisements, study customers, or manage social media.","zh":"市場推廣畢業生可能撰寫廣告、研究顧客或管理社交媒體。"},{"en":"Marketing jobs require creativity and understanding of consumer behaviour.","zh":"市場推廣工作需要創意和對消費者行為的理解。"},{"en":"Regional experience can help marketing graduates understand different Asian customers.","zh":"區域經驗可以幫助市場推廣畢業生理解不同亞洲顧客。"}],"source":"2016 Q3.pdf","sourcePage":4},{"front":"design and technology","meaning":"設計及科技","examples":[{"en":"Graduates compete for posts in design and technology.","zh":"畢業生競爭設計及科技方面的職位。"},{"en":"Design and technology involve creating useful, attractive, or digital products and systems.","zh":"設計及科技涉及創造有用、吸引或數碼化的產品和系統。"},{"en":"A graduate may work on app design, product design, or software development.","zh":"畢業生可能從事應用程式設計、產品設計或軟件開發。"},{"en":"Design and technology jobs often reward creativity and problem-solving.","zh":"設計及科技工作通常重視創意和解難能力。"},{"en":"Asian cities with growing technology sectors may offer more chances in this field.","zh":"科技行業增長中的亞洲城市，可能在這領域提供更多機會。"}],"source":"2016 Q3.pdf","sourcePage":4},{"front":"applicants","meaning":"申請者","examples":[{"en":"Too many applicants crowd into the same narrow doorway.","zh":"太多申請者擠進同一扇狹窄的門。"},{"en":"Applicants are people who apply for a job, school, scholarship, or opportunity.","zh":"申請者是申請工作、學校、獎學金或機會的人。"},{"en":"A company may receive hundreds of applicants for one graduate trainee post.","zh":"公司可能為一個畢業見習職位收到數百名申請者。"},{"en":"Too many applicants make competition harder for everyone.","zh":"太多申請者會令每個人的競爭更困難。"},{"en":"Applicants can improve their chances by widening their search.","zh":"申請者可以透過擴闊搜尋範圍來提高機會。"}],"source":"2016 Q3.pdf","sourcePage":4},{"front":"crowd into","meaning":"擠進","examples":[{"en":"Too many applicants crowd into the same narrow doorway.","zh":"太多申請者擠進同一扇狹窄的門。"},{"en":"To crowd into a place means to enter or gather there in large numbers.","zh":"擠進某處意思是大量進入或聚集在那裏。"},{"en":"Students crowd into the hall when an important career talk begins.","zh":"重要就業講座開始時，學生會擠進禮堂。"},{"en":"Graduates crowd into the same industry when they believe it is safest.","zh":"當畢業生認為某行業最安全時，他們會擠進同一行業。"},{"en":"When too many people crowd into one path, other paths become worth exploring.","zh":"當太多人擠進一條路時，其他路就值得探索。"}],"source":"2016 Q3.pdf","sourcePage":4},{"front":"the same narrow doorway","meaning":"同一扇狹窄的門","examples":[{"en":"Many applicants are trying to enter the same narrow doorway.","zh":"許多申請者正嘗試進入同一扇狹窄的門。"},{"en":"The same narrow doorway is a metaphor for limited opportunities that many people want.","zh":"同一扇狹窄的門是一個比喻，指許多人想要的有限機會。"},{"en":"One popular trainee programme can become the same narrow doorway for hundreds of graduates.","zh":"一個受歡迎的見習計劃可以成為數百名畢業生爭取的同一扇狹窄的門。"},{"en":"A narrow doorway leaves many capable people waiting outside.","zh":"狹窄的門會令許多有能力的人在外面等候。"},{"en":"Graduates should look for other doors instead of crowding into the same narrow doorway.","zh":"畢業生應尋找其他門，而不是擠進同一扇狹窄的門。"}],"source":"2016 Q3.pdf","sourcePage":4},{"front":"capable young people","meaning":"有能力的年輕人","examples":[{"en":"Even capable young people may be left waiting outside.","zh":"即使有能力的年輕人也可能被留在外面等候。"},{"en":"Capable young people are young people with ability, skills, and potential.","zh":"有能力的年輕人是具備能力、技能和潛力的年輕人。"},{"en":"A capable graduate may still struggle if too few jobs are available.","zh":"如果職位太少，有能力的畢業生仍可能遇到困難。"},{"en":"Being left out of the local market does not mean capable young people lack talent.","zh":"被本地市場排除在外不代表有能力的年輕人缺乏才能。"},{"en":"Wider regional opportunities can help capable young people begin their careers.","zh":"更廣闊的區域機會可以幫助有能力的年輕人開始事業。"}],"source":"2016 Q3.pdf","sourcePage":4},{"front":"be left waiting outside","meaning":"被留在門外等候","examples":[{"en":"Capable young people may be left waiting outside the job market.","zh":"有能力的年輕人可能被留在就業市場門外等候。"},{"en":"To be left waiting outside means to be excluded from an opportunity even after trying.","zh":"被留在門外等候意思是努力後仍被排除在機會之外。"},{"en":"A graduate may be left waiting outside when every company says they need more experience.","zh":"當每間公司都說需要更多經驗時，畢業生可能被留在門外等候。"},{"en":"This image shows disappointment and unfair delay.","zh":"這個意象顯示失望和不公平的延誤。"},{"en":"Exploring other cities can stop graduates from being left waiting outside one market.","zh":"探索其他城市可以防止畢業生被留在一個市場門外等候。"}],"source":"2016 Q3.pdf","sourcePage":4},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"By contrast, other Asian cities may need different kinds of talent.","zh":"相比之下，其他亞洲城市可能需要不同類型的人才。"},{"en":"By contrast introduces a clear difference from the previous point.","zh":"相比之下用來引出與前一點清楚不同的情況。"},{"en":"Hong Kong may have too many applicants; by contrast, another city may lack certain skills.","zh":"香港可能有太多申請者；相比之下，另一個城市可能缺乏某些技能。"},{"en":"Writers use by contrast to compare two situations.","zh":"作者使用 by contrast 來比較兩種情況。"},{"en":"This phrase helps show why graduates should widen their search.","zh":"這個短語幫助顯示為何畢業生應擴闊搜尋範圍。"}],"source":"2016 Q3.pdf","sourcePage":5},{"front":"cities such as","meaning":"例如……的城市","examples":[{"en":"Cities such as Singapore, Shenzhen, Taipei, Tokyo, Seoul and Bangkok may offer opportunities.","zh":"例如新加坡、深圳、台北、東京、首爾和曼谷的城市可能提供機會。"},{"en":"Cities such as introduces examples of cities being discussed.","zh":"例如……的城市用來引出正在討論的城市例子。"},{"en":"Cities such as Tokyo and Seoul may attract design and technology graduates.","zh":"例如東京和首爾的城市可能吸引設計及科技畢業生。"},{"en":"This phrase helps writers give concrete examples instead of speaking vaguely.","zh":"這個短語幫助作者給出具體例子，而不是含糊地說。"},{"en":"Naming cities such as these makes the career map feel more real.","zh":"說出這些城市例子，令事業地圖感覺更真實。"}],"source":"2016 Q3.pdf","sourcePage":5},{"front":"different kinds of talent","meaning":"不同類型的人才","examples":[{"en":"Other Asian cities may need different kinds of talent.","zh":"其他亞洲城市可能需要不同類型的人才。"},{"en":"Different kinds of talent means people with different skills, training, and strengths.","zh":"不同類型的人才是指具備不同技能、訓練和強項的人。"},{"en":"One city may need engineers, while another may need designers or language experts.","zh":"一個城市可能需要工程師，另一個城市可能需要設計師或語言專才。"},{"en":"Graduates should understand which kinds of talent each market needs.","zh":"畢業生應了解每個市場需要哪些不同類型的人才。"},{"en":"A wider market allows different kinds of talent to find suitable opportunities.","zh":"更廣闊市場讓不同類型的人才找到合適機會。"}],"source":"2016 Q3.pdf","sourcePage":5},{"front":"at different times","meaning":"在不同時候","examples":[{"en":"Different cities may need different talent at different times.","zh":"不同城市可能在不同時候需要不同人才。"},{"en":"At different times means not always at the same moment, but during different periods.","zh":"在不同時候意思是不是總在同一刻，而是在不同時期。"},{"en":"A city may need nurses one year and software engineers the next.","zh":"一個城市某一年可能需要護士，下一年可能需要軟件工程師。"},{"en":"Job markets change at different times because industries grow and slow down.","zh":"就業市場會在不同時候改變，因為行業有增長也有放緩。"},{"en":"Graduates should watch regional trends because needs appear at different times.","zh":"畢業生應留意區域趨勢，因為需要會在不同時候出現。"}],"source":"2016 Q3.pdf","sourcePage":5},{"front":"business graduate","meaning":"商科畢業生","examples":[{"en":"A business graduate may discover opportunities in Singapore.","zh":"商科畢業生可能在新加坡發現機會。"},{"en":"A business graduate is someone who has completed a degree or course in business.","zh":"商科畢業生是完成商業相關學位或課程的人。"},{"en":"A business graduate may work in finance, management, marketing, or consulting.","zh":"商科畢業生可能從事金融、管理、市場推廣或顧問工作。"},{"en":"Business graduates can use regional experience to understand different markets.","zh":"商科畢業生可以利用區域經驗理解不同市場。"},{"en":"A business graduate should compare cities before deciding where to begin.","zh":"商科畢業生應比較不同城市，再決定在哪裏開始。"}],"source":"2016 Q3.pdf","sourcePage":5},{"front":"local banking post","meaning":"本地銀行職位","examples":[{"en":"A business graduate may not find a local banking post.","zh":"商科畢業生可能找不到本地銀行職位。"},{"en":"A local banking post is a job in a bank within the graduate’s own city.","zh":"本地銀行職位是在畢業生自己城市內銀行的工作。"},{"en":"A graduate may fail to find a local banking post if banks hire only a small number of trainees.","zh":"如果銀行只聘請少量見習生，畢業生可能找不到本地銀行職位。"},{"en":"Not finding one local post does not mean the graduate has no future in finance.","zh":"找不到一個本地職位不代表畢業生在金融界沒有未來。"},{"en":"Regional financial centres may offer alternatives to a local banking post.","zh":"區域金融中心可能提供本地銀行職位以外的選擇。"}],"source":"2016 Q3.pdf","sourcePage":5},{"front":"discover opportunities in","meaning":"在……發現機會","examples":[{"en":"A graduate may discover opportunities in Singapore’s fintech sector.","zh":"畢業生可能在新加坡金融科技行業發現機會。"},{"en":"To discover opportunities in a place or field means to find possible chances there.","zh":"在某地或某領域發現機會，意思是在那裏找到可能的機會。"},{"en":"A design student may discover opportunities in Seoul’s creative industries.","zh":"設計學生可能在首爾創意產業發現機會。"},{"en":"Graduates discover opportunities when they research markets carefully.","zh":"畢業生仔細研究市場時，會發現機會。"},{"en":"Sometimes a person discovers opportunities in a city they had never considered.","zh":"有時一個人會在自己從未考慮過的城市發現機會。"}],"source":"2016 Q3.pdf","sourcePage":5},{"front":"Singapore’s fintech sector","meaning":"新加坡金融科技行業","examples":[{"en":"A business graduate may find opportunities in Singapore’s fintech sector.","zh":"商科畢業生可能在新加坡金融科技行業找到機會。"},{"en":"Singapore’s fintech sector means the financial technology industry in Singapore.","zh":"新加坡金融科技行業是指新加坡的金融科技產業。"},{"en":"This sector may include digital payments, online banking, and financial data services.","zh":"這個行業可能包括電子支付、網上銀行和金融數據服務。"},{"en":"A business graduate with technology skills may fit well in Singapore’s fintech sector.","zh":"具備科技技能的商科畢業生可能很適合新加坡金融科技行業。"},{"en":"Working in this sector can help graduates understand regional finance and innovation.","zh":"在這個行業工作可以幫助畢業生理解區域金融和創新。"}],"source":"2016 Q3.pdf","sourcePage":5},{"front":"design student","meaning":"設計學生","examples":[{"en":"A design student may find a place in Seoul’s creative industries.","zh":"設計學生可能在首爾創意產業找到位置。"},{"en":"A design student studies how to create visual, digital, product, or communication designs.","zh":"設計學生學習如何創造視覺、數碼、產品或傳意設計。"},{"en":"A design student may build a portfolio before applying for jobs.","zh":"設計學生可能在申請工作前建立作品集。"},{"en":"Design students need creativity, technical skills, and awareness of culture.","zh":"設計學生需要創意、技術技能和文化意識。"},{"en":"Asian creative cities may give design students more room to grow.","zh":"亞洲創意城市可能給設計學生更多成長空間。"}],"source":"2016 Q3.pdf","sourcePage":5},{"front":"find a place in","meaning":"在……找到位置","examples":[{"en":"A design student may find a place in Seoul’s creative industries.","zh":"設計學生可能在首爾創意產業找到位置。"},{"en":"To find a place in a field means to discover a suitable role or position there.","zh":"在某領域找到位置，意思是在那裏找到合適角色或職位。"},{"en":"A young programmer may find a place in a growing technology company.","zh":"年輕程式員可能在成長中的科技公司找到位置。"},{"en":"Graduates find a place when their skills match a market’s needs.","zh":"當畢業生的技能配合市場需要時，他們便找到位置。"},{"en":"Finding a place in another city can turn uncertainty into direction.","zh":"在另一個城市找到位置，可以把不確定變成方向。"}],"source":"2016 Q3.pdf","sourcePage":5},{"front":"creative industries","meaning":"創意產業","examples":[{"en":"Seoul’s creative industries may offer opportunities to design graduates.","zh":"首爾的創意產業可能為設計畢業生提供機會。"},{"en":"Creative industries are fields that use imagination, design, culture, and media to create value.","zh":"創意產業是運用想像力、設計、文化和媒體創造價值的領域。"},{"en":"Film, fashion, music, advertising, and game design are creative industries.","zh":"電影、時裝、音樂、廣告和遊戲設計都是創意產業。"},{"en":"Creative industries need people who can produce fresh ideas and attractive content.","zh":"創意產業需要能創造新想法和吸引內容的人。"},{"en":"A graduate may grow quickly in a city with strong creative industries.","zh":"畢業生可能在創意產業強的城市快速成長。"}],"source":"2016 Q3.pdf","sourcePage":6},{"front":"engineering graduate","meaning":"工程畢業生","examples":[{"en":"An engineering graduate may learn quickly in Shenzhen.","zh":"工程畢業生可能在深圳快速學習。"},{"en":"An engineering graduate is someone who has completed study in engineering.","zh":"工程畢業生是完成工程學習的人。"},{"en":"Engineering graduates may work on buildings, machines, software, or transport systems.","zh":"工程畢業生可能從事建築、機械、軟件或交通系統工作。"},{"en":"They learn quickly when they enter industries with real technical challenges.","zh":"當他們進入有真實技術挑戰的行業時，會學得很快。"},{"en":"Shenzhen technology firms may offer engineering graduates practical experience.","zh":"深圳科技公司可能為工程畢業生提供實際經驗。"}],"source":"2016 Q3.pdf","sourcePage":6},{"front":"technology firms","meaning":"科技公司","examples":[{"en":"An engineering graduate may learn quickly in Shenzhen’s technology firms.","zh":"工程畢業生可能在深圳的科技公司快速學習。"},{"en":"Technology firms are companies that create or use advanced digital, software, or engineering products.","zh":"科技公司是創造或使用先進數碼、軟件或工程產品的公司。"},{"en":"A technology firm may build apps, robots, chips, or online platforms.","zh":"科技公司可能開發應用程式、機械人、晶片或網上平台。"},{"en":"Working in technology firms helps graduates solve real problems with technical skills.","zh":"在科技公司工作幫助畢業生用技術技能解決真實問題。"},{"en":"Fast-growing technology firms can give young workers strong training.","zh":"快速成長的科技公司可以給年輕工作者強大訓練。"}],"source":"2016 Q3.pdf","sourcePage":6},{"front":"one person’s disappointment","meaning":"一個人的失望","examples":[{"en":"One person’s disappointment in Hong Kong can become another city’s opportunity.","zh":"一個人在香港的失望，可以成為另一個城市的機會。"},{"en":"One person’s disappointment means one person’s feeling of failure, sadness, or frustration.","zh":"一個人的失望是指一個人的失敗感、傷心或挫折感。"},{"en":"A rejected job application may be one person’s disappointment at first.","zh":"被一份工作拒絕，一開始可能是一個人的失望。"},{"en":"That disappointment can become motivation to search more widely.","zh":"那份失望可以變成更廣泛尋找的動力。"},{"en":"One person’s disappointment in one city may lead to success in another.","zh":"一個人在一個城市的失望，可能帶來另一個城市的成功。"}],"source":"2016 Q3.pdf","sourcePage":6},{"front":"another city’s opportunity","meaning":"另一個城市的機會","examples":[{"en":"A disappointment in Hong Kong can become another city’s opportunity.","zh":"在香港的失望可以成為另一個城市的機會。"},{"en":"Another city’s opportunity means a chance offered by a different city.","zh":"另一個城市的機會，是指由不同城市提供的機會。"},{"en":"A graduate rejected in Hong Kong may find another city’s opportunity in Taipei or Bangkok.","zh":"在香港被拒絕的畢業生，可能在台北或曼谷找到另一個城市的機會。"},{"en":"This phrase shows that failure in one market is not failure everywhere.","zh":"這個短語顯示在一個市場失敗，不代表在所有地方失敗。"},{"en":"Graduates should search for another city’s opportunity before giving up.","zh":"畢業生在放棄前，應尋找另一個城市的機會。"}],"source":"2016 Q3.pdf","sourcePage":6},{"front":"instead of treating…as…","meaning":"與其把……視為……","examples":[{"en":"Instead of treating unemployment as a dead end, graduates can treat Asia as a larger map.","zh":"與其把失業視為死胡同，畢業生可以把亞洲視為更大的地圖。"},{"en":"This structure contrasts an unhelpful view with a better way of seeing the situation.","zh":"這個結構把無助的看法和更好的理解方式作對比。"},{"en":"Instead of treating rejection as failure, students can treat it as feedback.","zh":"與其把拒絕視為失敗，學生可以把它視為回饋。"},{"en":"The phrase helps writers replace a negative attitude with a practical one.","zh":"這個短語幫助作者以實際態度取代負面態度。"},{"en":"Graduates should treat difficulty as a signal to explore, not as the end.","zh":"畢業生應把困難視為探索訊號，而不是終點。"}],"source":"2016 Q3.pdf","sourcePage":6},{"front":"unemployment","meaning":"失業","examples":[{"en":"Graduates should not treat unemployment as a dead end.","zh":"畢業生不應把失業視為死胡同。"},{"en":"Unemployment means the state of not having a job while wanting work.","zh":"失業意思是想工作但沒有工作的狀態。"},{"en":"A graduate may face unemployment for a few months after university.","zh":"畢業生可能在大學後面對數月失業。"},{"en":"Unemployment can be stressful, but it can also push people to widen their search.","zh":"失業可以令人有壓力，但也可以推動人擴闊搜尋。"},{"en":"Support and planning can turn unemployment into a temporary stage.","zh":"支援和規劃可以把失業變成暫時階段。"}],"source":"2016 Q3.pdf","sourcePage":6},{"front":"a dead end","meaning":"死胡同","examples":[{"en":"Unemployment should not be treated as a dead end.","zh":"失業不應被視為死胡同。"},{"en":"A dead end is a situation with no clear way forward.","zh":"死胡同是指沒有清晰前路的情況。"},{"en":"Missing one job offer is not a dead end if other cities still have openings.","zh":"錯過一份工作機會並不是死胡同，如果其他城市仍有空缺。"},{"en":"People feel hopeless when they mistake a delay for a dead end.","zh":"當人把延誤誤以為是死胡同時，會感到絕望。"},{"en":"Asia can offer new routes when the local path feels like a dead end.","zh":"當本地道路像死胡同時，亞洲可以提供新路線。"}],"source":"2016 Q3.pdf","sourcePage":6},{"front":"a larger map","meaning":"更大的地圖","examples":[{"en":"Asia can be treated as a larger map with more open doors.","zh":"亞洲可以被視為一幅有更多機會之門打開的更大地圖。"},{"en":"A larger map is a metaphor for a wider set of choices and directions.","zh":"更大的地圖是一個比喻，指更廣闊的選擇和方向。"},{"en":"A graduate sees a larger map when they compare jobs across several cities.","zh":"當畢業生比較幾個城市的工作時，他們便看見更大的地圖。"},{"en":"A larger map helps people stop focusing on one narrow doorway.","zh":"更大的地圖幫助人不再只盯著一扇狹窄的門。"},{"en":"Thinking of Asia as a larger map can make career planning less frightening.","zh":"把亞洲視為更大的地圖，可以令事業規劃不那麼可怕。"}],"source":"2016 Q3.pdf","sourcePage":6},{"front":"more doors are open","meaning":"更多機會之門打開","examples":[{"en":"Asia is a larger map on which more doors are open.","zh":"亞洲是一幅更大的地圖，上面有更多機會之門打開。"},{"en":"More doors are open means more opportunities are available.","zh":"更多機會之門打開意思是有更多機會可供選擇。"},{"en":"A graduate may find that more doors are open after applying to regional companies.","zh":"申請區域公司後，畢業生可能發現更多機會之門打開。"},{"en":"When one market is full, another market may still have open doors.","zh":"當一個市場飽和時，另一個市場可能仍有門打開。"},{"en":"Seeing more doors open can restore confidence after rejection.","zh":"看見更多機會之門打開，可以在被拒絕後恢復信心。"}],"source":"2016 Q3.pdf","sourcePage":6},{"front":"working elsewhere","meaning":"到其他地方工作","examples":[{"en":"Working elsewhere can make graduates more mature and adaptable.","zh":"到其他地方工作可以令畢業生更成熟和適應力更強。"},{"en":"Working elsewhere means taking a job in another city, region, or country.","zh":"到其他地方工作意思是在另一個城市、地區或國家工作。"},{"en":"A graduate working elsewhere must learn new routines, rules, and cultures.","zh":"到其他地方工作的畢業生必須學習新日常、新規則和新文化。"},{"en":"Working elsewhere can be difficult, but it often teaches independence.","zh":"到其他地方工作可以困難，但常會教人獨立。"},{"en":"Students should prepare carefully before working elsewhere.","zh":"學生到其他地方工作前應仔細準備。"}],"source":"2016 Q3.pdf","sourcePage":7},{"front":"mature","meaning":"成熟","examples":[{"en":"Working elsewhere can make graduates more mature.","zh":"到其他地方工作可以令畢業生更成熟。"},{"en":"Mature means sensible, responsible, and able to handle difficulties calmly.","zh":"成熟意思是明智、負責任，並能冷靜處理困難。"},{"en":"A mature graduate plans money, time, and work carefully.","zh":"成熟的畢業生會仔細規劃金錢、時間和工作。"},{"en":"Living in another city can make young people more mature because they must solve problems alone.","zh":"在另一個城市生活可以令人更成熟，因為他們必須自己解決問題。"},{"en":"Employers value mature workers who can act without constant guidance.","zh":"僱主重視成熟而不需時刻指導的工作者。"}],"source":"2016 Q3.pdf","sourcePage":7},{"front":"adaptable","meaning":"適應力強的","examples":[{"en":"Employers value graduates who are adaptable.","zh":"僱主重視適應力強的畢業生。"},{"en":"Adaptable means able to adjust to new situations, people, or problems.","zh":"適應力強的意思是能適應新情況、新人或新問題。"},{"en":"A graduate is adaptable if they can work with colleagues from different cultures.","zh":"如果畢業生能與不同文化的同事合作，就是適應力強。"},{"en":"Working abroad builds adaptability because daily life and work may change quickly.","zh":"海外工作能建立適應力，因為日常生活和工作可能很快改變。"},{"en":"Adaptable workers are useful in fast-changing industries.","zh":"適應力強的工作者在快速變化的行業中很有用。"}],"source":"2016 Q3.pdf","sourcePage":7},{"front":"employable","meaning":"更具就業能力","examples":[{"en":"Regional work experience can make graduates more employable.","zh":"區域工作經驗可以令畢業生更具就業能力。"},{"en":"Employable means having the skills, experience, and attitude that employers want.","zh":"更具就業能力意思是具備僱主想要的技能、經驗和態度。"},{"en":"A graduate becomes more employable after gaining real workplace experience.","zh":"畢業生獲得真實工作經驗後，會更具就業能力。"},{"en":"Language skills and cultural understanding can make a person more employable.","zh":"語言能力和文化理解可以令人更具就業能力。"},{"en":"Working in Asia can make graduates more employable in both regional and local markets.","zh":"在亞洲工作可以令畢業生在區域和本地市場都更具就業能力。"}],"source":"2016 Q3.pdf","sourcePage":7},{"front":"employers today","meaning":"現今僱主","examples":[{"en":"Employers today look for more than a degree.","zh":"現今僱主尋找的不只是一個學位。"},{"en":"Employers today means modern companies or bosses hiring workers now.","zh":"現今僱主是指現在聘請員工的現代公司或老闆。"},{"en":"Employers today often value problem-solving, communication, and adaptability.","zh":"現今僱主通常重視解難能力、溝通能力和適應力。"},{"en":"A degree matters, but employers today also ask whether candidates can handle pressure.","zh":"學位很重要，但現今僱主也會問求職者能否承受壓力。"},{"en":"Graduates should understand what employers today really need.","zh":"畢業生應了解現今僱主真正需要甚麼。"}],"source":"2016 Q3.pdf","sourcePage":7},{"front":"not merely ask whether","meaning":"不只是問是否","examples":[{"en":"Employers today do not merely ask whether a candidate has a degree.","zh":"現今僱主不只是問求職者是否有學位。"},{"en":"Not merely ask whether means not only ask this one simple question.","zh":"不只是問是否意思是不只提出這一個簡單問題。"},{"en":"Employers do not merely ask whether students studied hard; they ask what they can do.","zh":"僱主不只是問學生是否努力讀書；他們也問學生能做甚麼。"},{"en":"This phrase shows that modern hiring standards are broader.","zh":"這個短語顯示現代招聘標準更廣泛。"},{"en":"It helps explain why work experience matters.","zh":"它幫助解釋為何工作經驗重要。"}],"source":"2016 Q3.pdf","sourcePage":7},{"front":"candidate","meaning":"求職者","examples":[{"en":"Employers ask whether a candidate can solve problems.","zh":"僱主會問求職者能否解決問題。"},{"en":"A candidate is a person applying for a job, award, election, or opportunity.","zh":"求職者是申請工作、獎項、選舉或機會的人。"},{"en":"A strong candidate can explain their skills with real examples.","zh":"強勁求職者能用真實例子解釋自己的技能。"},{"en":"Employers compare candidates to decide who best fits the role.","zh":"僱主會比較求職者，決定誰最適合該職位。"},{"en":"Regional experience may make a candidate stand out.","zh":"區域經驗可能令求職者突出。"}],"source":"2016 Q3.pdf","sourcePage":7},{"front":"solve problems","meaning":"解決問題","examples":[{"en":"Employers want candidates who can solve problems.","zh":"僱主想要能解決問題的求職者。"},{"en":"To solve problems means to find practical answers to difficult situations.","zh":"解決問題意思是為困難情況找到實際答案。"},{"en":"A hotel employee solves problems when they calm an unhappy customer.","zh":"酒店員工安撫不滿顧客時，就是在解決問題。"},{"en":"Graduates learn to solve problems when they work in unfamiliar environments.","zh":"畢業生在陌生環境工作時，會學習解決問題。"},{"en":"Employers value problem-solving because workplaces rarely follow textbooks exactly.","zh":"僱主重視解難能力，因為工作場所很少完全跟課本一樣。"}],"source":"2016 Q3.pdf","sourcePage":7},{"front":"communicate across cultures","meaning":"跨文化溝通","examples":[{"en":"Graduates need to communicate across cultures.","zh":"畢業生需要跨文化溝通。"},{"en":"To communicate across cultures means to speak and work effectively with people from different backgrounds.","zh":"跨文化溝通意思是與不同背景的人有效說話和合作。"},{"en":"A Hong Kong graduate may communicate across cultures when working with Thai and Japanese colleagues.","zh":"香港畢業生與泰國和日本同事工作時，可能需要跨文化溝通。"},{"en":"Cross-cultural communication requires patience, respect, and clear language.","zh":"跨文化溝通需要耐性、尊重和清晰語言。"},{"en":"Working in Asia can train graduates to communicate across cultures.","zh":"在亞洲工作可以訓練畢業生跨文化溝通。"}],"source":"2016 Q3.pdf","sourcePage":7},{"front":"remain calm under pressure","meaning":"在壓力下保持冷靜","examples":[{"en":"Employers value people who remain calm under pressure.","zh":"僱主重視在壓力下保持冷靜的人。"},{"en":"To remain calm under pressure means to stay controlled and clear-minded during stress.","zh":"在壓力下保持冷靜意思是在緊張情況中仍保持克制和清晰思考。"},{"en":"A hotel worker must remain calm under pressure when many guests complain at once.","zh":"當許多客人同時投訴時，酒店員工必須在壓力下保持冷靜。"},{"en":"Graduates build this ability when they face difficult work in unfamiliar places.","zh":"畢業生在陌生地方面對困難工作時，會建立這種能力。"},{"en":"Remaining calm under pressure helps people solve problems more wisely.","zh":"在壓力下保持冷靜能幫助人更明智地解決問題。"}],"source":"2016 Q3.pdf","sourcePage":7},{"front":"only by entering","meaning":"只有透過進入","examples":[{"en":"Only by entering an unfamiliar environment can graduates discover their abilities.","zh":"只有透過進入陌生環境，畢業生才能發現自己的能力。"},{"en":"Only by entering means something can happen only when a person steps into a situation.","zh":"只有透過進入意思是某事只有在人踏入某種情況時才會發生。"},{"en":"Only by entering real workplaces can students understand what employers expect.","zh":"只有透過進入真實工作場所，學生才能理解僱主期望甚麼。"},{"en":"This phrase stresses that experience cannot be replaced by imagination alone.","zh":"這個短語強調經驗不能單靠想像取代。"},{"en":"Graduates may discover new strengths only by entering challenging environments.","zh":"畢業生可能只有透過進入具挑戰的環境，才會發現新強項。"}],"source":"2016 Q3.pdf","sourcePage":8},{"front":"unfamiliar environment","meaning":"陌生環境","examples":[{"en":"An unfamiliar environment can help graduates grow.","zh":"陌生環境可以幫助畢業生成長。"},{"en":"An unfamiliar environment is a place or situation that a person does not know well.","zh":"陌生環境是人不熟悉的地方或情況。"},{"en":"A new city, workplace, or language setting can be an unfamiliar environment.","zh":"新城市、新工作場所或新語言環境都可以是陌生環境。"},{"en":"Such environments force graduates to ask questions and adapt quickly.","zh":"這類環境迫使畢業生提問並快速適應。"},{"en":"Growth often begins when people leave familiar surroundings.","zh":"成長常在人離開熟悉環境時開始。"}],"source":"2016 Q3.pdf","sourcePage":8},{"front":"discover what they are truly capable of","meaning":"發現自己真正能做到甚麼","examples":[{"en":"Graduates can discover what they are truly capable of abroad.","zh":"畢業生可以在海外發現自己真正能做到甚麼。"},{"en":"To discover what they are truly capable of means to learn their real abilities through experience.","zh":"發現自己真正能做到甚麼，意思是透過經驗了解自己的真實能力。"},{"en":"A graduate may discover they can lead a team after handling a difficult project.","zh":"畢業生處理困難項目後，可能發現自己能帶領團隊。"},{"en":"People often underestimate themselves before facing real challenges.","zh":"人們在面對真正挑戰前，常會低估自己。"},{"en":"Working abroad can reveal abilities that school never fully tested.","zh":"海外工作可以揭示學校未能完全測試的能力。"}],"source":"2016 Q3.pdf","sourcePage":8},{"front":"imagine","meaning":"試想","examples":[{"en":"Imagine a Hong Kong graduate working in a hotel group in Bangkok.","zh":"試想一位香港畢業生在曼谷一個酒店集團工作。"},{"en":"Imagine means think about a possible situation in your mind.","zh":"試想意思是在腦海中想像一個可能情況。"},{"en":"Imagine working with colleagues from five countries every day.","zh":"試想每天與來自五個國家的同事共事。"},{"en":"Writers use imagine to make an example feel clear and real.","zh":"作者使用 imagine 令例子感覺清晰而真實。"},{"en":"This word invites readers to picture how regional work can train graduates.","zh":"這個詞邀請讀者想像區域工作如何訓練畢業生。"}],"source":"2016 Q3.pdf","sourcePage":8},{"front":"hotel group","meaning":"酒店集團","examples":[{"en":"A graduate may work in a hotel group in Bangkok.","zh":"畢業生可能在曼谷一個酒店集團工作。"},{"en":"A hotel group is a company that owns or manages several hotels.","zh":"酒店集團是擁有或管理多間酒店的公司。"},{"en":"A hotel group may hire graduates for management, marketing, or customer service.","zh":"酒店集團可能聘請畢業生從事管理、市場推廣或客戶服務。"},{"en":"Working in a hotel group teaches communication with many types of guests.","zh":"在酒店集團工作會教人與不同類型客人溝通。"},{"en":"A regional hotel group can expose graduates to international service standards.","zh":"區域酒店集團可以讓畢業生接觸國際服務標準。"}],"source":"2016 Q3.pdf","sourcePage":8},{"front":"negotiating with","meaning":"與……協商","examples":[{"en":"The graduate may be negotiating with colleagues from different countries.","zh":"畢業生可能正與來自不同國家的同事協商。"},{"en":"To negotiate with someone means to discuss an issue in order to reach an agreement.","zh":"與某人協商意思是討論問題，以達成協議。"},{"en":"A manager negotiates with suppliers about price and delivery time.","zh":"經理會與供應商就價格和送貨時間協商。"},{"en":"Negotiating with foreign colleagues requires clear language and cultural sensitivity.","zh":"與外國同事協商需要清晰語言和文化敏感度。"},{"en":"Graduates build confidence when they negotiate with people in real work situations.","zh":"畢業生在真實工作情況中與人協商時，會建立信心。"}],"source":"2016 Q3.pdf","sourcePage":8},{"front":"colleagues from different countries","meaning":"來自不同國家的同事","examples":[{"en":"Working abroad means cooperating with colleagues from different countries.","zh":"在海外工作意味著與來自不同國家的同事合作。"},{"en":"Colleagues from different countries are co-workers who come from various national backgrounds.","zh":"來自不同國家的同事，是指具有不同國籍背景的同事。"},{"en":"A hotel team may include colleagues from Thailand, Japan, India, and Hong Kong.","zh":"酒店團隊可能包括來自泰國、日本、印度和香港的同事。"},{"en":"Working with such colleagues teaches patience and cross-cultural communication.","zh":"與這類同事合作能教人耐性和跨文化溝通。"},{"en":"Graduates learn to respect different habits when they work with international teams.","zh":"畢業生與國際團隊工作時，會學習尊重不同習慣。"}],"source":"2016 Q3.pdf","sourcePage":8},{"front":"handling customers","meaning":"接待顧客；處理顧客需要","examples":[{"en":"The graduate may be handling customers with different expectations.","zh":"畢業生可能正接待有不同期望的顧客。"},{"en":"Handling customers means serving, helping, or responding to customers’ needs.","zh":"接待顧客或處理顧客需要，意思是服務、幫助或回應顧客需要。"},{"en":"A hotel worker handles customers when they answer questions or solve complaints.","zh":"酒店員工回答問題或處理投訴時，就是在接待顧客。"},{"en":"Handling customers from different cultures can improve communication skills.","zh":"接待不同文化的顧客可以提升溝通能力。"},{"en":"Good customer handling requires patience, judgement, and emotional control.","zh":"良好的顧客處理需要耐性、判斷力和情緒控制。"}],"source":"2016 Q3.pdf","sourcePage":8},{"front":"expectations differ from","meaning":"期望與……不同","examples":[{"en":"Customers’ expectations may differ from our own.","zh":"顧客的期望可能與我們自己的不同。"},{"en":"If expectations differ from ours, people want or assume different things.","zh":"如果期望與我們不同，意思是人們想要或假設的東西不同。"},{"en":"Tourists from different cultures may expect different service styles.","zh":"來自不同文化的旅客可能期待不同服務方式。"},{"en":"Misunderstanding happens when workers forget that expectations differ from place to place.","zh":"當工作者忘記期望會因地方而異時，誤解就會發生。"},{"en":"Regional work teaches graduates to notice how expectations differ from their own habits.","zh":"區域工作教畢業生注意別人的期望如何與自己的習慣不同。"}],"source":"2016 Q3.pdf","sourcePage":8},{"front":"explain ideas in","meaning":"用……解釋想法","examples":[{"en":"Graduates may need to explain ideas in English, Putonghua or a local language.","zh":"畢業生可能需要用英語、普通話或當地語言解釋想法。"},{"en":"To explain ideas in a language means to express thoughts clearly using that language.","zh":"用某種語言解釋想法，意思是用該語言清楚表達思想。"},{"en":"A graduate may explain ideas in English during a meeting with regional clients.","zh":"畢業生可能在與區域客戶開會時用英語解釋想法。"},{"en":"Explaining ideas in another language tests both language ability and confidence.","zh":"用另一種語言解釋想法會測試語言能力和信心。"},{"en":"Graduates communicate better when they can explain ideas in more than one language.","zh":"當畢業生能用多於一種語言解釋想法時，溝通會更好。"}],"source":"2016 Q3.pdf","sourcePage":8},{"front":"local language","meaning":"當地語言","examples":[{"en":"A graduate abroad may need to learn a local language.","zh":"在海外的畢業生可能需要學習當地語言。"},{"en":"A local language is the language commonly used by people in a particular place.","zh":"當地語言是在特定地方的人常用的語言。"},{"en":"A graduate in Bangkok may learn some Thai as a local language.","zh":"在曼谷的畢業生可能學習一些泰語作為當地語言。"},{"en":"Learning the local language shows respect for the community.","zh":"學習當地語言顯示對社區的尊重。"},{"en":"Even basic local language skills can help daily life and workplace trust.","zh":"即使基本當地語言能力，也能幫助日常生活和工作信任。"}],"source":"2016 Q3.pdf","sourcePage":9},{"front":"with new opportunities come new risks","meaning":"新機會伴隨新風險","examples":[{"en":"With new opportunities come new risks.","zh":"新機會伴隨新風險。"},{"en":"This phrase means every new chance may also bring possible difficulties.","zh":"這個短語意思是每個新機會也可能帶來困難。"},{"en":"Working abroad offers growth, but it may also bring homesickness and uncertainty.","zh":"海外工作提供成長，但也可能帶來思鄉和不確定性。"},{"en":"The phrase reminds graduates to be hopeful and careful at the same time.","zh":"這個短語提醒畢業生要同時抱有希望和保持謹慎。"},{"en":"New risks can be managed with research, preparation, and support.","zh":"新風險可以透過研究、準備和支援管理。"}],"source":"2016 Q3.pdf","sourcePage":9},{"front":"comes with training","meaning":"伴隨訓練","examples":[{"en":"Every opportunity also comes with training.","zh":"每個機會也伴隨訓練。"},{"en":"Comes with training means an experience includes lessons that help people improve.","zh":"伴隨訓練意思是某段經驗包括幫助人改善的學習。"},{"en":"A difficult first job comes with training in patience and responsibility.","zh":"困難的第一份工作伴隨耐性和責任感的訓練。"},{"en":"Working abroad comes with training because graduates must adapt daily.","zh":"海外工作伴隨訓練，因為畢業生每天都必須適應。"},{"en":"The training may be uncomfortable, but it can build real ability.","zh":"這種訓練可能不舒服，但可以建立真正能力。"}],"source":"2016 Q3.pdf","sourcePage":9},{"front":"survive homesickness","meaning":"捱過思鄉","examples":[{"en":"A graduate who has survived homesickness abroad will become stronger.","zh":"在海外捱過思鄉的畢業生會變得更強。"},{"en":"To survive homesickness means to get through the sadness of missing home.","zh":"捱過思鄉意思是渡過想家的傷感。"},{"en":"A student may survive homesickness by calling family and building new friendships.","zh":"學生可以透過致電家人和建立新友誼來捱過思鄉。"},{"en":"Homesickness is painful, but surviving it can build independence.","zh":"思鄉很痛苦，但捱過它可以建立獨立。"},{"en":"Graduates who survive homesickness often learn that they are stronger than expected.","zh":"捱過思鄉的畢業生常會發現自己比預期更堅強。"}],"source":"2016 Q3.pdf","sourcePage":9},{"front":"cultural misunderstanding","meaning":"文化誤解","examples":[{"en":"Working abroad may involve cultural misunderstanding.","zh":"在海外工作可能涉及文化誤解。"},{"en":"Cultural misunderstanding happens when people from different cultures misread each other’s words or behaviour.","zh":"文化誤解是來自不同文化的人誤讀彼此說話或行為時發生的。"},{"en":"Direct speech may cause cultural misunderstanding if another culture expects softer language.","zh":"如果另一種文化期待較委婉語言，直接說話可能造成文化誤解。"},{"en":"Such misunderstandings can be reduced through patience and questions.","zh":"這些誤解可以透過耐性和提問減少。"},{"en":"Working abroad teaches graduates how to handle cultural misunderstanding more calmly.","zh":"海外工作教畢業生更冷靜地處理文化誤解。"}],"source":"2016 Q3.pdf","sourcePage":9},{"front":"demanding supervisors","meaning":"要求高的上司","examples":[{"en":"A graduate may learn from demanding supervisors abroad.","zh":"畢業生可能向海外要求高的上司學習。"},{"en":"Demanding supervisors are managers who expect high standards and strong effort.","zh":"要求高的上司是期待高標準和高度努力的管理者。"},{"en":"A demanding supervisor may ask a graduate to revise a report several times.","zh":"要求高的上司可能要求畢業生多次修改報告。"},{"en":"Such supervisors can be stressful, but they may also train professionalism.","zh":"這類上司可以令人有壓力，但也可能訓練專業精神。"},{"en":"Graduates learn resilience when they work under demanding supervisors.","zh":"畢業生在要求高的上司下工作時，會學習抗逆力。"}],"source":"2016 Q3.pdf","sourcePage":9},{"front":"abroad","meaning":"在海外","examples":[{"en":"Working abroad can build confidence and resilience.","zh":"在海外工作可以建立信心和抗逆力。"},{"en":"Abroad means in or to another country or place outside one’s home region.","zh":"在海外意思是在另一個國家或家鄉地區以外的地方。"},{"en":"A graduate may work abroad in Singapore, Japan, or Thailand.","zh":"畢業生可能在新加坡、日本或泰國海外工作。"},{"en":"Living abroad teaches people to solve daily problems independently.","zh":"在海外生活教人獨立解決日常問題。"},{"en":"Abroad experience can make graduates more open-minded and employable.","zh":"海外經驗可以令畢業生更開明和更具就業能力。"}],"source":"2016 Q3.pdf","sourcePage":9},{"front":"not just with…but with…","meaning":"不只是帶著……而是帶著……","examples":[{"en":"A graduate returns not just with a line on a CV, but with judgment and confidence.","zh":"畢業生回來時不只是帶著履歷上的一行，而是帶著判斷力和信心。"},{"en":"This structure contrasts a small visible gain with a deeper real gain.","zh":"這個結構把表面的小收穫和更深的真正收穫作對比。"},{"en":"A student returns from internship not just with a certificate, but with practical skill.","zh":"學生完成實習後回來，不只是帶著證書，而是帶著實用技能。"},{"en":"It shows that experience gives more than something written on paper.","zh":"它顯示經驗給人的不只是紙上寫下的東西。"},{"en":"The phrase helps stress the deeper value of working elsewhere.","zh":"這個短語強調到其他地方工作的深層價值。"}],"source":"2016 Q3.pdf","sourcePage":9},{"front":"a line on a CV","meaning":"履歷上的一行","examples":[{"en":"Overseas work experience is more than a line on a CV.","zh":"海外工作經驗不只是履歷上的一行。"},{"en":"A line on a CV means one short item written on a résumé.","zh":"履歷上的一行意思是履歷中寫下的一個簡短項目。"},{"en":"An internship may appear as a line on a CV, but the skills gained matter more.","zh":"實習可能顯示為履歷上的一行，但獲得的技能更重要。"},{"en":"Employers care about what a graduate learned, not only the line on the CV.","zh":"僱主關心畢業生學到甚麼，而不只是履歷上的一行。"},{"en":"Real experience should become confidence and judgement, not just a line on a CV.","zh":"真實經驗應變成信心和判斷力，而不只是履歷上的一行。"}],"source":"2016 Q3.pdf","sourcePage":9},{"front":"judgment","meaning":"判斷力","examples":[{"en":"Working abroad can develop judgment.","zh":"在海外工作可以培養判斷力。"},{"en":"Judgment is the ability to make sensible decisions after considering facts and situations.","zh":"判斷力是考慮事實和情況後作出明智決定的能力。"},{"en":"A worker shows judgment when they choose the right way to answer an angry customer.","zh":"工作者選擇正確方式回應憤怒顧客時，就是顯示判斷力。"},{"en":"Regional work develops judgment because unfamiliar problems require careful choices.","zh":"區域工作會培養判斷力，因為陌生問題需要仔細選擇。"},{"en":"Employers value graduates with judgment because they can act responsibly.","zh":"僱主重視有判斷力的畢業生，因為他們能負責任地行動。"}],"source":"2016 Q3.pdf","sourcePage":9},{"front":"confidence and resilience","meaning":"信心和抗逆力","examples":[{"en":"Regional experience can build confidence and resilience.","zh":"區域經驗可以建立信心和抗逆力。"},{"en":"Confidence and resilience mean belief in oneself and the ability to recover from difficulty.","zh":"信心和抗逆力是指相信自己，以及從困難中恢復的能力。"},{"en":"A graduate builds confidence and resilience by solving problems far from home.","zh":"畢業生在離家很遠的地方解決問題時，會建立信心和抗逆力。"},{"en":"Homesickness and work pressure can be painful but useful training.","zh":"思鄉和工作壓力可能痛苦，但也是有用訓練。"},{"en":"Confidence and resilience help young workers face future challenges.","zh":"信心和抗逆力幫助年輕工作者面對未來挑戰。"}],"source":"2016 Q3.pdf","sourcePage":10},{"front":"as valuable as","meaning":"與……一樣有價值","examples":[{"en":"That kind of education is as valuable as anything taught in a lecture theatre.","zh":"那種教育與大講堂中教授的任何東西一樣有價值。"},{"en":"As valuable as means equally useful, important, or worthwhile.","zh":"與……一樣有價值意思是同樣有用、重要或值得。"},{"en":"Real workplace experience can be as valuable as classroom learning.","zh":"真實工作經驗可以與課堂學習一樣有價值。"},{"en":"Living abroad may teach lessons as valuable as those found in textbooks.","zh":"在海外生活可能教人與課本中一樣有價值的課。"},{"en":"This phrase helps compare two different but important forms of learning.","zh":"這個短語幫助比較兩種不同但重要的學習形式。"}],"source":"2016 Q3.pdf","sourcePage":10},{"front":"lecture theatre","meaning":"演講廳；大講堂","examples":[{"en":"Some lessons cannot be taught in a lecture theatre.","zh":"有些課不能在大講堂中教授。"},{"en":"A lecture theatre is a large room where university students listen to lectures.","zh":"大講堂是大學生聽講座的大型課室。"},{"en":"Students learn theories in a lecture theatre, but workplaces test those theories.","zh":"學生在大講堂學理論，但工作場所會測試這些理論。"},{"en":"A lecture theatre can teach knowledge, but not every real-life difficulty.","zh":"大講堂可以教授知識，但不能教授每個現實困難。"},{"en":"Working abroad provides lessons beyond the lecture theatre.","zh":"在海外工作提供大講堂以外的課。"}],"source":"2016 Q3.pdf","sourcePage":10},{"front":"seeking work in Asia","meaning":"在亞洲尋找工作","examples":[{"en":"Seeking work in Asia does not mean abandoning Hong Kong.","zh":"在亞洲尋找工作並不代表放棄香港。"},{"en":"Seeking work in Asia means looking for jobs in Asian cities or countries.","zh":"在亞洲尋找工作意思是在亞洲城市或國家找工作。"},{"en":"A graduate seeking work in Asia may apply to firms in Singapore, Seoul, and Bangkok.","zh":"在亞洲尋找工作的畢業生可能申請新加坡、首爾和曼谷的公司。"},{"en":"Seeking work regionally can be a way to grow skills and networks.","zh":"在區域尋找工作可以是增長技能和人脈的方法。"},{"en":"Graduates can seek work in Asia while still caring about Hong Kong’s future.","zh":"畢業生可以在亞洲尋找工作，同時仍關心香港未來。"}],"source":"2016 Q3.pdf","sourcePage":10},{"front":"abandoning Hong Kong","meaning":"放棄香港","examples":[{"en":"Working elsewhere does not mean abandoning Hong Kong.","zh":"到其他地方工作並不代表放棄香港。"},{"en":"Abandoning Hong Kong means giving up on the city or cutting off responsibility toward it.","zh":"放棄香港意思是放棄這個城市或切斷對它的責任。"},{"en":"A graduate working in Tokyo is not abandoning Hong Kong if they keep ties with home.","zh":"在東京工作的畢業生如果仍與家鄉保持連繫，就不是放棄香港。"},{"en":"People can leave temporarily without abandoning their community.","zh":"人們可以暫時離開，而不是放棄自己的社群。"},{"en":"Regional experience can help Hong Kong later instead of abandoning it.","zh":"區域經驗日後可以幫助香港，而不是放棄它。"}],"source":"2016 Q3.pdf","sourcePage":10},{"front":"fear that","meaning":"擔心","examples":[{"en":"Some people fear that graduates leaving will drain Hong Kong of talent.","zh":"有些人擔心畢業生離開會令香港人才流失。"},{"en":"Fear that means worry that something bad may happen.","zh":"擔心某事意思是憂慮壞事可能發生。"},{"en":"Parents may fear that working abroad will make their children lonely.","zh":"父母可能擔心海外工作會令孩子孤單。"},{"en":"People fear talent loss when many young workers leave at the same time.","zh":"當許多年輕工作者同時離開，人們會擔心人才流失。"},{"en":"This phrase introduces a concern that needs to be answered.","zh":"這個短語引出一個需要回應的憂慮。"}],"source":"2016 Q3.pdf","sourcePage":10},{"front":"drain our city of talent","meaning":"令我們城市人才流失","examples":[{"en":"Encouraging graduates to leave may seem to drain our city of talent.","zh":"鼓勵畢業生離開可能看似會令我們城市人才流失。"},{"en":"To drain a city of talent means to take away many skilled people from it.","zh":"令城市人才流失意思是帶走城市中許多有技能的人。"},{"en":"A city may worry about being drained of talent if young professionals never return.","zh":"如果年輕專業人士永不回來，城市可能擔心人才流失。"},{"en":"This fear is serious, but regional experience can also bring knowledge back.","zh":"這種恐懼很嚴肅，但區域經驗也可以把知識帶回來。"},{"en":"Good policy should turn outward movement into connection, not talent loss.","zh":"好政策應把向外流動轉化為連繫，而不是人才流失。"}],"source":"2016 Q3.pdf","sourcePage":10},{"front":"take their concern seriously","meaning":"認真看待他們的憂慮","examples":[{"en":"I take their concern seriously.","zh":"我認真看待他們的憂慮。"},{"en":"To take a concern seriously means to respect it and consider it carefully.","zh":"認真看待某個憂慮意思是尊重並仔細考慮它。"},{"en":"A school takes parents’ concern seriously when it explains safety plans clearly.","zh":"學校清楚解釋安全計劃時，就是認真看待家長的憂慮。"},{"en":"Taking concerns seriously does not mean agreeing with every fear.","zh":"認真看待憂慮不代表同意每種恐懼。"},{"en":"A balanced argument answers concerns instead of dismissing them.","zh":"平衡的論點會回應憂慮，而不是輕視它們。"}],"source":"2016 Q3.pdf","sourcePage":10},{"front":"I do not think it follows","meaning":"我不認為這必然成立","examples":[{"en":"I do not think it follows that graduates will forget Hong Kong.","zh":"我不認為畢業生會忘記香港這個結論必然成立。"},{"en":"I do not think it follows means I do not believe that conclusion must result from the previous idea.","zh":"我不認為這必然成立，意思是我不相信該結論一定由前一個想法導致。"},{"en":"If students study abroad, it does not follow that they will stop caring about home.","zh":"如果學生到海外讀書，並不必然代表他們會停止關心家鄉。"},{"en":"This phrase is useful for challenging weak reasoning.","zh":"這個短語適合用來挑戰薄弱推理。"},{"en":"It helps the writer separate fear from logical conclusion.","zh":"它幫助作者區分恐懼和合乎邏輯的結論。"}],"source":"2016 Q3.pdf","sourcePage":10},{"front":"to say that…is not to say that…","meaning":"說……並不是說……","examples":[{"en":"To say that young people should look beyond Hong Kong is not to say that they should forget Hong Kong.","zh":"說年輕人應放眼香港以外，並不是說他們應忘記香港。"},{"en":"This structure means one statement should not be misunderstood as a stronger or different claim.","zh":"這個結構意思是一個說法不應被誤解為更強或不同的主張。"},{"en":"To say that students should explore Asia is not to say that Hong Kong has no value.","zh":"說學生應探索亞洲，並不是說香港沒有價值。"},{"en":"This phrase helps writers make careful distinctions.","zh":"這個短語幫助作者作出謹慎區分。"},{"en":"It is useful when answering criticism fairly.","zh":"它適合用來公平回應批評。"}],"source":"2016 Q3.pdf","sourcePage":10},{"front":"forget Hong Kong","meaning":"忘記香港","examples":[{"en":"Looking beyond Hong Kong does not mean forgetting Hong Kong.","zh":"放眼香港以外並不代表忘記香港。"},{"en":"To forget Hong Kong means to stop caring about the city, its people, or its future.","zh":"忘記香港意思是停止關心這個城市、它的人和它的未來。"},{"en":"A graduate working in Singapore can still support Hong Kong through networks and knowledge.","zh":"在新加坡工作的畢業生仍可以透過人脈和知識支持香港。"},{"en":"Leaving physically does not always mean forgetting emotionally or professionally.","zh":"身體離開不一定代表情感上或專業上忘記。"},{"en":"Graduates can remember Hong Kong while gaining experience elsewhere.","zh":"畢業生可以記得香港，同時在其他地方累積經驗。"}],"source":"2016 Q3.pdf","sourcePage":11},{"front":"on the contrary","meaning":"相反","examples":[{"en":"On the contrary, regional experience can turn graduates into bridges.","zh":"相反，區域經驗可以把畢業生變成橋樑。"},{"en":"On the contrary introduces an opposite idea to the one just mentioned.","zh":"相反用來引出與剛才想法相反的觀點。"},{"en":"Working abroad does not weaken Hong Kong; on the contrary, it may connect Hong Kong to new markets.","zh":"海外工作不會削弱香港；相反，它可能把香港連接到新市場。"},{"en":"Writers use this phrase to correct a mistaken assumption strongly.","zh":"作者使用這個短語有力地糾正錯誤假設。"},{"en":"It helps show that leaving can create connection rather than loss.","zh":"它幫助顯示離開可以創造連繫，而不是損失。"}],"source":"2016 Q3.pdf","sourcePage":11},{"front":"regional experience","meaning":"區域經驗","examples":[{"en":"Regional experience can benefit Hong Kong in the long run.","zh":"區域經驗長遠而言可以對香港有利。"},{"en":"Regional experience means work or life experience gained in nearby countries or cities.","zh":"區域經驗是指在附近國家或城市獲得的工作或生活經驗。"},{"en":"A graduate working in Singapore gains regional experience in Southeast Asian business.","zh":"在新加坡工作的畢業生會獲得東南亞商業方面的區域經驗。"},{"en":"Regional experience helps people understand markets beyond Hong Kong.","zh":"區域經驗幫助人理解香港以外的市場。"},{"en":"Such experience becomes valuable when graduates share it with local firms.","zh":"當畢業生與本地公司分享這種經驗時，它會變得有價值。"}],"source":"2016 Q3.pdf","sourcePage":11},{"front":"turn them into bridges","meaning":"把他們變成橋樑","examples":[{"en":"Regional experience can turn graduates into bridges between Hong Kong and Asia.","zh":"區域經驗可以把畢業生變成香港和亞洲之間的橋樑。"},{"en":"To turn them into bridges means to make them connectors between different places or groups.","zh":"把他們變成橋樑意思是令他們成為不同地方或群體之間的連接者。"},{"en":"A graduate who knows both Hong Kong and Singapore can become a bridge for business.","zh":"同時了解香港和新加坡的畢業生，可以成為商業橋樑。"},{"en":"These bridges help ideas, jobs, and customers move between markets.","zh":"這些橋樑幫助想法、工作和顧客在市場之間流動。"},{"en":"Regional work turns graduates into bridges when they keep connections on both sides.","zh":"當畢業生保持兩邊連繫時，區域工作會把他們變成橋樑。"}],"source":"2016 Q3.pdf","sourcePage":11},{"front":"the rest of Asia","meaning":"亞洲其他地區","examples":[{"en":"Graduates can become bridges between Hong Kong and the rest of Asia.","zh":"畢業生可以成為香港和亞洲其他地區之間的橋樑。"},{"en":"The rest of Asia means Asian places outside Hong Kong.","zh":"亞洲其他地區意思是香港以外的亞洲地方。"},{"en":"Singapore, Seoul, Bangkok, Taipei, and Tokyo are part of the rest of Asia.","zh":"新加坡、首爾、曼谷、台北和東京都是亞洲其他地區的一部分。"},{"en":"Understanding the rest of Asia helps Hong Kong graduates see wider opportunities.","zh":"理解亞洲其他地區幫助香港畢業生看見更廣闊機會。"},{"en":"Strong links with the rest of Asia can benefit Hong Kong’s future.","zh":"與亞洲其他地區建立強大連繫，可以有利香港未來。"}],"source":"2016 Q3.pdf","sourcePage":11},{"front":"spend three years in","meaning":"在……度過三年","examples":[{"en":"A graduate may spend three years in Singapore.","zh":"畢業生可能在新加坡度過三年。"},{"en":"To spend three years in a place means to live, work, or study there for three years.","zh":"在某地度過三年，意思是在那裏生活、工作或學習三年。"},{"en":"A graduate may spend three years in Tokyo learning technology and language skills.","zh":"畢業生可能在東京度過三年，學習科技和語言技能。"},{"en":"Several years in another city can build deep regional understanding.","zh":"在另一個城市數年可以建立深厚的區域理解。"},{"en":"Spending time abroad can create contacts that remain useful later.","zh":"在海外度過一段時間可以建立日後仍有用的人脈。"}],"source":"2016 Q3.pdf","sourcePage":11},{"front":"start-up","meaning":"初創企業","examples":[{"en":"A Hong Kong start-up may benefit from regional experience.","zh":"香港初創企業可能從區域經驗中受益。"},{"en":"A start-up is a new company that is trying to grow, often with a new idea or product.","zh":"初創企業是正在嘗試成長的新公司，通常有新想法或新產品。"},{"en":"A start-up may need young workers who understand technology and customers.","zh":"初創企業可能需要了解科技和顧客的年輕工作者。"},{"en":"Graduates with regional experience can help start-ups enter new markets.","zh":"具備區域經驗的畢業生可以幫助初創企業進入新市場。"},{"en":"A start-up grows faster when it learns from different cities.","zh":"初創企業向不同城市學習時，會成長得更快。"}],"source":"2016 Q3.pdf","sourcePage":11},{"front":"Southeast Asian customers","meaning":"東南亞客戶","examples":[{"en":"A graduate may help a start-up understand Southeast Asian customers.","zh":"畢業生可能幫助初創企業了解東南亞客戶。"},{"en":"Southeast Asian customers are buyers or users from countries such as Thailand, Vietnam, Malaysia, and Indonesia.","zh":"東南亞客戶是來自泰國、越南、馬來西亞和印尼等國家的買家或使用者。"},{"en":"These customers may have different languages, habits, and expectations.","zh":"這些客戶可能有不同語言、習慣和期望。"},{"en":"Understanding Southeast Asian customers helps companies design better services.","zh":"理解東南亞客戶幫助公司設計更好的服務。"},{"en":"Regional work experience can make graduates useful to firms entering Southeast Asia.","zh":"區域工作經驗可以令畢業生對進入東南亞的公司有用。"}],"source":"2016 Q3.pdf","sourcePage":11},{"front":"mainland technology company","meaning":"內地科技公司","examples":[{"en":"Someone who works in a mainland technology company may bring back useful knowledge.","zh":"在內地科技公司工作的人可能帶回有用知識。"},{"en":"A mainland technology company is a technology firm based in mainland China.","zh":"內地科技公司是以中國內地為基地的科技企業。"},{"en":"Such a company may work on apps, artificial intelligence, e-commerce, or hardware.","zh":"這類公司可能從事應用程式、人工智能、電子商務或硬件。"},{"en":"Working there can teach graduates about production speed and large user markets.","zh":"在那裏工作可以教畢業生了解生產速度和大型用戶市場。"},{"en":"Graduates may later use this knowledge to support Hong Kong firms.","zh":"畢業生日後可能運用這些知識支持香港公司。"}],"source":"2016 Q3.pdf","sourcePage":11},{"front":"bring back knowledge about","meaning":"帶回關於……的知識","examples":[{"en":"Graduates may bring back knowledge about production, logistics and innovation.","zh":"畢業生可能帶回關於生產、物流和創新的知識。"},{"en":"To bring back knowledge about something means to return with useful understanding of it.","zh":"帶回關於某事的知識，意思是回來時帶著對它的有用理解。"},{"en":"A graduate may bring back knowledge about Southeast Asian customers after working in Bangkok.","zh":"畢業生在曼谷工作後，可能帶回關於東南亞客戶的知識。"},{"en":"Bringing back knowledge helps local companies learn from other markets.","zh":"帶回知識幫助本地公司向其他市場學習。"},{"en":"Overseas work benefits Hong Kong when graduates bring back practical knowledge.","zh":"當畢業生帶回實用知識時，海外工作便有利香港。"}],"source":"2016 Q3.pdf","sourcePage":11},{"front":"production","meaning":"生產","examples":[{"en":"Graduates may bring back knowledge about production.","zh":"畢業生可能帶回關於生產的知識。"},{"en":"Production means the process of making goods, products, or services.","zh":"生產是製造商品、產品或服務的過程。"},{"en":"A technology company improves production when it makes devices faster and more safely.","zh":"科技公司更快和更安全地製造裝置時，就是改善生產。"},{"en":"Understanding production helps graduates see how ideas become real products.","zh":"理解生產幫助畢業生看見想法如何變成真實產品。"},{"en":"Regional work can teach practical lessons about production that classrooms cannot show fully.","zh":"區域工作可以教授課室未能完全展示的生產實用知識。"}],"source":"2016 Q3.pdf","sourcePage":12},{"front":"logistics","meaning":"物流","examples":[{"en":"Regional experience can provide knowledge about logistics.","zh":"區域經驗可以提供關於物流的知識。"},{"en":"Logistics means the planning and movement of goods, people, or resources from one place to another.","zh":"物流是規劃和移動貨物、人員或資源由一地到另一地的過程。"},{"en":"A company needs good logistics to deliver products on time.","zh":"公司需要良好物流，才能準時送達產品。"},{"en":"Graduates who understand logistics can help businesses manage supply chains.","zh":"理解物流的畢業生可以幫助企業管理供應鏈。"},{"en":"Asian work experience may teach logistics through ports, warehouses, and delivery systems.","zh":"亞洲工作經驗可能透過港口、倉庫和配送系統教授物流。"}],"source":"2016 Q3.pdf","sourcePage":12},{"front":"innovation","meaning":"創新","examples":[{"en":"Graduates may bring back knowledge about innovation.","zh":"畢業生可能帶回關於創新的知識。"},{"en":"Innovation means creating new ideas, methods, products, or improvements.","zh":"創新意思是創造新想法、方法、產品或改善。"},{"en":"A start-up shows innovation when it solves an old problem in a new way.","zh":"初創企業用新方式解決舊問題時，就是展示創新。"},{"en":"Working in fast-growing cities can expose graduates to innovation daily.","zh":"在快速成長的城市工作，可以讓畢業生日常接觸創新。"},{"en":"Hong Kong benefits when graduates bring back innovative thinking.","zh":"當畢業生帶回創新思維時，香港會受益。"}],"source":"2016 Q3.pdf","sourcePage":12},{"front":"even if","meaning":"即使","examples":[{"en":"Even if graduates do not return immediately, their networks can still help Hong Kong.","zh":"即使畢業生不立即回來，他們的人脈仍可幫助香港。"},{"en":"Even if means although something may happen or be true.","zh":"即使意思是雖然某事可能發生或成立。"},{"en":"Even if a graduate stays abroad for years, they may still support Hong Kong companies.","zh":"即使畢業生在海外多年，他們仍可能支持香港公司。"},{"en":"This phrase helps show that one concern does not destroy the whole argument.","zh":"這個短語幫助顯示一個憂慮不會推翻整個論點。"},{"en":"Even if the path is uncertain, wider experience can still be valuable.","zh":"即使道路不確定，更廣闊經驗仍可以有價值。"}],"source":"2016 Q3.pdf","sourcePage":12},{"front":"return immediately","meaning":"立即回來","examples":[{"en":"Some graduates may not return immediately.","zh":"有些畢業生可能不會立即回來。"},{"en":"To return immediately means to come back at once or very soon.","zh":"立即回來意思是馬上或很快回來。"},{"en":"A graduate may not return immediately after finding good training abroad.","zh":"畢業生在海外找到良好培訓後，可能不會立即回來。"},{"en":"Not returning immediately does not mean cutting ties with Hong Kong.","zh":"不立即回來不代表切斷與香港的連繫。"},{"en":"Graduates can still share knowledge and networks before they return.","zh":"畢業生在回來前仍可以分享知識和人脈。"}],"source":"2016 Q3.pdf","sourcePage":12},{"front":"professional networks","meaning":"專業人脈網絡","examples":[{"en":"Graduates’ professional networks can connect back to Hong Kong.","zh":"畢業生的專業人脈網絡可以重新連接到香港。"},{"en":"Professional networks are work-related contacts, relationships, and connections.","zh":"專業人脈網絡是與工作相關的聯絡人、關係和連繫。"},{"en":"A graduate builds a professional network by meeting clients, mentors, and colleagues.","zh":"畢業生透過認識客戶、導師和同事來建立專業人脈網絡。"},{"en":"Professional networks can help people find jobs, partners, and market information.","zh":"專業人脈網絡可以幫助人尋找工作、夥伴和市場資訊。"},{"en":"Regional networks become useful when they connect opportunities back to Hong Kong.","zh":"當區域人脈把機會重新連接到香港時，它就變得有用。"}],"source":"2016 Q3.pdf","sourcePage":12},{"front":"connect back to","meaning":"重新連接到","examples":[{"en":"Their networks can still connect back to our city.","zh":"他們的人脈仍可以重新連接到我們的城市。"},{"en":"To connect back to a place means to create links that return value, information, or relationships to that place.","zh":"重新連接到某地，意思是建立把價值、資訊或關係帶回該地的連繫。"},{"en":"A graduate in Singapore can connect back to Hong Kong by introducing business partners.","zh":"在新加坡的畢業生可以透過介紹商業夥伴重新連接到香港。"},{"en":"Connections abroad can connect back to home through projects and advice.","zh":"海外連繫可以透過項目和建議重新連接到家鄉。"},{"en":"Graduates who connect back to Hong Kong prove that leaving can still help home.","zh":"重新連接到香港的畢業生證明離開仍可以幫助家鄉。"}],"source":"2016 Q3.pdf","sourcePage":12},{"front":"the question, therefore, is not whether…but whether…","meaning":"因此，問題不是是否……而是是否……","examples":[{"en":"The question is not whether graduates should stay or leave forever, but whether they should grow where opportunities appear.","zh":"因此，問題不是畢業生應留下或永遠離開，而是他們是否應在機會出現的地方成長。"},{"en":"This structure shifts attention from a false choice to the real issue.","zh":"這個結構把注意力從錯誤二選一轉向真正問題。"},{"en":"The question is not whether students love Hong Kong, but whether they can grow with wider experience.","zh":"問題不是學生是否愛香港，而是他們能否透過更廣闊經驗成長。"},{"en":"Writers use this structure to make an argument more balanced.","zh":"作者使用這個結構令論點更平衡。"},{"en":"It helps readers focus on growth rather than fear of leaving.","zh":"它幫助讀者聚焦成長，而不是害怕離開。"}],"source":"2016 Q3.pdf","sourcePage":12},{"front":"stay or leave forever","meaning":"留下或永遠離開","examples":[{"en":"The issue is not simply whether graduates should stay or leave forever.","zh":"問題不只是畢業生應留下或永遠離開。"},{"en":"Stay or leave forever means remain in one place permanently or depart permanently.","zh":"留下或永遠離開意思是永久留在一地或永久離開。"},{"en":"Career choices are rarely as simple as staying or leaving forever.","zh":"事業選擇很少像留下或永遠離開那樣簡單。"},{"en":"A graduate may work abroad for three years and later return with experience.","zh":"畢業生可能在海外工作三年，之後帶著經驗回來。"},{"en":"The better question is how graduates can grow wherever they work.","zh":"更好的問題是畢業生可以如何在任何工作地方成長。"}],"source":"2016 Q3.pdf","sourcePage":12},{"front":"brave enough to grow","meaning":"有足夠勇氣成長","examples":[{"en":"Graduates should be brave enough to grow where opportunities appear.","zh":"畢業生應有足夠勇氣在機會出現的地方成長。"},{"en":"Brave enough to grow means having the courage to improve through new and difficult experiences.","zh":"有足夠勇氣成長意思是有勇氣透過新而困難的經驗改善自己。"},{"en":"A young worker is brave enough to grow when they accept a useful job in an unfamiliar city.","zh":"年輕工作者接受陌生城市中的有用工作時，就是有足夠勇氣成長。"},{"en":"Growth often requires courage because comfort zones feel safer.","zh":"成長常需要勇氣，因為舒適圈感覺更安全。"},{"en":"Graduates who are brave enough to grow may build stronger futures.","zh":"有足夠勇氣成長的畢業生，可能建立更穩固的未來。"}],"source":"2016 Q3.pdf","sourcePage":12},{"front":"where opportunities appear","meaning":"在機會出現的地方","examples":[{"en":"Graduates should grow where opportunities appear.","zh":"畢業生應在機會出現的地方成長。"},{"en":"Where opportunities appear means in the places or situations where chances become available.","zh":"在機會出現的地方，意思是在機會變得可得的地方或情況中。"},{"en":"If a technology role appears in Shenzhen, an engineering graduate may grow there.","zh":"如果科技職位在深圳出現，工程畢業生可能在那裏成長。"},{"en":"Opportunities do not always appear in the city where a person was born.","zh":"機會不一定出現在一個人出生的城市。"},{"en":"Graduates should follow real opportunities, not only familiar locations.","zh":"畢業生應跟隨真正機會，而不只是熟悉地方。"}],"source":"2016 Q3.pdf","sourcePage":13},{"front":"all things considered","meaning":"綜合考慮各方面","examples":[{"en":"All things considered, graduates should look for opportunities in other Asian cities.","zh":"綜合考慮各方面，畢業生應在其他亞洲城市尋找機會。"},{"en":"All things considered means after thinking about all important points together.","zh":"綜合考慮各方面意思是一起考慮所有重要觀點後。"},{"en":"All things considered, a regional job may be better than waiting endlessly at home.","zh":"綜合考慮各方面，區域工作可能比在家無止境等待更好。"},{"en":"Writers use this phrase to introduce a final balanced judgement.","zh":"作者使用這個短語來引出平衡的最終判斷。"},{"en":"It shows that the conclusion considers both benefits and risks.","zh":"它顯示結論考慮了好處和風險。"}],"source":"2016 Q3.pdf","sourcePage":13},{"front":"strongly support the suggestion","meaning":"堅決支持這項建議","examples":[{"en":"I strongly support the suggestion that graduates should explore other Asian cities.","zh":"我堅決支持畢業生應探索其他亞洲城市這項建議。"},{"en":"To strongly support a suggestion means to agree with it firmly and openly.","zh":"堅決支持一項建議意思是堅定而公開地同意它。"},{"en":"A teacher may strongly support internships if they help students gain experience.","zh":"如果實習能幫助學生獲得經驗，老師可能堅決支持實習。"},{"en":"Strong support should come with reasons, examples, and practical advice.","zh":"堅決支持應配合理據、例子和實際建議。"},{"en":"The writer strongly supports the suggestion because it expands graduates’ choices.","zh":"作者堅決支持這項建議，因為它擴闊畢業生的選擇。"}],"source":"2016 Q3.pdf","sourcePage":13},{"front":"look for opportunities","meaning":"尋找機會","examples":[{"en":"Graduates should look for opportunities in other Asian cities.","zh":"畢業生應在其他亞洲城市尋找機會。"},{"en":"To look for opportunities means to search actively for chances to work, learn, or grow.","zh":"尋找機會意思是主動搜尋工作、學習或成長的機會。"},{"en":"A graduate may look for opportunities by reading job boards and contacting alumni.","zh":"畢業生可以透過查看招聘網站和聯絡校友來尋找機會。"},{"en":"Looking for opportunities requires effort, research, and patience.","zh":"尋找機會需要努力、研究和耐性。"},{"en":"People find more chances when they look for opportunities beyond familiar places.","zh":"當人們在熟悉地方以外尋找機會時，會找到更多可能性。"}],"source":"2016 Q3.pdf","sourcePage":13},{"front":"the path may involve","meaning":"這條路可能涉及","examples":[{"en":"The path may involve uncertainty, homesickness and practical costs.","zh":"這條路可能涉及不確定性、思鄉和實際開支。"},{"en":"The path may involve means this route may include certain difficulties or features.","zh":"這條路可能涉及意思是這個途徑可能包括某些困難或特點。"},{"en":"A career path may involve long training before better jobs appear.","zh":"事業道路可能涉及長時間培訓，之後才有更好工作出現。"},{"en":"Working abroad may involve both opportunity and pressure.","zh":"海外工作可能同時涉及機會和壓力。"},{"en":"This phrase prepares readers to think realistically about a choice.","zh":"這個短語讓讀者現實地思考一個選擇。"}],"source":"2016 Q3.pdf","sourcePage":13},{"front":"uncertainty","meaning":"不確定性","examples":[{"en":"Working abroad may involve uncertainty.","zh":"到海外工作可能涉及不確定性。"},{"en":"Uncertainty means not knowing exactly what will happen.","zh":"不確定性意思是不確切知道將會發生甚麼。"},{"en":"A graduate may feel uncertainty before moving to a new city for work.","zh":"畢業生搬到新城市工作前，可能感到不確定性。"},{"en":"Uncertainty can be stressful, but planning can reduce fear.","zh":"不確定性可以令人有壓力，但規劃能減少恐懼。"},{"en":"Career growth often includes some uncertainty.","zh":"事業成長常包括一些不確定性。"}],"source":"2016 Q3.pdf","sourcePage":13},{"front":"homesickness","meaning":"思鄉","examples":[{"en":"Graduates working elsewhere may experience homesickness.","zh":"到其他地方工作的畢業生可能會經歷思鄉。"},{"en":"Homesickness is sadness caused by missing home, family, and familiar places.","zh":"思鄉是因想念家、家人和熟悉地方而產生的傷感。"},{"en":"A graduate may feel homesickness during the first month in another city.","zh":"畢業生在另一個城市的第一個月可能感到思鄉。"},{"en":"Homesickness becomes easier when people build routines and friendships.","zh":"當人建立日常規律和友誼時，思鄉會變得較容易承受。"},{"en":"Surviving homesickness can make graduates more independent.","zh":"捱過思鄉可以令畢業生更獨立。"}],"source":"2016 Q3.pdf","sourcePage":13},{"front":"practical costs","meaning":"實際開支","examples":[{"en":"The path may involve practical costs.","zh":"這條路可能涉及實際開支。"},{"en":"Practical costs are real expenses or difficulties involved in doing something.","zh":"實際開支是做某事涉及的真實費用或困難。"},{"en":"Moving abroad may involve rent, transport, visa fees, and daily living costs.","zh":"搬到海外可能涉及租金、交通、簽證費和日常生活費。"},{"en":"Graduates should calculate practical costs before accepting a regional job.","zh":"畢業生接受區域工作前，應計算實際開支。"},{"en":"Careful planning makes practical costs less frightening.","zh":"仔細規劃可以令實際開支不那麼可怕。"}],"source":"2016 Q3.pdf","sourcePage":13},{"front":"research carefully","meaning":"仔細研究","examples":[{"en":"Students must research carefully before working elsewhere.","zh":"學生到其他地方工作前必須仔細研究。"},{"en":"To research carefully means to gather and check information seriously before deciding.","zh":"仔細研究意思是在決定前認真收集和核實資訊。"},{"en":"Graduates should research carefully about salary, rent, visas, and workplace culture.","zh":"畢業生應仔細研究薪金、租金、簽證和工作文化。"},{"en":"Careful research prevents poor choices based only on excitement.","zh":"仔細研究可以防止人只憑興奮作出差劣選擇。"},{"en":"Working abroad becomes safer when students research carefully first.","zh":"當學生先仔細研究，海外工作會變得較安全。"}],"source":"2016 Q3.pdf","sourcePage":13},{"front":"prepare financially","meaning":"在財政上做好準備","examples":[{"en":"Graduates should prepare financially before moving abroad.","zh":"畢業生搬到海外前應在財政上做好準備。"},{"en":"To prepare financially means to plan money, savings, and expenses before taking action.","zh":"在財政上做好準備意思是在行動前規劃金錢、儲蓄和開支。"},{"en":"A graduate prepares financially by saving enough for rent and emergency costs.","zh":"畢業生儲夠租金和緊急開支，就是在財政上做好準備。"},{"en":"Financial preparation reduces stress in the first months abroad.","zh":"財政準備能減少海外最初幾個月的壓力。"},{"en":"Working elsewhere is easier when graduates prepare financially in advance.","zh":"當畢業生預先在財政上做好準備，到其他地方工作會更容易。"}],"source":"2016 Q3.pdf","sourcePage":13},{"front":"respect local cultures","meaning":"尊重當地文化","examples":[{"en":"Graduates must respect local cultures.","zh":"畢業生必須尊重當地文化。"},{"en":"To respect local cultures means to value and follow the customs and habits of the place where one works.","zh":"尊重當地文化意思是重視並遵循工作所在地的習俗和習慣。"},{"en":"A graduate respects local culture by learning basic greetings and workplace manners.","zh":"畢業生學習基本問候和工作場所禮儀，就是尊重當地文化。"},{"en":"Respect reduces misunderstanding and helps people build trust.","zh":"尊重能減少誤解，並幫助人建立信任。"},{"en":"Working abroad requires curiosity, humility, and respect for local cultures.","zh":"海外工作需要好奇心、謙遜和對當地文化的尊重。"}],"source":"2016 Q3.pdf","sourcePage":14},{"front":"invite alumni","meaning":"邀請校友","examples":[{"en":"Schools can invite alumni working in Asia to share their experiences.","zh":"學校可以邀請在亞洲工作的校友分享經驗。"},{"en":"To invite alumni means to ask former students to return or take part in an event.","zh":"邀請校友意思是請以前的學生回來或參與活動。"},{"en":"A school may invite alumni to speak about careers in Singapore or Seoul.","zh":"學校可能邀請校友談談在新加坡或首爾的事業。"},{"en":"Alumni can give realistic advice because they have already taken the path.","zh":"校友能提供現實建議，因為他們已經走過這條路。"},{"en":"Inviting alumni helps current students imagine possible futures.","zh":"邀請校友幫助現在的學生想像可能的未來。"}],"source":"2016 Q3.pdf","sourcePage":14},{"front":"alumni working in Asia","meaning":"在亞洲工作的校友","examples":[{"en":"Alumni working in Asia can share useful experiences.","zh":"在亞洲工作的校友可以分享有用經驗。"},{"en":"Alumni working in Asia are former students who now work in Asian cities or countries.","zh":"在亞洲工作的校友，是指現在於亞洲城市或國家工作的舊生。"},{"en":"They may explain how they found jobs, housing, and support abroad.","zh":"他們可能解釋自己如何在海外找到工作、住所和支援。"},{"en":"Their stories help students understand both opportunities and difficulties.","zh":"他們的故事幫助學生理解機會和困難。"},{"en":"Alumni working in Asia can become bridges between school and regional careers.","zh":"在亞洲工作的校友可以成為學校和區域事業之間的橋樑。"}],"source":"2016 Q3.pdf","sourcePage":14},{"front":"share their experiences","meaning":"分享他們的經驗","examples":[{"en":"Alumni can share their experiences with current students.","zh":"校友可以與現在的學生分享他們的經驗。"},{"en":"To share their experiences means to tell others what they learned or went through.","zh":"分享他們的經驗意思是告訴別人自己學到或經歷過的事情。"},{"en":"A graduate may share their experiences of finding work in Bangkok.","zh":"畢業生可能分享自己在曼谷找工作的經驗。"},{"en":"Shared experiences make advice more real than general career slogans.","zh":"分享經驗令建議比一般事業口號更真實。"},{"en":"Students can prepare better when alumni share their experiences honestly.","zh":"當校友誠實分享他們的經驗時，學生可以準備得更好。"}],"source":"2016 Q3.pdf","sourcePage":14},{"front":"strengthen regional internship schemes","meaning":"加強區域實習計劃","examples":[{"en":"Universities can strengthen regional internship schemes.","zh":"大學可以加強區域實習計劃。"},{"en":"To strengthen regional internship schemes means to improve programmes that place students in work experience across the region.","zh":"加強區域實習計劃意思是改善安排學生到區域內不同地方獲得工作經驗的計劃。"},{"en":"Universities strengthen such schemes by adding funding, guidance, and trusted employers.","zh":"大學可以透過增加資助、指導和可靠僱主來加強這類計劃。"},{"en":"Strong internship schemes help students test careers before full-time work.","zh":"強大的實習計劃幫助學生在全職工作前測試事業方向。"},{"en":"Regional internships make overseas work less frightening and more practical.","zh":"區域實習令海外工作不那麼可怕，並更實際可行。"}],"source":"2016 Q3.pdf","sourcePage":14},{"front":"regional internship schemes","meaning":"區域實習計劃","examples":[{"en":"Regional internship schemes can help students explore Asian cities.","zh":"區域實習計劃可以幫助學生探索亞洲城市。"},{"en":"Regional internship schemes are organised work-experience programmes in nearby countries or cities.","zh":"區域實習計劃是在附近國家或城市進行的有組織工作經驗計劃。"},{"en":"A student may join a regional internship scheme in Singapore for two months.","zh":"學生可能參加在新加坡為期兩個月的區域實習計劃。"},{"en":"These schemes help students learn workplace culture before graduating.","zh":"這些計劃幫助學生在畢業前了解工作文化。"},{"en":"Regional internship schemes can build confidence, language skills, and networks.","zh":"區域實習計劃可以建立信心、語言能力和人脈。"}],"source":"2016 Q3.pdf","sourcePage":14},{"front":"build language skills","meaning":"建立語言能力","examples":[{"en":"Graduates should build language skills early.","zh":"畢業生應及早建立語言能力。"},{"en":"To build language skills means to improve listening, speaking, reading, and writing abilities.","zh":"建立語言能力意思是改善聆聽、說話、閱讀和寫作能力。"},{"en":"A graduate builds language skills by practising English, Putonghua, or a local language daily.","zh":"畢業生每天練習英語、普通話或當地語言，就是建立語言能力。"},{"en":"Language skills help people communicate across cultures and handle customers.","zh":"語言能力幫助人跨文化溝通和接待顧客。"},{"en":"Building language skills early makes regional work easier later.","zh":"及早建立語言能力，會令日後區域工作更容易。"}],"source":"2016 Q3.pdf","sourcePage":14},{"front":"professional networks","meaning":"專業人脈","examples":[{"en":"Graduates should build professional networks early.","zh":"畢業生應及早建立專業人脈。"},{"en":"Professional networks are work-related relationships that can provide advice, information, and opportunities.","zh":"專業人脈是與工作相關、能提供建議、資訊和機會的關係。"},{"en":"A student builds professional networks by joining internships and career events.","zh":"學生透過參加實習和就業活動建立專業人脈。"},{"en":"Professional networks matter because many opportunities come through trusted contacts.","zh":"專業人脈很重要，因為許多機會來自可信任的聯絡人。"},{"en":"Graduates with regional networks may connect Hong Kong with other Asian markets.","zh":"擁有區域人脈的畢業生，可能把香港與其他亞洲市場連接起來。"}],"source":"2016 Q3.pdf","sourcePage":14},{"front":"gone are the days when","meaning":"……的日子已經過去","examples":[{"en":"Gone are the days when a young person’s future had to fit inside one city.","zh":"年輕人的未來必須局限於一個城市之內的日子已經過去。"},{"en":"Gone are the days when means that an old situation no longer exists.","zh":"……的日子已經過去，意思是舊有情況已不再存在。"},{"en":"Gone are the days when graduates could only look near home for work.","zh":"畢業生只能在家附近找工作的日子已經過去。"},{"en":"This phrase shows that society and career paths have changed.","zh":"這個短語顯示社會和事業道路已經改變。"},{"en":"Gone are the days when one city had to contain every dream.","zh":"一個城市必須容納每個夢想的日子已經過去。"}],"source":"2016 Q3.pdf","sourcePage":14},{"front":"fit inside one city","meaning":"局限於一個城市之內","examples":[{"en":"A young person’s future no longer has to fit inside one city.","zh":"年輕人的未來不再需要局限於一個城市之內。"},{"en":"To fit inside one city means to be limited to opportunities in one place only.","zh":"局限於一個城市之內意思是只限於一個地方的機會。"},{"en":"A creative student’s dream may not fit inside one city if better chances exist elsewhere.","zh":"如果其他地方有更好機會，創意學生的夢想可能不應局限於一個城市之內。"},{"en":"Modern careers often cross borders, languages, and industries.","zh":"現代事業常跨越邊界、語言和行業。"},{"en":"Graduates should not force their future to fit inside one city.","zh":"畢業生不應強迫自己的未來局限於一個城市之內。"}],"source":"2016 Q3.pdf","sourcePage":14},{"front":"stand tall","meaning":"堂堂正正地站穩","examples":[{"en":"Hong Kong’s graduates should stand tall in a competitive world.","zh":"香港畢業生應在競爭激烈的世界中堂堂正正地站穩。"},{"en":"To stand tall means to act with confidence, dignity, and courage.","zh":"堂堂正正地站穩意思是帶著信心、尊嚴和勇氣行動。"},{"en":"A graduate stands tall when they apply again after rejection.","zh":"畢業生被拒絕後再次申請，就是堂堂正正地站穩。"},{"en":"Young people can stand tall abroad if they prepare well and respect others.","zh":"年輕人如果準備充分並尊重他人，就能在海外堂堂正正地站穩。"},{"en":"Standing tall does not mean being arrogant; it means believing one can grow.","zh":"堂堂正正地站穩不代表傲慢，而是相信自己能成長。"}],"source":"2016 Q3.pdf","sourcePage":15},{"front":"competitive world","meaning":"競爭激烈的世界","examples":[{"en":"Graduates need courage in a competitive world.","zh":"畢業生在競爭激烈的世界中需要勇氣。"},{"en":"A competitive world is a world where people, companies, and cities must work hard to succeed.","zh":"競爭激烈的世界是人、公司和城市都必須努力才能成功的世界。"},{"en":"In a competitive world, a degree alone may not be enough.","zh":"在競爭激烈的世界中，單靠學位可能不足夠。"},{"en":"Graduates need skills, networks, and adaptability to survive competition.","zh":"畢業生需要技能、人脈和適應力，才能在競爭中生存。"},{"en":"Looking across Asia is one way to face a competitive world wisely.","zh":"放眼亞洲是明智面對競爭激烈世界的一種方式。"}],"source":"2016 Q3.pdf","sourcePage":15},{"front":"why leave?","meaning":"為甚麼要離開？","examples":[{"en":"Graduates should not only ask, “Why leave?”","zh":"畢業生不應只問：「為甚麼要離開？」"},{"en":"“Why leave?” means asking why a person should go away from home or the local market.","zh":"「為甚麼要離開？」意思是詢問一個人為何應離開家或本地市場。"},{"en":"A worried parent may ask, “Why leave Hong Kong when your family is here?”","zh":"擔心的父母可能會問：「家人在香港，為甚麼要離開？」"},{"en":"This question is understandable, but it may focus too much on fear.","zh":"這個問題可以理解，但它可能太集中於恐懼。"},{"en":"Graduates should ask “Why leave?” and also ask what they may gain.","zh":"畢業生應問「為甚麼要離開？」，也應問自己可能獲得甚麼。"}],"source":"2016 Q3.pdf","sourcePage":15},{"front":"why not explore?","meaning":"為甚麼不探索？","examples":[{"en":"Graduates should ask, “Why not explore?”","zh":"畢業生應問：「為甚麼不探索？」"},{"en":"“Why not explore?” means asking why a person should not consider new possibilities.","zh":"「為甚麼不探索？」意思是詢問為何不考慮新的可能性。"},{"en":"A student may ask, “Why not explore Singapore if there are good internships there?”","zh":"學生可能會問：「如果新加坡有好實習，為甚麼不探索？」"},{"en":"This question encourages curiosity rather than fear.","zh":"這個問題鼓勵好奇心，而不是恐懼。"},{"en":"“Why not explore?” can turn uncertainty into a first step.","zh":"「為甚麼不探索？」可以把不確定性轉化為第一步。"}],"source":"2016 Q3.pdf","sourcePage":15}],"dse/writing/part-b/2016/Q4":[{"front":"Dear Editor","meaning":"尊敬的編輯","examples":[{"en":"A formal letter to a newspaper can begin with “Dear Editor”.","zh":"寫給報章的正式信件可以以「尊敬的編輯」開始。"},{"en":"Dear Editor is a polite opening used when writing to the editor of a newspaper or magazine.","zh":"Dear Editor 是寫給報章或雜誌編輯時使用的禮貌開首語。"},{"en":"Students may write “Dear Editor” when sending a letter about school pressure to a newspaper.","zh":"學生向報章投稿討論學校壓力時，可以寫「尊敬的編輯」。"},{"en":"This greeting shows that the letter is formal and meant for publication or serious consideration.","zh":"這個稱呼顯示信件是正式的，並希望被刊登或認真考慮。"},{"en":"Use “Dear Editor” when you do not know the editor’s personal name.","zh":"當你不知道編輯的個人姓名時，可以使用 Dear Editor。"}],"source":"2016 Q4.pdf","sourcePage":1},{"front":"protection, not possession","meaning":"保護，而不是佔有","examples":[{"en":"Parents should offer protection, not possession.","zh":"父母應提供保護，而不是佔有。"},{"en":"Protection, not possession means parents should keep children safe without treating them as property.","zh":"protection, not possession 的意思是父母應保護子女安全，但不應把他們當成財物。"},{"en":"A parent shows protection, not possession, by setting rules while still respecting a teenager’s privacy.","zh":"父母訂立規則同時尊重青少年的私隱，就是提供保護，而不是佔有。"},{"en":"Possession controls a child, but protection guides the child toward safer choices.","zh":"佔有是控制孩子，而保護是引導孩子作出更安全的選擇。"},{"en":"This phrase reminds parents that love should not become ownership.","zh":"這個短語提醒父母，愛不應變成擁有。"}],"source":"2016 Q4.pdf","sourcePage":1},{"front":"It has recently been reported that","meaning":"最近有報道指","examples":[{"en":"It has recently been reported that some parents are installing monitoring apps.","zh":"最近有報道指，有些父母正在安裝監控應用程式。"},{"en":"It has recently been reported that is a formal way to introduce news or information from reports.","zh":"It has recently been reported that 是正式地引入新聞或報道資料的說法。"},{"en":"It has recently been reported that more teenagers feel pressure from constant online messages.","zh":"最近有報道指，更多青少年因持續的網上訊息而感到壓力。"},{"en":"This phrase is useful in letters because it gives background before stating an opinion.","zh":"這個短語在書信中很有用，因為它在表達意見前先提供背景。"},{"en":"It suggests that the issue is current and has public attention.","zh":"它暗示該議題是近期的，並受到公眾關注。"}],"source":"2016 Q4.pdf","sourcePage":1},{"front":"install apps on","meaning":"在……安裝應用程式","examples":[{"en":"Some parents install apps on their children’s mobile phones.","zh":"有些父母在子女的手機上安裝應用程式。"},{"en":"To install apps on a phone means to add software so the phone can perform new functions.","zh":"install apps on a phone 的意思是在手機加入軟件，讓手機有新功能。"},{"en":"A parent may install a timetable app on a child’s phone to help with revision.","zh":"父母可以在孩子手機上安裝時間表應用程式，幫助他溫習。"},{"en":"Installing apps without permission can damage trust if the child feels secretly watched.","zh":"未經同意安裝應用程式可能破壞信任，因為孩子會覺得被秘密監視。"},{"en":"This phrase describes a technical action that can have emotional consequences.","zh":"這個短語描述一個技術行動，但它可能帶來情感後果。"}],"source":"2016 Q4.pdf","sourcePage":1},{"front":"children’s mobile phones","meaning":"子女的手機","examples":[{"en":"Parents may install monitoring apps on their children’s mobile phones.","zh":"父母可能在子女的手機上安裝監控應用程式。"},{"en":"Children’s mobile phones are phones used by children or teenagers for school, communication, entertainment, and daily life.","zh":"children’s mobile phones 是兒童或青少年用於學校、溝通、娛樂和日常生活的手機。"},{"en":"Children’s mobile phones may contain homework messages, photos, group chats, and private notes.","zh":"子女的手機可能包含功課訊息、相片、群組聊天和私人筆記。"},{"en":"Because children’s mobile phones hold personal information, parents should handle them with care.","zh":"因為子女的手機載有個人資料，父母應謹慎處理。"},{"en":"This phrase reminds readers that a phone is both a device and a private space.","zh":"這個短語提醒讀者，手機既是裝置，也是私人空間。"}],"source":"2016 Q4.pdf","sourcePage":1},{"front":"monitor their activities","meaning":"監察他們的活動","examples":[{"en":"The apps are used to monitor children’s activities.","zh":"這些應用程式用來監察孩子的活動。"},{"en":"To monitor their activities means to watch, check, or record what they do.","zh":"monitor their activities 的意思是觀看、檢查或記錄他們做甚麼。"},{"en":"Some apps monitor children’s activities by tracking screen time, locations, or websites visited.","zh":"有些應用程式透過追蹤屏幕時間、位置或瀏覽網站來監察孩子的活動。"},{"en":"Monitoring activities may help in emergencies, but constant checking can feel invasive.","zh":"監察活動在緊急情況下可能有幫助，但持續檢查會令人感到被侵犯。"},{"en":"This phrase shows control through observation.","zh":"這個短語展示透過觀察進行控制。"}],"source":"2016 Q4.pdf","sourcePage":1},{"front":"hoping to make sure that","meaning":"希望確保","examples":[{"en":"Parents use these apps, hoping to make sure that phones are used responsibly.","zh":"父母使用這些應用程式，希望確保手機被負責任地使用。"},{"en":"Hoping to make sure that means wanting to confirm or protect a certain result.","zh":"hoping to make sure that 的意思是希望確認或保障某個結果。"},{"en":"Parents may set rules, hoping to make sure that children sleep before midnight.","zh":"父母可以訂立規則，希望確保孩子午夜前睡覺。"},{"en":"This phrase explains the intention behind an action, even if the action may have problems.","zh":"這個短語解釋行動背後的意圖，即使該行動可能有問題。"},{"en":"It is useful when describing why someone chooses a particular method.","zh":"當描述某人為何選擇某方法時，它很有用。"}],"source":"2016 Q4.pdf","sourcePage":1},{"front":"be used responsibly","meaning":"被負責任地使用","examples":[{"en":"Mobile phones should be used responsibly.","zh":"手機應被負責任地使用。"},{"en":"To be used responsibly means to be used with care, self-control, and respect for others.","zh":"be used responsibly 的意思是以謹慎、自制和尊重他人的方式使用。"},{"en":"A phone is used responsibly when a student does not spread rumours or disturb lessons.","zh":"當學生不散播謠言或打擾課堂時，手機就是被負責任地使用。"},{"en":"Responsible phone use protects sleep, study time, privacy, and relationships.","zh":"負責任的手機使用保護睡眠、學習時間、私隱和關係。"},{"en":"This phrase focuses on wise behaviour, not just obeying restrictions.","zh":"這個短語聚焦明智行為，而不只是遵守限制。"}],"source":"2016 Q4.pdf","sourcePage":1},{"front":"serve as","meaning":"充當；用作","examples":[{"en":"Phones now serve as schoolbags, cameras, libraries and social spaces.","zh":"手機現在充當書包、相機、圖書館和社交空間。"},{"en":"To serve as something means to function as or be used as that thing.","zh":"serve as something 的意思是發揮某物的功能，或被用作某物。"},{"en":"A phone can serve as a dictionary when students check new words.","zh":"當學生查新字時，手機可以充當字典。"},{"en":"Because phones serve as many tools, controlling them affects many parts of a child’s life.","zh":"因為手機充當許多工具，控制手機會影響孩子生活的許多部分。"},{"en":"This phrase helps explain the role or function of something.","zh":"這個短語幫助解釋某物的角色或功能。"}],"source":"2016 Q4.pdf","sourcePage":1},{"front":"all at once","meaning":"同時","examples":[{"en":"Phones now serve many purposes all at once.","zh":"手機現在同時有許多用途。"},{"en":"All at once means at the same time or simultaneously.","zh":"all at once 的意思是在同一時間或同時發生。"},{"en":"A teenager may use a phone for study, music, photos, and messages all at once.","zh":"青少年可能同時用手機學習、聽音樂、拍照和傳訊息。"},{"en":"When one device does many things all at once, setting fair rules becomes harder.","zh":"當一部裝置同時做很多事，訂立公平規則就變得更困難。"},{"en":"This phrase shows that several actions or roles happen together.","zh":"這個短語顯示幾個行動或角色一起發生。"}],"source":"2016 Q4.pdf","sourcePage":1},{"front":"understandably anxious about","meaning":"對……感到焦慮是可以理解的","examples":[{"en":"Parents are understandably anxious about online risks.","zh":"父母對網上風險感到焦慮是可以理解的。"},{"en":"Understandably anxious about means worried for a reason that is easy to understand.","zh":"understandably anxious about 的意思是因容易理解的原因而感到擔心。"},{"en":"Parents are understandably anxious about cyberbullying because it can follow children home through their phones.","zh":"父母對網絡欺凌感到焦慮是可以理解的，因為它可以透過手機跟隨孩子回家。"},{"en":"This anxiety is reasonable, but it should not automatically lead to secret surveillance.","zh":"這種焦慮是合理的，但不應自動導致秘密監控。"},{"en":"The phrase shows sympathy while still allowing careful judgement.","zh":"這個短語表示同理，同時仍容許謹慎判斷。"}],"source":"2016 Q4.pdf","sourcePage":2},{"front":"gaming addiction","meaning":"遊戲成癮","examples":[{"en":"Parents worry about gaming addiction among teenagers.","zh":"父母擔心青少年遊戲成癮。"},{"en":"Gaming addiction is a harmful dependence on video games that interferes with sleep, study, health, or relationships.","zh":"gaming addiction 是對電子遊戲的有害依賴，並影響睡眠、學習、健康或關係。"},{"en":"A teenager may show signs of gaming addiction if he cannot stop playing even when exams are near.","zh":"如果青少年即使考試臨近仍無法停止打機，可能顯示遊戲成癮跡象。"},{"en":"Gaming addiction can make daily routines weaker because games replace rest and responsibilities.","zh":"遊戲成癮會令日常規律變弱，因為遊戲取代休息和責任。"},{"en":"This phrase describes a serious pattern, not ordinary enjoyment of games.","zh":"這個短語描述嚴重模式，而不是普通享受遊戲。"}],"source":"2016 Q4.pdf","sourcePage":2},{"front":"online scams","meaning":"網上騙案","examples":[{"en":"Parents are worried about online scams.","zh":"父母擔心網上騙案。"},{"en":"Online scams are dishonest tricks on the Internet that try to steal money, personal information, or trust.","zh":"online scams 是互聯網上的欺詐手法，試圖偷取金錢、個人資料或信任。"},{"en":"A teenager may face an online scam when a stranger asks for passwords or payment details.","zh":"當陌生人要求密碼或付款資料時，青少年可能遇到網上騙案。"},{"en":"Online scams can harm children because they may not recognise false messages quickly.","zh":"網上騙案可能傷害孩子，因為他們未必能快速識別虛假訊息。"},{"en":"This phrase explains one real danger behind parents’ concern.","zh":"這個短語解釋父母擔憂背後的一個真實危險。"}],"source":"2016 Q4.pdf","sourcePage":2},{"front":"cyberbullying","meaning":"網絡欺凌","examples":[{"en":"Cyberbullying is one reason parents worry about mobile phone use.","zh":"網絡欺凌是父母擔心手機使用的其中一個原因。"},{"en":"Cyberbullying means bullying through digital tools such as messages, posts, images, or group chats.","zh":"cyberbullying 是透過訊息、帖文、圖片或群組聊天等數碼工具進行欺凌。"},{"en":"A student may suffer cyberbullying if classmates spread cruel jokes about him online.","zh":"如果同學在網上散播關於某學生的殘酷笑話，他可能遭受網絡欺凌。"},{"en":"Cyberbullying can feel inescapable because the attacks may continue after school.","zh":"網絡欺凌會令人感到無法逃離，因為攻擊可能在放學後繼續。"},{"en":"This word describes online cruelty that can seriously harm mental health.","zh":"這個詞描述會嚴重傷害心理健康的網上殘酷行為。"}],"source":"2016 Q4.pdf","sourcePage":2},{"front":"Granted","meaning":"誠然","examples":[{"en":"Granted, parents have a duty to protect their children.","zh":"誠然，父母有責任保護子女。"},{"en":"Granted means it is accepted that part of the other side’s argument is true.","zh":"Granted 的意思是承認另一方論點有部分屬實。"},{"en":"Granted, phones can be dangerous, but secret monitoring is not always the right answer.","zh":"誠然，手機可能有危險，但秘密監控不一定是正確答案。"},{"en":"Writers use granted to sound fair before explaining their own view.","zh":"作者使用 granted 來顯得公平，然後解釋自己的看法。"},{"en":"This word helps an argument recognise complexity instead of ignoring opposing points.","zh":"這個詞幫助論點承認複雜性，而不是忽略相反觀點。"}],"source":"2016 Q4.pdf","sourcePage":2},{"front":"have a duty to","meaning":"有責任去","examples":[{"en":"Parents have a duty to protect their children.","zh":"父母有責任保護子女。"},{"en":"To have a duty to do something means to have a responsibility or moral obligation to do it.","zh":"have a duty to do something 的意思是有責任或道德義務去做某事。"},{"en":"Schools have a duty to protect students from bullying.","zh":"學校有責任保護學生免受欺凌。"},{"en":"Having a duty to protect does not mean adults may ignore a young person’s dignity.","zh":"有責任保護不代表成年人可以忽視年輕人的尊嚴。"},{"en":"This phrase is useful when discussing responsibility and care.","zh":"當討論責任和照顧時，這個短語很有用。"}],"source":"2016 Q4.pdf","sourcePage":2},{"front":"turn something into","meaning":"把……變成","examples":[{"en":"Parents should not turn monitoring apps into a normal parenting tool.","zh":"父母不應把監控應用程式變成常規育兒工具。"},{"en":"To turn something into something else means to change its role, use, or meaning.","zh":"turn something into something else 的意思是改變某物的角色、用途或意義。"},{"en":"Parents may turn a helpful safety tool into a source of fear if they use it secretly.","zh":"如果父母秘密使用，一個有用的安全工具可能被變成恐懼來源。"},{"en":"A rule can turn into control when it leaves no room for discussion.","zh":"當規則完全不留討論空間時，它可以變成控制。"},{"en":"This phrase shows how one thing can become another through use or habit.","zh":"這個短語展示某物如何透過使用或習慣變成另一樣東西。"}],"source":"2016 Q4.pdf","sourcePage":2},{"front":"monitoring apps","meaning":"監控應用程式","examples":[{"en":"Monitoring apps should not become a normal parenting tool.","zh":"監控應用程式不應成為常規育兒工具。"},{"en":"Monitoring apps are applications that track, record, or control a user’s phone activity.","zh":"monitoring apps 是追蹤、記錄或控制用戶手機活動的應用程式。"},{"en":"Some monitoring apps can show locations, screen time, browsing records, or messages.","zh":"有些監控應用程式可以顯示位置、屏幕時間、瀏覽紀錄或訊息。"},{"en":"Monitoring apps may help in serious cases, but constant use can damage trust.","zh":"監控應用程式在嚴重情況下可能有幫助，但持續使用會破壞信任。"},{"en":"This phrase refers to technology that must be used with clear limits.","zh":"這個短語指必須有清晰限制地使用的科技。"}],"source":"2016 Q4.pdf","sourcePage":2},{"front":"a normal parenting tool","meaning":"常規育兒工具","examples":[{"en":"I do not agree with turning monitoring apps into a normal parenting tool.","zh":"我不同意把監控應用程式變成常規育兒工具。"},{"en":"A normal parenting tool is a method parents regularly use to guide or manage children.","zh":"normal parenting tool 是父母經常用來引導或管理子女的方法。"},{"en":"Bedtime routines can be a normal parenting tool, but secret surveillance should not be one.","zh":"睡前規律可以是常規育兒工具，但秘密監控不應是。"},{"en":"If monitoring becomes a normal parenting tool, children may feel trusted only when watched.","zh":"如果監控成為常規育兒工具，孩子可能覺得只有在被監視時才被信任。"},{"en":"This phrase questions whether a method should become ordinary in family life.","zh":"這個短語質疑某方法是否應成為家庭生活中的平常做法。"}],"source":"2016 Q4.pdf","sourcePage":2},{"front":"As far as I am concerned","meaning":"就我而言","examples":[{"en":"As far as I am concerned, such surveillance damages trust.","zh":"就我而言，這種監控會破壞信任。"},{"en":"As far as I am concerned means in my opinion or from my point of view.","zh":"As far as I am concerned 的意思是在我看來或從我的角度而言。"},{"en":"As far as I am concerned, phone rules should be discussed openly with teenagers.","zh":"就我而言，手機規則應與青少年公開討論。"},{"en":"This phrase is useful when stating a clear position in a formal letter.","zh":"這個短語在正式信件中表達清晰立場時很有用。"},{"en":"It signals that the writer is giving a personal judgement.","zh":"它表示作者正在提出個人判斷。"}],"source":"2016 Q4.pdf","sourcePage":2},{"front":"such surveillance","meaning":"這種監控","examples":[{"en":"Such surveillance can damage trust between parents and children.","zh":"這種監控可以破壞父母與子女之間的信任。"},{"en":"Such surveillance means this kind of close watching, tracking, or checking.","zh":"such surveillance 的意思是這種密切觀看、追蹤或檢查。"},{"en":"Secretly reading messages is a form of such surveillance.","zh":"秘密閱讀訊息就是這種監控的一種形式。"},{"en":"Such surveillance may make children feel treated like suspects rather than family members.","zh":"這種監控可能令孩子覺得自己被視為嫌疑人，而不是家庭成員。"},{"en":"This phrase carries a serious tone because surveillance suggests control and suspicion.","zh":"這個短語語氣嚴肅，因為 surveillance 暗示控制和猜疑。"}],"source":"2016 Q4.pdf","sourcePage":3},{"front":"damage trust","meaning":"破壞信任","examples":[{"en":"Monitoring apps may damage trust in a family.","zh":"監控應用程式可能破壞家庭中的信任。"},{"en":"To damage trust means to weaken people’s belief that they can be honest and safe with one another.","zh":"damage trust 的意思是削弱人們相信彼此可以坦誠和安全相處的信念。"},{"en":"A parent may damage trust by secretly checking a teenager’s private messages.","zh":"父母秘密檢查青少年的私人訊息，可能破壞信任。"},{"en":"Once trust is damaged, children may hide problems instead of asking for help.","zh":"一旦信任被破壞，孩子可能隱藏問題，而不是尋求幫助。"},{"en":"This phrase shows how control can harm relationships.","zh":"這個短語展示控制如何傷害關係。"}],"source":"2016 Q4.pdf","sourcePage":3},{"front":"weaken self-discipline","meaning":"削弱自律","examples":[{"en":"Constant monitoring may weaken self-discipline.","zh":"持續監控可能削弱自律。"},{"en":"To weaken self-discipline means to reduce a person’s ability to control their own behaviour.","zh":"weaken self-discipline 的意思是減低一個人控制自己行為的能力。"},{"en":"If an app always blocks games, a child may not learn to stop by himself.","zh":"如果應用程式總是封鎖遊戲，孩子可能學不會自己停止。"},{"en":"Self-discipline weakens when people behave well only because someone is watching.","zh":"當人們只因有人監視才表現良好，自律就會被削弱。"},{"en":"This phrase explains why external control may not build inner responsibility.","zh":"這個短語解釋為何外在控制未必能建立內在責任感。"}],"source":"2016 Q4.pdf","sourcePage":3},{"front":"create risks","meaning":"製造風險","examples":[{"en":"Monitoring apps can create risks that are easily overlooked.","zh":"監控應用程式可以製造容易被忽略的風險。"},{"en":"To create risks means to produce new dangers or problems.","zh":"create risks 的意思是產生新的危險或問題。"},{"en":"A safety app may create risks if it collects sensitive information insecurely.","zh":"如果安全應用程式不安全地收集敏感資料，它可能製造風險。"},{"en":"Parents may create risks when they rely on technology instead of talking to their children.","zh":"當父母依賴科技而不是與子女交談時，可能製造風險。"},{"en":"This phrase reminds readers that a solution can also bring danger.","zh":"這個短語提醒讀者，解決方法也可以帶來危險。"}],"source":"2016 Q4.pdf","sourcePage":3},{"front":"easily overlooked","meaning":"容易被忽略","examples":[{"en":"Some risks of monitoring apps are easily overlooked.","zh":"監控應用程式的一些風險容易被忽略。"},{"en":"Easily overlooked means easy to miss, ignore, or fail to notice.","zh":"easily overlooked 的意思是容易錯過、忽視或沒有注意到。"},{"en":"Data privacy is easily overlooked when parents focus only on safety.","zh":"當父母只聚焦安全時，資料私隱容易被忽略。"},{"en":"Small changes in a child’s mood may be easily overlooked if parents only check dashboards.","zh":"如果父母只查看數據面板，孩子情緒上的細小變化可能容易被忽略。"},{"en":"This phrase warns readers to notice hidden or less obvious problems.","zh":"這個短語提醒讀者注意隱藏或較不明顯的問題。"}],"source":"2016 Q4.pdf","sourcePage":3},{"front":"first and foremost","meaning":"首先；最重要的是","examples":[{"en":"First and foremost, monitoring apps invade a young person’s privacy.","zh":"首先，監控應用程式侵犯年輕人的私隱。"},{"en":"First and foremost means most importantly and before anything else.","zh":"first and foremost 的意思是最重要的是，並且在其他事情之前。"},{"en":"First and foremost, parents should ask whether their rules protect trust.","zh":"首先，父母應問自己的規則是否保護信任。"},{"en":"Writers use this phrase to introduce their strongest or most important point.","zh":"作者使用這個短語來介紹最強或最重要的觀點。"},{"en":"It signals that the following idea is central to the argument.","zh":"它表示接下來的想法是論點的核心。"}],"source":"2016 Q4.pdf","sourcePage":3},{"front":"invade someone’s privacy","meaning":"侵犯某人的私隱","examples":[{"en":"Monitoring apps invade a young person’s privacy.","zh":"監控應用程式侵犯年輕人的私隱。"},{"en":"To invade someone’s privacy means to enter or examine their private life without proper respect or permission.","zh":"invade someone’s privacy 的意思是沒有適當尊重或同意下進入或檢查某人的私人生活。"},{"en":"Reading a teenager’s private chat without warning may invade their privacy.","zh":"未事先告知就閱讀青少年的私人聊天，可能侵犯其私隱。"},{"en":"Invading privacy can make children feel unsafe even inside their own family.","zh":"侵犯私隱可以令孩子即使在自己家庭中也感到不安全。"},{"en":"This phrase shows that protection can become harmful when boundaries are crossed.","zh":"這個短語顯示當界線被跨越時，保護可以變得有害。"}],"source":"2016 Q4.pdf","sourcePage":3},{"front":"a young person’s privacy","meaning":"年輕人的私隱","examples":[{"en":"A teenager’s phone contains a young person’s privacy.","zh":"青少年的手機包含年輕人的私隱。"},{"en":"A young person’s privacy is their right to keep personal thoughts, conversations, and information from unnecessary exposure.","zh":"a young person’s privacy 是年輕人把個人想法、對話和資料免受不必要暴露的權利。"},{"en":"A diary, private message, or search history may form part of a young person’s privacy.","zh":"日記、私人訊息或搜尋紀錄都可能是年輕人私隱的一部分。"},{"en":"Respecting a young person’s privacy helps them feel trusted as they grow older.","zh":"尊重年輕人的私隱，幫助他們在成長時感到被信任。"},{"en":"This phrase reminds adults that teenagers need boundaries as well as guidance.","zh":"這個短語提醒成年人，青少年需要界線，也需要引導。"}],"source":"2016 Q4.pdf","sourcePage":3},{"front":"in doing so","meaning":"這樣做的同時","examples":[{"en":"Monitoring apps invade privacy and, in doing so, poison trust.","zh":"監控應用程式侵犯私隱，這樣做的同時也破壞信任。"},{"en":"In doing so means by doing that action or as a result of that action.","zh":"in doing so 的意思是透過做該行動，或作為該行動的結果。"},{"en":"A parent may check every message and, in doing so, make the child afraid to speak honestly.","zh":"父母可能檢查每則訊息，這樣做的同時令孩子害怕坦誠說話。"},{"en":"This phrase links an action directly with its consequence.","zh":"這個短語把行動與其後果直接連繫起來。"},{"en":"It is useful when one behaviour creates an unintended problem.","zh":"當某行為造成意想不到的問題時，它很有用。"}],"source":"2016 Q4.pdf","sourcePage":3},{"front":"poison the trust between","meaning":"破壞……之間的信任","examples":[{"en":"Secret monitoring can poison the trust between parents and children.","zh":"秘密監控可以破壞父母與子女之間的信任。"},{"en":"To poison the trust between people means to slowly damage their relationship with suspicion, fear, or resentment.","zh":"poison the trust between people 的意思是透過猜疑、恐懼或怨恨慢慢破壞人際關係。"},{"en":"Secretly tracking a teenager may poison the trust between family members.","zh":"秘密追蹤青少年可能破壞家庭成員之間的信任。"},{"en":"Trust is poisoned when children feel their parents expect them to lie.","zh":"當孩子覺得父母預期自己會說謊時，信任就被破壞。"},{"en":"This phrase is strong because it suggests damage that spreads quietly.","zh":"這個短語語氣強烈，因為它暗示傷害會安靜地擴散。"}],"source":"2016 Q4.pdf","sourcePage":3},{"front":"not merely","meaning":"不只是","examples":[{"en":"A teenager’s phone is not merely a machine.","zh":"青少年的手機不只是一部機器。"},{"en":"Not merely means not only or not just.","zh":"not merely 的意思是不僅僅或不只是。"},{"en":"A phone is not merely a device; it can also be a diary, classroom, and social space.","zh":"手機不只是一部裝置；它也可以是日記、課室和社交空間。"},{"en":"This phrase helps writers show that something has deeper meaning than it first appears.","zh":"這個短語幫助作者展示某事物比表面看來有更深意義。"},{"en":"It is useful when expanding a simple idea into a more serious point.","zh":"當把簡單想法擴展成更嚴肅觀點時，它很有用。"}],"source":"2016 Q4.pdf","sourcePage":4},{"front":"private conversations","meaning":"私人對話","examples":[{"en":"A teenager’s phone may contain private conversations.","zh":"青少年的手機可能包含私人對話。"},{"en":"Private conversations are personal talks not meant for everyone to read or hear.","zh":"private conversations 是不打算讓所有人閱讀或聽到的個人談話。"},{"en":"Teenagers may have private conversations with friends about worries, friendships, or school pressure.","zh":"青少年可能與朋友進行關於憂慮、友誼或學校壓力的私人對話。"},{"en":"Reading private conversations without trust can make young people feel exposed.","zh":"在缺乏信任下閱讀私人對話，可以令年輕人感到被暴露。"},{"en":"This phrase shows why phones can be emotionally sensitive spaces.","zh":"這個短語展示為何手機可以是情感上敏感的空間。"}],"source":"2016 Q4.pdf","sourcePage":4},{"front":"awkward questions","meaning":"尷尬的問題","examples":[{"en":"A teenager’s phone may contain awkward questions.","zh":"青少年的手機可能包含尷尬的問題。"},{"en":"Awkward questions are questions that feel embarrassing, uncertain, or difficult to ask openly.","zh":"awkward questions 是令人尷尬、不確定或難以公開提出的問題。"},{"en":"A teenager may search awkward questions about friendship, health, or growing up.","zh":"青少年可能搜尋關於友情、健康或成長的尷尬問題。"},{"en":"If parents punish awkward questions, children may stop seeking safe information.","zh":"如果父母懲罰尷尬問題，孩子可能停止尋找安全資訊。"},{"en":"This phrase shows that privacy can help young people explore difficult topics.","zh":"這個短語顯示私隱可以幫助年輕人探索困難話題。"}],"source":"2016 Q4.pdf","sourcePage":4},{"front":"friendship problems","meaning":"友情問題","examples":[{"en":"A teenager’s phone may reveal friendship problems.","zh":"青少年的手機可能揭示友情問題。"},{"en":"Friendship problems are difficulties between friends, such as arguments, exclusion, jealousy, or broken trust.","zh":"friendship problems 是朋友之間的困難，例如爭吵、排斥、嫉妒或信任破裂。"},{"en":"A student may face friendship problems when a group chat leaves her out.","zh":"當群組聊天把學生排除在外時，她可能面對友情問題。"},{"en":"Friendship problems can feel serious to teenagers because friends are central to their daily lives.","zh":"友情問題對青少年來說可以很嚴重，因為朋友是他們日常生活的核心。"},{"en":"This phrase describes emotional struggles that adults may underestimate.","zh":"這個短語描述成年人可能低估的情感掙扎。"}],"source":"2016 Q4.pdf","sourcePage":4},{"front":"draft messages","meaning":"訊息草稿","examples":[{"en":"A teenager may keep draft messages on his or her phone.","zh":"青少年可能把訊息草稿保存在手機中。"},{"en":"Draft messages are messages written but not yet sent.","zh":"draft messages 是已寫好但尚未發送的訊息。"},{"en":"A teenager may write draft messages when trying to apologise but feeling too nervous to press send.","zh":"青少年想道歉但太緊張而不敢按發送時，可能會寫訊息草稿。"},{"en":"Draft messages can reveal private thoughts that were never meant to be read by others.","zh":"訊息草稿可以揭示從未打算讓別人閱讀的私人想法。"},{"en":"This phrase shows that even unsent words can be deeply personal.","zh":"這個短語顯示即使未發出的文字，也可以非常個人。"}],"source":"2016 Q4.pdf","sourcePage":4},{"front":"cries for help","meaning":"求助信號","examples":[{"en":"Some messages may be cries for help.","zh":"有些訊息可能是求助信號。"},{"en":"Cries for help are signs that someone is struggling and needs support.","zh":"cries for help 是某人正在掙扎並需要支援的跡象。"},{"en":"A teenager’s repeated messages about feeling alone may be cries for help.","zh":"青少年反覆發出關於感到孤單的訊息，可能是求助信號。"},{"en":"If parents only punish the messages, they may miss the pain behind them.","zh":"如果父母只懲罰這些訊息，可能會錯過背後的痛苦。"},{"en":"This phrase reminds adults to listen for hidden distress.","zh":"這個短語提醒成年人聆聽隱藏的困擾。"}],"source":"2016 Q4.pdf","sourcePage":4},{"front":"read, track or record","meaning":"閱讀、追蹤或記錄","examples":[{"en":"Some apps allow parents to read, track or record everything.","zh":"有些應用程式容許父母閱讀、追蹤或記錄一切。"},{"en":"Read, track or record means to view messages, follow activity, or save information about what someone does.","zh":"read, track or record 的意思是查看訊息、跟蹤活動或保存某人行為資料。"},{"en":"A monitoring app may read chats, track locations, or record browsing history.","zh":"監控應用程式可能閱讀聊天、追蹤位置或記錄瀏覽歷史。"},{"en":"These actions may feel protective to parents but invasive to children.","zh":"這些行動對父母來說可能像保護，但對孩子來說可能像侵犯。"},{"en":"This phrase lists different levels of digital monitoring.","zh":"這個短語列出不同程度的數碼監控。"}],"source":"2016 Q4.pdf","sourcePage":4},{"front":"no longer being guided","meaning":"不再是被引導","examples":[{"en":"The child is no longer being guided; he or she is being investigated.","zh":"孩子不再是被引導，而是被調查。"},{"en":"No longer being guided means support has changed into suspicion or control.","zh":"no longer being guided 的意思是支援已變成猜疑或控制。"},{"en":"A child is no longer being guided when every mistake becomes evidence against him.","zh":"當每個錯誤都變成指控孩子的證據時，孩子就不再是被引導。"},{"en":"Guidance helps children grow, but investigation can make them fearful and secretive.","zh":"引導幫助孩子成長，但調查會令他們害怕和變得秘密。"},{"en":"This phrase contrasts caring direction with distrustful checking.","zh":"這個短語把關懷的指引與不信任的檢查作對比。"}],"source":"2016 Q4.pdf","sourcePage":4},{"front":"be investigated","meaning":"被調查","examples":[{"en":"A child may feel that he or she is being investigated.","zh":"孩子可能覺得自己正在被調查。"},{"en":"To be investigated means to be examined closely as if suspected of doing something wrong.","zh":"be investigated 的意思是像被懷疑做錯事一樣被仔細檢查。"},{"en":"A teenager may feel investigated if parents secretly check every message and location.","zh":"如果父母秘密檢查每則訊息和位置，青少年可能覺得自己被調查。"},{"en":"Feeling investigated can make a child defensive rather than honest.","zh":"覺得被調查會令孩子變得防衛，而不是坦誠。"},{"en":"This phrase shows how monitoring can feel like accusation.","zh":"這個短語展示監控如何感覺像指控。"}],"source":"2016 Q4.pdf","sourcePage":4},{"front":"the result is not necessarily","meaning":"結果未必是","examples":[{"en":"The result is not necessarily honesty.","zh":"結果未必是誠實。"},{"en":"The result is not necessarily means the outcome may not be what people expect.","zh":"the result is not necessarily 的意思是結果未必如人們所預期。"},{"en":"If parents monitor everything, the result is not necessarily safety.","zh":"如果父母監控一切，結果未必是安全。"},{"en":"This phrase helps challenge a simple assumption about cause and effect.","zh":"這個短語幫助挑戰對因果關係的簡單假設。"},{"en":"It is useful when a method can produce unexpected results.","zh":"當某方法可能產生意外結果時，它很有用。"}],"source":"2016 Q4.pdf","sourcePage":4},{"front":"more often than not","meaning":"往往；多數情況下","examples":[{"en":"More often than not, constant monitoring leads to secrecy.","zh":"往往，持續監控會導致秘密行為。"},{"en":"More often than not means usually or in most cases.","zh":"more often than not 的意思是通常或多數情況下。"},{"en":"More often than not, children hide mistakes when they fear punishment more than they trust support.","zh":"多數情況下，當孩子害怕懲罰多於信任支援時，他們會隱藏錯誤。"},{"en":"This phrase is useful when describing a common pattern without saying it always happens.","zh":"這個短語在描述常見模式時很有用，但不表示總是如此。"},{"en":"It gives a general judgement while leaving room for exceptions.","zh":"它提出一般判斷，同時留有例外空間。"}],"source":"2016 Q4.pdf","sourcePage":5},{"front":"create another account","meaning":"開設另一個帳戶","examples":[{"en":"A teenager may simply create another account.","zh":"青少年可能只是開設另一個帳戶。"},{"en":"To create another account means to open a second online profile or login.","zh":"create another account 的意思是開設第二個網上個人檔案或登入帳戶。"},{"en":"If parents monitor one social media account, a teenager may create another account secretly.","zh":"如果父母監控一個社交媒體帳戶，青少年可能秘密開設另一個帳戶。"},{"en":"Creating another account can make monitoring less effective and communication less honest.","zh":"開設另一個帳戶會令監控較無效，也令溝通較不坦誠。"},{"en":"This phrase shows how control can lead to avoidance.","zh":"這個短語展示控制如何導致逃避。"}],"source":"2016 Q4.pdf","sourcePage":5},{"front":"borrow a friend’s phone","meaning":"借朋友的手機","examples":[{"en":"A teenager may borrow a friend’s phone to avoid being checked.","zh":"青少年可能借朋友的手機，以避免被檢查。"},{"en":"To borrow a friend’s phone means to use a friend’s device temporarily.","zh":"borrow a friend’s phone 的意思是暫時使用朋友的裝置。"},{"en":"A child who feels watched may borrow a friend’s phone to send private messages.","zh":"覺得被監視的孩子可能借朋友的手機發私人訊息。"},{"en":"Borrowing another phone can help a teenager avoid monitoring but increases secrecy.","zh":"借另一部手機可以幫助青少年避開監控，但會增加秘密行為。"},{"en":"This phrase shows that strict control may move the behaviour elsewhere.","zh":"這個短語展示嚴格控制可能把行為轉移到其他地方。"}],"source":"2016 Q4.pdf","sourcePage":5},{"front":"delete conversations","meaning":"刪除對話","examples":[{"en":"A teenager may delete conversations before going home.","zh":"青少年可能在回家前刪除對話。"},{"en":"To delete conversations means to remove chat histories or messages from a device.","zh":"delete conversations 的意思是從裝置中移除聊天紀錄或訊息。"},{"en":"A child may delete conversations if he fears parents will misunderstand his friends’ jokes.","zh":"如果孩子害怕父母誤解朋友的玩笑，他可能刪除對話。"},{"en":"Deleting conversations can hide both harmless privacy and serious problems.","zh":"刪除對話可以隱藏無害的私隱，也可以隱藏嚴重問題。"},{"en":"This phrase shows how fear can reduce openness.","zh":"這個短語展示恐懼如何減少坦誠。"}],"source":"2016 Q4.pdf","sourcePage":5},{"front":"worse still","meaning":"更糟的是","examples":[{"en":"Worse still, a student may hide serious problems.","zh":"更糟的是，學生可能隱藏嚴重問題。"},{"en":"Worse still means even worse or more seriously.","zh":"worse still 的意思是更糟或更嚴重的是。"},{"en":"Worse still, a child may stop asking for help because every conversation feels monitored.","zh":"更糟的是，孩子可能停止求助，因為每段對話都感覺被監控。"},{"en":"Writers use this phrase to introduce a more serious consequence.","zh":"作者使用這個短語來介紹更嚴重的後果。"},{"en":"It signals that the next point is especially worrying.","zh":"它表示下一個觀點尤其令人擔心。"}],"source":"2016 Q4.pdf","sourcePage":5},{"front":"struggle with","meaning":"受……困擾","examples":[{"en":"A student may be struggling with bullying or anxiety.","zh":"學生可能受欺凌或焦慮困擾。"},{"en":"To struggle with something means to have difficulty dealing with it.","zh":"struggle with something 的意思是難以處理某事。"},{"en":"A teenager may struggle with online pressure when classmates expect instant replies.","zh":"當同學期望立即回覆時，青少年可能受網上壓力困擾。"},{"en":"People who struggle with a problem often need support, not judgement.","zh":"受問題困擾的人通常需要支援，而不是批判。"},{"en":"This phrase describes an ongoing difficulty rather than one small mistake.","zh":"這個短語描述持續困難，而不是一個小錯誤。"}],"source":"2016 Q4.pdf","sourcePage":5},{"front":"bullying","meaning":"欺凌","examples":[{"en":"A student who is struggling with bullying may hide the problem.","zh":"受欺凌困擾的學生可能隱藏問題。"},{"en":"Bullying is repeated behaviour meant to hurt, frighten, exclude, or control another person.","zh":"bullying 是重複出現、意圖傷害、恐嚇、排斥或控制他人的行為。"},{"en":"Bullying may happen through insults, rumours, threats, or group exclusion.","zh":"欺凌可以透過侮辱、謠言、威脅或群體排斥發生。"},{"en":"A child may hide bullying if he fears parents will overreact or make things worse.","zh":"如果孩子害怕父母反應過激或令事情變差，他可能隱藏欺凌問題。"},{"en":"This word describes a serious harm that adults should handle carefully.","zh":"這個詞描述成年人應謹慎處理的嚴重傷害。"}],"source":"2016 Q4.pdf","sourcePage":5},{"front":"anxiety","meaning":"焦慮","examples":[{"en":"A student may hide his anxiety from his parents.","zh":"學生可能向父母隱藏自己的焦慮。"},{"en":"Anxiety is a strong feeling of worry, fear, or nervousness that may be hard to control.","zh":"anxiety 是強烈的憂慮、恐懼或緊張感，可能難以控制。"},{"en":"A teenager may feel anxiety before exams, interviews, or difficult conversations.","zh":"青少年在考試、面試或困難對話前可能感到焦慮。"},{"en":"Anxiety can become worse if a child feels watched but not understood.","zh":"如果孩子覺得被監視但不被理解，焦慮可能加重。"},{"en":"This word describes emotional pressure that may not be visible from outside.","zh":"這個詞描述從外表未必看得見的情緒壓力。"}],"source":"2016 Q4.pdf","sourcePage":5},{"front":"a broken friendship","meaning":"破裂的友情","examples":[{"en":"A teenager may be upset about a broken friendship.","zh":"青少年可能因破裂的友情而難過。"},{"en":"A broken friendship is a friendship that has been damaged or ended by conflict, betrayal, or distance.","zh":"broken friendship 是因衝突、背叛或疏離而受損或結束的友誼。"},{"en":"A teenager may cry over a broken friendship after being left out of a group chat.","zh":"青少年被排除在群組聊天外後，可能因破裂的友情而哭泣。"},{"en":"Broken friendships can affect study and sleep because teenagers value peer relationships deeply.","zh":"破裂的友情可以影響學習和睡眠，因為青少年十分重視朋輩關係。"},{"en":"This phrase describes emotional pain that adults should not dismiss as small.","zh":"這個短語描述成年人不應輕視的情感痛苦。"}],"source":"2016 Q4.pdf","sourcePage":5},{"front":"hide it for fear that","meaning":"因害怕……而隱瞞","examples":[{"en":"A student may hide the problem for fear that his parents will overreact.","zh":"學生可能因害怕父母反應過激而隱瞞問題。"},{"en":"Hide it for fear that means keep something secret because one is afraid of what may happen.","zh":"hide it for fear that 的意思是因害怕可能發生的事而把某事保密。"},{"en":"A teenager may hide a rude message for fear that parents will take away her phone.","zh":"青少年可能因害怕父母沒收手機而隱瞞一則粗魯訊息。"},{"en":"Fear can make children hide problems instead of seeking help early.","zh":"恐懼會令孩子隱藏問題，而不是及早求助。"},{"en":"This phrase shows how expected reactions shape honesty.","zh":"這個短語展示預期反應如何影響誠實。"}],"source":"2016 Q4.pdf","sourcePage":5},{"front":"overreact","meaning":"反應過激","examples":[{"en":"Some children fear that their parents will overreact.","zh":"有些孩子害怕父母會反應過激。"},{"en":"To overreact means to respond too strongly or emotionally to a situation.","zh":"overreact 的意思是對某情況作出過分強烈或情緒化的反應。"},{"en":"A parent may overreact by banning all phone use after one small mistake.","zh":"父母可能在一次小錯誤後禁止所有手機使用，這就是反應過激。"},{"en":"When children expect adults to overreact, they may stop sharing problems.","zh":"當孩子預期成年人會反應過激時，他們可能停止分享問題。"},{"en":"This word describes a response that is bigger than the situation requires.","zh":"這個詞描述比情況所需更大的反應。"}],"source":"2016 Q4.pdf","sourcePage":6},{"front":"What parents gain in…, they may lose in…","meaning":"父母在……方面得到的，可能會在……方面失去","examples":[{"en":"What parents gain in information, they may lose in openness.","zh":"父母在資訊方面得到的，可能會在坦誠溝通方面失去。"},{"en":"What parents gain in A, they may lose in B means getting one benefit may cost them another important thing.","zh":"What parents gain in A, they may lose in B 的意思是得到一種好處，可能要付出另一種重要東西。"},{"en":"What parents gain in control, they may lose in trust.","zh":"父母在控制方面得到的，可能會在信任方面失去。"},{"en":"This structure helps show a trade-off between two values.","zh":"這個結構幫助展示兩種價值之間的取捨。"},{"en":"It is useful when a solution brings hidden costs.","zh":"當解決方法帶來隱藏代價時，它很有用。"}],"source":"2016 Q4.pdf","sourcePage":6},{"front":"openness","meaning":"坦誠；開放溝通","examples":[{"en":"Parents may lose openness if they monitor too closely.","zh":"如果父母監控得太緊，他們可能失去坦誠溝通。"},{"en":"Openness means honest, free, and trusting communication.","zh":"openness 是誠實、自由和有信任的溝通。"},{"en":"A family has openness when children can admit mistakes without fear of immediate punishment.","zh":"當孩子可以承認錯誤而不怕立即被懲罰時，家庭就有坦誠溝通。"},{"en":"Openness can disappear when every conversation feels like evidence.","zh":"當每段對話都感覺像證據時，坦誠溝通可能消失。"},{"en":"This word describes the trust needed for real family communication.","zh":"這個詞描述真正家庭溝通所需要的信任。"}],"source":"2016 Q4.pdf","sourcePage":6},{"front":"responsible use","meaning":"負責任的使用方式","examples":[{"en":"Responsible use begins with trust.","zh":"負責任的使用方式由信任開始。"},{"en":"Responsible use means using something safely, sensibly, and with respect for others.","zh":"responsible use 是安全、理性並尊重他人地使用某物。"},{"en":"Responsible use of a phone includes checking facts, limiting screen time, and protecting privacy.","zh":"負責任地使用手機包括核實事實、限制屏幕時間和保護私隱。"},{"en":"Children learn responsible use better when rules are explained, not simply forced.","zh":"當規則被解釋，而不是單純被強迫執行時，孩子更能學會負責任使用。"},{"en":"This phrase focuses on judgement and habits.","zh":"這個短語聚焦判斷和習慣。"}],"source":"2016 Q4.pdf","sourcePage":6},{"front":"begin with trust","meaning":"由信任開始","examples":[{"en":"Responsible use begins with trust.","zh":"負責任的使用方式由信任開始。"},{"en":"Begin with trust means the first condition for success is a trusting relationship.","zh":"begin with trust 的意思是成功的第一個條件是有信任關係。"},{"en":"Phone rules begin with trust when parents discuss them honestly with children.","zh":"當父母與孩子坦誠討論手機規則時，這些規則就是由信任開始。"},{"en":"Without trust, even good rules may feel like punishment.","zh":"沒有信任，即使好規則也可能感覺像懲罰。"},{"en":"This phrase shows that relationships come before control.","zh":"這個短語顯示關係先於控制。"}],"source":"2016 Q4.pdf","sourcePage":6},{"front":"supervision becomes suspicion","meaning":"監督變成猜疑","examples":[{"en":"Without trust, supervision becomes suspicion.","zh":"沒有信任，監督就會變成猜疑。"},{"en":"Supervision becomes suspicion means guidance changes into distrustful watching.","zh":"supervision becomes suspicion 的意思是引導變成不信任的監視。"},{"en":"A parent’s checking becomes suspicion when every action is treated as possible wrongdoing.","zh":"當每個行動都被視為可能做錯事時，父母的檢查就變成猜疑。"},{"en":"Children may resist rules when supervision feels like suspicion.","zh":"當監督感覺像猜疑時，孩子可能抗拒規則。"},{"en":"This phrase warns that the tone of parenting matters.","zh":"這個短語提醒人們，育兒的語氣很重要。"}],"source":"2016 Q4.pdf","sourcePage":6},{"front":"constant monitoring","meaning":"持續監控","examples":[{"en":"Constant monitoring does not teach responsibility.","zh":"持續監控不能教導責任感。"},{"en":"Constant monitoring means watching or checking someone all the time.","zh":"constant monitoring 的意思是一直監視或檢查某人。"},{"en":"Constant monitoring may make a child behave well only while being observed.","zh":"持續監控可能令孩子只在被觀察時表現良好。"},{"en":"Too much monitoring can reduce privacy, honesty, and self-discipline.","zh":"過多監控可以減少私隱、誠實和自律。"},{"en":"This phrase describes a level of control that can become unhealthy.","zh":"這個短語描述一種可能變得不健康的控制程度。"}],"source":"2016 Q4.pdf","sourcePage":6},{"front":"teach responsibility","meaning":"教導責任感","examples":[{"en":"Constant monitoring does not teach responsibility.","zh":"持續監控不能教導責任感。"},{"en":"To teach responsibility means to help someone understand duties, consequences, and wise choices.","zh":"teach responsibility 的意思是幫助某人理解責任、後果和明智選擇。"},{"en":"Parents teach responsibility when they explain why sleep and study time matter.","zh":"當父母解釋睡眠和學習時間為何重要時，就是教導責任感。"},{"en":"Responsibility is learned through practice, mistakes, reflection, and trust.","zh":"責任感是透過練習、犯錯、反思和信任學會的。"},{"en":"This phrase focuses on education rather than simple control.","zh":"這個短語聚焦教育，而不是單純控制。"}],"source":"2016 Q4.pdf","sourcePage":6},{"front":"behave when they are being watched","meaning":"在被監視時表現得規矩","examples":[{"en":"Children may only learn how to behave when they are being watched.","zh":"孩子可能只學會在被監視時表現得規矩。"},{"en":"To behave when they are being watched means to act properly only while someone is observing them.","zh":"behave when they are being watched 的意思是只有在有人觀察時才行為恰當。"},{"en":"A child may stop using games when a parent is nearby but return to them later.","zh":"孩子可能在父母附近時停止打機，但之後又繼續。"},{"en":"If children only behave when watched, they have not yet developed self-control.","zh":"如果孩子只在被監視時表現規矩，他們尚未發展自制力。"},{"en":"This phrase shows the weakness of control without inner judgement.","zh":"這個短語展示沒有內在判斷的控制有何弱點。"}],"source":"2016 Q4.pdf","sourcePage":6},{"front":"the point is not whether…, but whether…","meaning":"重點不在於是否……，而在於是否……","examples":[{"en":"The point is not whether children should use phones freely, but whether they can make wise choices.","zh":"重點不在於孩子是否應自由使用手機，而在於他們是否能作出明智選擇。"},{"en":"The point is not whether A, but whether B means the real issue is B, not the simpler question A.","zh":"the point is not whether A, but whether B 的意思是真正議題是 B，而不是較簡單的 A 問題。"},{"en":"The point is not whether teenagers like social media, but whether they understand its risks.","zh":"重點不在於青少年是否喜歡社交媒體，而在於他們是否理解其風險。"},{"en":"This structure helps shift attention from a surface question to a deeper one.","zh":"這個結構幫助把注意力由表面問題轉向更深問題。"},{"en":"It is useful when correcting an oversimplified debate.","zh":"當修正過度簡化的辯論時，它很有用。"}],"source":"2016 Q4.pdf","sourcePage":6},{"front":"use phones freely","meaning":"自由使用手機","examples":[{"en":"The issue is not simply whether children should use phones freely.","zh":"問題不只是孩子是否應自由使用手機。"},{"en":"To use phones freely means to use phones without many limits or rules.","zh":"use phones freely 的意思是在沒有太多限制或規則下使用手機。"},{"en":"Teenagers may want to use phones freely, but freedom should come with responsibility.","zh":"青少年可能想自由使用手機，但自由應伴隨責任。"},{"en":"Using phones freely can be risky if children do not understand scams, privacy, or screen-time control.","zh":"如果孩子不了解騙案、私隱或屏幕時間控制，自由使用手機可能有風險。"},{"en":"This phrase describes freedom that needs guidance.","zh":"這個短語描述需要引導的自由。"}],"source":"2016 Q4.pdf","sourcePage":7},{"front":"make wise choices","meaning":"作出明智選擇","examples":[{"en":"Children need to learn to make wise choices.","zh":"孩子需要學會作出明智選擇。"},{"en":"To make wise choices means to decide carefully after thinking about consequences.","zh":"make wise choices 的意思是在思考後果後謹慎作決定。"},{"en":"A child makes a wise choice when she puts her phone away before sleep.","zh":"孩子睡前把手機收起來，就是作出明智選擇。"},{"en":"Wise choices grow from practice, explanation, and trust.","zh":"明智選擇來自練習、解釋和信任。"},{"en":"This phrase describes the goal of guidance, not just obedience.","zh":"這個短語描述引導的目標，而不只是服從。"}],"source":"2016 Q4.pdf","sourcePage":7},{"front":"when no one is standing behind them","meaning":"當沒有人在背後監督時","examples":[{"en":"Children must make good choices when no one is standing behind them.","zh":"孩子必須在沒有人在背後監督時作出好選擇。"},{"en":"When no one is standing behind them means when nobody is directly watching or controlling them.","zh":"when no one is standing behind them 的意思是沒有任何人直接監視或控制他們時。"},{"en":"A teenager shows self-discipline when he studies even when no one is standing behind him.","zh":"當青少年在沒有人背後監督時仍然溫習，他就是展現自律。"},{"en":"The real test of responsibility happens when children are not being monitored.","zh":"責任感的真正考驗，發生在孩子沒有被監控時。"},{"en":"This phrase highlights independence and inner judgement.","zh":"這個短語突顯獨立和內在判斷。"}],"source":"2016 Q4.pdf","sourcePage":7},{"front":"block games after thirty minutes","meaning":"三十分鐘後封鎖遊戲","examples":[{"en":"An app may block games after thirty minutes.","zh":"應用程式可能在三十分鐘後封鎖遊戲。"},{"en":"To block games after thirty minutes means to stop access to games once half an hour has passed.","zh":"block games after thirty minutes 的意思是半小時過後停止進入遊戲。"},{"en":"A parental-control app may block games after thirty minutes during exam season.","zh":"家長監控應用程式可能在考試期間三十分鐘後封鎖遊戲。"},{"en":"Blocking games can limit screen time, but it does not explain why limits matter.","zh":"封鎖遊戲可以限制屏幕時間，但不能解釋為何限制重要。"},{"en":"This phrase shows a technical limit, not a complete lesson in self-control.","zh":"這個短語展示技術限制，而不是完整的自制課程。"}],"source":"2016 Q4.pdf","sourcePage":7},{"front":"stop playing","meaning":"停止玩","examples":[{"en":"A child may stop playing when an app blocks games.","zh":"當應用程式封鎖遊戲時，孩子可能停止玩。"},{"en":"To stop playing means to end an activity, especially a game or entertainment.","zh":"stop playing 的意思是結束某項活動，尤其是遊戲或娛樂。"},{"en":"A teenager may stop playing after dinner so he can finish revision.","zh":"青少年可以晚飯後停止玩，以完成溫習。"},{"en":"Stopping because of an app is different from choosing to stop by oneself.","zh":"因應用程式而停止，與自己選擇停止不同。"},{"en":"This phrase can show either external control or personal discipline.","zh":"這個短語可以表示外在控制，也可以表示個人自律。"}],"source":"2016 Q4.pdf","sourcePage":7},{"front":"understand why","meaning":"明白為甚麼","examples":[{"en":"A child may not understand why sleep and revision matter.","zh":"孩子可能不明白為甚麼睡眠和溫習重要。"},{"en":"To understand why means to know the reason behind something.","zh":"understand why 的意思是知道某事背後的原因。"},{"en":"Children behave more responsibly when they understand why rules exist.","zh":"當孩子明白規則為何存在時，他們會更負責任地行事。"},{"en":"Without understanding why screen time matters, a child may only obey when forced.","zh":"如果不明白為甚麼屏幕時間重要，孩子可能只在被迫時服從。"},{"en":"This phrase shows the difference between knowing a rule and accepting its purpose.","zh":"這個短語展示知道規則與接受其目的之間的差別。"}],"source":"2016 Q4.pdf","sourcePage":7},{"front":"revision","meaning":"溫習","examples":[{"en":"Students need time for revision before exams.","zh":"學生考試前需要時間溫習。"},{"en":"Revision means reviewing and practising what has been learned before a test or exam.","zh":"revision 是在測驗或考試前重溫和練習已學內容。"},{"en":"A student may plan revision by dividing subjects into short study sessions.","zh":"學生可以把科目分成短時段來安排溫習。"},{"en":"Too much phone use can reduce revision time and increase exam stress.","zh":"過多使用手機可以減少溫習時間，並增加考試壓力。"},{"en":"This word describes preparation that strengthens memory and understanding.","zh":"這個詞描述加強記憶和理解的準備。"}],"source":"2016 Q4.pdf","sourcePage":7},{"front":"face-to-face conversation","meaning":"面對面交談","examples":[{"en":"Children should understand why face-to-face conversation matters.","zh":"孩子應明白為甚麼面對面交談重要。"},{"en":"Face-to-face conversation is direct talking between people who are physically present with one another.","zh":"face-to-face conversation 是人們在實際同場時直接交談。"},{"en":"A child may solve a misunderstanding better through face-to-face conversation than through angry texts.","zh":"孩子透過面對面交談解決誤會，可能比透過憤怒短訊更有效。"},{"en":"Face-to-face conversation helps people notice tone, expression, and feelings.","zh":"面對面交談幫助人們注意語氣、表情和感受。"},{"en":"This phrase describes communication that screens cannot fully replace.","zh":"這個短語描述螢幕不能完全取代的溝通。"}],"source":"2016 Q4.pdf","sourcePage":7},{"front":"matter","meaning":"重要","examples":[{"en":"Children should learn why sleep, revision and conversation matter.","zh":"孩子應學會為甚麼睡眠、溫習和交談重要。"},{"en":"To matter means to be important or have real effect.","zh":"matter 的意思是重要或有實際影響。"},{"en":"Sleep matters because tired students find it harder to think clearly.","zh":"睡眠重要，因為疲累學生較難清晰思考。"},{"en":"Revision matters because it helps students remember and use what they have learned.","zh":"溫習重要，因為它幫助學生記住並運用所學。"},{"en":"This word helps explain why a rule or habit deserves attention.","zh":"這個詞幫助解釋為何某規則或習慣值得注意。"}],"source":"2016 Q4.pdf","sourcePage":7},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"By contrast, discussion can help children understand the rules.","zh":"相比之下，討論可以幫助孩子理解規則。"},{"en":"By contrast means compared with the previous point, this next idea is different.","zh":"by contrast 的意思是與之前觀點相比，接下來的想法不同。"},{"en":"Monitoring may create fear; by contrast, conversation can build trust.","zh":"監控可能製造恐懼；相比之下，對話可以建立信任。"},{"en":"Writers use this phrase to show a clear difference between two approaches.","zh":"作者使用這個短語來顯示兩種方法之間的清楚差異。"},{"en":"It is useful when moving from criticism to a better alternative.","zh":"當由批評轉向更好替代方案時，它很有用。"}],"source":"2016 Q4.pdf","sourcePage":7},{"front":"sit down with","meaning":"坐下來與……","examples":[{"en":"Parents should sit down with their children to discuss phone use.","zh":"父母應坐下來與子女討論手機使用。"},{"en":"To sit down with someone means to spend time talking seriously and calmly with them.","zh":"sit down with someone 的意思是花時間與某人認真而冷靜地交談。"},{"en":"Parents can sit down with teenagers before setting screen-time rules.","zh":"父母可以在訂立屏幕使用時間規則前，坐下來與青少年討論。"},{"en":"Sitting down with children shows that their views matter.","zh":"坐下來與孩子交談，顯示他們的看法重要。"},{"en":"This phrase suggests patient conversation rather than quick orders.","zh":"這個短語暗示有耐性的對話，而不是快速命令。"}],"source":"2016 Q4.pdf","sourcePage":8},{"front":"set screen-time rules","meaning":"訂立屏幕使用時間規則","examples":[{"en":"Families can set screen-time rules together.","zh":"家庭可以一起訂立屏幕使用時間規則。"},{"en":"To set screen-time rules means to decide how long and when devices may be used.","zh":"set screen-time rules 的意思是決定電子裝置可以使用多久和何時使用。"},{"en":"A family may set screen-time rules such as no phones after 10 p.m.","zh":"家庭可以訂立屏幕使用時間規則，例如晚上十時後不使用手機。"},{"en":"Rules work better when children understand the reasons behind them.","zh":"當孩子明白規則背後的原因時，規則會更有效。"},{"en":"This phrase describes a practical way to manage digital habits.","zh":"這個短語描述管理數碼習慣的實際方法。"}],"source":"2016 Q4.pdf","sourcePage":8},{"front":"discuss online etiquette","meaning":"討論網上禮儀","examples":[{"en":"Parents should discuss online etiquette with their children.","zh":"父母應與子女討論網上禮儀。"},{"en":"Online etiquette means polite and responsible behaviour when communicating on the Internet.","zh":"online etiquette 是在互聯網溝通時禮貌而負責任的行為。"},{"en":"Parents can discuss online etiquette by talking about respectful replies and privacy.","zh":"父母可以透過討論尊重的回覆和私隱來談網上禮儀。"},{"en":"Understanding online etiquette helps children avoid cyberbullying and careless sharing.","zh":"理解網上禮儀幫助孩子避免網絡欺凌和粗心分享。"},{"en":"This phrase connects digital freedom with social responsibility.","zh":"這個短語把數碼自由與社會責任連繫起來。"}],"source":"2016 Q4.pdf","sourcePage":8},{"front":"review habits together","meaning":"一起檢視習慣","examples":[{"en":"Parents and children can review habits together.","zh":"父母和子女可以一起檢視習慣。"},{"en":"To review habits together means to look at regular behaviour as a family and decide what should improve.","zh":"review habits together 的意思是作為家庭一起查看日常行為，並決定甚麼需要改善。"},{"en":"Parents and children may review phone habits together every Sunday evening.","zh":"父母和子女可以每星期日晚一起檢視手機習慣。"},{"en":"Reviewing habits together feels less threatening than secret checking.","zh":"一起檢視習慣比秘密檢查感覺較少威脅。"},{"en":"This phrase shows cooperation and shared responsibility.","zh":"這個短語展示合作和共同責任。"}],"source":"2016 Q4.pdf","sourcePage":8},{"front":"the reasons behind the rules","meaning":"規則背後的原因","examples":[{"en":"Children should understand the reasons behind the rules.","zh":"孩子應明白規則背後的原因。"},{"en":"The reasons behind the rules are the purposes or explanations that make rules necessary.","zh":"the reasons behind the rules 是令規則有必要的目的或解釋。"},{"en":"The reason behind a bedtime phone rule may be protecting sleep and mental health.","zh":"睡前手機規則背後的原因可能是保護睡眠和心理健康。"},{"en":"Children accept rules more easily when the reasons behind them are clear.","zh":"當規則背後的原因清楚時，孩子會較容易接受規則。"},{"en":"This phrase shows that rules should teach, not merely control.","zh":"這個短語顯示規則應該教導，而不只是控制。"}],"source":"2016 Q4.pdf","sourcePage":8},{"front":"take…, for example","meaning":"以……為例","examples":[{"en":"Take a Secondary Four student preparing for exams, for example.","zh":"以一名正在準備考試的中四學生為例。"},{"en":"Take something for example is used to introduce a specific case that explains a wider point.","zh":"take something for example 用來介紹一個解釋較大觀點的具體例子。"},{"en":"Take a student revising late at night, for example: phone messages may disturb his focus.","zh":"以一名深夜溫習的學生為例：手機訊息可能打擾他的專注。"},{"en":"This phrase helps readers understand an argument through a concrete situation.","zh":"這個短語幫助讀者透過具體情況理解論點。"},{"en":"It is useful when moving from general claims to examples.","zh":"當由一般說法轉向例子時，它很有用。"}],"source":"2016 Q4.pdf","sourcePage":8},{"front":"prepare for exams","meaning":"準備考試","examples":[{"en":"A Secondary Four student may be preparing for exams.","zh":"中四學生可能正在準備考試。"},{"en":"To prepare for exams means to study, review, practise, and organise time before tests.","zh":"prepare for exams 的意思是在測驗前學習、重溫、練習和安排時間。"},{"en":"A student prepares for exams by making notes, doing past papers, and planning breaks.","zh":"學生透過整理筆記、做歷屆試題和安排小休來準備考試。"},{"en":"Phone distractions can make preparing for exams harder.","zh":"手機分心可以令準備考試更困難。"},{"en":"This phrase describes focused work before an important assessment.","zh":"這個短語描述重要評估前的專注工作。"}],"source":"2016 Q4.pdf","sourcePage":8},{"front":"not simply…, but…","meaning":"不只是……，而是……","examples":[{"en":"What he needs is not simply an app, but the ability to manage himself.","zh":"他需要的不只是一個應用程式，而是管理自己的能力。"},{"en":"Not simply A, but B means B is the deeper or more important need than A alone.","zh":"not simply A, but B 的意思是 B 比單單 A 更深層或更重要。"},{"en":"A teenager needs not simply blocked websites, but guidance on using time wisely.","zh":"青少年需要的不只是被封鎖網站，而是如何明智使用時間的引導。"},{"en":"This structure helps show that a surface solution is not enough.","zh":"這個結構幫助顯示表面解決方法不足夠。"},{"en":"It is useful when arguing for a deeper kind of support.","zh":"當論證需要更深層支援時，它很有用。"}],"source":"2016 Q4.pdf","sourcePage":8},{"front":"shut down Instagram","meaning":"關閉 Instagram","examples":[{"en":"An app may shut down Instagram during revision time.","zh":"應用程式可能在溫習時間關閉 Instagram。"},{"en":"To shut down Instagram means to block or close access to the Instagram app.","zh":"shut down Instagram 的意思是封鎖或關閉 Instagram 應用程式的使用。"},{"en":"A student may use a timer to shut down Instagram while studying.","zh":"學生可以使用計時器，在學習時關閉 Instagram。"},{"en":"Shutting down Instagram can reduce distraction, but it does not teach why focus matters.","zh":"關閉 Instagram 可以減少分心，但不能教導為何專注重要。"},{"en":"This phrase describes a direct technical control over app use.","zh":"這個短語描述對應用程式使用的直接技術控制。"}],"source":"2016 Q4.pdf","sourcePage":8},{"front":"the ability to","meaning":"……的能力","examples":[{"en":"A student needs the ability to manage notifications and revision breaks.","zh":"學生需要管理通知和溫習小休的能力。"},{"en":"The ability to do something means the skill or capacity to do it.","zh":"the ability to do something 的意思是做某事的技能或能力。"},{"en":"Children need the ability to judge when online replies can wait.","zh":"孩子需要判斷網上回覆何時可以等待的能力。"},{"en":"The ability to manage phone use grows through practice and explanation.","zh":"管理手機使用的能力透過練習和解釋而成長。"},{"en":"This phrase focuses on developing inner skills.","zh":"這個短語聚焦發展內在技能。"}],"source":"2016 Q4.pdf","sourcePage":8},{"front":"mute notifications","meaning":"將通知靜音","examples":[{"en":"Students need to learn how to mute notifications.","zh":"學生需要學會如何將通知靜音。"},{"en":"To mute notifications means to silence alerts from apps, messages, or group chats.","zh":"mute notifications 的意思是把應用程式、訊息或群組聊天的提示聲靜音。"},{"en":"A student may mute notifications during revision so messages do not interrupt concentration.","zh":"學生可以在溫習時將通知靜音，避免訊息打斷專注。"},{"en":"Muting notifications teaches children to control digital distractions themselves.","zh":"將通知靜音教孩子自行控制數碼干擾。"},{"en":"This phrase describes a practical self-management skill.","zh":"這個短語描述實用的自我管理技能。"}],"source":"2016 Q4.pdf","sourcePage":9},{"front":"plan revision breaks","meaning":"安排溫習小休","examples":[{"en":"A student should learn to plan revision breaks.","zh":"學生應學會安排溫習小休。"},{"en":"To plan revision breaks means to decide when to rest during study time.","zh":"plan revision breaks 的意思是在學習時間中決定何時休息。"},{"en":"A student may plan revision breaks after every forty minutes of focused work.","zh":"學生可以在每四十分鐘專注學習後安排溫習小休。"},{"en":"Planned breaks can prevent tiredness and reduce the urge to scroll endlessly.","zh":"有計劃的小休可以防止疲累，並減少無止境滑手機的衝動。"},{"en":"This phrase shows that healthy study includes both work and rest.","zh":"這個短語顯示健康學習包括工作和休息。"}],"source":"2016 Q4.pdf","sourcePage":9},{"front":"resist the pressure to","meaning":"抵抗……的壓力","examples":[{"en":"Students need to resist the pressure to reply instantly.","zh":"學生需要抵抗立即回覆的壓力。"},{"en":"To resist the pressure to do something means to refuse a strong feeling or expectation pushing you to do it.","zh":"resist the pressure to do something 的意思是拒絕推動你做某事的強烈感受或期望。"},{"en":"A teenager may resist the pressure to check every message during dinner.","zh":"青少年可以抵抗晚飯時查看每則訊息的壓力。"},{"en":"Resisting pressure becomes easier when family and friends respect boundaries.","zh":"當家庭和朋友尊重界線時，抵抗壓力會較容易。"},{"en":"This phrase describes self-control under social influence.","zh":"這個短語描述在社交影響下的自制力。"}],"source":"2016 Q4.pdf","sourcePage":9},{"front":"reply instantly to","meaning":"立即回覆","examples":[{"en":"Teenagers often feel pressure to reply instantly to group chats.","zh":"青少年常感到要立即回覆群組聊天的壓力。"},{"en":"To reply instantly to something means to answer it immediately.","zh":"reply instantly to something 的意思是立刻回答某事。"},{"en":"A student may feel she must reply instantly to friends even during revision.","zh":"學生即使在溫習時，也可能覺得自己必須立即回覆朋友。"},{"en":"The pressure to reply instantly can disturb sleep and concentration.","zh":"立即回覆的壓力可以打擾睡眠和專注。"},{"en":"This phrase shows how online communication can create urgency.","zh":"這個短語展示網上溝通如何製造迫切感。"}],"source":"2016 Q4.pdf","sourcePage":9},{"front":"group chat","meaning":"群組聊天","examples":[{"en":"A student may feel pressure to reply to every group chat.","zh":"學生可能感到要回覆每個群組聊天的壓力。"},{"en":"A group chat is an online conversation involving several people in the same message thread.","zh":"group chat 是幾個人在同一訊息串中的網上對話。"},{"en":"Classmates may use a group chat to discuss homework, jokes, or weekend plans.","zh":"同學可以使用群組聊天討論功課、笑話或週末計劃。"},{"en":"Group chats can support friendship, but they can also create pressure to be constantly available.","zh":"群組聊天可以支援友誼，但也可以製造需要隨時在線的壓力。"},{"en":"This phrase describes a common social space for teenagers.","zh":"這個短語描述青少年常見的社交空間。"}],"source":"2016 Q4.pdf","sourcePage":9},{"front":"only by giving… can…","meaning":"只有透過給予……才可以……","examples":[{"en":"Only by giving young people room to practise judgment can parents help them grow.","zh":"父母只有透過給予年輕人練習判斷的空間，才可以幫助他們成長。"},{"en":"Only by giving A can B means B is possible only if A is provided.","zh":"only by giving A can B 的意思是只有提供 A，B 才可能發生。"},{"en":"Only by giving children chances to make choices can parents teach responsibility.","zh":"父母只有給孩子作選擇的機會，才可以教導責任感。"},{"en":"This structure emphasises a necessary condition for success.","zh":"這個結構強調成功所需的必要條件。"},{"en":"It is useful when arguing that control alone cannot produce growth.","zh":"當論證單靠控制不能帶來成長時，它很有用。"}],"source":"2016 Q4.pdf","sourcePage":9},{"front":"room to practise judgment","meaning":"練習判斷的空間","examples":[{"en":"Young people need room to practise judgment.","zh":"年輕人需要練習判斷的空間。"},{"en":"Room to practise judgment means space and opportunity to make decisions and learn from them.","zh":"room to practise judgment 的意思是有空間和機會作決定並從中學習。"},{"en":"A teenager practises judgment when he decides to mute notifications during study time.","zh":"青少年在學習時決定將通知靜音，就是練習判斷。"},{"en":"Without room to practise judgment, children may obey rules but fail to develop wisdom.","zh":"沒有練習判斷的空間，孩子可能服從規則，卻未能發展智慧。"},{"en":"This phrase shows that responsibility grows through experience.","zh":"這個短語顯示責任感透過經驗成長。"}],"source":"2016 Q4.pdf","sourcePage":9},{"front":"disciplined users","meaning":"自律的使用者","examples":[{"en":"Parents should help children become disciplined users.","zh":"父母應幫助孩子成為自律的使用者。"},{"en":"Disciplined users are people who can control their own use of technology wisely.","zh":"disciplined users 是能明智地控制自己科技使用的人。"},{"en":"A disciplined user can stop scrolling when it is time to sleep or study.","zh":"自律的使用者在睡覺或學習時間到來時，可以停止滑手機。"},{"en":"Children become disciplined users through trust, practice, and clear boundaries.","zh":"孩子透過信任、練習和清晰界線成為自律的使用者。"},{"en":"This phrase describes self-control rather than fear of punishment.","zh":"這個短語描述自制，而不是害怕懲罰。"}],"source":"2016 Q4.pdf","sourcePage":9},{"front":"rather than obedient ones","meaning":"而不是只懂服從的人","examples":[{"en":"Children should become disciplined users rather than obedient ones.","zh":"孩子應成為自律的使用者，而不是只懂服從的人。"},{"en":"Rather than obedient ones means instead of people who only follow orders without understanding.","zh":"rather than obedient ones 的意思是不要成為只聽命令而不理解的人。"},{"en":"Parents should raise thoughtful phone users rather than obedient ones who behave only when watched.","zh":"父母應培養有思考的手機使用者，而不是只在被監視時守規矩的人。"},{"en":"Obedience may control behaviour, but discipline builds judgement.","zh":"服從可以控制行為，但自律建立判斷。"},{"en":"This phrase contrasts inner responsibility with simple compliance.","zh":"這個短語把內在責任與單純服從作對比。"}],"source":"2016 Q4.pdf","sourcePage":9},{"front":"create new dangers","meaning":"製造新的危險","examples":[{"en":"Monitoring apps can create new dangers.","zh":"監控應用程式可以製造新的危險。"},{"en":"To create new dangers means to produce risks that did not exist before.","zh":"create new dangers 的意思是產生以前不存在的風險。"},{"en":"A tracking app may create new dangers if a child’s location data is leaked.","zh":"如果孩子的位置資料外洩，追蹤應用程式可能製造新的危險。"},{"en":"New dangers can appear when parents trust technology without checking its privacy risks.","zh":"當父母信任科技卻不檢查其私隱風險時，新的危險可能出現。"},{"en":"This phrase warns that safety tools can also be unsafe.","zh":"這個短語提醒人們，安全工具也可能不安全。"}],"source":"2016 Q4.pdf","sourcePage":9},{"front":"a false sense of security","meaning":"虛假的安全感","examples":[{"en":"Monitoring apps may give parents a false sense of security.","zh":"監控應用程式可能給父母虛假的安全感。"},{"en":"A false sense of security is the mistaken feeling that something is safe when it is not fully safe.","zh":"false sense of security 是錯誤地覺得某事安全，但它並非完全安全。"},{"en":"A parent may feel safe because an app shows the child’s location, but the child may still feel lonely.","zh":"父母可能因應用程式顯示孩子位置而覺得安全，但孩子仍可能感到孤單。"},{"en":"A false sense of security can make adults stop asking deeper questions.","zh":"虛假的安全感可以令成年人停止提出更深問題。"},{"en":"This phrase shows that information is not the same as real protection.","zh":"這個短語顯示資訊不等同真正保護。"}],"source":"2016 Q4.pdf","sourcePage":10},{"front":"collect sensitive information","meaning":"收集敏感資料","examples":[{"en":"Many apps collect sensitive information.","zh":"許多應用程式收集敏感資料。"},{"en":"To collect sensitive information means to gather private data that could harm someone if exposed.","zh":"collect sensitive information 的意思是收集一旦外露可能傷害某人的私人資料。"},{"en":"Monitoring apps may collect sensitive information such as location, contacts, and browsing records.","zh":"監控應用程式可能收集位置、聯絡人和瀏覽紀錄等敏感資料。"},{"en":"Collecting sensitive information creates responsibility because the data must be protected.","zh":"收集敏感資料會帶來責任，因為資料必須受到保護。"},{"en":"This phrase explains a privacy risk behind digital tools.","zh":"這個短語解釋數碼工具背後的私隱風險。"}],"source":"2016 Q4.pdf","sourcePage":10},{"front":"sensitive information","meaning":"敏感資料","examples":[{"en":"Locations and browsing records are sensitive information.","zh":"位置和瀏覽紀錄都是敏感資料。"},{"en":"Sensitive information is private data that should be handled carefully because misuse could cause harm.","zh":"sensitive information 是應謹慎處理的私人資料，因為濫用可能造成傷害。"},{"en":"A child’s location, contacts, passwords, and search history can be sensitive information.","zh":"孩子的位置、聯絡人、密碼和搜尋紀錄都可以是敏感資料。"},{"en":"Sensitive information should not be collected unless there is a clear and limited reason.","zh":"除非有清楚而有限度的理由，否則不應收集敏感資料。"},{"en":"This phrase highlights the need for privacy and security.","zh":"這個短語強調私隱和安全的需要。"}],"source":"2016 Q4.pdf","sourcePage":10},{"front":"browsing records","meaning":"瀏覽紀錄","examples":[{"en":"Monitoring apps may collect browsing records.","zh":"監控應用程式可能收集瀏覽紀錄。"},{"en":"Browsing records are histories of websites, pages, or online content someone has visited.","zh":"browsing records 是某人曾瀏覽的網站、頁面或網上內容紀錄。"},{"en":"Browsing records may reveal a teenager’s worries, interests, or private questions.","zh":"瀏覽紀錄可能揭示青少年的憂慮、興趣或私人問題。"},{"en":"If browsing records are leaked, a child’s privacy may be seriously harmed.","zh":"如果瀏覽紀錄外洩，孩子的私隱可能受到嚴重傷害。"},{"en":"This phrase shows why online activity can be personal data.","zh":"這個短語展示為何網上活動可以是個人資料。"}],"source":"2016 Q4.pdf","sourcePage":10},{"front":"contact lists","meaning":"聯絡人名單","examples":[{"en":"Some apps collect children’s contact lists.","zh":"有些應用程式收集孩子的聯絡人名單。"},{"en":"Contact lists are collections of names, phone numbers, emails, or accounts saved on a device.","zh":"contact lists 是儲存在裝置中的姓名、電話號碼、電郵或帳戶集合。"},{"en":"A child’s contact list may include classmates, relatives, teachers, and private friends.","zh":"孩子的聯絡人名單可能包括同學、親戚、老師和私人朋友。"},{"en":"If contact lists are misused, strangers may reach people connected to the child.","zh":"如果聯絡人名單被濫用，陌生人可能接觸到與孩子有關的人。"},{"en":"This phrase describes data that can affect more people than just the phone owner.","zh":"這個短語描述會影響不只手機擁有者的資料。"}],"source":"2016 Q4.pdf","sourcePage":10},{"front":"data is leaked","meaning":"資料外洩","examples":[{"en":"If the data is leaked, the child may be placed in danger.","zh":"如果資料外洩，孩子可能陷入危險。"},{"en":"Data is leaked means private information is exposed or shared without permission.","zh":"data is leaked 的意思是私人資料在未經同意下被外露或分享。"},{"en":"If a child’s location data is leaked, strangers may learn where the child goes.","zh":"如果孩子的位置資料外洩，陌生人可能知道孩子去哪裏。"},{"en":"Data leaks can turn a safety tool into a real threat.","zh":"資料外洩可以把安全工具變成真正威脅。"},{"en":"This phrase describes a serious privacy failure.","zh":"這個短語描述嚴重的私隱失誤。"}],"source":"2016 Q4.pdf","sourcePage":10},{"front":"be misused","meaning":"被濫用","examples":[{"en":"Sensitive information may be misused.","zh":"敏感資料可能被濫用。"},{"en":"To be misused means to be used in a wrong, harmful, or dishonest way.","zh":"be misused 的意思是被以錯誤、有害或不誠實的方式使用。"},{"en":"A child’s browsing records may be misused if someone sells or shares them.","zh":"如果有人出售或分享孩子的瀏覽紀錄，這些資料可能被濫用。"},{"en":"Information collected for safety can be misused if there are weak protections.","zh":"為安全而收集的資訊，如果保護薄弱，也可能被濫用。"},{"en":"This phrase warns that data can harm people after collection.","zh":"這個短語提醒人們，資料在收集後仍可能傷害人。"}],"source":"2016 Q4.pdf","sourcePage":10},{"front":"accessed by the wrong person","meaning":"被不當人士取得","examples":[{"en":"Private data may be accessed by the wrong person.","zh":"私人資料可能被不當人士取得。"},{"en":"Accessed by the wrong person means seen or used by someone who should not have it.","zh":"accessed by the wrong person 的意思是被不應擁有該資料的人看到或使用。"},{"en":"A stranger accessing a child’s location history would be a serious danger.","zh":"陌生人取得孩子的位置歷史會是嚴重危險。"},{"en":"Data can be accessed by the wrong person if an app has weak security.","zh":"如果應用程式保安薄弱，資料可能被不當人士取得。"},{"en":"This phrase shows why privacy protection must be taken seriously.","zh":"這個短語顯示為何私隱保護必須被認真看待。"}],"source":"2016 Q4.pdf","sourcePage":10},{"front":"be placed in greater danger","meaning":"陷入更大危險","examples":[{"en":"A child may be placed in greater danger if data is leaked.","zh":"如果資料外洩，孩子可能陷入更大危險。"},{"en":"To be placed in greater danger means to become less safe than before.","zh":"be placed in greater danger 的意思是變得比以前更不安全。"},{"en":"A child may be placed in greater danger if a stranger learns his home and school locations.","zh":"如果陌生人知道孩子的住所和學校位置，孩子可能陷入更大危險。"},{"en":"Tools meant to protect children can place them in greater danger when data security fails.","zh":"當資料保安失效時，本來用來保護孩子的工具可能令他們陷入更大危險。"},{"en":"This phrase highlights unintended harm.","zh":"這個短語突顯意想不到的傷害。"}],"source":"2016 Q4.pdf","sourcePage":10},{"front":"not less","meaning":"而不是更少","examples":[{"en":"The child may be placed in greater danger, not less.","zh":"孩子可能陷入更大危險，而不是更少危險。"},{"en":"Not less means the opposite of a reduction; the danger or problem may actually increase.","zh":"not less 的意思不是減少；危險或問題其實可能增加。"},{"en":"If private data leaks, monitoring may make the child less safe, not less exposed.","zh":"如果私人資料外洩，監控可能令孩子更不安全，而不是較少暴露。"},{"en":"This phrase corrects an expectation by showing the result may be worse.","zh":"這個短語透過顯示結果可能更差來修正預期。"},{"en":"It is useful when a supposed solution increases the problem.","zh":"當所謂解決方法令問題增加時，它很有用。"}],"source":"2016 Q4.pdf","sourcePage":10},{"front":"work only up to a point","meaning":"只在某程度上有效","examples":[{"en":"Technology works only up to a point.","zh":"科技只在某程度上有效。"},{"en":"Work only up to a point means be useful only within limits.","zh":"work only up to a point 的意思是只在有限範圍內有用。"},{"en":"A monitoring app works only up to a point because it can track location but not feelings.","zh":"監控應用程式只在某程度上有效，因為它可以追蹤位置，但不能追蹤感受。"},{"en":"Technology may help parents notice risks, but it cannot replace conversation.","zh":"科技可以幫助父母注意風險，但不能取代對話。"},{"en":"This phrase reminds readers that tools have limits.","zh":"這個短語提醒讀者，工具有其限制。"}],"source":"2016 Q4.pdf","sourcePage":11},{"front":"show that","meaning":"顯示","examples":[{"en":"An app may show that a child is at school.","zh":"應用程式可能顯示孩子在學校。"},{"en":"Show that means provide information or evidence about something.","zh":"show that 的意思是提供關於某事的資料或證據。"},{"en":"A location app may show that a teenager has reached the library.","zh":"位置應用程式可能顯示青少年已到達圖書館。"},{"en":"What an app shows may be true but still incomplete.","zh":"應用程式顯示的內容可能真實，但仍不完整。"},{"en":"This phrase helps explain what information a tool can provide.","zh":"這個短語幫助解釋工具可以提供甚麼資料。"}],"source":"2016 Q4.pdf","sourcePage":11},{"front":"cannot tell whether","meaning":"無法判斷是否","examples":[{"en":"An app cannot tell whether a child feels lonely.","zh":"應用程式無法判斷孩子是否感到孤單。"},{"en":"Cannot tell whether means cannot know or judge if something is true.","zh":"cannot tell whether 的意思是無法知道或判斷某事是否真實。"},{"en":"A screen-time report cannot tell whether a child is using the phone for homework or escape.","zh":"屏幕時間報告無法判斷孩子是在用手機做功課，還是在逃避。"},{"en":"Technology cannot always tell whether a teenager needs help.","zh":"科技不一定能判斷青少年是否需要幫助。"},{"en":"This phrase shows the limits of data.","zh":"這個短語展示數據的限制。"}],"source":"2016 Q4.pdf","sourcePage":11},{"front":"feel lonely","meaning":"感到孤單","examples":[{"en":"A child may feel lonely even when he is at school.","zh":"孩子即使在學校也可能感到孤單。"},{"en":"To feel lonely means to feel emotionally alone or disconnected from others.","zh":"feel lonely 的意思是在情感上感到孤獨或與他人脫節。"},{"en":"A student may feel lonely if classmates talk in group chats but exclude him.","zh":"如果同學在群組聊天中說話卻排除他，學生可能感到孤單。"},{"en":"Loneliness can exist even in crowded places or busy classrooms.","zh":"孤單即使在擠迫地方或繁忙課室中也可以存在。"},{"en":"This phrase describes an inner feeling that cannot always be seen from outside.","zh":"這個短語描述外表未必看得見的內在感受。"}],"source":"2016 Q4.pdf","sourcePage":11},{"front":"record screen time","meaning":"記錄屏幕使用時間","examples":[{"en":"An app may record screen time.","zh":"應用程式可能記錄屏幕使用時間。"},{"en":"To record screen time means to measure and save how long someone uses a device or app.","zh":"record screen time 的意思是量度並保存某人使用裝置或應用程式的時間。"},{"en":"A phone may record screen time to show that a teenager used social media for two hours.","zh":"手機可能記錄屏幕使用時間，顯示青少年用了兩小時社交媒體。"},{"en":"Screen-time records can start a useful conversation, but they do not explain every reason behind use.","zh":"屏幕時間紀錄可以展開有用對話，但不能解釋使用背後的所有原因。"},{"en":"This phrase describes data collection about device habits.","zh":"這個短語描述關於裝置習慣的數據收集。"}],"source":"2016 Q4.pdf","sourcePage":11},{"front":"detect whether","meaning":"偵測是否","examples":[{"en":"An app cannot detect whether a joke has become humiliation.","zh":"應用程式無法偵測一個玩笑是否已變成羞辱。"},{"en":"To detect whether means to discover or identify if something is happening.","zh":"detect whether 的意思是發現或識別某事是否正在發生。"},{"en":"A programme may detect whether a website is blocked, but not whether a child feels hurt.","zh":"程式可以偵測網站是否被封鎖，但未必能偵測孩子是否受傷。"},{"en":"Technology cannot always detect whether online teasing has crossed a line.","zh":"科技不一定能偵測網上取笑是否已越界。"},{"en":"This phrase shows the difference between technical detection and human understanding.","zh":"這個短語展示技術偵測與人的理解之間的差別。"}],"source":"2016 Q4.pdf","sourcePage":11},{"front":"become humiliation","meaning":"變成羞辱","examples":[{"en":"A joke in a group chat may become humiliation.","zh":"群組聊天中的玩笑可能變成羞辱。"},{"en":"To become humiliation means to change from something light or funny into something that deeply embarrasses someone.","zh":"become humiliation 的意思是由輕鬆或有趣的事變成令某人深感難堪的事。"},{"en":"A joke becomes humiliation when classmates keep sharing it after the person asks them to stop.","zh":"當同學在當事人要求停止後仍繼續分享笑話，玩笑就變成羞辱。"},{"en":"Humiliation can hurt more when it happens publicly online.","zh":"當羞辱在網上公開發生時，傷害可能更大。"},{"en":"This phrase shows how humour can turn harmful.","zh":"這個短語展示幽默如何變得有害。"}],"source":"2016 Q4.pdf","sourcePage":11},{"front":"block one website","meaning":"封鎖一個網站","examples":[{"en":"An app may block one website.","zh":"應用程式可能封鎖一個網站。"},{"en":"To block one website means to prevent access to a particular online site.","zh":"block one website 的意思是阻止進入某個特定網站。"},{"en":"Parents may block one website that contains unsafe content.","zh":"父母可以封鎖一個含有不安全內容的網站。"},{"en":"Blocking one website may not solve the problem if the child simply finds another site.","zh":"如果孩子只是找到另一個網站，封鎖一個網站未必能解決問題。"},{"en":"This phrase describes a limited technical action.","zh":"這個短語描述有限的技術行動。"}],"source":"2016 Q4.pdf","sourcePage":11},{"front":"move elsewhere","meaning":"轉移到其他地方","examples":[{"en":"The problem may simply move elsewhere.","zh":"問題可能只是轉移到其他地方。"},{"en":"Move elsewhere means shift to another place, platform, or form.","zh":"move elsewhere 的意思是轉到另一個地方、平台或形式。"},{"en":"If one app is blocked, a teenager’s risky behaviour may move elsewhere online.","zh":"如果一個應用程式被封鎖，青少年的高風險行為可能轉移到網上其他地方。"},{"en":"A problem that moves elsewhere has not truly been solved.","zh":"轉移到其他地方的問題並沒有真正被解決。"},{"en":"This phrase warns against surface solutions.","zh":"這個短語提醒人們不要只採用表面解決方法。"}],"source":"2016 Q4.pdf","sourcePage":11},{"front":"rely too heavily on","meaning":"過度依賴","examples":[{"en":"Parents should not rely too heavily on monitoring apps.","zh":"父母不應過度依賴監控應用程式。"},{"en":"To rely too heavily on something means to depend on it too much.","zh":"rely too heavily on something 的意思是過分依靠某物。"},{"en":"Parents rely too heavily on technology when they stop having honest conversations.","zh":"當父母停止坦誠對話時，就是過度依賴科技。"},{"en":"Relying too heavily on apps may make adults miss emotional signs.","zh":"過度依賴應用程式可能令成年人錯過情緒跡象。"},{"en":"This phrase warns against using one tool as if it could solve everything.","zh":"這個短語提醒人們不要把一個工具當成能解決一切。"}],"source":"2016 Q4.pdf","sourcePage":11},{"front":"end up doing","meaning":"最終變成做……","examples":[{"en":"Parents may end up looking at dashboards instead of listening.","zh":"父母可能最終變成查看數據面板，而不是聆聽。"},{"en":"To end up doing something means to finally do something, often unintentionally.","zh":"end up doing something 的意思是最終做某事，通常並非原本有意。"},{"en":"Parents may intend to protect their child but end up creating fear.","zh":"父母可能本想保護孩子，但最終製造恐懼。"},{"en":"A family may end up arguing more if rules are imposed without discussion.","zh":"如果規則沒有討論就被強加，家庭可能最終爭吵更多。"},{"en":"This phrase shows an outcome that develops from earlier choices.","zh":"這個短語展示由早前選擇發展而來的結果。"}],"source":"2016 Q4.pdf","sourcePage":12},{"front":"dashboards","meaning":"數據面板","examples":[{"en":"Parents may spend too much time looking at dashboards.","zh":"父母可能花太多時間查看數據面板。"},{"en":"Dashboards are screens that show organised data, such as location, screen time, or app use.","zh":"dashboards 是顯示整理後數據的畫面，例如位置、屏幕時間或應用程式使用情況。"},{"en":"A monitoring dashboard may show how many hours a child spent online.","zh":"監控數據面板可以顯示孩子上網多少小時。"},{"en":"Dashboards can provide useful information, but they cannot show a child’s full emotional life.","zh":"數據面板可以提供有用資訊，但不能展示孩子完整的情感生活。"},{"en":"This word describes a data display that should not replace conversation.","zh":"這個詞描述不應取代對話的數據顯示。"}],"source":"2016 Q4.pdf","sourcePage":12},{"front":"instead of listening","meaning":"而不是聆聽","examples":[{"en":"Parents may look at dashboards instead of listening at the dinner table.","zh":"父母可能在飯桌上查看數據面板，而不是聆聽。"},{"en":"Instead of listening means choosing another action rather than paying attention to what someone says.","zh":"instead of listening 的意思是選擇另一個行動，而不是專心聽某人說話。"},{"en":"A parent may check phone reports instead of listening to why the child feels stressed.","zh":"父母可能查看手機報告，而不是聆聽孩子為何感到壓力。"},{"en":"Listening can reveal problems that data cannot show.","zh":"聆聽可以揭示數據無法展示的問題。"},{"en":"This phrase criticises replacing human attention with control.","zh":"這個短語批評以控制取代人的注意。"}],"source":"2016 Q4.pdf","sourcePage":12},{"front":"at the dinner table","meaning":"在飯桌上","examples":[{"en":"Parents should listen to their children at the dinner table.","zh":"父母應在飯桌上聆聽子女。"},{"en":"At the dinner table means during a meal, often when family members are together.","zh":"at the dinner table 的意思是在用膳時，通常是家人一起相處的時候。"},{"en":"A child may talk more freely at the dinner table if phones are put away.","zh":"如果手機被收起來，孩子可能在飯桌上更自由地說話。"},{"en":"Conversations at the dinner table can build trust through ordinary daily sharing.","zh":"飯桌上的對話可以透過普通日常分享建立信任。"},{"en":"This phrase describes a simple family setting for communication.","zh":"這個短語描述一個簡單的家庭溝通場景。"}],"source":"2016 Q4.pdf","sourcePage":12},{"front":"a better approach","meaning":"更好的做法","examples":[{"en":"A better approach would be a transparent family digital agreement.","zh":"更好的做法是制定透明的家庭數碼使用協議。"},{"en":"A better approach means a more suitable or effective way to deal with a problem.","zh":"a better approach 的意思是處理問題時更合適或更有效的方法。"},{"en":"A better approach to phone use may begin with discussion rather than secret monitoring.","zh":"處理手機使用的更好做法，可能由討論而不是秘密監控開始。"},{"en":"Better approaches solve problems while protecting trust and dignity.","zh":"更好的做法會解決問題，同時保護信任和尊嚴。"},{"en":"This phrase is useful when moving from criticism to recommendation.","zh":"當由批評轉向建議時，這個短語很有用。"}],"source":"2016 Q4.pdf","sourcePage":12},{"front":"transparent","meaning":"透明的","examples":[{"en":"Family phone rules should be transparent.","zh":"家庭手機規則應該是透明的。"},{"en":"Transparent means open, clear, and not hidden.","zh":"transparent 的意思是公開、清楚而不隱藏。"},{"en":"A transparent rule explains what parents may check, why they check it, and when the rule will be reviewed.","zh":"透明規則會解釋父母可以檢查甚麼、為何檢查，以及何時檢討。"},{"en":"Transparent rules reduce fear because children know what is happening.","zh":"透明規則減少恐懼，因為孩子知道正在發生甚麼。"},{"en":"This word contrasts open agreement with secret surveillance.","zh":"這個詞把公開協議與秘密監控作對比。"}],"source":"2016 Q4.pdf","sourcePage":12},{"front":"family digital agreement","meaning":"家庭數碼使用協議","examples":[{"en":"A family digital agreement can set clear rules for phone use.","zh":"家庭數碼使用協議可以為手機使用訂立清晰規則。"},{"en":"A family digital agreement is a shared set of rules about devices, privacy, safety, and screen time.","zh":"family digital agreement 是關於裝置、私隱、安全和屏幕時間的共同規則。"},{"en":"A family digital agreement may include no phones during meals and permission before downloading unknown apps.","zh":"家庭數碼使用協議可以包括用膳時不用手機，以及下載不明應用程式前先獲准。"},{"en":"Such an agreement works best when parents and children discuss it together.","zh":"當父母和子女一起討論時，這類協議最有效。"},{"en":"This phrase describes cooperation rather than hidden control.","zh":"這個短語描述合作，而不是隱藏控制。"}],"source":"2016 Q4.pdf","sourcePage":12},{"front":"phones outside bedrooms after bedtime","meaning":"睡覺時間後手機放在睡房外","examples":[{"en":"The agreement may require phones to stay outside bedrooms after bedtime.","zh":"協議可能要求睡覺時間後手機放在睡房外。"},{"en":"Phones outside bedrooms after bedtime means devices are kept away from sleeping areas at night.","zh":"phones outside bedrooms after bedtime 的意思是夜晚把裝置放在睡眠空間以外。"},{"en":"A family may charge phones in the living room after bedtime to protect sleep.","zh":"家庭可以在睡覺時間後把手機放在客廳充電，以保護睡眠。"},{"en":"This rule can reduce late-night scrolling without reading private messages.","zh":"這條規則可以減少深夜滑手機，而不用閱讀私人訊息。"},{"en":"The phrase describes a clear boundary that protects rest.","zh":"這個短語描述保護休息的清晰界線。"}],"source":"2016 Q4.pdf","sourcePage":12},{"front":"no devices during meals","meaning":"用膳時不使用電子裝置","examples":[{"en":"A family rule may say that there are no devices during meals.","zh":"家庭規則可能說用膳時不使用電子裝置。"},{"en":"No devices during meals means phones, tablets, and computers are not used while eating together.","zh":"no devices during meals 的意思是一起用膳時不使用手機、平板電腦和電腦。"},{"en":"This rule can help families talk at the dinner table without interruptions.","zh":"這條規則可以幫助家人在飯桌上不受打擾地交談。"},{"en":"No devices during meals protects conversation rather than simply controlling technology.","zh":"用膳時不使用電子裝置保護對話，而不只是控制科技。"},{"en":"This phrase describes a practical rule for family connection.","zh":"這個短語描述促進家庭連繫的實際規則。"}],"source":"2016 Q4.pdf","sourcePage":12},{"front":"permission before downloading unknown apps","meaning":"下載不明應用程式前先獲准","examples":[{"en":"Children should ask for permission before downloading unknown apps.","zh":"孩子下載不明應用程式前應先獲准。"},{"en":"Permission before downloading unknown apps means getting approval before installing unfamiliar software.","zh":"permission before downloading unknown apps 的意思是在安裝不熟悉的軟件前先得到批准。"},{"en":"This rule can protect children from scams, viruses, and hidden data collection.","zh":"這條規則可以保護孩子免受騙案、病毒和隱藏資料收集影響。"},{"en":"Asking permission teaches caution while still allowing children to learn digital judgment.","zh":"先獲准教導謹慎，同時仍讓孩子學習數碼判斷。"},{"en":"This phrase describes a safety rule based on discussion and consent.","zh":"這個短語描述建基於討論和同意的安全規則。"}],"source":"2016 Q4.pdf","sourcePage":12},{"front":"emergency location-sharing","meaning":"緊急位置分享","examples":[{"en":"Emergency location-sharing should be used only when necessary.","zh":"緊急位置分享應只在必要時使用。"},{"en":"Emergency location-sharing means sharing a person’s location during serious or urgent situations.","zh":"emergency location-sharing 是在嚴重或緊急情況下分享某人的位置。"},{"en":"A child may share location in an emergency if lost or in danger.","zh":"如果孩子迷路或有危險，可以在緊急情況下分享位置。"},{"en":"Location-sharing should not become everyday tracking unless there is a clear reason.","zh":"位置分享不應在沒有清晰原因下變成日常追蹤。"},{"en":"This phrase describes a limited safety measure.","zh":"這個短語描述有限度的安全措施。"}],"source":"2016 Q4.pdf","sourcePage":13},{"front":"with the child’s knowledge","meaning":"在孩子知情的情況下","examples":[{"en":"Location-sharing should happen only with the child’s knowledge.","zh":"位置分享只應在孩子知情的情況下進行。"},{"en":"With the child’s knowledge means the child knows what is happening and is not secretly monitored.","zh":"with the child’s knowledge 的意思是孩子知道正在發生甚麼，而不是被秘密監控。"},{"en":"Parents may agree on location-sharing with the child’s knowledge during a school trip.","zh":"父母可以在學校旅行期間，在孩子知情的情況下同意位置分享。"},{"en":"When monitoring happens with the child’s knowledge, it is more transparent and less damaging to trust.","zh":"當監控在孩子知情下進行時，它較透明，也較不會破壞信任。"},{"en":"This phrase highlights consent and honesty.","zh":"這個短語強調同意和誠實。"}],"source":"2016 Q4.pdf","sourcePage":13},{"front":"in serious cases","meaning":"在嚴重情況下","examples":[{"en":"In serious cases, temporary monitoring may be justified.","zh":"在嚴重情況下，暫時監控可能有合理理由。"},{"en":"In serious cases means when the situation is dangerous, repeated, or harmful enough to need stronger action.","zh":"in serious cases 的意思是情況足夠危險、重複或有害，需要更強行動。"},{"en":"In serious cases of cyberbullying, parents may need closer supervision for a limited time.","zh":"在嚴重網絡欺凌情況下，父母可能需要在有限時間內加強監督。"},{"en":"This phrase prevents a rule from being used too broadly.","zh":"這個短語防止某條規則被過度廣泛使用。"},{"en":"It shows that stronger measures need serious reasons.","zh":"它顯示更強措施需要嚴重理由。"}],"source":"2016 Q4.pdf","sourcePage":13},{"front":"repeated contact from strangers","meaning":"陌生人反覆聯絡","examples":[{"en":"Repeated contact from strangers may justify temporary monitoring.","zh":"陌生人反覆聯絡可能令暫時監控有合理理由。"},{"en":"Repeated contact from strangers means unknown people keep messaging, calling, or approaching a child.","zh":"repeated contact from strangers 的意思是不認識的人不斷發訊息、打電話或接近孩子。"},{"en":"If a stranger repeatedly sends private messages to a teenager, parents may need to act quickly.","zh":"如果陌生人反覆向青少年發私人訊息，父母可能需要迅速行動。"},{"en":"Repeated contact from strangers can be dangerous because children may be pressured or tricked.","zh":"陌生人反覆聯絡可能危險，因為孩子可能被施壓或欺騙。"},{"en":"This phrase describes a specific safety concern.","zh":"這個短語描述一個具體安全關注。"}],"source":"2016 Q4.pdf","sourcePage":13},{"front":"clear signs of addiction","meaning":"明顯的成癮跡象","examples":[{"en":"Clear signs of addiction may require stronger parental action.","zh":"明顯的成癮跡象可能需要父母採取更強行動。"},{"en":"Clear signs of addiction are obvious behaviours showing that someone cannot control a habit.","zh":"clear signs of addiction 是顯示某人無法控制某習慣的明顯行為。"},{"en":"A child may show clear signs of addiction if he stops sleeping, studying, or eating properly because of games.","zh":"如果孩子因打機而停止正常睡覺、學習或進食，可能顯示明顯成癮跡象。"},{"en":"Stronger action may be needed when ordinary reminders no longer work.","zh":"當普通提醒不再有效時，可能需要更強行動。"},{"en":"This phrase describes evidence that a problem has become serious.","zh":"這個短語描述問題已變嚴重的證據。"}],"source":"2016 Q4.pdf","sourcePage":13},{"front":"temporary monitoring","meaning":"暫時監控","examples":[{"en":"Temporary monitoring may be justified in serious cases.","zh":"在嚴重情況下，暫時監控可能有合理理由。"},{"en":"Temporary monitoring means checking or tracking for a limited period, not permanently.","zh":"temporary monitoring 的意思是在有限時間內檢查或追蹤，而不是永久監控。"},{"en":"Parents may use temporary monitoring after repeated contact from strangers, with clear explanation.","zh":"在陌生人反覆聯絡後，父母可以在清楚解釋下使用暫時監控。"},{"en":"Temporary monitoring should end once the danger is handled and trust is rebuilt.","zh":"當危險處理好並重建信任後，暫時監控應結束。"},{"en":"This phrase stresses limits and purpose.","zh":"這個短語強調限制和目的。"}],"source":"2016 Q4.pdf","sourcePage":13},{"front":"may be justified","meaning":"可能有合理理由","examples":[{"en":"Temporary monitoring may be justified if a child is in serious danger.","zh":"如果孩子正處於嚴重危險中，暫時監控可能有合理理由。"},{"en":"May be justified means may have a good enough reason to be accepted.","zh":"may be justified 的意思是可能有足夠好理由而被接受。"},{"en":"Stronger rules may be justified if a teenager is being threatened online.","zh":"如果青少年在網上受到威脅，更強規則可能有合理理由。"},{"en":"A measure is justified only when it is necessary, limited, and explained.","zh":"一項措施只有在必要、有限度並經解釋時，才有合理理由。"},{"en":"This phrase shows careful approval rather than complete support.","zh":"這個短語表示謹慎認可，而不是完全支持。"}],"source":"2016 Q4.pdf","sourcePage":13},{"front":"explained, limited and reviewed","meaning":"經解釋、有限度並定期檢討","examples":[{"en":"Any monitoring should be explained, limited and reviewed.","zh":"任何監控都應經解釋、有限度並定期檢討。"},{"en":"Explained, limited and reviewed means clearly told, restricted in scope, and checked again later.","zh":"explained, limited and reviewed 的意思是清楚說明、限制範圍，並在之後再次檢查。"},{"en":"Parents should explain why monitoring is needed, limit what is checked, and review when it should stop.","zh":"父母應解釋為何需要監控、限制檢查內容，並檢討何時停止。"},{"en":"These conditions prevent temporary safety measures from becoming permanent control.","zh":"這些條件防止暫時安全措施變成永久控制。"},{"en":"This phrase sets standards for fair and careful monitoring.","zh":"這個短語為公平而謹慎的監控設定標準。"}],"source":"2016 Q4.pdf","sourcePage":13},{"front":"all things considered","meaning":"綜合而言","examples":[{"en":"All things considered, monitoring apps should not be routine.","zh":"綜合而言，監控應用程式不應成為常規做法。"},{"en":"All things considered means after thinking about all important points.","zh":"all things considered 的意思是在思考所有重要觀點之後。"},{"en":"All things considered, parents should choose conversation before surveillance.","zh":"綜合而言，父母應先選擇對話，再考慮監控。"},{"en":"Writers use this phrase before giving a final balanced judgement.","zh":"作者在提出最終平衡判斷前會使用這個短語。"},{"en":"It shows that the conclusion follows careful weighing of different sides.","zh":"它顯示結論來自仔細權衡不同方面。"}],"source":"2016 Q4.pdf","sourcePage":13},{"front":"as a routine way to","meaning":"作為常規方式去","examples":[{"en":"Parents should not use monitoring apps as a routine way to control phones.","zh":"父母不應把監控應用程式作為控制手機的常規方式。"},{"en":"As a routine way to means as a normal or regular method for doing something.","zh":"as a routine way to 的意思是作為做某事的正常或經常方法。"},{"en":"Parents should not use secret checking as a routine way to manage behaviour.","zh":"父母不應把秘密檢查作為管理行為的常規方式。"},{"en":"A method used routinely can shape family culture over time.","zh":"經常使用的方法會隨時間塑造家庭文化。"},{"en":"This phrase warns against making an exceptional measure normal.","zh":"這個短語提醒人們不要把例外措施變成常規。"}],"source":"2016 Q4.pdf","sourcePage":13},{"front":"control their children’s phones","meaning":"控制子女的手機","examples":[{"en":"Parents should not routinely control their children’s phones.","zh":"父母不應常規地控制子女的手機。"},{"en":"To control their children’s phones means to decide or limit how children use their devices.","zh":"control their children’s phones 的意思是決定或限制孩子如何使用裝置。"},{"en":"Parents may need to control certain phone functions for safety, but total control can damage trust.","zh":"父母可能基於安全需要控制某些手機功能，但完全控制會破壞信任。"},{"en":"Controlling phones without discussion may teach obedience rather than responsibility.","zh":"沒有討論地控制手機，可能教出服從而不是責任感。"},{"en":"This phrase describes a power that should be used carefully.","zh":"這個短語描述一種應謹慎使用的權力。"}],"source":"2016 Q4.pdf","sourcePage":14},{"front":"Protection is necessary","meaning":"保護是必要的","examples":[{"en":"Protection is necessary, but it should not become possession.","zh":"保護是必要的，但它不應變成佔有。"},{"en":"Protection is necessary means keeping children safe is important and cannot be ignored.","zh":"Protection is necessary 的意思是保障孩子安全很重要，不能被忽視。"},{"en":"Protection is necessary when children face scams, cyberbullying, or dangerous strangers online.","zh":"當孩子面對網上騙案、網絡欺凌或危險陌生人時，保護是必要的。"},{"en":"However, necessary protection should still respect privacy and dignity.","zh":"然而，必要的保護仍應尊重私隱和尊嚴。"},{"en":"This phrase balances parental responsibility with children’s rights.","zh":"這個短語平衡父母責任與孩子權利。"}],"source":"2016 Q4.pdf","sourcePage":14},{"front":"protection should not become possession","meaning":"保護不應變成佔有","examples":[{"en":"Protection should not become possession.","zh":"保護不應變成佔有。"},{"en":"Protection should not become possession means care should not turn into ownership or total control.","zh":"protection should not become possession 的意思是關懷不應變成擁有或完全控制。"},{"en":"Parents protect children by guiding them, not by treating every private space as theirs to inspect.","zh":"父母透過引導來保護孩子，而不是把每個私人空間都視為可檢查。"},{"en":"When protection becomes possession, children may feel controlled rather than loved.","zh":"當保護變成佔有，孩子可能覺得被控制，而不是被愛。"},{"en":"This phrase gives a clear principle for respectful parenting.","zh":"這個短語為尊重的育兒方式提出清晰原則。"}],"source":"2016 Q4.pdf","sourcePage":14},{"front":"The time has come for","meaning":"是時候……","examples":[{"en":"The time has come for parents, schools and teenagers to work together.","zh":"是時候讓父母、學校和青少年合作。"},{"en":"The time has come for something means it is now necessary or appropriate to do it.","zh":"The time has come for something 的意思是現在有必要或適合做某事。"},{"en":"The time has come for families to discuss digital habits openly.","zh":"是時候讓家庭公開討論數碼習慣。"},{"en":"Writers use this phrase when calling for action after explaining a problem.","zh":"作者在解釋問題後呼籲行動時會使用這個短語。"},{"en":"It gives the conclusion a sense of urgency.","zh":"它令結論帶有迫切感。"}],"source":"2016 Q4.pdf","sourcePage":14},{"front":"work together","meaning":"合作","examples":[{"en":"Parents, schools and teenagers should work together.","zh":"父母、學校和青少年應合作。"},{"en":"To work together means to cooperate toward a shared goal.","zh":"work together 的意思是為共同目標而合作。"},{"en":"Families and schools can work together to teach safe and responsible phone use.","zh":"家庭和學校可以合作教授安全而負責任的手機使用方式。"},{"en":"Teenagers are more likely to accept rules when they help create them with adults.","zh":"當青少年與成年人一起制定規則時，他們較可能接受規則。"},{"en":"This phrase shows cooperation instead of one-sided control.","zh":"這個短語展示合作，而不是單方面控制。"}],"source":"2016 Q4.pdf","sourcePage":14},{"front":"teach digital literacy","meaning":"教授數碼素養","examples":[{"en":"Schools and parents should teach digital literacy.","zh":"學校和父母應教授數碼素養。"},{"en":"To teach digital literacy means to help people understand how to use digital tools safely, critically, and effectively.","zh":"teach digital literacy 的意思是幫助人們安全、批判而有效地使用數碼工具。"},{"en":"Digital literacy includes checking sources, protecting privacy, and recognising scams.","zh":"數碼素養包括核實來源、保護私隱和識別騙案。"},{"en":"Teaching digital literacy helps children make wise choices when adults are not watching.","zh":"教授數碼素養幫助孩子在成年人沒有監視時作出明智選擇。"},{"en":"This phrase describes education for responsible online life.","zh":"這個短語描述負責任網上生活所需的教育。"}],"source":"2016 Q4.pdf","sourcePage":14},{"front":"set clear boundaries","meaning":"訂立清晰界線","examples":[{"en":"Families should set clear boundaries for phone use.","zh":"家庭應為手機使用訂立清晰界線。"},{"en":"To set clear boundaries means to create understandable limits about what is acceptable.","zh":"set clear boundaries 的意思是制定容易理解的限制，說明甚麼是可接受的。"},{"en":"A family may set clear boundaries such as no phones during meals and no devices after bedtime.","zh":"家庭可以訂立清晰界線，例如用膳時不用手機、睡前不使用電子裝置。"},{"en":"Clear boundaries reduce arguments because everyone knows the expectations.","zh":"清晰界線可以減少爭吵，因為人人都知道期望。"},{"en":"This phrase shows that freedom works better with agreed limits.","zh":"這個短語顯示自由在有共同限制下會更有效。"}],"source":"2016 Q4.pdf","sourcePage":14},{"front":"online pressure","meaning":"網上壓力","examples":[{"en":"Teenagers need to talk about online pressure.","zh":"青少年需要談論網上壓力。"},{"en":"Online pressure is stress caused by messages, likes, comments, group chats, or expectations on the Internet.","zh":"online pressure 是由訊息、讚好、評論、群組聊天或互聯網上的期望造成的壓力。"},{"en":"A teenager may feel online pressure to reply instantly or look happy in every post.","zh":"青少年可能感到網上壓力，要立即回覆或在每篇帖文中看起來開心。"},{"en":"Talking about online pressure helps adults understand why phones are hard to put down.","zh":"談論網上壓力幫助成年人理解為何手機難以放下。"},{"en":"This phrase describes social stress created through digital life.","zh":"這個短語描述數碼生活造成的社交壓力。"}],"source":"2016 Q4.pdf","sourcePage":14},{"front":"adjust rules","meaning":"調整規則","examples":[{"en":"Parents should adjust rules as children mature.","zh":"父母應隨着孩子成熟而調整規則。"},{"en":"To adjust rules means to change rules so they better fit a new situation.","zh":"adjust rules 的意思是改變規則，使它們更適合新情況。"},{"en":"Parents may adjust phone rules when a child becomes more responsible.","zh":"當孩子變得更負責任時，父母可以調整手機規則。"},{"en":"Rules that never change may feel unfair as teenagers grow older.","zh":"永不改變的規則在青少年長大後可能感覺不公平。"},{"en":"This phrase shows that guidance should develop with the child.","zh":"這個短語顯示引導應隨孩子一起發展。"}],"source":"2016 Q4.pdf","sourcePage":14},{"front":"as children mature","meaning":"隨着孩子成熟","examples":[{"en":"Phone rules should change as children mature.","zh":"手機規則應隨着孩子成熟而改變。"},{"en":"As children mature means as children grow older and become more responsible or thoughtful.","zh":"as children mature 的意思是隨着孩子長大並變得更負責任或更成熟。"},{"en":"As children mature, parents can give them more privacy and decision-making space.","zh":"隨着孩子成熟，父母可以給予他們更多私隱和決策空間。"},{"en":"Rules should change with maturity because teenagers need practice managing freedom.","zh":"規則應隨成熟程度改變，因為青少年需要練習管理自由。"},{"en":"This phrase connects age and growth with changing responsibility.","zh":"這個短語把年齡和成長與責任變化連繫起來。"}],"source":"2016 Q4.pdf","sourcePage":14},{"front":"a tool for learning and connection","meaning":"學習和聯繫的工具","examples":[{"en":"A mobile phone should be a tool for learning and connection.","zh":"手機應是學習和聯繫的工具。"},{"en":"A tool for learning and connection means something used to gain knowledge and maintain relationships.","zh":"tool for learning and connection 是用來獲取知識和維持關係的東西。"},{"en":"A phone can be a tool for learning when students watch lessons or check dictionaries.","zh":"當學生觀看課堂影片或查字典時，手機可以是學習工具。"},{"en":"It can also support connection when children contact family or friends responsibly.","zh":"當孩子負責任地聯絡家人或朋友時，手機也可以支援聯繫。"},{"en":"This phrase describes the positive purpose of technology.","zh":"這個短語描述科技的正面目的。"}],"source":"2016 Q4.pdf","sourcePage":15},{"front":"not a leash","meaning":"不是牽制人的繩索","examples":[{"en":"A mobile phone should be a tool, not a leash.","zh":"手機應是一種工具，而不是牽制人的繩索。"},{"en":"Not a leash means it should not be used like a rope for controlling someone’s movement or behaviour.","zh":"not a leash 的意思是它不應像繩索一樣用來控制某人的行動或行為。"},{"en":"A phone becomes a leash if parents use it mainly to track and control a child.","zh":"如果父母主要用手機追蹤和控制孩子，手機就變成牽制人的繩索。"},{"en":"Technology should support independence, not keep teenagers tied to constant supervision.","zh":"科技應支援獨立，而不是把青少年綁在持續監督之下。"},{"en":"This metaphor criticises control that limits growth.","zh":"這個比喻批評限制成長的控制。"}],"source":"2016 Q4.pdf","sourcePage":15},{"front":"act responsibly","meaning":"負責任地行事","examples":[{"en":"Young people should learn to act responsibly online.","zh":"年輕人應學會在網上負責任地行事。"},{"en":"To act responsibly means to behave with care, honesty, and awareness of consequences.","zh":"act responsibly 的意思是以謹慎、誠實和有後果意識的方式行事。"},{"en":"Teenagers act responsibly when they check information before sharing it.","zh":"青少年在分享資訊前先核實，就是負責任地行事。"},{"en":"Responsible online action includes respecting privacy and avoiding cruel comments.","zh":"負責任的網上行為包括尊重私隱和避免殘酷評論。"},{"en":"This phrase describes behaviour guided by judgement, not fear.","zh":"這個短語描述由判斷而不是恐懼引導的行為。"}],"source":"2016 Q4.pdf","sourcePage":15},{"front":"not only rules to follow, but also trust to grow into","meaning":"不但需要可遵守的規則，也需要可讓他們成長的信任","examples":[{"en":"Young people need not only rules to follow, but also trust to grow into.","zh":"年輕人不但需要可遵守的規則，也需要可讓他們成長的信任。"},{"en":"Not only rules to follow, but also trust to grow into means children need limits and the confidence that adults believe they can mature.","zh":"not only rules to follow, but also trust to grow into 的意思是孩子需要限制，也需要成年人相信他們能成熟的信心。"},{"en":"A teenager learns better when parents give clear rules and gradually more trust.","zh":"當父母給予清晰規則並逐步增加信任時，青少年會學得更好。"},{"en":"Rules guide behaviour, but trust gives young people room to become responsible.","zh":"規則引導行為，但信任給年輕人成為負責任的人的空間。"},{"en":"This phrase captures a balanced approach to parenting.","zh":"這個短語概括了平衡的育兒方法。"}],"source":"2016 Q4.pdf","sourcePage":15},{"front":"Yours faithfully","meaning":"此致敬禮","examples":[{"en":"A formal letter can end with “Yours faithfully”.","zh":"正式信件可以以 Yours faithfully 作結。"},{"en":"Yours faithfully is a formal closing used when the writer does not know the recipient personally.","zh":"Yours faithfully 是在作者不熟悉收信人時使用的正式結尾語。"},{"en":"A student may end a letter to a newspaper editor with “Yours faithfully”.","zh":"學生寫給報章編輯的信件，可以用 Yours faithfully 作結。"},{"en":"This closing makes the letter sound polite, respectful, and formal.","zh":"這個結尾令信件聽起來禮貌、尊重而正式。"},{"en":"It belongs in formal letters, not casual messages to friends.","zh":"它屬於正式信件，不適合給朋友的隨意訊息。"}],"source":"2016 Q4.pdf","sourcePage":15}],"dse/writing/part-b/2016/Q5":[{"front":"still hot, still human","meaning":"仍然熱騰騰，仍然有人情味","examples":[{"en":"Dai pai dongs are still hot, still human, and still worth protecting.","zh":"大牌檔仍然熱騰騰，仍然有人情味，仍然值得保護。"},{"en":"Still hot, still human means something remains lively, warm, and full of real human feeling.","zh":"仍然熱騰騰，仍然有人情味，意思是某事物仍然有活力、有溫度，並充滿真實人情。"},{"en":"An old family kitchen may be still hot, still human, because people cook and talk there every night.","zh":"舊式家庭廚房可能仍然熱騰騰，仍然有人情味，因為人們每晚在那裏煮飯和聊天。"},{"en":"A place is still human when it makes people feel seen, welcomed, and connected.","zh":"當一個地方令人感到被看見、被歡迎和有連繫，它就是仍然有人情味。"},{"en":"Dai pai dongs are still hot, still human because food, voices, and care meet in the same space.","zh":"大牌檔仍然熱騰騰，仍然有人情味，因為食物、聲音和關心在同一空間相遇。"}],"source":"2016 Q5.pdf","sourcePage":1},{"front":"deserve a future","meaning":"值得擁有未來","examples":[{"en":"Dai pai dongs deserve a future in Hong Kong.","zh":"大牌檔在香港值得擁有未來。"},{"en":"To deserve a future means to be valuable enough to continue existing.","zh":"值得擁有未來，意思是某事物有足夠價值繼續存在。"},{"en":"A small neighbourhood library deserves a future if it helps children learn.","zh":"如果小型社區圖書館幫助孩子學習，它就值得擁有未來。"},{"en":"Old places deserve a future when they still serve people and carry meaning.","zh":"當舊地方仍服務人們並承載意義，它們就值得擁有未來。"},{"en":"Dai pai dongs deserve a future because they are part of Hong Kong’s memory and daily life.","zh":"大牌檔值得擁有未來，因為它們是香港記憶和日常生活的一部分。"}],"source":"2016 Q5.pdf","sourcePage":1},{"front":"street life","meaning":"街頭生活","examples":[{"en":"Street life used to announce itself before we even saw it.","zh":"街頭生活過去甚至在我們看見之前就已展現自身存在。"},{"en":"Street life means the sounds, smells, movement, shops, and people that make streets feel alive.","zh":"街頭生活，是令街道有生命力的聲音、氣味、活動、店舖和人群。"},{"en":"A market has strong street life when neighbours talk, vendors shout, and food smells fill the air.","zh":"當街坊聊天、小販叫賣、食物香氣充滿空氣，街市就有濃厚街頭生活。"},{"en":"Street life disappears when every corner becomes quiet, private, and the same.","zh":"當每個角落都變得安靜、私人化和一式一樣，街頭生活就會消失。"},{"en":"Dai pai dongs are important because they add warmth and rhythm to Hong Kong street life.","zh":"大牌檔重要，因為它們為香港街頭生活加入溫暖和節奏。"}],"source":"2016 Q5.pdf","sourcePage":1},{"front":"used to","meaning":"過去常常","examples":[{"en":"Street life used to announce itself through sounds and smells.","zh":"街頭生活過去常常透過聲音和氣味展現自身存在。"},{"en":"Used to means something happened regularly in the past but may not happen now.","zh":"過去常常，意思是某事在過去經常發生，但現在可能不再如此。"},{"en":"My grandmother used to buy vegetables from the same market stall every morning.","zh":"我的祖母過去常常每天早上在同一個街市檔口買菜。"},{"en":"When we say a place used to be lively, we suggest it has changed.","zh":"當我們說一個地方過去常常很熱鬧，就暗示它已經改變。"},{"en":"Hong Kong used to have more open-air food stalls than it does today.","zh":"香港過去常常有比今天更多的露天熟食檔。"}],"source":"2016 Q5.pdf","sourcePage":1},{"front":"announce itself","meaning":"展現自身存在","examples":[{"en":"Hong Kong street life used to announce itself before we saw it.","zh":"香港街頭生活過去在我們看見之前已展現自身存在。"},{"en":"To announce itself means to become noticeable without needing formal explanation.","zh":"展現自身存在，意思是不需要正式說明也變得明顯可感。"},{"en":"A bakery announces itself when the smell of fresh bread reaches the street.","zh":"當新鮮麵包香氣飄到街上，麵包店就展現自身存在。"},{"en":"A festival announces itself through music, lights, and crowds before visitors arrive.","zh":"節日透過音樂、燈光和人群，在遊人到達前已展現自身存在。"},{"en":"Dai pai dongs announce themselves through flames, voices, and the smell of food.","zh":"大牌檔透過火焰、人聲和食物香氣展現自身存在。"}],"source":"2016 Q5.pdf","sourcePage":1},{"front":"before we even saw it","meaning":"甚至在我們看見之前","examples":[{"en":"We could sense street life before we even saw it.","zh":"我們甚至在看見街頭生活之前，已經感受到它。"},{"en":"Before we even saw it means something was already noticeable through other senses before it appeared to our eyes.","zh":"甚至在我們看見之前，意思是某事在進入視線前已透過其他感官變得明顯。"},{"en":"We smelled the sea before we even saw it.","zh":"我們甚至在看見大海之前，已經聞到海的氣味。"},{"en":"A busy kitchen may be heard before we even see it.","zh":"忙碌的廚房可能甚至在我們看見之前，已經被聽見。"},{"en":"Dai pai dongs could be sensed before we even saw them because of their sound and smell.","zh":"大牌檔甚至在我們看見之前，已因聲音和氣味而被感受到。"}],"source":"2016 Q5.pdf","sourcePage":1},{"front":"clatter of woks","meaning":"鑊鏟聲","examples":[{"en":"The clatter of woks could be heard from the street.","zh":"街上可以聽見鑊鏟聲。"},{"en":"The clatter of woks is the loud metallic sound made when cooks move woks and tools quickly.","zh":"鑊鏟聲，是廚師快速移動鑊和廚具時發出的響亮金屬聲。"},{"en":"In a busy kitchen, the clatter of woks tells customers that food is being cooked fresh.","zh":"在忙碌廚房中，鑊鏟聲告訴顧客食物正在新鮮烹調。"},{"en":"The clatter of woks creates energy because it sounds fast, hot, and alive.","zh":"鑊鏟聲創造活力，因為它聽起來快速、熱鬧和有生命力。"},{"en":"For many people, the clatter of woks is part of Hong Kong’s street memory.","zh":"對很多人來說，鑊鏟聲是香港街頭記憶的一部分。"}],"source":"2016 Q5.pdf","sourcePage":1},{"front":"hiss of blue flames","meaning":"藍色火焰的嘶嘶聲","examples":[{"en":"The hiss of blue flames came from the open-air stalls.","zh":"藍色火焰的嘶嘶聲來自露天檔口。"},{"en":"The hiss of blue flames is the sharp sound of strong gas flames used for cooking.","zh":"藍色火焰的嘶嘶聲，是強烈煤氣火焰煮食時發出的尖細聲音。"},{"en":"A cook may turn up the fire, and the hiss of blue flames fills the stall.","zh":"廚師可能把火力調高，藍色火焰的嘶嘶聲便充滿檔口。"},{"en":"The hiss of blue flames suggests heat, speed, and freshly cooked food.","zh":"藍色火焰的嘶嘶聲暗示熱力、速度和新鮮烹調的食物。"},{"en":"At a dai pai dong, the hiss of blue flames makes the cooking feel immediate and alive.","zh":"在大牌檔，藍色火焰的嘶嘶聲令烹調感覺即時而有生命力。"}],"source":"2016 Q5.pdf","sourcePage":1},{"front":"fried noodles","meaning":"炒麵","examples":[{"en":"The smell of fried noodles drifted through the pavement.","zh":"炒麵的香氣飄過行人路。"},{"en":"Fried noodles are noodles cooked in a hot pan or wok with oil and other ingredients.","zh":"炒麵，是用熱鍋或鑊加油和其他食材炒成的麵。"},{"en":"A plate of fried noodles may include beef, vegetables, soy sauce, and strong wok flavour.","zh":"一碟炒麵可能包括牛肉、蔬菜、豉油和濃厚鑊氣。"},{"en":"The smell of fried noodles can attract hungry people walking past a stall.","zh":"炒麵的香氣可以吸引路過的飢餓行人。"},{"en":"Fried noodles are simple food, but they can carry strong memories of street eating.","zh":"炒麵是簡單食物，但可以承載強烈的街頭飲食記憶。"}],"source":"2016 Q5.pdf","sourcePage":1},{"front":"drift through","meaning":"飄過","examples":[{"en":"The smell of fried noodles drifted through a crowded pavement.","zh":"炒麵的香氣飄過擠迫的行人路。"},{"en":"To drift through means to move slowly and gently through a place.","zh":"飄過，意思是緩慢而輕柔地穿過某個地方。"},{"en":"The smell of flowers drifted through the classroom after the windows were opened.","zh":"窗戶打開後，花香飄過課室。"},{"en":"Food smells drift through streets and make people notice nearby stalls.","zh":"食物香氣飄過街道，令人注意附近檔口。"},{"en":"At night, the smell of hot noodles may drift through the pavement and lead people to a dai pai dong.","zh":"夜晚，熱麵香氣可能飄過行人路，把人帶到大牌檔。"}],"source":"2016 Q5.pdf","sourcePage":1},{"front":"crowded pavement","meaning":"擠迫的行人路","examples":[{"en":"The smell of food drifted through a crowded pavement.","zh":"食物香氣飄過擠迫的行人路。"},{"en":"A crowded pavement is a busy walkway filled with many pedestrians.","zh":"擠迫的行人路，是充滿大量行人的繁忙步行道。"},{"en":"A crowded pavement near a market may be full of shoppers, workers, and schoolchildren.","zh":"街市附近擠迫的行人路可能充滿買菜的人、上班族和學生。"},{"en":"Food stalls on crowded pavements make the street feel lively but also need careful management.","zh":"擠迫行人路上的熟食檔令街道熱鬧，但也需要小心管理。"},{"en":"Dai pai dongs belong to the memory of crowded pavements, voices, and shared meals.","zh":"大牌檔屬於擠迫行人路、人聲和共享飯餐的記憶。"}],"source":"2016 Q5.pdf","sourcePage":2},{"front":"open-air dai pai dong","meaning":"露天大牌檔","examples":[{"en":"The open-air dai pai dong was once part of Hong Kong street life.","zh":"露天大牌檔曾經是香港街頭生活的一部分。"},{"en":"An open-air dai pai dong is an outdoor cooked-food stall serving meals in a public street setting.","zh":"露天大牌檔，是在公共街道環境中供應熟食的戶外食檔。"},{"en":"People may sit at folding tables beside an open-air dai pai dong after work.","zh":"人們下班後可能坐在露天大牌檔旁的摺枱吃飯。"},{"en":"Open-air dai pai dongs feel different from indoor restaurants because cooking and eating happen in public.","zh":"露天大牌檔與室內餐廳不同，因為煮食和進食都在公共空間發生。"},{"en":"An open-air dai pai dong keeps street food visible, noisy, and human.","zh":"露天大牌檔讓街頭食物保持可見、熱鬧和有人情味。"}],"source":"2016 Q5.pdf","sourcePage":2},{"front":"once part of","meaning":"曾經是……的一部分","examples":[{"en":"Dai pai dongs were once part of Hong Kong’s urban music.","zh":"大牌檔曾經是香港城市樂章的一部分。"},{"en":"Once part of means something belonged to a place or situation in the past.","zh":"曾經是某事的一部分，意思是某物在過去屬於某個地方或情況。"},{"en":"Old letter boxes were once part of many neighbourhood entrances.","zh":"舊信箱曾經是許多屋苑入口的一部分。"},{"en":"When something was once part of daily life, losing it can feel personal.","zh":"當某事曾經是日常生活的一部分，失去它會令人感到切身。"},{"en":"Dai pai dongs were once part of the ordinary rhythm of Hong Kong streets.","zh":"大牌檔曾經是香港街道日常節奏的一部分。"}],"source":"2016 Q5.pdf","sourcePage":2},{"front":"urban music","meaning":"城市樂章","examples":[{"en":"The sounds of dai pai dongs formed part of the city’s urban music.","zh":"大牌檔的聲音構成這座城市城市樂章的一部分。"},{"en":"Urban music here means the everyday sounds that give a city its character.","zh":"這裏的城市樂章，是指賦予城市特色的日常聲音。"},{"en":"Bus brakes, market voices, and footsteps can become a city’s urban music.","zh":"巴士煞車聲、街市人聲和腳步聲，都可以成為城市樂章。"},{"en":"Urban music changes when old street sounds are replaced by silence or machines.","zh":"當舊街聲被沉默或機器取代，城市樂章就會改變。"},{"en":"Dai pai dongs added wok sounds and human voices to Hong Kong’s urban music.","zh":"大牌檔為香港城市樂章加入鑊聲和人聲。"}],"source":"2016 Q5.pdf","sourcePage":2},{"front":"be pushed aside by","meaning":"被……擠走","examples":[{"en":"Dai pai dongs are being pushed aside by redevelopment and rising rents.","zh":"大牌檔正被重建和租金上升擠走。"},{"en":"To be pushed aside by something means to be forced out or made less important because of it.","zh":"被某事擠走，意思是因它而被迫離開或變得不再重要。"},{"en":"Small shops may be pushed aside by large shopping malls.","zh":"小店可能被大型商場擠走。"},{"en":"Local traditions are pushed aside when money becomes the only priority.","zh":"當金錢成為唯一優先，本地傳統就會被擠走。"},{"en":"Dai pai dongs are pushed aside when redevelopment leaves no space for street culture.","zh":"當重建不給街頭文化留下空間，大牌檔就會被擠走。"}],"source":"2016 Q5.pdf","sourcePage":2},{"front":"redevelopment","meaning":"重建","examples":[{"en":"Redevelopment has pushed many old street stalls aside.","zh":"重建已經擠走許多舊街頭檔口。"},{"en":"Redevelopment means rebuilding an area with new buildings, roads, or facilities.","zh":"重建，意思是以新建築、道路或設施重新建設某個地區。"},{"en":"Redevelopment can improve safety, but it may also remove old communities.","zh":"重建可以改善安全，但也可能移走舊社群。"},{"en":"A street market may disappear when redevelopment turns the area into offices.","zh":"當重建把地區變成辦公室，街市可能會消失。"},{"en":"Hong Kong needs redevelopment that keeps space for memory and local culture.","zh":"香港需要能為記憶和本地文化保留空間的重建。"}],"source":"2016 Q5.pdf","sourcePage":2},{"front":"rising rents","meaning":"租金上升","examples":[{"en":"Rising rents make it harder for dai pai dongs to survive.","zh":"租金上升令大牌檔更難生存。"},{"en":"Rising rents are increasing costs that tenants must pay for using a place.","zh":"租金上升，是租戶使用地方所需支付的費用增加。"},{"en":"Rising rents can force small shops to close even if customers still love them.","zh":"即使顧客仍喜歡小店，租金上升也可能迫使它們結業。"},{"en":"When rents rise quickly, old food stalls may not earn enough to stay.","zh":"當租金快速上升，舊熟食檔可能賺不到足夠金錢留下。"},{"en":"Rising rents threaten dai pai dongs because they depend on affordable space.","zh":"租金上升威脅大牌檔，因為它們依賴可負擔的空間。"}],"source":"2016 Q5.pdf","sourcePage":2},{"front":"licensing restrictions","meaning":"牌照限制","examples":[{"en":"Licensing restrictions have affected the future of dai pai dongs.","zh":"牌照限制影響了大牌檔的未來。"},{"en":"Licensing restrictions are rules that limit who may operate and under what conditions.","zh":"牌照限制，是限制誰可以經營以及在甚麼條件下經營的規則。"},{"en":"A food stall may close if licensing restrictions make renewal impossible.","zh":"如果牌照限制令續牌不可能，食檔可能要結業。"},{"en":"Restrictions can protect safety, but they can also make survival difficult.","zh":"限制可以保障安全，但也可能令生存困難。"},{"en":"Fair licensing restrictions should protect hygiene without erasing dai pai dongs.","zh":"公平的牌照限制應保障衞生，而不抹去大牌檔。"}],"source":"2016 Q5.pdf","sourcePage":2},{"front":"chain restaurants","meaning":"連鎖餐廳","examples":[{"en":"Chain restaurants have replaced many older eating places.","zh":"連鎖餐廳已取代許多較舊的用餐地方。"},{"en":"Chain restaurants are restaurants with many branches using similar menus and designs.","zh":"連鎖餐廳，是有許多分店並使用相似餐牌和設計的餐廳。"},{"en":"A chain restaurant may look the same in different districts.","zh":"連鎖餐廳在不同地區可能看起來一樣。"},{"en":"Chain restaurants can be convenient, but they often feel less personal than old stalls.","zh":"連鎖餐廳可以方便，但通常比舊檔口少一點人情味。"},{"en":"When chain restaurants replace dai pai dongs, the city may lose local character.","zh":"當連鎖餐廳取代大牌檔，城市可能失去本地特色。"}],"source":"2016 Q5.pdf","sourcePage":2},{"front":"this has made citizens consider whether","meaning":"這令市民思考是否","examples":[{"en":"This has made citizens consider whether dai pai dongs should be preserved.","zh":"這令市民思考是否應保育大牌檔。"},{"en":"This has made citizens consider whether means this situation has caused people to think seriously about a question.","zh":"這令市民思考是否，意思是這種情況促使人們認真考慮一個問題。"},{"en":"Rising waste has made citizens consider whether plastic use should be reduced.","zh":"垃圾增加令市民思考是否應減少使用塑膠。"},{"en":"When old places disappear, citizens consider whether protection is needed.","zh":"當舊地方消失，市民會思考是否需要保護。"},{"en":"The decline of dai pai dongs has made citizens consider whether Hong Kong is losing part of itself.","zh":"大牌檔衰落令市民思考香港是否正失去自身一部分。"}],"source":"2016 Q5.pdf","sourcePage":2},{"front":"officials","meaning":"官員","examples":[{"en":"Officials must decide how to protect local food culture.","zh":"官員必須決定如何保護本地飲食文化。"},{"en":"Officials are people with authority to make or carry out public decisions.","zh":"官員，是有權制定或執行公共決定的人。"},{"en":"Government officials may inspect food stalls to check safety.","zh":"政府官員可能巡查食檔以檢查安全。"},{"en":"Officials should balance hygiene, public space, and cultural value.","zh":"官員應平衡衞生、公共空間和文化價值。"},{"en":"In the dai pai dong debate, officials need to protect both people and heritage.","zh":"在大牌檔討論中，官員需要同時保護人和文化遺產。"}],"source":"2016 Q5.pdf","sourcePage":3},{"front":"be left to disappear","meaning":"被任由消失","examples":[{"en":"Dai pai dongs should not simply be left to disappear.","zh":"大牌檔不應被簡單任由消失。"},{"en":"Be left to disappear means no one takes action, so something slowly vanishes.","zh":"被任由消失，意思是沒有人採取行動，所以某事物慢慢消失。"},{"en":"An old playground may be left to disappear if nobody repairs it.","zh":"如果沒有人修理，舊遊樂場可能被任由消失。"},{"en":"Cultural places disappear faster when society treats them as unimportant.","zh":"當社會把文化地方視為不重要，它們會更快消失。"},{"en":"Dai pai dongs should not be left to disappear just because they are old and inconvenient.","zh":"大牌檔不應只因為古老和不方便就被任由消失。"}],"source":"2016 Q5.pdf","sourcePage":3},{"front":"be preserved","meaning":"被保育；被保存","examples":[{"en":"Dai pai dongs should be preserved for future generations.","zh":"大牌檔應為未來世代被保育。"},{"en":"Be preserved means be protected so something can continue to exist.","zh":"被保育或被保存，意思是被保護，使某事物能繼續存在。"},{"en":"Old photos should be preserved because they record family history.","zh":"舊照片應被保存，因為它們記錄家庭歷史。"},{"en":"A market can be preserved by improving safety without removing its character.","zh":"街市可以透過改善安全而不移除特色來被保育。"},{"en":"Dai pai dongs should be preserved because they hold food, memory, and community together.","zh":"大牌檔應被保育，因為它們把食物、記憶和社區連在一起。"}],"source":"2016 Q5.pdf","sourcePage":3},{"front":"remain alive","meaning":"保持活力","examples":[{"en":"The city can remain alive if its street culture is protected.","zh":"如果街頭文化受到保護，這座城市可以保持活力。"},{"en":"Remain alive means continue to feel active, meaningful, and full of energy.","zh":"保持活力，意思是繼續感覺活躍、有意義和充滿能量。"},{"en":"A school tradition remains alive when students still practise it each year.","zh":"當學生每年仍實踐一項學校傳統，它就保持活力。"},{"en":"A city remains alive when ordinary people can still meet, talk, and eat in shared spaces.","zh":"當普通人仍能在共享空間相遇、聊天和吃飯，城市就保持活力。"},{"en":"Protecting dai pai dongs helps Hong Kong remain alive beyond shopping malls and offices.","zh":"保護大牌檔幫助香港在商場和辦公室以外保持活力。"}],"source":"2016 Q5.pdf","sourcePage":3},{"front":"as far as I am concerned","meaning":"就我而言","examples":[{"en":"As far as I am concerned, dai pai dongs are worth preserving.","zh":"就我而言，大牌檔值得保育。"},{"en":"As far as I am concerned means in my opinion or from my point of view.","zh":"就我而言，意思是以我的看法或從我的角度來說。"},{"en":"As far as I am concerned, students learn best from clear examples.","zh":"就我而言，學生從清晰例子中學得最好。"},{"en":"Writers use this phrase to introduce a personal but serious judgement.","zh":"作者使用這個短語來引入個人但認真的判斷。"},{"en":"As far as I am concerned, dai pai dongs should be improved, not erased.","zh":"就我而言，大牌檔應被改善，而不是被抹去。"}],"source":"2016 Q5.pdf","sourcePage":3},{"front":"worth preserving","meaning":"值得保育","examples":[{"en":"Dai pai dongs are worth preserving.","zh":"大牌檔值得保育。"},{"en":"Worth preserving means valuable enough to protect and keep.","zh":"值得保育，意思是有足夠價值值得保護和留下。"},{"en":"A handwritten family recipe is worth preserving because it carries memory.","zh":"手寫家庭食譜值得保存，因為它承載記憶。"},{"en":"Places are worth preserving when they teach people who they are.","zh":"當地方教人認識自己是誰，它們就值得保育。"},{"en":"Dai pai dongs are worth preserving because they connect food with local identity.","zh":"大牌檔值得保育，因為它們把食物與本地身份連結起來。"}],"source":"2016 Q5.pdf","sourcePage":3},{"front":"not merely because…, but because…","meaning":"不只是因為……而是因為……","examples":[{"en":"Dai pai dongs matter not merely because they are old, but because they hold shared memory.","zh":"大牌檔重要，不只是因為它們古老，而是因為它們承載共同記憶。"},{"en":"Not merely because…, but because… shows that the deeper reason is more important than the obvious one.","zh":"不只是因為……而是因為……，顯示更深層原因比表面原因更重要。"},{"en":"A school song matters not merely because it is old, but because students remember singing it together.","zh":"校歌重要，不只是因為它古老，而是因為學生記得一起唱過它。"},{"en":"This structure helps writers move from a simple reason to a stronger reason.","zh":"這個結構幫助作者由簡單原因轉向更有力原因。"},{"en":"Dai pai dongs should be protected not merely because of age, but because of meaning.","zh":"大牌檔應受保護，不只是因為年代久遠，而是因為意義深厚。"}],"source":"2016 Q5.pdf","sourcePage":3},{"front":"shared memory","meaning":"共同記憶","examples":[{"en":"Dai pai dongs protect Hong Kong’s shared memory.","zh":"大牌檔保護香港的共同記憶。"},{"en":"Shared memory means experiences and stories remembered by many people in a community.","zh":"共同記憶，是社群中許多人一起記得的經驗和故事。"},{"en":"A neighbourhood festival can become shared memory when families attend it every year.","zh":"當家庭每年參加社區節日，它可以成為共同記憶。"},{"en":"Shared memory helps people feel that they belong to the same place.","zh":"共同記憶幫助人們感到自己屬於同一個地方。"},{"en":"Dai pai dongs carry shared memory because different generations have eaten there.","zh":"大牌檔承載共同記憶，因為不同世代都曾在那裏吃飯。"}],"source":"2016 Q5.pdf","sourcePage":3},{"front":"sustain human connection","meaning":"維繫人與人之間的聯繫","examples":[{"en":"Dai pai dongs sustain human connection in a busy city.","zh":"大牌檔在繁忙城市中維繫人與人之間的聯繫。"},{"en":"To sustain human connection means to keep relationships, conversation, and care alive.","zh":"維繫人與人之間的聯繫，意思是保持關係、交談和關心。"},{"en":"A small park sustains human connection when neighbours meet there every morning.","zh":"當街坊每天早上在小公園相遇，公園就維繫人與人之間的聯繫。"},{"en":"Human connection weakens when people only order, eat, and leave without speaking.","zh":"當人們只落單、吃飯和離開而不說話，人與人的聯繫就會減弱。"},{"en":"Dai pai dongs sustain human connection by making strangers share space and stories.","zh":"大牌檔透過讓陌生人共享空間和故事，維繫人與人之間的聯繫。"}],"source":"2016 Q5.pdf","sourcePage":3},{"front":"future generations","meaning":"未來世代","examples":[{"en":"Future generations should know what authentic Hong Kong feels like.","zh":"未來世代應該知道真實的香港感覺如何。"},{"en":"Future generations are people who will live after the present generation.","zh":"未來世代，是在現今世代之後生活的人。"},{"en":"We preserve old buildings so future generations can understand the past.","zh":"我們保育舊建築，好讓未來世代理解過去。"},{"en":"If cultural places disappear, future generations may only learn about them from pictures.","zh":"如果文化地方消失，未來世代可能只能從圖片中認識它們。"},{"en":"Dai pai dongs should survive so future generations can taste part of Hong Kong history.","zh":"大牌檔應繼續存在，讓未來世代能品嚐香港歷史的一部分。"}],"source":"2016 Q5.pdf","sourcePage":3},{"front":"a taste of","meaning":"……的體驗；……的味道","examples":[{"en":"Dai pai dongs give young people a taste of authentic Hong Kong.","zh":"大牌檔給年輕人真實香港的體驗。"},{"en":"A taste of something means a small but real experience of it.","zh":"某事的體驗或味道，意思是對某事有小但真實的經驗。"},{"en":"A short visit to a farm gives children a taste of rural life.","zh":"短暫參觀農場可以給孩子鄉村生活的體驗。"},{"en":"Food can give people a taste of history when it carries old habits and stories.","zh":"當食物承載舊習慣和故事，它可以給人歷史的味道。"},{"en":"Dai pai dongs give young people a taste of street culture, not only a meal.","zh":"大牌檔給年輕人街頭文化的體驗，而不只是一餐飯。"}],"source":"2016 Q5.pdf","sourcePage":4},{"front":"authentic Hong Kong","meaning":"真實的香港","examples":[{"en":"Dai pai dongs offer a taste of authentic Hong Kong.","zh":"大牌檔提供真實香港的味道。"},{"en":"Authentic Hong Kong means the real local character of the city, not a polished image made for show.","zh":"真實的香港，意思是城市真正的本地特色，而不是為展示而包裝的形象。"},{"en":"Street markets, local cafés, and Cantonese voices can show authentic Hong Kong.","zh":"街市、本地茶餐廳和廣東話人聲可以展現真實的香港。"},{"en":"Authentic Hong Kong is found in ordinary daily life as much as in famous landmarks.","zh":"真實的香港不只在著名地標中，也在普通日常生活中。"},{"en":"Dai pai dongs feel authentic because they are practical, noisy, warm, and local.","zh":"大牌檔感覺真實，因為它們實用、嘈雜、溫暖而本地。"}],"source":"2016 Q5.pdf","sourcePage":4},{"front":"to begin with","meaning":"首先","examples":[{"en":"To begin with, dai pai dongs are living archives of Hong Kong history.","zh":"首先，大牌檔是香港歷史的活生生檔案。"},{"en":"To begin with is used to introduce the first reason or point.","zh":"首先，用來引入第一個理由或重點。"},{"en":"To begin with, students need enough sleep before they can study well.","zh":"首先，學生需要足夠睡眠，然後才能好好學習。"},{"en":"Writers use this phrase to organise an argument clearly.","zh":"作者使用這個短語來清楚組織論點。"},{"en":"To begin with, dai pai dongs matter because they keep history in daily use.","zh":"首先，大牌檔重要，因為它們讓歷史保留在日常使用之中。"}],"source":"2016 Q5.pdf","sourcePage":4},{"front":"living archives","meaning":"活生生的歷史檔案","examples":[{"en":"Dai pai dongs are living archives of Hong Kong history.","zh":"大牌檔是香港歷史的活生生檔案。"},{"en":"Living archives are places or practices that preserve history while still being used today.","zh":"活生生的歷史檔案，是仍在今天被使用、同時保存歷史的地方或做法。"},{"en":"An old market is a living archive when families still shop there and tell stories about it.","zh":"當家庭仍在舊街市買菜並講述相關故事，它就是活生生的歷史檔案。"},{"en":"Living archives are different from books because people can still experience them directly.","zh":"活生生的歷史檔案不同於書本，因為人們仍可直接體驗。"},{"en":"Dai pai dongs are living archives because history can be tasted, heard, and spoken there.","zh":"大牌檔是活生生的歷史檔案，因為歷史可以在那裏被品嚐、聽見和說出。"}],"source":"2016 Q5.pdf","sourcePage":4},{"front":"museum display","meaning":"博物館展品","examples":[{"en":"A dai pai dong is different from a museum display behind glass.","zh":"大牌檔不同於玻璃後面的博物館展品。"},{"en":"A museum display is an object or scene arranged for people to look at in a museum.","zh":"博物館展品，是在博物館中擺放給人觀看的物件或場景。"},{"en":"A bowl in a museum display can show history, but people cannot eat from it.","zh":"博物館展品中的碗可以展示歷史，但人們不能用它吃飯。"},{"en":"Museum displays preserve objects, while living culture lets people take part.","zh":"博物館展品保存物件，而活文化讓人參與其中。"},{"en":"Dai pai dongs matter because they are not only displays; they are working spaces.","zh":"大牌檔重要，因為它們不只是展品，而是仍在運作的空間。"}],"source":"2016 Q5.pdf","sourcePage":4},{"front":"behind glass","meaning":"玻璃後面","examples":[{"en":"Unlike a museum display behind glass, a street stall feels alive.","zh":"不像玻璃後面的博物館展品，街頭檔口感覺有生命力。"},{"en":"Behind glass means separated from people by a glass barrier, usually for protection or display.","zh":"玻璃後面，意思是被玻璃屏障與人隔開，通常是為保護或展示。"},{"en":"Old toys behind glass can be seen but not touched.","zh":"玻璃後面的舊玩具可以被看見，但不能被觸摸。"},{"en":"Culture behind glass may be safe, but it can feel distant from daily life.","zh":"玻璃後面的文化可能安全，但會感覺遠離日常生活。"},{"en":"Dai pai dongs should not exist only behind glass because their value is in use.","zh":"大牌檔不應只存在於玻璃後面，因為它們的價值在於被使用。"}],"source":"2016 Q5.pdf","sourcePage":4},{"front":"street stall","meaning":"街頭小食檔","examples":[{"en":"A street stall allows history to be tasted, heard and spoken.","zh":"街頭小食檔讓人品嚐、聽見和說出歷史。"},{"en":"A street stall is a small business that sells goods or food in a street or public area.","zh":"街頭小食檔，是在街道或公共地方售賣貨物或食物的小生意。"},{"en":"A street stall may sell noodles, fruit, snacks, or newspapers.","zh":"街頭小食檔可能售賣麵、水果、小食或報紙。"},{"en":"Street stalls make neighbourhoods lively because people can stop, talk, and buy quickly.","zh":"街頭檔口令社區熱鬧，因為人們可以停下、聊天和快速購買。"},{"en":"A dai pai dong is a street stall that carries both food and memory.","zh":"大牌檔是一種街頭小食檔，承載食物和記憶。"}],"source":"2016 Q5.pdf","sourcePage":4},{"front":"allow history to be tasted","meaning":"讓人品嚐歷史","examples":[{"en":"A street stall allows history to be tasted, heard and spoken.","zh":"街頭小食檔讓人品嚐、聽見和說出歷史。"},{"en":"To allow history to be tasted means to let people experience the past through food.","zh":"讓人品嚐歷史，意思是讓人透過食物體驗過去。"},{"en":"A traditional recipe allows family history to be tasted at dinner.","zh":"傳統食譜讓人在晚餐中品嚐家庭歷史。"},{"en":"Food allows history to be tasted when old cooking methods are still used.","zh":"當舊烹調方法仍被使用，食物就讓人品嚐歷史。"},{"en":"Dai pai dongs allow history to be tasted because old flavours remain part of daily life.","zh":"大牌檔讓人品嚐歷史，因為舊味道仍是日常生活的一部分。"}],"source":"2016 Q5.pdf","sourcePage":4},{"front":"wok-fried beef noodles","meaning":"鑊炒牛肉麵","examples":[{"en":"A plate of wok-fried beef noodles carries memories of earlier generations.","zh":"一碟鑊炒牛肉麵承載上一代人的記憶。"},{"en":"Wok-fried beef noodles are noodles and beef cooked quickly in a hot wok.","zh":"鑊炒牛肉麵，是用熱鑊快速炒成的牛肉和麵。"},{"en":"Wok-fried beef noodles often smell smoky because the wok is very hot.","zh":"鑊炒牛肉麵通常有煙火香，因為鑊非常熱。"},{"en":"Simple dishes like wok-fried beef noodles can remind people of family meals and street stalls.","zh":"像鑊炒牛肉麵這樣的簡單菜式，可以令人想起家庭飯餐和街頭檔口。"},{"en":"In a dai pai dong, wok-fried beef noodles are not fancy, but they feel honest and local.","zh":"在大牌檔，鑊炒牛肉麵不華麗，但感覺實在而本地。"}],"source":"2016 Q5.pdf","sourcePage":4},{"front":"earlier generations","meaning":"上一代人","examples":[{"en":"Earlier generations turned cheap ingredients into comfort.","zh":"上一代人把廉價食材變成安慰。"},{"en":"Earlier generations means people who lived before the present generation.","zh":"上一代人，是在現今世代之前生活的人。"},{"en":"Earlier generations often saved money by repairing things instead of replacing them.","zh":"上一代人常透過修理東西而不是更換來節省金錢。"},{"en":"We understand a city better when we learn how earlier generations lived and worked.","zh":"當我們了解上一代人如何生活和工作，就更理解一座城市。"},{"en":"Dai pai dongs show how earlier generations built comfort from limited resources.","zh":"大牌檔顯示上一代人如何用有限資源建立安慰。"}],"source":"2016 Q5.pdf","sourcePage":4},{"front":"cheap ingredients","meaning":"廉價食材","examples":[{"en":"Earlier generations turned cheap ingredients into comforting meals.","zh":"上一代人把廉價食材變成令人安慰的飯餐。"},{"en":"Cheap ingredients are low-cost foods used to cook meals.","zh":"廉價食材，是用來煮飯的低成本食物。"},{"en":"Rice, noodles, eggs, and vegetables can be cheap ingredients for a simple dinner.","zh":"米、麵、雞蛋和蔬菜可以是一頓簡單晚餐的廉價食材。"},{"en":"Skilled cooks can turn cheap ingredients into food that feels rich and satisfying.","zh":"有技巧的廚師可以把廉價食材變成豐富而令人滿足的食物。"},{"en":"Dai pai dongs prove that cheap ingredients can still carry warmth and memory.","zh":"大牌檔證明廉價食材仍可以承載溫暖和記憶。"}],"source":"2016 Q5.pdf","sourcePage":5},{"front":"turn… into comfort","meaning":"將……變成安慰","examples":[{"en":"Earlier generations turned cheap ingredients into comfort.","zh":"上一代人將廉價食材變成安慰。"},{"en":"To turn something into comfort means to change something simple into something that makes people feel safe or cared for.","zh":"將某物變成安慰，意思是把簡單事物變成令人感到安全或被照顧的東西。"},{"en":"A bowl of soup can turn a cold evening into comfort.","zh":"一碗湯可以將寒冷晚上變成安慰。"},{"en":"Families turn limited food into comfort when they cook with care.","zh":"當家庭用心煮食，他們可以將有限食物變成安慰。"},{"en":"Dai pai dong cooks turned cheap ingredients into comfort for tired workers.","zh":"大牌檔廚師將廉價食材變成疲倦工人的安慰。"}],"source":"2016 Q5.pdf","sourcePage":5},{"front":"battered folding table","meaning":"殘舊摺枱","examples":[{"en":"A battered folding table can show years of hard work.","zh":"一張殘舊摺枱可以顯示多年的辛勞。"},{"en":"A battered folding table is an old, worn table that can be folded and has marks from long use.","zh":"殘舊摺枱，是可以摺起、因長期使用而有痕跡的舊桌子。"},{"en":"A battered folding table in a market may carry scratches, stains, and stories.","zh":"街市中的殘舊摺枱可能承載刮痕、污漬和故事。"},{"en":"Such a table may look poor, but it shows how often people have gathered around it.","zh":"這樣的桌子可能看起來破舊，但顯示人們多常圍坐其旁。"},{"en":"At a dai pai dong, a battered folding table can hold more memory than new furniture.","zh":"在大牌檔，一張殘舊摺枱可能比新家具承載更多記憶。"}],"source":"2016 Q5.pdf","sourcePage":5},{"front":"folding table","meaning":"摺枱","examples":[{"en":"A folding table may carry years of neighbourhood memories.","zh":"一張摺枱可能承載多年的街坊記憶。"},{"en":"A folding table is a table that can be folded and moved easily.","zh":"摺枱，是可以摺起並容易移動的桌子。"},{"en":"Families use folding tables when there is not enough space at home.","zh":"家中空間不足時，家庭會使用摺枱。"},{"en":"Folding tables are practical because they can appear when needed and disappear afterwards.","zh":"摺枱很實用，因為需要時可以拿出來，用完後可以收起。"},{"en":"In a dai pai dong, folding tables turn a pavement into a shared dining room.","zh":"在大牌檔，摺枱把行人路變成共享飯廳。"}],"source":"2016 Q5.pdf","sourcePage":5},{"front":"build livelihoods","meaning":"維持生計","examples":[{"en":"Families built livelihoods with limited space.","zh":"家庭用有限空間維持生計。"},{"en":"To build livelihoods means to create ways to earn a living and support a family.","zh":"維持生計，意思是創造賺錢生活和支持家庭的方法。"},{"en":"A small shop owner builds a livelihood by serving regular customers every day.","zh":"小店店主每天服務熟客來維持生計。"},{"en":"People build livelihoods through skill, hard work, and whatever space they can find.","zh":"人們透過技巧、努力和可找到的空間維持生計。"},{"en":"Dai pai dongs show how families built livelihoods from small stalls and long hours.","zh":"大牌檔顯示家庭如何靠小檔口和長工時維持生計。"}],"source":"2016 Q5.pdf","sourcePage":5},{"front":"limited space","meaning":"有限空間","examples":[{"en":"Many families built livelihoods with limited space.","zh":"許多家庭用有限空間維持生計。"},{"en":"Limited space means there is not much room available.","zh":"有限空間，意思是可用地方不多。"},{"en":"Students in a small flat may study with limited space at the dinner table.","zh":"住在小單位的學生可能在飯桌上用有限空間溫習。"},{"en":"Limited space forces people to use every corner carefully.","zh":"有限空間迫使人們小心使用每個角落。"},{"en":"Dai pai dong families worked creatively because they had limited space but great determination.","zh":"大牌檔家庭因空間有限但決心很大，所以創意地工作。"}],"source":"2016 Q5.pdf","sourcePage":5},{"front":"few, if any","meaning":"即使有，也少之又少","examples":[{"en":"Few, if any, chain restaurants can carry this density of memory.","zh":"即使有，也少之又少連鎖餐廳能承載如此濃厚的記憶。"},{"en":"Few, if any, means almost none, and possibly none at all.","zh":"即使有，也少之又少，意思是幾乎沒有，甚至可能完全沒有。"},{"en":"Few, if any, students can do well without regular practice.","zh":"即使有，也少之又少學生能在沒有恆常練習下表現良好。"},{"en":"This phrase makes a strong comparison without sounding completely absolute.","zh":"這個短語作出強烈比較，但不顯得完全絕對。"},{"en":"Few, if any, modern restaurants carry the same street memories as old dai pai dongs.","zh":"即使有，也少之又少現代餐廳能承載像舊大牌檔一樣的街頭記憶。"}],"source":"2016 Q5.pdf","sourcePage":5},{"front":"carry this density of memory","meaning":"承載如此濃厚的記憶","examples":[{"en":"Chain restaurants cannot carry this density of memory.","zh":"連鎖餐廳不能承載如此濃厚的記憶。"},{"en":"To carry this density of memory means to hold many layers of shared experience and history.","zh":"承載如此濃厚的記憶，意思是保存許多層共同經驗和歷史。"},{"en":"An old school hall may carry a density of memory from assemblies, exams, and concerts.","zh":"舊學校禮堂可能因早會、考試和音樂會而承載濃厚記憶。"},{"en":"New buildings may look clean but not yet carry deep memory.","zh":"新建築可能乾淨，但未必已承載深厚記憶。"},{"en":"Dai pai dongs carry this density of memory because many lives have passed through them.","zh":"大牌檔承載如此濃厚的記憶，因為許多人生曾經過其中。"}],"source":"2016 Q5.pdf","sourcePage":5},{"front":"density of memory","meaning":"濃厚的記憶","examples":[{"en":"Old street stalls carry a density of memory.","zh":"舊街頭檔口承載濃厚的記憶。"},{"en":"Density of memory means a strong concentration of stories, feelings, and past experiences.","zh":"濃厚的記憶，意思是故事、感情和過去經驗高度集中。"},{"en":"A family photo album has a density of memory because each page recalls a different time.","zh":"家庭相簿有濃厚的記憶，因為每一頁都喚起不同時光。"},{"en":"Old places often have a density of memory that new places cannot copy quickly.","zh":"舊地方常有新地方不能快速複製的濃厚記憶。"},{"en":"Dai pai dongs have a density of memory built from years of ordinary meals.","zh":"大牌檔有由多年普通飯餐累積而成的濃厚記憶。"}],"source":"2016 Q5.pdf","sourcePage":5},{"front":"take… for example","meaning":"以……為例","examples":[{"en":"Take an old stall in Sham Shui Po, for example.","zh":"以深水埗一個老檔口為例。"},{"en":"Take… for example is used to introduce a specific case that supports a point.","zh":"以……為例，用來引入支持某個觀點的具體例子。"},{"en":"Take a crowded school canteen, for example; it shows why clear rules matter.","zh":"以擠迫的學校飯堂為例，它顯示清晰規則為何重要。"},{"en":"Writers use this phrase to move from a general idea to a concrete example.","zh":"作者使用這個短語，由一般想法轉向具體例子。"},{"en":"Take an old dai pai dong, for example, and you can see history in daily use.","zh":"以一個舊大牌檔為例，你可以看見日常使用中的歷史。"}],"source":"2016 Q5.pdf","sourcePage":5},{"front":"old stall","meaning":"老檔口","examples":[{"en":"An old stall in Sham Shui Po may not look elegant.","zh":"深水埗一個老檔口可能看起來不優雅。"},{"en":"An old stall is a small, long-used selling place, often with signs of age.","zh":"老檔口，是長期使用的小型售賣地方，通常有歲月痕跡。"},{"en":"An old stall may have faded signs, worn tables, and regular customers.","zh":"老檔口可能有褪色招牌、磨損桌子和熟客。"},{"en":"Old stalls can look simple but still serve important community needs.","zh":"老檔口可以看起來簡單，但仍服務重要社區需要。"},{"en":"An old stall may hold more local memory than a newly decorated restaurant.","zh":"老檔口可能比新裝修餐廳承載更多本地記憶。"}],"source":"2016 Q5.pdf","sourcePage":6},{"front":"Sham Shui Po","meaning":"深水埗","examples":[{"en":"Sham Shui Po still has traces of old street culture.","zh":"深水埗仍有舊街頭文化的痕跡。"},{"en":"Sham Shui Po is a Hong Kong district often associated with markets, working-class life, and older streets.","zh":"深水埗是香港一個地區，常與街市、基層生活和舊街道相關。"},{"en":"People visit Sham Shui Po for fabric shops, electronics, food, and neighbourhood atmosphere.","zh":"人們到深水埗尋找布店、電子產品、食物和社區氣氛。"},{"en":"A district like Sham Shui Po can show how daily life changes over time.","zh":"像深水埗這樣的地區，可以展示日常生活如何隨時間改變。"},{"en":"Old stalls in Sham Shui Po help people imagine Hong Kong’s earlier street life.","zh":"深水埗的老檔口幫助人們想像香港早期街頭生活。"}],"source":"2016 Q5.pdf","sourcePage":6},{"front":"plastic stools","meaning":"膠凳","examples":[{"en":"The plastic stools may not look elegant.","zh":"這些膠凳可能看起來不優雅。"},{"en":"Plastic stools are small seats made of plastic, often used in casual food stalls.","zh":"膠凳，是由塑膠製成的小座椅，常用於隨意食檔。"},{"en":"Plastic stools are light, cheap, and easy to move.","zh":"膠凳輕便、便宜，而且容易移動。"},{"en":"Customers sitting on plastic stools may feel closer to the street than in a formal restaurant.","zh":"坐在膠凳上的顧客，可能比在正式餐廳中更接近街道。"},{"en":"At dai pai dongs, plastic stools are part of the honest and practical atmosphere.","zh":"在大牌檔，膠凳是實在而實用氣氛的一部分。"}],"source":"2016 Q5.pdf","sourcePage":6},{"front":"look elegant","meaning":"看起來優雅","examples":[{"en":"The plastic stools may not look elegant, but they carry memory.","zh":"這些膠凳可能看起來不優雅，但它們承載記憶。"},{"en":"To look elegant means to appear graceful, stylish, or refined.","zh":"看起來優雅，意思是外表顯得優美、有格調或精緻。"},{"en":"A school hall may not look elegant, but it can still hold important memories.","zh":"學校禮堂可能看起來不優雅，但仍能保存重要記憶。"},{"en":"Something does not need to look elegant to be useful or meaningful.","zh":"某物不需要看起來優雅，才有用或有意義。"},{"en":"Dai pai dong furniture may not look elegant, but it feels honest and familiar.","zh":"大牌檔家具可能看起來不優雅，但感覺實在而熟悉。"}],"source":"2016 Q5.pdf","sourcePage":6},{"front":"every scratch on them","meaning":"上面的每一道刮痕","examples":[{"en":"Every scratch on the stools suggests years of use.","zh":"凳子上面的每一道刮痕都顯示多年使用。"},{"en":"Every scratch on them means each small mark left on those objects.","zh":"上面的每一道刮痕，意思是那些物件上留下的每一個小痕跡。"},{"en":"Every scratch on an old desk may remind students of past school years.","zh":"舊書桌上面的每一道刮痕可能令人想起過去的校園歲月。"},{"en":"Scratches show that objects have been touched, moved, and used by many people.","zh":"刮痕顯示物件曾被許多人觸碰、移動和使用。"},{"en":"Every scratch on dai pai dong stools can feel like a small record of public life.","zh":"大牌檔膠凳上面的每一道刮痕，都可以像公共生活的小紀錄。"}],"source":"2016 Q5.pdf","sourcePage":6},{"front":"suggest years of","meaning":"顯示多年……","examples":[{"en":"Every scratch suggests years of customers sitting there.","zh":"每一道刮痕都顯示多年顧客曾坐在那裏。"},{"en":"Suggest years of means shows signs that something has happened for a long time.","zh":"顯示多年……，意思是留下跡象，表明某事已長時間發生。"},{"en":"The worn steps suggest years of students walking into the school.","zh":"磨損的樓梯顯示多年學生走進學校。"},{"en":"Old marks suggest years of use even when no one tells the story aloud.","zh":"即使沒有人說出故事，舊痕跡也能顯示多年使用。"},{"en":"The scratches on dai pai dong tables suggest years of shared meals.","zh":"大牌檔桌上的刮痕顯示多年共享飯餐。"}],"source":"2016 Q5.pdf","sourcePage":6},{"front":"office workers","meaning":"上班族","examples":[{"en":"Office workers sat down for the same honest meal.","zh":"上班族坐下來吃同一份實在的一餐。"},{"en":"Office workers are people who work in offices, often using computers, documents, and meetings.","zh":"上班族，是在辦公室工作的人，通常使用電腦、文件和會議。"},{"en":"Office workers may eat quickly at a dai pai dong during lunch break.","zh":"上班族可能在午飯時間快速到大牌檔吃飯。"},{"en":"After a long day, office workers may want simple hot food more than a formal restaurant.","zh":"漫長一天後，上班族可能比起正式餐廳更想要簡單熱食。"},{"en":"Dai pai dongs bring office workers together with people from many other walks of life.","zh":"大牌檔把上班族和來自不同生活背景的人聚在一起。"}],"source":"2016 Q5.pdf","sourcePage":6},{"front":"taxi drivers","meaning":"的士司機","examples":[{"en":"Taxi drivers often ate at old dai pai dongs.","zh":"的士司機常在舊大牌檔吃飯。"},{"en":"Taxi drivers are people whose job is to drive passengers for payment.","zh":"的士司機，是以駕車接載乘客收費為工作的人。"},{"en":"Taxi drivers may stop at a street stall for a quick meal between shifts.","zh":"的士司機可能在更次之間停在街頭食檔吃一頓快餐。"},{"en":"Old food stalls support taxi drivers because they offer fast, filling meals.","zh":"舊食檔支持的士司機，因為它們提供快捷而飽肚的飯餐。"},{"en":"Dai pai dongs served people like taxi drivers who worked long hours across the city.","zh":"大牌檔服務像的士司機這樣在城市中長時間工作的人。"}],"source":"2016 Q5.pdf","sourcePage":6},{"front":"elderly neighbours","meaning":"年長街坊","examples":[{"en":"Elderly neighbours shared the same honest meal.","zh":"年長街坊共享同一份實在的一餐。"},{"en":"Elderly neighbours are older people living nearby in the same community.","zh":"年長街坊，是住在同一社區附近的年長人士。"},{"en":"Elderly neighbours may know which stall has served the area for decades.","zh":"年長街坊可能知道哪個檔口已服務區內數十年。"},{"en":"Eating with elderly neighbours can make young people learn local stories.","zh":"與年長街坊一起吃飯，可以讓年輕人聽到本地故事。"},{"en":"Dai pai dongs allow elderly neighbours to remain visible in community life.","zh":"大牌檔讓年長街坊繼續在社區生活中被看見。"}],"source":"2016 Q5.pdf","sourcePage":6},{"front":"sit down for","meaning":"坐下來吃","examples":[{"en":"Customers sat down for the same honest meal.","zh":"顧客坐下來吃同一份實在的一餐。"},{"en":"To sit down for a meal means to stop and eat, usually at a table.","zh":"坐下來吃一餐，意思是停下來，通常在桌旁用餐。"},{"en":"A family may sit down for dinner after a busy day.","zh":"忙碌一天後，一家人可能坐下來吃晚飯。"},{"en":"Sitting down for food gives people time to rest and talk.","zh":"坐下來吃飯給人時間休息和交談。"},{"en":"At dai pai dongs, strangers sit down for meals beside one another.","zh":"在大牌檔，陌生人坐下來在彼此旁邊吃飯。"}],"source":"2016 Q5.pdf","sourcePage":6},{"front":"honest meal","meaning":"實在的一餐","examples":[{"en":"Dai pai dongs serve honest meals to ordinary people.","zh":"大牌檔為普通人供應實在的一餐。"},{"en":"An honest meal is simple, filling, fairly priced, and not pretending to be fancy.","zh":"實在的一餐，是簡單、飽肚、價錢合理，而且不假裝高級的飯餐。"},{"en":"A bowl of hot rice and vegetables can be an honest meal after work.","zh":"下班後一碗熱飯和蔬菜可以是實在的一餐。"},{"en":"Honest meals comfort people because they meet real needs.","zh":"實在的一餐令人安慰，因為它滿足真實需要。"},{"en":"Dai pai dongs are loved because they provide honest meals with local flavour.","zh":"大牌檔受人喜愛，因為它們提供有本地味道的實在飯餐。"}],"source":"2016 Q5.pdf","sourcePage":7},{"front":"what matters is not…, but…","meaning":"重要的不是……而是……","examples":[{"en":"What matters is not decoration, but continuity.","zh":"重要的不是裝飾，而是延續性。"},{"en":"What matters is not A, but B means B is the truly important thing, not A.","zh":"重要的不是 A，而是 B，意思是 B 才是真正重要的事情，而不是 A。"},{"en":"What matters is not expensive equipment, but regular practice.","zh":"重要的不是昂貴設備，而是恆常練習。"},{"en":"This structure helps writers correct what people may focus on too much.","zh":"這個結構幫助作者糾正人們可能過度關注的事情。"},{"en":"For dai pai dongs, what matters is not polished design, but living memory.","zh":"對大牌檔來說，重要的不是亮麗設計，而是活著的記憶。"}],"source":"2016 Q5.pdf","sourcePage":7},{"front":"decoration","meaning":"裝飾","examples":[{"en":"What matters is not decoration, but continuity.","zh":"重要的不是裝飾，而是延續性。"},{"en":"Decoration means things added to make a place look nicer or more attractive.","zh":"裝飾，是加上去令地方看起來更好看或更吸引的東西。"},{"en":"A classroom can feel welcoming through care, not only decoration.","zh":"課室可以透過關心而不只是裝飾，令人感到受歡迎。"},{"en":"Decoration may improve appearance, but it cannot replace real meaning.","zh":"裝飾可以改善外觀，但不能取代真正意義。"},{"en":"Dai pai dongs do not need luxury decoration to carry cultural value.","zh":"大牌檔不需要豪華裝飾也能承載文化價值。"}],"source":"2016 Q5.pdf","sourcePage":7},{"front":"continuity","meaning":"延續性","examples":[{"en":"Dai pai dongs represent continuity in Hong Kong life.","zh":"大牌檔代表香港生活中的延續性。"},{"en":"Continuity means a connection between past, present, and future.","zh":"延續性，意思是過去、現在和未來之間的連繫。"},{"en":"A family recipe creates continuity when grandchildren cook it again.","zh":"當孫兒再次煮家庭食譜，它就創造延續性。"},{"en":"Continuity helps people feel that change has not erased everything familiar.","zh":"延續性幫助人們感到改變沒有抹去所有熟悉事物。"},{"en":"Dai pai dongs offer continuity because older habits still live in today’s city.","zh":"大牌檔提供延續性，因為舊習慣仍活在今天的城市中。"}],"source":"2016 Q5.pdf","sourcePage":7},{"front":"if these stalls vanish","meaning":"如果這些檔口消失","examples":[{"en":"If these stalls vanish, Hong Kong will lose more than food.","zh":"如果這些檔口消失，香港失去的不只是食物。"},{"en":"If these stalls vanish means if these food places disappear completely.","zh":"如果這些檔口消失，意思是如果這些食肆完全不見。"},{"en":"If old bookshops vanish, students may lose places to discover local stories.","zh":"如果舊書店消失，學生可能失去發現本地故事的地方。"},{"en":"When cultural places vanish, people lose experiences, not only buildings.","zh":"當文化地方消失，人們失去的是經驗，不只是建築物。"},{"en":"If dai pai dongs vanish, Hong Kong will lose sound, memory, and human warmth.","zh":"如果大牌檔消失，香港會失去聲音、記憶和人情味。"}],"source":"2016 Q5.pdf","sourcePage":7},{"front":"the loss will not be limited to","meaning":"損失不會限於","examples":[{"en":"The loss will not be limited to food.","zh":"損失不會限於食物。"},{"en":"The loss will not be limited to something means the damage will go beyond that one area.","zh":"損失不會限於某事，意思是傷害會超出那一個範圍。"},{"en":"If a school library closes, the loss will not be limited to books.","zh":"如果學校圖書館關閉，損失不會限於書本。"},{"en":"Losing a neighbourhood market may also mean losing relationships and routines.","zh":"失去社區街市也可能意味著失去關係和生活習慣。"},{"en":"If dai pai dongs disappear, the loss will not be limited to meals.","zh":"如果大牌檔消失，損失不會限於飯餐。"}],"source":"2016 Q5.pdf","sourcePage":7},{"front":"lose the language of hawkers","meaning":"失去小販的語言","examples":[{"en":"Hong Kong may lose the language of hawkers.","zh":"香港可能失去小販的語言。"},{"en":"To lose the language of hawkers means to lose the special words, calls, tones, and expressions used by street sellers.","zh":"失去小販的語言，意思是失去街頭小販使用的特別詞語、叫賣聲、語調和表達方式。"},{"en":"A market loses the language of hawkers when shouting voices are replaced by silent screens.","zh":"當叫賣聲被沉默的螢幕取代，街市就失去小販的語言。"},{"en":"This language matters because it carries humour, speed, and local identity.","zh":"這種語言重要，因為它承載幽默、速度和本地身份。"},{"en":"Dai pai dongs help keep the language of hawkers alive in daily life.","zh":"大牌檔幫助小販的語言在日常生活中保持活力。"}],"source":"2016 Q5.pdf","sourcePage":7},{"front":"hawkers","meaning":"小販","examples":[{"en":"The language of hawkers is part of Hong Kong culture.","zh":"小販的語言是香港文化的一部分。"},{"en":"Hawkers are people who sell food or goods in streets or public places.","zh":"小販，是在街道或公共地方售賣食物或貨品的人。"},{"en":"Hawkers may call out prices, recommend dishes, and speak quickly to customers.","zh":"小販可能叫賣價格、推薦菜式，並快速與顧客說話。"},{"en":"Hawkers are part of street culture because they make public spaces lively.","zh":"小販是街頭文化的一部分，因為他們令公共空間熱鬧。"},{"en":"Dai pai dongs grew from the labour and voices of hawkers.","zh":"大牌檔源自小販的勞動和聲音。"}],"source":"2016 Q5.pdf","sourcePage":7},{"front":"rhythm of Cantonese orders","meaning":"廣東話落單的節奏","examples":[{"en":"Dai pai dongs preserve the rhythm of Cantonese orders.","zh":"大牌檔保存廣東話落單的節奏。"},{"en":"The rhythm of Cantonese orders means the fast, familiar sound of people ordering food in Cantonese.","zh":"廣東話落單的節奏，是人們用廣東話點餐時快速而熟悉的聲音。"},{"en":"A busy tea restaurant has its own rhythm of Cantonese orders at lunchtime.","zh":"繁忙茶餐廳在午飯時間有自己的廣東話落單節奏。"},{"en":"This rhythm carries local humour, speed, and everyday identity.","zh":"這種節奏承載本地幽默、速度和日常身份。"},{"en":"Dai pai dongs preserve this rhythm because customers and cooks speak directly.","zh":"大牌檔保存這種節奏，因為顧客和廚師直接說話。"}],"source":"2016 Q5.pdf","sourcePage":7},{"front":"evidence that","meaning":"……的證據","examples":[{"en":"Dai pai dongs are evidence that Hong Kong was built by ordinary workers.","zh":"大牌檔是香港由普通工人建立的證據。"},{"en":"Evidence that means proof or signs showing something is true.","zh":"……的證據，意思是顯示某事真實的證明或跡象。"},{"en":"Old factory buildings are evidence that many families once worked in manufacturing.","zh":"舊工廠大廈是許多家庭曾在製造業工作的證據。"},{"en":"Daily objects can be evidence that history was made by ordinary people.","zh":"日常物件可以證明歷史由普通人創造。"},{"en":"Dai pai dongs are evidence that food labour helped build Hong Kong.","zh":"大牌檔是飲食勞動幫助建立香港的證據。"}],"source":"2016 Q5.pdf","sourcePage":7},{"front":"not only by…, but also by…","meaning":"不只是由……也是由……","examples":[{"en":"Hong Kong was built not only by bankers, but also by stove-side workers.","zh":"香港不只是由銀行家建立，也是由在熱爐旁工作的人建立。"},{"en":"Not only by…, but also by… shows that two groups contributed, not just the obvious one.","zh":"不只是由……也是由……，顯示兩個群體都有貢獻，不只是明顯的一方。"},{"en":"A school is built not only by principals, but also by cleaners and office staff.","zh":"學校不只是由校長建立，也是由清潔工和辦公室職員支持。"},{"en":"This structure gives credit to people who may be forgotten.","zh":"這個結構把功勞給予可能被遺忘的人。"},{"en":"Hong Kong’s food culture was built not only by famous chefs, but also by hawkers.","zh":"香港飲食文化不只是由名廚建立，也是由小販建立。"}],"source":"2016 Q5.pdf","sourcePage":8},{"front":"bankers and developers","meaning":"銀行家和發展商","examples":[{"en":"The city was not built only by bankers and developers.","zh":"這座城市不只是由銀行家和發展商建立。"},{"en":"Bankers and developers are people who work in finance and property development.","zh":"銀行家和發展商，是從事金融和地產發展的人。"},{"en":"Bankers and developers may shape a city’s skyline through money and buildings.","zh":"銀行家和發展商可能透過金錢和建築塑造城市天際線。"},{"en":"A city also depends on cooks, cleaners, drivers, and other ordinary workers.","zh":"一座城市也依靠廚師、清潔工、司機和其他普通工人。"},{"en":"The phrase reminds us that Hong Kong’s story is wider than wealth and property.","zh":"這個短語提醒我們，香港故事比財富和地產更廣闊。"}],"source":"2016 Q5.pdf","sourcePage":8},{"front":"people who worked beside hot stoves","meaning":"在熱爐旁工作的人","examples":[{"en":"Hong Kong was also built by people who worked beside hot stoves.","zh":"香港也是由在熱爐旁工作的人建立的。"},{"en":"People who worked beside hot stoves are cooks and food workers who spent long hours in heat.","zh":"在熱爐旁工作的人，是長時間在高溫中工作的廚師和飲食工人。"},{"en":"Street cooks worked beside hot stoves so office workers and drivers could eat.","zh":"街頭廚師在熱爐旁工作，好讓上班族和司機有飯吃。"},{"en":"Their labour matters because daily meals support daily work.","zh":"他們的勞動重要，因為日常飯餐支持日常工作。"},{"en":"Dai pai dongs honour people who worked beside hot stoves for the city.","zh":"大牌檔向為城市在熱爐旁工作的人致敬。"}],"source":"2016 Q5.pdf","sourcePage":8},{"front":"late into the night","meaning":"直到深夜","examples":[{"en":"Many hawkers worked late into the night.","zh":"許多小販工作直到深夜。"},{"en":"Late into the night means until very late at night.","zh":"直到深夜，意思是一直到很晚的夜間。"},{"en":"Students may study late into the night before a difficult exam.","zh":"學生可能在困難考試前溫習直到深夜。"},{"en":"Working late into the night can be tiring, especially in a hot kitchen.","zh":"工作直到深夜會令人疲倦，特別是在炎熱廚房中。"},{"en":"Dai pai dong workers often served customers late into the night after the city’s offices closed.","zh":"大牌檔工人常在城市辦公室關門後仍服務顧客直到深夜。"}],"source":"2016 Q5.pdf","sourcePage":8},{"front":"act of cultural respect","meaning":"文化尊重的行動","examples":[{"en":"Preserving dai pai dongs is an act of cultural respect.","zh":"保育大牌檔是一種文化尊重的行動。"},{"en":"An act of cultural respect is something done to honour and protect a community’s heritage.","zh":"文化尊重的行動，是為尊重和保護社群文化遺產而做的事。"},{"en":"Recording elders’ stories can be an act of cultural respect.","zh":"記錄長者故事可以是文化尊重的行動。"},{"en":"Cultural respect means not treating old practices as useless simply because they are old.","zh":"文化尊重意味著不因舊做法古老就視之為無用。"},{"en":"Protecting dai pai dongs is an act of cultural respect toward working-class history.","zh":"保護大牌檔是對基層歷史的文化尊重行動。"}],"source":"2016 Q5.pdf","sourcePage":8},{"front":"equally important","meaning":"同樣重要的是","examples":[{"en":"Equally important, dai pai dongs preserve public intimacy.","zh":"同樣重要的是，大牌檔保存公共親密感。"},{"en":"Equally important introduces another point that is just as important as the previous one.","zh":"同樣重要的是，用來引入另一個與前一點同樣重要的內容。"},{"en":"Exercise is good for health; equally important, sleep helps the body recover.","zh":"運動對健康有好處；同樣重要的是，睡眠幫助身體恢復。"},{"en":"Writers use this phrase to show that a second reason deserves the same attention.","zh":"作者使用這個短語，顯示第二個理由值得同等關注。"},{"en":"Dai pai dongs matter for history; equally important, they connect people today.","zh":"大牌檔因歷史而重要；同樣重要的是，它們今天仍連結人群。"}],"source":"2016 Q5.pdf","sourcePage":8},{"front":"rare form of","meaning":"罕有形式的","examples":[{"en":"Dai pai dongs preserve a rare form of public intimacy.","zh":"大牌檔保存一種罕有形式的公共親密感。"},{"en":"A rare form of something means an unusual or not commonly found type of it.","zh":"罕有形式的某事，意思是某事物不常見或不容易找到的類型。"},{"en":"Handwritten letters are now a rare form of personal communication.","zh":"手寫信現在是罕有形式的個人溝通。"},{"en":"Rare forms of community life should be noticed before they disappear.","zh":"罕有形式的社區生活應在消失前被注意。"},{"en":"Dai pai dongs offer a rare form of closeness between strangers in public.","zh":"大牌檔提供一種陌生人在公共空間中產生親近感的罕有形式。"}],"source":"2016 Q5.pdf","sourcePage":8},{"front":"public intimacy","meaning":"公共親密感","examples":[{"en":"Dai pai dongs preserve public intimacy in a private city.","zh":"大牌檔在私人化城市中保存公共親密感。"},{"en":"Public intimacy means warmth, closeness, and small human connections in shared public spaces.","zh":"公共親密感，是共享公共空間中的溫暖、親近和小小人際連繫。"},{"en":"Neighbours chatting at a market show public intimacy.","zh":"街坊在街市聊天，就是公共親密感的表現。"},{"en":"Public intimacy disappears when people share space but never speak to one another.","zh":"當人們共享空間卻從不交談，公共親密感就會消失。"},{"en":"Dai pai dongs create public intimacy by making strangers sit close and talk naturally.","zh":"大牌檔透過讓陌生人坐得近並自然交談，創造公共親密感。"}],"source":"2016 Q5.pdf","sourcePage":8},{"front":"increasingly private city","meaning":"越來越私人化的城市","examples":[{"en":"Hong Kong is becoming an increasingly private city.","zh":"香港正變成一個越來越私人化的城市。"},{"en":"An increasingly private city is a city where people spend more time in separated, controlled, or personal spaces.","zh":"越來越私人化的城市，是人們更多時間處於分隔、受控制或個人空間的城市。"},{"en":"When people order through apps and eat alone, the city can feel increasingly private.","zh":"當人們透過應用程式落單並獨自進食，城市會感覺越來越私人化。"},{"en":"An increasingly private city may become efficient but less warm.","zh":"越來越私人化的城市可能高效率，但較少溫暖。"},{"en":"Dai pai dongs resist this trend by keeping eating public and social.","zh":"大牌檔透過保留公共和社交的用餐方式，抵抗這種趨勢。"}],"source":"2016 Q5.pdf","sourcePage":8},{"front":"efficient","meaning":"高效率的","examples":[{"en":"Modern Hong Kong is efficient, but efficiency can reduce warmth.","zh":"現代香港高效率，但效率可能減少人情味。"},{"en":"Efficient means able to do things quickly with little waste of time or effort.","zh":"高效率的，意思是能快速完成事情，並少浪費時間或努力。"},{"en":"An efficient bus system helps people arrive at work on time.","zh":"高效率的巴士系統幫助人們準時上班。"},{"en":"Efficiency is useful, but it should not remove all human contact.","zh":"效率有用，但不應移走所有人與人的接觸。"},{"en":"Dai pai dongs may not be the most efficient places, but they give the city warmth.","zh":"大牌檔未必是最高效率的地方，但它們給城市溫暖。"}],"source":"2016 Q5.pdf","sourcePage":8},{"front":"come at the cost of","meaning":"以犧牲……為代價","examples":[{"en":"Efficiency often comes at the cost of warmth.","zh":"效率往往以犧牲人情味為代價。"},{"en":"To come at the cost of something means to be gained by losing or damaging it.","zh":"以犧牲某事為代價，意思是透過失去或損害它來取得某事。"},{"en":"High exam results should not come at the cost of students’ sleep.","zh":"高考試成績不應以犧牲學生睡眠為代價。"},{"en":"A city’s speed comes at too high a cost if people stop noticing one another.","zh":"如果人們停止注意彼此，城市速度付出的代價就太高。"},{"en":"Development should not come at the cost of dai pai dongs and street culture.","zh":"發展不應以犧牲大牌檔和街頭文化為代價。"}],"source":"2016 Q5.pdf","sourcePage":9},{"front":"warmth","meaning":"人情味；溫暖","examples":[{"en":"Efficiency often comes at the cost of warmth.","zh":"效率往往以犧牲人情味為代價。"},{"en":"Warmth means friendliness, kindness, and human feeling.","zh":"人情味或溫暖，意思是友善、善意和人的情感。"},{"en":"A shopkeeper shows warmth when they remember a regular customer’s usual order.","zh":"店主記得熟客平常點甚麼，就是展現人情味。"},{"en":"A place without warmth may work smoothly but feel lonely.","zh":"沒有溫暖的地方可能運作順暢，但感覺孤單。"},{"en":"Dai pai dongs keep warmth alive through shared tables and familiar voices.","zh":"大牌檔透過搭枱和熟悉人聲，讓人情味保持活力。"}],"source":"2016 Q5.pdf","sourcePage":9},{"front":"order through screens","meaning":"透過螢幕落單","examples":[{"en":"Many people now order through screens.","zh":"很多人現在透過螢幕落單。"},{"en":"To order through screens means to choose and pay for food using phones, tablets, or machines.","zh":"透過螢幕落單，意思是使用手機、平板或機器選擇並付款購買食物。"},{"en":"Students may order lunch through screens without speaking to staff.","zh":"學生可能透過螢幕訂午餐，而不用與職員說話。"},{"en":"Ordering through screens is convenient, but it can reduce conversation.","zh":"透過螢幕落單很方便，但可能減少交談。"},{"en":"Dai pai dongs feel different because customers often order through human voices.","zh":"大牌檔感覺不同，因為顧客常透過人聲落單。"}],"source":"2016 Q5.pdf","sourcePage":9},{"front":"eat in silence","meaning":"默默進食","examples":[{"en":"Many customers eat in silence and leave quickly.","zh":"許多顧客默默進食，然後快速離開。"},{"en":"To eat in silence means to eat without talking.","zh":"默默進食，意思是不說話地吃飯。"},{"en":"A tired worker may eat in silence after a long day.","zh":"疲倦的員工在漫長一天後可能默默進食。"},{"en":"Eating in silence can feel peaceful, but it can also make public life less social.","zh":"默默進食可以感覺平靜，但也可能令公共生活較不社交。"},{"en":"Dai pai dongs often break silence because people sit close and talk easily.","zh":"大牌檔常打破沉默，因為人們坐得近，也容易交談。"}],"source":"2016 Q5.pdf","sourcePage":9},{"front":"as soon as","meaning":"一……就……","examples":[{"en":"Customers often leave as soon as the bill is paid.","zh":"顧客常常一付完帳就離開。"},{"en":"As soon as means immediately after something happens.","zh":"一……就……，意思是某事發生後立即出現另一件事。"},{"en":"Students leave the classroom as soon as the bell rings.","zh":"學生一聽到鐘聲就離開課室。"},{"en":"If people leave as soon as they finish eating, there is little time for conversation.","zh":"如果人們一吃完就離開，就很少時間交談。"},{"en":"Dai pai dongs encourage some customers to stay and talk even after the bill is paid.","zh":"大牌檔鼓勵一些顧客即使付完帳後仍留下聊天。"}],"source":"2016 Q5.pdf","sourcePage":9},{"front":"bill is paid","meaning":"付完帳","examples":[{"en":"Some customers leave as soon as the bill is paid.","zh":"有些顧客付完帳就離開。"},{"en":"The bill is paid means the customer has paid the money owed for a meal or service.","zh":"付完帳，意思是顧客已支付用餐或服務所欠的款項。"},{"en":"After the bill is paid, a family may thank the waiter and leave.","zh":"付完帳後，一家人可能感謝侍應然後離開。"},{"en":"In fast restaurants, people often leave immediately after the bill is paid.","zh":"在快餐店，人們常在付完帳後立即離開。"},{"en":"At dai pai dongs, conversation may continue even after the bill is paid.","zh":"在大牌檔，付完帳後交談仍可能繼續。"}],"source":"2016 Q5.pdf","sourcePage":9},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"By contrast, a dai pai dong encourages conversation.","zh":"相比之下，大牌檔鼓勵交談。"},{"en":"By contrast is used to show a clear difference from the previous idea.","zh":"相比之下，用來顯示與前一個想法的清楚差異。"},{"en":"Some cafés feel silent; by contrast, markets feel noisy and social.","zh":"有些咖啡店感覺安靜；相比之下，街市感覺嘈雜而社交。"},{"en":"This phrase helps writers compare two different situations clearly.","zh":"這個短語幫助作者清楚比較兩種不同情況。"},{"en":"By contrast with screen ordering, dai pai dongs depend on voices and contact.","zh":"與透過螢幕落單相比，大牌檔依靠聲音和接觸。"}],"source":"2016 Q5.pdf","sourcePage":9},{"front":"encourage people to","meaning":"鼓勵人們去","examples":[{"en":"A dai pai dong encourages people to share tables.","zh":"大牌檔鼓勵人們去搭枱。"},{"en":"To encourage people to do something means to make them more willing to do it.","zh":"鼓勵人們去做某事，意思是令人更願意做那件事。"},{"en":"A teacher encourages students to speak by praising honest answers.","zh":"老師透過讚賞誠實答案，鼓勵學生發言。"},{"en":"Shared spaces encourage people to notice one another.","zh":"共享空間鼓勵人們注意彼此。"},{"en":"Dai pai dongs encourage people to talk because they sit close together.","zh":"大牌檔鼓勵人們交談，因為他們坐得很近。"}],"source":"2016 Q5.pdf","sourcePage":9},{"front":"share tables","meaning":"搭枱","examples":[{"en":"Dai pai dongs encourage people to share tables.","zh":"大牌檔鼓勵人們搭枱。"},{"en":"To share tables means to sit at the same table with other customers, sometimes strangers.","zh":"搭枱，意思是與其他顧客，有時是陌生人，坐在同一張桌子。"},{"en":"In a busy café, two students may share a table with an elderly neighbour.","zh":"在繁忙咖啡店，兩名學生可能與一位年長街坊搭枱。"},{"en":"Sharing tables can turn strangers into brief companions.","zh":"搭枱可以把陌生人變成短暫同伴。"},{"en":"Dai pai dongs preserve the habit of sharing tables in public life.","zh":"大牌檔保存公共生活中的搭枱習慣。"}],"source":"2016 Q5.pdf","sourcePage":9},{"front":"exchange glances","meaning":"交換眼神","examples":[{"en":"Strangers may exchange glances at a busy dai pai dong.","zh":"陌生人在繁忙大牌檔可能交換眼神。"},{"en":"To exchange glances means two people briefly look at each other.","zh":"交換眼神，意思是兩個人短暫互相望一望。"},{"en":"Passengers may exchange glances when a bus suddenly stops.","zh":"巴士突然停下時，乘客可能交換眼神。"},{"en":"Exchanging glances can show shared surprise, humour, or understanding without words.","zh":"交換眼神可以不用說話就顯示共同驚訝、幽默或理解。"},{"en":"At a crowded dai pai dong, strangers exchange glances when the cook jokes loudly.","zh":"在擠迫的大牌檔，廚師大聲說笑時，陌生人可能交換眼神。"}],"source":"2016 Q5.pdf","sourcePage":9},{"front":"complain about the weather","meaning":"抱怨天氣","examples":[{"en":"Customers may complain about the weather together.","zh":"顧客可能一起抱怨天氣。"},{"en":"To complain about the weather means to talk negatively about heat, rain, cold, or humidity.","zh":"抱怨天氣，意思是對炎熱、下雨、寒冷或潮濕作負面談論。"},{"en":"Neighbours often complain about the weather while waiting for the lift.","zh":"街坊等升降機時常抱怨天氣。"},{"en":"Small complaints about weather can start friendly conversations between strangers.","zh":"關於天氣的小抱怨可以展開陌生人之間的友善對話。"},{"en":"At dai pai dongs, complaining about the weather can become part of public intimacy.","zh":"在大牌檔，抱怨天氣可以成為公共親密感的一部分。"}],"source":"2016 Q5.pdf","sourcePage":10},{"front":"affectionate remarks","meaning":"親切的說話","examples":[{"en":"Customers may laugh at the cook’s affectionate remarks.","zh":"顧客可能因廚師親切的說話而大笑。"},{"en":"Affectionate remarks are warm, friendly comments that show fondness or care.","zh":"親切的說話，是顯示喜愛或關心的溫暖友善言語。"},{"en":"A grandmother’s affectionate remarks can make children feel loved.","zh":"祖母親切的說話可以令孩子感到被愛。"},{"en":"In local food stalls, affectionate remarks may sound direct but carry kindness.","zh":"在本地食檔，親切的說話可能聽起來直接，但帶有善意。"},{"en":"Dai pai dong cooks often use affectionate remarks to make regulars feel at home.","zh":"大牌檔廚師常用親切的說話令熟客感到像回家一樣。"}],"source":"2016 Q5.pdf","sourcePage":10},{"front":"fill your stomach","meaning":"填飽肚子","examples":[{"en":"You do not just go there to fill your stomach.","zh":"你去那裏不只是為了填飽肚子。"},{"en":"To fill your stomach means to eat enough food so you are no longer hungry.","zh":"填飽肚子，意思是吃足夠食物，使自己不再肚餓。"},{"en":"A bowl of noodles can fill your stomach after a long school day.","zh":"一碗麵可以在漫長上學日後填飽肚子。"},{"en":"Meals can fill the stomach, but shared meals can also fill emotional needs.","zh":"飯餐可以填飽肚子，但共享飯餐也可以滿足情感需要。"},{"en":"Dai pai dongs do more than fill your stomach; they give warmth and company.","zh":"大牌檔不只是填飽肚子；它們也給人溫暖和陪伴。"}],"source":"2016 Q5.pdf","sourcePage":10},{"front":"human pulse","meaning":"人情脈搏","examples":[{"en":"A dai pai dong makes people feel that the city still has a human pulse.","zh":"大牌檔令人感到這座城市仍有人情脈搏。"},{"en":"Human pulse means signs of real human life, feeling, and connection.","zh":"人情脈搏，意思是真實人類生活、感情和連繫的跡象。"},{"en":"A quiet street gains a human pulse when neighbours greet one another.","zh":"當街坊互相問候，安靜街道就有了人情脈搏。"},{"en":"A city loses its human pulse when people move quickly but never connect.","zh":"當人們快速移動卻從不連結，城市就會失去人情脈搏。"},{"en":"Dai pai dongs give Hong Kong a human pulse through voices, meals, and shared tables.","zh":"大牌檔透過人聲、飯餐和搭枱，給香港人情脈搏。"}],"source":"2016 Q5.pdf","sourcePage":10},{"front":"imagine","meaning":"試想像","examples":[{"en":"Imagine a student eating noodles beside a minibus driver.","zh":"試想像一名學生坐在小巴司機旁邊吃麵。"},{"en":"Imagine is used to ask readers to picture a situation in their minds.","zh":"試想像，用來要求讀者在腦海中構想某個情況。"},{"en":"Imagine a classroom where every student feels safe to speak.","zh":"試想像一間每位學生都敢說話的課室。"},{"en":"Writers use imagine to make an idea feel real and concrete.","zh":"作者使用「試想像」令想法感覺真實而具體。"},{"en":"Imagine a dai pai dong at night, with strangers sharing steam, noise, and food.","zh":"試想像夜晚的大牌檔，陌生人共享蒸氣、聲音和食物。"}],"source":"2016 Q5.pdf","sourcePage":10},{"front":"minibus driver","meaning":"小巴司機","examples":[{"en":"A student may eat noodles beside a minibus driver.","zh":"一名學生可能坐在小巴司機旁邊吃麵。"},{"en":"A minibus driver is a person whose job is to drive a small public bus.","zh":"小巴司機，是以駕駛小型公共巴士為工作的人。"},{"en":"A minibus driver may stop for a quick meal between routes.","zh":"小巴司機可能在路線之間停下來快速吃飯。"},{"en":"Minibus drivers are part of the daily transport life of Hong Kong.","zh":"小巴司機是香港日常交通生活的一部分。"},{"en":"At a dai pai dong, a minibus driver and a student can briefly share the same table.","zh":"在大牌檔，小巴司機和學生可以短暫共享同一張桌。"}],"source":"2016 Q5.pdf","sourcePage":10},{"front":"elderly regular","meaning":"年長熟客","examples":[{"en":"An elderly regular may recommend a dish to a tourist.","zh":"年長熟客可能向遊客推薦一道菜。"},{"en":"An elderly regular is an older customer who often visits the same place.","zh":"年長熟客，是經常光顧同一地方的年長顧客。"},{"en":"An elderly regular at a café may know the staff by name.","zh":"咖啡店的年長熟客可能認得職員名字。"},{"en":"Regular customers help a place feel familiar because they carry repeated memories.","zh":"熟客令地方感覺熟悉，因為他們承載重複的記憶。"},{"en":"At a dai pai dong, an elderly regular can become a guide to local taste.","zh":"在大牌檔，年長熟客可以成為本地味道的導賞員。"}],"source":"2016 Q5.pdf","sourcePage":10},{"front":"recommend the best dish","meaning":"推薦最佳菜式","examples":[{"en":"An elderly regular may recommend the best dish to a tourist.","zh":"年長熟客可能向遊客推薦最佳菜式。"},{"en":"To recommend the best dish means to suggest the food that one thinks is most worth trying.","zh":"推薦最佳菜式，意思是建議自己認為最值得嘗試的食物。"},{"en":"A waiter may recommend the best dish to someone visiting for the first time.","zh":"侍應可能向第一次到訪的人推薦最佳菜式。"},{"en":"Recommendations feel warmer when they come from people who know the place well.","zh":"當推薦來自熟悉地方的人，就會感覺更溫暖。"},{"en":"At a dai pai dong, recommending the best dish can turn strangers into temporary friends.","zh":"在大牌檔，推薦最佳菜式可以把陌生人變成短暫朋友。"}],"source":"2016 Q5.pdf","sourcePage":10},{"front":"tourist","meaning":"遊客","examples":[{"en":"A tourist may learn about local food from an elderly regular.","zh":"遊客可能從年長熟客那裏認識本地食物。"},{"en":"A tourist is someone who visits a place for travel, interest, or holiday.","zh":"遊客，是為旅行、興趣或假期而到訪某地的人。"},{"en":"A tourist may take photos of old streets and try local snacks.","zh":"遊客可能拍攝舊街道並嘗試本地小食。"},{"en":"Tourists learn more deeply when locals explain the meaning behind food.","zh":"當本地人解釋食物背後意義，遊客會學得更深入。"},{"en":"Dai pai dongs let tourists taste Hong Kong through real public life.","zh":"大牌檔讓遊客透過真實公共生活品嚐香港。"}],"source":"2016 Q5.pdf","sourcePage":10},{"front":"such encounters","meaning":"這些相遇","examples":[{"en":"Such encounters may seem small, but they matter.","zh":"這些相遇可能看似微小，但它們很重要。"},{"en":"Such encounters means these brief meetings or interactions just mentioned.","zh":"這些相遇，意思是剛剛提到的短暫見面或互動。"},{"en":"A smile between neighbours is a small encounter, but it can make a building feel friendlier.","zh":"街坊之間一個微笑是小小相遇，但可以令大廈感覺更友善。"},{"en":"Small encounters matter because they make public life less cold.","zh":"小小相遇重要，因為它們令公共生活不那麼冰冷。"},{"en":"Dai pai dongs create such encounters when strangers share tables and advice.","zh":"大牌檔在陌生人搭枱和互相建議時創造這些相遇。"}],"source":"2016 Q5.pdf","sourcePage":10},{"front":"seem small","meaning":"看似微小","examples":[{"en":"Such encounters may seem small.","zh":"這些相遇可能看似微小。"},{"en":"Seem small means appear unimportant or minor at first.","zh":"看似微小，意思是一開始看起來不重要或很細小。"},{"en":"Saying good morning to a neighbour may seem small, but it builds trust.","zh":"向街坊說早晨可能看似微小，但它建立信任。"},{"en":"Small actions can matter more than people first realise.","zh":"小行動的重要性可能比人們最初以為的大。"},{"en":"Dai pai dong conversations may seem small, yet they keep community feeling alive.","zh":"大牌檔的交談可能看似微小，卻保持社區感情。"}],"source":"2016 Q5.pdf","sourcePage":11},{"front":"make a neighbourhood feel less lonely","meaning":"令社區感覺不那麼孤單","examples":[{"en":"Small encounters make a neighbourhood feel less lonely.","zh":"小小相遇令社區感覺不那麼孤單。"},{"en":"To make a neighbourhood feel less lonely means to create connection so people do not feel so isolated.","zh":"令社區感覺不那麼孤單，意思是創造連繫，使人不那麼孤立。"},{"en":"A friendly shopkeeper can make a neighbourhood feel less lonely for elderly residents.","zh":"友善店主可以令年長居民覺得社區不那麼孤單。"},{"en":"Shared public spaces reduce loneliness by giving people chances to meet.","zh":"共享公共空間透過給人相遇機會來減少孤單。"},{"en":"Dai pai dongs make neighbourhoods feel less lonely because strangers can become familiar faces.","zh":"大牌檔令社區感覺不那麼孤單，因為陌生人可以變成熟悉面孔。"}],"source":"2016 Q5.pdf","sourcePage":11},{"front":"informal meeting places","meaning":"非正式聚腳點","examples":[{"en":"Dai pai dongs are informal meeting places.","zh":"大牌檔是非正式聚腳點。"},{"en":"Informal meeting places are relaxed spaces where people gather without official arrangements.","zh":"非正式聚腳點，是人們沒有正式安排也會聚集的輕鬆空間。"},{"en":"A park bench can become an informal meeting place for neighbours.","zh":"公園長椅可以成為街坊的非正式聚腳點。"},{"en":"Informal meeting places matter because not all community life happens in official centres.","zh":"非正式聚腳點重要，因為不是所有社區生活都發生在官方中心。"},{"en":"Dai pai dongs are informal meeting places where eating, talking, and resting happen together.","zh":"大牌檔是非正式聚腳點，吃飯、聊天和休息在那裏一起發生。"}],"source":"2016 Q5.pdf","sourcePage":11},{"front":"no less important than","meaning":"不亞於……重要","examples":[{"en":"These meeting places are no less important than community centres.","zh":"這些聚腳點不亞於社區中心重要。"},{"en":"No less important than means just as important as something else.","zh":"不亞於某事重要，意思是與另一事物同樣重要。"},{"en":"A school playground is no less important than a classroom for children’s growth.","zh":"對孩子成長而言，學校操場不亞於課室重要。"},{"en":"Informal spaces can be no less important than official buildings.","zh":"非正式空間可以不亞於官方建築重要。"},{"en":"Dai pai dongs are no less important than community centres because they connect people daily.","zh":"大牌檔不亞於社區中心重要，因為它們每天連結人們。"}],"source":"2016 Q5.pdf","sourcePage":11},{"front":"community centres","meaning":"社區中心","examples":[{"en":"Dai pai dongs can connect people like community centres do.","zh":"大牌檔可以像社區中心一樣連結人們。"},{"en":"Community centres are public places where residents can meet, learn, and join activities.","zh":"社區中心，是居民可以相聚、學習和參加活動的公共地方。"},{"en":"A community centre may offer classes, talks, and support services.","zh":"社區中心可能提供課程、講座和支援服務。"},{"en":"Community centres help people feel less isolated.","zh":"社區中心幫助人們感到不那麼孤立。"},{"en":"Dai pai dongs are not official community centres, but they can serve a similar social role.","zh":"大牌檔不是正式社區中心，但可以發揮相似的社交作用。"}],"source":"2016 Q5.pdf","sourcePage":11},{"front":"remind us that","meaning":"提醒我們","examples":[{"en":"Dai pai dongs remind us that culture is created in daily life.","zh":"大牌檔提醒我們，文化是在日常生活中創造的。"},{"en":"To remind us that means to make us remember or realise something important.","zh":"提醒我們，意思是令我們記起或意識到某件重要事情。"},{"en":"Old family photos remind us that ordinary moments become history.","zh":"舊家庭照片提醒我們，普通時刻也會成為歷史。"},{"en":"Cultural places remind us that identity is built through habits, not only speeches.","zh":"文化地方提醒我們，身份是透過習慣建立的，不只是透過演說。"},{"en":"Dai pai dongs remind us that food, talk, and street life are culture too.","zh":"大牌檔提醒我們，食物、交談和街頭生活也是文化。"}],"source":"2016 Q5.pdf","sourcePage":11},{"front":"performed on a stage","meaning":"在舞台上表演","examples":[{"en":"Culture is not always performed on a stage.","zh":"文化不一定總是在舞台上表演。"},{"en":"Performed on a stage means shown formally to an audience in a theatre or public performance space.","zh":"在舞台上表演，意思是在劇場或公共表演空間正式向觀眾展示。"},{"en":"A dance may be performed on a stage during a school concert.","zh":"舞蹈可能在學校音樂會中在舞台上表演。"},{"en":"Culture can also appear in kitchens, markets, streets, and family meals.","zh":"文化也可以出現在廚房、街市、街道和家庭飯餐中。"},{"en":"Dai pai dongs show that culture does not need to be performed on a stage to be real.","zh":"大牌檔顯示文化不需要在舞台上表演才是真實的。"}],"source":"2016 Q5.pdf","sourcePage":11},{"front":"more often than not","meaning":"往往；多數情況下","examples":[{"en":"More often than not, culture is created in everyday encounters.","zh":"往往，文化是在日常相遇中創造的。"},{"en":"More often than not means usually or in most cases.","zh":"往往或多數情況下，意思是通常或在大部分情況中。"},{"en":"More often than not, students understand better after seeing a real example.","zh":"多數情況下，學生看見真實例子後會理解得更好。"},{"en":"This phrase helps writers make a general point without saying always.","zh":"這個短語幫助作者提出一般觀點，而不是說永遠如此。"},{"en":"More often than not, local culture appears in ordinary habits rather than grand events.","zh":"往往，本地文化出現在普通習慣中，而不是盛大活動中。"}],"source":"2016 Q5.pdf","sourcePage":11},{"front":"strangers become temporary neighbours","meaning":"陌生人成為短暫鄰居","examples":[{"en":"Culture is created when strangers become temporary neighbours.","zh":"當陌生人成為短暫鄰居時，文化就被創造出來。"},{"en":"Strangers become temporary neighbours when people who do not know each other share a space briefly and peacefully.","zh":"陌生人成為短暫鄰居，是指不認識的人短暫而和平地共享空間。"},{"en":"Passengers on a long bus ride may become temporary neighbours for an hour.","zh":"長途巴士上的乘客可能在一小時內成為短暫鄰居。"},{"en":"Sharing a table can turn strangers into temporary neighbours through small talk.","zh":"搭枱可以透過閒談把陌生人變成短暫鄰居。"},{"en":"Dai pai dongs create culture by letting strangers become temporary neighbours over food.","zh":"大牌檔透過讓陌生人在食物旁成為短暫鄰居來創造文化。"}],"source":"2016 Q5.pdf","sourcePage":11},{"front":"temporary neighbours","meaning":"短暫鄰居","examples":[{"en":"People sharing a table can become temporary neighbours.","zh":"搭枱的人可以成為短暫鄰居。"},{"en":"Temporary neighbours are people who briefly share space and behave with neighbourly closeness.","zh":"短暫鄰居，是短時間共享空間並表現出鄰里親近感的人。"},{"en":"Two travellers waiting beside each other may become temporary neighbours during a delay.","zh":"兩名旅客在延誤期間並排等待，可能成為短暫鄰居。"},{"en":"Temporary neighbours may never meet again, but the small connection still matters.","zh":"短暫鄰居可能不會再見，但小小連繫仍重要。"},{"en":"Dai pai dongs turn strangers into temporary neighbours through shared tables.","zh":"大牌檔透過搭枱把陌生人變成短暫鄰居。"}],"source":"2016 Q5.pdf","sourcePage":11},{"front":"granted","meaning":"誠然","examples":[{"en":"Granted, some people argue that dai pai dongs are difficult to regulate.","zh":"誠然，有些人認為大牌檔難以規管。"},{"en":"Granted is used to admit that an opposing point has some truth before answering it.","zh":"誠然，用來承認相反觀點有一定道理，然後再回應它。"},{"en":"Granted, the old market is crowded, but it also supports many families.","zh":"誠然，舊街市很擁擠，但它也支持許多家庭。"},{"en":"This word helps writers sound fair instead of ignoring criticism.","zh":"這個詞幫助作者顯得公平，而不是忽視批評。"},{"en":"Granted, dai pai dongs have problems, but disappearance is not the only answer.","zh":"誠然，大牌檔有問題，但消失不是唯一答案。"}],"source":"2016 Q5.pdf","sourcePage":12},{"front":"argue that","meaning":"認為；主張","examples":[{"en":"Some people argue that dai pai dongs are noisy and smoky.","zh":"有些人認為大牌檔嘈雜而多煙。"},{"en":"To argue that means to state and support an opinion.","zh":"認為或主張，意思是提出並支持一個看法。"},{"en":"Some students argue that homework should be reduced.","zh":"有些學生認為功課應該減少。"},{"en":"People may argue that safety rules must be stricter after an accident.","zh":"意外後，人們可能主張安全規則必須更嚴格。"},{"en":"Critics argue that dai pai dongs need better regulation, not blind preservation.","zh":"批評者認為大牌檔需要更好規管，而不是盲目保育。"}],"source":"2016 Q5.pdf","sourcePage":12},{"front":"noisy, smoky and difficult to regulate","meaning":"嘈雜、多煙、難以規管","examples":[{"en":"Dai pai dongs may be noisy, smoky and difficult to regulate.","zh":"大牌檔可能嘈雜、多煙、難以規管。"},{"en":"Noisy, smoky and difficult to regulate describes a place that creates sound, cooking smoke, and management problems.","zh":"嘈雜、多煙、難以規管，形容一個地方產生聲音、煮食煙霧和管理問題。"},{"en":"A busy street barbecue stall may be noisy, smoky and difficult to regulate.","zh":"繁忙街頭燒烤檔可能嘈雜、多煙、難以規管。"},{"en":"These problems matter because neighbours need safety, clean air, and clear pavements.","zh":"這些問題重要，因為街坊需要安全、清潔空氣和暢通行人路。"},{"en":"Dai pai dongs can be improved even if they are noisy, smoky and difficult to regulate.","zh":"即使大牌檔嘈雜、多煙、難以規管，它們仍可以被改善。"}],"source":"2016 Q5.pdf","sourcePage":12},{"front":"difficult to regulate","meaning":"難以規管","examples":[{"en":"Open-air stalls can be difficult to regulate.","zh":"露天檔口可能難以規管。"},{"en":"Difficult to regulate means hard for authorities to control, inspect, or manage properly.","zh":"難以規管，意思是當局難以適當控制、檢查或管理。"},{"en":"Street parking can be difficult to regulate when many drivers ignore signs.","zh":"當很多司機忽視標誌，街邊泊車就可能難以規管。"},{"en":"Something difficult to regulate may need clearer rules instead of total removal.","zh":"難以規管的事物可能需要更清晰規則，而不是完全移除。"},{"en":"Dai pai dongs are difficult to regulate, but careful licensing can help.","zh":"大牌檔難以規管，但審慎牌照制度可以幫助。"}],"source":"2016 Q5.pdf","sourcePage":12},{"front":"that concern is reasonable","meaning":"這個憂慮是合理的","examples":[{"en":"That concern is reasonable and should not be ignored.","zh":"這個憂慮是合理的，不應被忽視。"},{"en":"That concern is reasonable means the worry has a fair and sensible basis.","zh":"這個憂慮是合理的，意思是這個擔心有公平和合理的基礎。"},{"en":"Parents’ concern about food safety at school is reasonable.","zh":"家長對學校食物安全的憂慮是合理的。"},{"en":"A reasonable concern deserves a practical answer, not dismissal.","zh":"合理憂慮值得實際回應，而不是被否定。"},{"en":"Concerns about hygiene at dai pai dongs are reasonable, but they do not require disappearance.","zh":"對大牌檔衞生的憂慮是合理的，但不代表必須令它們消失。"}],"source":"2016 Q5.pdf","sourcePage":12},{"front":"preservation","meaning":"保育","examples":[{"en":"Preservation should never become an excuse for poor hygiene.","zh":"保育絕不應成為衞生欠佳的藉口。"},{"en":"Preservation means protecting something so it can continue to exist.","zh":"保育，意思是保護某事物，使它能繼續存在。"},{"en":"Preservation of old buildings may require repairs and safety checks.","zh":"保育舊建築可能需要維修和安全檢查。"},{"en":"Good preservation keeps value alive while solving real problems.","zh":"好的保育會讓價值延續，同時解決真正問題。"},{"en":"Dai pai dong preservation should include hygiene, safety, and respect for neighbours.","zh":"大牌檔保育應包括衞生、安全和對街坊的尊重。"}],"source":"2016 Q5.pdf","sourcePage":12},{"front":"become an excuse for","meaning":"成為……的藉口","examples":[{"en":"Preservation should not become an excuse for poor hygiene.","zh":"保育不應成為衞生欠佳的藉口。"},{"en":"To become an excuse for something means to be used wrongly to justify a problem.","zh":"成為某事的藉口，意思是被錯誤用來合理化一個問題。"},{"en":"Freedom should not become an excuse for bullying classmates.","zh":"自由不應成為欺凌同學的藉口。"},{"en":"Tradition becomes an excuse for harm when people refuse to improve unsafe habits.","zh":"當人們拒絕改善不安全習慣，傳統就會成為傷害的藉口。"},{"en":"Dai pai dong culture should not become an excuse for ignoring cleanliness.","zh":"大牌檔文化不應成為忽視清潔的藉口。"}],"source":"2016 Q5.pdf","sourcePage":12},{"front":"poor hygiene","meaning":"衞生欠佳","examples":[{"en":"Preservation should not excuse poor hygiene.","zh":"保育不應為衞生欠佳開脫。"},{"en":"Poor hygiene means unclean conditions that may harm health.","zh":"衞生欠佳，意思是不清潔並可能危害健康的情況。"},{"en":"A kitchen with dirty tools and uncovered food has poor hygiene.","zh":"有骯髒工具和沒有覆蓋食物的廚房，就是衞生欠佳。"},{"en":"Poor hygiene can make customers sick, so food stalls need clear standards.","zh":"衞生欠佳可能令顧客生病，所以食檔需要清晰標準。"},{"en":"Dai pai dongs should be preserved only with better hygiene practices.","zh":"大牌檔應在改善衞生做法下被保育。"}],"source":"2016 Q5.pdf","sourcePage":12},{"front":"blocked pavements","meaning":"被阻塞的行人路","examples":[{"en":"Preservation should not excuse blocked pavements.","zh":"保育不應為被阻塞的行人路開脫。"},{"en":"Blocked pavements are walkways made hard to pass because objects or people are in the way.","zh":"被阻塞的行人路，是因物件或人群阻擋而難以通過的步行道。"},{"en":"Tables, boxes, or parked bicycles can create blocked pavements.","zh":"桌子、箱子或停泊的單車都可能造成被阻塞的行人路。"},{"en":"Blocked pavements are dangerous for elderly people, wheelchair users, and parents with prams.","zh":"被阻塞的行人路對長者、輪椅使用者和推嬰兒車的家長很危險。"},{"en":"Dai pai dongs can survive with layouts that avoid blocked pavements.","zh":"大牌檔可以透過避免阻塞行人路的布局繼續存在。"}],"source":"2016 Q5.pdf","sourcePage":12},{"front":"acknowledge the problem","meaning":"承認問題","examples":[{"en":"To acknowledge the problem is not to accept disappearance.","zh":"承認問題並不等於接受消失。"},{"en":"To acknowledge the problem means to admit honestly that a real issue exists.","zh":"承認問題，意思是誠實承認真實問題存在。"},{"en":"A school acknowledges a problem when it admits that bullying has happened.","zh":"學校承認欺凌曾發生，就是承認問題。"},{"en":"Acknowledging a problem is the first step toward fixing it.","zh":"承認問題是修正問題的第一步。"},{"en":"Supporters of dai pai dongs can acknowledge problems while still arguing for preservation.","zh":"支持大牌檔的人可以承認問題，同時仍主張保育。"}],"source":"2016 Q5.pdf","sourcePage":12},{"front":"concede that","meaning":"承認","examples":[{"en":"To acknowledge the problem is not to concede that disappearance is the only solution.","zh":"承認問題並不等於承認消失是唯一解決方法。"},{"en":"To concede that means to admit something, especially in an argument.","zh":"承認某事，意思是承認某事屬實，特別是在爭論中。"},{"en":"A student may concede that an essay has weaknesses while still defending its main idea.","zh":"學生可能承認文章有弱點，同時仍維護主要觀點。"},{"en":"Conceding one problem does not mean accepting the strongest criticism.","zh":"承認一個問題並不等於接受最強烈的批評。"},{"en":"We can concede that dai pai dongs need rules without accepting that they must disappear.","zh":"我們可以承認大牌檔需要規則，而不接受它們必須消失。"}],"source":"2016 Q5.pdf","sourcePage":13},{"front":"disappearance","meaning":"消失","examples":[{"en":"Disappearance is not the only solution.","zh":"消失不是唯一解決方法。"},{"en":"Disappearance means the act or process of something vanishing or no longer existing.","zh":"消失，意思是某事物不見或不再存在的行為或過程。"},{"en":"The disappearance of a village shop can change daily life for elderly residents.","zh":"鄉村小店的消失可以改變年長居民的日常生活。"},{"en":"Cultural disappearance happens slowly when people stop protecting living traditions.","zh":"當人們停止保護活著的傳統，文化消失會慢慢發生。"},{"en":"The disappearance of dai pai dongs would remove more than old food stalls.","zh":"大牌檔的消失會移走的不只是舊食檔。"}],"source":"2016 Q5.pdf","sourcePage":13},{"front":"the only solution","meaning":"唯一解決方法","examples":[{"en":"Closing all dai pai dongs is not the only solution.","zh":"關閉所有大牌檔不是唯一解決方法。"},{"en":"The only solution means the single answer to a problem.","zh":"唯一解決方法，意思是某個問題的唯一答案。"},{"en":"Punishment is not the only solution when students make mistakes.","zh":"當學生犯錯，懲罰不是唯一解決方法。"},{"en":"If there are several possible answers, one harsh action should not be treated as the only solution.","zh":"如果有幾個可能答案，就不應把一個嚴厲行動視為唯一解決方法。"},{"en":"Better rules, safer equipment, and suitable locations may work better than closing all stalls.","zh":"更好規則、更安全設備和合適地點，可能比關閉所有檔口更有效。"}],"source":"2016 Q5.pdf","sourcePage":13},{"front":"careful adaptation","meaning":"審慎調適","examples":[{"en":"The better answer is careful adaptation.","zh":"更好的答案是審慎調適。"},{"en":"Careful adaptation means changing something thoughtfully so it can survive in new conditions.","zh":"審慎調適，意思是仔細地改變某事物，使它能在新條件下生存。"},{"en":"An old school building may need careful adaptation to meet modern safety rules.","zh":"舊校舍可能需要審慎調適，以符合現代安全規則。"},{"en":"Careful adaptation protects value while solving practical problems.","zh":"審慎調適在解決實際問題的同時保護價值。"},{"en":"Dai pai dongs need careful adaptation, not careless destruction.","zh":"大牌檔需要審慎調適，而不是粗心摧毀。"}],"source":"2016 Q5.pdf","sourcePage":13},{"front":"designate suitable cooked-food zones","meaning":"指定合適熟食區","examples":[{"en":"The government could designate suitable cooked-food zones.","zh":"政府可以指定合適熟食區。"},{"en":"To designate suitable cooked-food zones means to officially choose proper areas for cooked-food stalls.","zh":"指定合適熟食區，意思是正式選定適合熟食檔經營的區域。"},{"en":"A school may designate a suitable eating area during a fair.","zh":"學校可能在嘉年華期間指定合適進食區。"},{"en":"Designated zones help manage safety, smoke, rubbish, and pedestrian space.","zh":"指定區域有助管理安全、煙霧、垃圾和行人空間。"},{"en":"Suitable cooked-food zones could let dai pai dongs operate without blocking pavements.","zh":"合適熟食區可以讓大牌檔經營而不阻塞行人路。"}],"source":"2016 Q5.pdf","sourcePage":13},{"front":"cooked-food zones","meaning":"熟食區","examples":[{"en":"Suitable cooked-food zones could help preserve dai pai dongs safely.","zh":"合適熟食區可以幫助安全保育大牌檔。"},{"en":"Cooked-food zones are areas set aside for stalls or shops selling prepared meals.","zh":"熟食區，是預留給售賣已煮好飯餐的檔口或店舖的區域。"},{"en":"A market may have cooked-food zones where people buy noodles and rice dishes.","zh":"街市可能有熟食區，讓人購買麵和飯類菜式。"},{"en":"Cooked-food zones make regulation easier because facilities can be planned together.","zh":"熟食區令規管較容易，因為設施可以一併規劃。"},{"en":"Dai pai dongs could survive better if cooked-food zones were designed with culture in mind.","zh":"如果熟食區設計時考慮文化，大牌檔可以更好地生存。"}],"source":"2016 Q5.pdf","sourcePage":13},{"front":"renewable licences","meaning":"可續期牌照","examples":[{"en":"The government could offer renewable licences to responsible operators.","zh":"政府可以向負責任的經營者提供可續期牌照。"},{"en":"Renewable licences are official permissions that can be extended after a period of time.","zh":"可續期牌照，是一段時間後可以延續的正式許可。"},{"en":"A market stall may keep operating if its renewable licence is approved.","zh":"如果可續期牌照獲批，街市檔口可以繼續經營。"},{"en":"Renewable licences can reward operators who meet safety and hygiene standards.","zh":"可續期牌照可以獎勵符合安全和衞生標準的經營者。"},{"en":"Dai pai dongs need renewable licences so responsible families can continue legally.","zh":"大牌檔需要可續期牌照，讓負責任家庭可以合法繼續經營。"}],"source":"2016 Q5.pdf","sourcePage":13},{"front":"responsible operators","meaning":"負責任的經營者","examples":[{"en":"Responsible operators should be allowed to continue running stalls.","zh":"負責任的經營者應被容許繼續經營檔口。"},{"en":"Responsible operators are business owners who follow rules and care about safety, cleanliness, and neighbours.","zh":"負責任的經營者，是遵守規則並關心安全、清潔和街坊的店主。"},{"en":"A responsible operator keeps food covered and rubbish under control.","zh":"負責任的經營者會覆蓋食物並妥善處理垃圾。"},{"en":"Responsible operators make preservation easier because they reduce public concerns.","zh":"負責任的經營者令保育更容易，因為他們減少公眾憂慮。"},{"en":"Dai pai dongs should be supported when responsible operators manage them well.","zh":"當負責任的經營者管理得好，大牌檔應受到支持。"}],"source":"2016 Q5.pdf","sourcePage":13},{"front":"modern safety equipment","meaning":"現代安全設備","examples":[{"en":"Dai pai dongs could use modern safety equipment.","zh":"大牌檔可以使用現代安全設備。"},{"en":"Modern safety equipment means updated tools that reduce danger, such as fire protection or better ventilation.","zh":"現代安全設備，是減少危險的更新工具，例如防火設備或更好通風。"},{"en":"A school kitchen uses modern safety equipment to prevent burns and fires.","zh":"學校廚房使用現代安全設備來防止燙傷和火警。"},{"en":"Safety equipment can protect workers and customers without changing the food itself.","zh":"安全設備可以保護工人和顧客，而不改變食物本身。"},{"en":"Dai pai dongs can become safer by using modern safety equipment carefully.","zh":"大牌檔可以透過小心使用現代安全設備變得更安全。"}],"source":"2016 Q5.pdf","sourcePage":13},{"front":"without destroying","meaning":"在不破壞……的情況下","examples":[{"en":"Safety rules can be introduced without destroying the stalls’ character.","zh":"安全規則可以在不破壞檔口特色的情況下引入。"},{"en":"Without destroying means improving or changing something while not ruining its essential value.","zh":"在不破壞某事的情況下，意思是改善或改變某事，同時不毀掉其核心價值。"},{"en":"A school can renovate a hall without destroying its history.","zh":"學校可以翻新禮堂，而不破壞其歷史。"},{"en":"Good rules improve safety without destroying local atmosphere.","zh":"好規則能改善安全，而不破壞本地氣氛。"},{"en":"Dai pai dongs can be cleaner without destroying their warmth and street energy.","zh":"大牌檔可以更潔淨，而不破壞它們的溫暖和街頭活力。"}],"source":"2016 Q5.pdf","sourcePage":13},{"front":"stalls’ character","meaning":"檔口特色","examples":[{"en":"Modern equipment should not destroy the stalls’ character.","zh":"現代設備不應破壞檔口特色。"},{"en":"Stalls’ character means the special style, feeling, and identity of the food stalls.","zh":"檔口特色，是食檔特別的風格、感覺和身份。"},{"en":"A stall’s character may come from its signs, cooking sounds, and regular customers.","zh":"檔口特色可能來自招牌、煮食聲音和熟客。"},{"en":"If renovation removes all familiar details, the stall’s character may disappear.","zh":"如果翻新移走所有熟悉細節，檔口特色可能消失。"},{"en":"Dai pai dong rules should protect safety while keeping the stalls’ character alive.","zh":"大牌檔規則應保障安全，同時保留檔口特色。"}],"source":"2016 Q5.pdf","sourcePage":14},{"front":"meanwhile","meaning":"與此同時","examples":[{"en":"Schools, meanwhile, could organise local culture projects.","zh":"與此同時，學校可以舉辦本地文化專題研習。"},{"en":"Meanwhile means at the same time or in another related part of the plan.","zh":"與此同時，意思是在同一時間，或在計劃中的另一相關部分。"},{"en":"The city can repair old buildings; meanwhile, schools can teach their history.","zh":"城市可以維修舊建築；與此同時，學校可以教導其歷史。"},{"en":"Writers use meanwhile to show a second action happening alongside the first.","zh":"作者使用「與此同時」顯示第二個行動與第一個行動並行。"},{"en":"The government can improve licences; meanwhile, schools can help students learn dai pai dong culture.","zh":"政府可以改善牌照；與此同時，學校可以幫助學生認識大牌檔文化。"}],"source":"2016 Q5.pdf","sourcePage":14},{"front":"organise local culture projects","meaning":"舉辦本地文化專題研習","examples":[{"en":"Schools could organise local culture projects about dai pai dongs.","zh":"學校可以舉辦關於大牌檔的本地文化專題研習。"},{"en":"To organise local culture projects means to plan learning activities about a community’s traditions and daily life.","zh":"舉辦本地文化專題研習，意思是策劃關於社區傳統和日常生活的學習活動。"},{"en":"A teacher may organise a local culture project about old shops near the school.","zh":"老師可能舉辦關於學校附近老店的本地文化專題研習。"},{"en":"These projects help students learn history through real people and places.","zh":"這些專題研習幫助學生透過真人真地學習歷史。"},{"en":"Schools can organise dai pai dong projects so students understand food as heritage.","zh":"學校可以舉辦大牌檔專題研習，讓學生理解食物也是文化遺產。"}],"source":"2016 Q5.pdf","sourcePage":14},{"front":"local culture projects","meaning":"本地文化專題研習","examples":[{"en":"Students could learn from local culture projects.","zh":"學生可以從本地文化專題研習中學習。"},{"en":"Local culture projects are school or community studies about nearby traditions, places, people, and habits.","zh":"本地文化專題研習，是關於附近傳統、地方、人物和習慣的學校或社區研究。"},{"en":"Students may interview shopkeepers for local culture projects.","zh":"學生可能為本地文化專題研習訪問店主。"},{"en":"Local culture projects make history feel close rather than distant.","zh":"本地文化專題研習令歷史感覺貼近，而不是遙遠。"},{"en":"Dai pai dongs are good topics for local culture projects because they connect food, work, and memory.","zh":"大牌檔是本地文化專題研習的好題目，因為它們連結食物、工作和記憶。"}],"source":"2016 Q5.pdf","sourcePage":14},{"front":"interview hawkers","meaning":"訪問小販","examples":[{"en":"Students could interview hawkers for school projects.","zh":"學生可以為學校專題訪問小販。"},{"en":"To interview hawkers means to ask street sellers questions and record their answers.","zh":"訪問小販，意思是向街頭售賣者提問並記錄他們的回答。"},{"en":"Students may interview hawkers about how long they have worked in the market.","zh":"學生可能訪問小販，了解他們在街市工作了多久。"},{"en":"Interviews help young people hear history directly from workers.","zh":"訪問幫助年輕人直接從工人口中聽見歷史。"},{"en":"Interviewing hawkers can preserve voices that may otherwise disappear.","zh":"訪問小販可以保存可能會消失的聲音。"}],"source":"2016 Q5.pdf","sourcePage":14},{"front":"record menus","meaning":"記錄餐牌","examples":[{"en":"Students could record menus as part of local history.","zh":"學生可以記錄餐牌，作為本地歷史的一部分。"},{"en":"To record menus means to write down, photograph, or save lists of dishes and prices.","zh":"記錄餐牌，意思是寫下、拍攝或保存菜式和價格清單。"},{"en":"A student may record menus from old cafés to compare food prices over time.","zh":"學生可能記錄舊咖啡店餐牌，以比較食物價格如何隨時間改變。"},{"en":"Menus show what people ate, what they could afford, and what flavours mattered.","zh":"餐牌顯示人們吃甚麼、負擔得起甚麼，以及哪些味道重要。"},{"en":"Recording dai pai dong menus can preserve a small but useful part of Hong Kong history.","zh":"記錄大牌檔餐牌可以保存香港歷史中細小但有用的一部分。"}],"source":"2016 Q5.pdf","sourcePage":14},{"front":"reflect migration","meaning":"反映移民","examples":[{"en":"A bowl of noodles can reflect migration and labour.","zh":"一碗麵可以反映移民和勞動。"},{"en":"To reflect migration means to show how people’s movement from one place to another has shaped something.","zh":"反映移民，意思是顯示人們從一地遷往另一地如何塑造某事物。"},{"en":"A city’s food can reflect migration when dishes carry flavours from different hometowns.","zh":"當菜式帶有不同家鄉味道，城市食物就可以反映移民。"},{"en":"Recipes reflect migration because families bring ingredients and habits with them.","zh":"食譜反映移民，因為家庭把食材和習慣帶到新地方。"},{"en":"Dai pai dong dishes can reflect migration through flavours shaped by workers’ journeys.","zh":"大牌檔菜式可以透過由工人旅程塑造的味道反映移民。"}],"source":"2016 Q5.pdf","sourcePage":14},{"front":"labour","meaning":"勞動","examples":[{"en":"A bowl of noodles can reflect migration, labour and sacrifice.","zh":"一碗麵可以反映移民、勞動和犧牲。"},{"en":"Labour means hard work, especially physical or practical work.","zh":"勞動，意思是辛勤工作，特別是體力或實際工作。"},{"en":"Cooking for many customers requires heat, speed, and labour.","zh":"為許多顧客煮食需要熱力、速度和勞動。"},{"en":"People often forget the labour behind cheap and convenient meals.","zh":"人們常忘記便宜方便飯餐背後的勞動。"},{"en":"Dai pai dongs make labour visible through open kitchens and tired hands.","zh":"大牌檔透過開放廚房和疲倦雙手令勞動可見。"}],"source":"2016 Q5.pdf","sourcePage":14},{"front":"family sacrifice","meaning":"家庭犧牲","examples":[{"en":"Local food can reflect family sacrifice.","zh":"本地食物可以反映家庭犧牲。"},{"en":"Family sacrifice means what family members give up or endure to support one another.","zh":"家庭犧牲，意思是家庭成員為支持彼此而放棄或承受的事情。"},{"en":"Parents working late to pay school fees show family sacrifice.","zh":"父母工作到很晚以支付學費，就是家庭犧牲。"},{"en":"Small businesses often depend on family sacrifice because relatives share long hours and risks.","zh":"小生意常依靠家庭犧牲，因為親人分擔長工時和風險。"},{"en":"Dai pai dongs carry family sacrifice through generations of hard work.","zh":"大牌檔透過幾代人的辛勤工作承載家庭犧牲。"}],"source":"2016 Q5.pdf","sourcePage":14},{"front":"freeze… in the past","meaning":"將……凍結在過去","examples":[{"en":"Preservation would not freeze dai pai dongs in the past.","zh":"保育不會將大牌檔凍結在過去。"},{"en":"To freeze something in the past means to keep it unchanged as if it belongs only to history.","zh":"將某事物凍結在過去，意思是把它保持不變，好像它只屬於歷史。"},{"en":"A museum should not freeze culture in the past if people still practise it today.","zh":"如果人們今天仍實踐某種文化，博物館不應將它凍結在過去。"},{"en":"Good preservation allows traditions to change without losing meaning.","zh":"好的保育容許傳統改變而不失去意義。"},{"en":"Dai pai dongs should not be frozen in the past; they should adapt and continue.","zh":"大牌檔不應被凍結在過去；它們應調適並延續。"}],"source":"2016 Q5.pdf","sourcePage":14},{"front":"make room for","meaning":"為……留出空間","examples":[{"en":"Preservation would make room for dai pai dongs in the future.","zh":"保育會為大牌檔在未來留出空間。"},{"en":"To make room for something means to create space or opportunity for it.","zh":"為某事留出空間，意思是為它創造空間或機會。"},{"en":"A timetable can make room for rest by reducing unnecessary tasks.","zh":"時間表可以透過減少不必要任務為休息留出空間。"},{"en":"Cities make room for culture when planning includes old and new together.","zh":"當城市規劃同時包括新舊事物，城市就是為文化留出空間。"},{"en":"Hong Kong should make room for dai pai dongs instead of replacing them completely.","zh":"香港應為大牌檔留出空間，而不是完全取代它們。"}],"source":"2016 Q5.pdf","sourcePage":15},{"front":"in the future","meaning":"在未來","examples":[{"en":"Dai pai dongs should have a place in the future.","zh":"大牌檔應該在未來有一席位。"},{"en":"In the future means in the time that has not yet come.","zh":"在未來，意思是在尚未到來的時間裏。"},{"en":"Students study hard because they want more choices in the future.","zh":"學生努力學習，因為他們希望在未來有更多選擇。"},{"en":"Planning for the future should include both development and memory.","zh":"為未來規劃時，應同時包括發展和記憶。"},{"en":"Dai pai dongs can exist in the future if policies support careful adaptation.","zh":"如果政策支持審慎調適，大牌檔可以在未來繼續存在。"}],"source":"2016 Q5.pdf","sourcePage":15},{"front":"cleaner stall","meaning":"更潔淨的檔口","examples":[{"en":"A cleaner stall can still be lively.","zh":"更潔淨的檔口仍然可以熱鬧。"},{"en":"A cleaner stall is a food stall that has better hygiene and tidier conditions.","zh":"更潔淨的檔口，是衞生和整潔情況更好的食檔。"},{"en":"A cleaner stall keeps food covered, tools washed, and rubbish controlled.","zh":"更潔淨的檔口會覆蓋食物、清洗工具並控制垃圾。"},{"en":"Cleanliness does not have to remove noise, warmth, or local character.","zh":"清潔不一定要移走聲音、溫暖或本地特色。"},{"en":"Dai pai dongs can become cleaner stalls while keeping their street energy.","zh":"大牌檔可以成為更潔淨的檔口，同時保留街頭活力。"}],"source":"2016 Q5.pdf","sourcePage":15},{"front":"lively","meaning":"熱鬧的；有活力的","examples":[{"en":"A cleaner stall can still be lively.","zh":"更潔淨的檔口仍然可以熱鬧。"},{"en":"Lively means full of energy, sound, movement, or activity.","zh":"熱鬧或有活力，意思是充滿能量、聲音、動作或活動。"},{"en":"A lively classroom has students asking questions and working together.","zh":"熱鬧的課室有學生提問和一起合作。"},{"en":"A place can be clean and lively at the same time.","zh":"一個地方可以同時乾淨和熱鬧。"},{"en":"Dai pai dongs are lively because cooking, eating, and talking happen close together.","zh":"大牌檔熱鬧，因為煮食、進食和交談近距離發生。"}],"source":"2016 Q5.pdf","sourcePage":15},{"front":"safer kitchen","meaning":"更安全的廚房","examples":[{"en":"A safer kitchen can still produce food with soul.","zh":"更安全的廚房仍然可以做出有靈魂的食物。"},{"en":"A safer kitchen is a cooking space with better equipment and habits to reduce danger.","zh":"更安全的廚房，是有更好設備和習慣來減少危險的煮食空間。"},{"en":"A safer kitchen may have fire protection, clear walkways, and clean tools.","zh":"更安全的廚房可能有防火設備、暢通通道和清潔工具。"},{"en":"Safer kitchens protect workers without making food less meaningful.","zh":"更安全的廚房保護工人，而不會令食物失去意義。"},{"en":"Dai pai dongs need safer kitchens so their culture can continue responsibly.","zh":"大牌檔需要更安全的廚房，好讓其文化負責任地延續。"}],"source":"2016 Q5.pdf","sourcePage":15},{"front":"food with soul","meaning":"有靈魂的食物","examples":[{"en":"A safer kitchen can still produce food with soul.","zh":"更安全的廚房仍然可以做出有靈魂的食物。"},{"en":"Food with soul means food that feels meaningful, personal, and full of care.","zh":"有靈魂的食物，是感覺有意義、個人化和充滿心意的食物。"},{"en":"A grandmother’s soup can be food with soul because it carries love and memory.","zh":"祖母的湯可以是有靈魂的食物，因為它承載愛和記憶。"},{"en":"Food with soul does not need to be expensive or beautifully decorated.","zh":"有靈魂的食物不需要昂貴或裝飾漂亮。"},{"en":"Dai pai dongs serve food with soul because each dish carries labour and local feeling.","zh":"大牌檔供應有靈魂的食物，因為每道菜都承載勞動和本地情感。"}],"source":"2016 Q5.pdf","sourcePage":15},{"front":"all things considered","meaning":"綜合而言","examples":[{"en":"All things considered, Hong Kong should preserve dai pai dongs.","zh":"綜合而言，香港應保育大牌檔。"},{"en":"All things considered means after thinking about all important points together.","zh":"綜合而言，意思是在一起考慮所有重要因素之後。"},{"en":"All things considered, the school should keep the library open after lessons.","zh":"綜合而言，學校應在放學後保持圖書館開放。"},{"en":"Writers use this phrase before giving a balanced final judgement.","zh":"作者在作出平衡的最終判斷前會使用這個短語。"},{"en":"All things considered, dai pai dongs should be protected and improved.","zh":"綜合而言，大牌檔應被保護和改善。"}],"source":"2016 Q5.pdf","sourcePage":15},{"front":"more than eating places","meaning":"不只是用餐地方","examples":[{"en":"Dai pai dongs are more than eating places.","zh":"大牌檔不只是用餐地方。"},{"en":"More than eating places means they have value beyond simply serving food.","zh":"不只是用餐地方，意思是它們的價值超越單純供應食物。"},{"en":"A school canteen may be more than an eating place if students build friendships there.","zh":"如果學生在學校飯堂建立友誼，飯堂就不只是用餐地方。"},{"en":"Food spaces matter when they carry memory, conversation, and identity.","zh":"當飲食空間承載記憶、交談和身份，它們就很重要。"},{"en":"Dai pai dongs are more than eating places because they are social and cultural spaces.","zh":"大牌檔不只是用餐地方，因為它們是社交和文化空間。"}],"source":"2016 Q5.pdf","sourcePage":15},{"front":"classrooms of memory","meaning":"記憶的課室","examples":[{"en":"Dai pai dongs are classrooms of memory.","zh":"大牌檔是記憶的課室。"},{"en":"Classrooms of memory are places where people learn about the past through lived experience.","zh":"記憶的課室，是人們透過生活經驗學習過去的地方。"},{"en":"An old market can be a classroom of memory when elders explain how it changed.","zh":"當長者解釋舊街市如何改變，它就可以是記憶的課室。"},{"en":"Such classrooms teach through sights, sounds, smells, and stories.","zh":"這些課室透過景象、聲音、氣味和故事教人。"},{"en":"Dai pai dongs are classrooms of memory because young people can learn history by eating there.","zh":"大牌檔是記憶的課室，因為年輕人可以透過在那裏吃飯學習歷史。"}],"source":"2016 Q5.pdf","sourcePage":15},{"front":"theatres of community","meaning":"社區的劇場","examples":[{"en":"Dai pai dongs are theatres of community.","zh":"大牌檔是社區的劇場。"},{"en":"Theatres of community are public spaces where community life is visibly acted out.","zh":"社區的劇場，是社區生活被可見地演繹出來的公共空間。"},{"en":"A market becomes a theatre of community when buyers, sellers, and neighbours interact.","zh":"當買家、賣家和街坊互動，街市就成為社區的劇場。"},{"en":"In these places, ordinary people become the main characters of local life.","zh":"在這些地方，普通人成為本地生活的主角。"},{"en":"Dai pai dongs are theatres of community because public eating becomes a daily performance of connection.","zh":"大牌檔是社區的劇場，因為公共用餐成為每日連繫的表演。"}],"source":"2016 Q5.pdf","sourcePage":15},{"front":"symbols of local resilience","meaning":"本地韌性的象徵","examples":[{"en":"Dai pai dongs are symbols of local resilience.","zh":"大牌檔是本地韌性的象徵。"},{"en":"Symbols of local resilience are things that show a community’s ability to survive difficulty.","zh":"本地韌性的象徵，是顯示社群面對困難仍能生存的事物。"},{"en":"A small shop that stays open after hard times can be a symbol of local resilience.","zh":"經歷困難後仍開門的小店，可以是本地韌性的象徵。"},{"en":"Local resilience appears when people adapt without losing identity.","zh":"當人們調適而不失去身份，本地韌性就會出現。"},{"en":"Dai pai dongs symbolise local resilience because they grew from hard work and limited space.","zh":"大牌檔象徵本地韌性，因為它們源自辛勤工作和有限空間。"}],"source":"2016 Q5.pdf","sourcePage":16},{"front":"local resilience","meaning":"本地韌性","examples":[{"en":"Dai pai dongs show local resilience.","zh":"大牌檔展現本地韌性。"},{"en":"Local resilience means a community’s ability to endure hardship and keep going.","zh":"本地韌性，意思是社群承受困難並繼續前進的能力。"},{"en":"A neighbourhood shows local resilience when residents help each other after a storm.","zh":"風暴後居民互相幫助時，社區就展現本地韌性。"},{"en":"Local resilience is built through practical skill, memory, and cooperation.","zh":"本地韌性透過實用技巧、記憶和合作建立。"},{"en":"Dai pai dongs show local resilience because families survived by cooking in difficult conditions.","zh":"大牌檔展現本地韌性，因為家庭在困難環境中靠煮食生存。"}],"source":"2016 Q5.pdf","sourcePage":16},{"front":"the time has come for","meaning":"是時候……","examples":[{"en":"The time has come for the government to protect dai pai dongs sensibly.","zh":"是時候讓政府明智地保護大牌檔。"},{"en":"The time has come for someone to do something means now is the right moment for action.","zh":"是時候讓某人做某事，意思是現在是採取行動的合適時刻。"},{"en":"The time has come for the school to repair the old playground.","zh":"是時候讓學校修理舊遊樂場。"},{"en":"This phrase suggests that waiting any longer would be unwise.","zh":"這個短語暗示再等待下去並不明智。"},{"en":"The time has come for Hong Kong to preserve dai pai dongs through practical policy.","zh":"是時候讓香港透過實際政策保育大牌檔。"}],"source":"2016 Q5.pdf","sourcePage":16},{"front":"protect them sensibly","meaning":"明智地保護它們","examples":[{"en":"The government should protect dai pai dongs sensibly.","zh":"政府應明智地保護大牌檔。"},{"en":"To protect them sensibly means to preserve them in a practical, balanced, and careful way.","zh":"明智地保護它們，意思是以實際、平衡和小心的方式保育它們。"},{"en":"A school protects old trees sensibly by checking safety while keeping shade.","zh":"學校透過檢查安全同時保留樹蔭，明智地保護老樹。"},{"en":"Sensible protection solves problems instead of ignoring them.","zh":"明智的保護會解決問題，而不是忽視問題。"},{"en":"Dai pai dongs should be protected sensibly with hygiene rules, licences, and cultural respect.","zh":"大牌檔應透過衞生規則、牌照和文化尊重被明智地保護。"}],"source":"2016 Q5.pdf","sourcePage":16},{"front":"teach their value","meaning":"教導其價值","examples":[{"en":"Schools should teach the value of dai pai dongs.","zh":"學校應教導大牌檔的價值。"},{"en":"To teach their value means to help people understand why they matter.","zh":"教導其價值，意思是幫助人們理解它們為何重要。"},{"en":"Teachers teach the value of old songs by explaining their history.","zh":"老師透過解釋舊歌歷史來教導其價值。"},{"en":"Students protect culture better when they understand its value.","zh":"當學生理解文化價值，他們會更好地保護文化。"},{"en":"Schools can teach the value of dai pai dongs through interviews, food history, and local visits.","zh":"學校可以透過訪問、飲食歷史和本地考察教導大牌檔的價值。"}],"source":"2016 Q5.pdf","sourcePage":16},{"front":"support them willingly","meaning":"自願支持它們","examples":[{"en":"Young people should support dai pai dongs willingly.","zh":"年輕人應自願支持大牌檔。"},{"en":"To support them willingly means to help or choose them freely, not because one is forced.","zh":"自願支持它們，意思是自由地幫助或選擇它們，而不是被迫。"},{"en":"Students support a school event willingly when they believe it matters.","zh":"當學生相信學校活動重要，他們就會自願支持它。"},{"en":"Cultural places survive better when young people support them willingly.","zh":"當年輕人自願支持文化地方，它們會更容易生存。"},{"en":"Young people can support dai pai dongs willingly by eating there and learning their stories.","zh":"年輕人可以透過在大牌檔吃飯和學習其故事來自願支持它們。"}],"source":"2016 Q5.pdf","sourcePage":16},{"front":"if the last wok falls silent","meaning":"如果最後一口鑊沉默下來","examples":[{"en":"If the last wok falls silent, Hong Kong will lose part of itself.","zh":"如果最後一口鑊沉默下來，香港將失去自身的一部分。"},{"en":"If the last wok falls silent means if the final dai pai dong stops cooking and its sounds disappear.","zh":"如果最後一口鑊沉默下來，意思是如果最後的大牌檔停止煮食，其聲音消失。"},{"en":"If the last school bell falls silent, the old campus may feel truly gone.","zh":"如果最後一聲校鐘沉默下來，舊校園可能感覺真正消失了。"},{"en":"This image makes cultural loss feel emotional and concrete.","zh":"這個畫面令文化失落感覺情感化而具體。"},{"en":"If the last wok falls silent, the city loses sound, food, memory, and human warmth.","zh":"如果最後一口鑊沉默下來，城市會失去聲音、食物、記憶和人情味。"}],"source":"2016 Q5.pdf","sourcePage":16},{"front":"fall silent","meaning":"沉寂下來","examples":[{"en":"One day, the last wok may fall silent.","zh":"有一天，最後一口鑊可能會沉寂下來。"},{"en":"To fall silent means to stop making sound.","zh":"沉寂下來，意思是停止發出聲音。"},{"en":"The classroom fell silent when the teacher announced sad news.","zh":"老師宣布傷心消息時，課室沉寂下來。"},{"en":"A place can feel different when its familiar sounds fall silent.","zh":"當熟悉聲音沉寂下來，一個地方會感覺不同。"},{"en":"If dai pai dong woks fall silent, a piece of street life disappears.","zh":"如果大牌檔的鑊聲沉寂下來，一部分街頭生活就會消失。"}],"source":"2016 Q5.pdf","sourcePage":16},{"front":"what disappeared was not just…, but…","meaning":"消失的不只是……而是……","examples":[{"en":"What disappeared was not just a meal, but a piece of ourselves.","zh":"消失的不只是一餐飯，而是我們自身的一部分。"},{"en":"What disappeared was not just A, but B means the loss is deeper than it first appears.","zh":"消失的不只是 A，而是 B，意思是損失比表面看起來更深。"},{"en":"When the old library closed, what disappeared was not just books, but a meeting place.","zh":"當舊圖書館關閉，消失的不只是書本，而是一個聚腳點。"},{"en":"This structure helps writers show emotional and cultural loss.","zh":"這個結構幫助作者表達情感和文化上的失去。"},{"en":"If dai pai dongs vanish, what disappears is not just food, but shared memory.","zh":"如果大牌檔消失，消失的不只是食物，而是共同記憶。"}],"source":"2016 Q5.pdf","sourcePage":16},{"front":"a piece of ourselves","meaning":"我們自身的一部分","examples":[{"en":"Losing dai pai dongs would mean losing a piece of ourselves.","zh":"失去大牌檔意味著失去我們自身的一部分。"},{"en":"A piece of ourselves means an important part of our identity, memory, or shared life.","zh":"我們自身的一部分，意思是我們身份、記憶或共同生活中的重要部分。"},{"en":"Losing a family photo album can feel like losing a piece of ourselves.","zh":"失去家庭相簿可能感覺像失去我們自身的一部分。"},{"en":"Communities lose a piece of themselves when familiar places disappear forever.","zh":"當熟悉地方永遠消失，社群就失去自身的一部分。"},{"en":"Dai pai dongs are a piece of ourselves because they hold Hong Kong’s food, labour, and human warmth.","zh":"大牌檔是我們自身的一部分，因為它們承載香港的食物、勞動和人情味。"}],"source":"2016 Q5.pdf","sourcePage":16}],"dse/writing/part-b/2016/Q6":[{"front":"the taste of honey","meaning":"蜂蜜的滋味","examples":[{"en":"The story is called The Taste of Honey.","zh":"這個故事叫《蜂蜜的滋味》。"},{"en":"The taste of honey means the sweet flavour of honey, but it can also suggest sweetness after pain or effort.","zh":"the taste of honey 指蜂蜜的甜味，也可以暗示痛苦或努力之後的甜美感覺。"},{"en":"A child remembers the taste of honey from tea his grandmother made when he was sick.","zh":"孩子記得生病時祖母泡的茶裏蜂蜜的滋味。"},{"en":"In a story about revenge, the taste of honey can suggest a victory that feels sweet.","zh":"在關於復仇的故事中，蜂蜜的滋味可以暗示勝利的甜味。"},{"en":"This title prepares readers for a story about sweetness, justice and hidden bitterness.","zh":"這個標題讓讀者準備讀一個關於甜美、正義和隱藏苦澀的故事。"}],"source":"2016 Q6.pdf","sourcePage":1},{"front":"by the time","meaning":"到……的時候","examples":[{"en":"By the time the posters appeared, Mary had learned to stay silent.","zh":"到海報出現的時候，Mary 已經學會保持沉默。"},{"en":"By the time means when a later moment arrived, something had already happened.","zh":"by the time 指到某個較後時間時，某事已經發生。"},{"en":"By the time the teacher entered, the students had already opened their books.","zh":"到老師進入課室的時候，學生已經打開書本。"},{"en":"By the time Mary saw the posters, her silence had become a habit.","zh":"到 Mary 看見海報的時候，她的沉默已經成為習慣。"},{"en":"This phrase helps show that one event happened before another important moment.","zh":"這個短語幫助顯示一件事在另一個重要時刻之前已經發生。"}],"source":"2016 Q6.pdf","sourcePage":1},{"front":"Creative Writing Week","meaning":"創意寫作週","examples":[{"en":"The posters for Creative Writing Week appeared along the corridor.","zh":"創意寫作週的海報出現在走廊沿途。"},{"en":"Creative Writing Week is a school event that celebrates writing stories, poems or essays.","zh":"Creative Writing Week 是慶祝寫故事、詩或文章的校園活動。"},{"en":"During Creative Writing Week, students may join competitions, readings and workshops.","zh":"在創意寫作週期間，學生可能參加比賽、朗讀和工作坊。"},{"en":"A Creative Writing Week poster can make students excited to share their ideas.","zh":"創意寫作週的海報可以令學生期待分享自己的想法。"},{"en":"In the story, Creative Writing Week brings back Mary’s painful memory of stolen work.","zh":"在故事中，創意寫作週勾起 Mary 作品被偷的痛苦記憶。"}],"source":"2016 Q6.pdf","sourcePage":1},{"front":"appear along the corridor","meaning":"出現在走廊沿途","examples":[{"en":"The posters appeared along the corridor before the competition.","zh":"比賽前，海報出現在走廊沿途。"},{"en":"Appear along the corridor means become visible on the walls or spaces beside a hallway.","zh":"appear along the corridor 指出現在走廊旁的牆上或空間中。"},{"en":"Exam notices appeared along the corridor before the school assessment week.","zh":"學校評估週前，考試告示出現在走廊沿途。"},{"en":"When colourful posters appear along the corridor, students know an event is coming.","zh":"當彩色海報出現在走廊沿途，學生就知道有活動快要來臨。"},{"en":"This phrase helps set a school scene in a simple, visual way.","zh":"這個短語用簡單而有畫面的方式建立校園場景。"}],"source":"2016 Q6.pdf","sourcePage":1},{"front":"silence could be worn like","meaning":"沉默可以像……一樣穿在身上","examples":[{"en":"Mary learned that silence could be worn like a school cardigan.","zh":"Mary 學會了沉默可以像校服冷衫一樣穿在身上。"},{"en":"Silence could be worn like something means silence can become a protective outer layer people show to others.","zh":"silence could be worn like something 指沉默可以成為人展示給別人的保護外層。"},{"en":"A shy student may wear silence like armour when classmates tease her.","zh":"被同學取笑時，害羞的學生可能把沉默像盔甲一樣穿在身上。"},{"en":"Mary wears silence like clothing because it helps hide anger and hurt.","zh":"Mary 把沉默像衣服一樣穿上，因為它幫她隱藏憤怒和傷痛。"},{"en":"This phrase turns silence into something visible and protective.","zh":"這個短語把沉默變成可見而具保護性的東西。"}],"source":"2016 Q6.pdf","sourcePage":1},{"front":"school cardigan","meaning":"校服冷衫","examples":[{"en":"She compared silence to a school cardigan.","zh":"她把沉默比作校服冷衫。"},{"en":"A school cardigan is a knitted sweater worn as part of a school uniform.","zh":"school cardigan 是校服的一部分，是針織外套。"},{"en":"Students may wear a school cardigan when the classroom is cold.","zh":"課室寒冷時，學生可能穿校服冷衫。"},{"en":"A school cardigan can look ordinary while hiding a stain or torn shirt underneath.","zh":"校服冷衫可以看起來普通，卻遮住底下的污漬或破損恤衫。"},{"en":"In the story, the school cardigan shows how silence can hide Mary’s pain.","zh":"在故事中，校服冷衫顯示沉默如何隱藏 Mary 的痛苦。"}],"source":"2016 Q6.pdf","sourcePage":1},{"front":"useful for hiding stains","meaning":"可用來遮掩污漬","examples":[{"en":"The cardigan was ordinary, neat and useful for hiding stains.","zh":"那件冷衫普通、整齊，而且可用來遮掩污漬。"},{"en":"Useful for hiding stains means good at covering dirty marks so others cannot see them.","zh":"useful for hiding stains 指適合遮住污痕，讓別人看不見。"},{"en":"A dark jacket is useful for hiding stains after art class.","zh":"美術課後，深色外套可用來遮掩污漬。"},{"en":"Silence can be useful for hiding emotional stains such as shame or anger.","zh":"沉默也可以用來遮掩羞恥或憤怒等情緒上的污漬。"},{"en":"This phrase links a simple object with Mary’s hidden hurt.","zh":"這個短語把簡單物件與 Mary 隱藏的傷痛連在一起。"}],"source":"2016 Q6.pdf","sourcePage":1},{"front":"steal my short story","meaning":"偷走我的短篇故事","examples":[{"en":"Chris had stolen Mary’s short story.","zh":"Chris 偷走了 Mary 的短篇故事。"},{"en":"To steal my short story means to take my written story and pretend it is yours.","zh":"steal my short story 指拿走我寫的故事，並假裝是自己的作品。"},{"en":"A student steals a short story if he copies another person’s work and submits it under his own name.","zh":"如果學生抄襲別人的作品並用自己名字提交，就是偷走別人的短篇故事。"},{"en":"Stealing someone’s short story hurts because it takes both their words and their effort.","zh":"偷走別人的短篇故事令人受傷，因為它奪走了文字和努力。"},{"en":"In the story, this theft is the reason Mary wants justice.","zh":"在故事中，這次偷竊是 Mary 想要正義的原因。"}],"source":"2016 Q6.pdf","sourcePage":1},{"front":"inside my head","meaning":"在我腦海裏","examples":[{"en":"“Stolen” was a word Mary used only inside her head.","zh":"「偷走」是 Mary 只在腦海裏使用的字。"},{"en":"Inside my head means privately in my thoughts, not spoken aloud.","zh":"inside my head 指只在自己的想法中，沒有說出口。"},{"en":"I called the idea unfair inside my head, but I said nothing in class.","zh":"我在腦海裏覺得那個想法不公平，但在課堂上甚麼也沒有說。"},{"en":"Mary keeps the word “stolen” inside her head because she has no proof.","zh":"Mary 把「偷走」這個字留在腦海裏，因為她沒有證據。"},{"en":"This phrase shows the difference between private truth and public speech.","zh":"這個短語顯示私人真相和公開說話之間的分別。"}],"source":"2016 Q6.pdf","sourcePage":1},{"front":"in public","meaning":"在公開場合","examples":[{"en":"In public, people called it similarity or coincidence.","zh":"在公開場合，人們把它稱為相似或巧合。"},{"en":"In public means where other people can hear, see or judge what is said.","zh":"in public 指在別人可以聽見、看見或評價的地方。"},{"en":"In public, students should speak respectfully even when they disagree.","zh":"在公開場合，學生即使不同意也應有禮貌地說話。"},{"en":"Mary cannot accuse Chris in public because people may not believe her.","zh":"Mary 不能在公開場合指控 Chris，因為別人可能不相信她。"},{"en":"This phrase contrasts what is said openly with what someone privately thinks.","zh":"這個短語把公開說法與私人想法形成對比。"}],"source":"2016 Q6.pdf","sourcePage":1},{"front":"similarity and coincidence","meaning":"相似和巧合","examples":[{"en":"People described the stolen story as similarity and coincidence.","zh":"人們把被偷的故事描述為相似和巧合。"},{"en":"Similarity and coincidence mean things look alike, but people claim it happened by chance.","zh":"similarity and coincidence 指事情看起來相似，但人們聲稱那只是偶然。"},{"en":"Two students may use similar titles by coincidence if the topic is common.","zh":"如果題目很常見，兩名學生可能巧合地使用相似標題。"},{"en":"Calling theft “similarity and coincidence” can make a serious act sound harmless.","zh":"把偷竊稱為「相似和巧合」，可以令嚴重行為聽起來無害。"},{"en":"In the story, these words protect Chris and silence Mary.","zh":"在故事中，這些字保護了 Chris，也令 Mary 沉默。"}],"source":"2016 Q6.pdf","sourcePage":2},{"front":"submit my story","meaning":"提交我的故事","examples":[{"en":"Chris submitted Mary’s story under his own name.","zh":"Chris 用自己的名字提交了 Mary 的故事。"},{"en":"Submit my story means hand in my written work for a teacher, judge or competition to read.","zh":"submit my story 指把我寫的作品交給老師、評審或比賽閱讀。"},{"en":"A student submits a story online before the deadline.","zh":"學生在截止日期前在網上提交故事。"},{"en":"Submitting someone else’s story under your own name is dishonest.","zh":"用自己的名字提交別人的故事是不誠實的。"},{"en":"This phrase shows how Chris turned Mary’s work into his public success.","zh":"這個短語顯示 Chris 如何把 Mary 的作品變成自己的公開成功。"}],"source":"2016 Q6.pdf","sourcePage":2},{"front":"paper lanterns","meaning":"紙燈籠","examples":[{"en":"The original story was about an old woman selling paper lanterns.","zh":"原本的故事是關於一位賣紙燈籠的老婦人。"},{"en":"Paper lanterns are light decorations made from paper, often used in festivals or celebrations.","zh":"paper lanterns 是用紙製成的輕巧裝飾，常用於節日或慶祝活動。"},{"en":"Children may carry paper lanterns during a night festival.","zh":"孩子可能在夜間節日提着紙燈籠。"},{"en":"Paper lanterns can make a story feel warm, traditional and visual.","zh":"紙燈籠可以令故事感覺溫暖、傳統而有畫面。"},{"en":"In Mary’s original story, paper lanterns are part of the world Chris stole.","zh":"在 Mary 的原稿中，紙燈籠是 Chris 偷走的故事世界的一部分。"}],"source":"2016 Q6.pdf","sourcePage":2},{"front":"change the names","meaning":"改掉名字","examples":[{"en":"Chris changed the names in Mary’s story.","zh":"Chris 改掉了 Mary 故事中的名字。"},{"en":"Change the names means replace the names of characters or places with different ones.","zh":"change the names 指把人物或地方的名字換成其他名字。"},{"en":"A writer may change the names in a draft to protect real people’s privacy.","zh":"作者可能在草稿中改掉名字，以保護真人私隱。"},{"en":"Chris changes the names to make Mary’s story look like his own.","zh":"Chris 改掉名字，是為了令 Mary 的故事看似自己的作品。"},{"en":"This phrase shows a small surface change that hides a larger theft.","zh":"這個短語顯示表面的小改動如何掩蓋更大的偷竊。"}],"source":"2016 Q6.pdf","sourcePage":2},{"front":"polish two metaphors","meaning":"修飾兩個比喻","examples":[{"en":"Chris polished two metaphors and won first prize.","zh":"Chris 修飾了兩個比喻，然後贏得一等獎。"},{"en":"Polish two metaphors means improve two comparisons so they sound smoother or more beautiful.","zh":"polish two metaphors 指改善兩個比喻，令它們聽起來更順暢或更美。"},{"en":"A teacher may help a student polish a metaphor before a writing competition.","zh":"寫作比賽前，老師可能幫學生修飾一個比喻。"},{"en":"Polishing two metaphors does not make a stolen story original.","zh":"修飾兩個比喻並不會令被偷的故事變成原創。"},{"en":"This phrase shows how little Chris changed before taking credit.","zh":"這個短語顯示 Chris 在據為己有前其實改動很少。"}],"source":"2016 Q6.pdf","sourcePage":2},{"front":"win first prize","meaning":"贏得一等獎","examples":[{"en":"Chris won first prize with Mary’s story.","zh":"Chris 用 Mary 的故事贏得一等獎。"},{"en":"Win first prize means receive the top award in a competition.","zh":"win first prize 指在比賽中得到最高獎項。"},{"en":"A student may win first prize if her poem is the strongest entry.","zh":"如果學生的詩是最出色的參賽作品，她可能贏得一等獎。"},{"en":"Winning first prize with someone else’s work is unfair and dishonest.","zh":"用別人的作品贏得一等獎是不公平和不誠實的。"},{"en":"In the story, Chris’s prize makes Mary’s silence even more painful.","zh":"在故事中，Chris 的獎項令 Mary 的沉默更加痛苦。"}],"source":"2016 Q6.pdf","sourcePage":2},{"front":"without proof","meaning":"沒有證據","examples":[{"en":"Without proof, Mary’s anger sounded childish.","zh":"沒有證據，Mary 的憤怒聽起來很幼稚。"},{"en":"Without proof means without evidence that can show something is true.","zh":"without proof 指沒有能顯示某事是真的的證據。"},{"en":"Without proof, a teacher cannot punish a student for copying.","zh":"沒有證據，老師不能因抄襲而懲罰學生。"},{"en":"Mary knows that without proof, people may treat her pain as jealousy.","zh":"Mary 知道沒有證據時，人們可能把她的痛苦當成嫉妒。"},{"en":"This phrase shows why truth can be hard to defend.","zh":"這個短語顯示為何真相有時難以捍衛。"}],"source":"2016 Q6.pdf","sourcePage":2},{"front":"sound childish","meaning":"聽起來幼稚","examples":[{"en":"Her anger sounded childish because she had no proof.","zh":"她的憤怒聽起來幼稚，因為她沒有證據。"},{"en":"Sound childish means seem immature, unreasonable or not serious.","zh":"sound childish 指聽起來不成熟、不合理或不嚴肅。"},{"en":"A complaint may sound childish if it is full of shouting but no facts.","zh":"如果投訴只有大叫而沒有事實，可能聽起來幼稚。"},{"en":"Mary’s anger sounds childish to others because they cannot see the evidence.","zh":"Mary 的憤怒在別人耳中聽起來幼稚，因為他們看不見證據。"},{"en":"This phrase shows how unfair situations can make real pain look small.","zh":"這個短語顯示不公平處境如何令真正痛苦看似微不足道。"}],"source":"2016 Q6.pdf","sourcePage":2},{"front":"the panel","meaning":"評審團","examples":[{"en":"The panel smiled but did not help Mary.","zh":"評審團微笑了，卻沒有幫助 Mary。"},{"en":"The panel is a group of people chosen to judge, discuss or decide something.","zh":"panel 是被選來評審、討論或決定某事的一群人。"},{"en":"The writing competition panel read each story before choosing the winner.","zh":"寫作比賽評審團在選出得獎者前閱讀每篇故事。"},{"en":"A panel should listen carefully when a student raises a serious concern.","zh":"當學生提出嚴重關注時，評審團應仔細聆聽。"},{"en":"In the story, the panel’s polite smile does not bring Mary justice.","zh":"在故事中，評審團禮貌的微笑沒有為 Mary 帶來正義。"}],"source":"2016 Q6.pdf","sourcePage":2},{"front":"leave someone with more questions than answers","meaning":"令某人留下更多疑問而非答案","examples":[{"en":"The panel left Mary with more questions than answers.","zh":"評審團令 Mary 留下更多疑問而非答案。"},{"en":"To leave someone with more questions than answers means make them feel more confused instead of giving clarity.","zh":"leave someone with more questions than answers 指令人更加困惑，而不是得到清楚答案。"},{"en":"The teacher’s vague reply left the class with more questions than answers.","zh":"老師含糊的回應令全班留下更多疑問而非答案。"},{"en":"When adults avoid the truth, they can leave students with more questions than answers.","zh":"當成年人迴避真相，他們可能令學生留下更多疑問而非答案。"},{"en":"This phrase shows that Mary received no real explanation or help.","zh":"這個短語顯示 Mary 沒有得到真正解釋或幫助。"}],"source":"2016 Q6.pdf","sourcePage":2},{"front":"stop raising my hand","meaning":"不再舉手","examples":[{"en":"After that, Mary stopped raising her hand in English lessons.","zh":"從那以後，Mary 在英文課上不再舉手。"},{"en":"Stop raising my hand means no longer put up my hand to answer or speak in class.","zh":"stop raising my hand 指不再在課堂上舉手回答或發言。"},{"en":"A student may stop raising her hand after being laughed at.","zh":"學生被取笑後，可能不再舉手。"},{"en":"Mary stops raising her hand because speaking up no longer feels safe.","zh":"Mary 不再舉手，因為發聲不再令她感到安全。"},{"en":"This phrase shows how unfair treatment can silence a student.","zh":"這個短語顯示不公平對待如何令學生沉默。"}],"source":"2016 Q6.pdf","sourcePage":3},{"front":"borrow my fountain pen","meaning":"借我的鋼筆","examples":[{"en":"Chris once borrowed Mary’s fountain pen.","zh":"Chris 曾經借過 Mary 的鋼筆。"},{"en":"Borrow my fountain pen means take my ink pen for a short time and promise to return it.","zh":"borrow my fountain pen 指短暫拿走我的墨水筆，並承諾歸還。"},{"en":"A classmate may borrow my fountain pen during a writing test.","zh":"同學可能在寫作測驗中借我的鋼筆。"},{"en":"Borrowing a fountain pen seems small, but returning it empty shows selfishness.","zh":"借鋼筆看似小事，但用光後才還就顯得自私。"},{"en":"In the story, this detail reminds readers of Chris’s habit of taking things.","zh":"在故事中，這個細節提醒讀者 Chris 有拿走別人東西的習慣。"}],"source":"2016 Q6.pdf","sourcePage":3},{"front":"return it empty","meaning":"把它用光後歸還","examples":[{"en":"Chris returned the fountain pen empty.","zh":"Chris 把鋼筆用光後歸還。"},{"en":"Return it empty means give something back after using up what was inside.","zh":"return it empty 指把裏面的東西用完後才歸還。"},{"en":"My brother borrowed my water bottle and returned it empty.","zh":"弟弟借了我的水樽，然後把它喝光後還給我。"},{"en":"Returning a borrowed pen empty is careless because the owner cannot use it later.","zh":"把借來的筆用光後歸還很粗心，因為物主之後不能使用。"},{"en":"This phrase shows a small act of disrespect.","zh":"這個短語顯示一種細小的不尊重。"}],"source":"2016 Q6.pdf","sourcePage":3},{"front":"this year’s theme was announced","meaning":"今年的主題被公布","examples":[{"en":"This year’s theme was announced as Revenge is Sweet.","zh":"今年的主題被公布為「復仇是甜蜜的」。"},{"en":"This year’s theme was announced means the topic for this year was officially made known.","zh":"this year’s theme was announced 指今年的題目被正式公開。"},{"en":"The debate topic was announced during morning assembly.","zh":"辯論題目在早會中被公布。"},{"en":"When the theme was announced, students began planning their stories.","zh":"主題公布後，學生開始構思故事。"},{"en":"In the story, the announced theme gives Mary a chance to act.","zh":"在故事中，被公布的主題給了 Mary 行動的機會。"}],"source":"2016 Q6.pdf","sourcePage":3},{"front":"Revenge is Sweet","meaning":"復仇是甜蜜的","examples":[{"en":"The theme of the competition was Revenge is Sweet.","zh":"比賽的主題是「復仇是甜蜜的」。"},{"en":"Revenge is Sweet means getting back at someone can feel satisfying, especially after being wronged.","zh":"Revenge is Sweet 指向傷害自己的人報復可能令人感到滿足。"},{"en":"A story titled Revenge is Sweet may show a character planning justice carefully.","zh":"題為「復仇是甜蜜的」的故事可能展示人物仔細策劃正義。"},{"en":"Revenge can feel sweet at first, but it may become bitter if it is only cruel.","zh":"復仇起初可能甜蜜，但如果只是殘忍，也可能變苦。"},{"en":"In Mary’s story, the phrase connects revenge with proof, justice and voice.","zh":"在 Mary 的故事中，這句話把復仇與證據、正義和聲音連在一起。"}],"source":"2016 Q6.pdf","sourcePage":3},{"front":"no one saw me coming","meaning":"沒有人預料到我會出手","examples":[{"en":"No one saw Mary coming.","zh":"沒有人預料到 Mary 會出手。"},{"en":"No one saw me coming means nobody expected me to act or become a threat.","zh":"no one saw me coming 指沒有人預料到我會行動或成為威脅。"},{"en":"The quiet student won the debate because no one saw her coming.","zh":"那個安靜學生贏了辯論，因為沒有人預料到她會出手。"},{"en":"Chris did not see Mary coming because he mistook her silence for weakness.","zh":"Chris 沒預料到 Mary 會出手，因為他錯把她的沉默當成軟弱。"},{"en":"This phrase suggests a hidden plan and a surprising change in power.","zh":"這個短語暗示隱藏計劃和權力上的驚人轉變。"}],"source":"2016 Q6.pdf","sourcePage":3},{"front":"for three nights","meaning":"連續三晚","examples":[{"en":"For three nights, Mary wrote a story called The Honey Jar.","zh":"Mary 連續三晚寫了一個名為《蜂蜜罐》的故事。"},{"en":"For three nights means during three separate nights in a row or within a short period.","zh":"for three nights 指在三個晚上裏，通常是連續或短時間內。"},{"en":"For three nights, the student stayed up revising for the exam.","zh":"那名學生連續三晚熬夜溫習考試。"},{"en":"Mary writes for three nights because her plan needs care and patience.","zh":"Mary 連續三晚寫作，因為她的計劃需要細心和耐性。"},{"en":"This phrase shows repeated effort over time.","zh":"這個短語顯示一段時間內的反覆努力。"}],"source":"2016 Q6.pdf","sourcePage":3},{"front":"a story called","meaning":"一個名為……的故事","examples":[{"en":"Mary wrote a story called The Honey Jar.","zh":"Mary 寫了一個名為《蜂蜜罐》的故事。"},{"en":"A story called something means a story with that title.","zh":"a story called something 指以某個名稱為題的故事。"},{"en":"The class read a story called The Last Train.","zh":"全班讀了一個名為《最後一班火車》的故事。"},{"en":"A title can guide readers toward the mood or meaning of a story.","zh":"標題可以引導讀者理解故事的氣氛或意思。"},{"en":"In this case, the story called The Honey Jar hides Mary’s trap inside sweetness.","zh":"在這裏，名為《蜂蜜罐》的故事把 Mary 的陷阱藏在甜味裏。"}],"source":"2016 Q6.pdf","sourcePage":3},{"front":"steal recipes from","meaning":"從……偷食譜","examples":[{"en":"The boy stole recipes from his grandmother.","zh":"那個男孩從祖母那裏偷食譜。"},{"en":"Steal recipes from someone means take their cooking instructions without permission or credit.","zh":"steal recipes from someone 指未經許可或不給 credit 就拿走別人的烹飪方法。"},{"en":"A blogger steals recipes from others if she copies them and posts them as her own.","zh":"如果博客複製別人的食譜並當成自己的發布，就是從別人那裏偷食譜。"},{"en":"In Mary’s story, stealing recipes mirrors Chris stealing her writing.","zh":"在 Mary 的故事中，偷食譜對應 Chris 偷她的作品。"},{"en":"This phrase makes theft easier to understand through a familiar home example.","zh":"這個短語透過熟悉的家庭例子令偷竊更容易理解。"}],"source":"2016 Q6.pdf","sourcePage":3},{"front":"become famous for","meaning":"因……而成名","examples":[{"en":"The boy became famous for cakes he could not bake.","zh":"那個男孩因自己不會焗製的蛋糕而成名。"},{"en":"Become famous for something means be widely known because of that thing.","zh":"become famous for something 指因某事而廣為人知。"},{"en":"A singer may become famous for one song before releasing an album.","zh":"歌手可能在推出專輯前先因一首歌而成名。"},{"en":"Becoming famous for work you cannot actually do is dishonest.","zh":"因自己其實不會做的作品而成名是不誠實的。"},{"en":"In the story, the boy’s fame exposes the unfairness Mary experienced.","zh":"在故事中，男孩的名聲揭露了 Mary 經歷的不公平。"}],"source":"2016 Q6.pdf","sourcePage":3},{"front":"could not bake","meaning":"不會焗製","examples":[{"en":"The boy became famous for cakes he could not bake.","zh":"那個男孩因自己不會焗製的蛋糕而成名。"},{"en":"Could not bake means did not have the ability to make cakes or bread in an oven.","zh":"could not bake 指沒有能力用焗爐製作蛋糕或麵包。"},{"en":"He sold cakes from his grandmother’s recipe, but he could not bake them himself.","zh":"他賣祖母食譜中的蛋糕，但自己不會焗製。"},{"en":"If someone becomes praised for food they could not bake, the credit is false.","zh":"如果有人因自己不會焗製的食物受讚賞，那份 credit 就是假的。"},{"en":"This phrase shows the gap between reputation and real ability.","zh":"這個短語顯示名聲和真正能力之間的差距。"}],"source":"2016 Q6.pdf","sourcePage":4},{"front":"each paragraph began","meaning":"每一段開始時","examples":[{"en":"Each paragraph began innocently enough.","zh":"每一段開始時都看似平常。"},{"en":"Each paragraph began means every separate section of writing started in a certain way.","zh":"each paragraph began 指每個獨立段落以某種方式開始。"},{"en":"Each paragraph began with a simple sentence before the argument became stronger.","zh":"每一段開始時都有一句簡單句子，然後論點變得更有力。"},{"en":"In Mary’s story, each paragraph began normally but secretly carried a message.","zh":"在 Mary 的故事中，每一段開始時都正常，但偷偷帶着一段信息。"},{"en":"This phrase draws attention to structure and hidden design.","zh":"這個短語把注意力放在結構和隱藏設計上。"}],"source":"2016 Q6.pdf","sourcePage":4},{"front":"innocently enough","meaning":"看似無辜地；看似平常地","examples":[{"en":"Each paragraph began innocently enough.","zh":"每一段開始時都看似無辜。"},{"en":"Innocently enough means seeming harmless or ordinary at first.","zh":"innocently enough 指起初看起來無害或普通。"},{"en":"The joke began innocently enough, but it soon hurt someone’s feelings.","zh":"那個笑話開始時看似無辜，但很快傷害了別人的感受。"},{"en":"Mary’s paragraphs looked innocently enough until the first letters were read together.","zh":"Mary 的段落看似平常，直到首字母被連起來讀。"},{"en":"This phrase often suggests that something harmless may hide a deeper purpose.","zh":"這個短語常暗示看似無害的東西可能藏着更深目的。"}],"source":"2016 Q6.pdf","sourcePage":4},{"front":"the first letters formed a sentence","meaning":"首字母拼成一句句子","examples":[{"en":"The first letters formed a sentence accusing Chris.","zh":"首字母拼成一句指控 Chris 的句子。"},{"en":"The first letters formed a sentence means the opening letters joined together to make words.","zh":"the first letters formed a sentence 指開頭字母連起來組成文字。"},{"en":"In an acrostic poem, the first letters formed a sentence down the page.","zh":"在藏頭詩中，首字母沿頁面向下拼成一句句子。"},{"en":"Mary uses the first letters to hide an accusation in plain sight.","zh":"Mary 用首字母把指控藏在眾人眼前。"},{"en":"This phrase explains the secret mechanism of her trap.","zh":"這個短語解釋她陷阱的秘密機制。"}],"source":"2016 Q6.pdf","sourcePage":4},{"front":"better still","meaning":"更妙的是","examples":[{"en":"Better still, Mary planted details only she could explain.","zh":"更妙的是，Mary 埋下了只有她能解釋的細節。"},{"en":"Better still means even better than the previous point.","zh":"better still 指比剛才提到的更好。"},{"en":"The essay had clear examples; better still, it used personal experience.","zh":"那篇文章有清楚例子；更妙的是，它用了個人經歷。"},{"en":"Mary hides a message; better still, she adds details that prove authorship.","zh":"Mary 藏了一段信息；更妙的是，她加入能證明作者身份的細節。"},{"en":"This phrase introduces an extra advantage.","zh":"這個短語引入額外優勢。"}],"source":"2016 Q6.pdf","sourcePage":4},{"front":"plant details","meaning":"埋下細節","examples":[{"en":"Mary planted details only she could explain.","zh":"Mary 埋下了只有她能解釋的細節。"},{"en":"Plant details means deliberately place small clues inside a story or plan.","zh":"plant details 指有意把小線索放進故事或計劃中。"},{"en":"A mystery writer plants details early so the ending feels fair.","zh":"懸疑作家會早早埋下細節，令結局顯得合理。"},{"en":"Mary plants details to prove the story belongs to her.","zh":"Mary 埋下細節，是為了證明故事屬於她。"},{"en":"This phrase suggests careful planning rather than accident.","zh":"這個短語暗示仔細策劃，而不是偶然。"}],"source":"2016 Q6.pdf","sourcePage":4},{"front":"only I could explain","meaning":"只有我能解釋","examples":[{"en":"She planted details only she could explain.","zh":"她埋下了只有她能解釋的細節。"},{"en":"Only I could explain means no one else had the knowledge needed to make sense of it.","zh":"only I could explain 指只有我擁有所需知識去說明它。"},{"en":"I added a family joke only I could explain to prove the story was mine.","zh":"我加入了一個只有我能解釋的家庭笑話，以證明故事是我的。"},{"en":"Details only Mary could explain make Chris’s theft harder to deny.","zh":"只有 Mary 能解釋的細節令 Chris 更難否認偷竊。"},{"en":"This phrase shows how private knowledge becomes evidence.","zh":"這個短語顯示私人知識如何變成證據。"}],"source":"2016 Q6.pdf","sourcePage":4},{"front":"original draft","meaning":"原稿","examples":[{"en":"Mary included one sentence from her original draft.","zh":"Mary 加入了原稿中的一句句子。"},{"en":"An original draft is the first or earlier version of a piece of writing.","zh":"original draft 指一篇作品最初或較早的版本。"},{"en":"A student may keep an original draft to show how her essay developed.","zh":"學生可能保留原稿，以顯示文章如何發展。"},{"en":"Mary’s original draft helps prove she had written the idea before Chris used it.","zh":"Mary 的原稿幫助證明她在 Chris 使用之前已經寫出那個想法。"},{"en":"This phrase connects the final story to Mary’s earlier work.","zh":"這個短語把最後故事與 Mary 較早的作品連在一起。"}],"source":"2016 Q6.pdf","sourcePage":4},{"front":"print two copies","meaning":"列印兩份","examples":[{"en":"On Friday afternoon, Mary printed two copies.","zh":"星期五下午，Mary 列印了兩份。"},{"en":"Print two copies means produce two paper versions of a document.","zh":"print two copies 指把文件列印成兩份紙本。"},{"en":"The student printed two copies of her speech, one for herself and one for the teacher.","zh":"學生列印兩份演講稿，一份給自己，一份給老師。"},{"en":"Mary prints two copies so one can be bait and one can be evidence.","zh":"Mary 列印兩份，讓一份作誘餌，一份作證據。"},{"en":"This phrase shows preparation before the trap begins.","zh":"這個短語顯示陷阱開始前的準備。"}],"source":"2016 Q6.pdf","sourcePage":4},{"front":"go into my bag","meaning":"放進我的袋裏","examples":[{"en":"One copy went into Mary’s bag.","zh":"其中一份放進 Mary 的袋裏。"},{"en":"Go into my bag means be placed inside my bag.","zh":"go into my bag 指被放進我的袋裏。"},{"en":"The permission slip went into my bag so I would not forget it.","zh":"家長同意書放進我的袋裏，免得我忘記。"},{"en":"Mary keeps one copy in her bag to protect her evidence.","zh":"Mary 把其中一份放進袋裏，以保護證據。"},{"en":"This phrase shows where an important object is safely kept.","zh":"這個短語顯示重要物件被安全保管的位置。"}],"source":"2016 Q6.pdf","sourcePage":4},{"front":"leave beneath a dictionary","meaning":"留在字典下面","examples":[{"en":"Mary left the other copy beneath a dictionary.","zh":"Mary 把另一份留在字典下面。"},{"en":"Leave beneath a dictionary means place something under a dictionary and leave it there.","zh":"leave beneath a dictionary 指把某物放在字典下面並留在那裏。"},{"en":"A student may leave a note beneath a dictionary so only one person notices it.","zh":"學生可能把紙條留在字典下面，讓只有一個人注意到。"},{"en":"Mary leaves the story beneath a dictionary to make Chris think he found it by chance.","zh":"Mary 把故事留在字典下面，令 Chris 以為自己偶然發現它。"},{"en":"This phrase shows how an ordinary object becomes part of a trap.","zh":"這個短語顯示普通物件如何成為陷阱的一部分。"}],"source":"2016 Q6.pdf","sourcePage":5},{"front":"title page facing up","meaning":"封面朝上","examples":[{"en":"The title page was facing up beneath the dictionary.","zh":"封面朝上地放在字典下面。"},{"en":"Title page facing up means the front page with the title was placed where it could be seen.","zh":"title page facing up 指寫有標題的首頁朝上，讓人看得見。"},{"en":"The report lay on the desk with its title page facing up.","zh":"報告放在桌上，封面朝上。"},{"en":"Mary leaves the title page facing up so Chris will notice the story quickly.","zh":"Mary 讓封面朝上，好令 Chris 很快注意到故事。"},{"en":"This phrase shows that the placement was deliberate.","zh":"這個短語顯示擺放方式是刻意安排的。"}],"source":"2016 Q6.pdf","sourcePage":5},{"front":"as though","meaning":"好像；彷彿","examples":[{"en":"She left the story there as though she had forgotten it.","zh":"她把故事留在那裏，好像自己忘記了它。"},{"en":"As though means as if, or in a way that makes something seem true.","zh":"as though 指好像或彷彿某事是真的。"},{"en":"He acted as though he had not heard the question.","zh":"他表現得好像沒有聽到問題。"},{"en":"Mary leaves the story as though it was an accident, but it is actually planned.","zh":"Mary 把故事留下，彷彿是意外，但其實是計劃。"},{"en":"This phrase helps show appearance that hides reality.","zh":"這個短語幫助顯示外表如何隱藏現實。"}],"source":"2016 Q6.pdf","sourcePage":5},{"front":"email the same file to","meaning":"把同一個檔案電郵給……","examples":[{"en":"Mary emailed the same file to Mrs Chan.","zh":"Mary 把同一個檔案電郵給 Chan 老師。"},{"en":"Email the same file to someone means send the identical document to that person by email.","zh":"email the same file to someone 指透過電郵把完全相同的文件寄給某人。"},{"en":"A student may email the same file to herself as a backup.","zh":"學生可能把同一個檔案電郵給自己作備份。"},{"en":"Mary emails the same file to Mrs Chan so there is a dated record.","zh":"Mary 把同一個檔案電郵給 Chan 老師，讓它有日期紀錄。"},{"en":"This phrase shows how digital evidence can support a claim.","zh":"這個短語顯示數碼證據如何支持主張。"}],"source":"2016 Q6.pdf","sourcePage":5},{"front":"evidence, if necessary","meaning":"如有需要，可作證據","examples":[{"en":"Mary sent the file as evidence, if necessary.","zh":"Mary 寄出檔案，如有需要，可作證據。"},{"en":"Evidence, if necessary means proof that can be used if the situation requires it.","zh":"evidence, if necessary 指如果情況需要，可以用來證明某事的證據。"},{"en":"Keep the receipt as evidence, if necessary, when returning a product.","zh":"退貨時保留收據，如有需要，可作證據。"},{"en":"Mary does not show the email immediately, but she has it as evidence if necessary.","zh":"Mary 沒有立刻展示電郵，但如有需要，它可以作證據。"},{"en":"This phrase suggests quiet preparation for a possible challenge.","zh":"這個短語暗示為可能的挑戰作安靜準備。"}],"source":"2016 Q6.pdf","sourcePage":5},{"front":"sit three tables away","meaning":"坐在三張桌子之外","examples":[{"en":"Mary sat three tables away and watched.","zh":"Mary 坐在三張桌子之外觀察。"},{"en":"Sit three tables away means sit at a distance of three tables from someone or something.","zh":"sit three tables away 指坐在距離某人或某物三張桌子的位置。"},{"en":"I sat three tables away from my friend during the exam.","zh":"考試時，我坐在朋友三張桌子之外。"},{"en":"Mary sits three tables away so she can watch Chris without attracting attention.","zh":"Mary 坐在三張桌子之外，這樣她可以觀察 Chris 而不引人注意。"},{"en":"This phrase creates a scene of quiet observation.","zh":"這個短語營造安靜觀察的場面。"}],"source":"2016 Q6.pdf","sourcePage":5},{"front":"glance around","meaning":"環顧四周","examples":[{"en":"Chris glanced around before lifting the dictionary.","zh":"Chris 拿起字典前環顧四周。"},{"en":"Glance around means look quickly in different directions.","zh":"glance around 指快速向不同方向看一看。"},{"en":"A student may glance around before passing a secret note.","zh":"學生傳秘密紙條前可能會環顧四周。"},{"en":"Chris glances around because he knows he is doing something wrong.","zh":"Chris 環顧四周，因為他知道自己在做錯事。"},{"en":"This phrase suggests nervousness or guilt without saying it directly.","zh":"這個短語不直接說明，卻暗示緊張或心虛。"}],"source":"2016 Q6.pdf","sourcePage":5},{"front":"lift the dictionary","meaning":"拿起字典","examples":[{"en":"Chris lifted the dictionary and found the story.","zh":"Chris 拿起字典，發現了那個故事。"},{"en":"Lift the dictionary means pick up the dictionary from where it is lying.","zh":"lift the dictionary 指把放着的字典拿起來。"},{"en":"The student lifted the dictionary to find the worksheet underneath.","zh":"學生拿起字典，找到下面的工作紙。"},{"en":"When Chris lifts the dictionary, he finds the bait Mary left for him.","zh":"Chris 拿起字典時，發現 Mary 留給他的誘餌。"},{"en":"This simple action begins the trap.","zh":"這個簡單動作開始了陷阱。"}],"source":"2016 Q6.pdf","sourcePage":5},{"front":"a guilty smile","meaning":"心虛的笑容","examples":[{"en":"Chris did not give Mary a guilty smile.","zh":"Chris 沒有給 Mary 一個心虛的笑容。"},{"en":"A guilty smile is a smile that suggests someone knows they have done something wrong.","zh":"guilty smile 指暗示某人知道自己做錯事的笑容。"},{"en":"The child gave a guilty smile after eating the last biscuit.","zh":"孩子吃掉最後一塊餅乾後露出心虛的笑容。"},{"en":"Mary expects guilt, but Chris’s face shows hunger instead.","zh":"Mary 以為會看見心虛，但 Chris 的表情顯示的是貪婪。"},{"en":"This phrase helps readers notice the difference between shame and greed.","zh":"這個短語幫助讀者留意羞愧和貪婪的分別。"}],"source":"2016 Q6.pdf","sourcePage":5},{"front":"too simple","meaning":"太簡單","examples":[{"en":"A guilty smile would have been too simple.","zh":"心虛的笑容會太簡單了。"},{"en":"Too simple means too easy, plain or straightforward for the situation.","zh":"too simple 指對某個情況而言太容易、太平直或太單純。"},{"en":"The mystery was too simple if the first suspect was guilty.","zh":"如果第一個嫌疑人就是兇手，這個謎團就太簡單了。"},{"en":"Chris’s reaction is too simple if it is only guilt; his greed matters more.","zh":"如果 Chris 的反應只是心虛，就太簡單；他的貪婪更重要。"},{"en":"This phrase shows that the story is more complex than expected.","zh":"這個短語顯示故事比預期更複雜。"}],"source":"2016 Q6.pdf","sourcePage":5},{"front":"a hungry smile","meaning":"貪婪的笑容","examples":[{"en":"His smile was not guilty but hungry.","zh":"他的笑容不是心虛，而是貪婪。"},{"en":"A hungry smile is a smile that shows desire, greed or eagerness to take something.","zh":"hungry smile 指顯示慾望、貪婪或急切想得到某物的笑容。"},{"en":"The shopper had a hungry smile when she saw the sale sign.","zh":"購物者看見減價牌時露出貪婪的笑容。"},{"en":"Chris’s hungry smile shows he wants the story, not that he regrets stealing.","zh":"Chris 的貪婪笑容顯示他想要故事，而不是後悔偷竊。"},{"en":"This phrase makes greed visible on a person’s face.","zh":"這個短語令貪婪在人的臉上變得可見。"}],"source":"2016 Q6.pdf","sourcePage":6},{"front":"all the while","meaning":"一直；期間始終","examples":[{"en":"All the while, Mary kept her eyes on her notes.","zh":"一直以來，Mary 都把目光放在筆記上。"},{"en":"All the while means during the whole time something else was happening.","zh":"all the while 指在另一件事發生的整段期間。"},{"en":"The teacher spoke, and all the while the students copied notes.","zh":"老師說話時，學生一直抄筆記。"},{"en":"Mary watches indirectly, but all the while she pretends to study.","zh":"Mary 間接觀察，但期間始終假裝在溫習。"},{"en":"This phrase shows two actions happening at the same time.","zh":"這個短語顯示兩個動作同時發生。"}],"source":"2016 Q6.pdf","sourcePage":6},{"front":"keep my eyes on","meaning":"把目光放在……上","examples":[{"en":"Mary kept her eyes on her notes.","zh":"Mary 把目光放在筆記上。"},{"en":"Keep my eyes on something means continue looking at it.","zh":"keep my eyes on something 指持續看着某物。"},{"en":"During the experiment, students kept their eyes on the thermometer.","zh":"實驗期間，學生把目光放在溫度計上。"},{"en":"Mary keeps her eyes on her notes so Chris will not suspect her.","zh":"Mary 把目光放在筆記上，讓 Chris 不會懷疑她。"},{"en":"This phrase can show focus, caution or pretending not to notice.","zh":"這個短語可以表示專注、小心，或假裝沒有留意。"}],"source":"2016 Q6.pdf","sourcePage":6},{"front":"subject, verb, object","meaning":"主語、動詞、賓語","examples":[{"en":"Mary wrote subject, verb and object in her notes.","zh":"Mary 在筆記中寫下主語、動詞和賓語。"},{"en":"Subject, verb, object are basic grammar parts showing who does an action and what receives it.","zh":"subject, verb, object 是基本文法部分，顯示誰做動作以及動作影響甚麼。"},{"en":"In “Mary wrote a story,” Mary is the subject, wrote is the verb, and story is the object.","zh":"在 “Mary wrote a story” 中，Mary 是主語，wrote 是動詞，story 是賓語。"},{"en":"Writing subject, verb and object makes Mary look like she is studying normally.","zh":"Mary 寫下主語、動詞和賓語，令她看起來像正常溫習。"},{"en":"This phrase adds classroom realism to the scene.","zh":"這個短語為場景加入課堂真實感。"}],"source":"2016 Q6.pdf","sourcePage":6},{"front":"the following Wednesday","meaning":"接下來的星期三","examples":[{"en":"The following Wednesday, the hall was packed.","zh":"接下來的星期三，禮堂擠滿了人。"},{"en":"The following Wednesday means the next Wednesday after the event just mentioned.","zh":"the following Wednesday 指剛才提到的事件之後的下一個星期三。"},{"en":"The results were announced the following Wednesday.","zh":"結果在接下來的星期三公布。"},{"en":"The following Wednesday gives the story a clear timeline.","zh":"接下來的星期三為故事提供清楚時間線。"},{"en":"This phrase helps readers understand when the public reading happened.","zh":"這個短語幫助讀者理解公開朗讀發生在何時。"}],"source":"2016 Q6.pdf","sourcePage":6},{"front":"the hall was packed","meaning":"禮堂擠滿了人","examples":[{"en":"The hall was packed for the finalists’ readings.","zh":"入圍者朗讀時，禮堂擠滿了人。"},{"en":"The hall was packed means the hall was full of people.","zh":"the hall was packed 指禮堂裏滿是人。"},{"en":"The hall was packed because parents and students came to watch the show.","zh":"因為家長和學生來看表演，禮堂擠滿了人。"},{"en":"A packed hall makes a public mistake feel more serious.","zh":"擠滿人的禮堂會令公開出錯感覺更嚴重。"},{"en":"In the story, the crowd increases the pressure on Chris.","zh":"在故事中，人群增加了 Chris 的壓力。"}],"source":"2016 Q6.pdf","sourcePage":6},{"front":"finalists’ readings","meaning":"入圍者朗讀","examples":[{"en":"Chris was chosen for the finalists’ readings.","zh":"Chris 被選中參加入圍者朗讀。"},{"en":"Finalists’ readings are public readings by students who reached the final stage of a competition.","zh":"finalists’ readings 指進入比賽最後階段的學生公開朗讀作品。"},{"en":"During the finalists’ readings, each writer reads part of their work aloud.","zh":"在入圍者朗讀中，每位作者會朗讀自己作品的一部分。"},{"en":"Being chosen for the finalists’ readings usually feels like an honour.","zh":"被選中參加入圍者朗讀通常是一種榮譽。"},{"en":"In the story, this event becomes the place where Chris is exposed.","zh":"在故事中，這個活動成為 Chris 被揭穿的地方。"}],"source":"2016 Q6.pdf","sourcePage":6},{"front":"be chosen again","meaning":"再次被選中","examples":[{"en":"Chris had been chosen again for the competition.","zh":"Chris 再次被選中參加比賽。"},{"en":"Be chosen again means be selected another time after being selected before.","zh":"be chosen again 指曾被選中後，再一次被選中。"},{"en":"The singer was chosen again for the school concert after last year’s success.","zh":"那名歌手因去年成功演出，再次被選中參加學校音樂會。"},{"en":"Chris being chosen again shows that adults still trust his writing talent.","zh":"Chris 再次被選中，顯示成年人仍相信他的寫作才華。"},{"en":"This phrase makes Mary’s plan feel riskier and more satisfying.","zh":"這個短語令 Mary 的計劃感覺更冒險，也更令人滿足。"}],"source":"2016 Q6.pdf","sourcePage":6},{"front":"walk onstage","meaning":"走上台","examples":[{"en":"Chris walked onstage in a white shirt.","zh":"Chris 穿着白恤衫走上台。"},{"en":"Walk onstage means go onto the stage in front of an audience.","zh":"walk onstage 指走到觀眾面前的舞台上。"},{"en":"The speaker walked onstage and adjusted the microphone.","zh":"演講者走上台，然後調整咪高峰。"},{"en":"Chris walks onstage confidently because he thinks the story is his victory.","zh":"Chris 自信地走上台，因為他以為這個故事是自己的勝利。"},{"en":"This phrase marks the moment private theft becomes public performance.","zh":"這個短語標示私人偷竊變成公開表演的一刻。"}],"source":"2016 Q6.pdf","sourcePage":6},{"front":"so crisp it seemed","meaning":"筆挺得像……","examples":[{"en":"His white shirt was so crisp it seemed ironed by angels.","zh":"他的白恤衫筆挺得像由天使燙過。"},{"en":"So crisp it seemed means extremely neat, fresh or sharp-looking, almost beyond normal.","zh":"so crisp it seemed 指非常整齊、清新或挺括，幾乎超出正常程度。"},{"en":"Her uniform was so crisp it seemed new from the shop.","zh":"她的校服筆挺得像剛從商店買回來。"},{"en":"Chris’s shirt is so crisp it makes him look innocent and perfect.","zh":"Chris 的恤衫筆挺，令他看起來無辜又完美。"},{"en":"This phrase exaggerates neatness to create a vivid image.","zh":"這個短語誇張地描寫整齊，製造鮮明畫面。"}],"source":"2016 Q6.pdf","sourcePage":6},{"front":"ironed by angels","meaning":"像由天使燙過","examples":[{"en":"His shirt seemed ironed by angels.","zh":"他的恤衫像由天使燙過。"},{"en":"Ironed by angels means perfectly pressed and neat, as if prepared by heavenly hands.","zh":"ironed by angels 指燙得完美整齊，好像由天使之手整理過。"},{"en":"The bride’s dress looked ironed by angels before the ceremony.","zh":"典禮前，新娘的裙子看起來像由天使燙過。"},{"en":"Saying Chris’s shirt was ironed by angels makes his appearance seem almost too perfect.","zh":"說 Chris 的恤衫像由天使燙過，令他的外表看似過分完美。"},{"en":"This phrase contrasts his clean look with his dishonest action.","zh":"這個短語把他乾淨的外表與不誠實的行為形成對比。"}],"source":"2016 Q6.pdf","sourcePage":7},{"front":"announce","meaning":"宣布","examples":[{"en":"Chris announced that his story was called The Honey Jar.","zh":"Chris 宣布他的故事名為《蜂蜜罐》。"},{"en":"Announce means say something publicly or officially.","zh":"announce 指公開或正式地說出某事。"},{"en":"The teacher announced the winners after lunch.","zh":"老師午飯後宣布得獎者。"},{"en":"Chris announces the title proudly because he does not expect the trap.","zh":"Chris 自豪地宣布標題，因為他沒有預料到陷阱。"},{"en":"This word shows a public moment where everyone hears the claim.","zh":"這個詞顯示一個所有人都聽見主張的公開時刻。"}],"source":"2016 Q6.pdf","sourcePage":7},{"front":"behind me","meaning":"在我身後","examples":[{"en":"Behind Mary, someone whispered that Chris was brilliant.","zh":"在 Mary 身後，有人低聲說 Chris 很出色。"},{"en":"Behind me means at my back or in the space behind where I am sitting or standing.","zh":"behind me 指在我背後，或我坐着、站着的位置後方。"},{"en":"Someone behind me coughed during the speech.","zh":"演講期間，我身後有人咳嗽。"},{"en":"Mary hears praise behind her, which makes the unfairness sharper.","zh":"Mary 聽到身後有人稱讚 Chris，令不公平感更尖銳。"},{"en":"This phrase places the reader close to Mary’s point of view.","zh":"這個短語把讀者放近 Mary 的視角。"}],"source":"2016 Q6.pdf","sourcePage":7},{"front":"whisper","meaning":"低聲說；耳語","examples":[{"en":"Someone whispered, “Isn’t he brilliant?”","zh":"有人低聲說：「他不是很出色嗎？」"},{"en":"Whisper means speak very quietly so only nearby people can hear.","zh":"whisper 指很小聲說話，讓只有附近的人聽到。"},{"en":"Students whispered during the reading because the hall was silent.","zh":"禮堂安靜時，學生在朗讀期間低聲說話。"},{"en":"A whisper can still hurt if the person nearby hears it clearly.","zh":"如果旁邊的人聽得清楚，耳語也可以傷人。"},{"en":"In the story, the whisper praises Chris while Mary knows the truth.","zh":"在故事中，耳語稱讚 Chris，而 Mary 知道真相。"}],"source":"2016 Q6.pdf","sourcePage":7},{"front":"read beautifully","meaning":"朗讀得很動聽","examples":[{"en":"Chris read the stolen story beautifully.","zh":"Chris 把偷來的故事朗讀得很動聽。"},{"en":"Read beautifully means read aloud with a pleasant voice, good rhythm and feeling.","zh":"read beautifully 指用悅耳聲音、良好節奏和感情朗讀。"},{"en":"The student read her poem beautifully during assembly.","zh":"那名學生在早會中把詩朗讀得很動聽。"},{"en":"Chris reads beautifully, but the beauty belongs to words he stole.","zh":"Chris 朗讀得很動聽，但那份美來自他偷來的文字。"},{"en":"This phrase shows how performance can hide dishonesty.","zh":"這個短語顯示表演如何掩蓋不誠實。"}],"source":"2016 Q6.pdf","sourcePage":7},{"front":"pauses were perfect","meaning":"停頓恰到好處","examples":[{"en":"His pauses were perfect during the reading.","zh":"他朗讀時停頓恰到好處。"},{"en":"Pauses were perfect means the speaker stopped at exactly the right moments.","zh":"pauses were perfect 指說話者在正確時刻停下來。"},{"en":"A good storyteller uses pauses to create suspense.","zh":"好說書人會用停頓製造懸念。"},{"en":"Chris’s perfect pauses make the stolen story sound even more impressive.","zh":"Chris 恰到好處的停頓令偷來的故事聽起來更出色。"},{"en":"This phrase shows skill in performance, not honesty in authorship.","zh":"這個短語顯示的是表演技巧，而不是作者身份的誠實。"}],"source":"2016 Q6.pdf","sourcePage":7},{"front":"voice warmed the hall","meaning":"聲音令禮堂變得溫暖","examples":[{"en":"His voice warmed the hall like afternoon sunlight.","zh":"他的聲音像午後陽光一樣令禮堂變得溫暖。"},{"en":"Voice warmed the hall means his voice made the place feel gentle, comfortable or emotionally warm.","zh":"voice warmed the hall 指他的聲音令地方感覺柔和、舒服或情感上溫暖。"},{"en":"The singer’s voice warmed the hall during the winter concert.","zh":"冬季音樂會中，歌手的聲音令禮堂變得溫暖。"},{"en":"Chris’s warm voice makes the audience trust him more easily.","zh":"Chris 溫暖的聲音令觀眾更容易信任他。"},{"en":"This phrase shows the power of sound to shape mood.","zh":"這個短語顯示聲音塑造氣氛的力量。"}],"source":"2016 Q6.pdf","sourcePage":7},{"front":"like afternoon sunlight","meaning":"像午後陽光一樣","examples":[{"en":"His voice warmed the hall like afternoon sunlight.","zh":"他的聲音像午後陽光一樣令禮堂變得溫暖。"},{"en":"Like afternoon sunlight compares something to soft, warm light later in the day.","zh":"like afternoon sunlight 把某物比作下午柔和溫暖的光。"},{"en":"Her gentle speech felt like afternoon sunlight after a difficult morning.","zh":"經過困難的早上後，她溫柔的說話像午後陽光一樣。"},{"en":"Comparing Chris’s voice to afternoon sunlight makes it seem comforting and golden.","zh":"把 Chris 的聲音比作午後陽光，令它顯得安慰而金黃。"},{"en":"This phrase creates beauty while making his deception more ironic.","zh":"這個短語製造美感，同時令他的欺騙更具諷刺。"}],"source":"2016 Q6.pdf","sourcePage":7},{"front":"the more..., the more...","meaning":"越……就越……","examples":[{"en":"The more confidently he performed, the more completely he trapped himself.","zh":"他表演得越自信，就越完全把自己困住。"},{"en":"The more A, the more B means as A increases, B also increases.","zh":"the more A, the more B 指 A 增加時，B 也跟着增加。"},{"en":"The more carefully students revise, the more confident they feel.","zh":"學生溫習得越仔細，就越有信心。"},{"en":"The more Chris performs the story as his own, the more evidence he creates against himself.","zh":"Chris 越把故事當成自己的來表演，就越為自己製造證據。"},{"en":"This structure clearly shows two changes growing together.","zh":"這個結構清楚顯示兩個變化一起增加。"}],"source":"2016 Q6.pdf","sourcePage":7},{"front":"perform confidently","meaning":"自信地表演","examples":[{"en":"Chris performed confidently onstage.","zh":"Chris 在台上自信地表演。"},{"en":"Perform confidently means act, speak or read in front of others with self-belief.","zh":"perform confidently 指在人前帶着自信地表演、說話或朗讀。"},{"en":"A student performs confidently when she knows her lines well.","zh":"學生熟記台詞時，會自信地表演。"},{"en":"Chris performs confidently because he believes no one can expose him.","zh":"Chris 自信地表演，因為他相信沒有人能揭穿他。"},{"en":"This phrase makes his later fear more dramatic.","zh":"這個短語令他後來的恐懼更具戲劇性。"}],"source":"2016 Q6.pdf","sourcePage":7},{"front":"wrap the string around himself","meaning":"把繩索繞到自己身上","examples":[{"en":"Chris wrapped the string around himself as he read.","zh":"Chris 朗讀時把繩索繞到自己身上。"},{"en":"Wrap the string around himself means, metaphorically, make his own trap tighter by his actions.","zh":"wrap the string around himself 在比喻上指透過自己的行動令陷阱收得更緊。"},{"en":"A liar wraps the string around himself when each new lie creates another problem.","zh":"說謊者每說一個新謊而製造新問題時，就是把繩索繞到自己身上。"},{"en":"Chris wraps the string around himself by reading Mary’s hidden message aloud.","zh":"Chris 朗讀 Mary 隱藏的信息時，就是把繩索繞到自己身上。"},{"en":"This phrase compares guilt to a trap made from thread or rope.","zh":"這個短語把罪責比作由線或繩造成的陷阱。"}],"source":"2016 Q6.pdf","sourcePage":8},{"front":"reach the last paragraph","meaning":"讀到最後一段","examples":[{"en":"When Chris reached the last paragraph, Mrs Chan noticed the message.","zh":"當 Chris 讀到最後一段時，Chan 老師注意到那段信息。"},{"en":"Reach the last paragraph means arrive at the final section of a piece of writing while reading.","zh":"reach the last paragraph 指閱讀時到達文章最後一個段落。"},{"en":"When I reached the last paragraph, I understood the writer’s main point.","zh":"當我讀到最後一段時，我明白了作者的主要觀點。"},{"en":"Chris reaches the last paragraph just as the hidden message becomes clear.","zh":"Chris 讀到最後一段時，隱藏信息剛好變得清楚。"},{"en":"This phrase marks the moment the trap is about to open.","zh":"這個短語標示陷阱快要打開的時刻。"}],"source":"2016 Q6.pdf","sourcePage":8},{"front":"straighten in her seat","meaning":"在座位上坐直","examples":[{"en":"Mrs Chan straightened in her seat.","zh":"Chan 老師在座位上坐直。"},{"en":"Straighten in her seat means sit up more upright, often because of surprise or attention.","zh":"straighten in her seat 指坐得更直，常因驚訝或注意到事情。"},{"en":"The teacher straightened in her seat when she heard the unusual answer.","zh":"老師聽到不尋常答案時，在座位上坐直。"},{"en":"Mrs Chan straightens because she has noticed something serious in the text.","zh":"Chan 老師坐直，因為她在文本中注意到嚴重事情。"},{"en":"This phrase shows sudden alertness without needing direct explanation.","zh":"這個短語不需直接解釋，也顯示突然警覺。"}],"source":"2016 Q6.pdf","sourcePage":8},{"front":"head of the panel","meaning":"評審團主席","examples":[{"en":"Mr Lau was the head of the panel.","zh":"Lau 先生是評審團主席。"},{"en":"The head of the panel is the person leading a judging or decision-making group.","zh":"head of the panel 指領導評審或決策小組的人。"},{"en":"The head of the panel announced the debate results.","zh":"評審團主席宣布辯論比賽結果。"},{"en":"When the head of the panel notices a problem, the issue becomes official.","zh":"當評審團主席注意到問題，事件就變得正式。"},{"en":"This phrase shows Mr Lau’s authority in the competition.","zh":"這個短語顯示 Lau 先生在比賽中的權威。"}],"source":"2016 Q6.pdf","sourcePage":8},{"front":"look down at","meaning":"低頭看着","examples":[{"en":"Mr Lau looked down at the printed copy in his hands.","zh":"Lau 先生低頭看着手中的列印本。"},{"en":"Look down at means lower your eyes to see something below you.","zh":"look down at 指垂下眼睛看下方的東西。"},{"en":"The student looked down at her notes before answering.","zh":"學生回答前低頭看着筆記。"},{"en":"Mr Lau looks down at the copy because the hidden message needs checking.","zh":"Lau 先生低頭看着列印本，因為隱藏信息需要核對。"},{"en":"This phrase creates a small but tense action.","zh":"這個短語製造細小但緊張的動作。"}],"source":"2016 Q6.pdf","sourcePage":8},{"front":"printed copy","meaning":"列印本","examples":[{"en":"Mr Lau held the printed copy in his hands.","zh":"Lau 先生手中拿着列印本。"},{"en":"A printed copy is a paper version of a digital document.","zh":"printed copy 指數碼文件的紙本版本。"},{"en":"The teacher asked for a printed copy of every essay.","zh":"老師要求每篇文章交一份列印本。"},{"en":"A printed copy can be marked, checked and passed around easily.","zh":"列印本容易批改、核對和傳閱。"},{"en":"In the story, the printed copy lets the panel see Mary’s hidden message.","zh":"在故事中，列印本讓評審團看見 Mary 的隱藏信息。"}],"source":"2016 Q6.pdf","sourcePage":8},{"front":"letter by letter","meaning":"一個字母一個字母地","examples":[{"en":"Letter by letter, the trap opened.","zh":"一個字母一個字母地，陷阱打開了。"},{"en":"Letter by letter means one letter at a time.","zh":"letter by letter 指每次一個字母地。"},{"en":"The child spelled her name letter by letter.","zh":"孩子一個字母一個字母地拼出自己的名字。"},{"en":"Mary’s hidden accusation appears letter by letter through the paragraph openings.","zh":"Mary 隱藏的指控透過段落開首一個字母一個字母地出現。"},{"en":"This phrase slows the moment down and builds suspense.","zh":"這個短語放慢時刻並建立懸念。"}],"source":"2016 Q6.pdf","sourcePage":8},{"front":"the trap opened","meaning":"陷阱打開","examples":[{"en":"The hidden message meant that the trap opened.","zh":"隱藏信息意味着陷阱打開了。"},{"en":"The trap opened means the planned trick or proof was finally revealed.","zh":"the trap opened 指計劃好的圈套或證據終於被揭示。"},{"en":"When the copied essay matched the old draft, the trap opened.","zh":"當抄襲文章與舊草稿相符時，陷阱打開了。"},{"en":"Mary’s trap opens when the panel sees the message Chris has read aloud.","zh":"當評審團看見 Chris 朗讀出的信息時，Mary 的陷阱打開了。"},{"en":"This phrase shows the moment a secret plan begins to work publicly.","zh":"這個短語顯示秘密計劃開始公開發揮作用的一刻。"}],"source":"2016 Q6.pdf","sourcePage":8},{"front":"applause broke out","meaning":"掌聲響起","examples":[{"en":"When Chris finished, applause broke out.","zh":"Chris 完成朗讀時，掌聲響起。"},{"en":"Applause broke out means people suddenly began clapping.","zh":"applause broke out 指人們突然開始拍手。"},{"en":"Applause broke out after the choir finished the final song.","zh":"合唱團唱完最後一首歌後，掌聲響起。"},{"en":"Applause can break out before people fully understand what has happened.","zh":"掌聲可能在人們完全理解發生甚麼之前就響起。"},{"en":"In the story, the applause is ironic because Chris may not deserve it.","zh":"在故事中，掌聲帶有諷刺，因為 Chris 未必值得得到它。"}],"source":"2016 Q6.pdf","sourcePage":8},{"front":"bow before","meaning":"在……之前鞠躬","examples":[{"en":"Chris bowed before anyone had decided whether he deserved it.","zh":"Chris 在任何人決定他是否值得之前就鞠躬。"},{"en":"Bow before means bend the body in respect before something else happens.","zh":"bow before 指在另一件事發生前彎身表示謝意或尊敬。"},{"en":"The actor bowed before the audience stopped clapping.","zh":"演員在觀眾停止拍手前鞠躬。"},{"en":"Chris bows before people decide whether his applause is deserved.","zh":"Chris 在人們決定掌聲是否應得之前就鞠躬。"},{"en":"This phrase shows his confidence arriving too early.","zh":"這個短語顯示他的自信來得太早。"}],"source":"2016 Q6.pdf","sourcePage":8},{"front":"deserve it","meaning":"值得得到它","examples":[{"en":"Chris bowed before anyone had decided whether he deserved the applause.","zh":"Chris 在任何人決定他是否值得得到掌聲之前就鞠躬。"},{"en":"Deserve it means be worthy of receiving something because of your actions.","zh":"deserve it 指因自己的行為而配得上得到某物。"},{"en":"A student who practises honestly deserves praise for improvement.","zh":"誠實練習的學生值得因進步而得到讚賞。"},{"en":"Chris may not deserve the applause because the story is not truly his.","zh":"Chris 可能不值得得到掌聲，因為故事不真正屬於他。"},{"en":"This phrase raises the question of fairness.","zh":"這個短語提出公平的問題。"}],"source":"2016 Q6.pdf","sourcePage":9},{"front":"stand up","meaning":"站起來","examples":[{"en":"Then Mrs Chan stood up.","zh":"然後 Chan 老師站起來。"},{"en":"Stand up means rise from a sitting position to your feet.","zh":"stand up 指從坐姿起身站立。"},{"en":"The teacher stood up to make an announcement.","zh":"老師站起來宣布消息。"},{"en":"Mrs Chan standing up signals that the situation has become serious.","zh":"Chan 老師站起來，表示情況變得嚴重。"},{"en":"This simple action changes the mood of the hall.","zh":"這個簡單動作改變了禮堂的氣氛。"}],"source":"2016 Q6.pdf","sourcePage":9},{"front":"explain why","meaning":"解釋為何","examples":[{"en":"Mrs Chan asked Chris to explain why the first letters formed a message.","zh":"Chan 老師要求 Chris 解釋為何首字母拼成一段信息。"},{"en":"Explain why means give the reason for something.","zh":"explain why 指說明某事的原因。"},{"en":"The teacher asked the student to explain why his answer changed.","zh":"老師要求學生解釋為何答案改變了。"},{"en":"Asking Chris to explain why forces him to face the hidden evidence.","zh":"要求 Chris 解釋為何，迫使他面對隱藏證據。"},{"en":"This phrase turns suspicion into a direct question.","zh":"這個短語把懷疑變成直接問題。"}],"source":"2016 Q6.pdf","sourcePage":9},{"front":"spell an unusual message","meaning":"拼出一段不尋常的信息","examples":[{"en":"The first letters of the paragraphs spelled an unusual message.","zh":"段落首字母拼出一段不尋常的信息。"},{"en":"Spell an unusual message means form a strange or unexpected message through letters.","zh":"spell an unusual message 指用字母形成奇怪或出乎意料的信息。"},{"en":"The first letters of the poem spelled an unusual message for the reader.","zh":"那首詩的首字母為讀者拼出一段不尋常的信息。"},{"en":"Mary’s paragraphs spell an unusual message that Chris cannot explain.","zh":"Mary 的段落拼出一段 Chris 無法解釋的不尋常信息。"},{"en":"This phrase shows how writing structure can carry secret meaning.","zh":"這個短語顯示寫作結構可以承載秘密意思。"}],"source":"2016 Q6.pdf","sourcePage":9},{"front":"go still","meaning":"變得一片寂靜","examples":[{"en":"The hall went still after Mrs Chan spoke.","zh":"Chan 老師說話後，禮堂變得一片寂靜。"},{"en":"Go still means become completely quiet or motionless.","zh":"go still 指變得完全安靜或一動不動。"},{"en":"The classroom went still when the principal entered.","zh":"校長進入時，課室變得一片寂靜。"},{"en":"The hall goes still because everyone senses something serious has happened.","zh":"禮堂變得一片寂靜，因為所有人都感到發生了嚴重事情。"},{"en":"This phrase creates sudden tension.","zh":"這個短語製造突然的緊張感。"}],"source":"2016 Q6.pdf","sourcePage":9},{"front":"hand someone the paper","meaning":"把紙遞給某人","examples":[{"en":"Mrs Chan handed Chris the paper.","zh":"Chan 老師把紙遞給 Chris。"},{"en":"Hand someone the paper means give a piece of paper to someone directly.","zh":"hand someone the paper 指直接把一張紙交給某人。"},{"en":"The teacher handed the student the marked essay.","zh":"老師把批改好的文章遞給學生。"},{"en":"Mrs Chan hands Chris the paper so he must see the evidence himself.","zh":"Chan 老師把紙遞給 Chris，讓他必須親自看見證據。"},{"en":"This phrase makes the confrontation physical and direct.","zh":"這個短語令對質變得具體而直接。"}],"source":"2016 Q6.pdf","sourcePage":9},{"front":"for once","meaning":"這一次；難得地","examples":[{"en":"For once, Chris’s face was worth writing about.","zh":"這一次，Chris 的臉值得寫下來。"},{"en":"For once means this time, unlike usual.","zh":"for once 指這一次，與平常不同。"},{"en":"For once, the noisy class became completely quiet.","zh":"難得地，那個嘈吵的班級變得完全安靜。"},{"en":"Mary says “for once” because Chris’s face finally reveals a true story.","zh":"Mary 說 for once，因為 Chris 的臉終於揭示真實故事。"},{"en":"This phrase suggests a rare change from the normal pattern.","zh":"這個短語暗示與平常模式不同的罕見改變。"}],"source":"2016 Q6.pdf","sourcePage":9},{"front":"worth writing about","meaning":"值得寫下來","examples":[{"en":"His face was finally worth writing about.","zh":"他的臉終於值得寫下來。"},{"en":"Worth writing about means interesting, meaningful or revealing enough to describe in writing.","zh":"worth writing about 指有趣、有意義或足以揭示真相，值得用文字描寫。"},{"en":"The old market was worth writing about because every stall had a story.","zh":"那個舊街市值得寫下來，因為每個攤檔都有故事。"},{"en":"Chris’s face is worth writing about because his confidence finally breaks.","zh":"Chris 的臉值得寫下來，因為他的自信終於崩塌。"},{"en":"This phrase shows that a small expression can carry a large meaning.","zh":"這個短語顯示細小表情可以承載巨大意義。"}],"source":"2016 Q6.pdf","sourcePage":9},{"front":"confidence drained from","meaning":"自信從……流失","examples":[{"en":"The confidence drained from his eyes and mouth.","zh":"自信從他的眼睛和嘴角流失。"},{"en":"Confidence drained from someone means their confidence disappeared slowly and visibly.","zh":"confidence drained from someone 指某人的自信慢慢而明顯地消失。"},{"en":"The confidence drained from the speaker’s face when she forgot her lines.","zh":"演講者忘記台詞時，自信從她臉上流失。"},{"en":"Chris’s confidence drains from his eyes and mouth as the truth appears.","zh":"當真相出現，Chris 的自信從眼睛和嘴角流失。"},{"en":"This phrase makes loss of courage look like liquid leaving the body.","zh":"這個短語令勇氣流失看起來像液體離開身體。"}],"source":"2016 Q6.pdf","sourcePage":9},{"front":"leave behind","meaning":"留下","examples":[{"en":"The loss of confidence left behind a frightened boy.","zh":"自信流失後，留下了一個驚慌的男孩。"},{"en":"Leave behind means remain after something else has gone.","zh":"leave behind 指某物離開後仍然留下另一物。"},{"en":"After the rain stopped, it left behind wet streets and puddles.","zh":"雨停後，留下濕街道和水窪。"},{"en":"When Chris’s confidence disappears, it leaves behind fear.","zh":"當 Chris 的自信消失，留下的是恐懼。"},{"en":"This phrase shows what remains after a change.","zh":"這個短語顯示變化後剩下的是甚麼。"}],"source":"2016 Q6.pdf","sourcePage":9},{"front":"a frightened boy","meaning":"驚慌的男孩","examples":[{"en":"The confident performer became a frightened boy.","zh":"那個自信的表演者變成了一個驚慌的男孩。"},{"en":"A frightened boy is a boy who feels scared and unsure.","zh":"frightened boy 指感到害怕和不安的男孩。"},{"en":"A frightened boy may look down, speak softly and avoid eye contact.","zh":"驚慌的男孩可能低頭、細聲說話，並避開目光接觸。"},{"en":"Chris becomes a frightened boy when his polished image falls apart.","zh":"當 Chris 精緻的形象崩塌，他變成一個驚慌的男孩。"},{"en":"This phrase strips away his public confidence.","zh":"這個短語剝去他的公開自信。"}],"source":"2016 Q6.pdf","sourcePage":10},{"front":"expensive shirt","meaning":"昂貴的恤衫","examples":[{"en":"Chris looked like a frightened boy in an expensive shirt.","zh":"Chris 看起來像一個穿着昂貴恤衫的驚慌男孩。"},{"en":"An expensive shirt is a costly, well-made or fashionable shirt.","zh":"expensive shirt 指價格高、做工好或時尚的恤衫。"},{"en":"An expensive shirt can make someone look confident and polished.","zh":"昂貴的恤衫可以令人看起來自信而精緻。"},{"en":"Chris’s expensive shirt cannot protect him when the truth appears.","zh":"真相出現時，Chris 的昂貴恤衫保護不了他。"},{"en":"This phrase contrasts outward status with inner fear.","zh":"這個短語把外在地位與內在恐懼形成對比。"}],"source":"2016 Q6.pdf","sourcePage":10},{"front":"precisely the problem","meaning":"正正是問題所在","examples":[{"en":"Mrs Chan said that his excuse was precisely the problem.","zh":"Chan 老師說他的藉口正正是問題所在。"},{"en":"Precisely the problem means exactly the thing that is wrong or troubling.","zh":"precisely the problem 指正是錯誤或令人困擾的地方。"},{"en":"Saying “everyone does it” is precisely the problem if cheating has become normal.","zh":"如果作弊變得正常，說「人人都這樣做」正正是問題所在。"},{"en":"Chris’s excuse is precisely the problem because it proves he does not understand ownership.","zh":"Chris 的藉口正正是問題所在，因為它證明他不理解作品擁有權。"},{"en":"This phrase strongly identifies the central issue.","zh":"這個短語有力指出核心問題。"}],"source":"2016 Q6.pdf","sourcePage":10},{"front":"no sooner had...than...","meaning":"一……就……","examples":[{"en":"No sooner had Mrs Chan spoken than murmurs swept across the hall.","zh":"Chan 老師一開口，竊竊私語就傳遍禮堂。"},{"en":"No sooner had A happened than B happened means B happened immediately after A.","zh":"no sooner had A happened than B happened 指 A 一發生，B 就立刻發生。"},{"en":"No sooner had the bell rung than the students rushed out.","zh":"鐘聲一響，學生就衝出去。"},{"en":"No sooner had the secret been revealed than everyone started whispering.","zh":"秘密一被揭露，所有人就開始低聲議論。"},{"en":"This structure is useful for showing quick reaction.","zh":"這個結構適合顯示快速反應。"}],"source":"2016 Q6.pdf","sourcePage":10},{"front":"murmurs swept across the hall","meaning":"竊竊私語傳遍禮堂","examples":[{"en":"Murmurs swept across the hall after Chris was exposed.","zh":"Chris 被揭穿後，竊竊私語傳遍禮堂。"},{"en":"Murmurs swept across the hall means quiet voices spread quickly through the audience.","zh":"murmurs swept across the hall 指低聲議論迅速在觀眾中傳開。"},{"en":"Murmurs swept across the hall when the winner’s name was changed.","zh":"得獎者名字被改動時，竊竊私語傳遍禮堂。"},{"en":"The phrase makes whispers feel like a wave moving through the crowd.","zh":"這個短語令耳語像浪一樣穿過人群。"},{"en":"In the story, the murmurs show public opinion turning against Chris.","zh":"在故事中，竊竊私語顯示公眾看法開始轉向 Chris。"}],"source":"2016 Q6.pdf","sourcePage":10},{"front":"look at me then","meaning":"那時看着我","examples":[{"en":"Chris looked at Mary then.","zh":"Chris 那時看着 Mary。"},{"en":"Look at me then means turn one’s eyes toward me at that specific moment.","zh":"look at me then 指在那個特定時刻把目光轉向我。"},{"en":"The student looked at me then, as if he finally understood the question.","zh":"那名學生那時看着我，好像終於明白問題。"},{"en":"Chris looks at Mary then because he realises she is connected to the trap.","zh":"Chris 那時看着 Mary，因為他明白她與陷阱有關。"},{"en":"This phrase marks a moment of recognition.","zh":"這個短語標示認出真相的一刻。"}],"source":"2016 Q6.pdf","sourcePage":10},{"front":"not angrily, but as if","meaning":"不是憤怒地，而是好像","examples":[{"en":"He looked at her not angrily, but as if he finally understood.","zh":"他看着她，不是憤怒地，而是好像終於明白了。"},{"en":"Not angrily, but as if means the look was not full of anger; it suggested another feeling or understanding.","zh":"not angrily, but as if 指那個眼神不是充滿憤怒，而是暗示另一種感受或理解。"},{"en":"She looked at the mistake not angrily, but as if she had expected it.","zh":"她看着那個錯誤，不是憤怒地，而是好像早已預料到。"},{"en":"Chris does not look angry because he finally understands Mary is not powerless.","zh":"Chris 沒有憤怒地看她，因為他終於明白 Mary 不是無力的。"},{"en":"This structure corrects the expected emotion and replaces it with a deeper one.","zh":"這個結構修正預期情緒，並以更深層的情緒取代。"}],"source":"2016 Q6.pdf","sourcePage":10},{"front":"finally realise","meaning":"終於明白","examples":[{"en":"Chris finally realised that Mary was not empty.","zh":"Chris 終於明白 Mary 並不是空白的人。"},{"en":"Finally realise means understand something after a long delay or mistake.","zh":"finally realise 指經過長時間延誤或錯誤後終於理解某事。"},{"en":"The student finally realised that copying homework did not help him learn.","zh":"那名學生終於明白抄功課不能幫助自己學習。"},{"en":"Chris finally realises Mary’s silence was not weakness.","zh":"Chris 終於明白 Mary 的沉默不是軟弱。"},{"en":"This phrase shows a delayed but important understanding.","zh":"這個短語顯示遲來但重要的理解。"}],"source":"2016 Q6.pdf","sourcePage":10},{"front":"a quiet person","meaning":"安靜的人","examples":[{"en":"A quiet person is not necessarily an empty one.","zh":"安靜的人不一定是內心空白的人。"},{"en":"A quiet person is someone who speaks little or does not show thoughts openly.","zh":"quiet person 指說話較少或不公開表達想法的人。"},{"en":"A quiet person may notice more than others because they listen carefully.","zh":"安靜的人可能因為仔細聆聽而注意到更多事情。"},{"en":"People may underestimate a quiet person if they mistake silence for emptiness.","zh":"如果人們錯把沉默當成空白，就可能低估安靜的人。"},{"en":"This phrase is central to Mary’s character.","zh":"這個短語是 Mary 角色的核心。"}],"source":"2016 Q6.pdf","sourcePage":10},{"front":"not necessarily","meaning":"不一定","examples":[{"en":"A quiet person is not necessarily an empty one.","zh":"安靜的人不一定是內心空白的人。"},{"en":"Not necessarily means not always or not in every case.","zh":"not necessarily 指不總是如此，或不是每個情況都如此。"},{"en":"A popular book is not necessarily a good book.","zh":"受歡迎的書不一定是好書。"},{"en":"Silence does not necessarily mean agreement.","zh":"沉默不一定代表同意。"},{"en":"This phrase helps avoid unfair generalisations.","zh":"這個短語幫助避免不公平的概括。"}],"source":"2016 Q6.pdf","sourcePage":10},{"front":"an empty one","meaning":"內心空白的人","examples":[{"en":"Chris realised that a quiet person was not an empty one.","zh":"Chris 明白安靜的人並不是內心空白的人。"},{"en":"An empty one means a person without thoughts, feelings or ideas.","zh":"empty one 指沒有思想、感受或想法的人。"},{"en":"A student who speaks little is not an empty one; she may be thinking carefully.","zh":"很少說話的學生不是內心空白的人；她可能正在仔細思考。"},{"en":"Chris once treated Mary like an empty one because she stayed silent.","zh":"Chris 曾把 Mary 當成內心空白的人，因為她保持沉默。"},{"en":"This phrase challenges the idea that quiet people have nothing inside.","zh":"這個短語挑戰「安靜的人內心沒有東西」的想法。"}],"source":"2016 Q6.pdf","sourcePage":11},{"front":"be read last","meaning":"最後被朗讀","examples":[{"en":"Mary’s own story was read last.","zh":"Mary 自己的故事最後被朗讀。"},{"en":"Be read last means be presented after all the other pieces.","zh":"be read last 指在所有其他作品之後被呈現。"},{"en":"The winning poem was read last to end the ceremony strongly.","zh":"得獎詩最後被朗讀，為典禮作有力結尾。"},{"en":"Mary’s story being read last gives her voice the final word.","zh":"Mary 的故事最後被朗讀，讓她的聲音成為最後一句。"},{"en":"This phrase creates a sense of delayed justice.","zh":"這個短語製造遲來正義的感覺。"}],"source":"2016 Q6.pdf","sourcePage":11},{"front":"tell the truth without naming him","meaning":"不點名地說出真相","examples":[{"en":"Mary’s story told the truth without naming Chris.","zh":"Mary 的故事不點名地說出真相。"},{"en":"Tell the truth without naming him means reveal what happened without directly saying his name.","zh":"tell the truth without naming him 指揭示發生的事，但不直接說出他的名字。"},{"en":"A writer can tell the truth without naming someone by using clear details.","zh":"作者可以透過清楚細節不點名地說出真相。"},{"en":"Mary tells the truth without naming Chris because the evidence speaks for itself.","zh":"Mary 不點名地說出真相，因為證據本身已經說明一切。"},{"en":"This phrase shows restraint and precision.","zh":"這個短語顯示克制和精準。"}],"source":"2016 Q6.pdf","sourcePage":11},{"front":"mistake silence for weakness","meaning":"錯把沉默當成軟弱","examples":[{"en":"The girl had mistaken silence for weakness.","zh":"那個女孩曾錯把沉默當成軟弱。"},{"en":"Mistake silence for weakness means wrongly think a quiet person is powerless.","zh":"mistake silence for weakness 指錯誤地以為安靜的人沒有力量。"},{"en":"A bully may mistake silence for weakness when a student does not answer back.","zh":"當學生沒有反駁時，欺凌者可能錯把沉默當成軟弱。"},{"en":"Chris mistakes Mary’s silence for weakness, so he underestimates her.","zh":"Chris 錯把 Mary 的沉默當成軟弱，所以低估了她。"},{"en":"This phrase shows the main misunderstanding in the story.","zh":"這個短語顯示故事中的主要誤解。"}],"source":"2016 Q6.pdf","sourcePage":11},{"front":"patience for surrender","meaning":"錯把耐性當成投降","examples":[{"en":"She had mistaken patience for surrender.","zh":"她曾錯把耐性當成投降。"},{"en":"Mistake patience for surrender means wrongly think someone waiting calmly has given up.","zh":"mistake patience for surrender 指錯以為某人冷靜等待就是放棄。"},{"en":"A teacher’s patience should not be mistaken for surrender during a noisy lesson.","zh":"在嘈吵課堂中，老師的耐性不應被錯當成投降。"},{"en":"Mary’s patience is not surrender; it is preparation.","zh":"Mary 的耐性不是投降，而是準備。"},{"en":"This phrase separates quiet waiting from defeat.","zh":"這個短語把安靜等待與失敗分開。"}],"source":"2016 Q6.pdf","sourcePage":11},{"front":"kindness for permission","meaning":"錯把善意當成許可","examples":[{"en":"She had mistaken kindness for permission.","zh":"她曾錯把善意當成許可。"},{"en":"Mistake kindness for permission means wrongly think someone’s gentleness allows you to use or hurt them.","zh":"mistake kindness for permission 指錯以為某人的溫和代表可以利用或傷害他。"},{"en":"A classmate may mistake kindness for permission if he keeps borrowing things without asking.","zh":"如果同學不問就一直借東西，他可能錯把善意當成許可。"},{"en":"Chris mistakes Mary’s kindness for permission to take her work.","zh":"Chris 錯把 Mary 的善意當成可以拿走她作品的許可。"},{"en":"This phrase shows how selfish people abuse gentle behaviour.","zh":"這個短語顯示自私的人如何濫用溫和行為。"}],"source":"2016 Q6.pdf","sourcePage":11},{"front":"merely cruel","meaning":"只是殘忍的","examples":[{"en":"Revenge that is merely cruel leaves a bitter taste.","zh":"只是殘忍的復仇會留下苦澀滋味。"},{"en":"Merely cruel means only hurtful, without justice, purpose or fairness.","zh":"merely cruel 指只是在傷害別人，沒有正義、目的或公平。"},{"en":"A prank that humiliates someone is merely cruel if it teaches nothing.","zh":"如果惡作劇只是羞辱別人而沒有教訓，就是只是殘忍的。"},{"en":"Mary’s revenge is not merely cruel because it reveals the truth.","zh":"Mary 的復仇不是只是殘忍的，因為它揭示真相。"},{"en":"This phrase separates empty harm from meaningful justice.","zh":"這個短語把空洞傷害與有意義的正義分開。"}],"source":"2016 Q6.pdf","sourcePage":11},{"front":"leave a bitter taste","meaning":"留下苦澀滋味","examples":[{"en":"Cruel revenge leaves a bitter taste.","zh":"殘忍的復仇會留下苦澀滋味。"},{"en":"Leave a bitter taste means create an unpleasant feeling that remains after an event.","zh":"leave a bitter taste 指在事件後留下不愉快的感覺。"},{"en":"Winning by cheating can leave a bitter taste even if you receive a prize.","zh":"即使得獎，以作弊取勝也可能留下苦澀滋味。"},{"en":"Revenge leaves a bitter taste when it only hurts and solves nothing.","zh":"當復仇只造成傷害而沒有解決問題，就會留下苦澀滋味。"},{"en":"This phrase uses taste to describe moral discomfort.","zh":"這個短語用味道描述道德上的不舒服。"}],"source":"2016 Q6.pdf","sourcePage":11},{"front":"patient, precise and earned","meaning":"有耐性、精準而應得的","examples":[{"en":"Justice can be patient, precise and earned.","zh":"正義可以是有耐性、精準而應得的。"},{"en":"Patient, precise and earned means calm, carefully targeted and deserved through effort.","zh":"patient, precise and earned 指冷靜、準確針對，而且透過努力或經歷而應得。"},{"en":"A fair teacher’s response should be patient, precise and earned, not angry and random.","zh":"公平老師的回應應該有耐性、精準而應得，不應憤怒和隨意。"},{"en":"Mary’s justice is patient because she waits, precise because she uses evidence, and earned because she suffered.","zh":"Mary 的正義有耐性，因為她等待；精準，因為她用證據；應得，因為她曾受傷。"},{"en":"This phrase describes justice as controlled rather than wild.","zh":"這個短語把正義描寫成受控制，而不是失控。"}],"source":"2016 Q6.pdf","sourcePage":11},{"front":"taste unexpectedly sweet","meaning":"嚐起來意想不到地甜","examples":[{"en":"Justice can taste unexpectedly sweet.","zh":"正義可以嚐起來意想不到地甜。"},{"en":"Taste unexpectedly sweet means feel surprisingly satisfying or rewarding.","zh":"taste unexpectedly sweet 指感覺出乎意料地令人滿足或值得。"},{"en":"An apology after months of unfairness can taste unexpectedly sweet.","zh":"經過數月不公平後得到道歉，可能嚐起來意想不到地甜。"},{"en":"Mary’s justice tastes unexpectedly sweet because her voice finally matters.","zh":"Mary 的正義嚐起來意想不到地甜，因為她的聲音終於變得重要。"},{"en":"This phrase connects emotional satisfaction with the story’s honey image.","zh":"這個短語把情感上的滿足與故事中的蜂蜜意象連在一起。"}],"source":"2016 Q6.pdf","sourcePage":11},{"front":"after the ceremony","meaning":"典禮之後","examples":[{"en":"After the ceremony, Chris tried to speak to Mary.","zh":"典禮之後，Chris 嘗試跟 Mary 說話。"},{"en":"After the ceremony means when the formal event had ended.","zh":"after the ceremony 指正式活動結束後。"},{"en":"After the ceremony, students took photos with their certificates.","zh":"典禮之後，學生拿着證書拍照。"},{"en":"Chris approaches Mary after the ceremony because the public exposure is over.","zh":"Chris 在典禮之後走近 Mary，因為公開揭穿已經結束。"},{"en":"This phrase moves the story from public judgement to private confrontation.","zh":"這個短語把故事從公開審判移向私人對質。"}],"source":"2016 Q6.pdf","sourcePage":12},{"front":"near the noticeboard","meaning":"在告示板附近","examples":[{"en":"Chris tried to speak to Mary near the noticeboard.","zh":"Chris 在告示板附近嘗試跟 Mary 說話。"},{"en":"Near the noticeboard means close to the board where school announcements are posted.","zh":"near the noticeboard 指靠近張貼學校公告的告示板。"},{"en":"Students gathered near the noticeboard to check the competition results.","zh":"學生聚在告示板附近查看比賽結果。"},{"en":"A conversation near the noticeboard feels public but slightly apart from the hall.","zh":"在告示板附近的對話感覺公開，但又稍微離開禮堂。"},{"en":"This phrase gives the final meeting a clear school location.","zh":"這個短語為最後見面提供清楚的校園位置。"}],"source":"2016 Q6.pdf","sourcePage":12},{"front":"try to speak to","meaning":"嘗試跟……說話","examples":[{"en":"Chris tried to speak to Mary after the ceremony.","zh":"Chris 在典禮之後嘗試跟 Mary 說話。"},{"en":"Try to speak to someone means attempt to start a conversation with them.","zh":"try to speak to someone 指嘗試與某人開始對話。"},{"en":"The student tried to speak to the teacher after class about her grade.","zh":"學生下課後嘗試跟老師談成績。"},{"en":"Chris tries to speak to Mary because he now knows she planned the exposure.","zh":"Chris 嘗試跟 Mary 說話，因為他現在知道是她策劃揭穿。"},{"en":"This phrase suggests an attempt that may or may not be welcomed.","zh":"這個短語暗示一次不一定受歡迎的嘗試。"}],"source":"2016 Q6.pdf","sourcePage":12},{"front":"hand someone something","meaning":"把某物遞給某人","examples":[{"en":"Mary handed Chris the blue fountain pen.","zh":"Mary 把藍色鋼筆遞給 Chris。"},{"en":"Hand someone something means give an object directly to a person.","zh":"hand someone something 指直接把某物交給某人。"},{"en":"The teacher handed each student a certificate.","zh":"老師把證書遞給每位學生。"},{"en":"Mary hands Chris the pen instead of giving him a long speech.","zh":"Mary 把鋼筆遞給 Chris，而不是給他長篇說話。"},{"en":"This phrase shows how an object can carry meaning in silence.","zh":"這個短語顯示物件如何在沉默中承載意思。"}],"source":"2016 Q6.pdf","sourcePage":12},{"front":"months before","meaning":"幾個月前","examples":[{"en":"Chris had emptied the pen months before.","zh":"Chris 幾個月前已把那支筆用光。"},{"en":"Months before means several months earlier than the present moment in the story.","zh":"months before 指比故事現在時刻早幾個月。"},{"en":"She had submitted the draft months before the competition.","zh":"她在比賽幾個月前已提交草稿。"},{"en":"Mentioning months before shows that Mary remembers small acts of disrespect.","zh":"提到幾個月前，顯示 Mary 記得細小的不尊重。"},{"en":"This phrase connects the final scene with an earlier wrong.","zh":"這個短語把最後場景與之前的錯事連在一起。"}],"source":"2016 Q6.pdf","sourcePage":12},{"front":"run out","meaning":"用完；耗盡","examples":[{"en":"The blue fountain pen had run out.","zh":"那支藍色鋼筆已經用完。"},{"en":"Run out means be used up so there is none left.","zh":"run out 指被用光，沒有剩下。"},{"en":"The printer ran out of paper before the reports were finished.","zh":"報告未完成前，打印機的紙用完了。"},{"en":"A fountain pen runs out when all the ink has been used.","zh":"當墨水全部用光，鋼筆就用完了。"},{"en":"In the story, the empty pen quietly reminds Chris of what he took.","zh":"在故事中，空了的鋼筆安靜地提醒 Chris 他曾拿走甚麼。"}],"source":"2016 Q6.pdf","sourcePage":12},{"front":"tuck shop","meaning":"小食部","examples":[{"en":"The tuck shop was selling honey cakes.","zh":"小食部正在賣蜂蜜蛋糕。"},{"en":"A tuck shop is a small school shop that sells snacks and drinks.","zh":"tuck shop 指學校裏售賣零食和飲品的小店。"},{"en":"Students bought sandwiches and juice from the tuck shop during recess.","zh":"學生在小息時從小食部買三文治和果汁。"},{"en":"A tuck shop makes the ending feel ordinary after the dramatic ceremony.","zh":"小食部令戲劇性的典禮之後的結尾感覺日常。"},{"en":"In the story, the tuck shop provides the honey cake that completes the title image.","zh":"在故事中，小食部提供蜂蜜蛋糕，完成標題中的蜂蜜意象。"}],"source":"2016 Q6.pdf","sourcePage":12},{"front":"honey cakes","meaning":"蜂蜜蛋糕","examples":[{"en":"Mary bought a honey cake outside the tuck shop.","zh":"Mary 在小食部外買了一個蜂蜜蛋糕。"},{"en":"Honey cakes are small cakes sweetened or flavoured with honey.","zh":"honey cakes 指用蜂蜜增甜或調味的小蛋糕。"},{"en":"Honey cakes may taste warm, soft and lightly sweet.","zh":"蜂蜜蛋糕可能吃起來溫暖、柔軟而微甜。"},{"en":"Buying honey cakes after the ceremony links Mary’s victory to sweetness.","zh":"典禮後買蜂蜜蛋糕，把 Mary 的勝利與甜味連在一起。"},{"en":"This phrase turns the story’s idea of sweet justice into a real food.","zh":"這個短語把故事中的甜美正義變成真正食物。"}],"source":"2016 Q6.pdf","sourcePage":12},{"front":"eat slowly","meaning":"慢慢吃","examples":[{"en":"Mary bought a honey cake and ate slowly.","zh":"Mary 買了一個蜂蜜蛋糕，然後慢慢吃。"},{"en":"Eat slowly means take small bites and not hurry while eating.","zh":"eat slowly 指小口進食，不匆忙。"},{"en":"After a stressful day, she ate slowly and let herself calm down.","zh":"壓力很大的一天後，她慢慢吃，讓自己平靜下來。"},{"en":"Mary eats slowly because she wants to feel the sweetness of the moment.","zh":"Mary 慢慢吃，因為她想感受這一刻的甜味。"},{"en":"This phrase makes the ending quiet and controlled.","zh":"這個短語令結尾安靜而受控制。"}],"source":"2016 Q6.pdf","sourcePage":12},{"front":"not because...because...","meaning":"不是因為……而是因為……","examples":[{"en":"Revenge was sweet not because Chris had fallen, but because Mary’s voice had risen.","zh":"復仇是甜蜜的，不是因為 Chris 倒下，而是因為 Mary 的聲音終於響起。"},{"en":"Not because A, but because B means A is not the real reason; B is the real reason.","zh":"not because A, but because B 指 A 不是真正原因，B 才是真正原因。"},{"en":"She felt proud not because she won, but because she had spoken honestly.","zh":"她感到自豪，不是因為勝出，而是因為自己誠實發聲。"},{"en":"Mary’s revenge is sweet not because Chris suffers, but because she regains her voice.","zh":"Mary 的復仇是甜蜜的，不是因為 Chris 受苦，而是因為她重新得到聲音。"},{"en":"This structure helps correct a shallow explanation with a deeper one.","zh":"這個結構幫助用更深層原因修正膚淺解釋。"}],"source":"2016 Q6.pdf","sourcePage":12},{"front":"fall","meaning":"倒下；失勢","examples":[{"en":"Chris had fallen after being exposed.","zh":"Chris 被揭穿後倒下了。"},{"en":"Fall here means lose status, confidence or public respect.","zh":"fall 在這裏指失去地位、自信或公眾尊重。"},{"en":"A dishonest leader may fall when the truth becomes public.","zh":"不誠實的領袖在真相公開後可能失勢。"},{"en":"Chris falls because the audience finally sees what he has done.","zh":"Chris 倒下，是因為觀眾終於看見他做了甚麼。"},{"en":"This word shows a loss of power rather than a physical fall.","zh":"這個詞顯示權力流失，而不只是身體跌倒。"}],"source":"2016 Q6.pdf","sourcePage":13},{"front":"at last","meaning":"終於","examples":[{"en":"At last, Mary’s voice had risen.","zh":"終於，Mary 的聲音響起了。"},{"en":"At last means finally, after waiting or struggling for a long time.","zh":"at last 指在長時間等待或掙扎後終於發生。"},{"en":"After many failed attempts, the student at last solved the problem.","zh":"經過多次失敗嘗試後，學生終於解開問題。"},{"en":"Mary speaks through her story at last after months of silence.","zh":"經過數月沉默後，Mary 終於透過故事發聲。"},{"en":"This phrase gives the ending a sense of relief.","zh":"這個短語為結尾帶來鬆一口氣的感覺。"}],"source":"2016 Q6.pdf","sourcePage":13},{"front":"my voice had risen","meaning":"我的聲音終於響起","examples":[{"en":"Mary’s voice had risen at last.","zh":"Mary 的聲音終於響起。"},{"en":"My voice had risen means I had finally spoken, been heard or gained power.","zh":"my voice had risen 指我終於發聲、被聽見或獲得力量。"},{"en":"After months of being ignored, her voice rose during the meeting.","zh":"被忽視數月後，她的聲音終於在會議中響起。"},{"en":"Mary’s voice rises not by shouting, but through careful writing and evidence.","zh":"Mary 的聲音不是透過大喊響起，而是透過仔細寫作和證據。"},{"en":"This phrase shows the true sweetness of the ending: Mary is no longer silent.","zh":"這個短語顯示結尾真正的甜味：Mary 不再沉默。"}],"source":"2016 Q6.pdf","sourcePage":13}],"dse/writing/part-b/2016/Q7":[{"front":"proposal for","meaning":"關於……的建議書","examples":[{"en":"This is a proposal for the Hong Kong Youth Festival.","zh":"這是一份關於香港青年節的建議書。"},{"en":"A proposal for something is a written plan that suggests what should be done.","zh":"A proposal for something 指一份建議應該做甚麼的書面計劃。"},{"en":"Students may write a proposal for a school fair to explain activities and benefits.","zh":"學生可能為學校嘉年華寫建議書，解釋活動和好處。"},{"en":"A good proposal for an event gives clear ideas, reasons and practical steps.","zh":"好的活動建議書會提出清楚想法、理據和實際步驟。"},{"en":"This phrase is useful in formal writing when suggesting a plan.","zh":"這個短語適合用於提出計劃的正式寫作。"}],"source":"2016 Q7.pdf","sourcePage":1},{"front":"organising committee","meaning":"籌備委員會","examples":[{"en":"The proposal is addressed to the Organising Committee.","zh":"這份建議書是寫給籌備委員會的。"},{"en":"An organising committee is a group of people responsible for planning and running an event.","zh":"Organising committee 指負責策劃和營運活動的一群人。"},{"en":"The organising committee decides the venue, programme and safety arrangements.","zh":"籌備委員會決定場地、節目和安全安排。"},{"en":"A festival can run smoothly when the organising committee communicates clearly.","zh":"當籌備委員會溝通清楚，節日活動就能順利進行。"},{"en":"This phrase is common in event proposals and formal letters.","zh":"這個短語常見於活動建議書和正式書信。"}],"source":"2016 Q7.pdf","sourcePage":1},{"front":"showcasing youth trends","meaning":"展示青年潮流","examples":[{"en":"The proposal suggests showcasing youth trends at the Youth Festival.","zh":"建議書建議在青年節展示青年潮流。"},{"en":"Showcasing youth trends means presenting popular interests, habits or styles among young people.","zh":"Showcasing youth trends 指呈現年輕人之間流行的興趣、習慣或風格。"},{"en":"A festival can showcase youth trends through booths, performances and workshops.","zh":"節日可以透過攤位、表演和工作坊展示青年潮流。"},{"en":"Showcasing youth trends helps adults understand what young people value today.","zh":"展示青年潮流有助成年人理解今天年輕人重視甚麼。"},{"en":"This phrase connects display with cultural understanding.","zh":"這個短語把展示和文化理解連接起來。"}],"source":"2016 Q7.pdf","sourcePage":1},{"front":"youth trends","meaning":"青年潮流","examples":[{"en":"The Festival could showcase two major youth trends.","zh":"青年節可以展示兩個主要青年潮流。"},{"en":"Youth trends are popular ideas, activities or styles among young people.","zh":"Youth trends 指年輕人之間流行的想法、活動或風格。"},{"en":"Short videos and sustainable fashion are examples of youth trends.","zh":"短片和可持續時裝都是青年潮流的例子。"},{"en":"Youth trends change when young people find new ways to express identity.","zh":"當年輕人找到新的身份表達方式，青年潮流就會改變。"},{"en":"This phrase is useful when discussing modern youth culture.","zh":"這個短語適合用來討論現代青年文化。"}],"source":"2016 Q7.pdf","sourcePage":1},{"front":"passive followers of","meaning":"……的被動追隨者","examples":[{"en":"Hong Kong’s young people are no longer passive followers of fashion.","zh":"香港年輕人不再是時尚的被動追隨者。"},{"en":"Passive followers of something are people who copy it without questioning or creating.","zh":"Passive followers of something 指不加質疑或創造，只是跟隨某事的人。"},{"en":"Students should not be passive followers of online trends if the trends are harmful.","zh":"如果網上潮流有害，學生不應成為它的被動追隨者。"},{"en":"Young people become creators when they stop being passive followers of fashion.","zh":"當年輕人不再做時尚的被動追隨者，他們就成為創作者。"},{"en":"This phrase contrasts copying with active choice.","zh":"這個短語把模仿和主動選擇作對比。"}],"source":"2016 Q7.pdf","sourcePage":1},{"front":"fashion, entertainment or technology","meaning":"時尚、娛樂或科技","examples":[{"en":"Young people are not passive followers of fashion, entertainment or technology.","zh":"年輕人不是時尚、娛樂或科技的被動追隨者。"},{"en":"Fashion, entertainment or technology means clothing styles, media activities and digital tools.","zh":"Fashion, entertainment or technology 指服裝風格、媒體活動和數碼工具。"},{"en":"Young people use fashion, entertainment and technology to express opinions and identity.","zh":"年輕人運用時尚、娛樂和科技來表達意見和身份。"},{"en":"These areas influence daily life because students wear, watch and use them every day.","zh":"這些範疇影響日常生活，因為學生每天都會穿、看和使用它們。"},{"en":"This phrase groups three major parts of youth culture.","zh":"這個短語概括青年文化的三個重要部分。"}],"source":"2016 Q7.pdf","sourcePage":1},{"front":"social awareness","meaning":"社會意識","examples":[{"en":"Many young people have social awareness in their minds.","zh":"許多年輕人心中有社會意識。"},{"en":"Social awareness means understanding social issues and caring about how they affect people.","zh":"Social awareness 指理解社會議題，並關心它們如何影響人。"},{"en":"A student shows social awareness when she thinks about waste, poverty or online safety.","zh":"當學生思考浪費、貧窮或網上安全時，她就表現出社會意識。"},{"en":"Social awareness can turn fashion or videos into messages about real problems.","zh":"社會意識可以把時裝或影片變成關於真實問題的訊息。"},{"en":"This phrase shows that youth culture can be thoughtful.","zh":"這個短語顯示青年文化可以有思考深度。"}],"source":"2016 Q7.pdf","sourcePage":1},{"front":"turn everyday life into","meaning":"把日常生活變成","examples":[{"en":"Young people are turning everyday life into a form of creativity.","zh":"年輕人正把日常生活變成一種創意形式。"},{"en":"Turn everyday life into something means change ordinary daily experience into something new or meaningful.","zh":"Turn everyday life into something 指把普通日常經驗變成新的或有意義的東西。"},{"en":"A student can turn everyday life into art by filming the journey to school.","zh":"學生可以拍攝上學路程，把日常生活變成藝術。"},{"en":"Social media helps young people turn meals, streets and hobbies into creative content.","zh":"社交媒體幫助年輕人把飯餐、街道和興趣變成創意內容。"},{"en":"This phrase shows transformation from ordinary life to expression.","zh":"這個短語顯示由日常生活到表達的轉化。"}],"source":"2016 Q7.pdf","sourcePage":1},{"front":"a form of creativity","meaning":"一種創意形式","examples":[{"en":"Everyday life can become a form of creativity.","zh":"日常生活可以成為一種創意形式。"},{"en":"A form of creativity is one way of using imagination to make or express something.","zh":"A form of creativity 指運用想像力去創作或表達的一種方式。"},{"en":"Cooking, dressing and filming can all become forms of creativity.","zh":"烹飪、穿搭和拍片都可以成為創意形式。"},{"en":"When students redesign old clothes, fashion becomes a form of creativity.","zh":"當學生重新設計舊衣服，時裝就成為一種創意形式。"},{"en":"This phrase helps show that creativity is not limited to traditional art.","zh":"這個短語幫助顯示創意不只限於傳統藝術。"}],"source":"2016 Q7.pdf","sourcePage":1},{"front":"in order to","meaning":"為了","examples":[{"en":"The Festival should be lively and meaningful in order to attract young people.","zh":"青年節應該生動而有意義，為了吸引年輕人。"},{"en":"In order to means for the purpose of doing something.","zh":"In order to 指為了達到某個目的。"},{"en":"The booths should be interactive in order to keep visitors interested.","zh":"攤位應該具互動性，為了令訪客保持興趣。"},{"en":"A proposal explains actions in order to show why they are useful.","zh":"建議書解釋行動，是為了顯示它們為何有用。"},{"en":"This phrase clearly connects an action with its purpose.","zh":"這個短語清楚連接行動和目的。"}],"source":"2016 Q7.pdf","sourcePage":1},{"front":"lively and meaningful","meaning":"生動而有意義","examples":[{"en":"The Youth Festival should be both lively and meaningful.","zh":"青年節應該既生動又有意義。"},{"en":"Lively and meaningful means energetic, enjoyable and also valuable in purpose.","zh":"Lively and meaningful 指充滿活力、有趣，而且有價值和目的。"},{"en":"A festival is lively and meaningful when visitors have fun and learn something important.","zh":"當訪客玩得開心又學到重要事情，節日就生動而有意義。"},{"en":"Music can make an event lively, while workshops can make it meaningful.","zh":"音樂可以令活動生動，工作坊則可以令活動有意義。"},{"en":"This phrase balances entertainment with purpose.","zh":"這個短語平衡娛樂和目的。"}],"source":"2016 Q7.pdf","sourcePage":2},{"front":"propose that","meaning":"建議","examples":[{"en":"I propose that the Festival showcase two major youth trends.","zh":"我建議青年節展示兩個主要青年潮流。"},{"en":"Propose that means formally suggest that something should be done.","zh":"Propose that 指正式建議應該做某事。"},{"en":"I propose that the school hold a recycling day each month.","zh":"我建議學校每月舉辦一次回收日。"},{"en":"In a proposal, this phrase introduces the writer’s main recommendation.","zh":"在建議書中，這個短語引出作者的主要建議。"},{"en":"It sounds formal and suitable for committee writing.","zh":"它語氣正式，適合寫給委員會。"}],"source":"2016 Q7.pdf","sourcePage":2},{"front":"major youth trends","meaning":"主要青年潮流","examples":[{"en":"The proposal focuses on two major youth trends.","zh":"這份建議書集中於兩個主要青年潮流。"},{"en":"Major youth trends are important popular developments among young people.","zh":"Major youth trends 指年輕人之間重要而流行的發展。"},{"en":"Digital content creation is a major youth trend because many students create online videos.","zh":"數碼內容創作是主要青年潮流，因為很多學生會製作網上影片。"},{"en":"A festival should choose major youth trends that many visitors can recognise.","zh":"青年節應選擇許多訪客都能認出的主要青年潮流。"},{"en":"This phrase helps show that the topics are significant.","zh":"這個短語幫助顯示題目具重要性。"}],"source":"2016 Q7.pdf","sourcePage":2},{"front":"short-form digital content creation","meaning":"短影片數碼內容創作","examples":[{"en":"Short-form digital content creation is a major youth trend.","zh":"短影片數碼內容創作是一個主要青年潮流。"},{"en":"Short-form digital content creation means making brief online videos, posts or media for digital platforms.","zh":"Short-form digital content creation 指為數碼平台製作簡短網上影片、貼文或媒體內容。"},{"en":"Students practise short-form digital content creation when they film school-life clips.","zh":"學生拍攝校園生活片段時，就是在練習短影片數碼內容創作。"},{"en":"It is popular because phones make filming and editing easy.","zh":"它受歡迎，因為手機令拍攝和剪輯變得容易。"},{"en":"This phrase connects youth creativity with online communication.","zh":"這個短語把青年創意和網上溝通連接起來。"}],"source":"2016 Q7.pdf","sourcePage":2},{"front":"sustainable streetwear culture","meaning":"可持續街頭服飾文化","examples":[{"en":"Sustainable streetwear culture should be shown at the Festival.","zh":"可持續街頭服飾文化應該在青年節展示。"},{"en":"Sustainable streetwear culture means casual fashion that values style, reuse and environmental care.","zh":"Sustainable streetwear culture 指重視風格、重用和環保的休閒服飾文化。"},{"en":"Young people join sustainable streetwear culture when they redesign second-hand jackets.","zh":"年輕人重新設計二手外套時，就是參與可持續街頭服飾文化。"},{"en":"This trend reduces waste while still allowing personal expression.","zh":"這股潮流減少浪費，同時仍讓人表達個性。"},{"en":"This phrase connects fashion with responsibility.","zh":"這個短語把時裝和責任連接起來。"}],"source":"2016 Q7.pdf","sourcePage":2},{"front":"not merely as displays","meaning":"不只是作為展示","examples":[{"en":"These trends should be presented not merely as displays.","zh":"這些潮流不應只是作為展示來呈現。"},{"en":"Not merely as displays means not only as things for visitors to look at.","zh":"Not merely as displays 指不只是讓訪客觀看的東西。"},{"en":"Youth trends should be experienced, not merely presented as displays behind tables.","zh":"青年潮流應該被體驗，而不只是放在桌子後作展示。"},{"en":"If visitors only look at posters, the festival may feel passive.","zh":"如果訪客只看海報，節日可能會顯得被動。"},{"en":"This phrase argues for deeper participation.","zh":"這個短語主張更深入的參與。"}],"source":"2016 Q7.pdf","sourcePage":2},{"front":"interactive experiences","meaning":"互動體驗","examples":[{"en":"The trends should be presented as interactive experiences.","zh":"這些潮流應作為互動體驗來呈現。"},{"en":"Interactive experiences are activities that allow visitors to take part, create or respond.","zh":"Interactive experiences 指讓訪客參與、創作或回應的活動。"},{"en":"A video booth is an interactive experience because visitors can film their own clips.","zh":"拍片攤位是互動體驗，因為訪客可以拍攝自己的短片。"},{"en":"Interactive experiences help young people learn by doing.","zh":"互動體驗幫助年輕人透過實踐學習。"},{"en":"This phrase suggests active participation, not passive watching.","zh":"這個短語暗示主動參與，而不是被動觀看。"}],"source":"2016 Q7.pdf","sourcePage":2},{"front":"through which","meaning":"透過……","examples":[{"en":"Visitors need experiences through which they can create and exchange ideas.","zh":"訪客需要一些體驗，透過這些體驗他們可以創作和交流想法。"},{"en":"Through which means by means of which or using which.","zh":"Through which 指透過某事物或藉着某事物。"},{"en":"The festival should provide workshops through which students can learn editing.","zh":"青年節應提供工作坊，讓學生透過它們學習剪輯。"},{"en":"A good activity gives visitors a channel through which they can express themselves.","zh":"好活動給訪客一個渠道，透過它表達自己。"},{"en":"This phrase links an activity with what it allows people to do.","zh":"這個短語把活動和它讓人做到的事情連接起來。"}],"source":"2016 Q7.pdf","sourcePage":2},{"front":"exchange ideas","meaning":"交流想法","examples":[{"en":"Visitors can create, perform and exchange ideas.","zh":"訪客可以創作、表演和交流想法。"},{"en":"Exchange ideas means share thoughts with others and listen to their thoughts too.","zh":"Exchange ideas 指與別人分享想法，也聆聽別人的想法。"},{"en":"Students exchange ideas when they discuss how to redesign old clothes.","zh":"學生討論如何改造舊衣服時，就是在交流想法。"},{"en":"Exchanging ideas can make a project stronger because people add different views.","zh":"交流想法可以令專題更好，因為人們加入不同觀點。"},{"en":"This phrase is useful for teamwork and creative events.","zh":"這個短語適合用於團隊合作和創意活動。"}],"source":"2016 Q7.pdf","sourcePage":2},{"front":"reflect on","meaning":"反思","examples":[{"en":"Visitors can reflect on what youth culture means today.","zh":"訪客可以反思今天青年文化的意義。"},{"en":"Reflect on means think carefully about something and its meaning.","zh":"Reflect on 指仔細思考某事及其意義。"},{"en":"After a workshop, students can reflect on how their online posts affect others.","zh":"工作坊後，學生可以反思自己的網上貼文如何影響他人。"},{"en":"Reflection helps visitors learn more than just facts from an activity.","zh":"反思幫助訪客從活動中學到不只是資料。"},{"en":"This phrase shows deeper thinking after experience.","zh":"這個短語顯示經驗後的深入思考。"}],"source":"2016 Q7.pdf","sourcePage":2},{"front":"youth culture","meaning":"青年文化","examples":[{"en":"The Festival should explore what youth culture means in Hong Kong today.","zh":"青年節應探索今天香港青年文化的意義。"},{"en":"Youth culture means the values, habits, styles and activities shared by young people.","zh":"Youth culture 指年輕人共同擁有的價值、習慣、風格和活動。"},{"en":"Music, fashion, online videos and social concerns can all be part of youth culture.","zh":"音樂、時裝、網上影片和社會關注都可以是青年文化的一部分。"},{"en":"Youth culture changes as young people respond to new technology and social issues.","zh":"青年文化會隨着年輕人回應新科技和社會議題而改變。"},{"en":"This phrase describes the living culture of young people.","zh":"這個短語描述年輕人活生生的文化。"}],"source":"2016 Q7.pdf","sourcePage":3},{"front":"worth presenting","meaning":"值得呈現","examples":[{"en":"The first trend worth presenting is short-form digital content creation.","zh":"第一個值得呈現的潮流是短影片數碼內容創作。"},{"en":"Worth presenting means valuable enough to be shown or explained to others.","zh":"Worth presenting 指有足夠價值向別人展示或解釋。"},{"en":"A student project is worth presenting if it teaches visitors something useful.","zh":"如果學生專題能教訪客有用知識，它就值得呈現。"},{"en":"This trend is worth presenting because many young people already practise it.","zh":"這股潮流值得呈現，因為許多年輕人已經在實踐它。"},{"en":"This phrase helps justify a choice in a proposal.","zh":"這個短語幫助在建議書中解釋選擇原因。"}],"source":"2016 Q7.pdf","sourcePage":3},{"front":"filmed for platforms","meaning":"為平台拍攝","examples":[{"en":"Many short videos are filmed for platforms such as Instagram and YouTube Shorts.","zh":"許多短片是為 Instagram 和 YouTube Shorts 等平台拍攝的。"},{"en":"Filmed for platforms means recorded for use on particular websites or apps.","zh":"Filmed for platforms 指為特定網站或應用程式錄製內容。"},{"en":"Students may film short clips for platforms where their classmates often watch videos.","zh":"學生可能為同學常看的平台拍攝短片。"},{"en":"Videos filmed for platforms are usually short, clear and easy to share.","zh":"為平台拍攝的影片通常簡短、清楚，並容易分享。"},{"en":"This phrase connects content creation with its intended audience.","zh":"這個短語把內容創作和目標觀眾連接起來。"}],"source":"2016 Q7.pdf","sourcePage":3},{"front":"platforms such as","meaning":"例如……的平台","examples":[{"en":"Young people film videos for platforms such as Instagram and YouTube Shorts.","zh":"年輕人為 Instagram 和 YouTube Shorts 等平台拍攝影片。"},{"en":"Platforms such as means websites or apps like the examples that follow.","zh":"Platforms such as 指像後面例子那樣的網站或應用程式。"},{"en":"Students share school projects on platforms such as YouTube and Instagram.","zh":"學生在 YouTube 和 Instagram 等平台分享學校專題。"},{"en":"This phrase introduces examples without listing every possible platform.","zh":"這個短語用來引入例子，而不需要列出所有可能平台。"},{"en":"It is useful when giving clear but not complete examples.","zh":"它適合用來給出清楚但不完整的例子。"}],"source":"2016 Q7.pdf","sourcePage":3},{"front":"YouTube Shorts","meaning":"YouTube 短片","examples":[{"en":"Some young people create videos for YouTube Shorts.","zh":"有些年輕人為 YouTube Shorts 創作影片。"},{"en":"YouTube Shorts is a platform feature for sharing short vertical videos.","zh":"YouTube Shorts 是用來分享短直向影片的平台功能。"},{"en":"Students may use YouTube Shorts to share quick tutorials or school-life clips.","zh":"學生可能使用 YouTube Shorts 分享快速教學或校園生活片段。"},{"en":"Because videos are short, creators need to express ideas clearly and quickly.","zh":"因為影片很短，創作者需要清楚而快速地表達想法。"},{"en":"This phrase names a common short-video platform.","zh":"這個短語指出一個常見短片平台。"}],"source":"2016 Q7.pdf","sourcePage":3},{"front":"TikTok-style channels","meaning":"TikTok 式頻道","examples":[{"en":"Young people also create videos for TikTok-style channels.","zh":"年輕人也為 TikTok 式頻道創作影片。"},{"en":"TikTok-style channels are short-video channels that use quick clips, music and visual trends.","zh":"TikTok-style channels 指使用快速片段、音樂和視覺潮流的短片頻道。"},{"en":"A TikTok-style channel may focus on food reviews, dance routines or daily jokes.","zh":"TikTok 式頻道可能集中於食評、舞蹈動作或日常笑話。"},{"en":"These channels attract young viewers because the content is fast and easy to watch.","zh":"這些頻道吸引年輕觀眾，因為內容快速而容易觀看。"},{"en":"This phrase describes a style of online video, not only one app.","zh":"這個短語描述一種網上短片風格，而不只是一個應用程式。"}],"source":"2016 Q7.pdf","sourcePage":3},{"front":"record food reviews","meaning":"記錄食評","examples":[{"en":"Young people use short videos to record food reviews.","zh":"年輕人用短片記錄食評。"},{"en":"Record food reviews means film opinions about restaurants, snacks or meals.","zh":"Record food reviews 指拍攝對餐廳、小食或飯餐的意見。"},{"en":"A student may record food reviews of affordable lunch places near school.","zh":"學生可能記錄學校附近平價午餐地點的食評。"},{"en":"Food reviews help viewers decide what to try and where to eat.","zh":"食評幫助觀眾決定嘗試甚麼和在哪裏吃。"},{"en":"This phrase shows how daily eating can become digital content.","zh":"這個短語顯示日常飲食如何變成數碼內容。"}],"source":"2016 Q7.pdf","sourcePage":3},{"front":"school life","meaning":"校園生活","examples":[{"en":"Short videos often show school life.","zh":"短片常展示校園生活。"},{"en":"School life means the daily experiences students have at school.","zh":"School life 指學生在學校中的日常經歷。"},{"en":"Homework, friendships, clubs and exams are all part of school life.","zh":"功課、友誼、學會和考試都是校園生活的一部分。"},{"en":"Videos about school life can help students feel that others share their worries.","zh":"關於校園生活的影片可以讓學生感到別人也有相同煩惱。"},{"en":"This phrase describes a familiar topic for young creators.","zh":"這個短語描述年輕創作者熟悉的題材。"}],"source":"2016 Q7.pdf","sourcePage":3},{"front":"dance routines","meaning":"舞蹈動作；舞蹈編排","examples":[{"en":"Teenagers record dance routines in short videos.","zh":"青少年在短片中記錄舞蹈動作。"},{"en":"Dance routines are planned sets of dance movements.","zh":"Dance routines 指預先編排好的一組舞蹈動作。"},{"en":"Students may practise dance routines for a performance or online challenge.","zh":"學生可能為表演或網上挑戰練習舞蹈編排。"},{"en":"A clear dance routine helps a group move together in time with music.","zh":"清楚的舞蹈編排幫助一組人跟着音樂一起動作。"},{"en":"This phrase is common in entertainment and social-media contexts.","zh":"這個短語常見於娛樂和社交媒體語境。"}],"source":"2016 Q7.pdf","sourcePage":3},{"front":"social commentary","meaning":"社會評論","examples":[{"en":"Some short videos include social commentary.","zh":"有些短片包含社會評論。"},{"en":"Social commentary means opinions or messages about problems in society.","zh":"Social commentary 指關於社會問題的意見或訊息。"},{"en":"A video about exam pressure can become social commentary if it questions unfair expectations.","zh":"如果一段關於考試壓力的影片質疑不公平期望，它就可以成為社會評論。"},{"en":"Young creators use humour to make social commentary easier to understand.","zh":"年輕創作者用幽默令社會評論更容易理解。"},{"en":"This phrase shows that short videos can discuss serious issues.","zh":"這個短語顯示短片也可以討論嚴肅議題。"}],"source":"2016 Q7.pdf","sourcePage":3},{"front":"local neighbourhood stories","meaning":"本區社區故事","examples":[{"en":"Young people use videos to tell local neighbourhood stories.","zh":"年輕人用影片講述本區社區故事。"},{"en":"Local neighbourhood stories are stories about ordinary places and people in a community.","zh":"Local neighbourhood stories 指關於社區中普通地方和人物的故事。"},{"en":"A video about an old snack shop can tell a local neighbourhood story.","zh":"一段關於舊小食店的影片可以講述本區社區故事。"},{"en":"These stories help young people value the streets and people around them.","zh":"這些故事幫助年輕人重視身邊的街道和人物。"},{"en":"This phrase connects digital media with community memory.","zh":"這個短語把數碼媒體和社區記憶連接起來。"}],"source":"2016 Q7.pdf","sourcePage":4},{"front":"low-cost way to","meaning":"低成本的……方法","examples":[{"en":"Short videos give teenagers a low-cost way to express themselves.","zh":"短片給青少年一種低成本的表達方法。"},{"en":"A low-cost way to do something means a method that does not require much money.","zh":"A low-cost way to do something 指不需要太多金錢的方法。"},{"en":"Using a phone is a low-cost way to make a simple video.","zh":"使用手機是製作簡單影片的低成本方法。"},{"en":"Low-cost creative tools allow more students to join, not only wealthy ones.","zh":"低成本創作工具讓更多學生參與，而不只限於富裕學生。"},{"en":"This phrase stresses accessibility.","zh":"這個短語強調易於參與。"}],"source":"2016 Q7.pdf","sourcePage":4},{"front":"express themselves","meaning":"表達自己","examples":[{"en":"Teenagers use digital content to express themselves.","zh":"青少年用數碼內容表達自己。"},{"en":"Express themselves means show their thoughts, feelings, identity or creativity.","zh":"Express themselves 指展示自己的想法、感受、身份或創意。"},{"en":"Students can express themselves through videos, clothes, music and writing.","zh":"學生可以透過影片、衣服、音樂和寫作表達自己。"},{"en":"When young people express themselves safely, they gain confidence and voice.","zh":"當年輕人安全地表達自己，他們會得到信心和聲音。"},{"en":"This phrase is important when discussing youth creativity.","zh":"討論青年創意時，這個短語很重要。"}],"source":"2016 Q7.pdf","sourcePage":4},{"front":"too shy to speak","meaning":"太害羞而不敢說話","examples":[{"en":"A student may be too shy to speak on a stage.","zh":"學生可能太害羞而不敢在舞台上說話。"},{"en":"Too shy to speak means so nervous or self-conscious that one cannot speak publicly.","zh":"Too shy to speak 指因太緊張或太在意自己而不能公開說話。"},{"en":"A quiet student may be too shy to speak in front of classmates.","zh":"安靜的學生可能太害羞而不敢在同學面前說話。"},{"en":"Digital videos can help shy students express ideas without live pressure.","zh":"數碼影片可以幫助害羞學生在沒有現場壓力下表達想法。"},{"en":"This phrase shows a barrier to public expression.","zh":"這個短語顯示公開表達的障礙。"}],"source":"2016 Q7.pdf","sourcePage":4},{"front":"on a stage","meaning":"在舞台上","examples":[{"en":"Some students are too shy to speak on a stage.","zh":"有些學生太害羞而不敢在舞台上說話。"},{"en":"On a stage means in front of an audience in a performance or presentation area.","zh":"On a stage 指在表演或演講空間中面對觀眾。"},{"en":"Speaking on a stage can feel frightening because many people are watching.","zh":"在舞台上說話可能令人害怕，因為很多人在觀看。"},{"en":"A festival can offer other ways to share ideas besides going on a stage.","zh":"青年節可以提供上台以外的分享想法方式。"},{"en":"This phrase describes public performance or presentation.","zh":"這個短語描述公開表演或匯報。"}],"source":"2016 Q7.pdf","sourcePage":4},{"front":"edit a thirty-second video","meaning":"剪輯一段三十秒短片","examples":[{"en":"A shy student can still edit a thirty-second video.","zh":"害羞的學生仍然可以剪輯一段三十秒短片。"},{"en":"Edit a thirty-second video means arrange and improve a short video clip lasting half a minute.","zh":"Edit a thirty-second video 指整理和改善一段半分鐘的短片。"},{"en":"Students can edit a thirty-second video with captions, music and simple cuts.","zh":"學生可以用字幕、音樂和簡單剪接剪輯一段三十秒短片。"},{"en":"Editing a short video gives quiet students another way to speak.","zh":"剪輯短片給安靜學生另一種發聲方式。"},{"en":"This phrase shows a practical digital skill.","zh":"這個短語顯示一項實用數碼技能。"}],"source":"2016 Q7.pdf","sourcePage":4},{"front":"hidden basketball courts","meaning":"隱藏的籃球場","examples":[{"en":"A student can make a video about hidden basketball courts.","zh":"學生可以製作關於隱藏籃球場的影片。"},{"en":"Hidden basketball courts are small or less-known places where people play basketball.","zh":"Hidden basketball courts 指較小或較少人知道的打籃球地方。"},{"en":"A video about hidden basketball courts can introduce useful spaces in a neighbourhood.","zh":"關於隱藏籃球場的影片可以介紹社區中有用的空間。"},{"en":"These courts matter because young people often build friendships there.","zh":"這些球場重要，因為年輕人常在那裏建立友誼。"},{"en":"This phrase turns ordinary local places into meaningful stories.","zh":"這個短語把普通本地地方變成有意義的故事。"}],"source":"2016 Q7.pdf","sourcePage":4},{"front":"examination stress","meaning":"考試壓力","examples":[{"en":"Students can make short videos about examination stress.","zh":"學生可以製作關於考試壓力的短片。"},{"en":"Examination stress means pressure and worry caused by tests or exams.","zh":"Examination stress 指由測驗或考試造成的壓力和憂慮。"},{"en":"Examination stress may make students sleep badly or feel unable to relax.","zh":"考試壓力可能令學生睡不好或無法放鬆。"},{"en":"A short video about examination stress can help students realise they are not alone.","zh":"關於考試壓力的短片可以幫助學生明白自己並不孤單。"},{"en":"This phrase is useful when discussing school pressure.","zh":"這個短語適合用來討論校園壓力。"}],"source":"2016 Q7.pdf","sourcePage":4},{"front":"in other words","meaning":"換句話說","examples":[{"en":"In other words, digital content is about identity and voice.","zh":"換句話說，數碼內容關乎身份和聲音。"},{"en":"In other words means saying the same idea again in a clearer or simpler way.","zh":"In other words 指用更清楚或更簡單的方式重說同一個想法。"},{"en":"Young people are not only watching videos; in other words, they are creating culture.","zh":"年輕人不只是觀看影片；換句話說，他們正在創造文化。"},{"en":"Writers use this phrase to explain a point more directly.","zh":"作者用這個短語更直接地解釋重點。"},{"en":"It helps readers understand the main meaning.","zh":"它幫助讀者理解主要意思。"}],"source":"2016 Q7.pdf","sourcePage":4},{"front":"not just about entertainment","meaning":"不只是關於娛樂","examples":[{"en":"Digital content is not just about entertainment.","zh":"數碼內容不只是關於娛樂。"},{"en":"Not just about entertainment means it has deeper purposes than making people laugh or relax.","zh":"Not just about entertainment 指它不只為了令人發笑或放鬆，還有更深目的。"},{"en":"A short video can discuss exam pressure, so it is not just about entertainment.","zh":"短片可以討論考試壓力，所以它不只是關於娛樂。"},{"en":"Digital content becomes meaningful when it gives young people a voice.","zh":"當數碼內容給年輕人聲音，它就變得有意義。"},{"en":"This phrase moves from surface fun to deeper value.","zh":"這個短語由表面樂趣推向更深價值。"}],"source":"2016 Q7.pdf","sourcePage":4},{"front":"identity, confidence and voice","meaning":"身份、信心和聲音","examples":[{"en":"Digital content is about identity, confidence and voice.","zh":"數碼內容關乎身份、信心和聲音。"},{"en":"Identity, confidence and voice mean knowing who you are, believing in yourself and expressing your views.","zh":"Identity, confidence and voice 指知道自己是誰、相信自己，並表達自己的看法。"},{"en":"A student gains identity, confidence and voice when her video is understood by others.","zh":"當學生的影片被別人理解，她就得到身份感、信心和聲音。"},{"en":"Creative platforms can help young people explore these three qualities.","zh":"創作平台可以幫助年輕人探索這三種特質。"},{"en":"This phrase summarises the personal value of content creation.","zh":"這個短語總結內容創作的個人價值。"}],"source":"2016 Q7.pdf","sourcePage":5},{"front":"present this trend effectively","meaning":"有效呈現這股潮流","examples":[{"en":"The Festival should present this trend effectively.","zh":"青年節應有效呈現這股潮流。"},{"en":"Present this trend effectively means show the trend in a clear, attractive and useful way.","zh":"Present this trend effectively 指以清楚、吸引和有用的方式展示這股潮流。"},{"en":"A festival presents digital creation effectively when visitors can make their own videos.","zh":"當訪客可以製作自己的影片，青年節就有效呈現數碼創作。"},{"en":"Effective presentation helps people understand why a trend matters.","zh":"有效呈現能幫助人理解一股潮流為何重要。"},{"en":"This phrase is useful for explaining event design.","zh":"這個短語適合用來解釋活動設計。"}],"source":"2016 Q7.pdf","sourcePage":5},{"front":"setting up","meaning":"設立","examples":[{"en":"The proposal suggests setting up a Creator Studio Zone.","zh":"建議書建議設立創作者工作室區。"},{"en":"Setting up means creating, arranging or preparing something for use.","zh":"Setting up 指建立、安排或準備某物供人使用。"},{"en":"The school is setting up a booth for student artwork.","zh":"學校正在設立一個學生藝術作品攤位。"},{"en":"Setting up a studio zone requires space, equipment and helpers.","zh":"設立工作室區需要空間、設備和助手。"},{"en":"This phrase is common when planning events.","zh":"這個短語常見於活動策劃。"}],"source":"2016 Q7.pdf","sourcePage":5},{"front":"Creator Studio Zone","meaning":"創作者工作室區","examples":[{"en":"The Creator Studio Zone would allow visitors to make videos.","zh":"創作者工作室區會讓訪客製作影片。"},{"en":"A Creator Studio Zone is an area where visitors can film, edit and share creative content.","zh":"Creator Studio Zone 指讓訪客拍攝、剪輯和分享創意內容的區域。"},{"en":"The Creator Studio Zone could include lights, backdrops and editing stations.","zh":"創作者工作室區可以包括燈光、背景板和剪片站。"},{"en":"This zone helps visitors become creators instead of only viewers.","zh":"這個區域幫助訪客成為創作者，而不只是觀眾。"},{"en":"The phrase names a proposed festival area.","zh":"這個短語指出建議中的節日區域名稱。"}],"source":"2016 Q7.pdf","sourcePage":5},{"front":"filming corner","meaning":"拍攝角","examples":[{"en":"The zone could include a filming corner.","zh":"這個區域可以包括一個拍攝角。"},{"en":"A filming corner is a small area prepared for recording videos.","zh":"Filming corner 指準備用來錄製影片的小區域。"},{"en":"A filming corner may provide good lighting, a clean background and space for movement.","zh":"拍攝角可以提供良好燈光、整潔背景和活動空間。"},{"en":"Students can use a filming corner to record short messages or performances.","zh":"學生可以用拍攝角錄製短訊息或表演。"},{"en":"This phrase describes a practical part of a creator zone.","zh":"這個短語描述創作者區的實用部分。"}],"source":"2016 Q7.pdf","sourcePage":5},{"front":"simple lighting and backdrops","meaning":"簡單燈光和背景板","examples":[{"en":"The filming corner could provide simple lighting and backdrops.","zh":"拍攝角可以提供簡單燈光和背景板。"},{"en":"Simple lighting and backdrops are basic lights and background materials used for filming.","zh":"Simple lighting and backdrops 指拍攝用的基本燈光和背景材料。"},{"en":"Simple lighting helps faces appear clearly in a video.","zh":"簡單燈光幫助影片中的臉部更清楚。"},{"en":"Backdrops can make a small filming corner look more professional.","zh":"背景板可以令小型拍攝角看起來更專業。"},{"en":"This phrase refers to affordable equipment for content creation.","zh":"這個短語指內容創作中的平價設備。"}],"source":"2016 Q7.pdf","sourcePage":5},{"front":"editing station","meaning":"剪片站","examples":[{"en":"The zone could include an editing station.","zh":"這個區域可以包括剪片站。"},{"en":"An editing station is a place with tools for cutting, arranging and improving videos.","zh":"Editing station 指設有工具，用來剪接、整理和改善影片的地方。"},{"en":"Students can add captions and transitions at an editing station.","zh":"學生可以在剪片站加入字幕和轉場效果。"},{"en":"An editing station helps beginners learn basic post-production skills.","zh":"剪片站幫助初學者學習基本後期製作技能。"},{"en":"This phrase describes a hands-on digital learning area.","zh":"這個短語描述實踐式數碼學習區域。"}],"source":"2016 Q7.pdf","sourcePage":5},{"front":"basic captioning","meaning":"基本字幕製作","examples":[{"en":"Volunteers could teach basic captioning.","zh":"義工可以教授基本字幕製作。"},{"en":"Basic captioning means adding simple written words to a video to show speech or key ideas.","zh":"Basic captioning 指在影片中加入簡單文字，以顯示說話內容或重點。"},{"en":"Captions help viewers understand videos even when the sound is off.","zh":"字幕幫助觀眾在關掉聲音時也理解影片。"},{"en":"Basic captioning makes digital content clearer and more accessible.","zh":"基本字幕製作令數碼內容更清楚，也更容易接觸。"},{"en":"This phrase describes an important beginner editing skill.","zh":"這個短語描述重要的初階剪輯技能。"}],"source":"2016 Q7.pdf","sourcePage":5},{"front":"transitions","meaning":"轉場效果","examples":[{"en":"Volunteers could teach basic captioning and transitions.","zh":"義工可以教授基本字幕製作和轉場效果。"},{"en":"Transitions are editing effects that move a video from one shot or scene to another.","zh":"Transitions 指影片從一個鏡頭或場景轉到另一個時使用的剪輯效果。"},{"en":"A simple transition can connect two clips smoothly.","zh":"簡單轉場效果可以順暢連接兩段片段。"},{"en":"Too many transitions may distract viewers from the message.","zh":"太多轉場效果可能令觀眾分心，忽略訊息。"},{"en":"This word is useful when discussing video editing.","zh":"討論影片剪輯時，這個詞很有用。"}],"source":"2016 Q7.pdf","sourcePage":5},{"front":"One-Minute Hong Kong Challenge","meaning":"一分鐘香港挑戰","examples":[{"en":"Participants could join a One-Minute Hong Kong Challenge.","zh":"參加者可以參與一分鐘香港挑戰。"},{"en":"A One-Minute Hong Kong Challenge is a short-video activity asking people to show Hong Kong in one minute.","zh":"One-Minute Hong Kong Challenge 指要求人們用一分鐘展示香港的短片活動。"},{"en":"Participants may film food, school life, street art or community stories.","zh":"參加者可以拍攝食物、校園生活、街頭藝術或社區故事。"},{"en":"The time limit makes creators choose their message carefully.","zh":"時間限制令創作者必須小心選擇訊息。"},{"en":"This phrase names a proposed festival competition.","zh":"這個短語指出建議中的節日比賽名稱。"}],"source":"2016 Q7.pdf","sourcePage":5},{"front":"create a short video","meaning":"創作一段短片","examples":[{"en":"Participants create a short video about youth life.","zh":"參加者創作一段關於青年生活的短片。"},{"en":"Create a short video means make a brief filmed piece with a clear idea.","zh":"Create a short video 指製作一段有清楚想法的簡短影片。"},{"en":"Students can create a short video using a phone and simple editing tools.","zh":"學生可以用手機和簡單剪輯工具創作一段短片。"},{"en":"Creating a short video teaches planning, filming and communication.","zh":"創作短片教人計劃、拍攝和溝通。"},{"en":"This phrase describes a practical creative task.","zh":"這個短語描述一項實用創作任務。"}],"source":"2016 Q7.pdf","sourcePage":6},{"front":"introducing something meaningful","meaning":"介紹有意義的事物","examples":[{"en":"The challenge asks participants to create a video introducing something meaningful.","zh":"這個挑戰要求參加者創作一段介紹有意義事物的影片。"},{"en":"Introducing something meaningful means presenting a subject that has personal, social or cultural value.","zh":"Introducing something meaningful 指呈現一個有個人、社會或文化價值的題材。"},{"en":"A student may introduce a family shop that has served the neighbourhood for years.","zh":"學生可能介紹一間服務社區多年的家庭小店。"},{"en":"Meaningful topics help videos feel deeper than simple entertainment.","zh":"有意義的題材令影片不只是簡單娛樂，而更有深度。"},{"en":"This phrase encourages creators to think about value.","zh":"這個短語鼓勵創作者思考價值。"}],"source":"2016 Q7.pdf","sourcePage":6},{"front":"youth life","meaning":"青年生活","examples":[{"en":"The videos should introduce something meaningful about youth life.","zh":"影片應介紹一些關於青年生活的有意義事物。"},{"en":"Youth life means the daily experiences, concerns and interests of young people.","zh":"Youth life 指年輕人的日常經歷、關注和興趣。"},{"en":"Youth life may include study pressure, friendships, hobbies and online expression.","zh":"青年生活可以包括學業壓力、友誼、興趣和網上表達。"},{"en":"A festival about youth life should let young people speak for themselves.","zh":"關於青年生活的節日應讓年輕人為自己發聲。"},{"en":"This phrase focuses on real young people, not adult assumptions.","zh":"這個短語集中於真實年輕人，而不是成年人假設。"}],"source":"2016 Q7.pdf","sourcePage":6},{"front":"best entries","meaning":"最佳作品","examples":[{"en":"The best entries could be shown every hour.","zh":"最佳作品可以每小時展示一次。"},{"en":"Best entries are the strongest submissions in a competition or activity.","zh":"Best entries 指比賽或活動中最出色的提交作品。"},{"en":"Judges may choose the best entries based on creativity, clarity and message.","zh":"評判可能根據創意、清晰度和訊息選出最佳作品。"},{"en":"Showing the best entries encourages participants to take the challenge seriously.","zh":"展示最佳作品能鼓勵參加者認真對待挑戰。"},{"en":"This phrase is useful when discussing contests.","zh":"討論比賽時，這個短語很有用。"}],"source":"2016 Q7.pdf","sourcePage":6},{"front":"central screen","meaning":"中央屏幕","examples":[{"en":"The best entries could be shown on a central screen.","zh":"最佳作品可以在中央屏幕上展示。"},{"en":"A central screen is a large display placed where many visitors can see it.","zh":"Central screen 指放在人多可見位置的大型顯示屏。"},{"en":"A central screen can show videos, announcements and live results.","zh":"中央屏幕可以播放影片、公告和即時結果。"},{"en":"Placing entries on a central screen gives young creators public recognition.","zh":"把作品放在中央屏幕上，能給年輕創作者公開肯定。"},{"en":"This phrase describes a visible display point at an event.","zh":"這個短語描述活動中的可見展示位置。"}],"source":"2016 Q7.pdf","sourcePage":6},{"front":"every hour","meaning":"每小時","examples":[{"en":"The videos could be shown every hour.","zh":"影片可以每小時展示一次。"},{"en":"Every hour means once in each sixty-minute period.","zh":"Every hour 指每六十分鐘一次。"},{"en":"Festival announcements can be made every hour so visitors know the schedule.","zh":"活動公告可以每小時播放，讓訪客知道時間表。"},{"en":"Showing videos every hour keeps the event active throughout the day.","zh":"每小時展示影片能令活動整天保持活力。"},{"en":"This phrase is useful for describing regular timing.","zh":"這個短語適合用來描述定時安排。"}],"source":"2016 Q7.pdf","sourcePage":6},{"front":"more engaging than","meaning":"比……更吸引","examples":[{"en":"This format would be more engaging than a lecture.","zh":"這種形式會比講座更吸引。"},{"en":"More engaging than means more interesting and likely to hold people’s attention.","zh":"More engaging than 指更有趣，更能吸引人注意。"},{"en":"A hands-on workshop is often more engaging than a long speech.","zh":"實踐工作坊通常比長篇演講更吸引。"},{"en":"Interactive activities are more engaging than lectures because visitors can take part.","zh":"互動活動比講座更吸引，因為訪客可以參與。"},{"en":"This phrase helps compare presentation methods.","zh":"這個短語幫助比較呈現方法。"}],"source":"2016 Q7.pdf","sourcePage":6},{"front":"would not simply watch","meaning":"不只是觀看","examples":[{"en":"Visitors would not simply watch creators.","zh":"訪客不只是觀看創作者。"},{"en":"Would not simply watch means would do more than observe passively.","zh":"Would not simply watch 指不只是被動觀看。"},{"en":"At the studio zone, visitors would not simply watch videos; they would make their own.","zh":"在工作室區，訪客不只是觀看影片，而是製作自己的影片。"},{"en":"People learn more when they do not simply watch but try the activity themselves.","zh":"當人們不只是觀看，而是親身嘗試活動，他們會學得更多。"},{"en":"This phrase argues for active participation.","zh":"這個短語主張主動參與。"}],"source":"2016 Q7.pdf","sourcePage":6},{"front":"become creators themselves","meaning":"親自成為創作者","examples":[{"en":"Visitors would become creators themselves.","zh":"訪客會親自成為創作者。"},{"en":"Become creators themselves means personally take part in making something creative.","zh":"Become creators themselves 指親自參與製作創意作品。"},{"en":"Students become creators themselves when they film, edit and share their own stories.","zh":"當學生拍攝、剪輯並分享自己的故事，他們就親自成為創作者。"},{"en":"A festival is more youth-led when visitors become creators themselves.","zh":"當訪客親自成為創作者，青年節就更由青年主導。"},{"en":"This phrase changes visitors from audience members into active participants.","zh":"這個短語把訪客由觀眾變成主動參與者。"}],"source":"2016 Q7.pdf","sourcePage":6},{"front":"encourage responsible online behaviour","meaning":"鼓勵負責任的網上行為","examples":[{"en":"The workshops would encourage responsible online behaviour.","zh":"工作坊會鼓勵負責任的網上行為。"},{"en":"Encourage responsible online behaviour means teach people to act safely, respectfully and thoughtfully on the internet.","zh":"Encourage responsible online behaviour 指教人安全、尊重和 thoughtful 地使用互聯網。"},{"en":"Workshops can encourage responsible online behaviour by discussing privacy and copyright.","zh":"工作坊可以透過討論私隱和版權，鼓勵負責任的網上行為。"},{"en":"Young creators need responsibility because online content can affect others.","zh":"年輕創作者需要責任感，因為網上內容可以影響他人。"},{"en":"This phrase connects digital creativity with ethics.","zh":"這個短語把數碼創意和倫理連接起來。"}],"source":"2016 Q7.pdf","sourcePage":6},{"front":"responsible online behaviour","meaning":"負責任的網上行為","examples":[{"en":"Participants should learn responsible online behaviour.","zh":"參加者應學習負責任的網上行為。"},{"en":"Responsible online behaviour means using the internet safely, respectfully and honestly.","zh":"Responsible online behaviour 指安全、尊重和誠實地使用互聯網。"},{"en":"Asking permission before filming someone is responsible online behaviour.","zh":"拍攝別人前先取得同意，就是負責任的網上行為。"},{"en":"Responsible online behaviour helps prevent harm such as cyberbullying or privacy loss.","zh":"負責任的網上行為有助防止網絡欺凌或私隱外洩等傷害。"},{"en":"This phrase is important for young digital creators.","zh":"這個短語對年輕數碼創作者很重要。"}],"source":"2016 Q7.pdf","sourcePage":7},{"front":"short workshops","meaning":"短工作坊","examples":[{"en":"Short workshops could remind participants about online safety.","zh":"短工作坊可以提醒參加者注意網上安全。"},{"en":"Short workshops are brief learning sessions focused on a practical topic.","zh":"Short workshops 指集中於實用題目的簡短學習環節。"},{"en":"A short workshop can teach students how to add captions in ten minutes.","zh":"短工作坊可以在十分鐘內教學生如何加入字幕。"},{"en":"Short workshops are useful at festivals because visitors may not have much time.","zh":"短工作坊適合節日活動，因為訪客可能沒有太多時間。"},{"en":"This phrase suggests quick but meaningful learning.","zh":"這個短語暗示快速但有意義的學習。"}],"source":"2016 Q7.pdf","sourcePage":7},{"front":"remind participants how to","meaning":"提醒參加者如何","examples":[{"en":"Workshops could remind participants how to respect copyright.","zh":"工作坊可以提醒參加者如何尊重版權。"},{"en":"Remind participants how to means help people remember the correct way to do something.","zh":"Remind participants how to 指幫助參加者記得做某事的正確方法。"},{"en":"Volunteers can remind participants how to ask for filming permission.","zh":"義工可以提醒參加者如何取得拍攝同意。"},{"en":"Reminders are useful because young creators may forget rules when excited.","zh":"提醒很有用，因為年輕創作者興奮時可能忘記規則。"},{"en":"This phrase gives practical guidance in a gentle way.","zh":"這個短語以溫和方式提供實用指引。"}],"source":"2016 Q7.pdf","sourcePage":7},{"front":"respect copyright","meaning":"尊重版權","examples":[{"en":"Participants should learn to respect copyright.","zh":"參加者應學習尊重版權。"},{"en":"Respect copyright means use other people’s music, images or work legally and fairly.","zh":"Respect copyright 指合法而公平地使用別人的音樂、圖片或作品。"},{"en":"A student respects copyright by using original music or properly licensed material.","zh":"學生使用原創音樂或有授權的材料，就是尊重版權。"},{"en":"Respecting copyright protects creators and prevents unfair copying.","zh":"尊重版權能保護創作者並防止不公平抄襲。"},{"en":"This phrase is essential in digital content creation.","zh":"這個短語在數碼內容創作中很重要。"}],"source":"2016 Q7.pdf","sourcePage":7},{"front":"protect privacy","meaning":"保護私隱","examples":[{"en":"Young creators should protect privacy.","zh":"年輕創作者應保護私隱。"},{"en":"Protect privacy means keep personal information and private moments safe.","zh":"Protect privacy 指保護個人資料和私人時刻。"},{"en":"Students protect privacy by not showing classmates’ faces without permission.","zh":"學生未經同意不展示同學樣貌，就是保護私隱。"},{"en":"Privacy protection matters because online videos can spread quickly.","zh":"保護私隱很重要，因為網上影片可以快速傳播。"},{"en":"This phrase teaches safety and respect.","zh":"這個短語教人安全和尊重。"}],"source":"2016 Q7.pdf","sourcePage":7},{"front":"avoid cyberbullying","meaning":"避免網絡欺凌","examples":[{"en":"Workshops could teach participants to avoid cyberbullying.","zh":"工作坊可以教參加者避免網絡欺凌。"},{"en":"Avoid cyberbullying means not use online tools to insult, threaten or shame others.","zh":"Avoid cyberbullying 指不使用網上工具侮辱、威脅或羞辱他人。"},{"en":"A creator avoids cyberbullying by refusing to post cruel jokes about classmates.","zh":"創作者拒絕發布關於同學的殘酷笑話，就是避免網絡欺凌。"},{"en":"Cyberbullying can seriously hurt someone’s confidence and mental health.","zh":"網絡欺凌可以嚴重傷害別人的信心和心理健康。"},{"en":"This phrase connects online behaviour with responsibility.","zh":"這個短語把網上行為和責任連接起來。"}],"source":"2016 Q7.pdf","sourcePage":7},{"front":"sustainable streetwear","meaning":"可持續街頭服飾","examples":[{"en":"The second trend is sustainable streetwear.","zh":"第二個潮流是可持續街頭服飾。"},{"en":"Sustainable streetwear is casual fashion that reduces waste and supports reuse.","zh":"Sustainable streetwear 指減少浪費並支持重用的休閒時裝。"},{"en":"Second-hand jackets and redesigned tote bags can be part of sustainable streetwear.","zh":"二手外套和改造帆布袋都可以是可持續街頭服飾的一部分。"},{"en":"Young people choose sustainable streetwear to look stylish without buying too much new clothing.","zh":"年輕人選擇可持續街頭服飾，為了有時尚感而不過度購買新衣。"},{"en":"This phrase connects street fashion with environmental care.","zh":"這個短語把街頭時裝和環保連接起來。"}],"source":"2016 Q7.pdf","sourcePage":7},{"front":"thrift shopping","meaning":"二手購物","examples":[{"en":"Sustainable streetwear includes thrift shopping.","zh":"可持續街頭服飾包括二手購物。"},{"en":"Thrift shopping means buying second-hand items, often at lower prices.","zh":"Thrift shopping 指購買二手物品，通常價錢較低。"},{"en":"Students may go thrift shopping to find unique jackets or bags.","zh":"學生可能去二手購物，尋找獨特外套或袋。"},{"en":"Thrift shopping can reduce waste because old clothes are used again.","zh":"二手購物可以減少浪費，因為舊衣物被再次使用。"},{"en":"This phrase is common in discussions of sustainable fashion.","zh":"這個短語常見於可持續時裝討論。"}],"source":"2016 Q7.pdf","sourcePage":7},{"front":"upcycling","meaning":"升級再造","examples":[{"en":"Sustainable streetwear includes upcycling.","zh":"可持續街頭服飾包括升級再造。"},{"en":"Upcycling means turning old or unwanted materials into something more useful or attractive.","zh":"Upcycling 指把舊的或不想要的材料變成更有用或更吸引的東西。"},{"en":"Students practise upcycling when they turn an old shirt into a tote bag.","zh":"學生把舊恤衫改成帆布袋時，就是在升級再造。"},{"en":"Upcycling reduces waste and allows personal creativity.","zh":"升級再造減少浪費，也容許個人創意。"},{"en":"This word is important in sustainable design.","zh":"這個詞在可持續設計中很重要。"}],"source":"2016 Q7.pdf","sourcePage":7},{"front":"outfit customisation","meaning":"服裝個人化改造","examples":[{"en":"Young people enjoy outfit customisation.","zh":"年輕人喜歡服裝個人化改造。"},{"en":"Outfit customisation means changing clothes to match personal taste or identity.","zh":"Outfit customisation 指改動衣服，使其配合個人口味或身份。"},{"en":"A student may add patches or paint to a jacket for outfit customisation.","zh":"學生可能在外套上加布章或繪畫，進行服裝個人化改造。"},{"en":"Customisation makes fashion feel personal instead of mass-produced.","zh":"個人化改造令時裝感覺個人化，而不是大量生產。"},{"en":"This phrase connects clothing with self-expression.","zh":"這個短語把衣服和自我表達連接起來。"}],"source":"2016 Q7.pdf","sourcePage":7},{"front":"among young people","meaning":"在年輕人之中","examples":[{"en":"Among young people, fashion is no longer limited to new items.","zh":"在年輕人之中，時尚不再局限於新貨品。"},{"en":"Among young people means within the group of young people.","zh":"Among young people 指在年輕人這個群體之內。"},{"en":"Among young people, short videos are often used to share opinions quickly.","zh":"在年輕人之中，短片常用來快速分享意見。"},{"en":"Trends spread quickly among young people when friends share them online.","zh":"當朋友在網上分享，潮流會在年輕人之中快速傳播。"},{"en":"This phrase identifies the group being discussed.","zh":"這個短語指出正在討論的群體。"}],"source":"2016 Q7.pdf","sourcePage":8},{"front":"no longer limited to","meaning":"不再局限於","examples":[{"en":"Fashion is no longer limited to buying expensive new items.","zh":"時尚不再局限於購買昂貴新貨品。"},{"en":"No longer limited to means not restricted to one old or narrow choice anymore.","zh":"No longer limited to 指不再受限於一個舊有或狹窄選擇。"},{"en":"Learning is no longer limited to classrooms because students can study online.","zh":"學習不再局限於課室，因為學生可以在網上學習。"},{"en":"Youth fashion is no longer limited to new clothes when upcycling becomes popular.","zh":"當升級再造流行，青年時裝就不再局限於新衣服。"},{"en":"This phrase shows expansion and change.","zh":"這個短語顯示擴闊和改變。"}],"source":"2016 Q7.pdf","sourcePage":8},{"front":"expensive new items","meaning":"昂貴新貨品","examples":[{"en":"Many young people do not want only expensive new items.","zh":"許多年輕人不只想要昂貴新貨品。"},{"en":"Expensive new items are newly bought products that cost a lot of money.","zh":"Expensive new items 指新買而價錢高的產品。"},{"en":"Students may avoid expensive new items because they want to save money.","zh":"學生可能避免購買昂貴新貨品，因為他們想省錢。"},{"en":"Second-hand fashion offers another choice besides expensive new items.","zh":"二手時裝提供昂貴新貨品以外的另一個選擇。"},{"en":"This phrase helps contrast consumption with sustainability.","zh":"這個短語幫助對比消費和可持續性。"}],"source":"2016 Q7.pdf","sourcePage":8},{"front":"second-hand jackets","meaning":"二手外套","examples":[{"en":"Many young people prefer second-hand jackets.","zh":"許多年輕人較喜歡二手外套。"},{"en":"Second-hand jackets are jackets that were owned or used by someone before.","zh":"Second-hand jackets 指曾由別人擁有或穿過的外套。"},{"en":"A second-hand jacket may look unique because it is not from the latest chain-store collection.","zh":"二手外套可能看起來獨特，因為它不是最新連鎖店系列。"},{"en":"Buying second-hand jackets can reduce clothing waste.","zh":"購買二手外套可以減少衣物浪費。"},{"en":"This phrase is useful when discussing thrift fashion.","zh":"這個短語適合用於二手時裝討論。"}],"source":"2016 Q7.pdf","sourcePage":8},{"front":"redesigned tote bags","meaning":"改造帆布袋","examples":[{"en":"Some young people prefer redesigned tote bags.","zh":"有些年輕人較喜歡改造帆布袋。"},{"en":"Redesigned tote bags are cloth bags changed with new patterns, patches or materials.","zh":"Redesigned tote bags 指用新圖案、布章或材料改動過的布袋。"},{"en":"A plain tote bag can become a redesigned tote bag with fabric paint.","zh":"普通帆布袋可以透過布料繪畫變成改造帆布袋。"},{"en":"Redesigned tote bags show creativity while reusing existing items.","zh":"改造帆布袋一邊重用現有物品，一邊顯示創意。"},{"en":"This phrase connects practical bags with personal style.","zh":"這個短語把實用袋子和個人風格連接起來。"}],"source":"2016 Q7.pdf","sourcePage":8},{"front":"handmade accessories","meaning":"手工飾物","examples":[{"en":"Young people may choose handmade accessories.","zh":"年輕人可能選擇手工飾物。"},{"en":"Handmade accessories are small fashion items made by hand, such as bracelets, pins or charms.","zh":"Handmade accessories 指用手製作的小型時尚物品，例如手鏈、襟章或吊飾。"},{"en":"Handmade accessories often feel personal because they are not mass-produced.","zh":"手工飾物常感覺更個人化，因為它們不是大量生產。"},{"en":"Students can sell handmade accessories at a festival booth.","zh":"學生可以在節日攤位售賣手工飾物。"},{"en":"This phrase connects craft with fashion identity.","zh":"這個短語把手作和時尚身份連接起來。"}],"source":"2016 Q7.pdf","sourcePage":8},{"front":"reflect their personality","meaning":"反映個性","examples":[{"en":"Young people like clothes that reflect their personality.","zh":"年輕人喜歡能反映個性的衣服。"},{"en":"Reflect their personality means show their character, taste or values.","zh":"Reflect their personality 指顯示他們的性格、品味或價值觀。"},{"en":"A colourful jacket may reflect a student’s cheerful personality.","zh":"色彩鮮明的外套可能反映學生開朗的個性。"},{"en":"Clothes can reflect personality when people customise them instead of copying trends.","zh":"當人們改造衣服而不是照抄潮流，衣服就能反映個性。"},{"en":"This phrase connects fashion with identity.","zh":"這個短語把時裝和身份連接起來。"}],"source":"2016 Q7.pdf","sourcePage":8},{"front":"see youth fashion as superficial","meaning":"視青年時裝為膚淺","examples":[{"en":"Some adults may see youth fashion as superficial.","zh":"有些成年人可能視青年時裝為膚淺。"},{"en":"See youth fashion as superficial means think young people’s clothing choices are shallow or only about appearance.","zh":"See youth fashion as superficial 指認為年輕人的服裝選擇很表面，只關乎外貌。"},{"en":"Adults may see youth fashion as superficial if they ignore its social and environmental messages.","zh":"如果成年人忽略其中的社會和環保訊息，他們可能視青年時裝為膚淺。"},{"en":"The proposal argues that streetwear can show values, not only looks.","zh":"建議書主張街頭服飾可以顯示價值觀，而不只是外表。"},{"en":"This phrase introduces a view that the writer wants to challenge.","zh":"這個短語引出作者想挑戰的看法。"}],"source":"2016 Q7.pdf","sourcePage":8},{"front":"concern for","meaning":"對……的關注","examples":[{"en":"This trend reveals young people’s concern for individuality and the environment.","zh":"這股潮流顯示年輕人對個人特色和環境的關注。"},{"en":"Concern for something means care or worry about it.","zh":"Concern for something 指對某事的關心或憂慮。"},{"en":"Students show concern for the environment when they reduce waste.","zh":"學生減少浪費時，就是表現對環境的關注。"},{"en":"Sustainable fashion reveals concern for both personal identity and public problems.","zh":"可持續時裝顯示對個人身份和公共問題的關注。"},{"en":"This phrase connects values with action.","zh":"這個短語把價值觀和行動連接起來。"}],"source":"2016 Q7.pdf","sourcePage":8},{"front":"individuality","meaning":"個人特色","examples":[{"en":"Sustainable streetwear shows young people’s individuality.","zh":"可持續街頭服飾顯示年輕人的個人特色。"},{"en":"Individuality means the qualities that make a person different from others.","zh":"Individuality 指令人與別人不同的特質。"},{"en":"A customised jacket can show a student’s individuality.","zh":"改造外套可以顯示學生的個人特色。"},{"en":"Young people value individuality because they do not want to look exactly the same.","zh":"年輕人重視個人特色，因為他們不想看起來完全一樣。"},{"en":"This word is useful when discussing identity and self-expression.","zh":"討論身份和自我表達時，這個詞很有用。"}],"source":"2016 Q7.pdf","sourcePage":8},{"front":"the environment","meaning":"環境","examples":[{"en":"Young people are concerned about the environment.","zh":"年輕人關心環境。"},{"en":"The environment means the natural world, including air, water, land, plants and animals.","zh":"The environment 指自然世界，包括空氣、水、土地、植物和動物。"},{"en":"Reducing clothing waste is one way to protect the environment.","zh":"減少衣物浪費是保護環境的一種方法。"},{"en":"A youth festival can teach environmental care through creative activities.","zh":"青年節可以透過創意活動教授環境保護。"},{"en":"This phrase is important in discussions of sustainability.","zh":"這個短語在可持續發展討論中很重要。"}],"source":"2016 Q7.pdf","sourcePage":9},{"front":"fast fashion","meaning":"快時尚","examples":[{"en":"Fast fashion produces waste.","zh":"快時尚製造浪費。"},{"en":"Fast fashion means cheap clothing made quickly to follow changing trends.","zh":"Fast fashion 指為追隨快速變化的潮流而迅速製造的廉價衣物。"},{"en":"Fast fashion encourages people to buy more clothes than they need.","zh":"快時尚鼓勵人購買多於需要的衣服。"},{"en":"It can harm the environment when unwanted clothes are thrown away quickly.","zh":"當不要的衣服很快被丟掉，它可能傷害環境。"},{"en":"This phrase is central to discussions of sustainable clothing.","zh":"這個短語是可持續服裝討論的核心。"}],"source":"2016 Q7.pdf","sourcePage":9},{"front":"produces waste","meaning":"製造浪費","examples":[{"en":"Fast fashion produces waste.","zh":"快時尚製造浪費。"},{"en":"Produces waste means creates unwanted material that may be thrown away.","zh":"Produces waste 指製造可能被丟棄的不需要材料。"},{"en":"A school event produces waste if it uses too many single-use cups.","zh":"如果學校活動使用太多即棄杯，就會製造浪費。"},{"en":"Clothing waste increases when people buy cheap items and discard them quickly.","zh":"當人們購買廉價衣物並很快丟掉，衣物浪費就會增加。"},{"en":"This phrase connects habits with environmental results.","zh":"這個短語把習慣和環境結果連接起來。"}],"source":"2016 Q7.pdf","sourcePage":9},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"By contrast, thrifting and upcycling reduce unnecessary consumption.","zh":"相比之下，二手購物和升級再造減少不必要消費。"},{"en":"By contrast means used to show a clear difference from the previous point.","zh":"By contrast 指用來顯示與前一點的清楚差異。"},{"en":"Fast fashion creates waste; by contrast, upcycling gives old clothes new life.","zh":"快時尚製造浪費；相比之下，升級再造給舊衣新生命。"},{"en":"Writers use this phrase to compare two different ideas.","zh":"作者用這個短語比較兩個不同想法。"},{"en":"This phrase helps make arguments clearer.","zh":"這個短語幫助令論點更清楚。"}],"source":"2016 Q7.pdf","sourcePage":9},{"front":"look stylish","meaning":"看起來有時尚感","examples":[{"en":"Thrifting allows students to look stylish.","zh":"二手購物讓學生看起來有時尚感。"},{"en":"Look stylish means appear fashionable, attractive or well-dressed.","zh":"Look stylish 指看起來時髦、吸引或穿搭得好。"},{"en":"Students can look stylish by mixing second-hand jackets with handmade accessories.","zh":"學生可以把二手外套和手工飾物配搭起來，看起來有時尚感。"},{"en":"Looking stylish does not always require buying expensive new items.","zh":"看起來有時尚感不一定需要購買昂貴新貨品。"},{"en":"This phrase connects appearance with fashion sense.","zh":"這個短語把外貌和時尚感連接起來。"}],"source":"2016 Q7.pdf","sourcePage":9},{"front":"unnecessary consumption","meaning":"不必要消費","examples":[{"en":"Upcycling avoids encouraging unnecessary consumption.","zh":"升級再造避免鼓勵不必要消費。"},{"en":"Unnecessary consumption means buying or using more than people truly need.","zh":"Unnecessary consumption 指購買或使用多於真正需要的東西。"},{"en":"Buying a new shirt for every trend can become unnecessary consumption.","zh":"為每個潮流都買一件新衣，可能變成不必要消費。"},{"en":"Upcycling reduces unnecessary consumption by making old items useful again.","zh":"升級再造透過令舊物再次有用，減少不必要消費。"},{"en":"This phrase is useful in environmental arguments.","zh":"這個短語適合用於環保論證。"}],"source":"2016 Q7.pdf","sourcePage":9},{"front":"be presented through","meaning":"透過……呈現","examples":[{"en":"This trend could be presented through a Streetwear Swap and Upcycling Market.","zh":"這股潮流可以透過街頭服飾交換及升級再造市集呈現。"},{"en":"Be presented through means be shown by using a particular activity or method.","zh":"Be presented through 指透過某種活動或方法展示。"},{"en":"Sustainability can be presented through workshops rather than only posters.","zh":"可持續發展可以透過工作坊呈現，而不只是海報。"},{"en":"A trend is clearer when it is presented through hands-on experiences.","zh":"當潮流透過實踐體驗呈現，它會更清楚。"},{"en":"This phrase explains the method of presentation.","zh":"這個短語解釋呈現方法。"}],"source":"2016 Q7.pdf","sourcePage":9},{"front":"Streetwear Swap and Upcycling Market","meaning":"街頭服飾交換及升級再造市集","examples":[{"en":"The Festival could include a Streetwear Swap and Upcycling Market.","zh":"青年節可以包括街頭服飾交換及升級再造市集。"},{"en":"A Streetwear Swap and Upcycling Market is an event where people exchange and redesign clothing.","zh":"Streetwear Swap and Upcycling Market 指讓人交換和改造衣物的活動。"},{"en":"Visitors could bring old clothes, receive tokens and join repair workshops.","zh":"訪客可以帶舊衣、取得代幣，並參加修補工作坊。"},{"en":"This market makes sustainability practical and social.","zh":"這個市集令可持續發展變得實用和具社交性。"},{"en":"The phrase names a proposed festival activity.","zh":"這個短語指出建議中的節日活動名稱。"}],"source":"2016 Q7.pdf","sourcePage":9},{"front":"be invited to","meaning":"被邀請去","examples":[{"en":"Visitors would be invited to bring clean clothes.","zh":"訪客會被邀請帶來乾淨衣物。"},{"en":"Be invited to means be asked or encouraged to do something.","zh":"Be invited to 指被要求或鼓勵去做某事。"},{"en":"Students may be invited to join a workshop before the fashion show.","zh":"學生可能被邀請在時裝表演前參加工作坊。"},{"en":"Inviting visitors to bring clothes makes them part of the activity.","zh":"邀請訪客帶衣物，令他們成為活動一部分。"},{"en":"This phrase sounds polite and suitable for event instructions.","zh":"這個短語語氣有禮，適合活動指引。"}],"source":"2016 Q7.pdf","sourcePage":9},{"front":"clean clothes","meaning":"乾淨衣物","examples":[{"en":"Visitors should bring clean clothes to the swap market.","zh":"訪客應帶乾淨衣物到交換市集。"},{"en":"Clean clothes are washed clothes that are suitable for others to handle or wear.","zh":"Clean clothes 指已清洗、適合別人處理或穿着的衣物。"},{"en":"A swap market needs clean clothes so the event feels hygienic and respectful.","zh":"交換市集需要乾淨衣物，令活動衛生並尊重他人。"},{"en":"Dirty clothing donations may create extra work for volunteers.","zh":"骯髒的衣物捐贈可能增加義工工作量。"},{"en":"This phrase shows a practical rule for clothing exchange.","zh":"這個短語顯示衣物交換的實際規則。"}],"source":"2016 Q7.pdf","sourcePage":9},{"front":"accessories they no longer use","meaning":"不再使用的飾物","examples":[{"en":"Visitors can bring accessories they no longer use.","zh":"訪客可以帶來他們不再使用的飾物。"},{"en":"Accessories they no longer use are small fashion items they do not wear or need anymore.","zh":"Accessories they no longer use 指他們不再佩戴或需要的小型時尚物品。"},{"en":"Old belts, pins and necklaces can be accessories people no longer use.","zh":"舊皮帶、襟章和頸鏈都可以是不再使用的飾物。"},{"en":"Bringing unused accessories gives them a chance to be valued by someone else.","zh":"帶來不用的飾物，給它們機會被別人重視。"},{"en":"This phrase supports reuse instead of throwing things away.","zh":"這個短語支持重用，而不是丟棄。"}],"source":"2016 Q7.pdf","sourcePage":10},{"front":"exchange them for tokens","meaning":"把它們換成代幣","examples":[{"en":"Visitors can exchange old items for tokens.","zh":"訪客可以把舊物換成代幣。"},{"en":"Exchange them for tokens means give items and receive small festival credits in return.","zh":"Exchange them for tokens 指交出物品並換取小型活動積分。"},{"en":"Visitors may exchange two clean shirts for tokens at the entrance.","zh":"訪客可以在入口把兩件乾淨恤衫換成代幣。"},{"en":"Tokens make the swap system fairer and easier to manage.","zh":"代幣令交換制度更公平，也更容易管理。"},{"en":"This phrase explains the basic process of the market.","zh":"這個短語解釋市集的基本流程。"}],"source":"2016 Q7.pdf","sourcePage":10},{"front":"tokens","meaning":"代幣","examples":[{"en":"Tokens can be used to buy other second-hand items.","zh":"代幣可以用來換取其他二手物品。"},{"en":"Tokens are small credits, tickets or objects used instead of money in an event.","zh":"Tokens 指在活動中代替金錢使用的小積分、票券或物件。"},{"en":"A visitor may receive tokens after donating clean clothes.","zh":"訪客捐出乾淨衣物後可能收到代幣。"},{"en":"Tokens help organisers control exchanges without using cash.","zh":"代幣幫助主辦方在不使用現金下管理交換。"},{"en":"This word is useful for festival and market systems.","zh":"這個詞適合用於節日和市集制度。"}],"source":"2016 Q7.pdf","sourcePage":10},{"front":"second-hand items","meaning":"二手物品","examples":[{"en":"Visitors can use tokens to buy second-hand items.","zh":"訪客可以用代幣換取二手物品。"},{"en":"Second-hand items are things that were owned or used by someone before.","zh":"Second-hand items 指曾由別人擁有或使用過的東西。"},{"en":"Bags, jackets and accessories can all be second-hand items.","zh":"袋、外套和飾物都可以是二手物品。"},{"en":"Buying second-hand items saves money and reduces waste.","zh":"購買二手物品可以省錢並減少浪費。"},{"en":"This phrase is central to thrift shopping.","zh":"這個短語是二手購物的核心。"}],"source":"2016 Q7.pdf","sourcePage":10},{"front":"swap area","meaning":"交換區","examples":[{"en":"Mini-workshops could be held beside the swap area.","zh":"小型工作坊可以在交換區旁邊舉行。"},{"en":"A swap area is a place where people exchange items with one another.","zh":"Swap area 指人們互相交換物品的地方。"},{"en":"The swap area should be clearly labelled so visitors know where to bring clothes.","zh":"交換區應有清楚標示，讓訪客知道在哪裏帶衣物。"},{"en":"Holding workshops near the swap area can encourage people to redesign items immediately.","zh":"在交換區附近舉辦工作坊，可以鼓勵人們即場改造物品。"},{"en":"This phrase describes a functional space at the market.","zh":"這個短語描述市集中的功能空間。"}],"source":"2016 Q7.pdf","sourcePage":10},{"front":"local young designers","meaning":"本地年輕設計師","examples":[{"en":"Local young designers could run mini-workshops.","zh":"本地年輕設計師可以舉辦小型工作坊。"},{"en":"Local young designers are young people from the community who create clothing, accessories or visual designs.","zh":"Local young designers 指來自本地社區、創作服裝、飾物或視覺設計的年輕人。"},{"en":"Local young designers can teach visitors how to customise old jackets.","zh":"本地年輕設計師可以教訪客如何改造舊外套。"},{"en":"Inviting local young designers supports youth talent and community creativity.","zh":"邀請本地年輕設計師能支持青年才華和社區創意。"},{"en":"This phrase identifies suitable workshop leaders.","zh":"這個短語指出合適的工作坊帶領者。"}],"source":"2016 Q7.pdf","sourcePage":10},{"front":"art students","meaning":"藝術學生","examples":[{"en":"Art students could help run the workshops.","zh":"藝術學生可以協助舉辦工作坊。"},{"en":"Art students are students who study visual art, design or creative subjects.","zh":"Art students 指修讀視覺藝術、設計或創意科目的學生。"},{"en":"Art students can help visitors paint fabric or make patches.","zh":"藝術學生可以幫助訪客進行布料繪畫或製作布章。"},{"en":"They gain real experience while helping the festival become more creative.","zh":"他們一邊獲得真實經驗，一邊令青年節更有創意。"},{"en":"This phrase suggests a useful youth volunteer group.","zh":"這個短語提出一個有用的青年義工群體。"}],"source":"2016 Q7.pdf","sourcePage":10},{"front":"run mini-workshops","meaning":"舉辦小型工作坊","examples":[{"en":"Designers and students could run mini-workshops.","zh":"設計師和學生可以舉辦小型工作坊。"},{"en":"Run mini-workshops means organise and lead short practical learning sessions.","zh":"Run mini-workshops 指組織和帶領簡短的實踐學習環節。"},{"en":"Volunteers can run mini-workshops on embroidery or fabric painting.","zh":"義工可以舉辦關於刺繡或布料繪畫的小型工作坊。"},{"en":"Mini-workshops work well when they teach one clear skill at a time.","zh":"小型工作坊每次教授一項清楚技能時效果最好。"},{"en":"This phrase describes hands-on event management.","zh":"這個短語描述實踐活動的營運。"}],"source":"2016 Q7.pdf","sourcePage":10},{"front":"embroidery","meaning":"刺繡","examples":[{"en":"Participants could learn embroidery.","zh":"參加者可以學習刺繡。"},{"en":"Embroidery is the craft of decorating fabric with stitched thread designs.","zh":"Embroidery 指用線縫出圖案來裝飾布料的手藝。"},{"en":"Students can use embroidery to add names or patterns to old clothes.","zh":"學生可以用刺繡在舊衣服上加入名字或圖案。"},{"en":"Embroidery makes upcycled clothing more personal and valuable.","zh":"刺繡令升級再造衣物更個人化和有價值。"},{"en":"This word is useful in fashion, craft and design contexts.","zh":"這個詞適合用於時裝、手作和設計語境。"}],"source":"2016 Q7.pdf","sourcePage":10},{"front":"fabric painting","meaning":"布料繪畫","examples":[{"en":"The workshops could teach fabric painting.","zh":"工作坊可以教授布料繪畫。"},{"en":"Fabric painting means painting designs directly onto cloth or clothing.","zh":"Fabric painting 指直接在布料或衣物上繪畫圖案。"},{"en":"A plain tote bag can become unique through fabric painting.","zh":"普通帆布袋可以透過布料繪畫變得獨特。"},{"en":"Fabric painting allows beginners to customise clothes without advanced sewing skills.","zh":"布料繪畫讓初學者不用高階縫紉技巧也能改造衣物。"},{"en":"This phrase describes an accessible fashion activity.","zh":"這個短語描述容易參與的時裝活動。"}],"source":"2016 Q7.pdf","sourcePage":10},{"front":"patch-making","meaning":"布章製作","examples":[{"en":"Participants could learn patch-making.","zh":"參加者可以學習布章製作。"},{"en":"Patch-making means creating small pieces of decorated fabric that can be attached to clothing.","zh":"Patch-making 指製作可縫或貼在衣服上的小型裝飾布片。"},{"en":"Students can use patch-making to cover holes or add style to jackets.","zh":"學生可以用布章製作遮蓋破洞，或為外套增加風格。"},{"en":"Patch-making supports upcycling because it repairs and decorates at the same time.","zh":"布章製作支持升級再造，因為它同時修補和裝飾。"},{"en":"This phrase connects craft with practical clothing repair.","zh":"這個短語把手作和實用衣物修補連接起來。"}],"source":"2016 Q7.pdf","sourcePage":11},{"front":"Re-made Runway","meaning":"再造時裝天橋","examples":[{"en":"A Re-made Runway could be held twice a day.","zh":"再造時裝天橋可以每日舉行兩次。"},{"en":"A Re-made Runway is a fashion show for outfits redesigned from old or reused materials.","zh":"Re-made Runway 指展示由舊物或重用材料重新設計服裝的時裝表演。"},{"en":"Participants can walk on the Re-made Runway to show their upcycled clothes.","zh":"參加者可以走上再造時裝天橋，展示自己的升級再造服裝。"},{"en":"This activity turns sustainability into a public celebration.","zh":"這個活動把可持續發展變成公開慶祝。"},{"en":"The phrase names a proposed fashion event.","zh":"這個短語指出建議中的時裝活動名稱。"}],"source":"2016 Q7.pdf","sourcePage":11},{"front":"held twice a day","meaning":"每日舉行兩次","examples":[{"en":"The Re-made Runway could be held twice a day.","zh":"再造時裝天橋可以每日舉行兩次。"},{"en":"Held twice a day means organised two times in one day.","zh":"Held twice a day 指一天之內舉辦兩次。"},{"en":"A popular workshop may be held twice a day so more visitors can join.","zh":"受歡迎的工作坊可以每日舉行兩次，讓更多訪客參與。"},{"en":"Holding the runway twice a day gives participants more chances to take part.","zh":"每日舉行兩次天橋活動，給參加者更多參與機會。"},{"en":"This phrase describes frequency in an event schedule.","zh":"這個短語描述活動時間表中的頻率。"}],"source":"2016 Q7.pdf","sourcePage":11},{"front":"model outfits","meaning":"展示服裝","examples":[{"en":"Participants could model outfits they have redesigned.","zh":"參加者可以展示他們重新設計的服裝。"},{"en":"Model outfits means wear and present clothes for others to see.","zh":"Model outfits 指穿着並向他人展示服裝。"},{"en":"Students can model outfits on a small runway during the festival.","zh":"學生可以在節日的小天橋上展示服裝。"},{"en":"Modelling redesigned outfits gives young people pride in their work.","zh":"展示重新設計的服裝能令年輕人為自己的作品感到自豪。"},{"en":"This phrase describes fashion presentation.","zh":"這個短語描述時裝呈現。"}],"source":"2016 Q7.pdf","sourcePage":11},{"front":"redesigned","meaning":"重新設計的","examples":[{"en":"Participants can model outfits they have redesigned.","zh":"參加者可以展示他們重新設計的服裝。"},{"en":"Redesigned means changed and improved with a new design.","zh":"Redesigned 指經過新設計改動和改善的。"},{"en":"A redesigned jacket may include painted sleeves or handmade patches.","zh":"重新設計的外套可能有繪畫袖子或手工布章。"},{"en":"Old clothes feel new when they are redesigned creatively.","zh":"舊衣物經創意重新設計後，可以感覺像新的。"},{"en":"This word is useful in design and upcycling contexts.","zh":"這個詞適合用於設計和升級再造語境。"}],"source":"2016 Q7.pdf","sourcePage":11},{"front":"create a festival atmosphere","meaning":"營造節日氣氛","examples":[{"en":"The activity would create a festival atmosphere.","zh":"這項活動會營造節日氣氛。"},{"en":"Create a festival atmosphere means make a place feel lively, joyful and event-like.","zh":"Create a festival atmosphere 指令一個地方感覺熱鬧、愉快並充滿活動感。"},{"en":"Music, colourful booths and performances can create a festival atmosphere.","zh":"音樂、繽紛攤位和表演可以營造節日氣氛。"},{"en":"A runway show creates excitement and gives visitors something to gather around.","zh":"天橋表演製造興奮感，也給訪客一個聚集焦點。"},{"en":"This phrase explains the mood an activity brings.","zh":"這個短語解釋活動帶來的氣氛。"}],"source":"2016 Q7.pdf","sourcePage":11},{"front":"sustainability","meaning":"可持續發展","examples":[{"en":"The market would show that sustainability can be enjoyable.","zh":"市集會顯示可持續發展也可以很有趣。"},{"en":"Sustainability means using resources in a way that protects the future and reduces harm.","zh":"Sustainability 指以保護未來和減少傷害的方式使用資源。"},{"en":"Reusing clothes is one way to practise sustainability.","zh":"重用衣物是實踐可持續發展的一種方法。"},{"en":"Sustainability becomes easier to accept when people see that it can be creative and fun.","zh":"當人們看見可持續發展可以有創意又有趣，它就更容易被接受。"},{"en":"This word is central to environmental planning.","zh":"這個詞是環境規劃的核心。"}],"source":"2016 Q7.pdf","sourcePage":11},{"front":"practical, creative and enjoyable","meaning":"實用、有創意而有趣","examples":[{"en":"Sustainability can be practical, creative and enjoyable.","zh":"可持續發展可以實用、有創意而有趣。"},{"en":"Practical, creative and enjoyable means useful, imaginative and fun at the same time.","zh":"Practical, creative and enjoyable 指同時有用、有想像力和有樂趣。"},{"en":"Upcycling is practical, creative and enjoyable when old clothes become new outfits.","zh":"當舊衣變成新穿搭，升級再造就是實用、有創意而有趣的。"},{"en":"This description helps remove the idea that environmental action is boring.","zh":"這種描述有助消除環保行動很沉悶的想法。"},{"en":"The phrase gives three positive qualities in one clear list.","zh":"這個短語用清楚清單給出三個正面特質。"}],"source":"2016 Q7.pdf","sourcePage":11},{"front":"the more…, the more…","meaning":"越……就越……","examples":[{"en":"The more visitors participate, the more clearly they will understand the message.","zh":"訪客參與得越多，就越清楚理解這個訊息。"},{"en":"The more…, the more… shows that one thing increases as another thing increases.","zh":"The more…, the more… 表示一件事增加時，另一件事也增加。"},{"en":"The more students create videos, the more confident they become.","zh":"學生創作影片越多，就越有信心。"},{"en":"The more visitors join the swap market, the more they understand reuse.","zh":"訪客越多參與交換市集，就越理解重用。"},{"en":"This structure clearly connects action with result.","zh":"這個結構清楚連接行動和結果。"}],"source":"2016 Q7.pdf","sourcePage":11},{"front":"participate","meaning":"參與","examples":[{"en":"The more visitors participate, the more they will understand sustainability.","zh":"訪客參與得越多，就越理解可持續發展。"},{"en":"Participate means take part in an activity instead of only watching.","zh":"Participate 指參加活動，而不只是觀看。"},{"en":"Visitors participate when they film videos, exchange clothes or join workshops.","zh":"當訪客拍片、交換衣物或參加工作坊時，就是參與。"},{"en":"Participation helps people remember ideas because they experience them directly.","zh":"參與能幫助人記住想法，因為他們親身體驗。"},{"en":"This word is important in interactive event design.","zh":"這個詞在互動活動設計中很重要。"}],"source":"2016 Q7.pdf","sourcePage":11},{"front":"protecting the environment","meaning":"保護環境","examples":[{"en":"Protecting the environment does not have to be dull.","zh":"保護環境不一定要沉悶。"},{"en":"Protecting the environment means taking action to reduce harm to nature.","zh":"Protecting the environment 指採取行動減少對自然的傷害。"},{"en":"Reusing clothes and reducing waste are ways of protecting the environment.","zh":"重用衣物和減少浪費都是保護環境的方法。"},{"en":"A festival can make protecting the environment feel creative and social.","zh":"青年節可以令保護環境感覺有創意並具社交性。"},{"en":"This phrase connects personal habits with public responsibility.","zh":"這個短語把個人習慣和公共責任連接起來。"}],"source":"2016 Q7.pdf","sourcePage":12},{"front":"does not have to be","meaning":"不一定要","examples":[{"en":"Protecting the environment does not have to be dull or expensive.","zh":"保護環境不一定要沉悶或昂貴。"},{"en":"Does not have to be means something is not necessarily a certain way.","zh":"Does not have to be 指某事不一定是某種樣子。"},{"en":"Learning English does not have to be boring if examples come from daily life.","zh":"如果例子來自日常生活，學英文不一定要沉悶。"},{"en":"Sustainable fashion does not have to be costly when people reuse clothes.","zh":"當人們重用衣物，可持續時裝不一定要昂貴。"},{"en":"This phrase helps challenge a common assumption.","zh":"這個短語幫助挑戰常見假設。"}],"source":"2016 Q7.pdf","sourcePage":12},{"front":"dull or expensive","meaning":"沉悶或昂貴","examples":[{"en":"Sustainability does not have to be dull or expensive.","zh":"可持續發展不一定要沉悶或昂貴。"},{"en":"Dull or expensive means boring or costing a lot of money.","zh":"Dull or expensive 指沉悶或花費很多金錢。"},{"en":"A clothes-swap event proves that eco-friendly fashion need not be dull or expensive.","zh":"衣物交換活動證明環保時裝不一定沉悶或昂貴。"},{"en":"Activities become more attractive when they are creative, low-cost and fun.","zh":"當活動有創意、低成本又有趣，就會更吸引。"},{"en":"This phrase names two worries people may have about sustainability.","zh":"這個短語指出人們對可持續發展可能有的兩個憂慮。"}],"source":"2016 Q7.pdf","sourcePage":12},{"front":"justification","meaning":"理據","examples":[{"en":"The proposal includes justification and expected benefits.","zh":"建議書包括理據和預期效益。"},{"en":"Justification means reasons that explain why a plan is suitable or necessary.","zh":"Justification 指解釋計劃為何合適或必要的理由。"},{"en":"A proposal needs justification so the committee understands why it should accept the idea.","zh":"建議書需要理據，讓委員會明白為何應接受這個想法。"},{"en":"Strong justification connects activities with clear benefits.","zh":"有力理據會把活動和清楚好處連接起來。"},{"en":"This word is important in formal proposal writing.","zh":"這個詞在正式建議書寫作中很重要。"}],"source":"2016 Q7.pdf","sourcePage":12},{"front":"expected benefits","meaning":"預期效益","examples":[{"en":"The proposal explains the expected benefits of the plan.","zh":"建議書解釋計劃的預期效益。"},{"en":"Expected benefits are the good results that a plan is likely to bring.","zh":"Expected benefits 指計劃可能帶來的好結果。"},{"en":"The expected benefits may include youth participation, creativity and environmental awareness.","zh":"預期效益可能包括青年參與、創意和環保意識。"},{"en":"Listing expected benefits helps readers judge whether the plan is worthwhile.","zh":"列出預期效益幫助讀者判斷計劃是否值得推行。"},{"en":"This phrase is useful when explaining why a proposal should be adopted.","zh":"這個短語適合用來解釋為何應採納建議。"}],"source":"2016 Q7.pdf","sourcePage":12},{"front":"presentation method","meaning":"呈現方法","examples":[{"en":"The proposed presentation method is suitable.","zh":"建議的呈現方法是合適的。"},{"en":"Presentation method means the way an idea, trend or activity is shown to people.","zh":"Presentation method 指向人們展示想法、潮流或活動的方式。"},{"en":"A lecture is one presentation method, but a workshop may be more interactive.","zh":"講座是一種呈現方法，但工作坊可能更具互動性。"},{"en":"The right presentation method helps visitors understand the message clearly.","zh":"合適的呈現方法幫助訪客清楚理解訊息。"},{"en":"This phrase is useful in event planning.","zh":"這個短語適合用於活動策劃。"}],"source":"2016 Q7.pdf","sourcePage":12},{"front":"suitable for three reasons","meaning":"基於三個原因而合適","examples":[{"en":"The method is suitable for three reasons.","zh":"這個方法基於三個原因而合適。"},{"en":"Suitable for three reasons means appropriate because there are three clear supporting points.","zh":"Suitable for three reasons 指因為有三個清楚支持點而合適。"},{"en":"A school trip may be suitable for three reasons: cost, safety and learning value.","zh":"學校旅行可能基於三個原因而合適：成本、安全和學習價值。"},{"en":"This phrase prepares readers for an organised explanation.","zh":"這個短語讓讀者準備閱讀有組織的解釋。"},{"en":"It is useful in formal writing because it signals structure.","zh":"它適合正式寫作，因為能標示結構。"}],"source":"2016 Q7.pdf","sourcePage":12},{"front":"interactive","meaning":"互動的","examples":[{"en":"The proposal is suitable because it is interactive.","zh":"這項建議合適，因為它是互動的。"},{"en":"Interactive means allowing people to take part, respond or create something.","zh":"Interactive 指容許人們參與、回應或創作。"},{"en":"An interactive booth lets visitors touch materials, answer questions or make products.","zh":"互動攤位讓訪客觸摸材料、回答問題或製作作品。"},{"en":"Interactive activities often hold young people’s attention better than speeches.","zh":"互動活動通常比演講更能吸引年輕人注意。"},{"en":"This word is important when describing youth-friendly events.","zh":"描述適合青年的活動時，這個詞很重要。"}],"source":"2016 Q7.pdf","sourcePage":12},{"front":"a successful youth festival","meaning":"成功的青年節","examples":[{"en":"A successful youth festival should give young people ownership.","zh":"成功的青年節應給年輕人主人翁意識。"},{"en":"A successful youth festival is an event that attracts young people and reflects their real interests.","zh":"A successful youth festival 指能吸引年輕人並反映他們真實興趣的活動。"},{"en":"It should allow young people to create, decide and participate.","zh":"它應讓年輕人創作、決定和參與。"},{"en":"A youth festival fails if young people feel it is only designed by adults for adults.","zh":"如果年輕人覺得活動只是成年人為成年人設計，青年節就失敗了。"},{"en":"This phrase sets the standard for the proposal.","zh":"這個短語為建議書定下標準。"}],"source":"2016 Q7.pdf","sourcePage":12},{"front":"make young people feel as if","meaning":"令年輕人覺得好像","examples":[{"en":"A festival should not make young people feel as if adults are lecturing them.","zh":"青年節不應令年輕人覺得好像成年人在教訓他們。"},{"en":"Make young people feel as if means create the impression that something is happening to them.","zh":"Make young people feel as if 指製造某種感覺，令年輕人覺得某事正在發生。"},{"en":"Too many speeches may make young people feel as if they are back in a classroom.","zh":"太多演講可能令年輕人覺得好像回到課室。"},{"en":"A youth festival should make young people feel as if their ideas matter.","zh":"青年節應令年輕人覺得好像自己的想法很重要。"},{"en":"This phrase focuses on how an event feels to its audience.","zh":"這個短語集中於活動帶給觀眾的感受。"}],"source":"2016 Q7.pdf","sourcePage":12},{"front":"explaining youth culture back to them","meaning":"向年輕人反過來解釋青年文化","examples":[{"en":"Adults should not simply explain youth culture back to young people.","zh":"成年人不應只是向年輕人反過來解釋青年文化。"},{"en":"Explaining youth culture back to them means telling young people about their own culture as if they do not understand it.","zh":"Explaining youth culture back to them 指像年輕人不懂自己的文化一樣，向他們講解青年文化。"},{"en":"A festival feels awkward if adults explain youth culture back to the youth without listening.","zh":"如果成年人不聆聽就向青年反過來解釋青年文化，活動會顯得尷尬。"},{"en":"Young people should help present their culture in their own voice.","zh":"年輕人應用自己的聲音呈現自己的文化。"},{"en":"This phrase criticises a top-down approach.","zh":"這個短語批評由上而下的做法。"}],"source":"2016 Q7.pdf","sourcePage":13},{"front":"instead","meaning":"相反；而是","examples":[{"en":"Instead, the Festival should give young people room to create.","zh":"相反，青年節應給年輕人創作空間。"},{"en":"Instead means as an alternative to what was just mentioned.","zh":"Instead 指作為剛才所說事情的替代選擇。"},{"en":"Do not only display posters; instead, let visitors make something.","zh":"不要只展示海報；相反，讓訪客製作東西。"},{"en":"Writers use instead to replace a weaker idea with a better one.","zh":"作者用 instead 以更好想法取代較弱想法。"},{"en":"This word helps show contrast and correction.","zh":"這個詞幫助顯示對比和修正。"}],"source":"2016 Q7.pdf","sourcePage":13},{"front":"give them room to","meaning":"給他們空間去","examples":[{"en":"The Festival should give young people room to take ownership.","zh":"青年節應給年輕人空間去主導活動。"},{"en":"Give them room to means allow them space, freedom or opportunity to do something.","zh":"Give them room to 指給予他們空間、自由或機會去做某事。"},{"en":"Teachers give students room to think when they do not answer every question for them.","zh":"老師不替學生回答所有問題，就是給他們空間去思考。"},{"en":"A youth festival gives young people room to create when it offers tools and trust.","zh":"青年節提供工具和信任時，就是給年輕人空間去創作。"},{"en":"This phrase suggests support without control.","zh":"這個短語暗示支持而不是控制。"}],"source":"2016 Q7.pdf","sourcePage":13},{"front":"take ownership of","meaning":"主導；有主人翁意識","examples":[{"en":"Young people should take ownership of the event.","zh":"年輕人應主導這項活動，並有主人翁意識。"},{"en":"Take ownership of means feel responsible for something and have control over it.","zh":"Take ownership of 指對某事有責任感，並有一定控制權。"},{"en":"Students take ownership of a project when they plan it and make decisions.","zh":"當學生規劃專題並作決定，他們就是在主導專題。"},{"en":"Young people will care more about the festival if they take ownership of it.","zh":"如果年輕人對青年節有主人翁意識，他們會更關心活動。"},{"en":"This phrase shows responsibility, pride and leadership.","zh":"這個短語顯示責任、自豪和領導。"}],"source":"2016 Q7.pdf","sourcePage":13},{"front":"balance technology and real-life community","meaning":"平衡科技與現實社區","examples":[{"en":"The two trends balance technology and real-life community.","zh":"這兩股潮流平衡科技與現實社區。"},{"en":"Balance technology and real-life community means include both online creativity and face-to-face social connection.","zh":"Balance technology and real-life community 指同時包括網上創意和面對面的社區連結。"},{"en":"A festival balances technology and community when it offers video booths and clothing swaps.","zh":"當青年節提供拍片攤位和衣物交換，它就平衡了科技與社區。"},{"en":"This balance prevents youth culture from seeming only digital or only traditional.","zh":"這種平衡避免青年文化顯得只屬數碼或只屬傳統。"},{"en":"This phrase explains why the two trends work well together.","zh":"這個短語解釋兩股潮流為何能配合。"}],"source":"2016 Q7.pdf","sourcePage":13},{"front":"appeals to","meaning":"吸引","examples":[{"en":"Digital creation appeals to students who enjoy online expression.","zh":"數碼創作吸引喜歡網上表達的學生。"},{"en":"Appeals to means attracts or interests a particular group of people.","zh":"Appeals to 指吸引或令某一群人感興趣。"},{"en":"Hands-on workshops appeal to students who dislike long lectures.","zh":"實踐工作坊吸引不喜歡長篇講座的學生。"},{"en":"Digital creation appeals to young people because it lets them share ideas quickly.","zh":"數碼創作吸引年輕人，因為它讓他們快速分享想法。"},{"en":"This phrase is useful when describing target audiences.","zh":"描述目標觀眾時，這個短語很有用。"}],"source":"2016 Q7.pdf","sourcePage":13},{"front":"online expression","meaning":"網上表達","examples":[{"en":"Some students enjoy online expression.","zh":"有些學生喜歡網上表達。"},{"en":"Online expression means sharing thoughts, identity or creativity through the internet.","zh":"Online expression 指透過互聯網分享想法、身份或創意。"},{"en":"Students use posts, videos and comments for online expression.","zh":"學生用貼文、影片和留言進行網上表達。"},{"en":"Online expression can be powerful when it is respectful and responsible.","zh":"當網上表達尊重他人並負責任，它可以很有力量。"},{"en":"This phrase connects self-expression with digital platforms.","zh":"這個短語把自我表達和數碼平台連接起來。"}],"source":"2016 Q7.pdf","sourcePage":13},{"front":"whereas","meaning":"而","examples":[{"en":"Digital creation appeals to some students, whereas sustainable fashion attracts others.","zh":"數碼創作吸引一些學生，而可持續時裝吸引另一些學生。"},{"en":"Whereas means while, and it is used to compare two different facts or groups.","zh":"Whereas 指「而」，用來比較兩個不同事實或群體。"},{"en":"Some students prefer filming, whereas others enjoy designing clothes.","zh":"有些學生喜歡拍片，而另一些學生喜歡設計衣服。"},{"en":"This word helps show that different trends attract different people.","zh":"這個詞幫助顯示不同潮流吸引不同人。"},{"en":"It is useful in balanced proposal writing.","zh":"它適合用於平衡的建議書寫作。"}],"source":"2016 Q7.pdf","sourcePage":13},{"front":"attracts those interested in","meaning":"吸引對……有興趣的人","examples":[{"en":"Sustainable fashion attracts those interested in design.","zh":"可持續時裝吸引對設計有興趣的人。"},{"en":"Attracts those interested in means draws people who already care about a subject.","zh":"Attracts those interested in 指吸引本來已關心某個題目的人。"},{"en":"A video studio attracts those interested in filming and editing.","zh":"影片工作室吸引對拍攝和剪輯有興趣的人。"},{"en":"A streetwear market attracts those interested in clothing, style and sustainability.","zh":"街頭服飾市集吸引對衣服、風格和可持續發展有興趣的人。"},{"en":"This phrase helps explain audience appeal.","zh":"這個短語幫助解釋活動對觀眾的吸引力。"}],"source":"2016 Q7.pdf","sourcePage":13},{"front":"design, lifestyle and environmental responsibility","meaning":"設計、生活方式和環保責任","examples":[{"en":"Sustainable fashion connects design, lifestyle and environmental responsibility.","zh":"可持續時裝連接設計、生活方式和環保責任。"},{"en":"Design, lifestyle and environmental responsibility mean creativity, daily choices and care for nature.","zh":"Design, lifestyle and environmental responsibility 指創意、日常選擇和對自然的責任。"},{"en":"A redesigned jacket can show design, lifestyle and environmental responsibility at once.","zh":"一件改造外套可以同時顯示設計、生活方式和環保責任。"},{"en":"This connection makes streetwear more meaningful than simple shopping.","zh":"這種連結令街頭服飾比單純購物更有意義。"},{"en":"The phrase summarises three values behind sustainable fashion.","zh":"這個短語總結可持續時裝背後的三種價值。"}],"source":"2016 Q7.pdf","sourcePage":13},{"front":"together","meaning":"合起來","examples":[{"en":"Together, the two trends show different sides of youth culture.","zh":"合起來，這兩股潮流展示青年文化的不同面向。"},{"en":"Together means when considered or used as a pair or group.","zh":"Together 指把兩者或多者一起考慮或使用時。"},{"en":"Together, digital videos and streetwear show both online and street-level creativity.","zh":"合起來，數碼影片和街頭服飾展示網上和街頭層面的創意。"},{"en":"Two activities can become stronger together than separately.","zh":"兩項活動合起來可能比分開時更有力量。"},{"en":"This word helps combine several points into one message.","zh":"這個詞幫助把幾個重點合成一個訊息。"}],"source":"2016 Q7.pdf","sourcePage":14},{"front":"exists both on screens and on the streets","meaning":"同時存在於屏幕上和街頭","examples":[{"en":"Hong Kong youth culture exists both on screens and on the streets.","zh":"香港青年文化同時存在於屏幕上和街頭。"},{"en":"Exists both on screens and on the streets means appears in online spaces and real public places.","zh":"Exists both on screens and on the streets 指出現在網上空間和現實公共地方。"},{"en":"Youth culture exists on screens through videos and on the streets through fashion.","zh":"青年文化透過影片存在於屏幕上，也透過時裝存在於街頭。"},{"en":"This phrase shows that young people live between digital and physical worlds.","zh":"這個短語顯示年輕人生活在數碼和實體世界之間。"},{"en":"It helps explain why the festival needs both trends.","zh":"它幫助解釋為何青年節需要兩股潮流。"}],"source":"2016 Q7.pdf","sourcePage":14},{"front":"more importantly","meaning":"更重要的是","examples":[{"en":"More importantly, the plan is realistic.","zh":"更重要的是，這個計劃實際可行。"},{"en":"More importantly introduces a point that matters more than the previous one.","zh":"More importantly 用來引出比前面更重要的一點。"},{"en":"The activities are fun; more importantly, they can be organised with simple equipment.","zh":"這些活動很有趣；更重要的是，它們可以用簡單設備舉辦。"},{"en":"Writers use this phrase to guide readers toward the strongest reason.","zh":"作者用這個短語引導讀者看見最有力原因。"},{"en":"This phrase helps structure an argument.","zh":"這個短語幫助組織論點。"}],"source":"2016 Q7.pdf","sourcePage":14},{"front":"realistic","meaning":"實際可行的","examples":[{"en":"The plan is realistic.","zh":"這個計劃是實際可行的。"},{"en":"Realistic means practical and possible to carry out.","zh":"Realistic 指實用並能夠實行。"},{"en":"A realistic festival plan uses available equipment, volunteers and space.","zh":"實際可行的節日計劃會使用現有設備、義工和空間。"},{"en":"A proposal is more convincing when its ideas are creative but realistic.","zh":"當建議有創意但實際可行，它會更有說服力。"},{"en":"This word is important when judging whether a plan can work.","zh":"判斷計劃能否實行時，這個詞很重要。"}],"source":"2016 Q7.pdf","sourcePage":14},{"front":"requires only","meaning":"只需要","examples":[{"en":"The Creator Studio requires only basic equipment.","zh":"創作者工作室只需要基本設備。"},{"en":"Requires only means needs no more than a small or limited amount of something.","zh":"Requires only 指只需要少量或有限的東西。"},{"en":"A simple filming booth requires only a phone, light and backdrop.","zh":"簡單拍攝攤位只需要一部手機、一盞燈和背景板。"},{"en":"This phrase makes a plan sound easier and more affordable.","zh":"這個短語令計劃聽起來更容易和更便宜。"},{"en":"It is useful when explaining why an idea is practical.","zh":"解釋想法為何實際可行時，這個短語很有用。"}],"source":"2016 Q7.pdf","sourcePage":14},{"front":"basic lighting","meaning":"基本燈光","examples":[{"en":"The Creator Studio requires basic lighting.","zh":"創作者工作室需要基本燈光。"},{"en":"Basic lighting means simple lights used to make filming clearer.","zh":"Basic lighting 指令拍攝更清楚的簡單燈具。"},{"en":"Basic lighting can improve a video even if the camera is only a phone.","zh":"即使相機只是手機，基本燈光也可以改善影片。"},{"en":"Good lighting helps creators show faces, clothes and details more clearly.","zh":"良好燈光幫助創作者更清楚展示臉部、衣服和細節。"},{"en":"This phrase describes simple but useful filming equipment.","zh":"這個短語描述簡單但有用的拍攝設備。"}],"source":"2016 Q7.pdf","sourcePage":14},{"front":"microphones","meaning":"麥克風","examples":[{"en":"The Creator Studio needs phones, microphones and volunteer guidance.","zh":"創作者工作室需要手機、麥克風和義工指導。"},{"en":"Microphones are devices used to record or make voices louder.","zh":"Microphones 指用來錄音或放大聲音的設備。"},{"en":"A small microphone can make a student’s video sound much clearer.","zh":"小型麥克風可以令學生影片的聲音清楚得多。"},{"en":"Microphones are useful when a festival space is noisy.","zh":"當節日場地嘈雜時，麥克風很有用。"},{"en":"This word is common in filming, speaking and performance contexts.","zh":"這個詞常見於拍攝、演講和表演語境。"}],"source":"2016 Q7.pdf","sourcePage":14},{"front":"volunteer guidance","meaning":"義工指導","examples":[{"en":"The Creator Studio can operate with volunteer guidance.","zh":"創作者工作室可以在義工指導下運作。"},{"en":"Volunteer guidance means help or instructions given by unpaid helpers.","zh":"Volunteer guidance 指由無薪助手提供的幫助或指引。"},{"en":"Volunteer guidance can teach visitors how to film safely and edit simply.","zh":"義工指導可以教訪客如何安全拍攝和簡單剪輯。"},{"en":"With volunteer guidance, beginners feel less lost in a new activity.","zh":"有義工指導，初學者在新活動中會較不迷惘。"},{"en":"This phrase shows how an event can run without high cost.","zh":"這個短語顯示活動如何在低成本下運作。"}],"source":"2016 Q7.pdf","sourcePage":14},{"front":"be supported by","meaning":"由……支持","examples":[{"en":"The upcycling market can be supported by schools and youth centres.","zh":"升級再造市集可以由學校和青年中心支持。"},{"en":"Be supported by means receive help, resources or cooperation from someone or something.","zh":"Be supported by 指得到某人或某機構的幫助、資源或合作。"},{"en":"The festival can be supported by local shops through material donations.","zh":"青年節可以由本地商店透過物資捐贈支持。"},{"en":"A plan becomes more realistic when it is supported by community partners.","zh":"當計劃由社區伙伴支持，它會更實際可行。"},{"en":"This phrase explains where help can come from.","zh":"這個短語解釋支援可以來自哪裏。"}],"source":"2016 Q7.pdf","sourcePage":14},{"front":"youth centres","meaning":"青年中心","examples":[{"en":"Youth centres can support the upcycling market.","zh":"青年中心可以支持升級再造市集。"},{"en":"Youth centres are community places that provide activities and services for young people.","zh":"Youth centres 指為年輕人提供活動和服務的社區場所。"},{"en":"Youth centres may lend rooms, volunteers or workshop materials.","zh":"青年中心可能借出房間、義工或工作坊材料。"},{"en":"Working with youth centres helps the festival reach more teenagers.","zh":"與青年中心合作幫助青年節接觸更多青少年。"},{"en":"This phrase names a practical community partner.","zh":"這個短語指出一個實用社區伙伴。"}],"source":"2016 Q7.pdf","sourcePage":14},{"front":"local design groups","meaning":"本地設計團體","examples":[{"en":"Local design groups can support the market.","zh":"本地設計團體可以支持這個市集。"},{"en":"Local design groups are community-based teams interested in fashion, art or product design.","zh":"Local design groups 指本地社區中關注時裝、藝術或產品設計的團隊。"},{"en":"Local design groups can provide mentors for upcycling workshops.","zh":"本地設計團體可以為升級再造工作坊提供導師。"},{"en":"Their support can make the market more professional and creative.","zh":"他們的支持可以令市集更專業和更有創意。"},{"en":"This phrase identifies another possible partner.","zh":"這個短語指出另一個可能合作伙伴。"}],"source":"2016 Q7.pdf","sourcePage":15},{"front":"minimise the risk of disorder","meaning":"減低混亂風險","examples":[{"en":"The Association should minimise the risk of disorder.","zh":"協會應減低混亂風險。"},{"en":"Minimise the risk of disorder means reduce the chance of confusion, mess or poor control.","zh":"Minimise the risk of disorder 指減少混亂、雜亂或管理不善的可能性。"},{"en":"Clear signs can minimise the risk of disorder at a busy festival.","zh":"清楚指示牌可以減低繁忙節日中的混亂風險。"},{"en":"Advance registration helps organisers avoid overcrowding and long queues.","zh":"預先登記幫助主辦方避免過度擁擠和長隊。"},{"en":"This phrase is useful when discussing event management.","zh":"這個短語適合用於活動管理討論。"}],"source":"2016 Q7.pdf","sourcePage":15},{"front":"advance registration","meaning":"預先登記","examples":[{"en":"Workshops could require advance registration.","zh":"工作坊可以要求預先登記。"},{"en":"Advance registration means signing up before the activity begins.","zh":"Advance registration 指在活動開始前報名。"},{"en":"Advance registration helps organisers know how many people will attend.","zh":"預先登記幫助主辦方知道會有多少人參加。"},{"en":"Popular workshops need advance registration to prevent overcrowding.","zh":"受歡迎的工作坊需要預先登記，以防過度擁擠。"},{"en":"This phrase describes a practical control measure.","zh":"這個短語描述一項實用管理措施。"}],"source":"2016 Q7.pdf","sourcePage":15},{"front":"set clear rules","meaning":"訂立清晰規則","examples":[{"en":"The Association could set clear rules for clothing donations.","zh":"協會可以為衣物捐贈訂立清晰規則。"},{"en":"Set clear rules means establish easy-to-understand instructions or limits.","zh":"Set clear rules 指建立容易理解的指引或限制。"},{"en":"Organisers should set clear rules about what clothes can be donated.","zh":"主辦方應訂立清晰規則，說明哪些衣物可以捐贈。"},{"en":"Clear rules help visitors know what to do and reduce arguments.","zh":"清晰規則幫助訪客知道要做甚麼，並減少爭拗。"},{"en":"This phrase is important for keeping events organised.","zh":"這個短語對保持活動有秩序很重要。"}],"source":"2016 Q7.pdf","sourcePage":15},{"front":"clothing donations","meaning":"衣物捐贈","examples":[{"en":"Clear rules are needed for clothing donations.","zh":"衣物捐贈需要清晰規則。"},{"en":"Clothing donations are clothes given for reuse, charity or community activities.","zh":"Clothing donations 指為重用、慈善或社區活動而捐出的衣服。"},{"en":"Clothing donations should be clean and in usable condition.","zh":"衣物捐贈應保持乾淨並可使用。"},{"en":"Rules for clothing donations protect both organisers and visitors.","zh":"衣物捐贈規則能保護主辦方和訪客。"},{"en":"This phrase is useful in discussions of charity and swap events.","zh":"這個短語適合用於慈善和交換活動討論。"}],"source":"2016 Q7.pdf","sourcePage":15},{"front":"in this way","meaning":"以這種方式","examples":[{"en":"In this way, the Festival would remain well-organised.","zh":"以這種方式，青年節會保持井然有序。"},{"en":"In this way means by using the method just mentioned.","zh":"In this way 指透過剛才提到的方法。"},{"en":"Visitors can register online first; in this way, queues will be shorter.","zh":"訪客可以先在網上登記；以這種方式，排隊時間會較短。"},{"en":"Writers use this phrase to connect a solution with its result.","zh":"作者用這個短語把解決方法和結果連接起來。"},{"en":"This phrase makes practical reasoning clear.","zh":"這個短語令實際推理更清楚。"}],"source":"2016 Q7.pdf","sourcePage":15},{"front":"remain well-organised","meaning":"保持井然有序","examples":[{"en":"The Festival would remain well-organised.","zh":"青年節會保持井然有序。"},{"en":"Remain well-organised means continue to run in a clear, orderly and controlled way.","zh":"Remain well-organised 指繼續以清楚、有秩序和受控的方式運作。"},{"en":"A festival remains well-organised when visitors know where to go and what to do.","zh":"當訪客知道去哪裏和做甚麼，節日就能保持井然有序。"},{"en":"Clear rules and advance registration help events remain well-organised.","zh":"清楚規則和預先登記幫助活動保持井然有序。"},{"en":"This phrase is useful when discussing event quality.","zh":"這個短語適合用來討論活動質素。"}],"source":"2016 Q7.pdf","sourcePage":15},{"front":"energetic and youth-led","meaning":"充滿活力並由青年主導","examples":[{"en":"The Festival should feel energetic and youth-led.","zh":"青年節應感覺充滿活力並由青年主導。"},{"en":"Energetic and youth-led means lively and mainly shaped by young people.","zh":"Energetic and youth-led 指熱鬧，並主要由年輕人塑造。"},{"en":"A youth-led festival lets students host booths, lead workshops and present ideas.","zh":"由青年主導的節日讓學生主持攤位、帶領工作坊和呈現想法。"},{"en":"The event feels energetic when visitors are moving, creating and sharing.","zh":"當訪客在活動中移動、創作和分享，活動就充滿活力。"},{"en":"This phrase describes the desired character of the festival.","zh":"這個短語描述青年節應有的特質。"}],"source":"2016 Q7.pdf","sourcePage":15},{"front":"all things considered","meaning":"綜合而言","examples":[{"en":"All things considered, the Association should adopt the theme.","zh":"綜合而言，協會應採用這個主題。"},{"en":"All things considered means after thinking about all important points.","zh":"All things considered 指考慮所有重要因素之後。"},{"en":"All things considered, the plan is affordable, creative and suitable for youth.","zh":"綜合而言，這個計劃成本可負擔、有創意並適合青年。"},{"en":"This phrase is often used before a final recommendation.","zh":"這個短語常用於最終建議之前。"},{"en":"It helps close an argument in a balanced way.","zh":"它幫助以平衡方式結束論證。"}],"source":"2016 Q7.pdf","sourcePage":15},{"front":"strongly recommend that","meaning":"強烈建議","examples":[{"en":"I strongly recommend that the Association adopt the theme.","zh":"我強烈建議協會採用這個主題。"},{"en":"Strongly recommend that means firmly advise someone to do something.","zh":"Strongly recommend that 指堅定地建議某人做某事。"},{"en":"I strongly recommend that the school include more student-led activities.","zh":"我強烈建議學校加入更多由學生主導的活動。"},{"en":"This phrase shows confidence in the proposal.","zh":"這個短語顯示作者對建議有信心。"},{"en":"It is formal and persuasive.","zh":"它語氣正式並具說服力。"}],"source":"2016 Q7.pdf","sourcePage":15},{"front":"adopt the theme","meaning":"採用主題","examples":[{"en":"The Association should adopt the theme “From Screen to Street”.","zh":"協會應採用 “From Screen to Street” 這個主題。"},{"en":"Adopt the theme means officially choose and use a main idea for an event.","zh":"Adopt the theme 指正式選擇並使用某個活動主題。"},{"en":"A festival may adopt the theme of sustainability to guide all activities.","zh":"節日可以採用可持續發展主題來引導所有活動。"},{"en":"Adopting a clear theme helps visitors understand the event’s purpose.","zh":"採用清楚主題能幫助訪客理解活動目的。"},{"en":"This phrase is useful in proposals about programmes and events.","zh":"這個短語適合用於關於節目和活動的建議書。"}],"source":"2016 Q7.pdf","sourcePage":16},{"front":"visually attractive","meaning":"視覺上吸引","examples":[{"en":"The two trends are visually attractive.","zh":"這兩股潮流在視覺上很吸引。"},{"en":"Visually attractive means pleasant or exciting to look at.","zh":"Visually attractive 指看起來悅目或令人興奮。"},{"en":"Bright videos and redesigned clothes can make a booth visually attractive.","zh":"鮮明影片和改造衣服可以令攤位在視覺上吸引。"},{"en":"A visually attractive event draws visitors before they even read the information.","zh":"視覺上吸引的活動在訪客閱讀資料前已能吸引他們。"},{"en":"This phrase describes the visual appeal of an idea.","zh":"這個短語描述想法的視覺吸引力。"}],"source":"2016 Q7.pdf","sourcePage":16},{"front":"rich in educational value","meaning":"富有教育價值","examples":[{"en":"The trends are rich in educational value.","zh":"這些潮流富有教育價值。"},{"en":"Rich in educational value means full of chances for people to learn useful ideas or skills.","zh":"Rich in educational value 指充滿讓人學習有用想法或技能的機會。"},{"en":"A workshop on copyright is rich in educational value for young creators.","zh":"關於版權的工作坊對年輕創作者富有教育價值。"},{"en":"Upcycling activities teach design and environmental responsibility at the same time.","zh":"升級再造活動同時教授設計和環保責任。"},{"en":"This phrase explains why an activity is not only entertaining.","zh":"這個短語解釋活動為何不只是娛樂。"}],"source":"2016 Q7.pdf","sourcePage":16},{"front":"organising committee","meaning":"籌備委員會","examples":[{"en":"The organising committee can invite youth volunteers.","zh":"籌備委員會可以邀請青年義工。"},{"en":"The organising committee is the group responsible for planning and managing the event.","zh":"Organising committee 指負責策劃和管理活動的團隊。"},{"en":"The organising committee should choose activities that match the festival theme.","zh":"籌備委員會應選擇符合節日主題的活動。"},{"en":"A strong organising committee works with schools, creators and youth centres.","zh":"強大的籌備委員會會與學校、創作者和青年中心合作。"},{"en":"This phrase identifies the decision-making group.","zh":"這個短語指出作決定的團體。"}],"source":"2016 Q7.pdf","sourcePage":16},{"front":"youth volunteers","meaning":"青年義工","examples":[{"en":"Youth volunteers could help run the booths.","zh":"青年義工可以協助營運攤位。"},{"en":"Youth volunteers are young people who offer help without being paid.","zh":"Youth volunteers 指無薪提供幫助的年輕人。"},{"en":"Youth volunteers can guide visitors, explain rules and support workshops.","zh":"青年義工可以引導訪客、解釋規則和支援工作坊。"},{"en":"Involving youth volunteers makes the festival more youth-led.","zh":"讓青年義工參與，能令青年節更由青年主導。"},{"en":"This phrase connects service with youth participation.","zh":"這個短語把服務和青年參與連接起來。"}],"source":"2016 Q7.pdf","sourcePage":16},{"front":"local creators","meaning":"本地創作者","examples":[{"en":"Local creators could help run the booths.","zh":"本地創作者可以協助營運攤位。"},{"en":"Local creators are people from the community who make videos, art, designs or other creative work.","zh":"Local creators 指來自社區、製作影片、藝術、設計或其他創意作品的人。"},{"en":"Local creators can demonstrate filming, editing or upcycling skills.","zh":"本地創作者可以示範拍攝、剪輯或升級再造技巧。"},{"en":"Inviting local creators gives the festival authenticity and practical knowledge.","zh":"邀請本地創作者能給青年節真實感和實用知識。"},{"en":"This phrase identifies people who can share real creative experience.","zh":"這個短語指出能分享真實創作經驗的人。"}],"source":"2016 Q7.pdf","sourcePage":16},{"front":"student designers","meaning":"學生設計師","examples":[{"en":"Student designers could help with the streetwear activities.","zh":"學生設計師可以協助街頭服飾活動。"},{"en":"Student designers are students who create or study design.","zh":"Student designers 指創作或修讀設計的學生。"},{"en":"Student designers can help visitors choose colours, patches and layouts.","zh":"學生設計師可以幫訪客選擇顏色、布章和布局。"},{"en":"Working at the festival gives student designers a chance to practise their skills.","zh":"在青年節工作給學生設計師機會練習技能。"},{"en":"This phrase highlights young creative talent.","zh":"這個短語突出年輕創意人才。"}],"source":"2016 Q7.pdf","sourcePage":16},{"front":"run the booths","meaning":"營運攤位","examples":[{"en":"Volunteers and creators can help run the booths.","zh":"義工和創作者可以協助營運攤位。"},{"en":"Run the booths means manage the activity stalls and help visitors use them.","zh":"Run the booths 指管理活動攤位並幫助訪客使用。"},{"en":"Youth volunteers can run the booths by explaining rules and answering questions.","zh":"青年義工可以透過解釋規則和回答問題營運攤位。"},{"en":"Well-run booths make the festival easier and more enjoyable for visitors.","zh":"營運良好的攤位令青年節更容易參與，也更愉快。"},{"en":"This phrase describes practical event operation.","zh":"這個短語描述實際活動營運。"}],"source":"2016 Q7.pdf","sourcePage":16},{"front":"not only showcase…, but also celebrate…","meaning":"不只展示……而且頌揚……","examples":[{"en":"The Festival will not only showcase what young people like, but also celebrate what they can create.","zh":"青年節不只展示年輕人喜歡的事物，而且頌揚他們能夠創造的東西。"},{"en":"Not only showcase…, but also celebrate… means do more than display something; it also honours and values it.","zh":"Not only showcase…, but also celebrate… 指不只是展示某物，還要尊重並重視它。"},{"en":"The event should not only showcase trends, but also celebrate young people’s creativity.","zh":"活動不只應展示潮流，而且應頌揚年輕人的創意。"},{"en":"This structure adds a deeper purpose after a basic function.","zh":"這個結構在基本功能後加入更深目的。"},{"en":"It is useful for ending a proposal with a strong message.","zh":"它適合用來以有力訊息結束建議書。"}],"source":"2016 Q7.pdf","sourcePage":16},{"front":"what young people like","meaning":"年輕人喜歡的事物","examples":[{"en":"The Festival should showcase what young people like.","zh":"青年節應展示年輕人喜歡的事物。"},{"en":"What young people like means the activities, styles and ideas that interest young people.","zh":"What young people like 指令年輕人感興趣的活動、風格和想法。"},{"en":"Short videos and streetwear are examples of what many young people like.","zh":"短片和街頭服飾都是許多年輕人喜歡的事物例子。"},{"en":"A youth festival should understand what young people like before planning activities.","zh":"青年節在策劃活動前，應理解年輕人喜歡甚麼。"},{"en":"This phrase focuses on youth interests.","zh":"這個短語集中於青年興趣。"}],"source":"2016 Q7.pdf","sourcePage":16},{"front":"what they can create","meaning":"他們能夠創造的東西","examples":[{"en":"The Festival should celebrate what young people can create.","zh":"青年節應頌揚年輕人能夠創造的東西。"},{"en":"What they can create means the videos, designs, ideas or activities young people are able to make.","zh":"What they can create 指年輕人能製作的影片、設計、想法或活動。"},{"en":"A youth festival should show not only what students enjoy, but also what they can create.","zh":"青年節不只應展示學生享受甚麼，也應展示他們能夠創造甚麼。"},{"en":"Celebrating what young people can create builds confidence and ownership.","zh":"頌揚年輕人能夠創造的東西，可以建立信心和主人翁意識。"},{"en":"This phrase ends the proposal with trust in young people’s abilities.","zh":"這個短語以對年輕人能力的信任結束建議書。"}],"source":"2016 Q7.pdf","sourcePage":17}],"dse/writing/part-b/2016/Q8":[{"front":"look fear in the eye","meaning":"直視恐懼；正視恐懼","examples":[{"en":"The essay encourages students to look fear in the eye.","zh":"這篇文章鼓勵學生直視恐懼。"},{"en":"To look fear in the eye means to face what scares you directly instead of avoiding it.","zh":"直視恐懼是指直接面對令你害怕的事情，而不是逃避它。"},{"en":"A student looks fear in the eye when she admits she is nervous about speaking and starts practising.","zh":"當學生承認自己害怕演講並開始練習時，她就是在直視恐懼。"},{"en":"Looking fear in the eye can make a problem feel smaller because it becomes clearer.","zh":"直視恐懼可以令問題感覺較小，因為它變得更清楚。"},{"en":"This phrase suggests courage, honesty, and action.","zh":"這個短語表示勇氣、誠實和行動。"}],"source":"2016 Q8.pdf","sourcePage":1},{"front":"a famous songwriter","meaning":"著名創作歌手","examples":[{"en":"A famous songwriter once said that fear loses power after we face it.","zh":"一位著名創作歌手曾經說過，當我們面對恐懼後，恐懼就會失去力量。"},{"en":"A famous songwriter is a well-known person who writes songs.","zh":"著名創作歌手是指廣為人知、創作歌曲的人。"},{"en":"A famous songwriter may express difficult feelings through lyrics and music.","zh":"著名創作歌手可能透過歌詞和音樂表達困難感受。"},{"en":"Quoting a famous songwriter can make an essay opening more memorable.","zh":"引用著名創作歌手的話，可以令文章開首更令人記得。"},{"en":"This phrase identifies the person as respected or widely recognised.","zh":"這個短語表示該人物受到尊重或廣為人知。"}],"source":"2016 Q8.pdf","sourcePage":1},{"front":"once said","meaning":"曾經說過","examples":[{"en":"A famous songwriter once said that fear has no power after we face it.","zh":"一位著名創作歌手曾經說過，當我們面對恐懼後，恐懼就沒有力量。"},{"en":"Once said is used to introduce something someone said in the past.","zh":"曾經說過用來引出某人在過去說過的話。"},{"en":"A teacher once said that mistakes are proof that learning is happening.","zh":"一位老師曾經說過，錯誤是學習正在發生的證明。"},{"en":"Writers use once said to bring a quotation or remembered idea into an essay.","zh":"作者使用「曾經說過」把引言或記得的想法帶入文章。"},{"en":"This phrase connects the present discussion with someone’s earlier words.","zh":"這個短語把現在的討論與某人早前的話連接起來。"}],"source":"2016 Q8.pdf","sourcePage":1},{"front":"expose yourself to","meaning":"讓自己面對……","examples":[{"en":"Expose yourself to your deepest fear.","zh":"讓自己面對你最深層的恐懼。"},{"en":"To expose yourself to something means to let yourself experience it instead of hiding from it.","zh":"讓自己面對某事，是指讓自己經歷它，而不是躲開它。"},{"en":"A shy student may expose herself to public speaking by first practising in front of one friend.","zh":"害羞的學生可以先在一位朋友面前練習，讓自己面對公開演說。"},{"en":"Exposing yourself to fear slowly can help your mind learn that the danger is manageable.","zh":"慢慢讓自己面對恐懼，可以幫助大腦學會危險是可以處理的。"},{"en":"This phrase should suggest careful facing, not reckless suffering.","zh":"這個短語應表示謹慎面對，而不是魯莽受苦。"}],"source":"2016 Q8.pdf","sourcePage":1},{"front":"deepest fear","meaning":"最深層的恐懼","examples":[{"en":"We should learn to face our deepest fear.","zh":"我們應學會面對自己最深層的恐懼。"},{"en":"Deepest fear means the worry or terror that feels most hidden and powerful inside us.","zh":"最深層的恐懼，是指內心最隱藏、最有力量的憂慮或害怕。"},{"en":"A student’s deepest fear may be being laughed at by classmates.","zh":"學生最深層的恐懼可能是被同學取笑。"},{"en":"Naming your deepest fear can make it easier to plan how to handle it.","zh":"說出自己最深層的恐懼，可以令你更容易計劃如何處理它。"},{"en":"This phrase points to a fear that is personal, serious, and hard to admit.","zh":"這個短語指向一種個人、嚴重且難以承認的恐懼。"}],"source":"2016 Q8.pdf","sourcePage":1},{"front":"after that","meaning":"在那之後","examples":[{"en":"After that, fear has no power.","zh":"在那之後，恐懼就沒有力量。"},{"en":"After that means following the action or event just mentioned.","zh":"在那之後，是指在剛才提到的行動或事件之後。"},{"en":"I wrote down my worries; after that, they felt less confusing.","zh":"我寫下自己的憂慮；在那之後，它們感覺沒那麼混亂。"},{"en":"A speaker may use after that to show the result of a previous step.","zh":"講者可能使用「在那之後」來顯示前一步的結果。"},{"en":"This phrase helps organise events in a clear order.","zh":"這個短語幫助清楚安排事件次序。"}],"source":"2016 Q8.pdf","sourcePage":1},{"front":"have no power","meaning":"沒有力量","examples":[{"en":"After we face fear, it has no power.","zh":"當我們面對恐懼後，它就沒有力量。"},{"en":"To have no power means to be unable to control, frighten, or influence someone strongly.","zh":"沒有力量是指不能強烈控制、嚇倒或影響某人。"},{"en":"A rumour has no power when everyone knows the truth.","zh":"當所有人都知道真相時，謠言就沒有力量。"},{"en":"Fear has less power when we understand what causes it.","zh":"當我們明白恐懼的成因時，恐懼的力量會減少。"},{"en":"This phrase shows that something loses control over us.","zh":"這個短語顯示某物失去對我們的控制。"}],"source":"2016 Q8.pdf","sourcePage":1},{"front":"although the line sounds dramatic","meaning":"雖然這句話聽起來戲劇化","examples":[{"en":"Although the line sounds dramatic, it speaks directly to ordinary life.","zh":"雖然這句話聽起來戲劇化，但它直接切中日常生活。"},{"en":"Although the line sounds dramatic means even though the sentence may seem emotional or theatrical.","zh":"雖然這句話聽起來戲劇化，是指即使這句話看似情緒化或像舞台台詞。"},{"en":"Although the line sounds dramatic, its message about facing fear is simple and practical.","zh":"雖然這句話聽起來戲劇化，但它關於面對恐懼的信息簡單而實用。"},{"en":"This phrase helps writers admit a possible weakness before defending the idea.","zh":"這個短語幫助作者先承認一個可能的弱點，再為想法辯護。"},{"en":"It shows contrast between style and meaning.","zh":"它顯示風格與意思之間的對比。"}],"source":"2016 Q8.pdf","sourcePage":1},{"front":"speak directly to","meaning":"直接切中……","examples":[{"en":"The line speaks directly to ordinary life.","zh":"這句話直接切中日常生活。"},{"en":"To speak directly to something means to be clearly relevant to it.","zh":"直接切中某事，是指與它有清楚而直接的關係。"},{"en":"A story about exam stress speaks directly to students who feel pressure every day.","zh":"關於考試壓力的故事，直接切中每天感到壓力的學生。"},{"en":"Advice speaks directly to a problem when it gives words to what people experience.","zh":"當建議能說出人們的經歷時，它就直接切中問題。"},{"en":"This phrase shows that an idea is not distant or abstract.","zh":"這個短語顯示想法並不遙遠或抽象。"}],"source":"2016 Q8.pdf","sourcePage":1},{"front":"ordinary life","meaning":"日常生活","examples":[{"en":"The quotation speaks directly to ordinary life.","zh":"這句引言直接切中日常生活。"},{"en":"Ordinary life means normal daily experiences such as school, family, friendships, and work.","zh":"日常生活是指普通每天的經歷，例如學校、家庭、友誼和工作。"},{"en":"Fear appears in ordinary life when students face tests, arguments, or presentations.","zh":"當學生面對測驗、爭執或匯報時，恐懼會出現在日常生活中。"},{"en":"An idea is useful when it helps people handle ordinary life better.","zh":"當一個想法能幫助人更好應付日常生活時，它就是有用的。"},{"en":"This phrase brings a big idea down to familiar situations.","zh":"這個短語把大想法帶到熟悉情境之中。"}],"source":"2016 Q8.pdf","sourcePage":1},{"front":"from examinations to friendships","meaning":"由考試到友誼","examples":[{"en":"From examinations to friendships, challenges do not disappear by themselves.","zh":"由考試到友誼，挑戰不會自行消失。"},{"en":"From examinations to friendships means across many parts of student life, including study and relationships.","zh":"由考試到友誼，是指跨越學生生活的許多部分，包括學習和人際關係。"},{"en":"From examinations to friendships, young people meet situations that require courage and honesty.","zh":"由考試到友誼，年輕人會遇到需要勇氣和誠實的情況。"},{"en":"This phrase shows that the idea applies widely, not only to one problem.","zh":"這個短語顯示想法適用範圍廣，而不只限於一個問題。"},{"en":"It helps an essay connect school pressure with personal relationships.","zh":"它幫助文章把學校壓力與個人關係連接起來。"}],"source":"2016 Q8.pdf","sourcePage":2},{"front":"challenges do not disappear","meaning":"挑戰不會消失","examples":[{"en":"Challenges do not disappear because we refuse to name them.","zh":"挑戰不會因為我們拒絕說出它們而消失。"},{"en":"Challenges do not disappear means problems remain even if we ignore them.","zh":"挑戰不會消失，是指即使我們忽視問題，問題仍然存在。"},{"en":"Homework pressure does not disappear just because a student avoids looking at the planner.","zh":"學生避開看手冊，功課壓力也不會消失。"},{"en":"Challenges may grow worse when they are hidden for too long.","zh":"當挑戰被隱藏太久時，可能會變得更嚴重。"},{"en":"This phrase warns that avoidance is not a solution.","zh":"這個短語警告我們，逃避不是解決方法。"}],"source":"2016 Q8.pdf","sourcePage":2},{"front":"refuse to name","meaning":"拒絕指出；拒絕說出","examples":[{"en":"Challenges do not disappear because we refuse to name them.","zh":"挑戰不會因為我們拒絕說出它們而消失。"},{"en":"To refuse to name something means to avoid saying clearly what the problem is.","zh":"拒絕說出某事，是指避免清楚指出問題是甚麼。"},{"en":"A student may refuse to name their fear because admitting it feels embarrassing.","zh":"學生可能因覺得尷尬而拒絕說出自己的恐懼。"},{"en":"When people refuse to name a problem, they cannot plan how to solve it.","zh":"當人們拒絕指出問題時，他們就無法計劃如何解決。"},{"en":"This phrase shows how silence can make fear stronger.","zh":"這個短語顯示沉默如何令恐懼更強。"}],"source":"2016 Q8.pdf","sourcePage":2},{"front":"instead","meaning":"反而","examples":[{"en":"Instead, challenges grow quietly in the dark.","zh":"反而，挑戰會在黑暗中悄悄壯大。"},{"en":"Instead introduces what happens in place of what someone expected.","zh":"反而用來引出取代預期情況而發生的事情。"},{"en":"Ignored problems do not vanish; instead, they often become harder to handle.","zh":"被忽視的問題不會消失；反而，它們常變得更難處理。"},{"en":"A writer uses instead to show contrast between hope and reality.","zh":"作者使用「反而」來顯示希望與現實之間的對比。"},{"en":"This word helps explain that avoidance can produce the opposite result.","zh":"這個詞幫助解釋逃避可能產生相反結果。"}],"source":"2016 Q8.pdf","sourcePage":2},{"front":"grow quietly in the dark","meaning":"在黑暗中悄悄壯大","examples":[{"en":"Challenges grow quietly in the dark when we ignore them.","zh":"當我們忽視挑戰時，它們會在黑暗中悄悄壯大。"},{"en":"To grow quietly in the dark means to become worse while hidden and unnoticed.","zh":"在黑暗中悄悄壯大，是指在被隱藏和未被注意時變得更嚴重。"},{"en":"Anxiety can grow quietly in the dark when a student tells no one about it.","zh":"當學生不向任何人說出焦慮時，焦慮可能在黑暗中悄悄壯大。"},{"en":"Small misunderstandings may grow quietly in the dark if friends never talk honestly.","zh":"如果朋友從不坦誠交談，小誤會可能在黑暗中悄悄壯大。"},{"en":"This image shows that hidden problems can become larger over time.","zh":"這個意象顯示隱藏的問題會隨時間變大。"}],"source":"2016 Q8.pdf","sourcePage":2},{"front":"this has made many young people consider whether","meaning":"這使很多年輕人思考是否","examples":[{"en":"This has made many young people consider whether they should hide their weaknesses.","zh":"這使很多年輕人思考是否應該隱藏自己的弱點。"},{"en":"This has made many young people consider whether means this situation has caused young people to think seriously about a choice.","zh":"這使很多年輕人思考是否……，意思是這種情況令年輕人認真思考一個選擇。"},{"en":"Exam pressure has made many students consider whether they should ask for help.","zh":"考試壓力使很多學生思考是否應該求助。"},{"en":"This phrase introduces a question created by a problem or experience.","zh":"這個短語引出由問題或經歷產生的疑問。"},{"en":"It helps writers move from a situation to a larger issue.","zh":"它幫助作者由一個情況轉向更大的議題。"}],"source":"2016 Q8.pdf","sourcePage":2},{"front":"hide their weaknesses","meaning":"隱藏自己的弱點","examples":[{"en":"Some young people wonder whether they should hide their weaknesses.","zh":"有些年輕人想知道自己是否應該隱藏弱點。"},{"en":"To hide their weaknesses means to keep their difficulties, fears, or limits secret.","zh":"隱藏自己的弱點，是指把自己的困難、恐懼或限制保密。"},{"en":"A student may hide their weaknesses by pretending they understand the lesson.","zh":"學生可能假裝聽懂課堂，藉此隱藏自己的弱點。"},{"en":"Hiding weaknesses can stop people from receiving help in time.","zh":"隱藏弱點可能阻止人及時得到幫助。"},{"en":"This phrase shows the pressure to appear strong even when struggling.","zh":"這個短語顯示即使正在掙扎，人也有表現堅強的壓力。"}],"source":"2016 Q8.pdf","sourcePage":2},{"front":"face them openly","meaning":"坦然面對它們","examples":[{"en":"Young people should learn to face their weaknesses openly.","zh":"年輕人應學會坦然面對自己的弱點。"},{"en":"To face them openly means to admit problems honestly instead of pretending they are not there.","zh":"坦然面對它們，是指誠實承認問題，而不是假裝問題不存在。"},{"en":"A student faces weaknesses openly when he tells a teacher he needs help with grammar.","zh":"當學生告訴老師自己需要文法幫助時，他就是坦然面對弱點。"},{"en":"Facing problems openly allows others to give useful support.","zh":"坦然面對問題能讓別人提供有用支援。"},{"en":"This phrase values honesty as the first step toward growth.","zh":"這個短語重視誠實作為成長的第一步。"}],"source":"2016 Q8.pdf","sourcePage":2},{"front":"in order to become","meaning":"為了變得","examples":[{"en":"They should face challenges in order to become calmer and stronger.","zh":"他們應面對挑戰，為了變得更冷靜和更堅強。"},{"en":"In order to become means for the purpose of developing into a certain state or kind of person.","zh":"為了變得……，是指以發展成某種狀態或某類人為目的。"},{"en":"Students practise regularly in order to become more confident speakers.","zh":"學生定期練習，為了變得更有信心演講。"},{"en":"We face difficulty in order to become wiser, not because difficulty is enjoyable.","zh":"我們面對困難，是為了變得更明智，而不是因為困難令人享受。"},{"en":"This phrase clearly connects action with purpose.","zh":"這個短語清楚連接行動與目的。"}],"source":"2016 Q8.pdf","sourcePage":2},{"front":"calmer and stronger","meaning":"更冷靜和更堅強","examples":[{"en":"Facing challenges can make us calmer and stronger.","zh":"面對挑戰可以令我們更冷靜和更堅強。"},{"en":"Calmer and stronger means more peaceful in mind and more able to handle difficulty.","zh":"更冷靜和更堅強，是指內心更平靜，並更能應付困難。"},{"en":"A student becomes calmer and stronger after learning how to prepare for presentations.","zh":"學生學會如何準備匯報後，會變得更冷靜和更堅強。"},{"en":"People often become calmer and stronger when they understand their fear instead of hiding it.","zh":"當人們理解自己的恐懼，而不是隱藏它時，常會變得更冷靜和更堅強。"},{"en":"This phrase describes emotional growth through experience.","zh":"這個短語描述透過經驗而來的情緒成長。"}],"source":"2016 Q8.pdf","sourcePage":2},{"front":"in my view","meaning":"在我看來","examples":[{"en":"In my view, acknowledging challenges is essential.","zh":"在我看來，承認挑戰是必不可少的。"},{"en":"In my view means in my opinion or from my perspective.","zh":"在我看來，是指以我的意見或角度來說。"},{"en":"In my view, asking for help is a sign of wisdom, not weakness.","zh":"在我看來，求助是智慧的表現，而不是軟弱。"},{"en":"Writers use this phrase to present their opinion clearly but politely.","zh":"作者使用這個短語清楚而有禮地提出自己的看法。"},{"en":"It signals that the following sentence is a personal judgement.","zh":"它表示接下來的句子是個人判斷。"}],"source":"2016 Q8.pdf","sourcePage":3},{"front":"acknowledging challenges","meaning":"承認挑戰","examples":[{"en":"Acknowledging challenges is essential for personal growth.","zh":"承認挑戰對個人成長是必不可少的。"},{"en":"Acknowledging challenges means admitting that difficulties exist instead of denying them.","zh":"承認挑戰是指承認困難存在，而不是否認它們。"},{"en":"A student acknowledges a challenge when she says, “I find public speaking frightening.”","zh":"當學生說「我覺得公開演說很可怕」時，她就是承認挑戰。"},{"en":"Acknowledging challenges helps people decide what support or practice they need.","zh":"承認挑戰幫助人決定自己需要甚麼支援或練習。"},{"en":"This phrase shows that honesty comes before improvement.","zh":"這個短語顯示誠實先於改善。"}],"source":"2016 Q8.pdf","sourcePage":3},{"front":"finding ways to cope with","meaning":"找方法應對……","examples":[{"en":"Finding ways to cope with challenges is essential.","zh":"找方法應對挑戰是必不可少的。"},{"en":"Finding ways to cope with something means looking for practical methods to handle it.","zh":"找方法應對某事，是指尋找實際方法來處理它。"},{"en":"A student may find ways to cope with exam stress by planning revision and sleeping earlier.","zh":"學生可以透過計劃溫習和早睡，找方法應對考試壓力。"},{"en":"Finding coping methods turns fear into a problem that can be managed.","zh":"找到應對方法能把恐懼變成可以管理的問題。"},{"en":"This phrase focuses on action, not just emotion.","zh":"這個短語著重行動，而不只是情緒。"}],"source":"2016 Q8.pdf","sourcePage":3},{"front":"cope with","meaning":"應對","examples":[{"en":"We need to find ways to cope with fear.","zh":"我們需要找方法應對恐懼。"},{"en":"To cope with something means to deal with a difficult situation without being defeated by it.","zh":"應對某事，是指處理困難情況而不被它擊倒。"},{"en":"Students cope with pressure better when they divide tasks into smaller steps.","zh":"當學生把任務分成較小步驟時，會更好地應對壓力。"},{"en":"Coping with fear does not mean feeling no fear; it means continuing wisely despite it.","zh":"應對恐懼並不代表沒有恐懼，而是即使害怕仍明智地繼續。"},{"en":"This phrase is useful for describing practical emotional management.","zh":"這個短語適合描述實際的情緒管理。"}],"source":"2016 Q8.pdf","sourcePage":3},{"front":"is essential","meaning":"是必不可少的","examples":[{"en":"Acknowledging challenges is essential.","zh":"承認挑戰是必不可少的。"},{"en":"Is essential means is absolutely necessary and cannot be left out.","zh":"是必不可少的，是指絕對需要，不能被省略。"},{"en":"Sleep is essential for students who want to concentrate well.","zh":"對想好好專注的學生來說，睡眠是必不可少的。"},{"en":"Honest communication is essential when friends need to repair trust.","zh":"當朋友需要修補信任時，誠實溝通是必不可少的。"},{"en":"This phrase shows that something is not optional.","zh":"這個短語顯示某事不是可有可無的。"}],"source":"2016 Q8.pdf","sourcePage":3},{"front":"only by recognising","meaning":"只有透過認清","examples":[{"en":"Only by recognising what frightens us can we understand it.","zh":"只有透過認清令我們害怕的事，我們才能理解它。"},{"en":"Only by recognising means we can achieve something only after noticing or admitting it clearly.","zh":"只有透過認清，是指只有在清楚注意或承認某事後，才可以達成某事。"},{"en":"Only by recognising weak study habits can students improve their marks.","zh":"只有透過認清薄弱的學習習慣，學生才能改善成績。"},{"en":"This structure strongly links awareness with progress.","zh":"這個句式強烈連接覺察與進步。"},{"en":"It shows that understanding begins with honest recognition.","zh":"它顯示理解始於誠實認清。"}],"source":"2016 Q8.pdf","sourcePage":3},{"front":"what frightens us","meaning":"令我們害怕的事","examples":[{"en":"We need to recognise what frightens us.","zh":"我們需要認清令我們害怕的事。"},{"en":"What frightens us means the thing, thought, or situation that makes us afraid.","zh":"令我們害怕的事，是指令我們感到害怕的事物、想法或情況。"},{"en":"For some students, what frightens them is not the exam but disappointing their parents.","zh":"對一些學生來說，令他們害怕的不是考試，而是令父母失望。"},{"en":"Knowing what frightens us helps us choose the right kind of support.","zh":"知道令我們害怕的事，有助我們選擇合適的支援。"},{"en":"This phrase asks us to identify fear clearly.","zh":"這個短語要求我們清楚辨認恐懼。"}],"source":"2016 Q8.pdf","sourcePage":3},{"front":"manage it","meaning":"管理它；控制它","examples":[{"en":"We can understand fear, manage it, and outgrow it.","zh":"我們可以理解恐懼、管理它，並成長至不再受它限制。"},{"en":"To manage it means to control or handle a problem so it does not control you.","zh":"管理它是指控制或處理一個問題，使它不控制你。"},{"en":"A student can manage nervousness by practising breathing and preparing notes.","zh":"學生可以透過練習呼吸和準備筆記來管理緊張。"},{"en":"Managing fear does not remove it completely, but it makes action possible.","zh":"管理恐懼不會完全移除它，但會令行動成為可能。"},{"en":"This phrase shows practical control over a difficult feeling.","zh":"這個短語顯示對困難感受的實際控制。"}],"source":"2016 Q8.pdf","sourcePage":3},{"front":"outgrow it","meaning":"成長至不再受它限制","examples":[{"en":"We can eventually outgrow our fear.","zh":"我們最終可以成長至不再受恐懼限制。"},{"en":"To outgrow it means to become stronger or more mature so that it no longer controls you.","zh":"成長至不再受它限制，是指變得更強或更成熟，使它不再控制你。"},{"en":"A child may outgrow a fear of the dark after learning that the room is safe.","zh":"孩子知道房間是安全後，可能成長至不再害怕黑暗。"},{"en":"Students can outgrow fear of speaking by practising in small, steady steps.","zh":"學生可以透過小而穩定的練習，成長至不再害怕演講。"},{"en":"This phrase suggests growth over time, not instant disappearance.","zh":"這個短語表示隨時間成長，而不是立即消失。"}],"source":"2016 Q8.pdf","sourcePage":3},{"front":"give fear a clear shape","meaning":"令恐懼有清晰形狀","examples":[{"en":"Acknowledging a challenge gives fear a clear shape.","zh":"承認挑戰會令恐懼有清晰形狀。"},{"en":"To give fear a clear shape means to make a vague worry specific and easier to understand.","zh":"令恐懼有清晰形狀，是指把含糊的憂慮變得具體和較容易理解。"},{"en":"Writing “I fear forgetting my lines” gives fear a clear shape.","zh":"寫下「我害怕忘記台詞」會令恐懼有清晰形狀。"},{"en":"Once fear has a clear shape, people can plan a clear response.","zh":"一旦恐懼有清晰形狀，人們就可以計劃清晰回應。"},{"en":"This phrase shows that naming fear makes it less mysterious.","zh":"這個短語顯示說出恐懼會令它不再那麼神秘。"}],"source":"2016 Q8.pdf","sourcePage":3},{"front":"a nameless fear","meaning":"無名的恐懼","examples":[{"en":"A nameless fear is like smoke in a closed room.","zh":"無名的恐懼就像密閉房間裡的煙。"},{"en":"A nameless fear is a fear that has not been clearly identified or explained.","zh":"無名的恐懼是尚未被清楚辨認或解釋的恐懼。"},{"en":"A student may feel a nameless fear before school without knowing whether it is about friends, exams, or teachers.","zh":"學生上學前可能感到無名的恐懼，不知道它是關於朋友、考試還是老師。"},{"en":"Nameless fear can feel larger because the mind cannot see its exact source.","zh":"無名的恐懼可能感覺更大，因為大腦看不見它的確切源頭。"},{"en":"Naming the fear is the first step to making it manageable.","zh":"為恐懼命名，是令它可處理的第一步。"}],"source":"2016 Q8.pdf","sourcePage":4},{"front":"a closed room","meaning":"密閉房間","examples":[{"en":"A nameless fear is like smoke in a closed room.","zh":"無名的恐懼就像密閉房間裡的煙。"},{"en":"A closed room is a room with no easy way for air, light, or people to move through.","zh":"密閉房間是空氣、光線或人不容易通過的房間。"},{"en":"Smoke in a closed room spreads quickly because it has nowhere to escape.","zh":"密閉房間裡的煙會迅速擴散，因為它沒有地方逃出。"},{"en":"Comparing fear to smoke in a closed room shows how trapped anxiety can feel.","zh":"把恐懼比作密閉房間裡的煙，顯示被困住的焦慮感覺如何。"},{"en":"This image helps readers understand fear as something that fills the mind.","zh":"這個意象幫助讀者理解恐懼像填滿大腦的東西。"}],"source":"2016 Q8.pdf","sourcePage":4},{"front":"spread everywhere","meaning":"到處蔓延","examples":[{"en":"Fear spreads everywhere when it is not named.","zh":"當恐懼沒有被說出來時，它會到處蔓延。"},{"en":"To spread everywhere means to move into many parts of a place or situation.","zh":"到處蔓延是指進入一個地方或情況的許多部分。"},{"en":"One worry about an exam can spread everywhere until it affects sleep, mood, and friendships.","zh":"一個關於考試的憂慮可能到處蔓延，直到影響睡眠、心情和友誼。"},{"en":"Fear spreads when people do not know exactly what they are afraid of.","zh":"當人們不知道自己到底害怕甚麼時，恐懼會蔓延。"},{"en":"This phrase shows how one hidden problem can affect many areas of life.","zh":"這個短語顯示一個隱藏問題如何影響生活多個範圍。"}],"source":"2016 Q8.pdf","sourcePage":4},{"front":"make it hard to breathe","meaning":"令人難以呼吸","examples":[{"en":"A nameless fear makes it hard to breathe.","zh":"無名的恐懼令人難以呼吸。"},{"en":"To make it hard to breathe means to create pressure so heavy that someone feels trapped or anxious.","zh":"令人難以呼吸，是指造成沉重壓力，使人感到被困或焦慮。"},{"en":"Too many hidden worries can make it hard to breathe even before anything bad happens.","zh":"太多隱藏憂慮可能在壞事發生前，已令人難以呼吸。"},{"en":"Talking about fear can reduce the feeling that it is hard to breathe.","zh":"談論恐懼可以減少那種難以呼吸的感覺。"},{"en":"This phrase describes emotional pressure through a physical image.","zh":"這個短語透過身體意象描述情緒壓力。"}],"source":"2016 Q8.pdf","sourcePage":4},{"front":"once we name it","meaning":"一旦我們把它說出來","examples":[{"en":"Once we name fear, we can locate its source.","zh":"一旦我們把恐懼說出來，就可以找出其源頭。"},{"en":"Once we name it means after we identify and say clearly what the problem is.","zh":"一旦我們把它說出來，是指在我們辨認並清楚說出問題是甚麼之後。"},{"en":"Once we name anxiety as fear of failure, we can plan how to study better.","zh":"一旦我們把焦慮說成害怕失敗，就可以計劃如何更好地學習。"},{"en":"Naming a problem gives us a starting point for action.","zh":"說出問題給我們一個行動起點。"},{"en":"This phrase shows that clarity often comes before control.","zh":"這個短語顯示清晰通常先於控制。"}],"source":"2016 Q8.pdf","sourcePage":4},{"front":"locate its source","meaning":"找出其源頭","examples":[{"en":"Once we name fear, we can locate its source.","zh":"一旦我們說出恐懼，就可以找出其源頭。"},{"en":"To locate its source means to find where a feeling or problem begins.","zh":"找出其源頭，是指找到某種感受或問題從哪裡開始。"},{"en":"A student may locate the source of stress in poor planning, not in the exam itself.","zh":"學生可能發現壓力的源頭在於計劃不足，而不是考試本身。"},{"en":"Locating the source helps people solve the real problem rather than guess.","zh":"找出源頭能幫助人解決真正問題，而不是猜測。"},{"en":"This phrase turns fear into something that can be investigated.","zh":"這個短語把恐懼變成可以調查的東西。"}],"source":"2016 Q8.pdf","sourcePage":4},{"front":"decide what to do next","meaning":"決定下一步做甚麼","examples":[{"en":"After locating the source, we can decide what to do next.","zh":"找出源頭後，我們可以決定下一步做甚麼。"},{"en":"To decide what to do next means to choose the following practical step.","zh":"決定下一步做甚麼，是指選擇接下來的實際步驟。"},{"en":"After learning that he fears eye contact, a student can decide what to do next by practising with one friend.","zh":"當學生知道自己害怕眼神接觸後，可以透過先和一位朋友練習來決定下一步做甚麼。"},{"en":"Clear decisions become easier when the problem is specific.","zh":"當問題具體時，清晰決定會變得更容易。"},{"en":"This phrase links understanding with action.","zh":"這個短語把理解與行動連接起來。"}],"source":"2016 Q8.pdf","sourcePage":4},{"front":"I learnt this in Form Four","meaning":"我在中四學到這一點","examples":[{"en":"I learnt this in Form Four when I had to give a presentation.","zh":"我在中四要做匯報時學到這一點。"},{"en":"I learnt this in Form Four means the writer discovered this lesson during the fourth year of secondary school.","zh":"我在中四學到這一點，是指作者在中學第四年期間明白這個道理。"},{"en":"A student may say this when connecting a personal school experience to a wider lesson.","zh":"當學生把個人學校經歷連接到更大道理時，可能會這樣說。"},{"en":"The phrase makes an essay more personal and believable.","zh":"這個短語令文章更個人化和可信。"},{"en":"It shows that the writer’s opinion comes from real experience.","zh":"它顯示作者的看法來自真實經驗。"}],"source":"2016 Q8.pdf","sourcePage":4},{"front":"give an English presentation","meaning":"做英文匯報","examples":[{"en":"I had to give an English presentation in Form Four.","zh":"我在中四時要做英文匯報。"},{"en":"To give an English presentation means to speak in English to explain a topic to an audience.","zh":"做英文匯報，是指用英語向觀眾講解一個主題。"},{"en":"Students may give an English presentation about a book, a social issue, or a project.","zh":"學生可能就一本書、社會議題或專題做英文匯報。"},{"en":"Giving a presentation can be frightening because others are listening and judging.","zh":"做匯報可能令人害怕，因為別人在聆聽和評價。"},{"en":"This phrase describes a common school task that requires preparation and courage.","zh":"這個短語描述一項需要準備和勇氣的常見學校任務。"}],"source":"2016 Q8.pdf","sourcePage":4},{"front":"not good at public speaking","meaning":"不擅長公開演說","examples":[{"en":"I told myself that I was just not good at public speaking.","zh":"我告訴自己，我只是一直不擅長公開演說。"},{"en":"Not good at public speaking means finding it difficult to speak clearly and confidently before an audience.","zh":"不擅長公開演說，是指在觀眾面前清楚而有信心地說話感到困難。"},{"en":"A student may think they are not good at public speaking because their voice shakes.","zh":"學生可能因為聲音顫抖，就以為自己不擅長公開演說。"},{"en":"Saying this too quickly can hide the real fear behind the problem.","zh":"太快這樣說，可能會隱藏問題背後真正的恐懼。"},{"en":"This phrase describes a difficulty, but it should not become a permanent label.","zh":"這個短語描述一種困難，但不應成為永久標籤。"}],"source":"2016 Q8.pdf","sourcePage":4},{"front":"in reality","meaning":"事實上","examples":[{"en":"In reality, I was terrified of being laughed at.","zh":"事實上，我非常害怕被取笑。"},{"en":"In reality means what is actually true, rather than what first seemed true.","zh":"事實上，是指真正的情況，而不是起初看似真實的情況。"},{"en":"I thought I hated presentations; in reality, I feared making mistakes in public.","zh":"我以為自己討厭匯報；事實上，我害怕在公開場合犯錯。"},{"en":"Writers use in reality to reveal the deeper truth behind an explanation.","zh":"作者使用「事實上」來揭示解釋背後更深的真相。"},{"en":"This phrase helps correct a surface impression.","zh":"這個短語幫助修正表面印象。"}],"source":"2016 Q8.pdf","sourcePage":5},{"front":"be terrified of","meaning":"非常害怕","examples":[{"en":"I was terrified of being laughed at.","zh":"我非常害怕被取笑。"},{"en":"To be terrified of something means to be extremely afraid of it.","zh":"非常害怕某事，是指對它感到極度恐懼。"},{"en":"A child may be terrified of swimming after nearly drowning.","zh":"孩子差點遇溺後，可能非常害怕游泳。"},{"en":"Students can be terrified of failure when they believe one mistake will ruin everything.","zh":"當學生相信一次錯誤會毀掉一切時，可能非常害怕失敗。"},{"en":"This phrase describes fear that feels intense and difficult to control.","zh":"這個短語描述強烈而難以控制的恐懼。"}],"source":"2016 Q8.pdf","sourcePage":5},{"front":"being laughed at","meaning":"被取笑","examples":[{"en":"I was terrified of being laughed at.","zh":"我非常害怕被取笑。"},{"en":"Being laughed at means having other people mock, tease, or make fun of you.","zh":"被取笑是指別人嘲笑、戲弄或拿你開玩笑。"},{"en":"A student may fear being laughed at if they pronounce a word wrongly in class.","zh":"如果學生在課堂讀錯一個字，可能會害怕被取笑。"},{"en":"The fear of being laughed at can stop people from trying new things.","zh":"害怕被取笑可以阻止人嘗試新事物。"},{"en":"This phrase shows why social judgement can feel painful.","zh":"這個短語顯示為何社交評價會令人痛苦。"}],"source":"2016 Q8.pdf","sourcePage":5},{"front":"refuse to admit","meaning":"拒絕承認","examples":[{"en":"I refused to admit that I was afraid.","zh":"我拒絕承認自己害怕。"},{"en":"To refuse to admit something means to avoid accepting or saying the truth.","zh":"拒絕承認某事，是指避免接受或說出真相。"},{"en":"A student may refuse to admit they need help because they do not want to look weak.","zh":"學生可能因不想顯得軟弱，而拒絕承認自己需要幫助。"},{"en":"Refusing to admit fear can stop people from preparing properly.","zh":"拒絕承認恐懼可能阻止人好好準備。"},{"en":"This phrase shows how pride can block honesty.","zh":"這個短語顯示自尊如何阻礙誠實。"}],"source":"2016 Q8.pdf","sourcePage":5},{"front":"avoid practice","meaning":"逃避練習","examples":[{"en":"Because I refused to admit my fear, I avoided practice.","zh":"因為我拒絕承認恐懼，所以我逃避練習。"},{"en":"To avoid practice means to stay away from training or preparation because it feels uncomfortable.","zh":"逃避練習是指因練習令人不舒服而避開訓練或準備。"},{"en":"A student may avoid practice when rehearsing reminds them of possible failure.","zh":"當排練令人想起可能失敗時，學生可能會逃避練習。"},{"en":"Avoiding practice often makes fear worse because the task remains unfamiliar.","zh":"逃避練習常令恐懼更嚴重，因為任務仍然陌生。"},{"en":"This phrase shows how avoidance can create a bigger problem.","zh":"這個短語顯示逃避如何製造更大問題。"}],"source":"2016 Q8.pdf","sourcePage":5},{"front":"rush my preparation","meaning":"匆忙準備","examples":[{"en":"I rushed my preparation before the presentation.","zh":"我在匯報前匆忙準備。"},{"en":"To rush my preparation means to prepare too quickly and without enough care.","zh":"匆忙準備是指準備得太快，而且不夠仔細。"},{"en":"A student may rush preparation the night before a speech and forget important points.","zh":"學生可能在演講前一晚匆忙準備，並忘記重要重點。"},{"en":"Rushed preparation can increase fear because the person feels unready.","zh":"匆忙準備會增加恐懼，因為人會感到未準備好。"},{"en":"This phrase shows a practical result of avoiding a task.","zh":"這個短語顯示逃避任務帶來的實際結果。"}],"source":"2016 Q8.pdf","sourcePage":5},{"front":"stand before my classmates","meaning":"站在同學面前","examples":[{"en":"I stood before my classmates with shaking hands.","zh":"我雙手顫抖地站在同學面前。"},{"en":"To stand before my classmates means to stand in front of classmates while they watch or listen.","zh":"站在同學面前，是指站在同學前方，讓他們觀看或聆聽。"},{"en":"A student may stand before classmates to give a speech, act in a scene, or explain a project.","zh":"學生可能站在同學面前演講、演戲或講解專題。"},{"en":"Standing before others can feel frightening because attention is focused on you.","zh":"站在別人面前可能令人害怕，因為注意力集中在你身上。"},{"en":"This phrase places the fear in a clear classroom situation.","zh":"這個短語把恐懼放在清晰的課室情境中。"}],"source":"2016 Q8.pdf","sourcePage":5},{"front":"shaking hands","meaning":"顫抖的雙手","examples":[{"en":"I stood before my classmates with shaking hands.","zh":"我雙手顫抖地站在同學面前。"},{"en":"Shaking hands are hands that tremble because of fear, cold, illness, or nervousness.","zh":"顫抖的雙手，是因恐懼、寒冷、疾病或緊張而發抖的手。"},{"en":"Before a piano performance, a student may have shaking hands from anxiety.","zh":"鋼琴表演前，學生可能因焦慮而雙手顫抖。"},{"en":"Shaking hands can show that fear is affecting the body.","zh":"顫抖的雙手可以顯示恐懼正在影響身體。"},{"en":"This phrase gives a physical sign of emotional pressure.","zh":"這個短語給出情緒壓力的身體徵象。"}],"source":"2016 Q8.pdf","sourcePage":5},{"front":"a blank mind","meaning":"腦海一片空白","examples":[{"en":"I had shaking hands and a blank mind.","zh":"我雙手顫抖，腦海一片空白。"},{"en":"A blank mind means being unable to think, remember, or speak because of pressure.","zh":"腦海一片空白，是指因壓力而無法思考、記起或說話。"},{"en":"A student may have a blank mind when a teacher suddenly asks a difficult question.","zh":"當老師突然問一條困難問題時，學生可能腦海一片空白。"},{"en":"Fear can create a blank mind even when the person has studied.","zh":"即使一個人已經溫習，恐懼仍可能令其腦海一片空白。"},{"en":"This phrase describes the mental effect of strong nervousness.","zh":"這個短語描述強烈緊張帶來的心理影響。"}],"source":"2016 Q8.pdf","sourcePage":5},{"front":"not the presentation itself","meaning":"不是匯報本身","examples":[{"en":"It was not the presentation itself that defeated me.","zh":"擊敗我的不是匯報本身。"},{"en":"Not the presentation itself means the real problem was not the task, but something behind it.","zh":"不是匯報本身，是指真正問題不是任務，而是任務背後的東西。"},{"en":"It was not the exam itself that scared her, but the fear of disappointing her family.","zh":"令她害怕的不是考試本身，而是令家人失望的恐懼。"},{"en":"This phrase helps separate the visible task from the hidden fear.","zh":"這個短語幫助把表面任務與隱藏恐懼分開。"},{"en":"It shows that understanding the real cause matters.","zh":"它顯示理解真正原因很重要。"}],"source":"2016 Q8.pdf","sourcePage":5},{"front":"defeat me","meaning":"擊敗我","examples":[{"en":"My refusal to face fear defeated me.","zh":"我拒絕面對恐懼這件事擊敗了我。"},{"en":"To defeat me means to overcome me or make me fail.","zh":"擊敗我是指戰勝我或令我失敗。"},{"en":"The difficult song did not defeat her; lack of practice did.","zh":"擊敗她的不是那首困難歌曲，而是缺乏練習。"},{"en":"Fear can defeat a student when it stops them from preparing.","zh":"當恐懼阻止學生準備時，它就可能擊敗學生。"},{"en":"This phrase shows that failure can come from avoidance, not only difficulty.","zh":"這個短語顯示失敗可以來自逃避，而不只是困難。"}],"source":"2016 Q8.pdf","sourcePage":6},{"front":"the fear behind it","meaning":"背後的恐懼","examples":[{"en":"I had refused to face the fear behind the presentation.","zh":"我拒絕面對匯報背後的恐懼。"},{"en":"The fear behind it means the hidden worry that lies beneath a visible task or problem.","zh":"背後的恐懼，是指藏在表面任務或問題之下的憂慮。"},{"en":"The fear behind a test may be the fear of being judged as lazy or stupid.","zh":"測驗背後的恐懼可能是害怕被評價為懶惰或愚蠢。"},{"en":"Finding the fear behind a problem helps people choose the right solution.","zh":"找出問題背後的恐懼，能幫助人選擇正確解決方法。"},{"en":"This phrase looks below the surface of a challenge.","zh":"這個短語看見挑戰表面以下的東西。"}],"source":"2016 Q8.pdf","sourcePage":6},{"front":"after that failure","meaning":"那次失敗之後","examples":[{"en":"After that failure, my teacher asked what I was afraid of.","zh":"那次失敗之後，老師問我害怕甚麼。"},{"en":"After that failure means following the unsuccessful experience just mentioned.","zh":"那次失敗之後，是指在剛才提到的不成功經歷之後。"},{"en":"After that failure, the student stopped guessing and asked how to improve.","zh":"那次失敗之後，學生停止猜測，並詢問如何改善。"},{"en":"This phrase shows that failure can become the beginning of learning.","zh":"這個短語顯示失敗可以成為學習的開始。"},{"en":"It helps connect a painful event with a later lesson.","zh":"它幫助把痛苦事件與之後的教訓連接起來。"}],"source":"2016 Q8.pdf","sourcePage":6},{"front":"what exactly","meaning":"到底甚麼","examples":[{"en":"What exactly are you afraid of?","zh":"你到底害怕甚麼？"},{"en":"What exactly asks for a clear and specific answer, not a vague one.","zh":"到底甚麼，是要求清楚而具體的答案，而不是含糊答案。"},{"en":"A teacher may ask, “What exactly confuses you in this question?”","zh":"老師可能問：「這條題目到底哪裡令你困惑？」"},{"en":"This phrase helps people move from general fear to a precise problem.","zh":"這個短語幫助人由籠統恐懼轉向精確問題。"},{"en":"It is useful when someone needs to think more deeply.","zh":"當某人需要更深入思考時，它很有用。"}],"source":"2016 Q8.pdf","sourcePage":6},{"front":"force someone to","meaning":"迫使某人","examples":[{"en":"That question forced me to separate the problem into smaller parts.","zh":"那個問題迫使我把問題拆成較小部分。"},{"en":"To force someone to do something means to make them do it, often because there is no easy way to avoid it.","zh":"迫使某人做某事，是指令他們去做，通常因為沒有容易逃避的方法。"},{"en":"A failed exam may force a student to rethink their study method.","zh":"一次考試失敗可能迫使學生重新思考學習方法。"},{"en":"A direct question can force someone to face a truth they have avoided.","zh":"直接問題可以迫使某人面對一直逃避的真相。"},{"en":"This phrase shows pressure that leads to necessary action.","zh":"這個短語顯示導向必要行動的壓力。"}],"source":"2016 Q8.pdf","sourcePage":6},{"front":"separate the problem into smaller parts","meaning":"把問題拆成較小部分","examples":[{"en":"The question forced me to separate the problem into smaller parts.","zh":"那個問題迫使我把問題拆成較小部分。"},{"en":"To separate the problem into smaller parts means to divide a large difficulty into clearer, more manageable pieces.","zh":"把問題拆成較小部分，是指把一個大困難分成更清楚、較易處理的部分。"},{"en":"A student may separate exam stress into time management, weak topics, and sleep problems.","zh":"學生可以把考試壓力拆成時間管理、薄弱課題和睡眠問題。"},{"en":"Smaller parts are easier to improve than one huge, confusing fear.","zh":"較小部分比一個巨大而混亂的恐懼更容易改善。"},{"en":"This phrase shows a practical method for coping.","zh":"這個短語顯示一種實際應對方法。"}],"source":"2016 Q8.pdf","sourcePage":6},{"front":"eye contact","meaning":"眼神接觸","examples":[{"en":"Eye contact was one part of the problem.","zh":"眼神接觸是問題的一部分。"},{"en":"Eye contact means looking at another person’s eyes while speaking or listening.","zh":"眼神接觸是指說話或聆聽時看着對方的眼睛。"},{"en":"In a presentation, eye contact can help the speaker connect with the audience.","zh":"在匯報中，眼神接觸可以幫助講者與觀眾建立連繫。"},{"en":"Some students avoid eye contact because it makes them feel judged.","zh":"有些學生避免眼神接觸，因為這令他們感覺被評價。"},{"en":"Practising eye contact slowly can make public speaking less frightening.","zh":"慢慢練習眼神接觸，可以令公開演說沒那麼可怕。"}],"source":"2016 Q8.pdf","sourcePage":6},{"front":"nervousness","meaning":"緊張","examples":[{"en":"Nervousness was one of the problems I had to manage.","zh":"緊張是我需要管理的問題之一。"},{"en":"Nervousness is the worried or uneasy feeling people have before something difficult or important.","zh":"緊張是人在困難或重要事情前感到擔心或不安的感覺。"},{"en":"A student may feel nervousness before an interview, exam, or performance.","zh":"學生在面試、考試或表演前可能感到緊張。"},{"en":"Nervousness can affect breathing, voice, hands, and concentration.","zh":"緊張會影響呼吸、聲音、雙手和專注力。"},{"en":"This feeling is normal, but it becomes easier to manage with preparation.","zh":"這種感覺很正常，但透過準備會更容易管理。"}],"source":"2016 Q8.pdf","sourcePage":6},{"front":"step by step","meaning":"一步一步地","examples":[{"en":"Step by step, I practised in more manageable ways.","zh":"一步一步地，我用更容易管理的方法練習。"},{"en":"Step by step means slowly, one stage at a time.","zh":"一步一步地，是指慢慢地，一個階段接一個階段。"},{"en":"A student can prepare for a speech step by step by writing notes, practising aloud, and speaking to friends.","zh":"學生可以透過寫筆記、朗讀練習和向朋友演講，一步一步準備演講。"},{"en":"Step-by-step practice makes a large fear feel less overwhelming.","zh":"一步一步練習令巨大的恐懼沒那麼難承受。"},{"en":"This phrase shows gradual progress rather than sudden success.","zh":"這個短語顯示漸進進步，而不是突然成功。"}],"source":"2016 Q8.pdf","sourcePage":6},{"front":"record my voice","meaning":"錄下自己的聲音","examples":[{"en":"I recorded my voice to practise the presentation.","zh":"我錄下自己的聲音來練習匯報。"},{"en":"To record my voice means to use a device to save the sound of myself speaking.","zh":"錄下自己的聲音，是指用裝置保存自己說話的聲音。"},{"en":"A student may record their voice to check pronunciation, speed, and clarity.","zh":"學生可能錄下自己的聲音，以檢查發音、速度和清晰度。"},{"en":"Recording your voice can feel uncomfortable at first, but it gives useful evidence.","zh":"錄下自己的聲音一開始可能令人不舒服，但它提供有用證據。"},{"en":"This method helps speakers hear problems they may not notice while speaking.","zh":"這個方法幫助講者聽見自己說話時未必注意到的問題。"}],"source":"2016 Q8.pdf","sourcePage":6},{"front":"practise in an empty classroom","meaning":"在空課室練習","examples":[{"en":"I practised in an empty classroom.","zh":"我在空課室練習。"},{"en":"To practise in an empty classroom means to rehearse in a classroom with no audience.","zh":"在空課室練習，是指在沒有觀眾的課室中排練。"},{"en":"A nervous speaker may practise in an empty classroom before speaking to classmates.","zh":"緊張的講者可能先在空課室練習，然後才向同學演講。"},{"en":"This practice reduces fear by making the room feel familiar.","zh":"這種練習透過令房間變得熟悉來減少恐懼。"},{"en":"It is a safe first step before facing a real audience.","zh":"在面對真正觀眾前，這是一個安全的第一步。"}],"source":"2016 Q8.pdf","sourcePage":7},{"front":"close friends","meaning":"親密朋友；好友","examples":[{"en":"I asked two close friends to listen to me.","zh":"我請兩位好友聽我練習。"},{"en":"Close friends are friends who know you well and can be trusted.","zh":"親密朋友是很了解你並可以信任的朋友。"},{"en":"A student may practise a speech in front of close friends before presenting to the whole class.","zh":"學生可能先在好友面前練習演講，再向全班匯報。"},{"en":"Close friends can give honest feedback without making the speaker feel unsafe.","zh":"親密朋友可以給予誠實回饋，而不令講者感到不安全。"},{"en":"This phrase shows support from people who feel familiar and kind.","zh":"這個短語顯示來自熟悉和友善的人的支援。"}],"source":"2016 Q8.pdf","sourcePage":7},{"front":"listen to me","meaning":"聽我練習","examples":[{"en":"I asked two close friends to listen to me.","zh":"我請兩位好友聽我練習。"},{"en":"To listen to me means to pay attention while I speak or practise.","zh":"聽我練習，是指在我說話或練習時留心聆聽。"},{"en":"A student may ask friends to listen to him so he can test whether his speech is clear.","zh":"學生可能請朋友聽他練習，以測試演講是否清楚。"},{"en":"Having someone listen can make practice feel more realistic.","zh":"有人聆聽可以令練習感覺更真實。"},{"en":"This phrase shows that feedback often begins with a willing audience.","zh":"這個短語顯示回饋常由願意聆聽的觀眾開始。"}],"source":"2016 Q8.pdf","sourcePage":7},{"front":"slowly but surely","meaning":"慢慢但穩定地","examples":[{"en":"Slowly but surely, the fear became less mysterious.","zh":"慢慢但穩定地，恐懼變得不再那麼神秘。"},{"en":"Slowly but surely means progress happens gradually but steadily.","zh":"慢慢但穩定地，是指進步逐漸但穩定地發生。"},{"en":"Slowly but surely, a shy student becomes more comfortable speaking in class.","zh":"慢慢但穩定地，害羞的學生在課堂說話時變得更自在。"},{"en":"This phrase gives hope when improvement is not immediate.","zh":"當進步不是立即出現時，這個短語帶來希望。"},{"en":"It shows that small repeated steps can still lead somewhere.","zh":"它顯示小而重複的步驟仍可以帶來成果。"}],"source":"2016 Q8.pdf","sourcePage":7},{"front":"become less mysterious","meaning":"變得不再那麼神秘","examples":[{"en":"The fear became less mysterious after I faced it.","zh":"我面對恐懼後，它變得不再那麼神秘。"},{"en":"Become less mysterious means become clearer, more understandable, and less frightening.","zh":"變得不再那麼神秘，是指變得更清楚、更容易理解和較不嚇人。"},{"en":"A difficult subject becomes less mysterious when a teacher explains it step by step.","zh":"當老師一步一步解釋時，困難科目會變得不再那麼神秘。"},{"en":"Fear becomes less mysterious when we know exactly what triggers it.","zh":"當我們知道到底甚麼觸發恐懼時，恐懼就變得不再那麼神秘。"},{"en":"This phrase shows how understanding reduces fear.","zh":"這個短語顯示理解如何減少恐懼。"}],"source":"2016 Q8.pdf","sourcePage":7},{"front":"vanish overnight","meaning":"一夜之間消失","examples":[{"en":"The fear did not vanish overnight.","zh":"恐懼沒有一夜之間消失。"},{"en":"To vanish overnight means to disappear suddenly and completely in a very short time.","zh":"一夜之間消失，是指在很短時間內突然完全消失。"},{"en":"Confidence does not vanish overnight, and fear does not vanish overnight either.","zh":"信心不會一夜之間消失，恐懼也不會一夜之間消失。"},{"en":"A problem may improve slowly even if it does not vanish overnight.","zh":"即使問題沒有一夜之間消失，它仍可能慢慢改善。"},{"en":"This phrase reminds readers to expect gradual progress.","zh":"這個短語提醒讀者預期漸進進步。"}],"source":"2016 Q8.pdf","sourcePage":7},{"front":"no longer controlled me","meaning":"不再控制我","examples":[{"en":"The fear no longer controlled me.","zh":"恐懼不再控制我。"},{"en":"No longer controlled me means it still existed but did not decide my actions anymore.","zh":"不再控制我，是指它仍然存在，但不再決定我的行動。"},{"en":"A student may still feel nervous, but nervousness no longer controls them if they can continue speaking.","zh":"學生可能仍感到緊張，但如果仍能繼續說話，緊張就不再控制他。"},{"en":"Fear loses power when it no longer controls choices and behaviour.","zh":"當恐懼不再控制選擇和行為時，它就會失去力量。"},{"en":"This phrase shows freedom from being ruled by fear.","zh":"這個短語顯示不再被恐懼支配的自由。"}],"source":"2016 Q8.pdf","sourcePage":7},{"front":"moreover","meaning":"此外","examples":[{"en":"Moreover, coping with challenges teaches us what courage really means.","zh":"此外，應對挑戰教會我們勇氣真正的意思。"},{"en":"Moreover is used to add another important point to an argument.","zh":"此外用來為論點加入另一個重要觀點。"},{"en":"Facing fear helps us grow; moreover, it teaches us empathy for others.","zh":"面對恐懼幫助我們成長；此外，它教會我們對別人有同理心。"},{"en":"Writers use moreover when the next point strengthens the previous one.","zh":"當下一點加強前一點時，作者會使用「此外」。"},{"en":"This word helps an essay sound organised and logical.","zh":"這個詞幫助文章聽起來有組織和合邏輯。"}],"source":"2016 Q8.pdf","sourcePage":7},{"front":"coping with challenges","meaning":"應對挑戰","examples":[{"en":"Coping with challenges teaches us courage.","zh":"應對挑戰教會我們勇氣。"},{"en":"Coping with challenges means dealing with difficulties in practical and steady ways.","zh":"應對挑戰是指以實際而穩定的方法處理困難。"},{"en":"Students cope with challenges when they ask for help, practise, and try again after failure.","zh":"當學生求助、練習並在失敗後再次嘗試時，他們就是在應對挑戰。"},{"en":"Coping with challenges builds confidence because people learn they can survive difficulty.","zh":"應對挑戰能建立信心，因為人們學會自己能渡過困難。"},{"en":"This phrase focuses on handling problems rather than avoiding them.","zh":"這個短語著重處理問題，而不是逃避問題。"}],"source":"2016 Q8.pdf","sourcePage":7},{"front":"courage is not the absence of fear","meaning":"勇氣並不是沒有恐懼","examples":[{"en":"Courage is not the absence of fear.","zh":"勇氣並不是沒有恐懼。"},{"en":"Courage is not the absence of fear means brave people can still feel afraid.","zh":"勇氣並不是沒有恐懼，是指勇敢的人仍可以感到害怕。"},{"en":"A student who speaks while nervous shows courage because fear is present but not in control.","zh":"緊張仍然上台說話的學生顯示勇氣，因為恐懼存在但沒有控制他。"},{"en":"This idea corrects the mistaken belief that courage means feeling nothing.","zh":"這個想法修正「勇氣等於沒有感覺」的錯誤信念。"},{"en":"It helps people act even when fear has not disappeared.","zh":"它幫助人在恐懼未消失時仍然行動。"}],"source":"2016 Q8.pdf","sourcePage":7},{"front":"the ability to act despite it","meaning":"即使害怕仍能行動的能力","examples":[{"en":"Courage is the ability to act despite fear.","zh":"勇氣是即使害怕仍能行動的能力。"},{"en":"The ability to act despite it means being able to do what is needed even though fear is present.","zh":"即使害怕仍能行動的能力，是指即使恐懼存在，仍能做需要做的事。"},{"en":"A student shows this ability when she enters the competition even with a trembling voice.","zh":"當學生即使聲音顫抖仍參加比賽時，她就顯示這種能力。"},{"en":"Acting despite fear builds confidence because the person learns fear is survivable.","zh":"即使害怕仍行動能建立信心，因為人學會恐懼是可以承受的。"},{"en":"This phrase defines courage as action, not comfort.","zh":"這個短語把勇氣定義為行動，而不是舒服。"}],"source":"2016 Q8.pdf","sourcePage":8},{"front":"imagine that","meaning":"以為；想像","examples":[{"en":"Many people imagine that facing fear means acting recklessly.","zh":"很多人以為面對恐懼就是魯莽行動。"},{"en":"Imagine that means believe or picture something, sometimes wrongly.","zh":"以為是指相信或想像某事，有時可能是錯的。"},{"en":"Some students imagine that asking for help will make them look weak.","zh":"有些學生以為求助會令自己看起來軟弱。"},{"en":"Writers use imagine that to introduce a common but possibly mistaken idea.","zh":"作者使用「以為」來引出一個常見但可能錯誤的想法。"},{"en":"This phrase prepares readers for correction or explanation.","zh":"這個短語為修正或解釋作準備。"}],"source":"2016 Q8.pdf","sourcePage":8},{"front":"facing fear","meaning":"面對恐懼","examples":[{"en":"Facing fear does not mean throwing oneself into pain recklessly.","zh":"面對恐懼並不代表魯莽地讓自己投進痛苦之中。"},{"en":"Facing fear means dealing with what frightens you in a careful and honest way.","zh":"面對恐懼是指以謹慎和誠實的方式處理令你害怕的事。"},{"en":"A student faces fear by practising a speech gradually, not by forcing themselves into panic.","zh":"學生透過逐步練習演講來面對恐懼，而不是逼自己陷入恐慌。"},{"en":"Facing fear can involve planning, support, and small steps.","zh":"面對恐懼可以包括計劃、支援和小步驟。"},{"en":"This phrase shows courage guided by wisdom.","zh":"這個短語顯示由智慧引導的勇氣。"}],"source":"2016 Q8.pdf","sourcePage":8},{"front":"throw oneself into pain","meaning":"讓自己投進痛苦之中","examples":[{"en":"Facing fear does not mean throwing oneself into pain.","zh":"面對恐懼並不代表讓自己投進痛苦之中。"},{"en":"To throw oneself into pain means to enter a painful situation carelessly or without protection.","zh":"讓自己投進痛苦之中，是指粗心或沒有保護地進入痛苦情況。"},{"en":"A student should not throw themselves into a huge speech before learning smaller practice steps.","zh":"學生不應在未學會較小練習步驟前，就讓自己投進大型演講之中。"},{"en":"Courage is different from throwing oneself into unnecessary harm.","zh":"勇氣不同於讓自己承受不必要的傷害。"},{"en":"This phrase warns against confusing bravery with recklessness.","zh":"這個短語警告人不要把勇敢與魯莽混淆。"}],"source":"2016 Q8.pdf","sourcePage":8},{"front":"recklessly","meaning":"魯莽地","examples":[{"en":"We should not throw ourselves into pain recklessly.","zh":"我們不應魯莽地讓自己投進痛苦之中。"},{"en":"Recklessly means without enough care, thought, or concern for danger.","zh":"魯莽地是指沒有足夠小心、思考或對危險的顧慮。"},{"en":"A student acts recklessly if he joins a competition without any preparation just to prove courage.","zh":"如果學生毫無準備地參加比賽，只為證明勇氣，他就是魯莽地行動。"},{"en":"Facing fear recklessly can create more harm than growth.","zh":"魯莽地面對恐懼可能造成比成長更多的傷害。"},{"en":"This word describes action that is brave-looking but unwise.","zh":"這個詞描述看似勇敢但不明智的行動。"}],"source":"2016 Q8.pdf","sourcePage":8},{"front":"to acknowledge fear is not to worship it","meaning":"承認恐懼並不是崇拜恐懼","examples":[{"en":"To acknowledge fear is not to worship it.","zh":"承認恐懼並不是崇拜恐懼。"},{"en":"To acknowledge fear is not to worship it means admitting fear does not mean letting fear become your master.","zh":"承認恐懼並不是崇拜恐懼，是指承認恐懼不代表讓恐懼成為你的主人。"},{"en":"A student can admit nervousness without treating it as a reason to give up.","zh":"學生可以承認緊張，而不把它視為放棄的理由。"},{"en":"This phrase separates honest awareness from unhealthy obsession.","zh":"這個短語把誠實覺察與不健康沉迷分開。"},{"en":"It shows that naming fear is a step toward control, not surrender.","zh":"它顯示說出恐懼是走向控制的一步，而不是投降。"}],"source":"2016 Q8.pdf","sourcePage":8},{"front":"worship it","meaning":"崇拜它","examples":[{"en":"Acknowledging fear is not the same as worshipping it.","zh":"承認恐懼並不等同於崇拜它。"},{"en":"To worship it means to give it too much importance or power.","zh":"崇拜它是指給它太多重要性或力量。"},{"en":"A student worships fear if every decision is made only to avoid embarrassment.","zh":"如果學生每個決定都只為避免尷尬，他就是在崇拜恐懼。"},{"en":"Naming fear is healthy, but worshipping it lets fear control your life.","zh":"說出恐懼是健康的，但崇拜恐懼會讓它控制你的生活。"},{"en":"This phrase warns against treating fear as more powerful than it really is.","zh":"這個短語警告人不要把恐懼看得比實際更強大。"}],"source":"2016 Q8.pdf","sourcePage":8},{"front":"suffer silently","meaning":"默默忍受","examples":[{"en":"Coping with fear is not the same as suffering silently.","zh":"應對恐懼並不等同於默默忍受。"},{"en":"To suffer silently means to endure pain or worry without telling anyone or seeking help.","zh":"默默忍受是指承受痛苦或憂慮，卻不告訴任何人或尋求幫助。"},{"en":"A student suffers silently when she hides anxiety and pretends everything is fine.","zh":"當學生隱藏焦慮並假裝一切沒事時，她就是在默默忍受。"},{"en":"Suffering silently can make problems worse because no one knows support is needed.","zh":"默默忍受可能令問題更嚴重，因為沒有人知道需要支援。"},{"en":"This phrase shows why asking for help can be wise.","zh":"這個短語顯示為何求助可以是明智的。"}],"source":"2016 Q8.pdf","sourcePage":8},{"front":"prepare for","meaning":"為……作準備","examples":[{"en":"I prepared for my first public speech competition.","zh":"我為第一次公開演講比賽作準備。"},{"en":"To prepare for something means to get ready for it before it happens.","zh":"為某事作準備，是指在它發生前做好準備。"},{"en":"Students prepare for exams by revising, practising questions, and resting properly.","zh":"學生透過溫習、練習題目和好好休息為考試作準備。"},{"en":"Preparing for a challenge can reduce fear because the situation feels less unknown.","zh":"為挑戰作準備可以減少恐懼，因為情況感覺較不陌生。"},{"en":"This phrase connects planning with confidence.","zh":"這個短語把計劃與信心連接起來。"}],"source":"2016 Q8.pdf","sourcePage":8},{"front":"public speech competition","meaning":"公開演講比賽","examples":[{"en":"I felt anxious before my first public speech competition.","zh":"第一次公開演講比賽前，我感到焦慮。"},{"en":"A public speech competition is an event where people give speeches before judges and an audience.","zh":"公開演講比賽是參賽者在評判和觀眾面前演講的活動。"},{"en":"Students in a public speech competition may be judged on content, voice, confidence, and delivery.","zh":"公開演講比賽中的學生可能會根據內容、聲音、信心和表達來評分。"},{"en":"Such a competition can be frightening because the speaker is being watched carefully.","zh":"這類比賽可能令人害怕，因為講者被仔細觀看。"},{"en":"This phrase describes a formal speaking challenge.","zh":"這個短語描述一項正式說話挑戰。"}],"source":"2016 Q8.pdf","sourcePage":8},{"front":"so anxious that","meaning":"焦慮得……","examples":[{"en":"I felt so anxious that I could hardly sleep.","zh":"我焦慮得幾乎睡不着。"},{"en":"So anxious that shows fear or worry was strong enough to cause a result.","zh":"焦慮得……，顯示恐懼或憂慮強烈到造成某個結果。"},{"en":"She was so anxious that she checked her notes ten times before the exam.","zh":"她焦慮得在考試前檢查筆記十次。"},{"en":"This structure connects an intense feeling with what happened because of it.","zh":"這個句式把強烈感受與它造成的事情連接起來。"},{"en":"It helps readers understand the degree of anxiety.","zh":"它幫助讀者理解焦慮的程度。"}],"source":"2016 Q8.pdf","sourcePage":9},{"front":"could hardly sleep","meaning":"幾乎睡不着","examples":[{"en":"I felt so anxious that I could hardly sleep.","zh":"我焦慮得幾乎睡不着。"},{"en":"Could hardly sleep means was almost unable to sleep because of worry, excitement, or discomfort.","zh":"幾乎睡不着，是指因憂慮、興奮或不適而差不多無法入睡。"},{"en":"A student could hardly sleep before receiving important exam results.","zh":"學生在收到重要考試結果前，可能幾乎睡不着。"},{"en":"When worry keeps the mind busy, people can hardly sleep.","zh":"當憂慮令大腦不停運轉時，人可能幾乎睡不着。"},{"en":"This phrase shows how anxiety affects the body at night.","zh":"這個短語顯示焦慮如何在夜晚影響身體。"}],"source":"2016 Q8.pdf","sourcePage":9},{"front":"instead of pretending to be fine","meaning":"而不是假裝沒事","examples":[{"en":"Instead of pretending to be fine, I wrote down my worries.","zh":"我寫下自己的憂慮，而不是假裝沒事。"},{"en":"Instead of pretending to be fine means choosing honesty rather than acting as if nothing is wrong.","zh":"而不是假裝沒事，是指選擇誠實，而不是裝作沒有問題。"},{"en":"A student may ask for help instead of pretending to be fine before a difficult exam.","zh":"學生可以在困難考試前求助，而不是假裝沒事。"},{"en":"Pretending can hide the problem, but honesty creates a path to support.","zh":"假裝可能隱藏問題，但誠實能建立通往支援的路。"},{"en":"This phrase contrasts false calm with useful self-awareness.","zh":"這個短語把虛假的冷靜與有用的自我覺察作對比。"}],"source":"2016 Q8.pdf","sourcePage":9},{"front":"write down my worries","meaning":"寫下自己的憂慮","examples":[{"en":"I wrote down my worries before the competition.","zh":"我在比賽前寫下自己的憂慮。"},{"en":"To write down my worries means to put anxious thoughts onto paper or a screen.","zh":"寫下自己的憂慮，是指把焦慮的想法寫在紙上或螢幕上。"},{"en":"A student may write down worries such as forgetting lines or making mistakes.","zh":"學生可能寫下忘記台詞或犯錯等憂慮。"},{"en":"Writing worries down can make them clearer and easier to answer.","zh":"寫下憂慮可以令它們更清楚，也更容易回應。"},{"en":"This phrase shows a practical way to manage anxiety.","zh":"這個短語顯示管理焦慮的實際方法。"}],"source":"2016 Q8.pdf","sourcePage":9},{"front":"questions, not facts","meaning":"是問題，而不是事實","examples":[{"en":"Most of my worries were questions, not facts.","zh":"我大部分憂慮是問題，而不是事實。"},{"en":"Questions, not facts means the worries were uncertain possibilities, not proven truths.","zh":"是問題，而不是事實，意思是那些憂慮是不確定的可能性，而不是已證明的真相。"},{"en":"“What if I fail?” is a question, not a fact.","zh":"「如果我失敗怎麼辦？」是問題，而不是事實。"},{"en":"Seeing worries as questions helps students answer them more calmly.","zh":"把憂慮看成問題，能幫助學生更冷靜地回應。"},{"en":"This phrase separates fear from evidence.","zh":"這個短語把恐懼與證據分開。"}],"source":"2016 Q8.pdf","sourcePage":9},{"front":"what if","meaning":"如果……怎麼辦","examples":[{"en":"What if I forget my lines?","zh":"如果我忘記台詞怎麼辦？"},{"en":"What if introduces a possible situation that someone worries about or wants to consider.","zh":"如果……怎麼辦，用來引出某人擔心或想考慮的可能情況。"},{"en":"A student may ask, “What if I make a mistake during the presentation?”","zh":"學生可能問：「如果我在匯報中犯錯怎麼辦？」"},{"en":"What-if questions can help planning when they are answered calmly.","zh":"如果冷靜回答，「如果……怎麼辦」的問題可以幫助計劃。"},{"en":"They become harmful only when people repeat them without action.","zh":"只有當人反覆想而不行動時，它們才會有害。"}],"source":"2016 Q8.pdf","sourcePage":9},{"front":"forget my lines","meaning":"忘記台詞","examples":[{"en":"I worried that I might forget my lines.","zh":"我擔心自己可能忘記台詞。"},{"en":"To forget my lines means to fail to remember the words I need to say in a speech or performance.","zh":"忘記台詞，是指未能記起在演講或表演中需要說的話。"},{"en":"An actor may forget lines when nervousness interrupts memory.","zh":"當緊張干擾記憶時，演員可能忘記台詞。"},{"en":"Practising opening sentences can reduce the fear of forgetting lines.","zh":"練習開首句可以減少忘記台詞的恐懼。"},{"en":"This phrase shows a common fear in speaking and performing.","zh":"這個短語顯示演講和表演中的常見恐懼。"}],"source":"2016 Q8.pdf","sourcePage":9},{"front":"look bored","meaning":"看起來感到沉悶","examples":[{"en":"I worried that the judges might look bored.","zh":"我擔心評判可能看起來感到沉悶。"},{"en":"To look bored means to seem uninterested through facial expression, posture, or behaviour.","zh":"看起來感到沉悶，是指透過表情、姿勢或行為顯得沒有興趣。"},{"en":"A speaker may panic if the audience looks bored during a presentation.","zh":"如果觀眾在匯報期間看起來感到沉悶，講者可能會慌張。"},{"en":"Judges may look serious, but that does not always mean they are bored.","zh":"評判可能看起來嚴肅，但不一定代表他們感到沉悶。"},{"en":"This phrase shows how performers can fear other people’s reactions.","zh":"這個短語顯示表演者如何害怕別人的反應。"}],"source":"2016 Q8.pdf","sourcePage":9},{"front":"think I am ridiculous","meaning":"覺得我很可笑","examples":[{"en":"I worried that my classmates might think I was ridiculous.","zh":"我擔心同學可能覺得我很可笑。"},{"en":"To think I am ridiculous means to believe I look foolish, silly, or embarrassing.","zh":"覺得我很可笑，是指認為我看起來愚蠢、幼稚或尷尬。"},{"en":"A student may fear others will think they are ridiculous if their voice shakes.","zh":"如果聲音顫抖，學生可能害怕別人覺得自己很可笑。"},{"en":"This worry can stop people from trying even when others are not judging harshly.","zh":"即使別人沒有嚴厲評價，這種憂慮也可能阻止人嘗試。"},{"en":"The phrase shows fear of social embarrassment.","zh":"這個短語顯示對社交尷尬的恐懼。"}],"source":"2016 Q8.pdf","sourcePage":9},{"front":"see these thoughts on paper","meaning":"在紙上看見這些想法","examples":[{"en":"Once I saw these thoughts on paper, I could answer them rationally.","zh":"一旦我在紙上看見這些想法，就能理性地回應它們。"},{"en":"To see these thoughts on paper means to look at written worries instead of keeping them only in the mind.","zh":"在紙上看見這些想法，是指看着寫下來的憂慮，而不是只把它們留在腦中。"},{"en":"Seeing fears on paper can make them feel smaller and more organised.","zh":"在紙上看見恐懼，可以令它們感覺較小和更有條理。"},{"en":"A student can answer worries better when they are written clearly.","zh":"當憂慮被清楚寫下時，學生可以更好地回應。"},{"en":"This phrase shows how writing can turn anxiety into something examinable.","zh":"這個短語顯示寫作如何把焦慮變成可以審視的東西。"}],"source":"2016 Q8.pdf","sourcePage":9},{"front":"answer them rationally","meaning":"理性地回應它們","examples":[{"en":"I could answer my worries rationally.","zh":"我可以理性地回應自己的憂慮。"},{"en":"To answer them rationally means to respond with reason, evidence, and calm thinking.","zh":"理性地回應它們，是指用原因、證據和冷靜思考作回應。"},{"en":"A student answers fear rationally by asking, “What can I practise today?”","zh":"學生透過問「我今天可以練習甚麼？」來理性地回應恐懼。"},{"en":"Rational answers reduce panic because they replace vague fear with practical steps.","zh":"理性回應能減少恐慌，因為它以實際步驟取代含糊恐懼。"},{"en":"This phrase shows a calm way to deal with anxious thoughts.","zh":"這個短語顯示處理焦慮想法的冷靜方法。"}],"source":"2016 Q8.pdf","sourcePage":10},{"front":"divide the speech into","meaning":"把演講分成……","examples":[{"en":"I divided the speech into five sections.","zh":"我把演講分成五個部分。"},{"en":"To divide the speech into parts means to separate it into smaller organised sections.","zh":"把演講分成幾部分，是指把它拆成較小而有組織的段落。"},{"en":"A student may divide a speech into introduction, story, argument, example, and conclusion.","zh":"學生可能把演講分成引言、故事、論點、例子和結論。"},{"en":"Dividing a speech makes it easier to remember and practise.","zh":"把演講分段令它更容易記住和練習。"},{"en":"This phrase shows a practical strategy for reducing fear.","zh":"這個短語顯示減少恐懼的實際策略。"}],"source":"2016 Q8.pdf","sourcePage":10},{"front":"five sections","meaning":"五個部分","examples":[{"en":"I divided the speech into five sections.","zh":"我把演講分成五個部分。"},{"en":"Five sections are five separate parts of a larger piece of writing or speaking.","zh":"五個部分是較大寫作或說話內容中的五個獨立部分。"},{"en":"A speech with five sections may feel easier to manage than one long block.","zh":"有五個部分的演講可能比一整段長內容更容易處理。"},{"en":"Sections help speakers know where they are and what comes next.","zh":"分段幫助講者知道自己在哪裡，以及接下來是甚麼。"},{"en":"This phrase gives structure to a task that may feel overwhelming.","zh":"這個短語為可能令人不知所措的任務提供結構。"}],"source":"2016 Q8.pdf","sourcePage":10},{"front":"highlight the opening sentence","meaning":"標示開首句","examples":[{"en":"I highlighted the opening sentence of each part.","zh":"我標示每一部分的開首句。"},{"en":"To highlight the opening sentence means to mark the first sentence so it is easy to notice.","zh":"標示開首句，是指把第一句標記出來，方便注意。"},{"en":"A student may highlight opening sentences to remember how each section begins.","zh":"學生可能標示開首句，以記住每部分如何開始。"},{"en":"Highlighting key sentences can reduce panic during a speech.","zh":"標示關鍵句可以減少演講期間的恐慌。"},{"en":"This phrase shows a simple memory-support strategy.","zh":"這個短語顯示簡單的記憶支援策略。"}],"source":"2016 Q8.pdf","sourcePage":10},{"front":"opening sentence","meaning":"開首句","examples":[{"en":"I highlighted the opening sentence of each part.","zh":"我標示每一部分的開首句。"},{"en":"An opening sentence is the first sentence of a paragraph, section, speech, or piece of writing.","zh":"開首句是段落、部分、演講或文章的第一句。"},{"en":"A strong opening sentence tells the listener where the next idea begins.","zh":"有力的開首句會告訴聽眾下一個想法從哪裡開始。"},{"en":"In a speech, remembering the opening sentence can help the speaker continue smoothly.","zh":"在演講中，記住開首句可以幫助講者順利繼續。"},{"en":"This phrase shows how structure supports confidence.","zh":"這個短語顯示結構如何支援信心。"}],"source":"2016 Q8.pdf","sourcePage":10},{"front":"practise breathing slowly","meaning":"練習慢慢呼吸","examples":[{"en":"I practised breathing slowly before I began.","zh":"開始前，我練習慢慢呼吸。"},{"en":"To practise breathing slowly means to train yourself to take calm, controlled breaths.","zh":"練習慢慢呼吸，是指訓練自己作冷靜而受控制的呼吸。"},{"en":"A student may practise breathing slowly before entering an exam room.","zh":"學生進入試場前可能練習慢慢呼吸。"},{"en":"Slow breathing can help reduce shaking, rushing, and panic.","zh":"慢呼吸可以幫助減少顫抖、急促和恐慌。"},{"en":"This phrase shows a physical method for calming fear.","zh":"這個短語顯示平靜恐懼的身體方法。"}],"source":"2016 Q8.pdf","sourcePage":10},{"front":"on the day of the competition","meaning":"比賽當日","examples":[{"en":"On the day of the competition, my voice still trembled.","zh":"比賽當日，我的聲音仍然顫抖。"},{"en":"On the day of the competition means during the actual day when the event took place.","zh":"比賽當日，是指活動實際舉行的那一天。"},{"en":"On the day of the competition, a student may still feel nervous even after practising.","zh":"比賽當日，即使已經練習，學生仍可能感到緊張。"},{"en":"This phrase moves the story from preparation to the real event.","zh":"這個短語把故事由準備帶到真正事件。"},{"en":"It reminds readers that courage is tested in the moment of action.","zh":"它提醒讀者，勇氣是在行動的一刻被考驗的。"}],"source":"2016 Q8.pdf","sourcePage":10},{"front":"voice still trembled","meaning":"聲音仍然顫抖","examples":[{"en":"My voice still trembled during the speech.","zh":"演講期間，我的聲音仍然顫抖。"},{"en":"Voice still trembled means the speaker’s voice continued to shake because of nervousness or emotion.","zh":"聲音仍然顫抖，是指講者的聲音因緊張或情緒而繼續發抖。"},{"en":"A student’s voice may still tremble even after careful preparation.","zh":"即使仔細準備，學生的聲音仍然可能顫抖。"},{"en":"A trembling voice does not mean failure if the speaker continues.","zh":"如果講者繼續說下去，聲音顫抖並不代表失敗。"},{"en":"This phrase shows that courage can exist with visible fear.","zh":"這個短語顯示勇氣可以與可見恐懼並存。"}],"source":"2016 Q8.pdf","sourcePage":10},{"front":"nevertheless","meaning":"儘管如此","examples":[{"en":"Nevertheless, I completed the speech.","zh":"儘管如此，我完成了演講。"},{"en":"Nevertheless means despite what has just been said.","zh":"儘管如此，是指即使剛才所說的事情存在。"},{"en":"I was nervous; nevertheless, I walked onto the stage.","zh":"我很緊張；儘管如此，我仍走上舞台。"},{"en":"Writers use nevertheless to show that difficulty did not stop the action.","zh":"作者使用「儘管如此」來顯示困難沒有阻止行動。"},{"en":"This word helps emphasise persistence.","zh":"這個詞幫助強調堅持。"}],"source":"2016 Q8.pdf","sourcePage":10},{"front":"complete the speech","meaning":"完成演講","examples":[{"en":"I completed the speech despite my fear.","zh":"即使害怕，我仍完成演講。"},{"en":"To complete the speech means to finish giving the speech from beginning to end.","zh":"完成演講，是指由開始到結尾講完整篇演講。"},{"en":"A student completes a speech when they continue even after forgetting one word.","zh":"當學生即使忘記一個字仍繼續說下去時，他就是完成演講。"},{"en":"Completing the speech can become a victory even if the performance is imperfect.","zh":"即使表現不完美，完成演講也可以成為一次勝利。"},{"en":"This phrase values finishing the task despite difficulty.","zh":"這個短語重視在困難中完成任務。"}],"source":"2016 Q8.pdf","sourcePage":10},{"front":"walk away knowing that","meaning":"離開時明白","examples":[{"en":"I walked away knowing that fear could travel with me.","zh":"我離開時明白，恐懼可以與我同行。"},{"en":"Walk away knowing that means leave an experience with a new understanding.","zh":"離開時明白，是指從一段經歷離開時帶着新的理解。"},{"en":"A student may walk away knowing that mistakes do not destroy confidence.","zh":"學生可能離開時明白，錯誤不會摧毀信心。"},{"en":"This phrase shows that an event has taught the person something important.","zh":"這個短語顯示一件事教會了人重要道理。"},{"en":"It connects action with reflection.","zh":"它把行動與反思連接起來。"}],"source":"2016 Q8.pdf","sourcePage":11},{"front":"travel with me","meaning":"與我同行","examples":[{"en":"Fear could travel with me without controlling me.","zh":"恐懼可以與我同行，而不控制我。"},{"en":"Travel with me means stay present alongside me during an experience.","zh":"與我同行，是指在一段經歷中留在我身邊。"},{"en":"Nervousness may travel with a speaker onto the stage, but it does not have to stop the speech.","zh":"緊張可能與講者一起走上舞台，但不必阻止演講。"},{"en":"This phrase suggests that fear may remain but become less powerful.","zh":"這個短語表示恐懼可能仍存在，但變得較沒有力量。"},{"en":"It helps readers accept fear without surrendering to it.","zh":"它幫助讀者接受恐懼，而不向它投降。"}],"source":"2016 Q8.pdf","sourcePage":11},{"front":"drive the vehicle","meaning":"掌控方向；駕駛車輛","examples":[{"en":"Fear could travel with me without driving the vehicle.","zh":"恐懼可以與我同行，但不掌控方向。"},{"en":"To drive the vehicle means to control the direction of what happens.","zh":"掌控方向是指控制事情發展的方向。"},{"en":"Anxiety may sit in the car, but it should not drive the vehicle of your life.","zh":"焦慮可以坐在車上，但不應駕駛你人生的車輛。"},{"en":"This image shows the difference between feeling fear and letting fear decide.","zh":"這個意象顯示感到恐懼與讓恐懼作決定之間的分別。"},{"en":"It teaches that emotions can be present without being in charge.","zh":"它教我們，情緒可以存在，但不必掌權。"}],"source":"2016 Q8.pdf","sourcePage":11},{"front":"some may argue that","meaning":"有些人可能會認為","examples":[{"en":"Some may argue that focusing on difficulties makes people more negative.","zh":"有些人可能會認為，專注於困難會令人更負面。"},{"en":"Some may argue that introduces an opposing opinion that some people may hold.","zh":"有些人可能會認為……，用來引出一些人可能持有的相反意見。"},{"en":"Some may argue that students should ignore fear and simply work harder.","zh":"有些人可能會認為，學生應忽視恐懼並只需更努力。"},{"en":"Writers use this phrase before responding to another viewpoint.","zh":"作者在回應另一種觀點前會使用這個短語。"},{"en":"It helps an essay sound balanced and thoughtful.","zh":"它幫助文章聽起來平衡而有思想。"}],"source":"2016 Q8.pdf","sourcePage":11},{"front":"focus on difficulties","meaning":"專注於困難","examples":[{"en":"Focusing on difficulties does not always make people more negative.","zh":"專注於困難不一定會令人更負面。"},{"en":"To focus on difficulties means to pay attention to problems or challenges.","zh":"專注於困難，是指把注意力放在問題或挑戰上。"},{"en":"A student focuses on difficulties wisely when they identify weak topics before revising.","zh":"當學生在溫習前找出薄弱課題時，他就是明智地專注於困難。"},{"en":"Focusing on difficulties becomes harmful only when people stop looking for solutions.","zh":"只有當人們停止尋找解決方法時，專注於困難才會變得有害。"},{"en":"This phrase can describe either useful awareness or unhealthy worry, depending on context.","zh":"這個短語可以描述有用的覺察，也可以描述不健康的憂慮，視乎語境。"}],"source":"2016 Q8.pdf","sourcePage":11},{"front":"more negative","meaning":"更負面","examples":[{"en":"Some people worry that facing challenges makes us more negative.","zh":"有些人擔心面對挑戰會令我們更負面。"},{"en":"More negative means more focused on bad possibilities, problems, or hopeless feelings.","zh":"更負面是指更專注於壞的可能性、問題或無望感。"},{"en":"A student may become more negative if they repeat worries without taking action.","zh":"如果學生反覆想憂慮而不採取行動，可能會變得更負面。"},{"en":"Facing challenges carefully does not have to make people more negative.","zh":"小心地面對挑戰不一定會令人更負面。"},{"en":"This phrase describes a darker or less hopeful mindset.","zh":"這個短語描述較黑暗或較沒有希望的心態。"}],"source":"2016 Q8.pdf","sourcePage":11},{"front":"this view is understandable","meaning":"這種看法可以理解","examples":[{"en":"This view is understandable when excessive worry becomes unhealthy.","zh":"當過度憂慮變得不健康時，這種看法可以理解。"},{"en":"This view is understandable means the opinion has a reasonable cause, even if it is not fully correct.","zh":"這種看法可以理解，是指該意見有合理原因，即使未必完全正確。"},{"en":"It is understandable to fear failure when pressure from exams is very high.","zh":"當考試壓力很大時，害怕失敗是可以理解的。"},{"en":"Writers use this phrase to show respect for an opposing view before disagreeing.","zh":"作者使用這個短語，在不同意前先尊重相反觀點。"},{"en":"It helps discussion stay fair rather than dismissive.","zh":"它幫助討論保持公平，而不是輕視別人。"}],"source":"2016 Q8.pdf","sourcePage":11},{"front":"excessive worry","meaning":"過度憂慮","examples":[{"en":"Excessive worry can indeed become unhealthy.","zh":"過度憂慮確實可以變得不健康。"},{"en":"Excessive worry means worry that is too much, too constant, or beyond what the situation needs.","zh":"過度憂慮是指太多、太持續或超出情況所需的憂慮。"},{"en":"A student has excessive worry if they cannot sleep for weeks before a small quiz.","zh":"如果學生在一次小測前幾星期都睡不着，就是有過度憂慮。"},{"en":"Excessive worry can harm concentration, health, and daily life.","zh":"過度憂慮會傷害專注力、健康和日常生活。"},{"en":"This phrase warns that thinking about problems needs balance.","zh":"這個短語提醒我們，思考問題需要平衡。"}],"source":"2016 Q8.pdf","sourcePage":11},{"front":"indeed","meaning":"確實","examples":[{"en":"Excessive worry can indeed become unhealthy.","zh":"過度憂慮確實可以變得不健康。"},{"en":"Indeed is used to emphasise that something is truly the case.","zh":"確實用來強調某事真的是這樣。"},{"en":"Fear can indeed protect us when it makes us prepare carefully.","zh":"當恐懼令我們小心準備時，它確實可以保護我們。"},{"en":"Writers use indeed to strengthen or confirm a point.","zh":"作者使用「確實」來加強或確認一個觀點。"},{"en":"This word adds certainty to the sentence.","zh":"這個詞為句子加入確定感。"}],"source":"2016 Q8.pdf","sourcePage":11},{"front":"become unhealthy","meaning":"變得不健康","examples":[{"en":"Excessive worry can become unhealthy.","zh":"過度憂慮可以變得不健康。"},{"en":"Become unhealthy means develop into something harmful to the mind, body, or daily life.","zh":"變得不健康，是指發展成對心靈、身體或日常生活有害的東西。"},{"en":"Study pressure can become unhealthy when a student stops sleeping properly.","zh":"當學生停止好好睡覺時，學習壓力可能變得不健康。"},{"en":"Thinking about fear becomes unhealthy if it traps people instead of helping them act.","zh":"如果思考恐懼把人困住，而不是幫助人行動，它就會變得不健康。"},{"en":"This phrase shows a change from normal concern to harmful pressure.","zh":"這個短語顯示由正常關注變成有害壓力的轉變。"}],"source":"2016 Q8.pdf","sourcePage":11},{"front":"crucial difference between","meaning":"……之間的關鍵分別","examples":[{"en":"There is a crucial difference between acknowledging a challenge and dwelling on it.","zh":"承認挑戰與反覆糾結於挑戰之間有關鍵分別。"},{"en":"A crucial difference between two things is an important distinction that changes how we understand them.","zh":"兩者之間的關鍵分別，是指會改變我們理解方式的重要差異。"},{"en":"There is a crucial difference between preparing carefully and worrying endlessly.","zh":"仔細準備與無止境憂慮之間有關鍵分別。"},{"en":"Recognising this difference helps students face problems without becoming trapped by them.","zh":"認清這個分別能幫助學生面對問題，而不被問題困住。"},{"en":"This phrase is useful when two ideas look similar but are actually not the same.","zh":"當兩個想法看似相似但其實不同時，這個短語很有用。"}],"source":"2016 Q8.pdf","sourcePage":12},{"front":"dwell on","meaning":"反覆糾結於……","examples":[{"en":"Acknowledging a challenge is not the same as dwelling on it.","zh":"承認挑戰並不等同於反覆糾結於它。"},{"en":"To dwell on something means to think about it repeatedly in a way that keeps you stuck.","zh":"反覆糾結於某事，是指反覆想它，以致自己被困住。"},{"en":"A student dwells on one mistake if they replay it all night without learning from it.","zh":"如果學生整晚反覆回想一個錯誤，卻沒有從中學習，就是反覆糾結。"},{"en":"Dwelling on fear can increase anxiety instead of leading to action.","zh":"反覆糾結於恐懼可能增加焦慮，而不是導向行動。"},{"en":"This phrase warns against staying too long inside a problem.","zh":"這個短語提醒人不要在問題裡停留太久。"}],"source":"2016 Q8.pdf","sourcePage":12},{"front":"ignoring a fever","meaning":"忽視發燒","examples":[{"en":"Ignoring a fever does not heal the body.","zh":"忽視發燒不會治癒身體。"},{"en":"Ignoring a fever means pretending a high body temperature is not a problem.","zh":"忽視發燒，是指假裝高體溫不是問題。"},{"en":"A parent should not ignore a fever if a child is weak and uncomfortable.","zh":"如果孩子虛弱又不舒服，家長不應忽視發燒。"},{"en":"Ignoring a fever can delay treatment and make illness worse.","zh":"忽視發燒可能延誤治療，令疾病更嚴重。"},{"en":"This example compares physical illness with emotional problems.","zh":"這個例子把身體疾病與情緒問題作比較。"}],"source":"2016 Q8.pdf","sourcePage":12},{"front":"heal the body","meaning":"治癒身體","examples":[{"en":"Ignoring a fever does not heal the body.","zh":"忽視發燒不會治癒身體。"},{"en":"To heal the body means to help the body recover from illness, injury, or weakness.","zh":"治癒身體是指幫助身體從疾病、受傷或虛弱中恢復。"},{"en":"Rest, medicine, and care can help heal the body after sickness.","zh":"休息、藥物和照顧可以幫助身體在生病後復原。"},{"en":"The body cannot heal properly if signs of illness are ignored.","zh":"如果疾病徵象被忽視，身體無法好好復原。"},{"en":"This phrase shows that recovery needs attention, not denial.","zh":"這個短語顯示康復需要注意，而不是否認。"}],"source":"2016 Q8.pdf","sourcePage":12},{"front":"ignoring anxiety","meaning":"忽視焦慮","examples":[{"en":"Ignoring anxiety does not heal the mind.","zh":"忽視焦慮不會治癒心靈。"},{"en":"Ignoring anxiety means pretending worry, fear, or panic is not there.","zh":"忽視焦慮是指假裝憂慮、恐懼或恐慌不存在。"},{"en":"A student ignores anxiety when they say “I’m fine” but cannot sleep or concentrate.","zh":"當學生說「我沒事」但睡不着或不能專心時，他就是在忽視焦慮。"},{"en":"Ignoring anxiety can make it harder to seek help or find coping methods.","zh":"忽視焦慮可能令人更難求助或尋找應對方法。"},{"en":"This phrase treats emotional health as something that deserves attention.","zh":"這個短語把情緒健康視為值得注意的事情。"}],"source":"2016 Q8.pdf","sourcePage":12},{"front":"heal the mind","meaning":"治癒心靈","examples":[{"en":"Ignoring anxiety does not heal the mind.","zh":"忽視焦慮不會治癒心靈。"},{"en":"To heal the mind means to help thoughts and emotions recover from stress, fear, or pain.","zh":"治癒心靈是指幫助思想和情緒從壓力、恐懼或痛苦中恢復。"},{"en":"Talking to a trusted adult can help heal the mind after a frightening experience.","zh":"可怕經歷後，與可信任成人交談可以幫助治癒心靈。"},{"en":"The mind heals better when people name problems and receive support.","zh":"當人們說出問題並得到支援時，心靈會更好地復原。"},{"en":"This phrase connects emotional recovery with care and honesty.","zh":"這個短語把情緒復原與關懷和誠實連接起來。"}],"source":"2016 Q8.pdf","sourcePage":12},{"front":"do badly in","meaning":"在……表現差","examples":[{"en":"I did badly in a mock examination.","zh":"我在一次模擬考試中表現差。"},{"en":"To do badly in something means to perform poorly or get an unsatisfactory result.","zh":"在某事中表現差，是指表現不好或得到不理想結果。"},{"en":"A student may do badly in a test if they use the wrong study method.","zh":"如果學生使用錯誤學習方法，可能在測驗中表現差。"},{"en":"Doing badly once does not decide a person’s ability forever.","zh":"一次表現差不會永遠決定一個人的能力。"},{"en":"This phrase describes a result that can become a chance to improve.","zh":"這個短語描述一個可以變成改善機會的結果。"}],"source":"2016 Q8.pdf","sourcePage":12},{"front":"mock examination","meaning":"模擬考試","examples":[{"en":"I did badly in a mock examination in Form Five.","zh":"我在中五的一次模擬考試中表現差。"},{"en":"A mock examination is a practice exam that prepares students for a real public or final exam.","zh":"模擬考試是為真正公開試或期末考作準備的練習考試。"},{"en":"Students take mock examinations to test their knowledge, timing, and exam skills.","zh":"學生參加模擬考試，以測試知識、時間控制和應試技巧。"},{"en":"A poor mock examination result can reveal weak study habits before the real exam.","zh":"模擬考試成績差可以在真正考試前揭示薄弱學習習慣。"},{"en":"This phrase describes a serious but still useful practice test.","zh":"這個短語描述嚴肅但仍有用的練習考試。"}],"source":"2016 Q8.pdf","sourcePage":12},{"front":"protect my pride by","meaning":"透過……保護自尊","examples":[{"en":"I protected my pride by saying that the paper was unfair.","zh":"我透過說試卷不公平來保護自尊。"},{"en":"To protect my pride by doing something means to use that action to avoid feeling ashamed or wrong.","zh":"透過做某事保護自尊，是指用那個行動來避免感到羞愧或承認錯誤。"},{"en":"A student may protect their pride by blaming the teacher instead of reviewing mistakes.","zh":"學生可能透過責怪老師，而不是檢視錯誤來保護自尊。"},{"en":"Protecting pride can feel easier than admitting weakness, but it blocks improvement.","zh":"保護自尊可能比承認弱點容易，但會阻礙改善。"},{"en":"This phrase shows how self-defence can hide the real problem.","zh":"這個短語顯示自我防衛如何隱藏真正問題。"}],"source":"2016 Q8.pdf","sourcePage":12},{"front":"the paper was unfair","meaning":"試卷不公平","examples":[{"en":"I said that the paper was unfair to protect my pride.","zh":"我說試卷不公平來保護自尊。"},{"en":"The paper was unfair means the exam was not reasonable, balanced, or suitable.","zh":"試卷不公平，是指考試不合理、不平衡或不合適。"},{"en":"Sometimes an exam paper may be unfair if it tests material never taught in class.","zh":"如果試卷考核課堂從未教過的內容，它有時可能是不公平的。"},{"en":"However, saying the paper was unfair can also become an excuse for avoiding self-reflection.","zh":"然而，說試卷不公平也可能成為逃避自我反思的藉口。"},{"en":"This phrase can be a real complaint or a way to protect pride, depending on context.","zh":"這個短語可以是真實投訴，也可以是保護自尊的方法，視乎語境。"}],"source":"2016 Q8.pdf","sourcePage":12},{"front":"of course","meaning":"當然","examples":[{"en":"My marks, of course, did not improve.","zh":"我的分數當然沒有進步。"},{"en":"Of course means as expected or naturally, given the situation.","zh":"當然是指在這種情況下，結果如預期般自然發生。"},{"en":"If a student never changes their study method, of course the result may stay the same.","zh":"如果學生從不改變學習方法，成績當然可能保持不變。"},{"en":"Writers use of course to show that the outcome should not surprise readers.","zh":"作者使用「當然」來顯示結果不應令讀者驚訝。"},{"en":"This phrase can gently point out an obvious result.","zh":"這個短語可以溫和指出明顯結果。"}],"source":"2016 Q8.pdf","sourcePage":13},{"front":"only when I admitted that","meaning":"只有當我承認……時","examples":[{"en":"Only when I admitted that my study method was shallow did real progress begin.","zh":"只有當我承認自己的學習方法很浮淺時，真正的進步才開始。"},{"en":"Only when I admitted that means progress happened only after I accepted a difficult truth.","zh":"只有當我承認……時，是指只有在我接受一個困難真相後，進步才發生。"},{"en":"Only when I admitted that I needed help did my writing start to improve.","zh":"只有當我承認自己需要幫助時，我的寫作才開始改善。"},{"en":"This structure strongly emphasises the turning point in a story.","zh":"這個句式強烈強調故事中的轉捩點。"},{"en":"It shows that honesty can open the door to improvement.","zh":"它顯示誠實可以打開改善之門。"}],"source":"2016 Q8.pdf","sourcePage":13},{"front":"study method","meaning":"學習方法","examples":[{"en":"My study method was shallow.","zh":"我的學習方法很浮淺。"},{"en":"A study method is the way a student learns, reviews, practises, or remembers information.","zh":"學習方法是學生學習、複習、練習或記憶資料的方式。"},{"en":"Copying notes is one study method, but it may not be enough for deep understanding.","zh":"抄筆記是一種學習方法，但未必足以達到深入理解。"},{"en":"A better study method may include timed practice, error review, and explanation to others.","zh":"更好的學習方法可能包括限時練習、錯題檢討和向別人解釋。"},{"en":"This phrase helps students discuss how they learn, not only how long they study.","zh":"這個短語幫助學生討論如何學習，而不只是學習多久。"}],"source":"2016 Q8.pdf","sourcePage":13},{"front":"shallow","meaning":"浮淺的；不深入的","examples":[{"en":"I admitted that my study method was shallow.","zh":"我承認自己的學習方法很浮淺。"},{"en":"Shallow means not deep, serious, or thorough enough.","zh":"浮淺的是指不夠深入、認真或全面。"},{"en":"A shallow answer only repeats facts without explaining reasons.","zh":"浮淺的答案只重複事實，而不解釋原因。"},{"en":"Shallow revision may help students recognise words but not use ideas in new questions.","zh":"浮淺的溫習可能幫助學生認出詞語，但不能在新題目中使用概念。"},{"en":"This word shows that something looks like effort but lacks depth.","zh":"這個詞顯示某事看似努力，但缺乏深度。"}],"source":"2016 Q8.pdf","sourcePage":13},{"front":"real progress began","meaning":"真正的進步開始","examples":[{"en":"Real progress began when I changed my study method.","zh":"當我改變學習方法時，真正的進步開始了。"},{"en":"Real progress began means genuine improvement started to happen.","zh":"真正的進步開始，是指真正改善開始發生。"},{"en":"Real progress began after the student stopped blaming the exam and reviewed mistakes carefully.","zh":"當學生停止責怪考試並仔細檢討錯誤後，真正的進步開始了。"},{"en":"Progress becomes real when actions change, not only excuses.","zh":"當行動改變，而不只是藉口改變時，進步才是真正的。"},{"en":"This phrase marks the moment when improvement becomes visible.","zh":"這個短語標示改善開始變得可見的一刻。"}],"source":"2016 Q8.pdf","sourcePage":13},{"front":"copy notes mindlessly","meaning":"盲目抄筆記","examples":[{"en":"I stopped copying notes mindlessly.","zh":"我停止盲目抄筆記。"},{"en":"To copy notes mindlessly means to write notes again without thinking about their meaning.","zh":"盲目抄筆記是指不思考意思，只把筆記再寫一次。"},{"en":"A student copies notes mindlessly if they fill pages but cannot explain the ideas.","zh":"如果學生寫滿很多頁，卻不能解釋概念，他就是在盲目抄筆記。"},{"en":"Mindless copying feels productive but may not lead to understanding.","zh":"盲目抄寫感覺像有生產力，但未必帶來理解。"},{"en":"This phrase criticises study that has action but little thinking.","zh":"這個短語批評有行動但缺乏思考的學習。"}],"source":"2016 Q8.pdf","sourcePage":13},{"front":"timed practice","meaning":"限時練習","examples":[{"en":"I started doing timed practice after the mock examination.","zh":"模擬考試後，我開始做限時練習。"},{"en":"Timed practice means practising with a time limit, like in a real test or performance.","zh":"限時練習是指像真正考試或表演一樣，在時間限制下練習。"},{"en":"Students do timed practice to learn how quickly they can answer exam questions.","zh":"學生做限時練習，以學習自己可以多快回答考試題目。"},{"en":"Timed practice helps reveal whether knowledge can be used under pressure.","zh":"限時練習有助揭示知識能否在壓力下使用。"},{"en":"This phrase shows a practical way to prepare for real conditions.","zh":"這個短語顯示為真實情況作準備的實際方法。"}],"source":"2016 Q8.pdf","sourcePage":13},{"front":"discuss mistakes with","meaning":"與……討論錯誤","examples":[{"en":"I discussed mistakes with classmates.","zh":"我與同學討論錯誤。"},{"en":"To discuss mistakes with someone means to talk about errors together in order to understand and improve.","zh":"與某人討論錯誤，是指一起談論錯處，以便理解和改善。"},{"en":"Students discuss mistakes with classmates when they compare wrong answers and explain methods.","zh":"當學生比較錯誤答案並解釋方法時，就是與同學討論錯誤。"},{"en":"Discussing mistakes can reduce shame because everyone sees that errors are part of learning.","zh":"討論錯誤可以減少羞愧，因為每個人都看見錯誤是學習的一部分。"},{"en":"This phrase turns failure into shared problem-solving.","zh":"這個短語把失敗轉化成共同解決問題。"}],"source":"2016 Q8.pdf","sourcePage":13},{"front":"a trouble shared is a trouble halved","meaning":"困難有人分擔就減半","examples":[{"en":"A trouble shared was, in a very real sense, a trouble halved.","zh":"在很真實的意義上，困難有人分擔就減半。"},{"en":"A trouble shared is a trouble halved means a problem feels lighter when you talk about it with someone.","zh":"困難有人分擔就減半，是指當你與別人談論問題時，問題感覺會較輕。"},{"en":"A student’s exam fear may feel smaller after discussing it with a trusted friend.","zh":"學生與可信任朋友討論考試恐懼後，恐懼可能感覺較小。"},{"en":"Sharing trouble can bring advice, comfort, and a clearer plan.","zh":"分擔困難可以帶來建議、安慰和更清晰計劃。"},{"en":"This saying reminds us that silence often makes problems heavier.","zh":"這句話提醒我們，沉默常令問題更沉重。"}],"source":"2016 Q8.pdf","sourcePage":13},{"front":"in a very real sense","meaning":"在很真實的意義上","examples":[{"en":"A trouble shared was, in a very real sense, a trouble halved.","zh":"在很真實的意義上，困難有人分擔就減半。"},{"en":"In a very real sense means in a true, practical, and meaningful way.","zh":"在很真實的意義上，是指以真實、實際和有意義的方式。"},{"en":"In a very real sense, asking for help gave the student more courage.","zh":"在很真實的意義上，求助給了學生更多勇氣。"},{"en":"This phrase emphasises that the effect is not just poetic or imaginary.","zh":"這個短語強調效果不只是詩意或想像。"},{"en":"It helps writers show that an idea works in real life.","zh":"它幫助作者顯示一個想法在現實生活中有效。"}],"source":"2016 Q8.pdf","sourcePage":13},{"front":"remain","meaning":"仍然存在","examples":[{"en":"The challenge remained, but it became manageable.","zh":"挑戰仍然存在，但它變得可以處理。"},{"en":"To remain means to continue to exist or stay the same in some way.","zh":"仍然存在是指繼續存在，或在某方面保持不變。"},{"en":"The exam pressure remained, but the student felt more prepared.","zh":"考試壓力仍然存在，但學生感到準備更充足。"},{"en":"A problem may remain even after fear becomes easier to handle.","zh":"即使恐懼變得較容易處理，問題仍可能存在。"},{"en":"This word shows that improvement does not always mean complete disappearance.","zh":"這個詞顯示改善不一定代表完全消失。"}],"source":"2016 Q8.pdf","sourcePage":14},{"front":"work with","meaning":"可以處理；可以着手改善","examples":[{"en":"The challenge became something I could work with.","zh":"挑戰變成了我可以着手處理的東西。"},{"en":"To work with a problem means to handle it, adjust to it, or improve it step by step.","zh":"可以處理一個問題，是指一步一步應付、適應或改善它。"},{"en":"A student can work with nervousness by preparing notes and practising breathing.","zh":"學生可以透過準備筆記和練習呼吸來處理緊張。"},{"en":"When a problem becomes something you can work with, it no longer feels impossible.","zh":"當問題變成可以處理的東西時，它就不再感覺不可能。"},{"en":"This phrase shows practical cooperation with reality rather than denial.","zh":"這個短語顯示與現實作實際合作，而不是否認現實。"}],"source":"2016 Q8.pdf","sourcePage":14},{"front":"all in all","meaning":"總括而言","examples":[{"en":"All in all, acknowledging challenges is indispensable.","zh":"總括而言，承認挑戰是不可或缺的。"},{"en":"All in all introduces a final overall judgement after several points.","zh":"總括而言，是在提出幾點後引出整體最終判斷。"},{"en":"All in all, facing fear helps students understand themselves better.","zh":"總括而言，面對恐懼幫助學生更了解自己。"},{"en":"Writers use all in all to signal that the essay is reaching its conclusion.","zh":"作者使用「總括而言」來表示文章正走向結論。"},{"en":"This phrase helps summarise the main argument clearly.","zh":"這個短語幫助清楚總結主要論點。"}],"source":"2016 Q8.pdf","sourcePage":14},{"front":"not merely important","meaning":"不只是重要","examples":[{"en":"Acknowledging challenges is not merely important.","zh":"承認挑戰不只是重要。"},{"en":"Not merely important means more than just important; it is necessary or central.","zh":"不只是重要，是指不僅重要，而是必要或核心。"},{"en":"Sleep is not merely important for students; it is essential for memory and health.","zh":"睡眠對學生不只是重要；它對記憶和健康是必不可少的。"},{"en":"This phrase raises the strength of an argument.","zh":"這個短語提高論點的力度。"},{"en":"It tells readers that the issue should be taken very seriously.","zh":"它告訴讀者，這個議題應被非常認真看待。"}],"source":"2016 Q8.pdf","sourcePage":14},{"front":"indispensable","meaning":"不可或缺的","examples":[{"en":"Acknowledging challenges is indispensable for us.","zh":"承認挑戰對我們來說是不可或缺的。"},{"en":"Indispensable means so necessary that something cannot be done well without it.","zh":"不可或缺的是指非常必要，沒有它就不能好好完成某事。"},{"en":"Practice is indispensable for anyone preparing for a speech competition.","zh":"對準備演講比賽的人來說，練習是不可或缺的。"},{"en":"Honest feedback is indispensable when students want to improve their writing.","zh":"當學生想改善寫作時，誠實回饋是不可或缺的。"},{"en":"This word is stronger than important because it means cannot be left out.","zh":"這個詞比「重要」更強，因為它表示不能缺少。"}],"source":"2016 Q8.pdf","sourcePage":14},{"front":"gain power","meaning":"變得更有力量","examples":[{"en":"Fear gains power when it is hidden.","zh":"當恐懼被隱藏時，它會變得更有力量。"},{"en":"To gain power means to become stronger or more able to influence someone.","zh":"變得更有力量，是指變得更強或更能影響某人。"},{"en":"A worry gains power when a student repeats it silently instead of discussing it.","zh":"當學生默默反覆想一個憂慮，而不是討論它時，憂慮會變得更有力量。"},{"en":"Hidden fear can gain power because it feels vague and endless.","zh":"隱藏的恐懼可能變得更有力量，因為它感覺含糊又無盡。"},{"en":"This phrase shows how avoidance can strengthen a problem.","zh":"這個短語顯示逃避如何加強問題。"}],"source":"2016 Q8.pdf","sourcePage":14},{"front":"be hidden","meaning":"被隱藏","examples":[{"en":"Fear gains power when it is hidden.","zh":"當恐懼被隱藏時，它會變得更有力量。"},{"en":"To be hidden means to be kept out of sight or not spoken about.","zh":"被隱藏是指被藏起來或沒有被說出來。"},{"en":"A student’s anxiety may be hidden behind jokes and smiles.","zh":"學生的焦慮可能被隱藏在笑話和笑容背後。"},{"en":"When fear is hidden, teachers and friends may not know help is needed.","zh":"當恐懼被隱藏時，老師和朋友可能不知道有人需要幫助。"},{"en":"This phrase shows why silence can make emotional problems harder to handle.","zh":"這個短語顯示為何沉默會令情緒問題更難處理。"}],"source":"2016 Q8.pdf","sourcePage":14},{"front":"be exaggerated","meaning":"被誇大","examples":[{"en":"Fear gains power when it is exaggerated.","zh":"當恐懼被誇大時，它會變得更有力量。"},{"en":"To be exaggerated means to be made to seem larger, worse, or more serious than it really is.","zh":"被誇大是指被說得或想得比實際更大、更壞或更嚴重。"},{"en":"A student may exaggerate one mistake until it feels like total failure.","zh":"學生可能把一個錯誤誇大到感覺像徹底失敗。"},{"en":"Exaggerated fear can stop people from seeing realistic solutions.","zh":"被誇大的恐懼會阻止人看見實際解決方法。"},{"en":"This phrase shows how the mind can make problems look bigger.","zh":"這個短語顯示大腦如何令問題看起來更大。"}],"source":"2016 Q8.pdf","sourcePage":14},{"front":"be left unexplained","meaning":"未被解釋","examples":[{"en":"Fear gains power when it is left unexplained.","zh":"當恐懼未被解釋時，它會變得更有力量。"},{"en":"To be left unexplained means no one has clearly described, understood, or answered it.","zh":"未被解釋是指沒有人清楚描述、理解或回應它。"},{"en":"Anxiety about school may grow when the cause is left unexplained.","zh":"當原因未被解釋時，對學校的焦慮可能會增加。"},{"en":"An unexplained fear feels frightening because the person does not know where to begin.","zh":"未被解釋的恐懼令人害怕，因為人不知道從哪裡開始。"},{"en":"This phrase shows why explanation is part of healing.","zh":"這個短語顯示解釋是療癒的一部分。"}],"source":"2016 Q8.pdf","sourcePage":14},{"front":"lose power","meaning":"失去力量","examples":[{"en":"Fear loses power when it is named and examined.","zh":"當恐懼被說出並被審視時，它會失去力量。"},{"en":"To lose power means to become weaker or less able to control someone.","zh":"失去力量是指變得較弱或較不能控制某人。"},{"en":"A rumour loses power when facts are checked and shared.","zh":"當事實被查證和分享時，謠言會失去力量。"},{"en":"Fear loses power when students understand its source and plan a response.","zh":"當學生理解恐懼源頭並計劃回應時，恐懼會失去力量。"},{"en":"This phrase shows the effect of clarity and action.","zh":"這個短語顯示清晰和行動的效果。"}],"source":"2016 Q8.pdf","sourcePage":14},{"front":"be named and examined","meaning":"被說出並被審視","examples":[{"en":"Fear loses power when it is named and examined.","zh":"當恐懼被說出並被審視時，它會失去力量。"},{"en":"To be named and examined means to be clearly identified and looked at carefully.","zh":"被說出並被審視，是指被清楚辨認並仔細查看。"},{"en":"A fear of public speaking is named and examined when a student asks whether the real fear is forgetting lines or being judged.","zh":"當學生詢問真正恐懼是忘記台詞還是被評價時，公開演說恐懼就是被說出並被審視。"},{"en":"Named and examined problems are easier to solve than vague worries.","zh":"被說出並被審視的問題比含糊憂慮更容易解決。"},{"en":"This phrase shows a careful method for dealing with fear.","zh":"這個短語顯示處理恐懼的細心方法。"}],"source":"2016 Q8.pdf","sourcePage":15},{"front":"practical action","meaning":"實際行動","examples":[{"en":"Fear should be answered with practical action.","zh":"恐懼應以實際行動來回應。"},{"en":"Practical action means real steps that can be taken to improve a situation.","zh":"實際行動是指可以採取來改善情況的真實步驟。"},{"en":"If a student fears failing, practical action may include timed practice and asking questions.","zh":"如果學生害怕失敗，實際行動可以包括限時練習和提問。"},{"en":"Practical action turns worry into movement.","zh":"實際行動把憂慮變成前進。"},{"en":"This phrase shows that fear needs response, not just thought.","zh":"這個短語顯示恐懼需要回應，而不只是思考。"}],"source":"2016 Q8.pdf","sourcePage":15},{"front":"speak honestly about","meaning":"坦誠談論……","examples":[{"en":"Students should speak honestly about their struggles.","zh":"學生應坦誠談論自己的掙扎。"},{"en":"To speak honestly about something means to talk truthfully about it without pretending.","zh":"坦誠談論某事，是指真實地談論它，而不假裝。"},{"en":"A student speaks honestly about anxiety when they tell a teacher they feel overwhelmed.","zh":"當學生告訴老師自己感到不知所措時，就是坦誠談論焦慮。"},{"en":"Speaking honestly helps others understand what support is needed.","zh":"坦誠談論幫助別人理解需要甚麼支援。"},{"en":"This phrase values openness as a way to solve problems.","zh":"這個短語重視開放作為解決問題的方法。"}],"source":"2016 Q8.pdf","sourcePage":15},{"front":"struggles","meaning":"掙扎；困難","examples":[{"en":"Students should speak honestly about their struggles.","zh":"學生應坦誠談論自己的掙扎。"},{"en":"Struggles are difficulties, problems, or efforts that are hard to deal with.","zh":"掙扎是指難以處理的困難、問題或努力過程。"},{"en":"Student struggles may include exam pressure, friendship problems, or fear of failure.","zh":"學生的掙扎可能包括考試壓力、友誼問題或害怕失敗。"},{"en":"Talking about struggles can make them easier to understand and manage.","zh":"談論掙扎可以令它們更容易理解和管理。"},{"en":"This word reminds us that difficulty is part of growth.","zh":"這個詞提醒我們，困難是成長的一部分。"}],"source":"2016 Q8.pdf","sourcePage":15},{"front":"create an environment in which","meaning":"創造一個……的環境","examples":[{"en":"We should create an environment in which asking for help is seen as wisdom.","zh":"我們應創造一個把求助視為智慧的環境。"},{"en":"Create an environment in which means build conditions where a certain behaviour or value can exist.","zh":"創造一個……的環境，是指建立能讓某種行為或價值存在的條件。"},{"en":"Teachers can create an environment in which students feel safe to ask questions.","zh":"老師可以創造一個讓學生安心提問的環境。"},{"en":"Such an environment helps people admit problems before they become serious.","zh":"這樣的環境幫助人們在問題變嚴重前承認問題。"},{"en":"This phrase is useful when discussing culture, support, and shared behaviour.","zh":"討論文化、支援和共同習慣時，這個短語很有用。"}],"source":"2016 Q8.pdf","sourcePage":15},{"front":"asking for help","meaning":"求助","examples":[{"en":"Asking for help should be seen as wisdom.","zh":"求助應被視為智慧。"},{"en":"Asking for help means telling someone you need support, advice, or guidance.","zh":"求助是指告訴別人你需要支援、建議或指導。"},{"en":"A student asks for help when they cannot understand a topic after trying.","zh":"當學生嘗試後仍不明白課題時，他就是在求助。"},{"en":"Asking for help early can prevent a small difficulty from becoming a larger problem.","zh":"及早求助可以防止小困難變成大問題。"},{"en":"This phrase shows responsibility, not failure.","zh":"這個短語顯示責任感，而不是失敗。"}],"source":"2016 Q8.pdf","sourcePage":15},{"front":"be seen not as…, but as…","meaning":"不應被視為……而應被視為……","examples":[{"en":"Asking for help should be seen not as weakness, but as wisdom.","zh":"求助不應被視為軟弱，而應被視為智慧。"},{"en":"Be seen not as A, but as B means people should understand something in the second way, not the first.","zh":"不應被視為A，而應被視為B，是指人們應用第二種方式理解某事，而不是第一種。"},{"en":"Mistakes should be seen not as shame, but as information for improvement.","zh":"錯誤不應被視為羞恥，而應被視為改善的資訊。"},{"en":"This structure corrects a common misunderstanding by replacing it with a better view.","zh":"這個句式透過以更好看法取代錯誤看法，修正常見誤解。"},{"en":"It is useful when arguing for a change in attitude.","zh":"當論證態度需要改變時，這個句式很有用。"}],"source":"2016 Q8.pdf","sourcePage":15},{"front":"weakness","meaning":"軟弱","examples":[{"en":"Asking for help is not a weakness.","zh":"求助不是軟弱。"},{"en":"Weakness means a lack of strength, confidence, ability, or support in a certain area.","zh":"軟弱是指在某方面缺乏力量、信心、能力或支援。"},{"en":"Everyone has weaknesses, such as poor time management or fear of speaking.","zh":"每個人都有弱點，例如時間管理差或害怕說話。"},{"en":"Admitting weakness can be the first step toward becoming stronger.","zh":"承認弱點可以是變得更強的第一步。"},{"en":"This word does not have to mean failure; it can point to where growth is needed.","zh":"這個詞不一定代表失敗；它可以指出需要成長的地方。"}],"source":"2016 Q8.pdf","sourcePage":15},{"front":"wisdom","meaning":"智慧","examples":[{"en":"Asking for help can be a form of wisdom.","zh":"求助可以是一種智慧。"},{"en":"Wisdom means good judgement, deep understanding, and the ability to choose well.","zh":"智慧是指良好判斷、深入理解和作出好選擇的能力。"},{"en":"A student shows wisdom when they ask for advice before a problem becomes serious.","zh":"當學生在問題變嚴重前尋求建議時，就是顯示智慧。"},{"en":"Wisdom is not knowing everything; it is knowing when support is needed.","zh":"智慧不是知道所有事，而是知道何時需要支援。"},{"en":"This word presents help-seeking as mature and intelligent.","zh":"這個詞把求助呈現為成熟和明智。"}],"source":"2016 Q8.pdf","sourcePage":15},{"front":"contain storms","meaning":"充滿風暴；總有風雨","examples":[{"en":"Life will always contain storms.","zh":"人生總會有風雨。"},{"en":"Contain storms means include difficult, painful, or frightening periods.","zh":"充滿風暴是指包括困難、痛苦或令人害怕的時期。"},{"en":"A school year may contain storms such as exams, friendship problems, and family pressure.","zh":"一個學年可能有考試、友誼問題和家庭壓力等風雨。"},{"en":"Saying life contains storms reminds us that difficulty is normal, not unusual.","zh":"說人生總有風雨，提醒我們困難是正常的，而不是罕見的。"},{"en":"This phrase uses weather as an image for hardship.","zh":"這個短語用天氣作為困難的意象。"}],"source":"2016 Q8.pdf","sourcePage":15},{"front":"what matters is whether","meaning":"重要的是是否","examples":[{"en":"What matters is whether we face the storm with open eyes.","zh":"重要的是我們是否睜開眼睛面對風暴。"},{"en":"What matters is whether means the most important question is whether something happens or not.","zh":"重要的是是否……，意思是最重要的問題是某事是否發生。"},{"en":"What matters is whether students learn from failure, not whether they never fail.","zh":"重要的是學生是否從失敗中學習，而不是他們是否從不失敗。"},{"en":"This phrase shifts attention to the key issue.","zh":"這個短語把注意力轉向關鍵問題。"},{"en":"It helps writers separate what is important from what is less important.","zh":"它幫助作者分辨重要與較不重要的事情。"}],"source":"2016 Q8.pdf","sourcePage":16},{"front":"shut our eyes","meaning":"閉上眼睛","examples":[{"en":"We should not shut our eyes and sink.","zh":"我們不應閉上眼睛然後沉下去。"},{"en":"To shut our eyes means to refuse to see or face a problem.","zh":"閉上眼睛是指拒絕看見或面對問題。"},{"en":"A student shuts their eyes to a problem when they ignore failing marks until it is too late.","zh":"當學生忽視不合格成績直到太遲時，就是對問題閉上眼睛。"},{"en":"Shutting our eyes may feel safer for a moment, but it prevents action.","zh":"閉上眼睛可能一時感覺較安全，但會阻止行動。"},{"en":"This phrase uses a physical image to describe denial.","zh":"這個短語用身體意象描述否認。"}],"source":"2016 Q8.pdf","sourcePage":16},{"front":"sink","meaning":"沉下去","examples":[{"en":"If we ignore challenges, we may sink.","zh":"如果我們忽視挑戰，就可能沉下去。"},{"en":"To sink means to go down, fail, or become overwhelmed by difficulty.","zh":"沉下去是指下降、失敗或被困難壓垮。"},{"en":"A student may feel like sinking when stress becomes too heavy and no help is sought.","zh":"當壓力太重而沒有求助時，學生可能感覺像沉下去。"},{"en":"People are less likely to sink when they speak honestly and take practical action.","zh":"當人們坦誠說出問題並採取實際行動時，較不會沉下去。"},{"en":"This word creates an image of being pulled under by problems.","zh":"這個詞營造出被問題拖下去的意象。"}],"source":"2016 Q8.pdf","sourcePage":16},{"front":"steady ourselves","meaning":"穩住自己","examples":[{"en":"We should open our eyes and steady ourselves.","zh":"我們應睜開眼睛並穩住自己。"},{"en":"To steady ourselves means to calm and support ourselves so we can continue.","zh":"穩住自己是指令自己冷靜和有支撐，好讓自己能繼續。"},{"en":"Before a speech, a student may steady herself by breathing slowly and looking at her notes.","zh":"演講前，學生可能透過慢慢呼吸和看筆記來穩住自己。"},{"en":"Steadying ourselves helps us act even when fear is still present.","zh":"穩住自己能幫助我們在恐懼仍存在時行動。"},{"en":"This phrase suggests balance, control, and readiness.","zh":"這個短語表示平衡、控制和準備好。"}],"source":"2016 Q8.pdf","sourcePage":16},{"front":"walk through the rain","meaning":"走過風雨","examples":[{"en":"We can steady ourselves and walk through the rain.","zh":"我們可以穩住自己，然後走過風雨。"},{"en":"To walk through the rain means to continue through difficulty instead of avoiding it.","zh":"走過風雨是指繼續穿越困難，而不是逃避它。"},{"en":"A student walks through the rain when they face exam fear with practice and support.","zh":"當學生用練習和支援面對考試恐懼時，就是在走過風雨。"},{"en":"Walking through the rain does not mean the storm is pleasant; it means the person keeps going.","zh":"走過風雨不代表風暴令人愉快，而是代表人仍然繼續前行。"},{"en":"This phrase ends the essay with an image of courage and endurance.","zh":"這個短語以勇氣和忍耐的意象結束文章。"}],"source":"2016 Q8.pdf","sourcePage":16}],"dse/writing/part-b/2016/Q9":[{"front":"support my application to","meaning":"支持我申請……","examples":[{"en":"Please support my application to HKAPA.","zh":"請支持我申請香港演藝學院。"},{"en":"To support my application to a school means to agree with and encourage my decision to apply there.","zh":"支持我申請某學校，意思是同意並鼓勵我申請那裡的決定。"},{"en":"Parents may support a child’s application to a music school by helping with forms and practice.","zh":"父母可透過協助填表和練習來支持孩子申請音樂學校。"},{"en":"If you support my application to HKAPA, I will feel more confident before the deadline.","zh":"如果你們支持我申請香港演藝學院，我會在截止日期前更有信心。"},{"en":"This phrase asks for emotional support as well as practical approval.","zh":"這個片語請求情感上的支持，也請求實際上的認可。"}],"source":"2016 Q9.pdf","sourcePage":1},{"front":"HKAPA","meaning":"香港演藝學院","examples":[{"en":"I intend to apply to HKAPA.","zh":"我打算申請香港演藝學院。"},{"en":"HKAPA refers to the Hong Kong Academy for Performing Arts.","zh":"HKAPA 指香港演藝學院。"},{"en":"A student who wants professional theatre training may apply to HKAPA.","zh":"想接受專業戲劇訓練的學生可能會申請香港演藝學院。"},{"en":"HKAPA is suitable for students who are serious about acting, dance, music, or other performing arts.","zh":"香港演藝學院適合認真追求演戲、舞蹈、音樂或其他表演藝術的學生。"},{"en":"Mentioning HKAPA shows that the writer has a specific school and career direction in mind.","zh":"提到香港演藝學院，顯示作者已有明確學校和事業方向。"}],"source":"2016 Q9.pdf","sourcePage":1},{"front":"Dear Mum and Dad","meaning":"親愛的爸爸媽媽","examples":[{"en":"The email begins with Dear Mum and Dad.","zh":"這封電郵以「親愛的爸爸媽媽」開始。"},{"en":"Dear Mum and Dad is a warm but respectful opening for an email to parents.","zh":"Dear Mum and Dad 是寫給父母時溫暖而尊重的開首語。"},{"en":"A student may write “Dear Mum and Dad” before explaining an important decision.","zh":"學生在解釋重要決定前，可能會寫 “Dear Mum and Dad”。"},{"en":"This opening sounds personal because the writer is speaking to family, not strangers.","zh":"這個開首語聽起來親切，因為作者是在對家人說話，而不是對陌生人說話。"},{"en":"It prepares the reader for a sincere and emotional message.","zh":"它讓讀者準備閱讀一封真誠而帶感情的訊息。"}],"source":"2016 Q9.pdf","sourcePage":1},{"front":"I hope your trip is going well","meaning":"希望你們旅途順利","examples":[{"en":"I hope your trip is going well.","zh":"希望你們旅途順利。"},{"en":"This sentence politely shows care before the writer discusses the main issue.","zh":"這句話在作者討論主要事情前，有禮貌地表達關心。"},{"en":"A child may write this to parents who are travelling overseas.","zh":"孩子可能會對正在外遊的父母寫這句話。"},{"en":"It makes the email warmer because it asks about the parents’ situation first.","zh":"它令電郵更溫暖，因為作者先關心父母的情況。"},{"en":"This phrase is useful when beginning a personal email gently.","zh":"這個片語適合用來溫和地開始私人電郵。"}],"source":"2016 Q9.pdf","sourcePage":1},{"front":"application deadline","meaning":"申請截止日期","examples":[{"en":"The application deadline is drawing near.","zh":"申請截止日期逐漸迫近。"},{"en":"An application deadline is the final date by which an application must be submitted.","zh":"申請截止日期是必須提交申請的最後日期。"},{"en":"A student may feel pressure when the university application deadline is close.","zh":"當大學申請截止日期接近時，學生可能感到壓力。"},{"en":"Missing an application deadline can mean losing the chance to apply that year.","zh":"錯過申請截止日期，可能代表失去該年申請機會。"},{"en":"Clear planning is important when an application deadline is approaching.","zh":"當申請截止日期迫近時，清晰計劃很重要。"}],"source":"2016 Q9.pdf","sourcePage":1},{"front":"draw near","meaning":"逐漸迫近","examples":[{"en":"The application deadline is drawing near.","zh":"申請截止日期逐漸迫近。"},{"en":"Draw near means become closer in time.","zh":"draw near 意思是在時間上越來越接近。"},{"en":"As exams draw near, students may start revising more seriously.","zh":"隨著考試逐漸迫近，學生可能開始更認真溫習。"},{"en":"When a deadline draws near, people usually need to make a decision quickly.","zh":"當截止日期逐漸迫近，人們通常需要很快作決定。"},{"en":"This phrase creates a sense that time is running out.","zh":"這個片語營造時間快將用完的感覺。"}],"source":"2016 Q9.pdf","sourcePage":1},{"front":"think carefully about","meaning":"認真思考","examples":[{"en":"I have been thinking carefully about life after HKDSE.","zh":"我一直認真思考文憑試後的人生。"},{"en":"To think carefully about something means to consider it seriously before deciding.","zh":"think carefully about 意思是在決定前嚴肅地考慮某事。"},{"en":"A student should think carefully about which subject matches their strengths.","zh":"學生應認真思考哪個科目符合自己的強項。"},{"en":"Thinking carefully helps people avoid choosing only because others expect it.","zh":"認真思考幫助人避免只因別人期望而作選擇。"},{"en":"This phrase shows that the decision is not sudden or careless.","zh":"這個片語顯示決定不是突然或草率的。"}],"source":"2016 Q9.pdf","sourcePage":1},{"front":"life after HKDSE","meaning":"文憑試後的人生","examples":[{"en":"I have been thinking carefully about life after HKDSE.","zh":"我一直認真思考文憑試後的人生。"},{"en":"Life after HKDSE means the study, career, and personal choices that come after the public exam.","zh":"文憑試後的人生指公開考試後的升學、事業和個人選擇。"},{"en":"Students may worry about life after HKDSE because many paths are possible.","zh":"學生可能擔心文憑試後的人生，因為有很多可能道路。"},{"en":"Planning life after HKDSE can include university applications, interviews, and career goals.","zh":"規劃文憑試後的人生可包括大學申請、面試和事業目標。"},{"en":"This phrase shows a turning point between school life and the next stage.","zh":"這個片語顯示由校園生活走向下一階段的轉捩點。"}],"source":"2016 Q9.pdf","sourcePage":1},{"front":"HKDSE","meaning":"香港中學文憑試","examples":[{"en":"I have been thinking carefully about life after HKDSE.","zh":"我一直認真思考文憑試後的人生。"},{"en":"HKDSE is the Hong Kong Diploma of Secondary Education examination.","zh":"HKDSE 是香港中學文憑考試。"},{"en":"Many Hong Kong students take the HKDSE before applying to universities or colleges.","zh":"許多香港學生在申請大學或學院前會應考香港中學文憑試。"},{"en":"HKDSE results can affect students’ study choices after secondary school.","zh":"文憑試成績可能影響學生中學後的升學選擇。"},{"en":"In this email, HKDSE marks the moment when the writer must choose a future path.","zh":"在這封電郵中，文憑試標誌作者必須選擇未來道路的時刻。"}],"source":"2016 Q9.pdf","sourcePage":1},{"front":"pursue an acting career","meaning":"投身演員事業","examples":[{"en":"Because I want to pursue an acting career, I intend to apply to HKAPA.","zh":"因為我想投身演員事業，所以我打算申請香港演藝學院。"},{"en":"To pursue an acting career means to work seriously towards becoming a professional actor.","zh":"pursue an acting career 意思是認真朝成為專業演員的方向努力。"},{"en":"A student may pursue an acting career by training in voice, movement, and performance.","zh":"學生可透過接受聲線、動作和表演訓練來投身演員事業。"},{"en":"Pursuing an acting career requires preparation, discipline, and resilience.","zh":"投身演員事業需要準備、紀律和抗逆力。"},{"en":"This phrase shows that acting is treated as a real career, not just a hobby.","zh":"這個片語顯示演戲被視為真正事業，而不只是興趣。"}],"source":"2016 Q9.pdf","sourcePage":1},{"front":"intend to apply to","meaning":"打算申請","examples":[{"en":"I intend to apply to HKAPA.","zh":"我打算申請香港演藝學院。"},{"en":"Intend to apply to means plan seriously to submit an application to a school or organisation.","zh":"intend to apply to 意思是認真計劃向某學校或機構提交申請。"},{"en":"A student may intend to apply to a drama academy after preparing a portfolio.","zh":"學生準備好作品集後，可能打算申請戲劇學院。"},{"en":"This phrase sounds more definite than “I might apply”.","zh":"這個片語比 “I might apply” 聽起來更確定。"},{"en":"It shows that the writer has moved from thinking to planning.","zh":"它顯示作者已由思考走向計劃。"}],"source":"2016 Q9.pdf","sourcePage":2},{"front":"I am writing not to…but to…","meaning":"我寫信不是為了……而是為了……","examples":[{"en":"I am writing not to reject your advice, but to ask for your trust.","zh":"我寫信不是為了拒絕你們的建議，而是為了請求你們信任。"},{"en":"This structure explains what the writer is not trying to do and what the real purpose is.","zh":"這個句式解釋作者不是想做甚麼，以及真正目的為何。"},{"en":"I am writing not to argue, but to explain my decision calmly.","zh":"我寫信不是為了爭辯，而是為了冷靜解釋我的決定。"},{"en":"It helps reduce conflict because it shows respect for the reader.","zh":"它有助減少衝突，因為它顯示對讀者的尊重。"},{"en":"This phrase is useful when asking for support in a sensitive situation.","zh":"在敏感情況下請求支持時，這個片語很有用。"}],"source":"2016 Q9.pdf","sourcePage":2},{"front":"reject your advice","meaning":"拒絕你們的建議","examples":[{"en":"I am writing not to reject your advice.","zh":"我寫信不是為了拒絕你們的建議。"},{"en":"To reject your advice means to refuse or dismiss what you suggested.","zh":"reject your advice 意思是拒絕或否定你們提出的建議。"},{"en":"A teenager may disagree with parents without rejecting their advice disrespectfully.","zh":"青少年可以不同意父母，但不一定是不尊重地拒絕他們的建議。"},{"en":"The writer wants to show that choosing HKAPA is not an act of rebellion.","zh":"作者想顯示選擇香港演藝學院不是反叛行為。"},{"en":"This phrase helps keep the tone respectful while explaining a different choice.","zh":"這個片語幫助作者在解釋不同選擇時保持尊重語氣。"}],"source":"2016 Q9.pdf","sourcePage":2},{"front":"ask for your trust","meaning":"請求你們信任","examples":[{"en":"I am writing to ask for your trust.","zh":"我寫信是為了請求你們信任。"},{"en":"To ask for your trust means to request that you believe I will act responsibly.","zh":"ask for your trust 意思是請求你們相信我會負責任地行事。"},{"en":"A child may ask for parents’ trust before making an important education choice.","zh":"孩子在作重要升學選擇前，可能請求父母信任。"},{"en":"Asking for trust does not mean asking others to stop worrying completely.","zh":"請求信任並不代表要求別人完全停止擔心。"},{"en":"This phrase shows that the writer values the relationship with the parents.","zh":"這個片語顯示作者重視與父母的關係。"}],"source":"2016 Q9.pdf","sourcePage":2},{"front":"prefer a more academic subject","meaning":"較喜歡學術性較強的科目","examples":[{"en":"I understand that you prefer a more academic subject.","zh":"我明白你們較喜歡學術性較強的科目。"},{"en":"To prefer a more academic subject means to favour a course based more on traditional study and theory.","zh":"prefer a more academic subject 意思是較傾向選擇以傳統學習和理論為主的課程。"},{"en":"Parents may prefer a more academic subject because it seems stable.","zh":"父母可能因為學術科目看似穩定，而較喜歡它。"},{"en":"A student may respect academic subjects but still choose performing arts.","zh":"學生可能尊重學術科目，但仍選擇表演藝術。"},{"en":"This phrase recognises the parents’ view before giving a different argument.","zh":"這個片語先承認父母看法，再提出不同論點。"}],"source":"2016 Q9.pdf","sourcePage":2},{"front":"want my future to be secure","meaning":"希望我的前途有保障","examples":[{"en":"You want my future to be secure.","zh":"你們希望我的前途有保障。"},{"en":"To want my future to be secure means to hope I will have safety, income, and stability later in life.","zh":"want my future to be secure 意思是希望我日後有安全感、收入和穩定性。"},{"en":"Parents often want their children’s future to be secure because they love them.","zh":"父母常希望孩子前途有保障，因為他們愛孩子。"},{"en":"A secure future may involve money, confidence, skills, and clear direction.","zh":"有保障的前途可能涉及金錢、信心、技能和清晰方向。"},{"en":"This phrase shows that the writer understands the parents’ worry as care.","zh":"這個片語顯示作者理解父母的擔心是出於關心。"}],"source":"2016 Q9.pdf","sourcePage":2},{"front":"my position is that","meaning":"我的立場是","examples":[{"en":"My position is that HKAPA is the most suitable choice for me.","zh":"我的立場是香港演藝學院是最適合我的選擇。"},{"en":"My position is that means my clear opinion or stance is that.","zh":"my position is that 意思是我的清楚意見或立場是。"},{"en":"My position is that students should choose courses that match their strengths.","zh":"我的立場是學生應選擇符合自己強項的課程。"},{"en":"This phrase helps the writer state an argument directly.","zh":"這個片語幫助作者直接提出論點。"},{"en":"It sounds calm and reasoned rather than emotional or defensive.","zh":"它聽起來冷靜而有理據，不是情緒化或防衛性。"}],"source":"2016 Q9.pdf","sourcePage":2},{"front":"the most suitable choice","meaning":"最合適的選擇","examples":[{"en":"HKAPA is the most suitable choice for me.","zh":"香港演藝學院是最適合我的選擇。"},{"en":"The most suitable choice means the option that best fits a person’s goals, strengths, and situation.","zh":"the most suitable choice 指最符合一個人的目標、強項和情況的選項。"},{"en":"A science programme may be the most suitable choice for a student who loves research.","zh":"對熱愛研究的學生來說，科學課程可能是最合適的選擇。"},{"en":"HKAPA may be suitable if the writer wants serious acting training.","zh":"如果作者想接受認真演藝訓練，香港演藝學院可能合適。"},{"en":"This phrase focuses on fit, not only reputation.","zh":"這個片語著重適合程度，而不只是名聲。"}],"source":"2016 Q9.pdf","sourcePage":2},{"front":"match my strengths","meaning":"符合我的強項","examples":[{"en":"HKAPA matches my strengths.","zh":"香港演藝學院符合我的強項。"},{"en":"To match my strengths means to fit what I am naturally good at or have worked hard to develop.","zh":"match my strengths 意思是配合我天生擅長或努力培養出來的能力。"},{"en":"A course in design may match a student’s strengths in drawing and problem-solving.","zh":"設計課程可能符合學生在繪畫和解難方面的強項。"},{"en":"Acting training matches the writer’s strengths if she learns well through performance.","zh":"如果作者透過表演學得好，演藝訓練便符合她的強項。"},{"en":"Choosing a path that matches strengths can increase confidence and motivation.","zh":"選擇符合強項的道路可以增加信心和動力。"}],"source":"2016 Q9.pdf","sourcePage":2},{"front":"provide professional training","meaning":"提供專業訓練","examples":[{"en":"HKAPA provides professional training.","zh":"香港演藝學院提供專業訓練。"},{"en":"To provide professional training means to offer serious instruction for a specific career.","zh":"provide professional training 意思是為特定職業提供認真的指導。"},{"en":"A nursing school provides professional training in patient care and safety.","zh":"護理學校提供病人照顧和安全方面的專業訓練。"},{"en":"Acting schools provide professional training in voice, movement, and performance.","zh":"演藝學校提供聲線、動作和表演方面的專業訓練。"},{"en":"Professional training helps students move from interest to real skill.","zh":"專業訓練幫助學生由興趣走向真正技能。"}],"source":"2016 Q9.pdf","sourcePage":2},{"front":"manage the risks sensibly","meaning":"理性地管理風險","examples":[{"en":"HKAPA still allows me to manage the risks sensibly.","zh":"香港演藝學院仍讓我可以理性地管理風險。"},{"en":"To manage the risks sensibly means to face possible problems with realistic plans.","zh":"manage the risks sensibly 意思是用現實計劃面對可能出現的問題。"},{"en":"A student can manage financial risks sensibly by applying for scholarships.","zh":"學生可透過申請獎學金來理性地管理財政風險。"},{"en":"The writer can manage career risks by building transferable skills.","zh":"作者可透過培養可轉移技能來管理事業風險。"},{"en":"This phrase shows that courage can still be careful and responsible.","zh":"這個片語顯示勇敢仍可以是謹慎和負責任的。"}],"source":"2016 Q9.pdf","sourcePage":3},{"front":"not an escape from","meaning":"不是逃避……","examples":[{"en":"HKAPA is not an escape from academic discipline.","zh":"香港演藝學院不是逃避學術紀律。"},{"en":"Not an escape from means not a way to avoid something difficult or serious.","zh":"not an escape from 意思是不是用來避開困難或嚴肅事情的方法。"},{"en":"Choosing art is not an escape from hard work if the training is demanding.","zh":"如果訓練要求高，選擇藝術並不是逃避努力。"},{"en":"HKAPA is not an escape from discipline because acting requires study and practice.","zh":"香港演藝學院不是逃避紀律，因為演戲需要學習和練習。"},{"en":"This phrase answers the fear that performing arts is an easy option.","zh":"這個片語回應「表演藝術是輕鬆選項」的擔憂。"}],"source":"2016 Q9.pdf","sourcePage":3},{"front":"academic discipline","meaning":"學術紀律；學術訓練","examples":[{"en":"HKAPA is not an escape from academic discipline.","zh":"香港演藝學院不是逃避學術紀律。"},{"en":"Academic discipline means serious study habits, intellectual effort, and respect for standards.","zh":"academic discipline 指認真的學習習慣、智力努力和對標準的尊重。"},{"en":"Script analysis requires academic discipline because actors must study meaning carefully.","zh":"劇本分析需要學術紀律，因為演員必須仔細研究意思。"},{"en":"A performing arts student still needs academic discipline to research roles and understand texts.","zh":"表演藝術學生仍需要學術紀律，以研究角色和理解文本。"},{"en":"This phrase shows that art and serious study can belong together.","zh":"這個片語顯示藝術和嚴肅學習可以並存。"}],"source":"2016 Q9.pdf","sourcePage":3},{"front":"the most direct and serious route","meaning":"最直接而認真的途徑","examples":[{"en":"HKAPA is the most direct and serious route to the career I want.","zh":"香港演藝學院是通往我想要事業的最直接而認真的途徑。"},{"en":"The most direct and serious route means the clearest and most professional path to a goal.","zh":"the most direct and serious route 指通往目標最清晰和最專業的道路。"},{"en":"Medical school is the most direct route for someone who wants to become a doctor.","zh":"對想成為醫生的人來說，醫學院是最直接的途徑。"},{"en":"For acting, a performing arts academy can be a direct and serious route.","zh":"對演戲而言，表演藝術學院可以是直接而認真的途徑。"},{"en":"This phrase shows that the writer has chosen a practical path, not a random dream.","zh":"這個片語顯示作者選擇的是實際道路，而不是隨機夢想。"}],"source":"2016 Q9.pdf","sourcePage":3},{"front":"be prepared to work for","meaning":"準備為……努力","examples":[{"en":"Acting is the career I am prepared to work for.","zh":"演戲是我準備為之努力的事業。"},{"en":"To be prepared to work for something means to be ready to put in effort for it.","zh":"be prepared to work for 意思是準備好為某事付出努力。"},{"en":"A student prepared to work for music will practise even when progress is slow.","zh":"準備為音樂努力的學生，即使進步慢也會練習。"},{"en":"The writer is not only dreaming of acting but is ready to train for it.","zh":"作者不只是夢想演戲，而是準備為此接受訓練。"},{"en":"This phrase shows commitment and maturity.","zh":"這個片語顯示承擔和成熟。"}],"source":"2016 Q9.pdf","sourcePage":3},{"front":"not merely","meaning":"不只是","examples":[{"en":"Acting is not merely memorising lines under bright lights.","zh":"演戲不只是站在明亮燈光下背台詞。"},{"en":"Not merely means not only or not simply.","zh":"not merely 意思是不只是或不單單是。"},{"en":"Teaching is not merely explaining facts; it also involves understanding students.","zh":"教學不只是解釋知識；它也包括理解學生。"},{"en":"Acting is not merely performance because it also needs analysis and teamwork.","zh":"演戲不只是表演，因為它也需要分析和團隊合作。"},{"en":"This phrase helps correct an oversimplified view.","zh":"這個片語有助糾正過分簡化的看法。"}],"source":"2016 Q9.pdf","sourcePage":3},{"front":"memorise lines","meaning":"背台詞","examples":[{"en":"Acting is not merely memorising lines.","zh":"演戲不只是背台詞。"},{"en":"To memorise lines means to learn the words of a script by heart.","zh":"memorise lines 意思是把劇本中的文字牢記。"},{"en":"Actors must memorise lines before they can perform naturally on stage.","zh":"演員必須先背熟台詞，才能在舞台上自然演出。"},{"en":"Memorising lines is important, but it is only one part of acting.","zh":"背台詞很重要，但只是演戲的一部分。"},{"en":"Good actors also understand the character behind the lines.","zh":"好演員也會理解台詞背後的角色。"}],"source":"2016 Q9.pdf","sourcePage":3},{"front":"under bright lights","meaning":"在明亮燈光下","examples":[{"en":"Acting is not just memorising lines under bright lights.","zh":"演戲不只是站在明亮燈光下背台詞。"},{"en":"Under bright lights means in a performance setting where stage lights shine strongly.","zh":"under bright lights 指在強烈舞台燈光照射下的表演環境中。"},{"en":"A performer may feel nervous under bright lights before a large audience.","zh":"表演者在明亮燈光下面對大量觀眾前可能會緊張。"},{"en":"The phrase creates an image of public performance and pressure.","zh":"這個片語營造公開表演和壓力的畫面。"},{"en":"Acting under bright lights requires confidence, control, and preparation.","zh":"在明亮燈光下演出需要信心、控制和準備。"}],"source":"2016 Q9.pdf","sourcePage":3},{"front":"voice control","meaning":"聲線控制","examples":[{"en":"Acting requires voice control.","zh":"演戲需要聲線控制。"},{"en":"Voice control means using volume, tone, speed, and breathing effectively when speaking.","zh":"聲線控制指說話時有效運用音量、語調、速度和呼吸。"},{"en":"Actors need voice control so the audience can hear emotion and meaning clearly.","zh":"演員需要聲線控制，讓觀眾清楚聽到情感和意思。"},{"en":"Poor voice control may make a powerful line sound weak.","zh":"聲線控制差可能令有力台詞聽起來薄弱。"},{"en":"Training voice control helps performers speak clearly under pressure.","zh":"訓練聲線控制幫助表演者在壓力下清楚說話。"}],"source":"2016 Q9.pdf","sourcePage":3},{"front":"physical training","meaning":"身體訓練","examples":[{"en":"Acting requires physical training.","zh":"演戲需要身體訓練。"},{"en":"Physical training means training the body to move, stand, breathe, and perform safely.","zh":"身體訓練指訓練身體安全地移動、站立、呼吸和表演。"},{"en":"Actors may need physical training to express age, emotion, or injury convincingly.","zh":"演員可能需要身體訓練，才能有說服力地表達年齡、情緒或受傷狀態。"},{"en":"Without physical training, performers may tire quickly during long rehearsals.","zh":"沒有身體訓練，表演者在長時間排練中可能很快疲倦。"},{"en":"This phrase shows that acting uses the body as well as the voice.","zh":"這個片語顯示演戲不只使用聲音，也使用身體。"}],"source":"2016 Q9.pdf","sourcePage":3},{"front":"script analysis","meaning":"劇本分析","examples":[{"en":"Actors need script analysis.","zh":"演員需要劇本分析。"},{"en":"Script analysis means studying a script to understand characters, motives, conflict, and meaning.","zh":"劇本分析指研究劇本，以理解角色、動機、衝突和意義。"},{"en":"An actor uses script analysis to decide why a character says a line.","zh":"演員使用劇本分析來判斷角色為何說某句台詞。"},{"en":"Without script analysis, performance may become shallow or mechanical.","zh":"沒有劇本分析，表演可能變得膚淺或機械化。"},{"en":"This skill proves that acting needs careful thinking, not only emotion.","zh":"這項技能證明演戲需要仔細思考，而不只是情感。"}],"source":"2016 Q9.pdf","sourcePage":4},{"front":"emotional intelligence","meaning":"情緒智商","examples":[{"en":"Acting requires emotional intelligence.","zh":"演戲需要情緒智商。"},{"en":"Emotional intelligence means understanding feelings in oneself and others.","zh":"情緒智商指理解自己和他人情感的能力。"},{"en":"Actors need emotional intelligence to show grief, anger, or joy truthfully.","zh":"演員需要情緒智商，才能真實地表現悲傷、憤怒或喜悅。"},{"en":"Emotional intelligence also helps performers work respectfully with directors and classmates.","zh":"情緒智商也幫助表演者與導演和同學尊重地合作。"},{"en":"This skill is useful beyond acting because people use it in daily relationships.","zh":"這項技能不只對演戲有用，因為人們在日常關係中也會使用它。"}],"source":"2016 Q9.pdf","sourcePage":4},{"front":"teamwork and resilience","meaning":"團隊合作和抗逆力","examples":[{"en":"Acting requires teamwork and resilience.","zh":"演戲需要團隊合作和抗逆力。"},{"en":"Teamwork and resilience mean working well with others and recovering after difficulty or criticism.","zh":"團隊合作和抗逆力指能與他人良好合作，並在困難或批評後恢復過來。"},{"en":"A cast needs teamwork because every actor depends on others.","zh":"劇組需要團隊合作，因為每位演員都依賴其他人。"},{"en":"Actors need resilience when auditions fail or rehearsals are demanding.","zh":"當試鏡失敗或排練要求高時，演員需要抗逆力。"},{"en":"These qualities make acting training useful for many careers.","zh":"這些素質令演藝訓練對許多職業都有用。"}],"source":"2016 Q9.pdf","sourcePage":4},{"front":"conventional academic programme","meaning":"傳統學術課程","examples":[{"en":"A conventional academic programme may not provide daily acting training.","zh":"傳統學術課程未必提供每日演藝訓練。"},{"en":"A conventional academic programme is a traditional course focused more on classroom study and theory.","zh":"conventional academic programme 是較著重課堂學習和理論的傳統課程。"},{"en":"Such a programme may be respected but not closely connected to acting practice.","zh":"這類課程可能受尊重，但未必與演戲實踐密切相關。"},{"en":"If a student wants performance training, a conventional programme may not be direct enough.","zh":"如果學生想接受表演訓練，傳統課程可能不夠直接。"},{"en":"This phrase contrasts traditional study with specialised artistic training.","zh":"這個片語把傳統學習與專門藝術訓練作對比。"}],"source":"2016 Q9.pdf","sourcePage":4},{"front":"respectable degree","meaning":"受尊重的學位","examples":[{"en":"I might receive a respectable degree in a conventional academic programme.","zh":"我可能在傳統學術課程中取得受尊重的學位。"},{"en":"A respectable degree is a qualification that society generally sees as serious and valuable.","zh":"respectable degree 是社會一般視為認真而有價值的資格。"},{"en":"A business or law degree may be considered respectable by many relatives.","zh":"商科或法律學位可能被許多親戚視為受尊重的學位。"},{"en":"A respectable degree is useful, but it may not match every student’s career goal.","zh":"受尊重的學位有用，但未必符合每位學生的事業目標。"},{"en":"This phrase shows respect for academic paths while questioning whether they fit the writer.","zh":"這個片語尊重學術道路，同時質疑它是否適合作者。"}],"source":"2016 Q9.pdf","sourcePage":4},{"front":"daily training in","meaning":"每日接受……訓練","examples":[{"en":"I would not receive daily training in the craft I want to practise.","zh":"我不會每日接受我想鑽研的技藝訓練。"},{"en":"Daily training in something means regular practice in that skill every day or very often.","zh":"daily training in 某事，意思是每天或經常練習該技能。"},{"en":"A dancer needs daily training in movement, balance, and strength.","zh":"舞者需要每日接受動作、平衡和力量訓練。"},{"en":"Daily training in acting helps students improve voice, body, and confidence.","zh":"每日接受演藝訓練幫助學生改善聲線、身體和信心。"},{"en":"This phrase stresses that skill grows through repeated practice.","zh":"這個片語強調技能是透過反覆練習成長的。"}],"source":"2016 Q9.pdf","sourcePage":4},{"front":"the craft I want to practise","meaning":"我想鑽研的技藝","examples":[{"en":"Acting is the craft I want to practise.","zh":"演戲是我想鑽研的技藝。"},{"en":"The craft I want to practise means the skill or art I want to study and improve seriously.","zh":"the craft I want to practise 指我想認真學習和改進的技能或藝術。"},{"en":"For a chef, cooking may be the craft they want to practise every day.","zh":"對廚師來說，烹飪可能是他們每天想鑽研的技藝。"},{"en":"Calling acting a craft shows that it takes training, patience, and technique.","zh":"把演戲稱為技藝，顯示它需要訓練、耐性和技巧。"},{"en":"This phrase makes the writer’s dream sound serious and disciplined.","zh":"這個片語令作者的夢想聽起來認真而有紀律。"}],"source":"2016 Q9.pdf","sourcePage":4},{"front":"over the past two years","meaning":"在過去兩年","examples":[{"en":"Over the past two years, I have joined school drama productions.","zh":"在過去兩年，我參與了學校戲劇製作。"},{"en":"Over the past two years means during the two years leading up to now.","zh":"over the past two years 意思是在截至現在的兩年期間。"},{"en":"Over the past two years, a student may build experience through practice and performances.","zh":"在過去兩年，學生可能透過練習和演出建立經驗。"},{"en":"This phrase shows that the interest has lasted for some time.","zh":"這個片語顯示興趣已持續一段時間。"},{"en":"It helps prove that the decision is based on experience, not a sudden impulse.","zh":"它有助證明這個決定基於經驗，而不是突然衝動。"}],"source":"2016 Q9.pdf","sourcePage":4},{"front":"school drama productions","meaning":"學校戲劇製作","examples":[{"en":"I have joined school drama productions.","zh":"我參與了學校戲劇製作。"},{"en":"School drama productions are plays or performances created and performed by students at school.","zh":"學校戲劇製作是由學生在學校創作和演出的戲劇或表演。"},{"en":"Students in school drama productions may act, direct, design costumes, or manage backstage work.","zh":"參與學校戲劇製作的學生可能演戲、導演、設計服裝或管理後台工作。"},{"en":"Joining school drama productions helps students understand teamwork and performance pressure.","zh":"參與學校戲劇製作幫助學生理解團隊合作和表演壓力。"},{"en":"This experience can show whether a student is serious about acting.","zh":"這種經驗可以顯示學生是否認真對待演戲。"}],"source":"2016 Q9.pdf","sourcePage":4},{"front":"volunteer backstage","meaning":"自願到後台幫忙","examples":[{"en":"I have volunteered backstage during drama productions.","zh":"我曾在戲劇製作期間自願到後台幫忙。"},{"en":"To volunteer backstage means to help behind the scenes without being paid.","zh":"volunteer backstage 意思是在幕後無薪幫忙。"},{"en":"A student may volunteer backstage by moving props or helping actors prepare.","zh":"學生可能透過搬道具或協助演員準備來自願到後台幫忙。"},{"en":"Backstage work teaches responsibility because the show depends on hidden support.","zh":"後台工作教人負責任，因為演出依賴看不見的支援。"},{"en":"Volunteering backstage shows that the writer respects all parts of theatre.","zh":"自願到後台幫忙顯示作者尊重劇場的所有部分。"}],"source":"2016 Q9.pdf","sourcePage":4},{"front":"watch performances","meaning":"觀看演出","examples":[{"en":"I have watched performances to understand acting.","zh":"我曾觀看演出以理解演戲。"},{"en":"To watch performances means to observe plays, films, or stage shows carefully.","zh":"watch performances 意思是仔細觀察戲劇、電影或舞台表演。"},{"en":"A student can learn timing and expression by watching performances.","zh":"學生可以透過觀看演出學習節奏和表達。"},{"en":"Watching performances helps future actors see how professionals build characters.","zh":"觀看演出幫助未來演員看見專業人士如何塑造角色。"},{"en":"This phrase shows that learning can happen as an audience member too.","zh":"這個片語顯示作為觀眾也可以學習。"}],"source":"2016 Q9.pdf","sourcePage":5},{"front":"build characters","meaning":"塑造角色","examples":[{"en":"I watched performances to understand how actors build characters.","zh":"我觀看演出，以理解演員如何塑造角色。"},{"en":"To build characters means to create believable people on stage or screen through choices and details.","zh":"build characters 意思是透過選擇和細節，在舞台或螢幕上創造可信的人物。"},{"en":"Actors build characters by studying their background, voice, movement, and motives.","zh":"演員透過研究角色背景、聲線、動作和動機來塑造角色。"},{"en":"A weak performance may happen if an actor does not build the character carefully.","zh":"如果演員沒有仔細塑造角色，表演可能會薄弱。"},{"en":"This phrase shows that acting involves imagination and analysis.","zh":"這個片語顯示演戲涉及想像和分析。"}],"source":"2016 Q9.pdf","sourcePage":5},{"front":"the more…the more…","meaning":"越……越……","examples":[{"en":"The more I perform, the more I realise how demanding the profession is.","zh":"我越表演，就越明白這個職業有多高要求。"},{"en":"The more…the more… shows that one thing increases together with another.","zh":"the more…the more… 顯示一件事會隨另一件事一起增加。"},{"en":"The more students practise, the more confident they may become.","zh":"學生越練習，便越可能有信心。"},{"en":"The more the writer performs, the more she understands acting is not easy.","zh":"作者越表演，就越明白演戲並不容易。"},{"en":"This structure is useful for showing gradual discovery or development.","zh":"這個句式適合用來顯示逐步發現或發展。"}],"source":"2016 Q9.pdf","sourcePage":5},{"front":"how demanding the profession is","meaning":"這個職業有多高要求","examples":[{"en":"I realise how demanding the acting profession is.","zh":"我明白演員這個職業有多高要求。"},{"en":"How demanding the profession is means how much effort, skill, and discipline the job requires.","zh":"how demanding the profession is 意思是這份工作需要多少努力、技能和紀律。"},{"en":"A doctor soon learns how demanding the profession is during long hospital shifts.","zh":"醫生在醫院長時間輪班時，很快會明白這個職業有多高要求。"},{"en":"Acting is demanding because performers must train their voice, body, and emotions.","zh":"演戲要求高，因為表演者必須訓練聲線、身體和情感。"},{"en":"This phrase shows respect for the difficulty of the career.","zh":"這個片語顯示對該事業難度的尊重。"}],"source":"2016 Q9.pdf","sourcePage":5},{"front":"proper training matters","meaning":"正規訓練很重要","examples":[{"en":"Proper training matters for anyone serious about acting.","zh":"對任何認真看待演戲的人來說，正規訓練很重要。"},{"en":"Proper training matters means good formal preparation is important.","zh":"proper training matters 意思是良好的正式準備很重要。"},{"en":"Proper training matters in medicine because mistakes can harm patients.","zh":"在醫學中，正規訓練很重要，因為錯誤可能傷害病人。"},{"en":"In acting, proper training helps students perform safely and truthfully.","zh":"在演戲中，正規訓練幫助學生安全而真實地表演。"},{"en":"This phrase argues that talent alone is not enough.","zh":"這個片語主張單靠天分並不足夠。"}],"source":"2016 Q9.pdf","sourcePage":5},{"front":"medical school","meaning":"醫學院","examples":[{"en":"Future doctors need medical school.","zh":"未來醫生需要醫學院。"},{"en":"Medical school is a professional school where people train to become doctors.","zh":"醫學院是人們接受訓練成為醫生的專業學校。"},{"en":"Students attend medical school to study the body, disease, treatment, and patient care.","zh":"學生在醫學院學習身體、疾病、治療和病人照顧。"},{"en":"The example of medical school shows that serious careers need proper training.","zh":"醫學院這個例子顯示嚴肅職業需要正規訓練。"},{"en":"This comparison helps explain why actors also need specialised education.","zh":"這個比較有助解釋為何演員也需要專門教育。"}],"source":"2016 Q9.pdf","sourcePage":5},{"front":"engineering training","meaning":"工程訓練","examples":[{"en":"Future engineers need engineering training.","zh":"未來工程師需要工程訓練。"},{"en":"Engineering training teaches people how to design, build, test, and solve technical problems.","zh":"工程訓練教人如何設計、建造、測試和解決技術問題。"},{"en":"A future engineer needs training before designing bridges or machines safely.","zh":"未來工程師在安全設計橋樑或機器前需要訓練。"},{"en":"This example shows that professional skill requires structured learning.","zh":"這個例子顯示專業技能需要有系統的學習。"},{"en":"It supports the idea that acting also deserves serious training.","zh":"它支持演戲也值得接受認真訓練的想法。"}],"source":"2016 Q9.pdf","sourcePage":5},{"front":"performing arts academy","meaning":"表演藝術學院","examples":[{"en":"A future actor should not avoid a performing arts academy.","zh":"未來演員不應避開表演藝術學院。"},{"en":"A performing arts academy is a school that trains students in theatre, dance, music, and related arts.","zh":"表演藝術學院是訓練學生戲劇、舞蹈、音樂和相關藝術的學校。"},{"en":"A student may attend a performing arts academy to receive daily stage training.","zh":"學生可能入讀表演藝術學院，以接受每日舞台訓練。"},{"en":"Such an academy gives artists space to practise under professional guidance.","zh":"這類學院給藝術家在專業指導下練習的空間。"},{"en":"This phrase presents acting education as serious and specialised.","zh":"這個片語把演藝教育呈現為嚴肅而專門的訓練。"}],"source":"2016 Q9.pdf","sourcePage":5},{"front":"childish impulse","meaning":"幼稚衝動","examples":[{"en":"Choosing HKAPA is not a childish impulse.","zh":"選擇香港演藝學院不是幼稚衝動。"},{"en":"A childish impulse is a sudden immature wish that has not been thought through.","zh":"childish impulse 是未經深思熟慮的突然幼稚願望。"},{"en":"Buying something expensive because of one advertisement may be a childish impulse.","zh":"只因一個廣告就買昂貴物品，可能是幼稚衝動。"},{"en":"The writer argues that applying to HKAPA comes from experience and planning.","zh":"作者主張申請香港演藝學院來自經驗和計劃。"},{"en":"This phrase helps defend the choice as serious, not naive.","zh":"這個片語有助把選擇辯護為認真，而不是天真。"}],"source":"2016 Q9.pdf","sourcePage":5},{"front":"practical alignment between…and…","meaning":"……與……之間的實際契合","examples":[{"en":"Choosing HKAPA is a practical alignment between my goal and my education.","zh":"選擇香港演藝學院是我的目標和我的教育之間的實際契合。"},{"en":"Practical alignment between two things means they fit together in a useful and realistic way.","zh":"practical alignment between two things 意思是兩者以有用而現實的方式配合。"},{"en":"Studying nursing creates practical alignment between caring for people and career training.","zh":"修讀護理令關心他人和職業訓練之間形成實際契合。"},{"en":"HKAPA aligns the writer’s acting goal with daily professional education.","zh":"香港演藝學院把作者的演員目標與每日專業教育連繫起來。"},{"en":"This phrase shows that the choice is logical, not only emotional.","zh":"這個片語顯示選擇有邏輯，而不只是情感。"}],"source":"2016 Q9.pdf","sourcePage":5},{"front":"my goal and my education","meaning":"我的目標和我的教育","examples":[{"en":"HKAPA creates a practical alignment between my goal and my education.","zh":"香港演藝學院令我的目標和我的教育之間形成實際契合。"},{"en":"My goal and my education means what I want to achieve and the study path I choose.","zh":"my goal and my education 指我想達成的事，以及我選擇的學習道路。"},{"en":"A student’s goal and education should support each other where possible.","zh":"學生的目標和教育應盡可能互相支持。"},{"en":"If the writer’s goal is acting, HKAPA connects education directly to that goal.","zh":"如果作者的目標是演戲，香港演藝學院便把教育直接連接到該目標。"},{"en":"This phrase explains why choosing the right course matters.","zh":"這個片語解釋為何選對課程很重要。"}],"source":"2016 Q9.pdf","sourcePage":6},{"front":"more importantly","meaning":"更重要的是","examples":[{"en":"More importantly, I am not asking you to support a dream with no plan.","zh":"更重要的是，我不是請求你們支持一個沒有計劃的夢想。"},{"en":"More importantly introduces a point that matters even more than the previous one.","zh":"more importantly 用來引出比前一點更重要的重點。"},{"en":"Talent is useful; more importantly, discipline is needed every day.","zh":"天分有用；更重要的是，每天都需要紀律。"},{"en":"This phrase helps the writer move to the strongest reassurance for the parents.","zh":"這個片語幫助作者轉向最能安撫父母的重點。"},{"en":"It signals that the next point deserves special attention.","zh":"它表示下一點值得特別注意。"}],"source":"2016 Q9.pdf","sourcePage":6},{"front":"support a dream with no plan","meaning":"支持一個沒有計劃的夢想","examples":[{"en":"I am not asking you to support a dream with no plan.","zh":"我不是請求你們支持一個沒有計劃的夢想。"},{"en":"To support a dream with no plan means to encourage an ambition that has no practical steps.","zh":"support a dream with no plan 意思是鼓勵一個沒有實際步驟的抱負。"},{"en":"Parents may worry if a child asks them to support a dream without training or research.","zh":"如果孩子要求父母支持一個沒有訓練或資料搜集的夢想，父母可能會擔心。"},{"en":"The writer wants to show that her acting dream includes preparation and risk management.","zh":"作者想顯示她的演員夢包含準備和風險管理。"},{"en":"This phrase separates responsible ambition from empty fantasy.","zh":"這個片語把負責任的抱負與空想分開。"}],"source":"2016 Q9.pdf","sourcePage":6},{"front":"worry about","meaning":"擔心","examples":[{"en":"I know you worry about income, competition and stability.","zh":"我知道你們擔心收入、競爭和穩定性。"},{"en":"To worry about something means to feel concerned that it may become a problem.","zh":"worry about 意思是擔心某事可能成為問題。"},{"en":"Parents may worry about whether an arts career can provide enough income.","zh":"父母可能擔心藝術事業能否提供足夠收入。"},{"en":"Worrying about risk is natural when a child chooses an uncertain path.","zh":"當孩子選擇不確定的道路時，擔心風險是自然的。"},{"en":"This phrase shows that the writer understands the parents’ concerns.","zh":"這個片語顯示作者理解父母的憂慮。"}],"source":"2016 Q9.pdf","sourcePage":6},{"front":"income, competition and stability","meaning":"收入、競爭和穩定性","examples":[{"en":"My parents worry about income, competition and stability.","zh":"我的父母擔心收入、競爭和穩定性。"},{"en":"Income, competition and stability are practical concerns about money, career pressure, and long-term security.","zh":"收入、競爭和穩定性是關於金錢、事業壓力和長期保障的實際憂慮。"},{"en":"Creative careers may raise questions about income because work can be irregular.","zh":"創意事業可能引起收入問題，因為工作可以不固定。"},{"en":"Competition and stability matter because many people may chase the same roles.","zh":"競爭和穩定性很重要，因為許多人可能爭取同一角色。"},{"en":"Naming these concerns helps the writer answer them directly.","zh":"說出這些憂慮有助作者直接回應。"}],"source":"2016 Q9.pdf","sourcePage":6},{"front":"what concerns me more","meaning":"更令我擔心的是","examples":[{"en":"What concerns me more is choosing a subject without direction.","zh":"更令我擔心的是選擇一個沒有方向的科目。"},{"en":"What concerns me more means the thing that worries me even more.","zh":"what concerns me more 意思是更令我憂慮的事情。"},{"en":"A student may worry about job competition, but what concerns her more is losing purpose.","zh":"學生可能擔心就業競爭，但更令她擔心的是失去目標。"},{"en":"This phrase shifts attention from the parents’ fear to the writer’s deeper fear.","zh":"這個片語把焦點由父母的恐懼轉向作者更深的恐懼。"},{"en":"It shows that safety can also become risky if the choice is wrong.","zh":"它顯示如果選擇錯誤，安全也可能變成風險。"}],"source":"2016 Q9.pdf","sourcePage":6},{"front":"the risk of spending four years","meaning":"花四年的風險","examples":[{"en":"I worry about the risk of spending four years studying the wrong subject.","zh":"我擔心花四年修讀錯誤科目的風險。"},{"en":"The risk of spending four years means the danger of using a long period of time on the wrong choice.","zh":"the risk of spending four years 指把長時間用在錯誤選擇上的危險。"},{"en":"A student may waste energy if she spends four years studying a subject she does not believe in.","zh":"如果學生花四年讀一科自己不相信的科目，可能浪費精力。"},{"en":"This risk matters because time, money, and motivation are limited.","zh":"這個風險重要，因為時間、金錢和動力都是有限的。"},{"en":"The phrase shows that a safe-looking path can still carry serious cost.","zh":"這個片語顯示看似安全的道路仍可能有嚴重代價。"}],"source":"2016 Q9.pdf","sourcePage":6},{"front":"truly belong to","meaning":"真正屬於；真正適合","examples":[{"en":"I do not want to study something I respect but do not truly belong to.","zh":"我不想修讀一個我尊重但不真正適合我的科目。"},{"en":"To truly belong to a field means to feel that it fits your identity, strengths, and purpose.","zh":"truly belong to 某領域，意思是感到它符合你的身份、強項和目的。"},{"en":"A student may respect law but feel she truly belongs to music.","zh":"學生可能尊重法律，但覺得自己真正屬於音樂。"},{"en":"Studying a subject you do not belong to can weaken motivation over time.","zh":"修讀不真正適合自己的科目，可能隨時間削弱動力。"},{"en":"This phrase expresses emotional fit as well as practical suitability.","zh":"這個片語表達情感上的契合，也表達實際上的合適程度。"}],"source":"2016 Q9.pdf","sourcePage":6},{"front":"look safe on paper","meaning":"紙面上看似安全","examples":[{"en":"A degree may look safe on paper.","zh":"學位可能紙面上看似安全。"},{"en":"Look safe on paper means seem secure when judged by appearance, reputation, or simple facts.","zh":"look safe on paper 意思是按外表、名聲或簡單資料判斷時似乎有保障。"},{"en":"A popular course may look safe on paper because many people recognise it.","zh":"熱門課程可能紙面上看似安全，因為許多人認識它。"},{"en":"Something that looks safe on paper may not fit a student’s strengths.","zh":"紙面上看似安全的東西，未必符合學生強項。"},{"en":"This phrase warns that surface security may not be real security.","zh":"這個片語提醒人表面安全未必是真正安全。"}],"source":"2016 Q9.pdf","sourcePage":6},{"front":"become unsafe in reality","meaning":"在現實中變得有風險","examples":[{"en":"A safe-looking degree may become unsafe in reality.","zh":"看似安全的學位可能在現實中變得有風險。"},{"en":"Become unsafe in reality means turn risky in real life despite seeming secure at first.","zh":"become unsafe in reality 意思是即使起初看似有保障，在現實生活中卻變得有風險。"},{"en":"A subject may become unsafe in reality if the student loses motivation and direction.","zh":"如果學生失去動力和方向，一個科目可能在現實中變得有風險。"},{"en":"A career path that looks stable can still become unsafe if it does not fit the person.","zh":"看似穩定的事業道路，如果不適合本人，仍可能變得有風險。"},{"en":"This phrase contrasts appearance with real-life consequences.","zh":"這個片語把表面與現實後果作對比。"}],"source":"2016 Q9.pdf","sourcePage":6},{"front":"without passion, confidence or direction","meaning":"沒有熱誠、信心或方向","examples":[{"en":"A degree may be risky if I study it without passion, confidence or direction.","zh":"如果我沒有熱誠、信心或方向地修讀一個學位，它可能有風險。"},{"en":"Without passion, confidence or direction means lacking love, belief, and a clear path.","zh":"without passion, confidence or direction 意思是缺乏熱愛、信念和清晰道路。"},{"en":"A student may struggle in any subject if she studies without passion or direction.","zh":"如果學生沒有熱誠或方向，修讀任何科目都可能吃力。"},{"en":"Confidence helps students continue when the course becomes difficult.","zh":"信心幫助學生在課程變困難時繼續下去。"},{"en":"This phrase explains why emotional commitment can affect practical success.","zh":"這個片語解釋為何情感投入會影響實際成功。"}],"source":"2016 Q9.pdf","sourcePage":7},{"front":"transferable skills","meaning":"可轉移技能","examples":[{"en":"At HKAPA, I will build transferable skills.","zh":"在香港演藝學院，我會建立可轉移技能。"},{"en":"Transferable skills are abilities that can be used in more than one job or field.","zh":"可轉移技能是可用於多於一種工作或領域的能力。"},{"en":"Communication, teamwork, and problem-solving are transferable skills.","zh":"溝通、團隊合作和解難都是可轉移技能。"},{"en":"Acting training can build transferable skills through rehearsals and performance.","zh":"演藝訓練可以透過排練和表演建立可轉移技能。"},{"en":"These skills reduce risk because they open more than one career path.","zh":"這些技能降低風險，因為它們打開不止一條事業道路。"}],"source":"2016 Q9.pdf","sourcePage":7},{"front":"clear communication","meaning":"清晰溝通","examples":[{"en":"Clear communication is a transferable skill.","zh":"清晰溝通是一項可轉移技能。"},{"en":"Clear communication means expressing ideas so others can understand them easily.","zh":"清晰溝通意思是以他人容易理解的方式表達想法。"},{"en":"Actors need clear communication when speaking lines and working with directors.","zh":"演員在說台詞和與導演合作時需要清晰溝通。"},{"en":"Clear communication is also useful in interviews, teaching, and public relations.","zh":"清晰溝通在面試、教學和公共關係中也有用。"},{"en":"This skill helps people avoid misunderstandings in many workplaces.","zh":"這項技能幫助人們在許多工作場所避免誤解。"}],"source":"2016 Q9.pdf","sourcePage":7},{"front":"public speaking","meaning":"公開演說","examples":[{"en":"Public speaking is useful beyond the stage.","zh":"公開演說在舞台以外也有用。"},{"en":"Public speaking means speaking clearly and confidently to an audience.","zh":"public speaking 指清楚而自信地向觀眾說話。"},{"en":"Acting training can improve public speaking by teaching voice and presence.","zh":"演藝訓練可透過教授聲線和台風來改善公開演說。"},{"en":"Public speaking is useful in presentations, interviews, and leadership roles.","zh":"公開演說在匯報、面試和領導角色中都有用。"},{"en":"This phrase shows that stage skills can help outside theatre too.","zh":"這個片語顯示舞台技能在劇場以外也有幫助。"}],"source":"2016 Q9.pdf","sourcePage":7},{"front":"collaboration","meaning":"協作","examples":[{"en":"Acting training can develop collaboration.","zh":"演藝訓練可以培養協作能力。"},{"en":"Collaboration means working with others to achieve a shared goal.","zh":"collaboration 意思是與他人合作以達成共同目標。"},{"en":"A theatre production needs collaboration between actors, directors, designers, and backstage crew.","zh":"戲劇製作需要演員、導演、設計師和後台人員之間的協作。"},{"en":"Collaboration teaches students to listen, adjust, and respect other ideas.","zh":"協作教學生聆聽、調整和尊重其他想法。"},{"en":"This skill is valuable in almost every career.","zh":"這項技能在幾乎每個事業中都有價值。"}],"source":"2016 Q9.pdf","sourcePage":7},{"front":"the ability to handle criticism","meaning":"承受批評的能力","examples":[{"en":"Actors need the ability to handle criticism.","zh":"演員需要承受批評的能力。"},{"en":"The ability to handle criticism means being able to listen to negative comments and improve from them.","zh":"the ability to handle criticism 意思是能聆聽負面意見並從中改善。"},{"en":"A student handles criticism well when she revises her work instead of giving up.","zh":"學生接受批評後修改作品，而不是放棄，就是良好地承受批評。"},{"en":"Actors receive criticism from teachers, directors, and audiences.","zh":"演員會收到老師、導演和觀眾的批評。"},{"en":"This ability builds resilience and professional maturity.","zh":"這種能力建立抗逆力和專業成熟度。"}],"source":"2016 Q9.pdf","sourcePage":7},{"front":"valuable not only…but also…","meaning":"不但對……有價值，而且對……也有價值","examples":[{"en":"These skills are valuable not only on stage, but also in other fields.","zh":"這些技能不但在舞台上有價值，而且在其他領域也有價值。"},{"en":"Valuable not only…but also… means useful in one area and useful in another area too.","zh":"valuable not only…but also… 意思是對一個範疇有用，對另一個範疇也有用。"},{"en":"Communication is valuable not only in acting, but also in teaching and business.","zh":"溝通能力不但對演戲有價值，而且對教學和商業也有價值。"},{"en":"This structure helps show that a skill has wider value.","zh":"這個句式有助顯示技能有更廣泛價值。"},{"en":"It reassures parents that acting training is not limited to performance alone.","zh":"它安撫父母，說明演藝訓練不只限於表演。"}],"source":"2016 Q9.pdf","sourcePage":7},{"front":"on stage","meaning":"在舞台上","examples":[{"en":"Acting skills are valuable on stage.","zh":"演藝技能在舞台上有價值。"},{"en":"On stage means in a theatre or performance space in front of an audience.","zh":"on stage 意思是在劇場或表演空間中面對觀眾。"},{"en":"An actor must speak clearly on stage so the audience can hear every line.","zh":"演員在舞台上必須清楚說話，讓觀眾聽到每句台詞。"},{"en":"Confidence on stage can also improve confidence in public speaking.","zh":"舞台上的信心也可以改善公開演說的信心。"},{"en":"This phrase refers to performance, but the skills can extend beyond it.","zh":"這個片語指表演，但相關技能可延伸至其他地方。"}],"source":"2016 Q9.pdf","sourcePage":7},{"front":"cultural management","meaning":"文化管理","examples":[{"en":"Communication skills are useful in cultural management.","zh":"溝通技能在文化管理中有用。"},{"en":"Cultural management means organising arts, heritage, performances, or cultural projects.","zh":"cultural management 指組織藝術、文化遺產、演出或文化項目。"},{"en":"A cultural manager may plan festivals, exhibitions, or theatre programmes.","zh":"文化管理人員可能策劃節慶、展覽或劇場節目。"},{"en":"Acting training can help in cultural management because it builds understanding of performers and audiences.","zh":"演藝訓練可幫助文化管理，因為它建立對表演者和觀眾的理解。"},{"en":"This phrase shows one possible career door beyond acting itself.","zh":"這個片語顯示演戲本身以外的一扇事業門。"}],"source":"2016 Q9.pdf","sourcePage":7},{"front":"public relations","meaning":"公共關係","examples":[{"en":"Communication skills are also useful in public relations.","zh":"溝通技能在公共關係中也有用。"},{"en":"Public relations means managing how an organisation communicates with the public.","zh":"public relations 指管理一個機構如何與公眾溝通。"},{"en":"People in public relations write messages, handle events, and protect reputation.","zh":"公共關係工作者撰寫訊息、處理活動和維護聲譽。"},{"en":"Acting training may help public relations work because it develops confidence and audience awareness.","zh":"演藝訓練可能有助公共關係工作，因為它培養信心和觀眾意識。"},{"en":"This field shows that performance skills can be used in communication careers.","zh":"這個領域顯示表演技能可用於溝通事業。"}],"source":"2016 Q9.pdf","sourcePage":7},{"front":"in other words","meaning":"換言之","examples":[{"en":"In other words, I am not choosing acting or nothing.","zh":"換言之，我不是選擇演戲或一無所有。"},{"en":"In other words is used to explain the same idea more clearly or simply.","zh":"in other words 用來以更清楚或簡單的方式解釋同一想法。"},{"en":"I will build transferable skills; in other words, I will not have only one path.","zh":"我會建立可轉移技能；換言之，我不會只有一條路。"},{"en":"This phrase helps the writer restate a key reassurance for the parents.","zh":"這個片語幫助作者重新表達給父母的重要安撫。"},{"en":"It is useful when turning a complex point into a simple conclusion.","zh":"當把複雜重點變成簡單結論時，它很有用。"}],"source":"2016 Q9.pdf","sourcePage":8},{"front":"acting or nothing","meaning":"演戲或一無所有","examples":[{"en":"I am not choosing acting or nothing.","zh":"我不是選擇演戲或一無所有。"},{"en":"Acting or nothing means the false idea that the writer has only one possible future.","zh":"acting or nothing 指作者只有一種可能未來的錯誤想法。"},{"en":"A student choosing music is not choosing music or nothing if she builds transferable skills.","zh":"如果學生建立可轉移技能，選擇音樂並不等於選擇音樂或一無所有。"},{"en":"The creative industry can offer more paths than performing alone.","zh":"創意產業可以提供比單純表演更多的道路。"},{"en":"This phrase rejects an all-or-nothing view of career choice.","zh":"這個片語拒絕對事業選擇的非黑即白看法。"}],"source":"2016 Q9.pdf","sourcePage":8},{"front":"open several doors","meaning":"打開幾扇門；帶來多種機會","examples":[{"en":"The creative industry can open several doors for me.","zh":"創意產業可以為我打開幾扇門。"},{"en":"To open several doors means to create several opportunities or future paths.","zh":"open several doors 意思是創造多種機會或未來道路。"},{"en":"Strong communication skills can open doors in teaching, media, and public relations.","zh":"強溝通能力可以在教學、媒體和公共關係中打開機會。"},{"en":"Acting training may open doors beyond the stage.","zh":"演藝訓練可能打開舞台以外的門。"},{"en":"This phrase helps show that one choice can lead to many possibilities.","zh":"這個片語有助顯示一個選擇可以帶來多種可能。"}],"source":"2016 Q9.pdf","sourcePage":8},{"front":"creative industry","meaning":"創意產業","examples":[{"en":"I am choosing a field within the creative industry.","zh":"我選擇的是創意產業中的一個領域。"},{"en":"The creative industry includes work in arts, media, design, performance, film, and culture.","zh":"創意產業包括藝術、媒體、設計、表演、電影和文化方面的工作。"},{"en":"A person in the creative industry may act, produce shows, manage events, or write content.","zh":"創意產業中的人可能演戲、製作節目、管理活動或撰寫內容。"},{"en":"The creative industry can be competitive but also full of different career paths.","zh":"創意產業可以競爭激烈，但也充滿不同事業道路。"},{"en":"This phrase presents acting as part of a wider professional field.","zh":"這個片語把演戲呈現為更廣泛專業領域的一部分。"}],"source":"2016 Q9.pdf","sourcePage":8},{"front":"minimise the risk","meaning":"將風險減至最低","examples":[{"en":"To minimise the risk, I will apply for scholarships.","zh":"為了將風險減至最低，我會申請獎學金。"},{"en":"To minimise the risk means to reduce possible danger, loss, or uncertainty.","zh":"minimise the risk 意思是減少可能的危險、損失或不確定性。"},{"en":"A student can minimise financial risk by planning a budget before university.","zh":"學生可透過大學前規劃預算來減低財政風險。"},{"en":"Applying for scholarships can minimise the risk of heavy study costs.","zh":"申請獎學金可以減低沉重學費帶來的風險。"},{"en":"This phrase shows that the writer has thought about practical protection.","zh":"這個片語顯示作者已考慮實際保障。"}],"source":"2016 Q9.pdf","sourcePage":8},{"front":"apply for scholarships","meaning":"申請獎學金","examples":[{"en":"I will apply for scholarships.","zh":"我會申請獎學金。"},{"en":"To apply for scholarships means to request financial awards that help pay for study.","zh":"apply for scholarships 意思是申請幫助支付學費的資助獎項。"},{"en":"A student may apply for scholarships by submitting grades, references, and personal statements.","zh":"學生可透過提交成績、推薦信和個人陳述來申請獎學金。"},{"en":"Scholarships can reduce the financial pressure on a family.","zh":"獎學金可以減輕家庭財政壓力。"},{"en":"This plan shows responsibility because the writer is not leaving all costs to her parents.","zh":"這個計劃顯示負責任，因為作者不是把所有費用都留給父母承擔。"}],"source":"2016 Q9.pdf","sourcePage":8},{"front":"take part-time work","meaning":"做兼職工作","examples":[{"en":"I will take part-time work only when it does not harm my training.","zh":"我只會在不影響訓練的情況下做兼職工作。"},{"en":"To take part-time work means to do a job for fewer hours while studying or doing something else.","zh":"take part-time work 意思是在學習或做其他事情的同時做工時較少的工作。"},{"en":"A student may take part-time work to pay for transport or materials.","zh":"學生可能做兼職工作來支付交通費或材料費。"},{"en":"Part-time work can help financially, but it should not damage study or training.","zh":"兼職工作可以在財政上有幫助，但不應損害學習或訓練。"},{"en":"This phrase shows a careful balance between money and learning.","zh":"這個片語顯示在金錢和學習之間作出謹慎平衡。"}],"source":"2016 Q9.pdf","sourcePage":8},{"front":"harm my training","meaning":"影響我的訓練","examples":[{"en":"I will not take part-time work if it harms my training.","zh":"如果兼職工作影響我的訓練，我就不會做。"},{"en":"To harm my training means to damage or weaken the quality of my practice and learning.","zh":"harm my training 意思是損害或削弱我的練習和學習質素。"},{"en":"A job may harm training if it leaves a student too tired for rehearsals.","zh":"如果工作令學生太疲倦而無法排練，它便可能影響訓練。"},{"en":"The writer promises that earning money will not come before professional preparation.","zh":"作者承諾賺錢不會優先於專業準備。"},{"en":"This phrase shows that training remains the main priority.","zh":"這個片語顯示訓練仍是首要事項。"}],"source":"2016 Q9.pdf","sourcePage":8},{"front":"keep improving","meaning":"持續改善","examples":[{"en":"I will keep improving my English and Putonghua.","zh":"我會持續改善我的英文和普通話。"},{"en":"To keep improving means to continue getting better through effort and practice.","zh":"keep improving 意思是透過努力和練習繼續變得更好。"},{"en":"A performer should keep improving voice, movement, and language skills.","zh":"表演者應持續改善聲線、動作和語言能力。"},{"en":"Keeping improving shows that the writer accepts growth as a long process.","zh":"持續改善顯示作者接受成長是一個長期過程。"},{"en":"This phrase suggests discipline after admission, not only before application.","zh":"這個片語表示入學後也有紀律，而不只是申請前努力。"}],"source":"2016 Q9.pdf","sourcePage":8},{"front":"English and Putonghua","meaning":"英文和普通話","examples":[{"en":"I will keep improving my English and Putonghua.","zh":"我會持續改善我的英文和普通話。"},{"en":"English and Putonghua are language skills that can help performers reach wider audiences.","zh":"英文和普通話是可以幫助表演者接觸更廣觀眾的語言技能。"},{"en":"Actors may need English and Putonghua for auditions, scripts, interviews, or media work.","zh":"演員在試鏡、劇本、訪問或媒體工作中可能需要英文和普通話。"},{"en":"Improving languages can open more opportunities in the creative industry.","zh":"改善語言能力可以在創意產業中打開更多機會。"},{"en":"This phrase shows a practical plan to strengthen career flexibility.","zh":"這個片語顯示一個增強事業彈性的實際計劃。"}],"source":"2016 Q9.pdf","sourcePage":8},{"front":"review my progress with","meaning":"與……檢討我的進度","examples":[{"en":"I will review my progress with you after the first year.","zh":"第一年後，我會與你們檢討我的進度。"},{"en":"To review my progress with someone means to look back together and judge how much improvement has been made.","zh":"review my progress with someone 意思是與某人一起回顧並判斷有多少進步。"},{"en":"A student may review progress with parents after one semester.","zh":"學生可能在一個學期後與父母檢討進度。"},{"en":"Reviewing progress helps turn trust into accountability.","zh":"檢討進度幫助把信任變成問責。"},{"en":"This phrase reassures the parents that the decision will be checked, not ignored.","zh":"這個片語安撫父母，說明這個決定會被檢查，而不是被忽視。"}],"source":"2016 Q9.pdf","sourcePage":9},{"front":"after the first year","meaning":"第一年後","examples":[{"en":"I will review my progress after the first year.","zh":"第一年後，我會檢討我的進度。"},{"en":"After the first year means once the first year of study has finished.","zh":"after the first year 意思是在第一年學習完成之後。"},{"en":"A student can judge whether a course fits better after the first year.","zh":"學生在第一年後可以更好判斷課程是否適合。"},{"en":"Reviewing after the first year gives enough time for real experience.","zh":"第一年後檢討能給予足夠時間累積真實經驗。"},{"en":"This phrase sets a clear checkpoint for the family.","zh":"這個片語為家庭設定清晰檢查點。"}],"source":"2016 Q9.pdf","sourcePage":9},{"front":"bold, but not blind","meaning":"大膽但不盲目","examples":[{"en":"My choice will be bold, but not blind.","zh":"我的選擇會是大膽但不盲目。"},{"en":"Bold, but not blind means brave, but still careful and informed.","zh":"bold, but not blind 意思是勇敢，但仍然謹慎和有資訊根據。"},{"en":"Applying to an arts academy may be bold, but planning scholarships makes it less blind.","zh":"申請藝術學院可能大膽，但規劃獎學金令它不那麼盲目。"},{"en":"A bold choice becomes responsible when risks are understood and managed.","zh":"當風險被理解和管理時，大膽選擇便變得負責任。"},{"en":"This phrase balances courage with maturity.","zh":"這個片語平衡勇氣與成熟。"}],"source":"2016 Q9.pdf","sourcePage":9},{"front":"one objection","meaning":"一個反對意見","examples":[{"en":"I know there is one objection you may still have.","zh":"我知道你們可能仍有一個反對意見。"},{"en":"One objection means one remaining reason for disagreement or concern.","zh":"one objection 指一個仍然存在的反對或憂慮理由。"},{"en":"Parents may have one objection about whether acting is stable enough.","zh":"父母可能有一個反對意見，就是演戲是否足夠穩定。"},{"en":"Naming one objection helps the writer answer it directly.","zh":"說出一個反對意見幫助作者直接回應。"},{"en":"This phrase prepares the reader for a respectful rebuttal.","zh":"這個片語讓讀者準備閱讀尊重的反駁。"}],"source":"2016 Q9.pdf","sourcePage":9},{"front":"academic subject","meaning":"學術科目","examples":[{"en":"An academic subject may appear more respectable and stable.","zh":"學術科目可能看起來更體面和穩定。"},{"en":"An academic subject is a school or university subject focused mainly on study, theory, and knowledge.","zh":"academic subject 是主要著重學習、理論和知識的學校或大學科目。"},{"en":"History, economics, and biology are examples of academic subjects.","zh":"歷史、經濟和生物都是學術科目的例子。"},{"en":"Academic subjects can be valuable, but they are not the only serious choices.","zh":"學術科目可以有價值，但不是唯一認真的選擇。"},{"en":"This phrase contrasts traditional study with professional arts training.","zh":"這個片語把傳統學習與專業藝術訓練作對比。"}],"source":"2016 Q9.pdf","sourcePage":9},{"front":"another institution","meaning":"另一所院校","examples":[{"en":"You may prefer an academic subject at another institution.","zh":"你們可能較喜歡我在另一所院校修讀學術科目。"},{"en":"Another institution means a different school, college, or university.","zh":"another institution 指另一間學校、學院或大學。"},{"en":"Parents may prefer another institution because they know its reputation better.","zh":"父母可能較喜歡另一所院校，因為他們較熟悉它的名聲。"},{"en":"A student should compare institutions by fit, training, and future goals.","zh":"學生應按合適程度、訓練和未來目標比較院校。"},{"en":"This phrase shows that the disagreement is about both subject and school.","zh":"這個片語顯示分歧同時關乎科目和學校。"}],"source":"2016 Q9.pdf","sourcePage":9},{"front":"appear more respectable and stable","meaning":"看起來更體面和穩定","examples":[{"en":"An academic subject may appear more respectable and stable.","zh":"學術科目可能看起來更體面和穩定。"},{"en":"Appear more respectable and stable means seem more socially accepted and secure.","zh":"appear more respectable and stable 意思是看起來更受社會接受和更有保障。"},{"en":"Some careers appear stable because they follow a familiar path.","zh":"有些事業因沿著熟悉道路發展而看起來穩定。"},{"en":"However, a path that appears stable may not suit every student.","zh":"然而，看起來穩定的道路未必適合每位學生。"},{"en":"This phrase shows the difference between public image and personal fit.","zh":"這個片語顯示公眾形象與個人適合程度之間的分別。"}],"source":"2016 Q9.pdf","sourcePage":9},{"front":"in the eyes of","meaning":"在……眼中","examples":[{"en":"An academic subject may look more respectable in the eyes of relatives.","zh":"在親戚眼中，學術科目可能看起來更體面。"},{"en":"In the eyes of means from the viewpoint of a particular person or group.","zh":"in the eyes of 意思是從某人或某群體的角度來看。"},{"en":"In the eyes of parents, a stable career may feel safer.","zh":"在父母眼中，穩定事業可能感覺更安全。"},{"en":"In the eyes of the writer, HKAPA may be the more suitable choice.","zh":"在作者眼中，香港演藝學院可能是更合適的選擇。"},{"en":"This phrase helps show that different people may judge the same choice differently.","zh":"這個片語幫助顯示不同人可能對同一選擇有不同判斷。"}],"source":"2016 Q9.pdf","sourcePage":9},{"front":"relatives, employers and society","meaning":"親戚、僱主和社會","examples":[{"en":"Relatives, employers and society may value academic subjects more.","zh":"親戚、僱主和社會可能更重視學術科目。"},{"en":"Relatives, employers and society refers to family members, people who hire workers, and the wider community.","zh":"relatives, employers and society 指家庭成員、聘請員工的人和更廣泛社群。"},{"en":"These groups may influence how parents judge a student’s study choice.","zh":"這些群體可能影響父母如何判斷學生的升學選擇。"},{"en":"Social approval matters, but it should not completely decide a person’s future.","zh":"社會認可重要，但不應完全決定一個人的未來。"},{"en":"This phrase names the outside voices that may affect family pressure.","zh":"這個片語點出可能造成家庭壓力的外界聲音。"}],"source":"2016 Q9.pdf","sourcePage":9},{"front":"I hear you","meaning":"我明白你們的想法","examples":[{"en":"I hear you, and I understand your concern.","zh":"我明白你們的想法，也理解你們的擔憂。"},{"en":"I hear you means I understand what you are saying and take it seriously.","zh":"I hear you 意思是我明白你們所說的話，並且認真看待。"},{"en":"A child may say “I hear you” to show parents their worries are not ignored.","zh":"孩子可能說 “I hear you”，以表示沒有忽視父母的憂慮。"},{"en":"This phrase can calm disagreement because it recognises the other person’s feelings.","zh":"這個片語可以緩和分歧，因為它承認對方感受。"},{"en":"It is warmer than simply saying “I understand”.","zh":"它比單純說「我明白」更溫暖。"}],"source":"2016 Q9.pdf","sourcePage":9},{"front":"work so hard to","meaning":"非常努力去……","examples":[{"en":"You have worked so hard to give me options.","zh":"你們非常努力去給我選擇。"},{"en":"To work so hard to do something means to make great effort for a purpose.","zh":"work so hard to 意思是為某個目的付出巨大努力。"},{"en":"Parents work so hard to give their children education and choices.","zh":"父母非常努力去給孩子教育和選擇。"},{"en":"Recognising this effort helps the email sound grateful, not selfish.","zh":"承認這份努力令電郵聽起來感激，而不是自私。"},{"en":"This phrase shows respect for the parents’ sacrifice.","zh":"這個片語顯示對父母付出的尊重。"}],"source":"2016 Q9.pdf","sourcePage":10},{"front":"give me options","meaning":"給我選擇","examples":[{"en":"You have worked hard to give me options.","zh":"你們很努力給我選擇。"},{"en":"To give me options means to create choices and opportunities for me.","zh":"give me options 意思是為我創造選擇和機會。"},{"en":"Parents give children options by supporting their education and personal growth.","zh":"父母透過支持孩子教育和個人成長來給他們選擇。"},{"en":"Having options allows a student to choose a path thoughtfully.","zh":"擁有選擇讓學生可以深思熟慮地選路。"},{"en":"This phrase shows that the writer sees parental support as a gift.","zh":"這個片語顯示作者把父母的支持視為一份禮物。"}],"source":"2016 Q9.pdf","sourcePage":10},{"front":"treat that lightly","meaning":"輕視這一點","examples":[{"en":"I would never treat your effort lightly.","zh":"我絕不會輕視你們的努力。"},{"en":"To treat that lightly means to fail to value something serious or important enough.","zh":"treat that lightly 意思是沒有足夠重視嚴肅或重要的事情。"},{"en":"A student should not treat parents’ sacrifices lightly.","zh":"學生不應輕視父母的犧牲。"},{"en":"The writer says this to show gratitude and responsibility.","zh":"作者這樣說，是為了顯示感激和責任感。"},{"en":"This phrase reassures the parents that their effort is respected.","zh":"這個片語安撫父母，說明他們的努力受到尊重。"}],"source":"2016 Q9.pdf","sourcePage":10},{"front":"respectability","meaning":"體面；受尊重","examples":[{"en":"Respectability should not be confused with suitability.","zh":"體面不應與合適程度混為一談。"},{"en":"Respectability means being socially approved, admired, or seen as proper.","zh":"respectability 指受到社會認可、欣賞或被視為正當。"},{"en":"A course may have respectability because many people recognise its name.","zh":"某課程可能因許多人認識其名稱而有體面。"},{"en":"Respectability is valuable, but it does not always mean the course fits the student.","zh":"體面有價值，但不一定代表課程適合學生。"},{"en":"This word helps separate public approval from personal direction.","zh":"這個字幫助區分公眾認可和個人方向。"}],"source":"2016 Q9.pdf","sourcePage":10},{"front":"be confused with","meaning":"與……混為一談","examples":[{"en":"Respectability should not be confused with suitability.","zh":"體面不應與合適程度混為一談。"},{"en":"Be confused with means be wrongly treated as the same thing as something else.","zh":"be confused with 意思是錯誤地把某物當成與另一物相同。"},{"en":"Popularity should not be confused with quality.","zh":"受歡迎程度不應與質素混為一談。"},{"en":"A respectable subject should not be confused with the most suitable subject.","zh":"受尊重的科目不應與最適合的科目混為一談。"},{"en":"This phrase helps the writer draw a careful distinction.","zh":"這個片語幫助作者作出仔細區分。"}],"source":"2016 Q9.pdf","sourcePage":10},{"front":"suitability","meaning":"合適程度","examples":[{"en":"Respectability is not the same as suitability.","zh":"體面不等於合適程度。"},{"en":"Suitability means how well something fits a person, purpose, or situation.","zh":"suitability 指某事與一個人、目的或情況有多配合。"},{"en":"A subject may be respectable but have low suitability for a student’s strengths.","zh":"一個科目可能受尊重，但對學生強項而言合適程度低。"},{"en":"HKAPA may have strong suitability for someone who wants serious acting training.","zh":"對想接受認真演藝訓練的人來說，香港演藝學院可能有高合適程度。"},{"en":"This word helps focus on fit rather than reputation alone.","zh":"這個字幫助聚焦於配合，而不只是名聲。"}],"source":"2016 Q9.pdf","sourcePage":10},{"front":"mainly to satisfy other people","meaning":"主要為了滿足別人","examples":[{"en":"I should not study a subject mainly to satisfy other people.","zh":"我不應主要為了滿足別人而修讀一個科目。"},{"en":"Mainly to satisfy other people means mostly to please others rather than follow one’s own real direction.","zh":"mainly to satisfy other people 意思是主要為了取悅別人，而不是跟隨自己的真正方向。"},{"en":"A student may feel unhappy if she chooses a course mainly to satisfy relatives.","zh":"如果學生主要為了滿足親戚而選科，可能會不快樂。"},{"en":"Respecting others is important, but personal suitability also matters.","zh":"尊重他人很重要，但個人合適程度也重要。"},{"en":"This phrase warns against living only for outside approval.","zh":"這個片語提醒人不要只為外界認可而生活。"}],"source":"2016 Q9.pdf","sourcePage":10},{"front":"keep me comfortable for a while","meaning":"令我暫時安心","examples":[{"en":"A respectable subject may keep me comfortable for a while.","zh":"一個受尊重的科目可能令我暫時安心。"},{"en":"To keep me comfortable for a while means to make me feel safe temporarily.","zh":"keep me comfortable for a while 意思是令我暫時感到安全。"},{"en":"Choosing a familiar path may keep a family comfortable for a while.","zh":"選擇熟悉道路可能令家庭暫時安心。"},{"en":"However, temporary comfort may not solve long-term uncertainty.","zh":"然而，暫時安心未必能解決長遠不確定。"},{"en":"This phrase contrasts short-term relief with deeper fulfilment.","zh":"這個片語把短期安慰與更深層滿足作對比。"}],"source":"2016 Q9.pdf","sourcePage":10},{"front":"leave me wondering","meaning":"令我一直疑惑","examples":[{"en":"The wrong choice may leave me wondering for years.","zh":"錯誤選擇可能令我多年來一直疑惑。"},{"en":"To leave me wondering means to make me keep questioning what might have happened.","zh":"leave me wondering 意思是令我一直思考如果當初不同選擇會怎樣。"},{"en":"A student may be left wondering if she never tries the path she truly wants.","zh":"如果學生從未嘗試真正想走的道路，可能會一直疑惑。"},{"en":"Regret can last if people choose only to avoid criticism.","zh":"如果人們只為避免批評而選擇，後悔可能持續很久。"},{"en":"This phrase expresses the emotional cost of not trying.","zh":"這個片語表達不嘗試所帶來的情感代價。"}],"source":"2016 Q9.pdf","sourcePage":10},{"front":"for years","meaning":"多年來","examples":[{"en":"I might wonder for years what would have happened if I had tried.","zh":"我可能多年來一直想，如果我曾嘗試，會發生甚麼事。"},{"en":"For years means for a long period lasting several years.","zh":"for years 意思是持續好幾年的長時間。"},{"en":"A person may regret a missed opportunity for years.","zh":"一個人可能為錯過機會而多年來感到後悔。"},{"en":"The writer fears that not applying to HKAPA may create long-term regret.","zh":"作者擔心不申請香港演藝學院可能造成長期遺憾。"},{"en":"This phrase shows that some decisions can affect feelings far into the future.","zh":"這個片語顯示有些決定會長遠影響感受。"}],"source":"2016 Q9.pdf","sourcePage":10},{"front":"what would have happened if","meaning":"如果……會發生甚麼","examples":[{"en":"I may wonder what would have happened if I had tried.","zh":"我可能會想，如果我曾嘗試，會發生甚麼事。"},{"en":"What would have happened if asks about an imagined result of a choice not taken.","zh":"what would have happened if 是詢問未曾作出的選擇可能帶來的想像結果。"},{"en":"A student may wonder what would have happened if she had applied for the scholarship.","zh":"學生可能會想，如果她曾申請獎學金，會發生甚麼事。"},{"en":"This phrase often expresses regret, curiosity, or unfinished possibility.","zh":"這個片語常表達後悔、好奇或未完成的可能性。"},{"en":"It shows why the writer does not want fear to decide her future.","zh":"它顯示作者不想讓恐懼決定未來。"}],"source":"2016 Q9.pdf","sourcePage":11},{"front":"brave enough to try","meaning":"有足夠勇氣嘗試","examples":[{"en":"I may wonder whether I was brave enough to try.","zh":"我可能會想自己是否有足夠勇氣嘗試。"},{"en":"Brave enough to try means having enough courage to attempt something difficult or uncertain.","zh":"brave enough to try 意思是有足夠勇氣嘗試困難或不確定的事情。"},{"en":"A student is brave enough to try when she applies despite fearing rejection.","zh":"學生即使害怕被拒仍申請，就是有足夠勇氣嘗試。"},{"en":"Trying does not guarantee success, but it prevents regret from never attempting.","zh":"嘗試不保證成功，但可避免因從未嘗試而後悔。"},{"en":"This phrase connects courage with personal responsibility.","zh":"這個片語把勇氣與個人責任連繫起來。"}],"source":"2016 Q9.pdf","sourcePage":11},{"front":"just because…does not mean…","meaning":"只因……並不代表……","examples":[{"en":"Just because the acting path is difficult does not mean it is irresponsible.","zh":"只因演員道路困難，並不代表它不負責任。"},{"en":"This structure shows that one fact does not automatically prove another idea.","zh":"這個句式顯示一個事實不會自動證明另一個想法。"},{"en":"Just because a course is competitive does not mean it is impossible.","zh":"只因課程競爭激烈，並不代表它不可能成功。"},{"en":"Just because parents worry does not mean the student has no plan.","zh":"只因父母擔心，並不代表學生沒有計劃。"},{"en":"This phrase is useful for correcting an unfair assumption.","zh":"這個片語適合用來糾正不公平假設。"}],"source":"2016 Q9.pdf","sourcePage":11},{"front":"the acting path","meaning":"演員道路","examples":[{"en":"The acting path is difficult but not irresponsible.","zh":"演員道路困難，但並非不負責任。"},{"en":"The acting path means the route towards becoming an actor or working in performance.","zh":"the acting path 指通往成為演員或從事表演工作的道路。"},{"en":"The acting path may include training, auditions, rejection, and long practice.","zh":"演員道路可能包括訓練、試鏡、被拒絕和長時間練習。"},{"en":"A difficult acting path can still be responsible if the student prepares well.","zh":"如果學生好好準備，困難的演員道路仍可以是負責任的。"},{"en":"This phrase treats acting as a journey, not a simple wish.","zh":"這個片語把演戲視為一段旅程，而不是簡單願望。"}],"source":"2016 Q9.pdf","sourcePage":11},{"front":"irresponsible","meaning":"不負責任","examples":[{"en":"A difficult career path is not necessarily irresponsible.","zh":"困難的事業道路不一定是不負責任。"},{"en":"Irresponsible means careless, immature, or unwilling to think about consequences.","zh":"irresponsible 意思是草率、不成熟或不願思考後果。"},{"en":"Choosing art is not irresponsible if the student has training plans and backup skills.","zh":"如果學生有訓練計劃和後備技能，選擇藝術並非不負責任。"},{"en":"Spending money without planning may be irresponsible.","zh":"沒有計劃便花錢可能是不負責任。"},{"en":"This word is important because the writer wants to prove she is acting maturely.","zh":"這個字很重要，因為作者想證明自己行事成熟。"}],"source":"2016 Q9.pdf","sourcePage":11},{"front":"if anything","meaning":"反而；如果說有甚麼","examples":[{"en":"If anything, knowing the path is difficult makes me prepare harder.","zh":"反而，知道這條路困難令我更加努力準備。"},{"en":"If anything means the truth is closer to the opposite of what was suggested.","zh":"if anything 意思是真相更接近剛才說法的相反方向。"},{"en":"If anything, failure made her practise more, not less.","zh":"如果說有甚麼，失敗令她練習更多，而不是更少。"},{"en":"The writer says difficulty does not make her careless; if anything, it makes her more serious.","zh":"作者說困難不會令她草率；反而，困難令她更認真。"},{"en":"This phrase is useful when turning criticism into support for your argument.","zh":"這個片語適合用來把批評轉化為支持自己論點的理由。"}],"source":"2016 Q9.pdf","sourcePage":11},{"front":"more determined to","meaning":"更加下定決心去……","examples":[{"en":"The difficulty makes me more determined to prepare well.","zh":"困難令我更加下定決心好好準備。"},{"en":"More determined to means having stronger will to do something.","zh":"more determined to 意思是有更強意志去做某事。"},{"en":"A rejected performer may become more determined to train harder.","zh":"被拒絕的表演者可能更加下定決心努力訓練。"},{"en":"Difficulty can make a serious student more determined, not less committed.","zh":"困難可以令認真的學生更下定決心，而不是更不投入。"},{"en":"This phrase shows that challenge strengthens the writer’s decision.","zh":"這個片語顯示挑戰加強了作者的決定。"}],"source":"2016 Q9.pdf","sourcePage":11},{"front":"prepare well","meaning":"好好準備","examples":[{"en":"I am determined to prepare well.","zh":"我下定決心好好準備。"},{"en":"To prepare well means to plan, practise, and get ready carefully.","zh":"prepare well 意思是仔細計劃、練習和準備。"},{"en":"A student prepares well for an audition by choosing pieces and rehearsing regularly.","zh":"學生透過選擇試鏡片段和定期排練來好好準備試鏡。"},{"en":"Preparing well reduces risk because it turns hope into action.","zh":"好好準備可以減少風險，因為它把希望變成行動。"},{"en":"This phrase shows responsibility before taking a difficult path.","zh":"這個片語顯示在走困難道路前的責任感。"}],"source":"2016 Q9.pdf","sourcePage":11},{"front":"lower your expectations of me","meaning":"降低你們對我的期望","examples":[{"en":"I am not asking you to lower your expectations of me.","zh":"我不是要求你們降低對我的期望。"},{"en":"To lower your expectations of me means to expect less from me than before.","zh":"lower your expectations of me 意思是比以前對我有較低期望。"},{"en":"A child may reassure parents that choosing art does not mean accepting lower standards.","zh":"孩子可能安撫父母，說選擇藝術不代表接受較低標準。"},{"en":"The writer wants to meet high expectations in a field that suits her.","zh":"作者希望在適合自己的領域達到高期望。"},{"en":"This phrase shows respect for the parents’ hopes.","zh":"這個片語顯示對父母期望的尊重。"}],"source":"2016 Q9.pdf","sourcePage":11},{"front":"meet them","meaning":"達到它們；符合期望","examples":[{"en":"I am asking you to let me meet your expectations in a suitable field.","zh":"我是請求你們讓我在合適的領域達到你們的期望。"},{"en":"To meet them means to satisfy or achieve expectations, standards, or requirements.","zh":"meet them 意思是滿足或達到期望、標準或要求。"},{"en":"A student can meet parents’ expectations by working hard and acting responsibly.","zh":"學生可透過努力和負責任行事來符合父母期望。"},{"en":"The writer wants to meet expectations through HKAPA, not reject them.","zh":"作者希望透過香港演藝學院達到期望，而不是拒絕它們。"},{"en":"This phrase shows that the writer still values family standards.","zh":"這個片語顯示作者仍重視家庭標準。"}],"source":"2016 Q9.pdf","sourcePage":11},{"front":"in a field where","meaning":"在一個……的領域","examples":[{"en":"I want to meet your expectations in a field where I can stand tall.","zh":"我想在一個可以堂堂正正站穩的領域達到你們的期望。"},{"en":"In a field where means in an area or profession in which a certain thing is possible.","zh":"in a field where 意思是在一個能做到某事的範疇或職業中。"},{"en":"A student should study in a field where her strengths can grow.","zh":"學生應在一個能讓自己強項成長的領域學習。"},{"en":"The writer wants a field where effort feels meaningful.","zh":"作者想要一個努力有意義的領域。"},{"en":"This phrase connects career choice with personal fit and confidence.","zh":"這個片語把事業選擇與個人契合和信心連接起來。"}],"source":"2016 Q9.pdf","sourcePage":12},{"front":"stand tall","meaning":"堂堂正正地站穩","examples":[{"en":"I want to work in a field where I can stand tall.","zh":"我想在一個可以堂堂正正站穩的領域工作。"},{"en":"To stand tall means to feel proud, confident, and dignified.","zh":"stand tall 意思是感到自豪、自信和有尊嚴。"},{"en":"A person stands tall when they work hard in a field that truly suits them.","zh":"當一個人在真正適合自己的領域努力時，便能堂堂正正地站穩。"},{"en":"The writer wants to succeed without pretending to be someone else.","zh":"作者想成功，而不是假裝成另一個人。"},{"en":"This phrase suggests self-respect and honest confidence.","zh":"這個片語表示自尊和誠實的信心。"}],"source":"2016 Q9.pdf","sourcePage":12},{"front":"support my application","meaning":"支持我的申請","examples":[{"en":"Please support my application to HKAPA before the deadline.","zh":"請在截止日期前支持我申請香港演藝學院。"},{"en":"To support my application means to encourage and approve my request to enter a school or programme.","zh":"support my application 意思是鼓勵並認可我入讀某學校或課程的申請。"},{"en":"Parents can support an application by giving advice, documents, or emotional support.","zh":"父母可透過給予建議、文件或情感支持來支持申請。"},{"en":"Support before the deadline matters because the application must be submitted on time.","zh":"截止日期前的支持很重要，因為申請必須準時提交。"},{"en":"This phrase is the writer’s central request.","zh":"這個片語是作者的核心請求。"}],"source":"2016 Q9.pdf","sourcePage":12},{"front":"before the deadline","meaning":"在截止日期前","examples":[{"en":"Please support my application before the deadline.","zh":"請在截止日期前支持我的申請。"},{"en":"Before the deadline means earlier than the final time or date allowed.","zh":"before the deadline 意思是在允許的最後時間或日期之前。"},{"en":"Students should submit forms before the deadline to avoid last-minute problems.","zh":"學生應在截止日期前提交表格，以避免最後一刻出問題。"},{"en":"The writer needs support before the deadline because the application cannot wait forever.","zh":"作者需要在截止日期前得到支持，因為申請不能一直等待。"},{"en":"This phrase adds urgency to the request.","zh":"這個片語為請求加入迫切感。"}],"source":"2016 Q9.pdf","sourcePage":12},{"front":"promise that","meaning":"承諾","examples":[{"en":"I promise that I will not take your support for granted.","zh":"我承諾不會把你們的支持視為理所當然。"},{"en":"Promise that means say firmly that you will do something or behave in a certain way.","zh":"promise that 意思是堅定地說自己會做某事或以某種方式行事。"},{"en":"A student may promise that she will work hard after receiving her parents’ support.","zh":"學生得到父母支持後，可能承諾會努力學習。"},{"en":"This phrase creates responsibility because the writer makes a clear commitment.","zh":"這個片語創造責任感，因為作者作出清晰承諾。"},{"en":"It helps parents feel that their trust will be respected.","zh":"它幫助父母感到自己的信任會被尊重。"}],"source":"2016 Q9.pdf","sourcePage":12},{"front":"take your support for granted","meaning":"把你們的支持視為理所當然","examples":[{"en":"I will not take your support for granted.","zh":"我不會把你們的支持視為理所當然。"},{"en":"To take your support for granted means to receive help without appreciating it properly.","zh":"take your support for granted 意思是接受幫助卻沒有好好珍惜。"},{"en":"A child takes support for granted if she expects help but never shows gratitude.","zh":"如果孩子期望別人幫助卻從不感謝，就是把支持視為理所當然。"},{"en":"The writer promises to value her parents’ trust and effort.","zh":"作者承諾珍惜父母的信任和努力。"},{"en":"This phrase shows humility and appreciation.","zh":"這個片語顯示謙卑和感激。"}],"source":"2016 Q9.pdf","sourcePage":12},{"front":"application materials","meaning":"申請材料","examples":[{"en":"I will show you my application materials.","zh":"我會給你們看我的申請材料。"},{"en":"Application materials are the documents and work needed for an application.","zh":"application materials 是申請所需的文件和作品。"},{"en":"Application materials may include forms, personal statements, references, and portfolios.","zh":"申請材料可能包括表格、個人陳述、推薦信和作品集。"},{"en":"Showing application materials helps parents see that the plan is serious.","zh":"展示申請材料幫助父母看見計劃是認真的。"},{"en":"This phrase turns a dream into visible preparation.","zh":"這個片語把夢想變成可見的準備。"}],"source":"2016 Q9.pdf","sourcePage":12},{"front":"practise seriously for","meaning":"為……認真練習","examples":[{"en":"I will practise seriously for the audition.","zh":"我會為試鏡認真練習。"},{"en":"To practise seriously for something means to prepare with discipline and focus.","zh":"practise seriously for 某事，意思是有紀律而專注地準備。"},{"en":"A singer practises seriously for an audition by training every day.","zh":"歌手透過每日訓練來為試鏡認真練習。"},{"en":"Serious practice shows respect for the opportunity and the people supporting it.","zh":"認真練習顯示對機會和支持者的尊重。"},{"en":"This phrase reassures parents that the writer will not be careless.","zh":"這個片語安撫父母，說明作者不會草率。"}],"source":"2016 Q9.pdf","sourcePage":12},{"front":"audition","meaning":"試鏡","examples":[{"en":"I will practise seriously for the audition.","zh":"我會為試鏡認真練習。"},{"en":"An audition is a performance test used to decide whether someone is suitable for a role or programme.","zh":"audition 是用來判斷某人是否適合某角色或課程的表演測試。"},{"en":"A student may prepare a monologue for a drama school audition.","zh":"學生可能為戲劇學校試鏡準備獨白。"},{"en":"Auditions can be stressful because performers must show skill in a short time.","zh":"試鏡可以令人緊張，因為表演者必須在短時間內展示能力。"},{"en":"Preparing for an audition requires confidence, discipline, and repeated practice.","zh":"準備試鏡需要信心、紀律和反覆練習。"}],"source":"2016 Q9.pdf","sourcePage":12},{"front":"keep you updated","meaning":"讓你們知道最新情況","examples":[{"en":"I will keep you updated while you are away.","zh":"在你們不在香港期間，我會讓你們知道最新情況。"},{"en":"To keep you updated means to tell you the latest news or progress.","zh":"keep you updated 意思是告訴你們最新消息或進度。"},{"en":"A student may keep parents updated about application results and interview dates.","zh":"學生可能讓父母知道申請結果和面試日期的最新情況。"},{"en":"Keeping parents updated reduces worry because they know what is happening.","zh":"讓父母知道最新情況可減少擔心，因為他們知道正在發生甚麼。"},{"en":"This phrase shows openness and responsibility.","zh":"這個片語顯示坦誠和責任感。"}],"source":"2016 Q9.pdf","sourcePage":12},{"front":"while you are away","meaning":"在你們不在香港期間","examples":[{"en":"I will keep you updated while you are away.","zh":"在你們不在香港期間，我會讓你們知道最新情況。"},{"en":"While you are away means during the time when you are not at home or not nearby.","zh":"while you are away 意思是在你們不在家或不在附近的期間。"},{"en":"A child may message parents while they are away on a trip.","zh":"父母外遊期間，孩子可能會發訊息給他們。"},{"en":"Keeping contact while parents are away helps them feel included in important decisions.","zh":"在父母不在期間保持聯絡，幫助他們感到自己仍參與重要決定。"},{"en":"This phrase explains when the updates will happen.","zh":"這個片語解釋最新情況會在甚麼時候提供。"}],"source":"2016 Q9.pdf","sourcePage":13},{"front":"mean a lot to me","meaning":"對我意義重大","examples":[{"en":"Your support would mean a lot to me.","zh":"你們的支持對我意義重大。"},{"en":"Mean a lot to me means be very important and emotionally valuable to me.","zh":"mean a lot to me 意思是對我非常重要，並有很大情感價值。"},{"en":"A parent’s blessing can mean a lot to a child making a difficult choice.","zh":"父母的祝福對作出困難選擇的孩子可以意義重大。"},{"en":"Support may not remove all risk, but it can give courage.","zh":"支持未必能移除所有風險，但可以給予勇氣。"},{"en":"This phrase expresses deep gratitude without sounding demanding.","zh":"這個片語表達深切感激，而不顯得強求。"}],"source":"2016 Q9.pdf","sourcePage":13},{"front":"press submit","meaning":"按下「提交」","examples":[{"en":"I hope to feel your blessing when I press submit.","zh":"我希望在按下「提交」時感受到你們的祝福。"},{"en":"To press submit means to click the button that sends an online form or application.","zh":"press submit 意思是按下發送網上表格或申請的按鈕。"},{"en":"A student may feel nervous when pressing submit for a university application.","zh":"學生在為大學申請按下「提交」時可能會緊張。"},{"en":"The phrase turns the application into a concrete moment.","zh":"這個片語把申請變成一個具體時刻。"},{"en":"It shows that the writer wants emotional support at the final step.","zh":"它顯示作者希望在最後一步得到情感支持。"}],"source":"2016 Q9.pdf","sourcePage":13},{"front":"not walking away from…but walking forward with…","meaning":"不是離開……而是帶著……向前走","examples":[{"en":"I am not walking away from my family, but walking forward with your blessing.","zh":"我不是離開家人，而是帶著你們的祝福向前走。"},{"en":"This structure contrasts leaving something behind with moving ahead together with support.","zh":"這個句式把離開某事與帶著支持一起前進作對比。"},{"en":"Choosing a personal dream is not walking away from family if respect remains.","zh":"如果仍然保持尊重，選擇個人夢想並不是離開家庭。"},{"en":"Walking forward with someone’s blessing means moving ahead while carrying their support.","zh":"帶著某人的祝福向前走，意思是一邊前進，一邊帶著他們的支持。"},{"en":"This phrase is emotional because it shows independence and family connection at the same time.","zh":"這個片語有感情，因為它同時顯示獨立和家庭連繫。"}],"source":"2016 Q9.pdf","sourcePage":13},{"front":"walking away from my family","meaning":"離開家人；背棄家庭","examples":[{"en":"Applying to HKAPA does not mean walking away from my family.","zh":"申請香港演藝學院並不代表離開家人。"},{"en":"Walking away from my family means leaving family values, support, or connection behind.","zh":"walking away from my family 意思是拋下家庭價值、支持或連繫。"},{"en":"A student can choose a different path without walking away from family.","zh":"學生可以選擇不同道路，而不代表背棄家庭。"},{"en":"The writer wants her parents to know that HKAPA is not rejection of them.","zh":"作者希望父母知道香港演藝學院不是對他們的拒絕。"},{"en":"This phrase reassures the family that love and respect remain.","zh":"這個片語安撫家人，說明愛和尊重仍然存在。"}],"source":"2016 Q9.pdf","sourcePage":13},{"front":"walking forward with your blessing","meaning":"帶著你們的祝福向前走","examples":[{"en":"I want to walk forward with your blessing.","zh":"我想帶著你們的祝福向前走。"},{"en":"Walking forward with your blessing means moving into the future with your support and approval.","zh":"walking forward with your blessing 意思是帶著你們的支持和認可走向未來。"},{"en":"A child feels stronger when she starts a new path with her parents’ blessing.","zh":"孩子帶著父母祝福開始新道路時，會感到更有力量。"},{"en":"The phrase shows that the writer wants independence without losing family support.","zh":"這個片語顯示作者想要獨立，但不想失去家庭支持。"},{"en":"It turns approval into something emotionally meaningful.","zh":"它把認可變成有情感意義的東西。"}],"source":"2016 Q9.pdf","sourcePage":13},{"front":"count on me","meaning":"相信我；依靠我","examples":[{"en":"I hope you can count on me.","zh":"我希望你們可以相信我。"},{"en":"To count on me means to trust me to act responsibly and keep my promises.","zh":"count on me 意思是信任我會負責任地行事並履行承諾。"},{"en":"Parents can count on a child who communicates honestly and works hard.","zh":"如果孩子誠實溝通並努力，父母便可以相信他。"},{"en":"The writer asks her parents to believe she will take the choice seriously.","zh":"作者請求父母相信她會認真對待這個選擇。"},{"en":"This phrase is simple but carries strong responsibility.","zh":"這個片語簡單，但帶有很強責任感。"}],"source":"2016 Q9.pdf","sourcePage":13},{"front":"turn this choice into","meaning":"把這個選擇變成","examples":[{"en":"I hope to turn this choice into something worthy of your trust.","zh":"我希望把這個選擇變成對得起你們信任的事情。"},{"en":"To turn this choice into something means to make the decision become a particular result through action.","zh":"turn this choice into something 意思是透過行動令這個決定變成某種結果。"},{"en":"A student can turn a difficult choice into success through planning and discipline.","zh":"學生可透過計劃和紀律把困難選擇變成成功。"},{"en":"The writer wants to turn HKAPA into proof that her parents’ trust was not misplaced.","zh":"作者想把香港演藝學院這個選擇變成證明父母沒有信錯她的事情。"},{"en":"This phrase shows that the decision still requires effort after it is made.","zh":"這個片語顯示決定作出後仍需要努力。"}],"source":"2016 Q9.pdf","sourcePage":13},{"front":"worthy of your trust","meaning":"對得起你們信任","examples":[{"en":"I want to make this choice worthy of your trust.","zh":"我想令這個選擇對得起你們的信任。"},{"en":"Worthy of your trust means deserving the trust you have given me.","zh":"worthy of your trust 意思是值得你們給予我的信任。"},{"en":"A student becomes worthy of trust by keeping promises and working consistently.","zh":"學生透過守承諾和持續努力，便能對得起信任。"},{"en":"The writer wants her actions to prove that her parents’ support was right.","zh":"作者希望用行動證明父母的支持是正確的。"},{"en":"This phrase expresses gratitude, responsibility, and love.","zh":"這個片語表達感激、責任和愛。"}],"source":"2016 Q9.pdf","sourcePage":13},{"front":"Love","meaning":"愛你的","examples":[{"en":"The email ends with Love.","zh":"這封電郵以「愛你的」結束。"},{"en":"Love is a warm closing used when writing to close family members or loved ones.","zh":"Love 是寫給親密家人或所愛的人時使用的溫暖結尾。"},{"en":"A child may end an email to parents with “Love” to show affection.","zh":"孩子可能以 “Love” 結束寫給父母的電郵，以表達愛意。"},{"en":"This closing fits the email because the message is personal and emotional.","zh":"這個結尾適合這封電郵，因為訊息私人且帶感情。"},{"en":"It leaves the parents with a feeling of closeness after a serious request.","zh":"它在嚴肅請求後，讓父母感到親近。"}],"source":"2016 Q9.pdf","sourcePage":13}]};
window.EDMUND_FLASHCARD_SEED = window.EDMUND_FLASHCARD_SEED || {};
